/**
 * The two WalletDbHandle implementations.
 *
 * Everything that differs between the IndexedDB emulation and the native
 * sqlite database is confined to these two classes.
 */

import {
  CancellationToken,
  getErrorDetailFromException,
  Logger,
  NotificationType,
  WalletNotification,
} from "@gnu-taler/taler-util";
import {
  AccessStats,
  BridgeIDBFactory,
  IDBDatabase,
} from "@gnu-taler/idb-bridge";

import {
  abortTalerDatabaseReplacement,
  beginTalerDatabaseReplacement,
  clearDatabase,
  openTalerDatabase,
  publishTalerDatabaseReplacement,
  retireTalerDatabaseGeneration,
} from "./database.js";
import { exportDb, importDb } from "./dump.js";
import {
  applyFixups,
  WALLET_DB_MAINTENANCE_TOTAL_STEPS,
  WALLET_DB_SCHEMA_UPGRADE_STEP,
} from "./fixups.js";
import { WalletIndexedDbStoresV1 } from "./schema.js";
import {
  WalletDbAccessStats,
  WalletDbHandle,
  WalletDbImportFinalizer,
  WalletDbMigrationOptions,
} from "../handle.js";
import { IdbWalletTransaction } from "./transaction.js";
import { WalletDbTransaction } from "../transaction.js";
import { DbAccess, DbAccessImpl } from "../query.js";

const logger = new Logger("db/indexeddb/handle.ts");

function notifySafely(
  sink: (notification: WalletNotification) => void,
  notification: WalletNotification,
): void {
  try {
    sink(notification);
  } catch (e) {
    logger.warn(
      `ignoring exception from wallet notification sink: ${
        e instanceof Error ? e.message : String(e)
      }`,
    );
  }
}

/**
 * WalletDbHandle over the IndexedDB emulation.
 *
 * Opens lazily: the wallet is constructed before it is initialised, and
 * opening on construction would create a database file for a wallet that is
 * never used.
 */
export class IdbWalletDbHandle implements WalletDbHandle {
  readonly name = "indexeddb";

  private idbHandle: IDBDatabase | undefined;
  private dbAccess: DbAccess<typeof WalletIndexedDbStoresV1> | undefined;
  private opening:
    | Promise<{ fixupsApplied: number; schemaUpgraded: boolean }>
    | undefined;

  private notify: (n: WalletNotification) => void = () => {};

  /**
   * Filesystem-backed capabilities, supplied by the host when it has them.
   * A browser extension leaves them unset.
   */
  exportToFile?: (
    directory: string,
    stem: string,
    forceFormat?: string,
  ) => Promise<{ path: string }>;
  readBackupJson?: (path: string) => Promise<any>;
  getDiagnosticStats?: () => unknown;

  /**
   * In-place migration to the native schema, set by the host when the
   * emulation runs over a sqlite database the host can also open natively.
   * See {@link WalletDbHandle.migrateToNative}.
   */
  migrateToNative?: (
    options?: WalletDbMigrationOptions,
  ) => Promise<WalletDbHandle>;
  openNativeIfEmpty?: () => Promise<WalletDbHandle>;

  setNotificationSink(sink: (n: WalletNotification) => void): void {
    this.notify = sink;
  }

  emitNotification(notification: WalletNotification): void {
    notifySafely(this.notify, notification);
  }

  constructor(
    private idbFactory: BridgeIDBFactory,
    /**
     * Raw backend counters, when the backend was asked to track them.
     * Summed into a single figure by getAccessStats.
     */
    private rawStats?: () => AccessStats | undefined,
    private applyDbFixups: typeof applyFixups = applyFixups,
  ) {}

  /**
   * Open the database if it is not open yet.
   *
   * Returns whether fixups changed anything, which the caller needs in order
   * to decide whether wallet-level views have to be rebuilt.
   */
  async ensureOpen(): Promise<{
    fixupsApplied: number;
    schemaUpgraded: boolean;
  }> {
    if (this.dbAccess) {
      return { fixupsApplied: 0, schemaUpgraded: false };
    }
    if (this.opening) {
      return await this.opening;
    }
    const opening = this.openDatabase();
    this.opening = opening;
    try {
      return await opening;
    } finally {
      if (this.opening === opening) {
        this.opening = undefined;
      }
    }
  }

  private async openDatabase(): Promise<{
    fixupsApplied: number;
    schemaUpgraded: boolean;
  }> {
    let schemaUpgraded = false;
    let upgradeStep: string | undefined;
    let idbHandle: IDBDatabase;
    try {
      idbHandle = await openTalerDatabase(
        this.idbFactory,
        async () => {},
        (oldVersion, newVersion) => {
          schemaUpgraded = true;
          upgradeStep = `${WALLET_DB_SCHEMA_UPGRADE_STEP}-${oldVersion}-to-${newVersion}`;
          this.emitNotification({
            type: NotificationType.DatabaseMaintenanceProgress,
            operation: "indexeddb-fixup",
            phase: "fixup",
            step: upgradeStep,
            completedSteps: 0,
            totalSteps: WALLET_DB_MAINTENANCE_TOTAL_STEPS,
          });
        },
      );
    } catch (e) {
      if (upgradeStep) {
        this.emitNotification({
          type: NotificationType.DatabaseMaintenanceProgress,
          operation: "indexeddb-fixup",
          phase: "failed",
          step: upgradeStep,
          completedSteps: 0,
          totalSteps: WALLET_DB_MAINTENANCE_TOTAL_STEPS,
          error: getErrorDetailFromException(e),
        });
      }
      throw e;
    }
    const dbAccess = this.makeAccess(idbHandle);
    try {
      const fixupsApplied = await this.applyDbFixups(
        dbAccess,
        (n) => this.emitNotification(n),
        { deferCompletion: true },
      );
      this.idbHandle = idbHandle;
      this.dbAccess = dbAccess;
      return { fixupsApplied, schemaUpgraded };
    } catch (e) {
      idbHandle.close();
      throw e;
    }
  }

  private makeAccess(
    idbHandle: IDBDatabase,
    notificationSink: (n: WalletNotification) => void = (n) =>
      this.emitNotification(n),
  ): DbAccess<typeof WalletIndexedDbStoresV1> {
    return new DbAccessImpl(
      idbHandle,
      WalletIndexedDbStoresV1,
      CancellationToken.CONTINUE,
      (notifs: WalletNotification[]) => {
        for (const n of notifs) {
          notificationSink(n);
        }
      },
    );
  }

  /**
   * The raw DbAccess for the fixup log, which is an IndexedDB concern rather
   * than a generic database concern.
   *
   * Reachable only through this class, so generic code cannot pick it up by
   * accident the way it could when the wallet state exposed a factory.
   */
  async rawAccess(): Promise<DbAccess<typeof WalletIndexedDbStoresV1>> {
    await this.ensureOpen();
    if (!this.dbAccess) {
      throw Error("wallet database is not open");
    }
    return this.dbAccess;
  }

  /** The IndexedDB factory used by hosts that install the bridge shim. */
  factory(): BridgeIDBFactory {
    return this.idbFactory;
  }

  async runReadWriteTx<T>(
    f: (tx: WalletDbTransaction) => Promise<T>,
  ): Promise<T> {
    const access = await this.rawAccess();
    return await access.runAllStoresReadWriteTx({}, async (mytx) => {
      return await f(new IdbWalletTransaction(mytx));
    });
  }

  async exportDatabase(): Promise<any> {
    await this.ensureOpen();
    return await exportDb(this.idbFactory);
  }

  async importDatabase(
    dump: any,
    finalize: WalletDbImportFinalizer,
  ): Promise<void> {
    // A native-backend dump has {schemaVersion, tables}; this backend's dumps
    // have {databases}.  Importing across backends is a format conversion,
    // not a copy, and silently accepting the wrong shape would import
    // nothing while reporting success.
    if (dump != null && typeof dump === "object" && "tables" in dump) {
      throw Error(
        "this dump is from the native sqlite backend and cannot be" +
          " imported into the IndexedDB backend; convert the database" +
          " instead",
      );
    }
    await this.ensureOpen();
    if (!this.idbHandle) {
      throw Error("wallet database is not open");
    }
    const oldHandle = this.idbHandle;
    const oldName = oldHandle.name;
    const stagedNotifications: WalletNotification[] = [];
    let published = false;
    const staged = await beginTalerDatabaseReplacement(
      this.idbFactory,
      oldName,
      async () => {},
    );
    const stagedAccess = this.makeAccess(staged.handle, (n) => {
      if (published) {
        this.emitNotification(n);
      } else {
        stagedNotifications.push(n);
      }
    });
    try {
      await importDb(staged.handle, dump);
      // The imported records may predate any of the fixups, whatever the old
      // generation had applied.  Clear the imported log and repair the staged
      // generation before it can become authoritative.
      await stagedAccess.runAllStoresReadWriteTx({}, async (tx) => {
        const fixups = await tx.fixups.getAll();
        for (const fx of fixups) {
          await tx.fixups.delete(fx.fixupName);
        }
      });
      await this.applyDbFixups(
        stagedAccess,
        (n) => stagedNotifications.push(n),
        { deferCompletion: true },
      );
      await stagedAccess.runAllStoresReadWriteTx({}, async (tx) => {
        await finalize(new IdbWalletTransaction(tx));
      });
      stagedNotifications.push({
        type: NotificationType.DatabaseMaintenanceProgress,
        operation: "indexeddb-fixup",
        phase: "complete",
        completedSteps: WALLET_DB_MAINTENANCE_TOTAL_STEPS,
        totalSteps: WALLET_DB_MAINTENANCE_TOTAL_STEPS,
      });

      // This metadata transaction is the commit point.  A crash before it
      // keeps oldName authoritative; a crash afterwards opens staged.name.
      await publishTalerDatabaseReplacement(
        this.idbFactory,
        oldName,
        staged.name,
      );
      published = true;
      this.idbHandle = staged.handle;
      this.dbAccess = stagedAccess;
      oldHandle.close();
      for (const n of stagedNotifications) this.emitNotification(n);
    } catch (e) {
      if (!published) {
        staged.handle.close();
        await abortTalerDatabaseReplacement(this.idbFactory, staged.name);
      }
      throw e;
    }

    // Deletion is deliberately outside the commit semantics: failure or a
    // second client blocking it only retains an unreachable old generation.
    await retireTalerDatabaseGeneration(this.idbFactory, oldName, staged.name);
  }

  async clearDatabase(): Promise<void> {
    await this.ensureOpen();
    if (!this.idbHandle) {
      throw Error("wallet database is not open");
    }
    await clearDatabase(this.idbHandle);
  }

  getAccessStats(): WalletDbAccessStats | undefined {
    const st = this.rawStats?.();
    if (!st) {
      return undefined;
    }
    // Index reads and store reads both count: a query served entirely from an
    // index still read those records, and leaving them out would make a
    // full index scan look bounded.
    let recordsRead = 0;
    for (const k of Object.keys(st.readItemsPerIndex)) {
      recordsRead += st.readItemsPerIndex[k];
    }
    for (const k of Object.keys(st.readItemsPerStore)) {
      recordsRead += st.readItemsPerStore[k];
    }
    return { recordsRead };
  }

  async close(): Promise<void> {
    this.idbHandle?.close();
    this.idbHandle = undefined;
    this.dbAccess = undefined;
  }
}
