import { WalletNotification } from "@gnu-taler/taler-util";
import { HttpRequestLibrary } from "@gnu-taler/taler-util/http";
import type { Sqlite3Database } from "@gnu-taler/idb-bridge";

/**
 * Helpers to initiate a wallet in a host environment.
 */

/**
 */
export interface DefaultNodeWalletArgs {
  /**
   * Location of the wallet database.
   *
   * If not specified, the wallet starts out with an empty database and
   * the wallet database is stored only in memory.
   */
  persistentStoragePath?: string;

  /**
   * Handler for asynchronous notifications from the wallet.
   */
  notifyHandler?: (n: WalletNotification) => void;

  /**
   * If specified, use this as HTTP request library instead
   * of the default one.
   */
  httpLib?: HttpRequestLibrary;

  cryptoWorkerType?: "sync" | "node-worker-thread";
}

/**
 * Claim a filesystem-backed wallet database for this connection's lifetime.
 *
 * The in-memory operation gate serializes users of one Wallet instance, but it
 * cannot see another process (or another Wallet instance in this process).
 * SQLite's exclusive locking mode supplies that outer ownership boundary.  A
 * transaction is needed to acquire the lock immediately; merely setting the
 * pragma would defer the conflict until the first later database operation.
 * The connection retains the lock after COMMIT and releases it on close.
 */
export async function acquireSqliteWalletDbOwnership(
  db: Sqlite3Database,
): Promise<void> {
  let transactionStarted = false;
  try {
    await db.exec("PRAGMA locking_mode = EXCLUSIVE");
    await (await db.prepare("BEGIN EXCLUSIVE")).run({});
    transactionStarted = true;
    await (await db.prepare("COMMIT")).run({});
    transactionStarted = false;
  } catch (cause) {
    if (transactionStarted) {
      try {
        await (await db.prepare("ROLLBACK")).run({});
      } catch {
        // Preserve the acquisition error.  Closing the connection is the
        // caller's responsibility and also releases any partially held lock.
      }
    }
    throw new Error(
      "could not acquire exclusive ownership of the wallet database; " +
        "another wallet process may still be using it",
      { cause },
    );
  }
}

/**
 * Generate a random alphanumeric ID.  Does *not* use cryptographically
 * secure randomness.
 */
export function makeTempfileId(length: number): string {
  let result = "";
  const characters = "abcdefghijklmnopqrstuvwxyz0123456789";
  for (let i = 0; i < length; i++) {
    result += characters.charAt(Math.floor(Math.random() * characters.length));
  }
  return result;
}

/**
 * Get the underlying sqlite3 DB filename
 * from the storage path specified by the wallet-core client.
 */
export function getSqlite3FilenameFromStoragePath(
  p: string | undefined,
): string {
  // Allow specifying a directory as the storage path.
  // In that case, we pick the filename and use the sqlite3
  // backend.
  //
  // We still allow specifying a filename for backwards
  // compatibility and control over the exact file.
  //
  // Specifying a directory allows us to automatically
  // migrate to a new DB file in the future.
  if (!p) {
    return ":memory:";
  }
  if (p.endsWith("/")) {
    // Current sqlite3 DB filename.
    // Should rarely if ever change.
    return `${p}talerwalletdb-v30.sqlite3`;
  } else {
    return p;
  }
}
