/**
 * Conversion between wallet database backends.
 *
 * The converter copies records through the DAL: it reads every entity from
 * one {@link WalletDbHandle} and writes it into another, knowing nothing
 * about either storage layout.  Opening the IndexedDB source runs the fixup
 * log, so the converted database contains repaired records by construction --
 * the native schema has no fixup log to replay.
 *
 * Auto-generated serials (reserves, exchange details, denomination families,
 * refund items) are preserved: other records reference them, and every upsert
 * honours a supplied key.
 *
 * The caller supplies a fresh, empty destination and swaps files afterwards;
 * nothing here mutates the source.
 */

import {
  CancellationToken,
  DatabaseMaintenanceProgressNotification,
  Logger,
  NotificationType,
  sha256,
  stringToBytes,
} from "@gnu-taler/taler-util";

import {
  WalletCoin,
  WalletCoinAvailability,
  WalletPlanchet,
  WalletPurchase,
  WalletReserve,
} from "../records.js";
import { WalletDbHandle } from "../handle.js";
import { WalletDbMigrationStore, WalletDbTransaction } from "../transaction.js";

const logger = new Logger("db/migration/converter.ts");

/**
 * One entity to copy.
 *
 * `read` identifies the existing DAL enumeration used by the backend's
 * bounded migration scanner; `write` stores one record.
 * `normalize` is applied before the verification comparison, for the few
 * stores where the destination deliberately canonicalises a representation
 * (for example global-currency ids, which nothing else references).
 */
interface CopyStep {
  name: WalletDbMigrationStore;
  read: (tx: WalletDbTransaction) => Promise<unknown[]>;
  write: (tx: WalletDbTransaction, rec: unknown) => Promise<unknown>;
  normalize?: (rec: unknown) => unknown;
  validate?: (tx: WalletDbTransaction, rec: unknown) => Promise<void>;
}

function step<T>(
  name: WalletDbMigrationStore,
  read: (tx: WalletDbTransaction) => Promise<T[]>,
  write: (tx: WalletDbTransaction, rec: T) => Promise<unknown>,
  normalize?: (rec: T) => unknown,
  validate?: (tx: WalletDbTransaction, rec: T) => Promise<void>,
): CopyStep {
  return {
    name,
    read: read as CopyStep["read"],
    write: write as CopyStep["write"],
    normalize: normalize as CopyStep["normalize"],
    validate: validate as CopyStep["validate"],
  };
}

const stripId = (rec: unknown): unknown => {
  const { id, ...rest } = rec as Record<string, unknown>;
  return rest;
};

/**
 * Fields old databases still carry that no current record type has.
 *
 * The IndexedDB backend returns stored records as-is, unknown fields
 * included; the modern code ignores them and the sqlite mapper cannot store
 * them.  Conversion drops them -- that is the "as if every fixup had run"
 * shape of the data -- but only fields on this list: an unknown field NOT
 * listed here fails verification, so a genuinely lost field cannot be
 * mistaken for legacy junk without a human putting its name here.
 */
const LEGACY_FIELDS: Record<string, string[]> = {
  // Removed when exchange update retry state moved to operation_retries.
  exchanges: ["updateRetryCounter"],
  // Removed 2024-06-13 ("remove coinAllocationId, simplify coin history").
  coins: ["spendAllocation"],
  // Dropped when denomination records were restructured; nothing reads it.
  denominations: ["listIssueDate"],
  // Superseded by per-selection UIDs inside denomsSel; removed 2024-06-10.
  withdrawalGroups: ["denomSelUid"],
  // Documented in records.ts as a reserved legacy field (v1 refresh); the
  // current protocol derives a public seed on demand instead.
  refreshSessions: ["sessionSecretSeed"],
};

function stripLegacy(
  stepName: string,
): ((rec: unknown) => unknown) | undefined {
  const fields = LEGACY_FIELDS[stepName];
  if (!fields) return undefined;
  return (rec: unknown) => {
    const out = { ...(rec as Record<string, unknown>) };
    for (const f of fields) {
      delete out[f];
    }
    return out;
  };
}

/**
 * The IndexedDB schema allowed old wallet versions to persist an empty
 * `exchanges` array.  The native schema represents that field with rows in
 * `purchase_exchanges`, so both an absent field and an empty array have zero
 * rows and consequently read back as absent.  The field is optional and the
 * wallet itself does not create empty arrays, making absent the native
 * canonical form.
 */
function normalizePurchase(rec: WalletPurchase): unknown {
  if (rec.exchanges?.length !== 0) {
    return rec;
  }
  const { exchanges: _exchanges, ...rest } = rec;
  return rest;
}

/**
 * Crockford encoding is case-insensitive.  IndexedDB records from an older
 * wallet may contain this capability key in lowercase, whereas the native
 * BLOB representation always decodes it in its canonical uppercase form.
 */
function normalizeContractPriv<T extends { contractPriv: string }>(rec: T): T {
  return { ...rec, contractPriv: rec.contractPriv.toUpperCase() };
}

/**
 * Require the one-reserve-per-public-key invariant of the native schema.
 *
 * The IndexedDB fixup may remove byte-identical duplicates after remapping all
 * references.  Anything left here is ambiguous; conversion never picks a
 * winner merely because one row happens to be referenced or older.
 */
async function validateReservePub(
  tx: WalletDbTransaction,
  reserve: WalletReserve,
): Promise<void> {
  const selected = await tx.getReserveByReservePub(reserve.reservePub);
  if (!selected || selected.rowId !== reserve.rowId) {
    throw Error(
      `conversion refused: multiple reserve rows have public key ${reserve.reservePub}`,
    );
  }
}

const rsaWithdrawValues = { cipher: "RSA" } as const;

function normalizePlanchet(rec: WalletPlanchet): WalletPlanchet {
  return rec.exchangeWithdrawValues === undefined
    ? ({ ...rec, exchangeWithdrawValues: rsaWithdrawValues } as WalletPlanchet)
    : rec;
}

function normalizeCoin(rec: WalletCoin): WalletCoin {
  const stripped = stripLegacy("coins")!(rec) as WalletCoin;
  return {
    ...stripped,
    exchangeMasterPub: stripped.exchangeMasterPub ?? "",
    exchangeWithdrawValues:
      stripped.exchangeWithdrawValues ?? rsaWithdrawValues,
  };
}

function normalizeCoinAvailability(
  rec: WalletCoinAvailability,
): WalletCoinAvailability {
  return { ...rec, hasFreshCoins: rec.freshCoinCount > 0 ? 1 : 0 };
}

/**
 * The copy plan, in groups.
 *
 * Each group runs in one destination transaction, and groups run in
 * ownership order (parents before their children), so every commit leaves
 * the destination's deferred foreign keys satisfied.
 */
