export enum DepositEligibilityReasonType {
  DirectDepositDisabled = "direct-deposit-disabled",
  ScopeRestricted = "scope-restricted",
  WireMethodUnsupported = "wire-method-unsupported",
  WireFeeUnavailable = "wire-fee-unavailable",
  DepositAccountRestricted = "deposit-account-restricted",
}

/** Reason why a ready, same-currency exchange cannot serve a deposit. */
export type DepositEligibilityReason =
  | { type: DepositEligibilityReasonType.DirectDepositDisabled }
  | {
      type: DepositEligibilityReasonType.ScopeRestricted;
      scopeInfo: ScopeInfo;
    }
  | {
      type: DepositEligibilityReasonType.WireMethodUnsupported;
      wireMethod: string;
    }
  | {
      type: DepositEligibilityReasonType.WireFeeUnavailable;
      wireMethod: string;
    }
  | {
      type: DepositEligibilityReasonType.DepositAccountRestricted;
      wireMethod: string;
      accountRestrictions: Record<string, AccountRestriction[]>;
    };

