/**
 * Coin selection algorithm the wallet uses when spending.
 *
 * "legacy-2024" is the algorithm the wallet shipped with in 2024: strictly
 * largest-coin-first, without the exact-fit shortcut and the deposit-fee
 * allowance correction that were added later.  It is kept reachable because
 * test suites outside this repository (in particular the exchange's auditor
 * tests) pin the coin selections it produces.
 */
export type CoinSelectionAlgorithm = "default" | "legacy-2024";

export interface PartialWalletRunConfig {
  testing?: Partial<WalletRunConfig["testing"]>;
  features?: Partial<WalletRunConfig["features"]>;
  lazyTaskLoop?: Partial<WalletRunConfig["lazyTaskLoop"]>;
  logLevel?: Partial<WalletRunConfig["logLevel"]>;
}

export interface WalletRunConfig {
  /**
   * Unsafe options which it should only be used to create
   * testing environment.
   */
  testing: {
    devModeActive: boolean;
    insecureTrustExchange: boolean;
    preventThrottling: boolean;
    skipDefaults: boolean;
    emitObservabilityEvents?: boolean;

    /**
     * Coin selection algorithm to use when spending.
     *
     * Defaults to the TALER_WALLET_COINSEL environment variable, and to
     * "default" when that is unset.
     */
    coinSelectionAlgorithm: CoinSelectionAlgorithm;
  };

  /**
   * Configurations values that may be safe to show to the user
   */
  features: {
    allowHttp: boolean;

    /**
     * Migrate the wallet database to wallet-core's native sqlite schema,
     * replacing the IndexedDB emulation it has been stored in so far.
     *
     * Checked whenever the wallet is initialized, so a client that offers
     * this as a setting only has to initialize the wallet again for it to
     * take effect.  Off by default: the native schema is still experimental.
     *
     * The migration happens once and is not undone by clearing the flag --
     * afterwards the database *is* a native one.  It also only ever runs
     * where the host stores the wallet in a sqlite file, which excludes the
     * browser extension.
     */
    migrateNativeDb: boolean;

    /**
     * Use wallet-core's native sqlite schema when initializing a new, empty
     * database.
     *
     * Unlike migrateNativeDb, this never converts an existing IndexedDB
     * wallet.  Hosts without a native sqlite backend ignore the preference.
     */
    useNativeDb: boolean;
  };

  /**
   * Start processing tasks only when explicitly required, even after
   * init has been called.
   *
   * Useful when the wallet is started to make single read-only request,
   * as otherwise wallet-core starts making network request and process
   * unrelated pending tasks.
   */
  lazyTaskLoop: boolean;

  /**
   * Global log level.
   */
  logLevel: string;
}

