/**
 * Shorter version of stringifyScopeInfo
 */
export function stringifyScopeInfoShort(si: ScopeInfo): string {
  switch (si.type) {
    case ScopeType.Global:
      return `${si.currency}`;
    case ScopeType.Exchange:
      return `${si.currency}/${encodeURIComponent(si.url)}`;
    case ScopeType.Auditor:
      return `${si.currency}:${encodeURIComponent(si.url)}`;
    case ScopeType.ExchangeLegacyKeys:
      // The URL is percent-encoded and so contains no slash of its own,
      // which is what lets a third field be appended unambiguously.
      return `${si.currency}/${encodeURIComponent(si.url)}/${si.masterPub}`;
  }
}
export function parseScopeInfoShort(si: string): ScopeInfo | undefined {
  const indexOfColon = si.indexOf(":");
  const indexOfSlash = si.indexOf("/");
  if (indexOfColon === -1 && indexOfSlash === -1) {
    return {
      type: ScopeType.Global,
      currency: si,
    };
  }
  if (indexOfColon > 0) {
    return {
      type: ScopeType.Auditor,
      currency: si.substring(0, indexOfColon),
      url: decodeURIComponent(si.substring(indexOfColon + 1)),
    };
  }
  if (indexOfSlash > 0) {
    const currency = si.substring(0, indexOfSlash);
    const rest = si.substring(indexOfSlash + 1);
    const sep = rest.indexOf("/");
    if (sep > 0) {
      return {
        type: ScopeType.ExchangeLegacyKeys,
        currency,
        url: decodeURIComponent(rest.substring(0, sep)),
        masterPub: rest.substring(sep + 1),
      };
    }
    return {
      type: ScopeType.Exchange,
      currency,
      url: decodeURIComponent(rest),
    };
  }
  return undefined;
}

/**
 * Encode scope info as a string.
 *
 * Format must be stable as it's used in the database.
 */
export function stringifyScopeInfo(si: ScopeInfo): string {
  switch (si.type) {
    case ScopeType.Global:
      return `taler-si:global/${si.currency}`;
    case ScopeType.Auditor:
      return `taler-si:auditor/${si.currency}/${encodeURIComponent(si.url)}`;
    case ScopeType.Exchange:
      return `taler-si:exchange/${si.currency}/${encodeURIComponent(si.url)}`;
    case ScopeType.ExchangeLegacyKeys:
      // A prefix of its own, so that every scope string written before this
      // type existed still encodes to exactly the bytes it did before and no
      // stored record has to be rewritten.
      return `taler-si:exchange-legacy/${si.currency}/${encodeURIComponent(
        si.url,
      )}/${si.masterPub}`;
  }
}

