export enum InsufficientBalanceHint {
  /**
   *  Merchant doesn't accept money from exchange(s) that the wallet supports.
   */
  MerchantAcceptInsufficient = "merchant-accept-insufficient",

  /**
   * Merchant accepts funds from a matching exchange, but the funds can't be
   * deposited with the wire method.
   */
  MerchantDepositInsufficient = "merchant-deposit-insufficient",

  /**
   * While in principle the balance is sufficient,
   * the age restriction on coins causes the spendable
   * balance to be insufficient.
   */
  AgeRestricted = "age-restricted",

  /**
   * Wallet has enough available funds,
   * but the material funds are insufficient. Usually because there is a
   * pending refresh operation.
   */
  WalletBalanceMaterialInsufficient = "wallet-balance-material-insufficient",

  /**
   * The wallet simply doesn't have enough available funds.
   * This is the "obvious" case of insufficient balance.
   */
  WalletBalanceAvailableInsufficient = "wallet-balance-available-insufficient",

  /**
   * Exchange is missing the global fee configuration, thus fees are unknown
   * and funds from this exchange can't be used for p2p payments.
   */
  ExchangeMissingGlobalFees = "exchange-missing-global-fees",

  /**
   * Even though the balance looks sufficient for the instructed amount,
   * the fees can be covered by neither the merchant nor the remaining wallet
   * balance.
   */
  FeesNotCovered = "fees-not-covered",
}

/**
 * Machine-readable reasons that prevented a requested coin selection.
 *
 * Unlike {@link InsufficientBalanceHint}, these values are exhaustive and can
 * be reported together.  Consumers must branch on the discriminator instead
 * of assuming that the first entry is the only cause.
 */
export enum CoinSelectionFailureReasonType {
  AvailableBalanceInsufficient = "available-balance-insufficient",
  PendingRefresh = "pending-refresh",
  MinimumAge = "minimum-age",
  ScopeRestricted = "scope-restricted",
  ReceiverNotAccepted = "receiver-not-accepted",
  ReceiverExchangeMasterPubMismatch = "receiver-exchange-master-pub-mismatch",
  WireMethodUnsupported = "wire-method-unsupported",
  WireFeeUnavailable = "wire-fee-unavailable",
  DepositAccountRestricted = "deposit-account-restricted",
  ExchangeGlobalFeesUnavailable = "exchange-global-fees-unavailable",
  FeesNotCovered = "fees-not-covered",
  BalanceFragmented = "balance-fragmented",
  SupersededExchangeMasterPub = "superseded-exchange-master-pub",
  SelectionFailed = "selection-failed",
}

export type CoinSelectionFailureReason =
  | {
      type: CoinSelectionFailureReasonType.AvailableBalanceInsufficient;
      amountAvailable: AmountString;
    }
  | {
      type: CoinSelectionFailureReasonType.PendingRefresh;
      amountPendingRefresh: AmountString;
    }
  | {
      type: CoinSelectionFailureReasonType.MinimumAge;
      requiredMinimumAge: number;
      amountAgeAcceptable: AmountString;
    }
  | {
      type: CoinSelectionFailureReasonType.ScopeRestricted;
      scopeInfo: ScopeInfo;
    }
  | { type: CoinSelectionFailureReasonType.ReceiverNotAccepted }
  | {
      type: CoinSelectionFailureReasonType.ReceiverExchangeMasterPubMismatch;
      walletMasterPub: string;
      receiverMasterPubs: string[];
    }
  | {
      type: CoinSelectionFailureReasonType.WireMethodUnsupported;
      wireMethod: string;
    }
  | {
      type: CoinSelectionFailureReasonType.WireFeeUnavailable;
      wireMethod: string;
    }
  | {
      type: CoinSelectionFailureReasonType.DepositAccountRestricted;
      wireMethod: string;
      accountRestrictions: Record<string, AccountRestriction[]>;
    }
  | { type: CoinSelectionFailureReasonType.ExchangeGlobalFeesUnavailable }
  | {
      type: CoinSelectionFailureReasonType.FeesNotCovered;
      maximumPayableAmount: AmountString;
    }
  | {
      type: CoinSelectionFailureReasonType.BalanceFragmented;
      combinedMaximumPayableAmount: AmountString;
    }
  | {
      type: CoinSelectionFailureReasonType.SupersededExchangeMasterPub;
      amountAffected: AmountString;
    }
  | { type: CoinSelectionFailureReasonType.SelectionFailed };

/**
 * Balance amounts before age, receiver, wire and fee restrictions.
 *
 * The terminology follows balance.ts: pending withdrawals and peer credits
 * are pending incoming balance and are not included here.  Only effective
 * outputs expected from unfinished refreshes bridge material to available.
 */
export interface CoinSelectionBalanceSnapshot {
  /** Balance that the wallet believes it can spend immediately. */
  material: AmountString;

  /** Expected effective output of unfinished refresh operations. */
  pendingRefresh: AmountString;

  /** Material balance plus pending refresh output. */
  available: AmountString;
}

export interface CoinSelectionExchangeFailureDiagnostics {
  /** Balance held at this exchange before payment restrictions. */
  balance: CoinSelectionBalanceSnapshot;

  /** Maximum contribution selectable from this exchange for this request. */
  maximumPayableAmount: AmountString;

  /** Exchange-local reasons, in deterministic evaluation order. */
  reasons: CoinSelectionFailureReason[];
}

/** Structured explanation emitted by current wallet-core versions. */
export interface PaymentInsufficientBalanceStructuredDetails {
  /** Balance in the requested sender scope before payment restrictions. */
  balance: CoinSelectionBalanceSnapshot;

  /**
   * Maximum contribution attainable under the failed request's actual
   * restrictions and fee policy.  For peer payments this is the maximum at
   * one exchange, since peer payments cannot combine exchanges.
   */
  maximumPayableAmount: AmountString;

  /** Operation-wide reasons, in deterministic evaluation order. */
  reasons: CoinSelectionFailureReason[];

  /** Detailed analysis for every same-currency exchange known to the wallet. */
  exchanges: Record<string, CoinSelectionExchangeFailureDiagnostics>;
}

