/**
 * Info about an exchange entry in the wallet.
 */
/**
 * An exchange that changed its key set, pending the user's confirmation.
 *
 * The wallet has already adopted the new key set, so the entry works and the
 * older coins stay spendable.  What is withheld until this is confirmed is
 * withdrawing: the bank details a withdrawal pays into are signed by the
 * master key, so adopting a new one silently would let a URL that changed
 * hands redirect the next transfer.
 */
export interface ExchangeKeyChangeInfo {
  /** Master public key the exchange now uses, and the wallet now trusts. */
  currentMasterPub: string;
  currentCurrency: string;
  /** Master public key the wallet's older funds were issued under. */
  supersededMasterPub: string;
  supersededCurrency: string;
  /**
   * Whether the new key set still advertises denominations the wallet holds
   * coins of.
   *
   * False means the exchange does not offer to settle the older coins at all.
   * True is the exchange's claim that it does, not proof of continuity:
   * denomination public keys are public and anyone can re-publish them.
   */
  sharesDenominations: boolean;
  firstSeen: TalerPreciseTimestamp;
}

export const codecForExchangeKeyChangeInfo = (): Codec<ExchangeKeyChangeInfo> =>
  buildCodecForObject<ExchangeKeyChangeInfo>()
    .property("currentMasterPub", codecForString())
    .property("currentCurrency", codecForString())
    .property("supersededMasterPub", codecForString())
    .property("supersededCurrency", codecForString())
    .property("sharesDenominations", codecForBoolean())
    .property("firstSeen", codecForPreciseTimestamp)
    .build("ExchangeKeyChangeInfo");

