export class PeerPushCreditTransactionContext implements TransactionContext {
  readonly transactionId: TransactionIdStr;
  readonly taskId: TaskIdStr;

  constructor(
    public wex: WalletExecutionContext,
    public peerPushCreditId: string,
  ) {
    this.transactionId = constructTransactionIdentifier({
      tag: TransactionType.PeerPushCredit,
      peerPushCreditId,
    });
    this.taskId = constructTaskIdentifier({
      tag: PendingTaskType.PeerPushCredit,
      peerPushCreditId,
    });
  }

  async updateTransactionMeta(tx: WalletDbTransaction): Promise<void> {
    const rec = await tx.getPeerPushCredit(this.peerPushCreditId);
    if (rec == null) {
      await tx.deleteTransactionMeta(this.transactionId);
    } else {
      await tx.upsertTransactionMeta({
        currency: Amounts.currencyOf(rec.estimatedAmountEffective),
        exchanges: [rec.exchangeBaseUrl],
        status: rec.status,
        timestamp: rec.timestamp,
        transactionId: this.transactionId,
      });
    }
  }

  /**
   * Get the full transaction details for the transaction.
   *
   * Returns undefined if the transaction is in a state where we do not have a
   * transaction item (e.g. if it was deleted).
   */
  async lookupFullTransaction(
    tx: WalletDbTransaction,
  ): Promise<Transaction | undefined> {
    const pushInc = await tx.getPeerPushCredit(this.peerPushCreditId);
    if (!pushInc) {
      return undefined;
    }

    let wg: WalletWithdrawalGroup | undefined = undefined;
    let wgRetryRecord: WalletOperationRetry | undefined = undefined;
    if (pushInc.withdrawalGroupId) {
      wg = await tx.getWithdrawalGroup(pushInc.withdrawalGroupId);
      if (wg) {
        const withdrawalOpId = TaskIdentifiers.forWithdrawal(wg);
        wgRetryRecord = await tx.getOperationRetry(withdrawalOpId);
      }
    }
    const pushIncOpId = TaskIdentifiers.forPeerPushCredit(pushInc);
    const pushRetryRecord = await tx.getOperationRetry(pushIncOpId);

    const ct = await tx.getContractTerms(pushInc.contractTermsHash);

    if (!ct) {
      throw Error("contract terms for P2P payment not found");
    }

    const peerContractTerms = ct.contractTermsRaw;

    let kycUrl: string | undefined = undefined;
    let kycAccessToken: string | undefined = undefined;
    if (wg?.kycAccessToken && wg.exchangeBaseUrl) {
      // This should not really happen, as the p2p merge
      // should not count towards the withdrawal limit.
      kycUrl = new URL(`kyc-spa/${wg.kycAccessToken}`, wg.exchangeBaseUrl).href;
      kycAccessToken = wg.kycAccessToken;
    } else if (pushInc.kycAccessToken) {
      kycUrl = new URL(
        `kyc-spa/${pushInc.kycAccessToken}`,
        pushInc.exchangeBaseUrl,
      ).href;
      kycAccessToken = pushInc.kycAccessToken;
    }

    if (wg) {
      if (wg.wgInfo.withdrawalType !== WithdrawalRecordType.PeerPushCredit) {
        throw Error("invalid withdrawal group type for push payment credit");
      }
      checkDbInvariant(wg.instructedAmount !== undefined, "wg uninitialized");
      checkDbInvariant(wg.denomsSel !== undefined, "wg uninitialized");
      checkDbInvariant(wg.exchangeBaseUrl !== undefined, "wg uninitialized");

      const txState = computePeerPushCreditTransactionState(pushInc);
      return {
        type: TransactionType.PeerPushCredit,
        txState,
        stId: pushInc.status,
        scopes: await getScopeForAllExchanges(tx, [pushInc.exchangeBaseUrl]),
        txActions: computePeerPushCreditTransactionActions(pushInc),
        amountEffective: isUnsuccessfulTransaction(txState)
          ? Amounts.stringify(Amounts.zeroOfAmount(wg.instructedAmount))
          : Amounts.stringify(wg.denomsSel.totalCoinValue),
        amountRaw: Amounts.stringify(wg.instructedAmount),
        exchangeBaseUrl: wg.exchangeBaseUrl,
        info: {
          expiration: peerContractTerms.purse_expiration,
          summary: peerContractTerms.summary,
          iconId: peerContractTerms.icon_id,
        },
        timestamp: timestampPreciseFromDb(wg.timestampStart),
        transactionId: this.transactionId,
        abortReason: pushInc.abortReason,
        failReason: pushInc.failReason,
        kycUrl,
        kycPaytoHash: wg.kycPaytoHash,
        ...(wgRetryRecord?.lastError ? { error: wgRetryRecord.lastError } : {}),
      };
    }

    const txState = computePeerPushCreditTransactionState(pushInc);
    return {
      type: TransactionType.PeerPushCredit,
      txState,
      stId: pushInc.status,
      scopes: await getScopeForAllExchanges(tx, [pushInc.exchangeBaseUrl]),
      txActions: computePeerPushCreditTransactionActions(pushInc),
      amountEffective: isUnsuccessfulTransaction(txState)
        ? Amounts.stringify(Amounts.zeroOfAmount(peerContractTerms.amount))
        : // FIXME: This is wrong, needs to consider fees!
          Amounts.stringify(peerContractTerms.amount),
      amountRaw: Amounts.stringify(peerContractTerms.amount),
      exchangeBaseUrl: pushInc.exchangeBaseUrl,
      info: {
        expiration: peerContractTerms.purse_expiration,
        summary: peerContractTerms.summary,
        iconId: peerContractTerms.icon_id,
      },
      kycUrl,
      kycPaytoHash: pushInc.kycPaytoHash,
      kycAccessToken,
      timestamp: timestampPreciseFromDb(pushInc.timestamp),
      transactionId: this.transactionId,
      abortReason: pushInc.abortReason,
      failReason: pushInc.failReason,
      ...(pushRetryRecord?.lastError
        ? { error: pushRetryRecord.lastError }
        : {}),
    };
  }

  async getRecordHandle(
    tx: WalletDbTransaction,
  ): Promise<
    [WalletPeerPushCredit | undefined, RecordHandle<WalletPeerPushCredit>]
  > {
    return getGenericRecordHandle<WalletPeerPushCredit>(
      this,
      tx,
      async () => tx.getPeerPushCredit(this.peerPushCreditId),
      async (r) => {
        await tx.upsertPeerPushCredit(r);
      },
      async () => tx.deletePeerPushCredit(this.peerPushCreditId),
      (r) => computePeerPushCreditTransactionState(r),
      (r) => r.status,
      () => this.updateTransactionMeta(tx),
    );
  }

  async userDeleteTransaction(): Promise<void> {
    await this.wex.runWalletDbTx(async (tx) => this.deleteTransactionInTx(tx));
  }

  async deleteTransactionInTx(tx: WalletDbTransaction): Promise<void> {
    const [rec, h] = await this.getRecordHandle(tx);
    if (!rec) {
      return;
    }
    await h.update(undefined, "delete");
    const withdrawalGroupId = rec.withdrawalGroupId;
    if (withdrawalGroupId != null) {
      const withdrawalCtx = new WithdrawTransactionContext(
        this.wex,
        withdrawalGroupId,
      );
      await withdrawalCtx.deleteTransactionInTx(tx);
    }
  }

  async userSuspendTransaction(): Promise<void> {
    await this.wex.runWalletDbTx(async (tx) => {
      const [rec, h] = await this.getRecordHandle(tx);
      if (!rec) {
        return;
      }
      switch (rec.status) {
        case PeerPushCreditStatus.DialogProposed:
        case PeerPushCreditStatus.Done:
        case PeerPushCreditStatus.SuspendedMerge:
        case PeerPushCreditStatus.SuspendedMergeKycRequired:
        case PeerPushCreditStatus.SuspendedWithdrawing:
        case PeerPushCreditStatus.SuspendedBalanceKycRequired:
        case PeerPushCreditStatus.SuspendedBalanceKycInit:
        case PeerPushCreditStatus.Failed:
        case PeerPushCreditStatus.FailedKycHardLimit:
        case PeerPushCreditStatus.Aborted:
        case PeerPushCreditStatus.Expired:
        case PeerPushCreditStatus.FinalizingKycHardLimit:
          return;
        case PeerPushCreditStatus.PendingBalanceKycRequired:
          rec.status = PeerPushCreditStatus.SuspendedBalanceKycRequired;
          break;
        case PeerPushCreditStatus.PendingBalanceKycInit:
          rec.status = PeerPushCreditStatus.SuspendedBalanceKycInit;
          break;
        case PeerPushCreditStatus.PendingMergeKycRequired:
          rec.status = PeerPushCreditStatus.SuspendedMergeKycRequired;
          break;
        case PeerPushCreditStatus.PendingMerge:
          rec.status = PeerPushCreditStatus.SuspendedMerge;
          break;
        case PeerPushCreditStatus.PendingWithdrawing:
          // FIXME: Suspend internal withdrawal transaction!
          rec.status = PeerPushCreditStatus.SuspendedWithdrawing;
          break;
        default:
          assertUnreachable(rec.status);
      }
      await h.update(rec, "suspend");
    });
    this.wex.taskScheduler.stopShepherdTask(this.taskId);
  }

  async userAbortTransaction(): Promise<void> {
    await this.wex.runWalletDbTx(async (tx) => {
      const [rec, h] = await this.getRecordHandle(tx);
      if (!rec) {
        return;
      }
      switch (rec.status) {
        case PeerPushCreditStatus.Failed:
        case PeerPushCreditStatus.FailedKycHardLimit:
        case PeerPushCreditStatus.Aborted:
        case PeerPushCreditStatus.Done:
        case PeerPushCreditStatus.FinalizingKycHardLimit:
          return;
        case PeerPushCreditStatus.SuspendedMerge:
        case PeerPushCreditStatus.DialogProposed:
        case PeerPushCreditStatus.SuspendedMergeKycRequired:
        case PeerPushCreditStatus.SuspendedWithdrawing:
        case PeerPushCreditStatus.PendingBalanceKycRequired:
        case PeerPushCreditStatus.SuspendedBalanceKycRequired:
        case PeerPushCreditStatus.PendingWithdrawing:
        case PeerPushCreditStatus.PendingMergeKycRequired:
        case PeerPushCreditStatus.PendingMerge:
        case PeerPushCreditStatus.PendingBalanceKycInit:
        case PeerPushCreditStatus.SuspendedBalanceKycInit:
        case PeerPushCreditStatus.Expired:
          rec.status = PeerPushCreditStatus.Aborted;
          break;
        default:
          assertUnreachable(rec.status);
      }
      await h.update(rec, "abort");
    });
    this.wex.taskScheduler.stopShepherdTask(this.taskId);
  }

  async userResumeTransaction(): Promise<void> {
    await this.wex.runWalletDbTx(async (tx) => {
      const [rec, h] = await this.getRecordHandle(tx);
      if (!rec) {
        return;
      }
      switch (rec.status) {
        case PeerPushCreditStatus.DialogProposed:
        case PeerPushCreditStatus.PendingMergeKycRequired:
        case PeerPushCreditStatus.PendingMerge:
        case PeerPushCreditStatus.PendingWithdrawing:
        case PeerPushCreditStatus.PendingBalanceKycRequired:
        case PeerPushCreditStatus.PendingBalanceKycInit:
        case PeerPushCreditStatus.Done:
        case PeerPushCreditStatus.Aborted:
        case PeerPushCreditStatus.Failed:
        case PeerPushCreditStatus.FailedKycHardLimit:
        case PeerPushCreditStatus.Expired:
        case PeerPushCreditStatus.FinalizingKycHardLimit:
          return;
        case PeerPushCreditStatus.SuspendedMerge:
          rec.status = PeerPushCreditStatus.PendingMerge;
          break;
        case PeerPushCreditStatus.SuspendedMergeKycRequired:
          rec.status = PeerPushCreditStatus.PendingMergeKycRequired;
          break;
        case PeerPushCreditStatus.SuspendedWithdrawing:
          // FIXME: resume underlying "internal-withdrawal" transaction.
          rec.status = PeerPushCreditStatus.PendingWithdrawing;
          break;
        case PeerPushCreditStatus.SuspendedBalanceKycRequired:
          rec.status = PeerPushCreditStatus.PendingBalanceKycRequired;
          break;
        case PeerPushCreditStatus.SuspendedBalanceKycInit:
          rec.status = PeerPushCreditStatus.PendingBalanceKycInit;
          break;
        default:
          assertUnreachable(rec.status);
      }
      await h.update(rec, "resume");
    });
    await this.wex.taskScheduler.resetTask(this.taskId);
  }

  async failTransaction(
    fromSt: PeerPushCreditStatus,
    reason?: TalerErrorDetail,
  ): Promise<void> {
    const { wex } = this;
    await wex.runWalletDbTx(async (tx) => {
      const [rec, h] = await this.getRecordHandle(tx);
      if (rec?.status != fromSt) {
        return;
      }
      rec.status = PeerPushCreditStatus.Failed;
      rec.failReason = reason;
      await h.update(rec, "fail");
    });
  }

  async userFailTransaction(reason?: TalerErrorDetail): Promise<void> {
    await this.wex.runWalletDbTx(async (tx) => {
      const [rec, h] = await this.getRecordHandle(tx);
      if (!rec) {
        return;
      }
      switch (rec.status) {
        case PeerPushCreditStatus.PendingWithdrawing:
        case PeerPushCreditStatus.SuspendedWithdrawing:
          rec.status = PeerPushCreditStatus.Failed;
          rec.failReason = reason;
          break;
        case PeerPushCreditStatus.Done:
        case PeerPushCreditStatus.Aborted:
        case PeerPushCreditStatus.Failed:
        case PeerPushCreditStatus.FailedKycHardLimit:
        case PeerPushCreditStatus.Expired:
        case PeerPushCreditStatus.FinalizingKycHardLimit:
          // Already in a final state.
          return;
        case PeerPushCreditStatus.DialogProposed:
        case PeerPushCreditStatus.PendingMergeKycRequired:
        case PeerPushCreditStatus.PendingMerge:
        case PeerPushCreditStatus.SuspendedMerge:
        case PeerPushCreditStatus.SuspendedMergeKycRequired:
        case PeerPushCreditStatus.PendingBalanceKycRequired:
        case PeerPushCreditStatus.SuspendedBalanceKycRequired:
        case PeerPushCreditStatus.PendingBalanceKycInit:
        case PeerPushCreditStatus.SuspendedBalanceKycInit:
          // The current state does not advertise Fail.
          return;
        default:
          assertUnreachable(rec.status);
      }
      await h.update(rec, "user-fail");
    });
    this.wex.taskScheduler.stopShepherdTask(this.taskId);
  }
}

export async function preparePeerPushCredit(
  wex: WalletExecutionContext,
  req: PreparePeerPushCreditRequest,
): Promise<PreparePeerPushCreditResponse> {
  return runWithMaybeProgressContext(
    wex,
    "preparePeerPushCredit",
    req.progressToken,
    () => internalPreparePeerPushCredit(wex, req),
  );
}

async function internalPreparePeerPushCredit(
  wex: WalletExecutionContext,
  req: PreparePeerPushCreditRequest,
): Promise<PreparePeerPushCreditResponse> {
  if (!req.talerUri && !req.transactionId) {
    throw TalerError.fromDetail(
      TalerErrorCode.WALLET_CORE_API_BAD_REQUEST,
      { parameter: "talerUri" },
      "either talerUri or transactionId must be specified",
    );
  }

  let uri: TalerPayPushUri | undefined;
  if (req.talerUri) {
    uri = Result.orUndefined(
      TalerUris.parseRestricted(req.talerUri, TalerUriAction.PayPush),
    );
    if (!uri) {
      throw TalerError.fromDetail(
        TalerErrorCode.WALLET_TALER_URI_MALFORMED,
        { talerUri: req.talerUri, expectedAction: TalerUriAction.PayPush },
        "expected a taler://pay-push URI",
      );
    }
  }

  let parsedTxId: string | undefined;
  if (req.transactionId) {
    const parsedRes = parseTransactionIdentifier(req.transactionId);
    if (!parsedRes || parsedRes.tag !== TransactionType.PeerPushCredit) {
      throw makeInvalidTransactionIdError(
        req.transactionId,
        TransactionType.PeerPushCredit,
      );
    }
    parsedTxId = parsedRes.peerPushCreditId;
  }

  const existing = await wex.runWalletDbTx(async (tx) => {
    let existingPushInc: WalletPeerPushCredit | undefined;
    if (uri) {
      existingPushInc = await tx.getPeerPushCreditByExchangeAndContractPriv(
        uri.exchangeBaseUrl,
        uri.contractPriv,
      );
    } else if (parsedTxId) {
      existingPushInc = await tx.getPeerPushCredit(parsedTxId);
    }
    if (!existingPushInc) {
      return;
    }
    const existingContractTermsRec = await tx.getContractTerms(
      existingPushInc.contractTermsHash,
    );
    if (!existingContractTermsRec) {
      throw Error(
        "contract terms for peer push payment credit not found in database",
      );
    }
    const existingContractTerms = codecForPeerContractTerms().decode(
      existingContractTermsRec.contractTermsRaw,
    );
    return { existingPushInc, existingContractTerms };
  });

  if (existing) {
    const exchange = await fetchFreshExchangeWithRetryNow(
      wex,
      existing.existingPushInc.exchangeBaseUrl,
    );
    const currency = Amounts.currencyOf(existing.existingContractTerms.amount);
    const exchangeBaseUrl = existing.existingPushInc.exchangeBaseUrl;
    const scopeInfo = await wex.runWalletDbTx(
      async (tx) => await getExchangeScopeInfo(tx, exchangeBaseUrl, currency),
    );
    return {
      amount: existing.existingContractTerms.amount,
      amountEffective: existing.existingPushInc.estimatedAmountEffective,
      amountRaw: existing.existingContractTerms.amount,
      contractTerms: existing.existingContractTerms,
      transactionId: constructTransactionIdentifier({
        tag: TransactionType.PeerPushCredit,
        peerPushCreditId: existing.existingPushInc.peerPushCreditId,
      }),
      txState: computePeerPushCreditTransactionState(existing.existingPushInc),
      scopeInfo,
      exchangeBaseUrl,
      ...getPeerCreditLimitInfo(
        exchange,
        existing.existingContractTerms.amount,
      ),
    };
  }

  if (!uri) {
    throw makeTransactionNotFoundError(req.transactionId!);
  }

  const exchangeBaseUrl = uri.exchangeBaseUrl;
  const exchange = await fetchFreshExchangeWithRetryNow(wex, exchangeBaseUrl);
  const contractPriv = uri.contractPriv;
  const contractPub = encodeCrock(eddsaGetPublic(decodeCrock(contractPriv)));
  const exchangeClient = walletExchangeClient(exchangeBaseUrl, wex);

  // Retried under a progress context: a terminal outcome (NotFound) comes back
  // as a result case rather than an exception, so only transient failures are
  // retried — the caller still handles NotFound below.
  const contractResp = await runWithProgressRetries(wex, () =>
    exchangeClient.getContract(contractPub),
  );
  switch (contractResp.case) {
    case "ok":
      break;
    case HttpStatusCode.NotFound:
      throw TalerError.fromDetail(
        TalerErrorCode.WALLET_PEER_CONTRACT_NOT_FOUND,
        {},
        "the exchange does not know this peer-to-peer contract",
      );
    default:
      assertUnreachable(contractResp);
  }
  const pursePub = contractResp.body.purse_pub;

  const dec = await wex.cryptoApi.decryptContractForMerge({
    ciphertext: contractResp.body.econtract,
    contractPriv: contractPriv,
    pursePub: pursePub,
  });

  const contractTerms = codecForPeerContractTerms().decode(dec.contractTerms);
  if (isPurseGoneByExpiration(contractTerms.purse_expiration)) {
    throw TalerError.fromDetail(
      TalerErrorCode.WALLET_PEER_PUSH_CREDIT_PURSE_GONE,
      { purseExpired: true },
      "this payment expired",
    );
  }
  const resp = await runWithProgressRetries(wex, () =>
    exchangeClient.getPurseStatusAtDeposit(pursePub),
  );
  switch (resp.case) {
    case "ok":
      break;
    case HttpStatusCode.Gone: {
      const purseExpired = isPurseGoneByExpiration(
        contractTerms.purse_expiration,
      );
      throw TalerError.fromDetail(
        TalerErrorCode.WALLET_PEER_PUSH_CREDIT_PURSE_GONE,
        { purseExpired },
        purseExpired
          ? "this payment expired"
          : "the sender aborted this payment",
      );
    }
    case HttpStatusCode.NotFound:
      throw TalerError.fromDetail(
        TalerErrorCode.WALLET_PEER_CONTRACT_NOT_FOUND,
        {},
        "the exchange does not know the purse of this payment",
      );
    default:
      assertUnreachable(resp);
  }

  await requireValidExchangePurseStatus(wex, exchangeBaseUrl, resp.body);
  const purseStatus = resp.body;

  logger.info(
    `peer push credit, purse balance ${purseStatus.balance}, contract amount ${contractTerms.amount}`,
  );

  const peerPushCreditId = encodeCrock(getRandomBytes(32));

  const contractTermsHash = ContractTermsUtil.hashContractTerms(
    dec.contractTerms,
  );

  const withdrawalGroupId = encodeCrock(getRandomBytes(32));

  const wi = await getExchangeWithdrawalInfo(
    wex,
    exchangeBaseUrl,
    Amounts.parseOrThrow(purseStatus.balance),
    WithdrawalRecordType.PeerPushCredit,
    undefined,
  );

  if (wi.selectedDenoms.selectedDenoms.length === 0) {
    throw Error(
      `unable to prepare push credit from ${exchangeBaseUrl}, can't select denominations for instructed amount (${purseStatus.balance}`,
    );
  }

  const currency = Amounts.currencyOf(wi.withdrawalAmountRaw);

  const ctx = new PeerPushCreditTransactionContext(wex, peerPushCreditId);

  const res = await wex.runWalletDbTx(async (tx) => {
    await tx.upsertContractTerms({
      h: contractTermsHash,
      contractTermsRaw: dec.contractTerms,
    });

    const [rec, h] = await ctx.getRecordHandle(tx);
    if (rec) {
      throw Error("record already exists");
    }
    const newRec: WalletPeerPushCredit = {
      peerPushCreditId,
      contractPriv: contractPriv,
      exchangeBaseUrl: exchangeBaseUrl,
      mergePriv: dec.mergePriv,
      pursePub: pursePub,
      timestamp: timestampPreciseToDb(TalerPreciseTimestamp.now()),
      contractTermsHash,
      status: PeerPushCreditStatus.DialogProposed,
      withdrawalGroupId,
      currency: Amounts.currencyOf(purseStatus.balance),
      estimatedAmountEffective: Amounts.stringify(wi.withdrawalAmountEffective),
    };
    // Only the offer is presented to the user, the incoming funds are not
    // counted towards the balance until the transfer is confirmed.
    await h.update(newRec, "prepare", BalanceEffect.None);
    return {
      scopeInfo: await getExchangeScopeInfo(tx, exchangeBaseUrl, currency),
      newRec,
    };
  });

  wex.taskScheduler.startShepherdTask(ctx.taskId);

  return {
    amount: purseStatus.balance,
    amountEffective: wi.withdrawalAmountEffective,
    amountRaw: purseStatus.balance,
    contractTerms: dec.contractTerms,
    transactionId: ctx.transactionId,
    exchangeBaseUrl,
    scopeInfo: res.scopeInfo,
    txState: computePeerPushCreditTransactionState(res.newRec),
    ...getPeerCreditLimitInfo(exchange, purseStatus.balance),
  };
}

async function processPeerPushDebitMergeKyc(
  wex: WalletExecutionContext,
  peerInc: WalletPeerPushCredit,
  contractTerms: PeerContractTerms,
): Promise<TaskRunResult> {
  if (isPurseGoneByExpiration(contractTerms.purse_expiration)) {
    return reconcileExpiredPeerPushCredit(wex, peerInc, contractTerms);
  }
  const ctx = new PeerPushCreditTransactionContext(
    wex,
    peerInc.peerPushCreditId,
  );
  const { exchangeBaseUrl } = peerInc;
  // FIXME: What if this changes? Should be part of the p2p record
  const mergeReserveInfo = await getMergeReserveInfo(wex, {
    exchangeBaseUrl,
  });

  const accountPub = mergeReserveInfo.reservePub;
  const accountPriv = mergeReserveInfo.reservePriv;

  let myKycState: GenericKycStatusReq | undefined;

  if (peerInc.kycPaytoHash) {
    myKycState = {
      accountPriv,
      accountPub,
      // FIXME: Is this the correct amount?
      amount: peerInc.estimatedAmountEffective,
      exchangeBaseUrl,
      operation: "MERGE",
      paytoHash: peerInc.kycPaytoHash,
      lastAmlReview: peerInc.kycLastAmlReview,
      lastCheckCode: peerInc.kycLastCheckCode,
      lastCheckStatus: peerInc.kycLastCheckStatus,
      lastDeny: peerInc.kycLastDeny,
      lastRuleGen: peerInc.kycLastRuleGen,
      haveAccessToken: peerInc.kycAccessToken != null,
    };
  }

  if (myKycState == null || isKycOperationDue(myKycState)) {
    return processPendingMerge(wex, peerInc, contractTerms);
  }

  const algoRes = await runKycCheckAlgo(wex, myKycState);

  if (!algoRes.updatedStatus) {
    return algoRes.taskResult;
  }

  const updatedStatus = algoRes.updatedStatus;

  checkProtocolInvariant(algoRes.requiresAuth != true);
  const hardLimitReason = algoRes.hardLimitExceeded
    ? makeKycHardLimitError(myKycState)
    : undefined;

  await ctx.wex.runWalletDbTx(async (tx) => {
    const [rec, h] = await ctx.getRecordHandle(tx);
    if (!rec) {
      return;
    }
    rec.kycLastAmlReview = updatedStatus.lastAmlReview;
    rec.kycLastCheckStatus = updatedStatus.lastCheckStatus;
    rec.kycLastCheckCode = updatedStatus.lastCheckCode;
    rec.kycLastDeny = updatedStatus.lastDeny;
    rec.kycLastRuleGen = updatedStatus.lastRuleGen;
    rec.kycAccessToken = updatedStatus.accessToken;
    if (
      hardLimitReason &&
      rec.status === PeerPushCreditStatus.PendingMergeKycRequired
    ) {
      rec.status = PeerPushCreditStatus.FinalizingKycHardLimit;
      rec.failReason = hardLimitReason;
    }
    await h.update(rec, "merge-kyc-status");
  });

  return hardLimitReason ? TaskRunResult.progress() : algoRes.taskResult;
}

async function processPeerPushCreditKycHardLimitRecovery(
  wex: WalletExecutionContext,
  peerInc: WalletPeerPushCredit,
): Promise<TaskRunResult> {
  const exchangeClient = walletExchangeClient(peerInc.exchangeBaseUrl, wex);
  const statusResp = await exchangeClient.getPurseStatusAtMerge(
    peerInc.pursePub,
    true,
  );
  let nextStatus: PeerPushCreditStatus | undefined;
  switch (statusResp.case) {
    case "ok":
      await requireValidExchangePurseStatus(
        wex,
        peerInc.exchangeBaseUrl,
        statusResp.body,
      );
      if (isPurseMerged(statusResp.body)) {
        // A merge committed despite the earlier hard-limit response.  Resume
        // the idempotent merge path so custody moves to a tracked withdrawal
        // group, whose own hard-limit recovery can close the reserve.
        nextStatus = PeerPushCreditStatus.PendingMerge;
      }
      break;
    case HttpStatusCode.Gone:
    case HttpStatusCode.NotFound:
      // Unmerged purse value is refunded to its depositing coins when the
      // purse expires or is deleted by its owner.
      nextStatus = PeerPushCreditStatus.FailedKycHardLimit;
      break;
    default:
      assertUnreachable(statusResp);
  }
  if (!nextStatus) {
    return TaskRunResult.backoff();
  }
  const ctx = new PeerPushCreditTransactionContext(
    wex,
    peerInc.peerPushCreditId,
  );
  await wex.runWalletDbTx(async (tx) => {
    const [rec, h] = await ctx.getRecordHandle(tx);
    if (rec?.status !== PeerPushCreditStatus.FinalizingKycHardLimit) {
      return;
    }
    rec.status = nextStatus;
    if (nextStatus === PeerPushCreditStatus.PendingMerge) {
      delete rec.failReason;
    }
    await h.update(rec, "kyc-hard-limit-purse-recovery");
  });
  return nextStatus === PeerPushCreditStatus.PendingMerge
    ? TaskRunResult.progress()
    : TaskRunResult.finished();
}

async function transitionPeerPushCreditKycRequired(
  wex: WalletExecutionContext,
  peerInc: WalletPeerPushCredit,
  kycPending: LegitimizationNeededResponse,
): Promise<TaskRunResult> {
  const ctx = new PeerPushCreditTransactionContext(
    wex,
    peerInc.peerPushCreditId,
  );

  return await wex.runWalletDbTx(async (tx) => {
    const [peerInc, h] = await ctx.getRecordHandle(tx);
    if (!peerInc) {
      return TaskRunResult.finished();
    }
    peerInc.kycPaytoHash = kycPending.h_payto;
    peerInc.status = PeerPushCreditStatus.PendingMergeKycRequired;
    peerInc.kycLastDeny = timestampPreciseToDb(TalerPreciseTimestamp.now());
    await h.update(peerInc, "merge-kyc-required");
    return TaskRunResult.progress();
  });
}

async function continuePeerPushCreditAfterMerge(
  wex: WalletExecutionContext,
  peerInc: WalletPeerPushCredit,
  amount: ReturnType<typeof Amounts.parseOrThrow>,
  mergeReserveInfo: WalletReserve,
): Promise<TaskRunResult> {
  const ctx = new PeerPushCreditTransactionContext(
    wex,
    peerInc.peerPushCreditId,
  );
  const withdrawalGroupPrep = await internalPrepareCreateWithdrawalGroup(wex, {
    amount,
    wgInfo: {
      withdrawalType: WithdrawalRecordType.PeerPushCredit,
    },
    forcedWithdrawalGroupId: peerInc.withdrawalGroupId,
    exchangeBaseUrl: peerInc.exchangeBaseUrl,
    reserveStatus: WithdrawalGroupStatus.PendingQueryingStatus,
    reserveKeyPair: {
      priv: mergeReserveInfo.reservePriv,
      pub: mergeReserveInfo.reservePub,
    },
  });

  await wex.runWalletDbTx(async (tx) => {
    const [current, h] = await ctx.getRecordHandle(tx);
    if (!current) {
      return;
    }
    switch (current.status) {
      case PeerPushCreditStatus.PendingMerge:
      case PeerPushCreditStatus.PendingMergeKycRequired:
      case PeerPushCreditStatus.PendingBalanceKycRequired:
      case PeerPushCreditStatus.PendingBalanceKycInit: {
        current.status = PeerPushCreditStatus.PendingWithdrawing;
        const wgCreateRes = await internalPerformCreateWithdrawalGroup(
          wex,
          tx,
          withdrawalGroupPrep,
        );
        current.withdrawalGroupId =
          wgCreateRes.withdrawalGroup.withdrawalGroupId;
        break;
      }
      default:
        return;
    }
    await h.update(current, "merge-done");
  });
  return TaskRunResult.backoff();
}

function isActivePreMergePeerPushCreditStatus(
  status: PeerPushCreditStatus,
): boolean {
  switch (status) {
    case PeerPushCreditStatus.PendingMerge:
    case PeerPushCreditStatus.PendingMergeKycRequired:
    case PeerPushCreditStatus.PendingBalanceKycRequired:
    case PeerPushCreditStatus.PendingBalanceKycInit:
      return true;
    default:
      return false;
  }
}

async function reconcileExpiredPeerPushCredit(
  wex: WalletExecutionContext,
  peerInc: WalletPeerPushCredit,
  contractTerms: PeerContractTerms,
): Promise<TaskRunResult> {
  const exchangeClient = walletExchangeClient(peerInc.exchangeBaseUrl, wex);
  const statusResp = await exchangeClient.getPurseStatusAtMerge(
    peerInc.pursePub,
    true,
  );
  switch (statusResp.case) {
    case "ok":
      await requireValidExchangePurseStatus(
        wex,
        peerInc.exchangeBaseUrl,
        statusResp.body,
      );
      if (!isPurseMerged(statusResp.body)) {
        return TaskRunResult.longpollReturnedPending();
      }
      return continuePeerPushCreditAfterMerge(
        wex,
        peerInc,
        Amounts.parseOrThrow(contractTerms.amount),
        await getMergeReserveInfo(wex, {
          exchangeBaseUrl: peerInc.exchangeBaseUrl,
        }),
      );
    case HttpStatusCode.Gone: {
      const ctx = new PeerPushCreditTransactionContext(
        wex,
        peerInc.peerPushCreditId,
      );
      await wex.runWalletDbTx(async (tx) => {
        const [rec, h] = await ctx.getRecordHandle(tx);
        if (!rec || !isActivePreMergePeerPushCreditStatus(rec.status)) {
          return;
        }
        rec.status = PeerPushCreditStatus.Expired;
        await h.update(rec, "expired-before-merge");
      });
      return TaskRunResult.finished();
    }
    case HttpStatusCode.NotFound: {
      const ctx = new PeerPushCreditTransactionContext(
        wex,
        peerInc.peerPushCreditId,
      );
      await ctx.failTransaction(peerInc.status, statusResp.detail);
      return TaskRunResult.finished();
    }
    default:
      assertUnreachable(statusResp);
  }
}

async function processPendingMerge(
  wex: WalletExecutionContext,
  peerInc: WalletPeerPushCredit,
  contractTerms: PeerContractTerms,
): Promise<TaskRunResult> {
  const { peerPushCreditId } = peerInc;
  const ctx = new PeerPushCreditTransactionContext(wex, peerPushCreditId);

  if (isPurseGoneByExpiration(contractTerms.purse_expiration)) {
    return reconcileExpiredPeerPushCredit(wex, peerInc, contractTerms);
  }

  const kycCheckRes = await checkIncomingAmountLegalUnderKycBalanceThreshold(
    wex,
    peerInc.exchangeBaseUrl,
    peerInc.estimatedAmountEffective,
  );

  if (kycCheckRes.result === "violation") {
    // Do this before we transition so that the exchange is already in the right state.
    await handleStartExchangeWalletKyc(wex, {
      amount: kycCheckRes.nextThreshold,
      exchangeBaseUrl: peerInc.exchangeBaseUrl,
    });
    await ctx.wex.runWalletDbTx(async (tx) => {
      const [rec, h] = await ctx.getRecordHandle(tx);
      if (!rec) {
        return;
      }
      switch (rec.status) {
        case PeerPushCreditStatus.PendingMergeKycRequired:
        case PeerPushCreditStatus.PendingMerge: {
          rec.status = PeerPushCreditStatus.PendingBalanceKycInit;
          break;
        }
        default:
          return;
      }
      await h.update(rec, "merge-balance-kyc");
    });
    return TaskRunResult.progress();
  }

  const amount = Amounts.parseOrThrow(contractTerms.amount);

  // FIXME: What if this changes? Should be part of the p2p record
  const mergeReserveInfo = await getMergeReserveInfo(wex, {
    exchangeBaseUrl: peerInc.exchangeBaseUrl,
  });

  const timestamp = timestampPreciseFromDb(peerInc.timestamp);

  const mergeTimestamp = AbsoluteTime.toProtocolTimestamp(
    AbsoluteTime.fromPreciseTimestamp(timestamp),
  );

  const reservePayto = reservePaytoFromExchange(
    peerInc.exchangeBaseUrl,
    mergeReserveInfo.reservePub,
  );

  const sigRes = await wex.cryptoApi.signPurseMerge({
    contractTermsHash: ContractTermsUtil.hashContractTerms(contractTerms),
    flags: WalletAccountMergeFlags.MergeFullyPaidPurse,
    mergePriv: peerInc.mergePriv,
    mergeTimestamp: mergeTimestamp,
    purseAmount: Amounts.stringify(amount),
    purseExpiration: contractTerms.purse_expiration,
    purseFee: Amounts.stringify(Amounts.zeroOfCurrency(amount.currency)),
    pursePub: peerInc.pursePub,
    reservePayto,
    reservePriv: mergeReserveInfo.reservePriv,
  });

  const exchangeClient = walletExchangeClient(peerInc.exchangeBaseUrl, wex);

  const mergeReq: ExchangePurseMergeRequest = {
    payto_uri: reservePayto,
    merge_timestamp: mergeTimestamp,
    merge_sig: sigRes.mergeSig,
    reserve_sig: sigRes.accountSig,
  };

  logger.trace(`merge request: ${j2s(mergeReq)}`);
  if (isPurseGoneByExpiration(contractTerms.purse_expiration)) {
    return reconcileExpiredPeerPushCredit(wex, peerInc, contractTerms);
  }
  const mergeResp = await exchangeClient.postPurseMerge(
    peerInc.pursePub,
    mergeReq,
  );

  switch (mergeResp.case) {
    case "ok":
      logger.trace(`merge response: ${j2s(mergeResp.body)}`);
      break;
    case HttpStatusCode.UnavailableForLegalReasons: {
      const kycLegiNeededResp = mergeResp.body;
      logger.info(`kyc legitimization needed response: ${j2s(mergeResp.body)}`);
      return transitionPeerPushCreditKycRequired(
        wex,
        peerInc,
        kycLegiNeededResp,
      );
    }
    case HttpStatusCode.Conflict: {
      const conflictReservePayto = reservePaytoFromExchange(
        mergeResp.body.partner_url ?? peerInc.exchangeBaseUrl,
        mergeResp.body.reserve_pub,
      );
      const mergePub = (
        await wex.cryptoApi.eddsaGetPublic({ priv: peerInc.mergePriv })
      ).pub;
      const { valid } = await wex.cryptoApi.isValidPurseMergeSignature({
        mergeTimestamp: mergeResp.body.merge_timestamp,
        pursePub: peerInc.pursePub,
        reservePayto: conflictReservePayto,
        mergePub,
        mergeSig: mergeResp.body.merge_sig,
      });
      if (!valid) {
        throw TalerError.fromDetail(
          TalerErrorCode.WALLET_TRANSACTION_PROTOCOL_VIOLATION,
          {},
          "exchange returned an invalid purse merge conflict signature",
        );
      }
      if (conflictReservePayto === reservePayto) {
        // The exchange committed our earlier identical request but its success
        // response was lost.  Continue with withdrawal idempotently.
        break;
      }
      await ctx.wex.runWalletDbTx(async (tx) => {
        const [rec, h] = await ctx.getRecordHandle(tx);
        if (!rec) {
          return;
        }
        switch (rec.status) {
          case PeerPushCreditStatus.PendingMergeKycRequired:
          case PeerPushCreditStatus.PendingMerge: {
            // FIXME: reason / minor state "completed by other"?
            rec.status = PeerPushCreditStatus.Failed;
            break;
          }
          default:
            return;
        }
        await h.update(rec, "merge-conflict");
      });
      return TaskRunResult.finished();
    }
    case HttpStatusCode.Gone: {
      const purseExpired = isPurseGoneByExpiration(
        contractTerms.purse_expiration,
      );
      const reason = makeErrorDetail(
        TalerErrorCode.WALLET_PEER_PUSH_CREDIT_PURSE_GONE,
        { purseExpired },
        purseExpired
          ? "this payment expired"
          : "the sender aborted this payment",
      );
      await ctx.wex.runWalletDbTx(async (tx) => {
        const [rec, h] = await ctx.getRecordHandle(tx);
        if (!rec) {
          return;
        }
        switch (rec.status) {
          case PeerPushCreditStatus.PendingMergeKycRequired:
          case PeerPushCreditStatus.PendingMerge: {
            if (purseExpired) {
              rec.status = PeerPushCreditStatus.Expired;
            } else {
              rec.status = PeerPushCreditStatus.Failed;
              rec.failReason = reason;
            }
            break;
          }
          default:
            return;
        }
        await h.update(rec, "merge-gone");
      });
      return TaskRunResult.finished();
    }
    case HttpStatusCode.Forbidden:
    case HttpStatusCode.NotFound:
      await ctx.failTransaction(peerInc.status, mergeResp.detail);
      return TaskRunResult.finished();
    default:
      assertUnreachable(mergeResp);
  }

  return continuePeerPushCreditAfterMerge(
    wex,
    peerInc,
    amount,
    mergeReserveInfo,
  );
}

async function processPendingWithdrawing(
  wex: WalletExecutionContext,
  peerInc: WalletPeerPushCredit,
): Promise<TaskRunResult> {
  if (!peerInc.withdrawalGroupId) {
    throw Error("invalid db state (withdrawing, but no withdrawal group ID");
  }
  await waitWithdrawalFinal(wex, peerInc.withdrawalGroupId);
  const ctx = new PeerPushCreditTransactionContext(
    wex,
    peerInc.peerPushCreditId,
  );
  const wgId = peerInc.withdrawalGroupId;
  return await wex.runWalletDbTx(async (tx) => {
    const [ppi, h] = await ctx.getRecordHandle(tx);
    if (!ppi) {
      return TaskRunResult.finished();
    }
    if (ppi.status !== PeerPushCreditStatus.PendingWithdrawing) {
      return TaskRunResult.finished();
    }
    const wg = await tx.getWithdrawalGroup(wgId);
    if (!wg) {
      ppi.status = PeerPushCreditStatus.Failed;
      await h.update(ppi, "withdrawal-missing");
      return TaskRunResult.finished();
    }
    switch (wg.status) {
      case WithdrawalGroupStatus.AbortedBank:
      case WithdrawalGroupStatus.AbortedExchange:
      case WithdrawalGroupStatus.AbortedOtherWallet:
      case WithdrawalGroupStatus.AbortedUserRefused:
      case WithdrawalGroupStatus.AbortingBank:
      case WithdrawalGroupStatus.FailedAbortingBank:
      case WithdrawalGroupStatus.FailedBankAborted:
      case WithdrawalGroupStatus.FailedKycHardLimit:
      case WithdrawalGroupStatus.FailedKycHardLimitRecovery:
        if (
          wg.status === WithdrawalGroupStatus.FailedKycHardLimit ||
          wg.status === WithdrawalGroupStatus.FailedKycHardLimitRecovery
        ) {
          ppi.status = PeerPushCreditStatus.FailedKycHardLimit;
          ppi.failReason = wg.failReason;
        } else {
          ppi.status = PeerPushCreditStatus.Failed;
        }
        await h.update(
          ppi,
          ppi.status === PeerPushCreditStatus.FailedKycHardLimit
            ? "withdrawal-kyc-hard-limit"
            : "withdrawal-failed",
        );
        return TaskRunResult.finished();
      case WithdrawalGroupStatus.Done:
        ppi.status = PeerPushCreditStatus.Done;
        await h.update(ppi, "withdrawal-done");
        return TaskRunResult.finished();
      case WithdrawalGroupStatus.PendingQueryingStatus:
      case WithdrawalGroupStatus.PendingReady:
      case WithdrawalGroupStatus.PendingRedenominate:
      case WithdrawalGroupStatus.PendingRegisteringBank:
      case WithdrawalGroupStatus.PendingWaitConfirmBank:
      case WithdrawalGroupStatus.SuspendedAbortingBank:
      case WithdrawalGroupStatus.SuspendedBalanceKyc:
      case WithdrawalGroupStatus.SuspendedBalanceKycInit:
      case WithdrawalGroupStatus.SuspendedKyc:
      case WithdrawalGroupStatus.SuspendedQueryingStatus:
      case WithdrawalGroupStatus.SuspendedReady:
      case WithdrawalGroupStatus.SuspendedRedenominate:
      case WithdrawalGroupStatus.SuspendedRegisteringBank:
      case WithdrawalGroupStatus.SuspendedWaitConfirmBank:
      case WithdrawalGroupStatus.FinalizingKycHardLimit:
        return TaskRunResult.backoff();
      case WithdrawalGroupStatus.PendingBalanceKyc:
      case WithdrawalGroupStatus.PendingBalanceKycInit:
      case WithdrawalGroupStatus.PendingKyc:
      case WithdrawalGroupStatus.DialogProposed:
        throw Error(
          "unexpected status of withdrawal transaction for peer-push-credit",
        );
      default:
        assertUnreachable(wg.status);
    }
  });
}

async function processPeerPushDebitDialogProposed(
  wex: WalletExecutionContext,
  pullIni: WalletPeerPushCredit,
): Promise<TaskRunResult> {
  const ctx = new PeerPushCreditTransactionContext(
    wex,
    pullIni.peerPushCreditId,
  );
  const exchangeClient = walletExchangeClient(pullIni.exchangeBaseUrl, wex);
  const resp = await exchangeClient.getPurseStatusAtMerge(
    pullIni.pursePub,
    true,
  );

  switch (resp.case) {
    case "ok":
      break;
    case HttpStatusCode.Gone:
      // The purse is gone: either it lapsed or the sender called the
      // payment off.
      await ctx.wex.runWalletDbTx(async (tx) => {
        const [rec, h] = await ctx.getRecordHandle(tx);
        if (!rec) {
          return;
        }
        switch (rec.status) {
          case PeerPushCreditStatus.DialogProposed: {
            const ct = await tx.getContractTerms(rec.contractTermsHash);
            checkDbInvariant(!!ct, "contract terms for P2P payment not found");
            if (isPurseGoneByExpiration(ct.contractTermsRaw.purse_expiration)) {
              rec.status = PeerPushCreditStatus.Expired;
            } else {
              rec.status = PeerPushCreditStatus.Aborted;
              rec.abortReason = makeErrorDetail(
                TalerErrorCode.WALLET_PEER_PUSH_CREDIT_PURSE_GONE,
                { purseExpired: false },
                "the sender aborted this payment",
              );
            }
            break;
          }
          default:
            return;
        }
        await h.update(rec, "purse-gone");
      });
      return TaskRunResult.finished();
    case HttpStatusCode.NotFound:
      await ctx.failTransaction(pullIni.status, resp.detail);
      return TaskRunResult.finished();
    default:
      assertUnreachable(resp);
  }

  await requireValidExchangePurseStatus(
    wex,
    pullIni.exchangeBaseUrl,
    resp.body,
  );

  if (isPurseMerged(resp.body)) {
    logger.info("purse completed by another wallet");
    await ctx.wex.runWalletDbTx(async (tx) => {
      const [rec, h] = await ctx.getRecordHandle(tx);
      if (!rec) {
        return;
      }
      switch (rec.status) {
        case PeerPushCreditStatus.DialogProposed: {
          rec.status = PeerPushCreditStatus.Aborted;
          break;
        }
        default:
          return;
      }
      await h.update(rec, "purse-merged-other");
    });
    return TaskRunResult.finished();
  }

  return TaskRunResult.longpollReturnedPending();
}

export async function processPeerPushCredit(
  wex: WalletExecutionContext,
  peerPushCreditId: string,
): Promise<TaskRunResult> {
  const ctx = new PeerPushCreditTransactionContext(wex, peerPushCreditId);

  const { peerInc, contractTerms } = await wex.runWalletDbTx(async (tx) => {
    const rec = await tx.getPeerPushCredit(peerPushCreditId);
    let contractTerms = null;
    if (rec != null) {
      const contract = await tx.getContractTerms(rec.contractTermsHash);
      if (contract != null) {
        contractTerms = contract.contractTermsRaw;
      }
    }
    return {
      peerInc: rec,
      contractTerms,
    };
  });

  if (!peerInc) {
    throw Error(
      `can't accept unknown incoming p2p push payment (${peerPushCreditId})`,
    );
  }

  logger.info(
    `processing peerPushCredit in state ${peerInc.status.toString(16)}`,
  );

  checkDbInvariant(
    !!contractTerms,
    `not contract terms for peer push ${peerPushCreditId}`,
  );

  switch (peerInc.status) {
    case PeerPushCreditStatus.Done:
    case PeerPushCreditStatus.Aborted:
    case PeerPushCreditStatus.Failed:
    case PeerPushCreditStatus.FailedKycHardLimit:
    case PeerPushCreditStatus.Expired:
    case PeerPushCreditStatus.SuspendedMerge:
    case PeerPushCreditStatus.SuspendedMergeKycRequired:
    case PeerPushCreditStatus.SuspendedWithdrawing:
    case PeerPushCreditStatus.SuspendedBalanceKycRequired:
    case PeerPushCreditStatus.SuspendedBalanceKycInit:
      return TaskRunResult.finished();
    default:
      break;
  }

  const purseExpiration = contractTerms.purse_expiration;
  if (
    peerInc.status === PeerPushCreditStatus.DialogProposed &&
    isPurseGoneByExpiration(purseExpiration)
  ) {
    await wex.runWalletDbTx(async (tx) => {
      const [rec, h] = await ctx.getRecordHandle(tx);
      if (rec?.status !== PeerPushCreditStatus.DialogProposed) {
        return;
      }
      rec.status = PeerPushCreditStatus.Expired;
      await h.update(rec, "dialog-expired");
    });
    return TaskRunResult.finished();
  }

  if (!wex.ws.networkAvailable) {
    if (
      peerInc.status === PeerPushCreditStatus.DialogProposed ||
      isActivePreMergePeerPushCreditStatus(peerInc.status)
    ) {
      if (!isPurseGoneByExpiration(purseExpiration)) {
        return TaskRunResult.runAgainAt(
          AbsoluteTime.fromProtocolTimestamp(purseExpiration),
        );
      }
    }
    return TaskRunResult.networkRequired();
  }

  if (
    isActivePreMergePeerPushCreditStatus(peerInc.status) &&
    isPurseGoneByExpiration(purseExpiration)
  ) {
    return reconcileExpiredPeerPushCredit(wex, peerInc, contractTerms);
  }

  switch (peerInc.status) {
    case PeerPushCreditStatus.DialogProposed:
      return processPeerPushDebitDialogProposed(wex, peerInc);
    case PeerPushCreditStatus.PendingMergeKycRequired:
      if (!peerInc.kycPaytoHash) {
        throw Error("invalid state, kycPaytoHash required");
      }
      return processPeerPushDebitMergeKyc(wex, peerInc, contractTerms);
    case PeerPushCreditStatus.FinalizingKycHardLimit:
      return processPeerPushCreditKycHardLimitRecovery(wex, peerInc);
    case PeerPushCreditStatus.PendingMerge:
      return processPendingMerge(wex, peerInc, contractTerms);
    case PeerPushCreditStatus.PendingWithdrawing:
      return processPendingWithdrawing(wex, peerInc);
    case PeerPushCreditStatus.PendingBalanceKycInit:
    case PeerPushCreditStatus.PendingBalanceKycRequired:
      return processPeerPushCreditBalanceKyc(ctx, peerInc);
    default:
      return TaskRunResult.finished();
  }
}

async function processPeerPushCreditBalanceKyc(
  ctx: PeerPushCreditTransactionContext,
  peerInc: WalletPeerPushCredit,
): Promise<TaskRunResult> {
  const exchangeBaseUrl = peerInc.exchangeBaseUrl;
  const amount = peerInc.estimatedAmountEffective;

  const ret = await genericWaitForStateVal(ctx.wex, {
    async checkState(): Promise<BalanceThresholdCheckResult | undefined> {
      const checkRes = await checkIncomingAmountLegalUnderKycBalanceThreshold(
        ctx.wex,
        exchangeBaseUrl,
        amount,
      );
      logger.info(
        `balance check result for ${exchangeBaseUrl} +${amount}: ${j2s(
          checkRes,
        )}`,
      );
      if (checkRes.result === "ok") {
        return checkRes;
      }
      if (
        peerInc.status === PeerPushCreditStatus.PendingBalanceKycInit &&
        checkRes.walletKycStatus === ExchangeWalletKycStatus.Legi
      ) {
        return checkRes;
      }
      await handleStartExchangeWalletKyc(ctx.wex, {
        amount: checkRes.nextThreshold,
        exchangeBaseUrl,
      });
      return undefined;
    },
    filterNotification(notif) {
      return (
        (notif.type === NotificationType.ExchangeStateTransition &&
          notif.exchangeBaseUrl === exchangeBaseUrl) ||
        notif.type === NotificationType.BalanceChange
      );
    },
  });

  if (ret.result === "ok") {
    await ctx.wex.runWalletDbTx(async (tx) => {
      const [rec, h] = await ctx.getRecordHandle(tx);
      if (!rec) {
        return;
      }
      switch (rec.status) {
        // The balance increase is legal, so no wallet KYC is needed and
        // the initial state is left behind together with the required one.
        case PeerPushCreditStatus.PendingBalanceKycInit:
        case PeerPushCreditStatus.PendingBalanceKycRequired: {
          rec.status = PeerPushCreditStatus.PendingMerge;
          await h.update(rec, "balance-kyc-ok");
          break;
        }
      }
    });
    return TaskRunResult.progress();
  } else if (
    peerInc.status === PeerPushCreditStatus.PendingBalanceKycInit &&
    ret.walletKycStatus === ExchangeWalletKycStatus.Legi
  ) {
    await ctx.wex.runWalletDbTx(async (tx) => {
      const [rec, h] = await ctx.getRecordHandle(tx);
      if (!rec) {
        return;
      }
      switch (rec.status) {
        case PeerPushCreditStatus.PendingBalanceKycInit: {
          rec.status = PeerPushCreditStatus.PendingBalanceKycRequired;
          rec.kycAccessToken = ret.walletKycAccessToken;
          await h.update(rec, "balance-kyc-required");
        }
      }
    });
    return TaskRunResult.progress();
  } else {
    throw Error("not reached");
  }
}

export async function confirmPeerPushCredit(
  wex: WalletExecutionContext,
  req: ConfirmPeerPushCreditRequest,
): Promise<AcceptPeerPushPaymentResponse> {
  return runWithMaybeProgressContext(
    wex,
    "confirmPeerPushCredit",
    req.progressToken,
    () => internalConfirmPeerPushCredit(wex, req),
  );
}

async function internalConfirmPeerPushCredit(
  wex: WalletExecutionContext,
  req: ConfirmPeerPushCreditRequest,
): Promise<AcceptPeerPushPaymentResponse> {
  const parsedTx = parseTransactionIdentifier(req.transactionId);
  if (!parsedTx) {
    throw makeInvalidTransactionIdError(
      req.transactionId,
      TransactionType.PeerPushCredit,
    );
  }
  if (parsedTx.tag !== TransactionType.PeerPushCredit) {
    throw makeInvalidTransactionIdError(
      req.transactionId,
      TransactionType.PeerPushCredit,
    );
  }
  const ctx = new PeerPushCreditTransactionContext(
    wex,
    parsedTx.peerPushCreditId,
  );

  logger.trace(`confirming peer-push-credit ${ctx.peerPushCreditId}`);

  const res = await wex.runWalletDbTx(async (tx) => {
    const rec = await tx.getPeerPushCredit(ctx.peerPushCreditId);
    if (!rec) {
      return;
    }
    const ct = await tx.getContractTerms(rec.contractTermsHash);
    if (!ct) {
      return undefined;
    }
    return {
      peerInc: rec,
      contractTerms: ct.contractTermsRaw as PeerContractTerms,
    };
  });

  if (!res) {
    throw makeTransactionNotFoundError(req.transactionId);
  }

  const peerInc = res.peerInc;

  if (peerInc.status !== PeerPushCreditStatus.DialogProposed) {
    return { transactionId: ctx.transactionId };
  }
  if (isPurseGoneByExpiration(res.contractTerms.purse_expiration)) {
    await wex.runWalletDbTx(async (tx) => {
      const [rec, h] = await ctx.getRecordHandle(tx);
      if (rec?.status !== PeerPushCreditStatus.DialogProposed) {
        return;
      }
      rec.status = PeerPushCreditStatus.Expired;
      await h.update(rec, "confirm-expired");
    });
    return { transactionId: ctx.transactionId };
  }

  const exchange = await fetchFreshExchangeWithRetryNow(
    wex,
    peerInc.exchangeBaseUrl,
  );
  requireExchangeKeysConfirmedOrThrow(wex, exchange);
  requireExchangeTosAcceptedOrThrow(wex, exchange);

  if (checkPeerCreditHardLimitExceeded(exchange, res.contractTerms.amount)) {
    throw TalerError.fromDetail(
      TalerErrorCode.WALLET_KYC_LIMIT_EXCEEDED,
      {
        exchangeBaseUrl: peerInc.exchangeBaseUrl,
        requestedAmount: res.contractTerms.amount,
      },
      "accepting this payment would exceed a hard limit of the exchange",
    );
  }

  await wex.runWalletDbTx(async (tx) => {
    const [rec, h] = await ctx.getRecordHandle(tx);
    if (!rec) {
      return;
    }
    switch (rec.status) {
      case PeerPushCreditStatus.DialogProposed: {
        if (isPurseGoneByExpiration(res.contractTerms.purse_expiration)) {
          rec.status = PeerPushCreditStatus.Expired;
          await h.update(rec, "confirm-expired");
        } else {
          rec.status = PeerPushCreditStatus.PendingMerge;
          await h.update(rec, "confirm");
        }
        break;
      }
    }
  });

  await wex.taskScheduler.resetTask(ctx.taskId);

  return {
    transactionId: ctx.transactionId,
  };
}

export function computePeerPushCreditTransactionState(
  pushCreditRecord: WalletPeerPushCredit,
): TransactionState {
  switch (pushCreditRecord.status) {
    case PeerPushCreditStatus.DialogProposed:
      return {
        major: TransactionMajorState.Dialog,
        minor: TransactionMinorState.Proposed,
      };
    case PeerPushCreditStatus.PendingMerge:
      return {
        major: TransactionMajorState.Pending,
        minor: TransactionMinorState.Merge,
        working: true,
      };
    case PeerPushCreditStatus.Done:
      return {
        major: TransactionMajorState.Done,
      };
    case PeerPushCreditStatus.FinalizingKycHardLimit:
      return {
        major: TransactionMajorState.Finalizing,
        minor: TransactionMinorState.KycHardLimit,
        working: true,
      };
    case PeerPushCreditStatus.FailedKycHardLimit:
      return {
        major: TransactionMajorState.Failed,
        minor: TransactionMinorState.KycHardLimit,
      };
    case PeerPushCreditStatus.PendingMergeKycRequired:
      if (pushCreditRecord.kycAccessToken) {
        return {
          major: TransactionMajorState.Pending,
          minor: TransactionMinorState.KycRequired,
        };
      } else {
        return {
          major: TransactionMajorState.Pending,
          minor: TransactionMinorState.KycInit,
          working: true,
        };
      }
    case PeerPushCreditStatus.SuspendedMergeKycRequired:
      if (pushCreditRecord.kycAccessToken) {
        return {
          major: TransactionMajorState.Suspended,
          minor: TransactionMinorState.KycRequired,
        };
      } else {
        return {
          major: TransactionMajorState.Suspended,
          minor: TransactionMinorState.KycInit,
        };
      }
    case PeerPushCreditStatus.PendingWithdrawing:
      return {
        major: TransactionMajorState.Pending,
        minor: TransactionMinorState.Withdraw,
        working: true,
      };
    case PeerPushCreditStatus.SuspendedMerge:
      return {
        major: TransactionMajorState.Suspended,
        minor: TransactionMinorState.Merge,
      };
    case PeerPushCreditStatus.SuspendedWithdrawing:
      return {
        major: TransactionMajorState.Suspended,
        minor: TransactionMinorState.Withdraw,
      };
    case PeerPushCreditStatus.Aborted:
      return {
        major: TransactionMajorState.Aborted,
      };
    case PeerPushCreditStatus.Failed:
      return {
        major: TransactionMajorState.Failed,
      };
    case PeerPushCreditStatus.PendingBalanceKycRequired:
      return {
        major: TransactionMajorState.Pending,
        minor: TransactionMinorState.BalanceKycRequired,
      };
    case PeerPushCreditStatus.SuspendedBalanceKycRequired:
      return {
        major: TransactionMajorState.Suspended,
        minor: TransactionMinorState.BalanceKycRequired,
      };
    case PeerPushCreditStatus.PendingBalanceKycInit:
      return {
        major: TransactionMajorState.Pending,
        minor: TransactionMinorState.KycInit,
        working: true,
      };
    case PeerPushCreditStatus.SuspendedBalanceKycInit:
      return {
        major: TransactionMajorState.Suspended,
        minor: TransactionMinorState.KycInit,
      };
    case PeerPushCreditStatus.Expired:
      return {
        major: TransactionMajorState.Expired,
      };
    default:
      assertUnreachable(pushCreditRecord.status);
  }
}

export function computePeerPushCreditTransactionActions(
  pushCreditRecord: WalletPeerPushCredit,
): TransactionAction[] {
  switch (pushCreditRecord.status) {
    case PeerPushCreditStatus.DialogProposed:
      return [TransactionAction.Retry, TransactionAction.Delete];
    case PeerPushCreditStatus.PendingMerge:
      return [
        TransactionAction.Retry,
        TransactionAction.Abort,
        TransactionAction.Suspend,
      ];
    case PeerPushCreditStatus.Done:
      return [TransactionAction.Delete];
    case PeerPushCreditStatus.FinalizingKycHardLimit:
      return [TransactionAction.Retry];
    case PeerPushCreditStatus.FailedKycHardLimit:
      return [TransactionAction.Delete];
    case PeerPushCreditStatus.PendingMergeKycRequired:
      return [
        TransactionAction.Retry,
        TransactionAction.Abort,
        TransactionAction.Suspend,
      ];
    case PeerPushCreditStatus.PendingWithdrawing:
      return [
        TransactionAction.Retry,
        TransactionAction.Suspend,
        TransactionAction.Fail,
      ];
    case PeerPushCreditStatus.SuspendedMerge:
      return [TransactionAction.Resume, TransactionAction.Abort];
    case PeerPushCreditStatus.SuspendedMergeKycRequired:
      return [TransactionAction.Resume, TransactionAction.Abort];
    case PeerPushCreditStatus.SuspendedWithdrawing:
      return [TransactionAction.Resume, TransactionAction.Fail];
    case PeerPushCreditStatus.PendingBalanceKycRequired:
      return [TransactionAction.Suspend, TransactionAction.Abort];
    case PeerPushCreditStatus.SuspendedBalanceKycRequired:
      return [TransactionAction.Resume, TransactionAction.Abort];
    case PeerPushCreditStatus.PendingBalanceKycInit:
      return [TransactionAction.Suspend, TransactionAction.Abort];
    case PeerPushCreditStatus.SuspendedBalanceKycInit:
      return [TransactionAction.Resume, TransactionAction.Abort];
    case PeerPushCreditStatus.Aborted:
      return [TransactionAction.Delete];
    case PeerPushCreditStatus.Failed:
      return [TransactionAction.Delete];
    case PeerPushCreditStatus.Expired:
      return [TransactionAction.Delete];
    default:
      assertUnreachable(pushCreditRecord.status);
  }
}
