/**
 * Imports.
 */
import {
  processExit,
  processArgv,
  readlinePrompt,
  pathBasename,
  terminalWidth,
} from "#compat-impl";
import { AmountString } from "./types-taler-common.js";

export namespace clk {
  class Converter<T> {}

  export const INT = new Converter<number>();
  export const STRING: Converter<string> = new Converter<string>();
  export const AMOUNT: Converter<AmountString> = new Converter<AmountString>();

  export interface OptionArgs<T> {
    help?: string;
    default?: T;
    onPresentHandler?: (v: T) => void;
    mark?: CommandMark;
  }

  export interface ArgumentArgs<T> {
    metavar?: string;
    help?: string;
    default?: T;
  }

  /**
   * Status of a command or of an option, for programs that don't want to
   * offer all of them on equal terms.
   *
   * What a mark means is up to the program's CommandMarkPolicy; clk only
   * carries it, decides what to list, and asks before running.
   */
  export type CommandMark = "experimental" | "legacy" | "hidden";

  /**
   * Marks in the order of how much they restrict a command, so that the
   * strictest one along a command's path is the one that applies.
   */
  const MARK_STRENGTH: CommandMark[] = ["hidden", "legacy", "experimental"];

  /**
   * Where a command group remembers which of its options were given on the
   * command line rather than defaulted.  A symbol, so that it doesn't
   * collide with an option name and stays out of the parsed arguments as
   * far as every ordinary consumer is concerned.
   */
  const FOUND_OPTIONS = Symbol("clk-found-options");

  export interface CommandMarkPolicy {
    /**
     * Is a command or option carrying this mark listed in the help?
     */
    isListed(mark: CommandMark): boolean;

    /**
     * Called before a command runs: once with the strictest mark on the
     * command's path and the full command name, and once per marked option
     * that was actually given, with that option's flag.  May warn, or not
     * return at all.
     */
    check(mark: CommandMark, what: string): void;
  }

  export interface SubcommandArgs {
    help?: string;
    mark?: CommandMark;
  }

  export interface FlagArgs {
    help?: string;
  }

  export interface ProgramArgs {
    help?: string;
    /**
     * How to treat marked commands.  Without one, marks are inert and
     * every command is listed and runnable.
     */
    markPolicy?: CommandMarkPolicy;
  }

  interface ArgumentDef {
    name: string;
    conv: Converter<any>;
    args: ArgumentArgs<any>;
    required: boolean;
  }

  interface SubcommandDef {
    commandGroup: CommandGroup<any, any>;
    name: string;
    args: SubcommandArgs;
  }

  type ActionFn<TG> = (x: TG) => void;

  type SubRecord<S extends keyof any, N extends keyof any, V> = {
    [Y in S]: { [X in N]: V };
  };

  interface OptionDef {
    name: string;
    flagspec: string[];
    /**
     * Converter, only present for options, not for flags.
     */
    conv?: Converter<any>;
    args: OptionArgs<any>;
    isFlag: boolean;
    required: boolean;
  }

  function splitOpt(opt: string): { key: string; value?: string } {
    const idx = opt.indexOf("=");
    if (idx == -1) {
      return { key: opt };
    }
    return { key: opt.substring(0, idx), value: opt.substring(idx + 1) };
  }

  /**
   * Width to wrap help output at.
   *
   * Capped, because a description running the full width of a very wide
   * terminal is hard to read even though it fits, and floored so that the
   * indented description column keeps a usable amount of room.
   */
  function helpWidth(): number {
    const w = terminalWidth();
    if (w == null || w < 40) {
      return 80;
    }
    return Math.min(w, 100);
  }

  /**
   * Break a text into lines that fit into `width` when indented by
   * `indent`.  A word that doesn't fit on its own is left to overflow
   * rather than broken, so that URIs and flag names stay selectable.
   */
  function wrapText(text: string, width: number, indent: number): string[] {
    const lines: string[] = [];
    let current = "";
    for (const word of text.split(/\s+/).filter((w) => w !== "")) {
      if (current === "") {
        current = word;
      } else if (indent + current.length + 1 + word.length <= width) {
        current += " " + word;
      } else {
        lines.push(current);
        current = word;
      }
    }
    if (current !== "") {
      lines.push(current);
    }
    return lines;
  }

  function formatListing(key: string, value?: string): string {
    const res = "  " + key;
    if (!value) {
      return res;
    }
    // A key that reaches into the description column gets a line of its own.
    const ownLine = res.length >= 25;
    const indent = ownLine ? 4 : 25;
    const pad = " ".repeat(indent);
    // Newlines in command help deliberately create a new help line.  This is
    // useful for a parent command that needs to expose its most important
    // subcommands without turning the whole listing into a paragraph.
    const body = value
      .split("\n")
      .flatMap((line) => wrapText(line, helpWidth(), indent))
      .join("\n" + pad);
    if (ownLine) {
      return res + "\n" + pad + body;
    }
    return res.padEnd(24) + " " + body;
  }

  /**
   * Abbreviations that end in a period without ending a sentence.
   */
  const ABBREVIATIONS = ["e.g", "i.e", "cf", "etc", "resp", "vs", "approx"];

  /**
   * The first sentence of a help text.
   *
   * A command's one-line entry in its parent's help only gets this much;
   * the rest is what the command's own '--help' is for.
   */
  function firstSentence(text: string): string {
    for (let i = 0; i < text.length; i++) {
      const c = text[i];
      if (c !== "." && c !== "!" && c !== "?") {
        continue;
      }
      // A sentence ends where whitespace or the end of the text follows,
      // so that "3.5" or "taler://" don't count as one.
      if (i + 1 < text.length && !/\s/.test(text[i + 1])) {
        continue;
      }
      const before = text.substring(0, i).toLowerCase();
      if (ABBREVIATIONS.some((a) => before.endsWith(a))) {
        continue;
      }
      return text.substring(0, i + 1);
    }
    return text;
  }

  function convertArg(
    name: string,
    conv: Converter<any> | undefined,
    value: string,
  ): any {
    if (conv === INT) {
      const n = Number.parseInt(value, 10);
      if (Number.isNaN(n)) {
        throw Error(`invalid integer value for '${name}'`);
      }
      return n;
    }
    if (conv == null || conv === STRING || conv === AMOUNT) {
      return value;
    }
    throw Error("unknown converter");
  }

  export class CommandGroup<GN extends keyof any, TG> {
    private shortOptions: { [name: string]: OptionDef } = {};
    private longOptions: { [name: string]: OptionDef } = {};
    private subcommandMap: { [name: string]: SubcommandDef } = {};
    private subcommands: SubcommandDef[] = [];
    private options: OptionDef[] = [];
    private arguments: ArgumentDef[] = [];

    private myAction?: ActionFn<TG>;

    constructor(
      private argKey: string,
      private name: string | null,
      private scArgs: SubcommandArgs,
      /**
       * Inherited from the program, so that every command can consult it
       * without walking back up the tree.
       */
      private markPolicy?: CommandMarkPolicy,
      private parent?: CommandGroup<any, any>,
    ) {}

    /**
     * The mark of this command, if it has one.
     */
    getMark(): CommandMark | undefined {
      return this.scArgs.mark;
    }

    action(f: ActionFn<TG>): void {
      if (this.myAction) {
        throw Error("only one action supported per command");
      }
      this.myAction = f;
    }

    requiredOption<N extends keyof any, V>(
      name: N,
      flagspec: string[],
      conv: Converter<V>,
      args: OptionArgs<V> = {},
    ): CommandGroup<GN, TG & SubRecord<GN, N, V>> {
      const def: OptionDef = {
        args: args,
        conv: conv,
        flagspec: flagspec,
        isFlag: false,
        required: true,
        name: name as string,
      };
      this.options.push(def);
      for (const flag of flagspec) {
        if (flag.startsWith("--")) {
          const flagname = flag.substring(2);
          this.longOptions[flagname] = def;
        } else if (flag.startsWith("-")) {
          const flagname = flag.substring(1);
          this.shortOptions[flagname] = def;
        } else {
          throw Error("option must start with '-' or '--'");
        }
      }
      return this as any;
    }

    maybeOption<N extends keyof any, V>(
      name: N,
      flagspec: string[],
      conv: Converter<V>,
      args: OptionArgs<V> = {},
    ): CommandGroup<GN, TG & SubRecord<GN, N, V | undefined>> {
      const def: OptionDef = {
        args: args,
        conv: conv,
        flagspec: flagspec,
        isFlag: false,
        required: false,
        name: name as string,
      };
      this.options.push(def);
      for (const flag of flagspec) {
        if (flag.startsWith("--")) {
          const flagname = flag.substring(2);
          this.longOptions[flagname] = def;
        } else if (flag.startsWith("-")) {
          const flagname = flag.substring(1);
          this.shortOptions[flagname] = def;
        } else {
          throw Error("option must start with '-' or '--'");
        }
      }
      return this as any;
    }

    requiredArgument<N extends keyof any, V>(
      name: N,
      conv: Converter<V>,
      args: ArgumentArgs<V> = {},
    ): CommandGroup<GN, TG & SubRecord<GN, N, V>> {
      const argDef: ArgumentDef = {
        args: args,
        conv: conv,
        name: name as string,
        required: true,
      };
      this.arguments.push(argDef);
      return this as any;
    }

    maybeArgument<N extends keyof any, V>(
      name: N,
      conv: Converter<V>,
      args: ArgumentArgs<V> = {},
    ): CommandGroup<GN, TG & SubRecord<GN, N, V | undefined>> {
      const argDef: ArgumentDef = {
        args: args,
        conv: conv,
        name: name as string,
        required: false,
      };
      this.arguments.push(argDef);
      return this as any;
    }

    flag<N extends string, V>(
      name: N,
      flagspec: string[],
      args: OptionArgs<V> = {},
    ): CommandGroup<GN, TG & SubRecord<GN, N, boolean>> {
      const def: OptionDef = {
        args: args,
        flagspec: flagspec,
        isFlag: true,
        required: false,
        name: name as string,
      };
      this.options.push(def);
      for (const flag of flagspec) {
        if (flag.startsWith("--")) {
          const flagname = flag.substring(2);
          this.longOptions[flagname] = def;
        } else if (flag.startsWith("-")) {
          const flagname = flag.substring(1);
          this.shortOptions[flagname] = def;
        } else {
          throw Error("option must start with '-' or '--'");
        }
      }
      return this as any;
    }

    subcommand<GN extends keyof any>(
      argKey: GN,
      name: string,
      args: SubcommandArgs = {},
    ): CommandGroup<GN, TG> {
      // The policy comes from the program, so it has to be handed down.
      const cg = new CommandGroup<GN, {}>(
        argKey as string,
        name,
        args,
        this.markPolicy,
        this,
      );
      const def: SubcommandDef = {
        commandGroup: cg,
        name: name as string,
        args: args,
      };
      cg.flag("help", ["-h", "--help"], {
        help: "Show this message and exit.",
      });
      this.subcommandMap[name as string] = def;
      this.subcommands.push(def);
      this.subcommands = this.subcommands.sort((x1, x2) => {
        const a = x1.name;
        const b = x2.name;
        if (a === b) {
          return 0;
        } else if (a < b) {
          return -1;
        } else {
          return 1;
        }
      });
      return cg as any;
    }

    /**
     * Make this command available under another name without listing that
     * name in the parent's help.  The alias intentionally shares all options
     * and nested subcommands with the canonical command.
     */
    alias(name: string): this {
      if (this.parent == null || this.name == null) {
        throw Error("only a subcommand can have an alias");
      }
      if (this.parent.subcommandMap[name] != null) {
        throw Error(`command alias '${name}' is already in use`);
      }
      const def = this.parent.subcommandMap[this.name];
      if (def == null) {
        throw Error(`command '${this.name}' is not registered with its parent`);
      }
      this.parent.subcommandMap[name] = def;
      return this;
    }

    /**
     * Ask the policy about the strictest mark on the way to this command.
     *
     * A group's mark covers everything below it, so that marking a group
     * is enough and its subcommands don't have to repeat it.
     */
    /**
     * Does something carrying this mark show up in the help?  Without a
     * policy nothing is held back.
     */
    private isListed(args: { mark?: CommandMark }): boolean {
      return (
        args.mark == null ||
        this.markPolicy == null ||
        this.markPolicy.isListed(args.mark)
      );
    }

    /**
     * Ask the policy about every marked option that was actually given.
     *
     * Options are reported one by one under their own flag: unlike a
     * command, several of them can apply at once and lumping them together
     * would hide which one the policy is talking about.
     */
    private checkOptionMarkPolicy(myArgs: any): void {
      const policy = this.markPolicy;
      if (policy == null) {
        return;
      }
      const found: { [name: string]: boolean } = myArgs[FOUND_OPTIONS] ?? {};
      for (const option of this.options) {
        const mark = option.args.mark;
        if (mark == null || !found[option.name]) {
          continue;
        }
        // The long flag is what documentation and scripts use.
        const flag =
          option.flagspec.find((f) => f.startsWith("--")) ?? option.flagspec[0];
        policy.check(mark, flag);
      }
    }

    private checkMarkPolicy(
      parents: CommandGroup<any, any>[],
      progname: string,
    ): void {
      const policy = this.markPolicy;
      if (policy == null) {
        return;
      }
      let strictest: CommandMark | undefined;
      for (const cg of [...parents, this]) {
        const mark = cg.scArgs.mark;
        if (mark == null) {
          continue;
        }
        if (
          strictest == null ||
          MARK_STRENGTH.indexOf(mark) > MARK_STRENGTH.indexOf(strictest)
        ) {
          strictest = mark;
        }
      }
      if (strictest == null) {
        return;
      }
      // Name the command the way the user typed it, minus the program
      // name, which the root carries as a null name.
      const commandPath = [...parents, this]
        .map((cg) => cg.name)
        .filter((n) => n != null)
        .join(" ");
      policy.check(strictest, commandPath === "" ? progname : commandPath);
    }

    printHelp(progName: string, parents: CommandGroup<any, any>[]): void {
      let usageSpec = "";
      for (const p of parents) {
        usageSpec += (p.name ?? progName) + " ";
        if (p.arguments.length >= 1) {
          usageSpec += "<ARGS...> ";
        }
      }
      usageSpec += (this.name ?? progName) + " ";
      for (const a of this.arguments) {
        const argName = a.args.metavar ?? a.name;
        usageSpec += `<${argName}> `;
      }
      if (this.subcommands.length != 0) {
        usageSpec += "COMMAND ";
      }
      usageSpec = usageSpec.trimRight();
      console.log(`Usage: ${usageSpec}`);
      const ownMark = this.scArgs.mark;
      if (this.scArgs.help || ownMark) {
        const description = [
          ownMark ? `[${ownMark}]` : undefined,
          this.scArgs.help,
        ]
          .filter((x) => x)
          .join(" ");
        console.log();
        console.log(wrapText(description, helpWidth(), 0).join("\n"));
      }
      // Only when something has been documented: without help texts this
      // would just repeat the usage line.
      if (this.arguments.some((a) => a.args.help)) {
        console.log();
        console.log("Arguments:");
        for (const arg of this.arguments) {
          const argName = arg.args.metavar ?? arg.name;
          console.log(formatListing(argName, arg.args.help));
        }
      }
      // Same rule as for subcommands: a mark decides whether the option
      // shows up, not whether it works.
      const listedOptions = this.options.filter((opt) =>
        this.isListed(opt.args),
      );
      if (listedOptions.length != 0) {
        console.log();
        console.log("Options:");
        for (const opt of listedOptions) {
          let optSpec = opt.flagspec.join(", ");
          if (!opt.isFlag) {
            optSpec = optSpec + "=VALUE";
          }
          const help = [
            opt.args.mark ? `[${opt.args.mark}]` : undefined,
            opt.args.help,
          ]
            .filter((x) => x)
            .join(" ");
          console.log(formatListing(optSpec, help ? help : undefined));
        }
      }

      // A mark only decides whether the command shows up here; it says
      // nothing about the subcommands underneath it.
      const listed = this.subcommands.filter((sc) => this.isListed(sc.args));
      if (listed.length != 0) {
        console.log();
        console.log("Commands:");
        for (const subcmd of listed) {
          const help = [
            subcmd.args.mark ? `[${subcmd.args.mark}]` : undefined,
            subcmd.args.help ? firstSentence(subcmd.args.help) : undefined,
          ]
            .filter((x) => x)
            .join(" ");
          console.log(formatListing(subcmd.name, help));
        }
      }
    }

    /**
     * Run the (sub-)command with the given command line parameters.
     */
    run(
      progname: string,
      parents: CommandGroup<any, any>[],
      unparsedArgs: string[],
      parsedArgs: any,
    ): void {
      let posArgIndex = 0;
      let argsTerminated = false;
      let i;
      let foundSubcommand: CommandGroup<any, any> | undefined = undefined;
      if (Object.prototype.hasOwnProperty.call(parsedArgs, this.argKey)) {
        throw Error(
          `command argument key '${this.argKey}' collides with a parent command`,
        );
      }
      const myArgs: any = (parsedArgs[this.argKey] = {});
      const foundOptions: { [name: string]: boolean } = {};
      myArgs[FOUND_OPTIONS] = foundOptions;
      const currentName = this.name ?? progname;
      const storeOption = (def: OptionDef, value: string) => {
        foundOptions[def.name] = true;
        myArgs[def.name] = convertArg(def.name, def.conv, value);
      };
      const storeFlag = (def: OptionDef, value: boolean) => {
        foundOptions[def.name] = true;
        myArgs[def.name] = value;
      };
      for (i = 0; i < unparsedArgs.length; i++) {
        const argVal = unparsedArgs[i];
        if (argsTerminated == false) {
          if (argVal === "--") {
            argsTerminated = true;
            continue;
          }
          if (argVal.startsWith("--")) {
            const opt = argVal.substring(2);
            const r = splitOpt(opt);
            const d = this.longOptions[r.key];
            if (!d) {
              console.error(
                `error: unknown option '--${r.key}' for ${currentName}`,
              );
              processExit(-1);
              throw Error("not reached");
            }
            if (d.isFlag) {
              if (r.value !== undefined) {
                console.error(`error: flag '--${r.key}' does not take a value`);
                processExit(-1);
                throw Error("not reached");
              }
              storeFlag(d, true);
            } else {
              if (r.value === undefined) {
                if (i === unparsedArgs.length - 1) {
                  console.error(`error: option '--${r.key}' needs an argument`);
                  processExit(-1);
                  throw Error("not reached");
                }
                storeOption(d, unparsedArgs[i + 1]);
                i++;
              } else {
                storeOption(d, r.value);
              }
            }
            continue;
          }
          if (argVal.startsWith("-") && argVal != "-") {
            const optShort = argVal.substring(1);
            for (let si = 0; si < optShort.length; si++) {
              const chr = optShort[si];
              const opt = this.shortOptions[chr];
              if (!opt) {
                console.error(`error: option '-${chr}' not known`);
                processExit(-1);
              }
              if (opt.isFlag) {
                storeFlag(opt, true);
              } else {
                if (si == optShort.length - 1) {
                  if (i === unparsedArgs.length - 1) {
                    console.error(`error: option '-${chr}' needs an argument`);
                    processExit(-1);
                    throw Error("not reached");
                  } else {
                    storeOption(opt, unparsedArgs[i + 1]);
                    i++;
                  }
                } else {
                  storeOption(opt, optShort.substring(si + 1));
                }
                break;
              }
            }
            continue;
          }
        }
        if (posArgIndex < this.arguments.length) {
          const d = this.arguments[posArgIndex];
          myArgs[d.name] = convertArg(d.name, d.conv, argVal);
          posArgIndex++;
        } else if (this.subcommands.length != 0) {
          const subcmd = this.subcommandMap[argVal];
          if (!subcmd) {
            console.error(`error: unknown command '${argVal}'`);
            processExit(-1);
            throw Error("not reached");
          }
          foundSubcommand = subcmd.commandGroup;
          break;
        } else {
          console.error(`error: too many arguments for ${currentName}`);
          processExit(-1);
          throw Error("not reached");
        }
      }

      if (parsedArgs[this.argKey].help) {
        this.printHelp(progname, parents);
        processExit(0);
        throw Error("not reached");
      }

      for (let i = posArgIndex; i < this.arguments.length; i++) {
        const d = this.arguments[i];
        if (d.args.default !== undefined) {
          myArgs[d.name] = d.args.default;
        } else if (d.required) {
          console.error(
            `error: missing positional argument '${d.name}' for ${currentName}`,
          );
          processExit(-1);
          throw Error("not reached");
        }
      }

      for (const option of this.options) {
        if (foundOptions[option.name]) {
          continue;
        }
        if (option.isFlag) {
          myArgs[option.name] =
            option.args.default !== undefined ? option.args.default : false;
        } else if (option.args.default !== undefined) {
          myArgs[option.name] = option.args.default;
        } else if (option.required) {
          const name = option.flagspec.join(",");
          console.error(`error: missing option '${name}'`);
          processExit(-1);
          throw Error("not reached");
        }
      }

      for (const option of this.options) {
        const ph = option.args.onPresentHandler;
        if (ph && foundOptions[option.name]) {
          ph(myArgs[option.name]);
        }
      }

      if (foundSubcommand) {
        foundSubcommand.run(
          progname,
          Array.prototype.concat(parents, [this]),
          unparsedArgs.slice(i + 1),
          parsedArgs,
        );
      } else if (this.myAction) {
        // Only now that something is actually going to run, and after
        // --help has been handled above.  Unlike the listing, a mark on
        // any ancestor applies here.
        this.checkMarkPolicy(parents, progname);
        // Global options live on an ancestor, so the whole path has to be
        // asked about its options, not just the command that runs.
        for (const cg of [...parents, this]) {
          cg.checkOptionMarkPolicy(parsedArgs[cg.argKey]);
        }
        let r;
        try {
          r = this.myAction(parsedArgs);
        } catch (e) {
          console.error(`An error occurred while running ${currentName}`);
          console.error(e);
          processExit(1);
        }
        Promise.resolve(r).catch((e) => {
          console.error(`An error occurred while running ${currentName}`);
          console.error(e);
          processExit(1);
        });
      } else {
        this.printHelp(progname, parents);
        processExit(-1);
        throw Error("not reached");
      }
    }
  }

  export class Program<PN extends keyof any, T> {
    private mainCommand: CommandGroup<any, any>;

    constructor(argKey: string, args: ProgramArgs = {}) {
      this.mainCommand = new CommandGroup<any, any>(
        argKey,
        null,
        { help: args.help },
        args.markPolicy,
      );
      this.mainCommand.flag("help", ["-h", "--help"], {
        help: "Show this message and exit.",
      });
    }

    run(cmdlineArgs?: string[]): void {
      let args: string[];
      if (cmdlineArgs) {
        args = cmdlineArgs;
      } else {
        args = processArgv().slice(1);
      }
      if (args.length < 1) {
        console.error(
          "Error while parsing command line arguments: not enough arguments",
        );
        processExit(-1);
      }
      const progname = pathBasename(args[0]);
      const rest = args.slice(1);

      this.mainCommand.run(progname, [], rest, {});
    }

    subcommand<GN extends keyof any>(
      argKey: GN,
      name: string,
      args: SubcommandArgs = {},
    ): CommandGroup<GN, T> {
      const cmd = this.mainCommand.subcommand(argKey, name as string, args);
      return cmd as any;
    }

    requiredOption<N extends keyof any, V>(
      name: N,
      flagspec: string[],
      conv: Converter<V>,
      args: OptionArgs<V> = {},
    ): Program<PN, T & SubRecord<PN, N, V>> {
      this.mainCommand.requiredOption(name, flagspec, conv, args);
      return this as any;
    }

    maybeOption<N extends keyof any, V>(
      name: N,
      flagspec: string[],
      conv: Converter<V>,
      args: OptionArgs<V> = {},
    ): Program<PN, T & SubRecord<PN, N, V | undefined>> {
      this.mainCommand.maybeOption(name, flagspec, conv, args);
      return this as any;
    }

    /**
     * Add a flag (option without value) to the program.
     */
    flag<N extends string>(
      name: N,
      flagspec: string[],
      args: OptionArgs<boolean> = {},
    ): Program<PN, T & SubRecord<PN, N, boolean>> {
      this.mainCommand.flag(name, flagspec, args);
      return this as any;
    }

    /**
     * Add a required positional argument to the program.
     */
    requiredArgument<N extends keyof any, V>(
      name: N,
      conv: Converter<V>,
      args: ArgumentArgs<V> = {},
    ): Program<PN, T & SubRecord<PN, N, V>> {
      this.mainCommand.requiredArgument(name, conv, args);
      return this as any;
    }

    /**
     * Add an optional argument to the program.
     */
    maybeArgument<N extends keyof any, V>(
      name: N,
      conv: Converter<V>,
      args: ArgumentArgs<V> = {},
    ): Program<PN, T & SubRecord<PN, N, V | undefined>> {
      this.mainCommand.maybeArgument(name, conv, args);
      return this as any;
    }

    action(f: ActionFn<T>): void {
      this.mainCommand.action(f);
    }
  }

  export type GetArgType<T> =
    T extends Program<any, infer AT>
      ? AT
      : T extends CommandGroup<any, infer AT>
        ? AT
        : any;

  export function program<PN extends keyof any>(
    argKey: PN,
    args: ProgramArgs = {},
  ): Program<PN, {}> {
    return new Program(argKey as string, args);
  }

  export function prompt(question: string): Promise<string> {
    return readlinePrompt(question);
  }
}
