const MAX_PAIVANA_PICKUP_SECONDS = 60 * 60 * 24 * 365 * 100;

function malformedPaivanaResponse(
  requestUrl: string,
  requestMethod: string,
  httpStatusCode: number,
  hint: string,
): TalerError {
  return TalerError.fromDetail(
    TalerErrorCode.WALLET_RECEIVED_MALFORMED_RESPONSE,
    { requestUrl, requestMethod, httpStatusCode },
    hint,
  );
}

/** Validate and canonicalize a protected Paivana resource URL. */
export function canonicalizePaivanaUrl(url: string): string {
  let parsed: URL;
  try {
    parsed = new URL(url);
  } catch {
    throw TalerError.fromDetail(
      TalerErrorCode.WALLET_CORE_API_BAD_REQUEST,
      { parameter: "url" },
      `invalid Paivana URL "${url}"`,
    );
  }
  if (parsed.protocol !== "http:" && parsed.protocol !== "https:") {
    throw TalerError.fromDetail(
      TalerErrorCode.WALLET_CORE_API_BAD_REQUEST,
      { parameter: "url" },
      "Paivana payments require an HTTP(S) URL",
    );
  }
  if (parsed.username !== "" || parsed.password !== "") {
    throw TalerError.fromDetail(
      TalerErrorCode.WALLET_CORE_API_BAD_REQUEST,
      { parameter: "url" },
      "Paivana URLs must not contain credentials",
    );
  }
  // Fragments are not sent in HTTP requests and therefore cannot be part of
  // the URL reconstructed by the Paivana reverse proxy.
  parsed.hash = "";
  return parsed.href;
}

/** Encode a Paivana expiration as an unsigned big-endian microsecond value. */
export function encodePaivanaExpiration(
  expiration: TalerProtocolTimestamp,
): Uint8Array {
  if (expiration.t_s === "never") {
    throw Error("a Paivana expiration must be finite");
  }
  return timestampRoundedToBuffer(expiration);
}

/** Derive the DD 76 session identifier from its protocol inputs. */
export function makePaivanaSessionId(
  expiration: TalerProtocolTimestamp,
  nonce: Uint8Array,
  url: string,
): string {
  if (expiration.t_s === "never") {
    throw Error("a Paivana expiration must be finite");
  }
  if (nonce.byteLength !== 16) {
    throw Error("a Paivana nonce must contain exactly 16 bytes");
  }
  const urlBytes = stringToBytes(`${url}\0`);
  const expirationBytes = encodePaivanaExpiration(expiration);
  const input = new Uint8Array(
    nonce.byteLength + urlBytes.byteLength + expirationBytes.byteLength,
  );
  input.set(nonce, 0);
  input.set(urlBytes, nonce.byteLength);
  input.set(expirationBytes, nonce.byteLength + urlBytes.byteLength);
  const digest = base64FromArrayBuffer(sha256(input))
    .replace(/\+/g, "-")
    .replace(/\//g, "_")
    .replace(/=+$/, "");
  return `${expiration.t_s}-${digest}`;
}

/** Compute a finite access expiration, with the browser client's 100y cap. */
export function getPaivanaExpiration(
  maxPickupDuration: { d_us: number | "forever" } | undefined,
  now: TalerProtocolTimestamp = TalerProtocolTimestamp.now(),
): TalerProtocolTimestamp {
  if (now.t_s === "never") {
    throw Error("current time must be finite");
  }
  const pickupSeconds =
    maxPickupDuration?.d_us === undefined ||
    maxPickupDuration.d_us === "forever"
      ? MAX_PAIVANA_PICKUP_SECONDS
      : Math.min(
          MAX_PAIVANA_PICKUP_SECONDS,
          Math.floor(maxPickupDuration.d_us / 1_000_000),
        );
  return TalerProtocolTimestamp.fromSeconds(now.t_s + pickupSeconds);
}

export interface PreparedPaivanaTemplate {
  request: PreparePayForPaivanaRequest;
  redemption: PaivanaRedemption;
  talerPayTemplateUri: string;
  templateInfo: WalletTemplateDetailsResponse;
}

export function parsePaivanaTemplateUri(
  advertisedUri: string,
): TalerPayTemplateUri | undefined {
  return Result.orUndefined(
    TalerUris.parseRestricted(advertisedUri, TalerUriAction.PayTemplate),
  );
}

export function requirePaivanaTemplate(
  templateInfo: WalletTemplateDetailsResponse,
): void {
  if (templateInfo.template_contract.template_type !== TemplateType.PAIVANA) {
    throw TalerError.fromDetail(
      TalerErrorCode.WALLET_CONTRACT_TERMS_UNSUPPORTED,
      {},
      "the template advertised by the Paivana paywall is not a Paivana template",
    );
  }
}

/** Discover and validate the payment template advertised by a paywall. */
export async function preparePaivanaTemplate(
  wex: WalletExecutionContext,
  request: PreparePayForPaivanaRequest,
): Promise<PreparedPaivanaTemplate> {
  const url = canonicalizePaivanaUrl(request.url);
  const paywall = await runWithProgressRetries(wex, () =>
    wex.http.fetch(url, {
      method: "GET",
      redirect: "follow",
      cancellationToken: wex.cancellationToken,
    }),
  );
  if (paywall.status !== 402) {
    throw malformedPaivanaResponse(
      paywall.requestUrl,
      paywall.requestMethod,
      paywall.status,
      "the URL did not lead to a Paivana 402 paywall",
    );
  }
  const advertisedUri = paywall.headers.get("Paivana");
  if (!advertisedUri) {
    throw malformedPaivanaResponse(
      paywall.requestUrl,
      paywall.requestMethod,
      paywall.status,
      "the Paivana paywall did not advertise a payment template",
    );
  }
  const parsed = parsePaivanaTemplateUri(advertisedUri);
  if (!parsed) {
    throw malformedPaivanaResponse(
      paywall.requestUrl,
      paywall.requestMethod,
      paywall.status,
      "the Paivana header did not contain a valid pay-template URI",
    );
  }

  const merchantApi = new TalerMerchantInstanceHttpClient(
    parsed.merchantBaseUrl,
    wex.http,
    undefined,
    wex.cancellationToken,
  );
  const templateInfo = await runWithProgressRetries(wex, async () =>
    succeedOrThrow(await merchantApi.useTemplateGetInfo(parsed.templateId)),
  );
  requirePaivanaTemplate(templateInfo);

  const expiration = getPaivanaExpiration(
    templateInfo.template_contract.max_pickup_duration,
  );
  const nonceBytes = getRandomBytes(16);
  const redemption: PaivanaRedemption = {
    url,
    nonce: encodeCrock(nonceBytes),
    expiration,
  };
  const payTemplate: TalerPayTemplateUri = {
    ...parsed,
    sessionId: makePaivanaSessionId(expiration, nonceBytes, url),
    fulfillmentUrl: url,
  };
  return {
    request,
    redemption,
    talerPayTemplateUri: TalerUris.stringify(payTemplate),
    templateInfo,
  };
}

export async function preparePayForPaivana(
  wex: WalletExecutionContext,
  req: PreparePayForPaivanaRequest,
): Promise<PreparePayForPaivanaResult> {
  return runWithMaybeProgressContext(
    wex,
    "preparePayForPaivana",
    req.progressToken,
    async () => {
      const prepared = await preparePaivanaTemplate(wex, req);
      const instantiated = await instantiateTemplateRaw(
        wex,
        { talerPayTemplateUri: prepared.talerPayTemplateUri },
        prepared.templateInfo,
      );
      const proposalRes = await createOrReusePurchase(
        wex,
        instantiated.merchantBaseUrl,
        instantiated.orderId,
        instantiated.sessionId,
        instantiated.claimToken,
        undefined,
        prepared.talerPayTemplateUri,
      );
      return {
        transactionId: proposalRes.transactionId,
        paivana: prepared.redemption,
      };
    },
  );
}

/** Reduce Paivana's Set-Cookie response to a Cookie header name/value pair. */
export function extractPaivanaCookie(setCookie: string | null): string {
  if (setCookie === null) {
    throw Error("missing Paivana Set-Cookie header");
  }
  const firstPart = setCookie.split(";", 1)[0];
  if (!/^Paivana-Cookie=[^\s,;]+$/.test(firstPart)) {
    throw Error("invalid Paivana Set-Cookie header");
  }
  return firstPart;
}

export function validatePaivanaRedemption(redemption: PaivanaRedemption): {
  url: string;
  nonceBytes: Uint8Array;
  sessionId: string;
} {
  const url = canonicalizePaivanaUrl(redemption.url);
  let nonceBytes: Uint8Array;
  try {
    nonceBytes = decodeCrock(redemption.nonce);
  } catch {
    nonceBytes = new Uint8Array();
  }
  if (
    url !== redemption.url ||
    redemption.expiration.t_s === "never" ||
    nonceBytes.byteLength !== 16 ||
    encodeCrock(nonceBytes) !== redemption.nonce
  ) {
    throw TalerError.fromDetail(
      TalerErrorCode.WALLET_CORE_API_BAD_REQUEST,
      { parameter: "paivana" },
      "invalid Paivana redemption metadata",
    );
  }
  return {
    url,
    nonceBytes,
    sessionId: makePaivanaSessionId(redemption.expiration, nonceBytes, url),
  };
}

export async function getPaivanaCookie(
  wex: WalletExecutionContext,
  req: GetPaivanaCookieRequest,
): Promise<GetPaivanaCookieResult> {
  const parsedTx = parseTransactionIdentifier(req.transactionId);
  if (parsedTx?.tag !== TransactionType.Payment) {
    throw makeInvalidTransactionIdError(
      req.transactionId,
      TransactionType.Payment,
    );
  }
  const { url, sessionId } = validatePaivanaRedemption(req.paivana);

  const purchaseInfo = await wex.runWalletDbTx(async (tx) => {
    let p = await tx.getPurchase(parsedTx.proposalId);
    if (!p) {
      return undefined;
    }
    const requestedSessionId = p.downloadSessionId;
    if (p.purchaseStatus === PurchaseStatus.DoneRepurchaseDetected) {
      if (!p.repurchaseProposalId) {
        return { purchase: p, requestedSessionId };
      }
      p = await tx.getPurchase(p.repurchaseProposalId);
    }
    return p ? { purchase: p, requestedSessionId } : undefined;
  });
  if (!purchaseInfo) {
    throw makeTransactionNotFoundError(req.transactionId);
  }
  const { purchase, requestedSessionId } = purchaseInfo;
  if (requestedSessionId !== sessionId) {
    throw TalerError.fromDetail(
      TalerErrorCode.WALLET_CORE_API_BAD_REQUEST,
      { parameter: "paivana" },
      "the Paivana redemption metadata does not match the transaction",
    );
  }
  if (purchase.purchaseStatus !== PurchaseStatus.Done) {
    throw TalerError.fromDetail(
      TalerErrorCode.WALLET_REQUEST_TRANSACTION_STATE_UNSUPPORTED,
      { txState: computePayMerchantTransactionState(purchase) },
      "the Paivana cookie can only be redeemed after payment succeeds",
    );
  }
  if (purchase.download?.fulfillmentUrl !== url) {
    throw TalerError.fromDetail(
      TalerErrorCode.WALLET_CORE_API_BAD_REQUEST,
      { parameter: "paivana.url" },
      "the Paivana URL does not match the paid contract",
    );
  }

  const endpoint = new URL("/.well-known/paivana", url).href;
  const response = await wex.http.fetch(endpoint, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: {
      order_id: purchase.orderId,
      nonce: req.paivana.nonce,
      expiration: req.paivana.expiration,
      website: url,
    },
    redirect: "manual",
    cancellationToken: wex.cancellationToken,
  });
  if (response.status !== 303) {
    if (response.status >= 400) {
      throw TalerError.fromUncheckedDetail(
        await readTalerErrorResponse(response),
      );
    }
    throw malformedPaivanaResponse(
      response.requestUrl,
      response.requestMethod,
      response.status,
      "Paivana redemption did not return the required 303 response",
    );
  }
  const location = response.headers.get("Location");
  let destination: string;
  try {
    destination = new URL(location ?? "", endpoint).href;
  } catch {
    destination = "";
  }
  if (!location || destination !== url) {
    throw malformedPaivanaResponse(
      response.requestUrl,
      response.requestMethod,
      response.status,
      "Paivana redemption redirected to an unexpected destination",
    );
  }
  let cookie: string;
  try {
    cookie = extractPaivanaCookie(response.headers.get("Set-Cookie"));
  } catch {
    throw malformedPaivanaResponse(
      response.requestUrl,
      response.requestMethod,
      response.status,
      "Paivana redemption returned an invalid access cookie",
    );
  }
  return { cookie };
}
