/**
 * List bank accounts known to the wallet from
 * previous withdrawals.
 */
async function handleListBankAccounts(
  wex: WalletExecutionContext,
  req: ListBankAccountsRequest,
): Promise<ListBankAccountsResponse> {
  const accounts: WalletBankAccountInfo[] = [];
  const currency = req.currency;
  await wex.runWalletDbTx(async (tx) => {
    const knownAccounts = await tx.listBankAccounts();
    for (const r of knownAccounts) {
      if (currency && r.currencies && !r.currencies.includes(currency)) {
        continue;
      }
      const payto = Result.orUndefined(Paytos.fromString(r.paytoUri));
      if (payto) {
        accounts.push({
          bankAccountId: r.bankAccountId,
          paytoUri: r.paytoUri,
          label: r.label,
          kycCompleted: r.kycCompleted,
          currencies: r.currencies,
        });
      }
    }
  });
  return { accounts };
}

async function handleGetBankAccountById(
  wex: WalletExecutionContext,
  req: GetBankAccountByIdRequest,
): Promise<GetBankAccountByIdResponse> {
  const acct = await wex.runWalletDbTx(async (tx) => {
    return tx.getBankAccount(req.bankAccountId);
  });
  if (!acct) {
    throw TalerError.fromDetail(
      TalerErrorCode.WALLET_BANK_ACCOUNT_NOT_FOUND,
      { bankAccountId: req.bankAccountId },
      `bank account ${req.bankAccountId} not found`,
    );
  }
  return acct;
}

/**
 * Remove a known bank account.
 */
async function forgetBankAccount(
  wex: WalletExecutionContext,
  bankAccountId: string,
): Promise<void> {
  await wex.runWalletDbTx(async (tx) => {
    const account = await tx.getBankAccount(bankAccountId);
    if (!account) {
      throw TalerError.fromDetail(
        TalerErrorCode.WALLET_BANK_ACCOUNT_NOT_FOUND,
        { bankAccountId },
        `bank account ${bankAccountId} not found`,
      );
    }
    await tx.deleteBankAccount(account.bankAccountId);
  });
  wex.ws.notify({
    type: NotificationType.BankAccountChange,
    bankAccountId,
  });
  return;
}

export async function setCoinSuspended(
  wex: WalletExecutionContext,
  coinPub: string,
  suspended: boolean,
): Promise<void> {
  await wex.runWalletDbTx(async (tx) => {
    const c = await tx.getCoin(coinPub);
    if (!c) {
      logger.warn(`coin ${coinPub} not found, won't suspend`);
      return;
    }
    const coinAvailability = await tx.getCoinAvailability(c);
    checkDbInvariant(
      !!coinAvailability,
      `no denom info for ${c.denomPubHash} age ${c.maxAge}`,
    );
    if (suspended) {
      if (c.status !== CoinStatus.Fresh) {
        return;
      }
      if (coinAvailability.freshCoinCount === 0) {
        throw Error(
          `invalid coin count ${coinAvailability.freshCoinCount} in DB`,
        );
      }
      coinAvailability.freshCoinCount--;
      c.status = CoinStatus.FreshSuspended;
    } else {
      if (c.status !== CoinStatus.FreshSuspended) {
        return;
      }
      coinAvailability.freshCoinCount++;
      c.status = CoinStatus.Fresh;
    }
    await tx.upsertCoin(c);
    await tx.upsertCoinAvailability(coinAvailability);
  });
}

/**
 * Dump the public information of coins we have in an easy-to-process format.
 */
async function dumpCoins(wex: WalletExecutionContext): Promise<CoinDumpJson> {
  const coinsJson: CoinDumpJson = { coins: [] };
  logger.info("dumping coins");
  await wex.runWalletDbTx(async (tx) => {
    const coins = await tx.listAllCoins();
    const denominations = await tx.getDenominationsByRefs(coins);
    const denominationsByRef = new Map(
      denominations.map((denom) => [denomRefKey(denom), denom]),
    );
    const histories = await tx.getCoinHistoriesByPubs(
      coins.map((coin) => coin.coinPub),
    );
    const historiesByPub = new Map(
      histories.map((history) => [history.coinPub, history]),
    );
    for (const c of coins) {
      const denom = denominationsByRef.get(denomRefKey(c));
      if (!denom) {
        logger.warn("no denom found for coin");
        continue;
      }
      const cs = c.coinSource;
      let refreshParentCoinPub: string | undefined;
      if (cs.type == CoinSourceType.Refresh) {
        refreshParentCoinPub = cs.oldCoinPub;
      }
      let withdrawalReservePub: string | undefined;
      if (cs.type == CoinSourceType.Withdraw) {
        withdrawalReservePub = cs.reservePub;
      }
      const historyRec = historiesByPub.get(c.coinPub);
      coinsJson.coins.push({
        coinPub: c.coinPub,
        denomPub: denom.denomPub,
        denomPubHash: c.denomPubHash,
        denomValue: denom.value,
        exchangeBaseUrl: c.exchangeBaseUrl,
        refreshParentCoinPub: refreshParentCoinPub,
        withdrawalReservePub: withdrawalReservePub,
        coinStatus: c.status,
        ageCommitmentProof: c.ageCommitmentProof,
        history: historyRec ? historyRec.history : [],
      });
    }
  });
  return coinsJson;
}

/**
 * The IndexedDB backend, or an error naming what needs it.
 *
 * The fixup log is an IndexedDB concern: the native schema starts clean and
 * evolves through schemaMigrations, so it has no fixup log.  Failing loudly
 * here beats silently operating on an unrelated emulation database.
 */
function requireIdbBackend(
  wex: WalletExecutionContext,
  what: string,
): IdbWalletDbHandle {
  const idb = wex.ws.idbOnly;
  if (!idb) {
    throw TalerError.fromDetail(
      TalerErrorCode.WALLET_DB_BACKEND_UNSUPPORTED,
      { backend: wex.ws.db.name },
      `${what} is only supported on the IndexedDB backend`,
    );
  }
  return idb;
}

async function handlePrepareWithdrawExchange(
  wex: WalletExecutionContext,
  req: PrepareWithdrawExchangeRequest,
): Promise<PrepareWithdrawExchangeResponse> {
  const parsedUri = Result.orUndefined(TalerUris.parse(req.talerUri));
  if (parsedUri?.type !== TalerUriAction.WithdrawExchange) {
    throw TalerError.fromDetail(
      TalerErrorCode.WALLET_TALER_URI_MALFORMED,
      {
        talerUri: req.talerUri,
        expectedAction: TalerUriAction.WithdrawExchange,
      },
      "expected a taler://withdraw-exchange URI",
    );
  }
  const exchangeBaseUrl = parsedUri.exchangeBaseUrl;

  return await runWithMaybeProgressContext(
    wex,
    "prepareWithdrawExchange",
    req.progressToken,
    async (pc) => {
      if (pc) {
        pc.onRetryNow = async () => {
          await resetExchangeRetries(wex, exchangeBaseUrl);
        };
      }
      const exchange = await fetchFreshExchange(wex, exchangeBaseUrl, {
        noBail: pc != null,
      });
      if (parsedUri.amount) {
        const amt = Amounts.parseOrThrow(parsedUri.amount);
        if (amt.currency !== exchange.currency) {
          throw TalerError.fromDetail(
            TalerErrorCode.GENERIC_CURRENCY_MISMATCH,
            {},
            `mismatch of currency (URI says ${amt.currency}, exchange uses ${exchange.currency})`,
          );
        }
      }
      return {
        exchangeBaseUrl,
        amount: parsedUri.amount,
      };
    },
  );
}

async function handleSharePayment(
  wex: WalletExecutionContext,
  req: SharePaymentRequest,
): Promise<SharePaymentResult> {
  return await sharePayment(wex, req.merchantBaseUrl, req.orderId);
}

async function handleUnclaimPayment(
  wex: WalletExecutionContext,
  req: UnclaimPaymentRequest,
): Promise<UnclaimPaymentResult> {
  const parsed = parseTransactionIdentifier(req.transactionId);
  if (parsed?.tag !== TransactionType.Payment) {
    throw makeInvalidTransactionIdError(req.transactionId);
  }
  return unclaimPayment(wex, parsed.proposalId);
}

/**
 * Highest number of HTTP redirects followed while probing one candidate base
 * URL, so that a redirect loop cannot keep the completion running forever.
 */
const maxCompletionRedirects = 5;

type ExchangeProbeResult =
  | {
      status: "ok";
      /** Base URL that the validated /config response was served under. */
      baseUrl: string;
    }
  | {
      status: "bad-network" | "bad-exchange";
      error: TalerErrorDetail;
    };

/**
 * True for the status codes that carry a "location" header we should follow.
 */
function isRedirectStatus(status: number): boolean {
  switch (status) {
    case HttpStatusCode.MovedPermanently:
    case HttpStatusCode.Found:
    case HttpStatusCode.SeeOther:
    case HttpStatusCode.TemporaryRedirect:
    case HttpStatusCode.PermanentRedirect:
      return true;
    default:
      return false;
  }
}

/**
 * Decide whether a failed request never reached a server, or reached one that
 * answered with something an exchange would not answer.
 */
function classifyProbeError(
  error: TalerErrorDetail,
): "bad-network" | "bad-exchange" {
  switch (error.code) {
    case TalerErrorCode.WALLET_NETWORK_ERROR:
    case TalerErrorCode.WALLET_HTTP_REQUEST_GENERIC_TIMEOUT:
    case TalerErrorCode.WALLET_HTTP_REQUEST_THROTTLED:
      return "bad-network";
    default:
      return "bad-exchange";
  }
}

/**
 * Check whether an exchange is served under @a baseUrl by requesting its
 * /config and validating the response.
 *
 * Redirects are followed here instead of by the HTTP layer, because the base
 * URL to report back is the one the final response came from, and the HTTP
 * layer does not expose it.  The qtart runtime follows redirects natively and
 * ignores the "manual" setting, so on that platform a redirected exchange
 * validates but is reported under the base URL we asked for.
 *
 * @param wex wallet execution context
 * @param baseUrl candidate base URL, already cleaned up
 * @param allowHttp whether a plain-HTTP redirect target is acceptable
 * @returns the base URL that answered, or why the candidate was rejected
 */
async function probeExchangeBaseUrl(
  wex: WalletExecutionContext,
  baseUrl: string,
  allowHttp: boolean,
): Promise<ExchangeProbeResult> {
  let configUrl = new URL("config", baseUrl).href;

  for (let redirectCount = 0; ; redirectCount++) {
    let resp: HttpResponse;
    try {
      resp = await wex.http.fetch(configUrl, {
        redirect: "manual",
        cancellationToken: wex.cancellationToken,
      });
    } catch (e) {
      const error = getErrorDetailFromException(e);
      return { status: classifyProbeError(error), error };
    }

    if (isRedirectStatus(resp.status)) {
      const location = resp.headers.get("location");
      if (location == null) {
        return {
          status: "bad-exchange",
          error: {
            code: TalerErrorCode.WALLET_RECEIVED_MALFORMED_RESPONSE,
            requestUrl: configUrl,
            httpStatusCode: resp.status,
            detail: "redirect without a location header",
          },
        };
      }
      if (redirectCount >= maxCompletionRedirects) {
        return {
          status: "bad-exchange",
          error: {
            code: TalerErrorCode.WALLET_UNEXPECTED_REQUEST_ERROR,
            requestUrl: configUrl,
            httpStatusCode: resp.status,
            detail: `too many redirects (more than ${maxCompletionRedirects})`,
          },
        };
      }
      let target: string;
      try {
        target = new URL(location, configUrl).href;
      } catch (e) {
        return {
          status: "bad-exchange",
          error: {
            code: TalerErrorCode.WALLET_RECEIVED_MALFORMED_RESPONSE,
            requestUrl: configUrl,
            httpStatusCode: resp.status,
            detail: `redirect to an unparsable location (${location})`,
          },
        };
      }
      const targetProtocol = new URL(target).protocol;
      if (
        targetProtocol !== "https:" &&
        !(targetProtocol === "http:" && allowHttp)
      ) {
        return {
          status: "bad-exchange",
          error: {
            code: TalerErrorCode.WALLET_UNEXPECTED_REQUEST_ERROR,
            requestUrl: configUrl,
            httpStatusCode: resp.status,
            detail: `redirect to a non-HTTPS location (${target})`,
          },
        };
      }
      configUrl = target;
      continue;
    }

    try {
      await carefullyParseConfig(
        "taler-exchange",
        TalerExchangeHttpClient.SUPPORTED_EXCHANGE_PROTOCOL_VERSION,
        resp,
        codecForExchangeConfig(),
      );
    } catch (e) {
      return {
        status: "bad-exchange",
        error: getErrorDetailFromException(e),
      };
    }

    // We can only vouch for a base URL whose /config we actually read, so a
    // server that redirects /config somewhere else entirely gets rejected
    // rather than reported under a base URL we never validated.
    const parsedConfigUrl = new URL(configUrl);
    if (!parsedConfigUrl.pathname.endsWith("/config")) {
      return {
        status: "bad-exchange",
        error: {
          code: TalerErrorCode.WALLET_UNEXPECTED_REQUEST_ERROR,
          requestUrl: configUrl,
          httpStatusCode: resp.status,
          detail: "config was served under a path that is not <base>/config",
        },
      };
    }

    return { status: "ok", baseUrl: new URL(".", configUrl).href };
  }
}

export async function handleCompleteExchangeBaseUrl(
  wex: WalletExecutionContext,
  req: CompleteBaseUrlRequest,
): Promise<CompleteBaseUrlResult> {
  const allowHttp = wex.ws.config.features.allowHttp;

  const cleanup = cleanUpExchangeBaseUrl(req.url, { allowHttp });
  if (cleanup.status !== "ok") {
    return {
      status: "bad-syntax",
      error: {
        code: TalerErrorCode.WALLET_CORE_API_BAD_REQUEST,
        detail: cleanup.detail,
      },
    };
  }

  // Probing every candidate can take as long as the network takes to time
  // out, so a client that passes a progress token gets the "delayed"/
  // "stalled" phases and can cancel.  There is deliberately no retry loop
  // around the probe: an exchange that cannot be reached is the answer this
  // request exists to give, not a failure to retry until it goes away.
  return await runWithMaybeProgressContext(
    wex,
    "completeExchangeBaseUrl",
    req.progressToken,
    async () => {
      const candidates = exchangeBaseUrlCandidates(cleanup.baseUrl);
      let lastFailure: Extract<
        ExchangeProbeResult,
        { status: "bad-network" | "bad-exchange" }
      > = {
        status: "bad-network",
        error: {
          code: TalerErrorCode.WALLET_NETWORK_ERROR,
          detail: "no candidate base URL could be probed",
        },
      };

      for (const candidate of candidates) {
        const probeResult = await probeExchangeBaseUrl(
          wex,
          candidate,
          allowHttp,
        );
        if (probeResult.status === "ok") {
          return { status: "ok", completion: probeResult.baseUrl };
        }
        lastFailure = probeResult;
      }

      const knownExchanges = await listExchanges(wex, {});
      const suggestions = findExchangeSuggestions(
        cleanup.baseUrl,
        knownExchanges.exchanges.map((x) => x.exchangeBaseUrl),
      );

      return {
        status: lastFailure.status,
        error: lastFailure.error,
        ...(suggestions.length > 0 ? { suggestions } : {}),
      };
    },
  );
}

async function handleSetWalletRunConfig(
  wex: WalletExecutionContext,
  req: InitRequest,
) {
  if (logger.shouldLogTrace()) {
    const initType = wex.ws.initCalled
      ? "repeat initialization"
      : "first initialization";
    logger.trace(`init request (${initType}): ${j2s(req)}`);
  }

  // Write to the DB to make sure that we're failing early in
  // case the DB is not writeable.
  try {
    await wex.runWalletDbTx(async (tx) => {
      tx.upsertConfig({
        key: ConfigRecordKey.LastInitInfo,
        value: timestampProtocolToDb(TalerProtocolTimestamp.now()),
      });
    });
  } catch (e) {
    logger.error(
      "error writing to database during initialization (while writing last error info)",
    );
    const err = getErrorDetailFromException(e);
    logger.error(`details: ${j2s(err)}`);
    throw TalerError.fromDetail(TalerErrorCode.WALLET_DB_UNAVAILABLE, {
      innerError: err,
    });
  }
  // Before anything else touches the database: everything below this line
  // runs against whichever backend the wallet ends up on, and the migration
  // needs the fixup log of the old one to have been replayed, which opening
  // it for the write above did.
  if (wex.ws.config.features.migrateNativeDb) {
    await wex.ws.migrateDbToNativeSchema();
  }

  if (wex.ws.config.testing.skipDefaults) {
    logger.trace("skipping defaults");
  } else {
    logger.trace("filling defaults");
    await fillDefaults(wex);
  }

  if (req.config?.logLevel) {
    setGlobalLogLevelFromString(req.config.logLevel);
  }

  await migrateMaterializedTransactions(wex);

  if (!wex.ws.initCalled) {
    await collectLeftoverClaims(wex);
    await deleteEphemeralExchanges(wex);
  }

  const databaseBackend = wex.ws.db.name;
  checkDbInvariant(
    databaseBackend === "indexeddb" || databaseBackend === "sqlite",
    `unknown wallet database backend: ${databaseBackend}`,
  );
  const resp: InitResponse = {
    versionInfo: await handleGetVersion(wex),
    databaseBackend,
  };

  if (req.config?.lazyTaskLoop) {
    logger.trace("lazily starting task loop");
  } else {
    await wex.taskScheduler.ensureRunning();
  }

  wex.ws.initCalled = true;
  return resp;
}

