async function handleAddBankAccount(
  wex: WalletExecutionContext,
  req: AddBankAccountRequest,
): Promise<AddBankAccountResponse> {
  Paytos.parseOrThrow(req.paytoUri);
  const acctId = await wex.runWalletDbTx(async (tx) => {
    let currencies = req.currencies;
    let myId: string;
    const oldAcct = await tx.getBankAccountByPaytoUri(req.paytoUri);
    if (req.replaceBankAccountId) {
      // Without this check, replacing an account that does not exist would
      // create one under the client's ID instead of failing, which hides a
      // stale ID in the client and mints accounts with foreign ID formats.
      const toReplace = await tx.getBankAccount(req.replaceBankAccountId);
      if (!toReplace) {
        throw TalerError.fromDetail(
          TalerErrorCode.WALLET_BANK_ACCOUNT_NOT_FOUND,
          { bankAccountId: req.replaceBankAccountId },
          `bank account ${req.replaceBankAccountId} not found, cannot replace it`,
        );
      }
      myId = req.replaceBankAccountId;
    } else if (oldAcct) {
      myId = oldAcct.bankAccountId;
      currencies = [
        ...new Set([...(req.currencies ?? []), ...(oldAcct.currencies ?? [])]),
      ];
      currencies.sort();
    } else {
      // New Account!
      myId = `acct:${encodeCrock(getRandomBytes(32))}`;
    }
    await tx.upsertBankAccount({
      bankAccountId: myId,
      paytoUri: req.paytoUri,
      label: req.label,
      currencies,
      kycCompleted: false,
    });
    return myId;
  });
  wex.ws.notify({
    type: NotificationType.BankAccountChange,
    bankAccountId: acctId,
  });
  return {
    bankAccountId: acctId,
  };
}

