async function handleExportDbToFile(
  wex: WalletExecutionContext,
  req: ExportDbToFileRequest,
): Promise<ExportDbToFileResponse> {
  const db = wex.ws.db;
  if (!db.exportToFile) {
    throw TalerError.fromDetail(
      TalerErrorCode.WALLET_DB_BACKEND_UNSUPPORTED,
      { backend: db.name },
      `the ${db.name} backend cannot export the database to a file`,
    );
  }
  // Called as a method: the sqlite implementation reads this.ndb, and
  // extracting the function first would drop the receiver.
  const res = await db.exportToFile(req.directory, req.stem, req.forceFormat);
  return {
    path: res.path,
  };
}

async function handleMigrateDatabase(
  wex: WalletExecutionContext,
  req: MigrateDatabaseRequest,
): Promise<MigrateDatabaseResponse> {
  return await runWithMaybeProgressContext(
    wex,
    WalletApiOperation.MigrateDatabase,
    req.progressToken,
    async () => {
      const migrated = await wex.ws.migrateDbToNativeSchema({
        cancellationToken: wex.cancellationToken,
        progressToken: req.progressToken,
        failIfUnsupported: true,
        propagateFailure: true,
      });
      const databaseBackend = wex.ws.db.name;
      checkDbInvariant(
        databaseBackend === "indexeddb" || databaseBackend === "sqlite",
        `unknown wallet database backend: ${databaseBackend}`,
      );
      return { migrated, databaseBackend };
    },
  );
}

async function handleImportDb(
  wex: WalletExecutionContext,
  req: ImportDbRequest,
): Promise<EmptyObject> {
  // Import, backend repairs and the derived transaction view become visible
  // together.  The backend keeps the old database authoritative if this
  // finalizer throws.
  await wex.ws.db.importDatabase(req.dump, async (tx) => {
    await rematerializeTransactionsAtCurrentVersion(wex, tx);
  });

  // The import replaced the database underneath the DAL, writing through the
  // raw IndexedDB handle, so none of the automatic invalidation saw it.  Every
  // cached exchange, denomination and refresh cost now describes records that
  // are gone.
  wex.ws.clearAllCaches();
  return {};
}

async function handleImportDbFromFile(
  wex: WalletExecutionContext,
  req: ImportDbFromFileRequest,
): Promise<EmptyObject> {
  if (req.path.endsWith(".json")) {
    const db = wex.ws.db;
    if (!db.readBackupJson) {
      throw TalerError.fromDetail(
        TalerErrorCode.WALLET_DB_BACKEND_UNSUPPORTED,
        { backend: db.name },
        `the ${db.name} backend cannot read a database dump from a file`,
      );
    }
    const dump = await db.readBackupJson(req.path);
    return await handleImportDb(wex, {
      dump,
    });
  } else {
    throw TalerError.fromDetail(
      TalerErrorCode.WALLET_CORE_API_BAD_REQUEST,
      { parameter: "path" },
      "DB file import only supports .json files at the moment",
    );
  }
}

