export async function handleHintApplicationResumed(
  wex: WalletExecutionContext,
  req: EmptyObject,
): Promise<HintApplicationResumedResponse> {
  logger.info("handling hintApplicationResumed");

  let dbWriteHealthy = false;
  try {
    await wex.runWalletDbTx(async (tx) => {
      await tx.upsertConfig({
        key: ConfigRecordKey.LastResumed,
        value: timestampProtocolToDb(TalerProtocolTimestamp.now()),
      });
    });
    dbWriteHealthy = true;
  } catch (e) {
    logger.error(
      `database write health check failed: ${j2s(getErrorDetailFromException(e))}`,
    );
  }

  let dbReadHealthy = false;
  try {
    await wex.runWalletDbTx(async (tx) => {
      await tx.getConfig(ConfigRecordKey.LastResumed);
    });
    dbReadHealthy = true;
  } catch (e) {
    logger.error(
      `database read health check failed: ${j2s(getErrorDetailFromException(e))}`,
    );
  }

  await restartAllRunningTasks(wex);
  return { dbWriteHealthy, dbReadHealthy };
}

export async function handleTestingRunFixup(
  wex: WalletExecutionContext,
  req: RunFixupRequest,
): Promise<EmptyObject> {
  for (const fixup of walletDbFixups) {
    if (fixup.name != req.id) {
      continue;
    }
    // fixup.fn takes the raw IndexedDB transaction: fixups repair that
    // backend's records and are not expressible through the DAL.
    await wex.ws.runWithDatabaseShared(async () => {
      // Resolve the backend after admission: a queued fixup must not retain an
      // IndexedDB handle across a native migration.
      const idb = requireIdbBackend(wex, "running a fixup");
      const access = await idb.rawAccess();
      await access.runAllStoresReadWriteTx({}, async (tx) => {
        await fixup.fn(tx);
      });
    });
    await wex.runWalletDbTx(async (tx) => {
      await rematerializeTransactions(wex, tx);
    });
    return {};
  }
  throw TalerError.fromDetail(
    TalerErrorCode.WALLET_CORE_API_BAD_REQUEST,
    { parameter: "id" },
    `fixup "${req.id}" not found`,
  );
}

