/**
 * Check whether an operation may be run before the wallet is initialized.
 *
 * Both operations run the same handler, either of them initializes the wallet.
 */
export function isWalletInitOperation(operation: string): boolean {
  return (
    operation === WalletApiOperation.InitWallet ||
    operation === WalletApiOperation.SetWalletRunConfig
  );
}

/**
 * Implementation of the "wallet-core" API.
 */
export async function dispatchRequestInternal(
  wex: WalletExecutionContext,
  operation: WalletApiOperation,
  payload: unknown,
): Promise<WalletCoreResponseType<typeof operation>> {
  if (!wex.ws.initCalled && !isWalletInitOperation(operation)) {
    throw TalerError.fromDetail(
      TalerErrorCode.WALLET_CORE_NOT_AVAILABLE,
      {},
      `wallet must be initialized before running operation ${operation}`,
    );
  }

  const h: HandlerWithValidator<any> = handlers[operation];

  if (!h) {
    throw TalerError.fromDetail(
      TalerErrorCode.WALLET_CORE_API_OPERATION_UNKNOWN,
      {
        operation,
      },
      "unknown operation",
    );
  }

  const req = h.codec.decode(payload);
  return await h.handler(wex, req);
}
