/**
 * Get information about the coin selected for signatures.
 */
export async function queryCoinInfosForSelection(
  wex: WalletExecutionContext,
  csel: DbPeerPushPaymentCoinSelection,
): Promise<SpendCoinDetails[]> {
  let infos: SpendCoinDetails[] = [];
  const exchangeBaseUrls = new Set<string>();
  await wex.runWalletDbTx(async (tx) => {
    const coins = await tx.getCoinsByPubs(csel.coinPubs);
    const coinsByPub = new Map(coins.map((coin) => [coin.coinPub, coin]));
    const denoms = await getDenomInfos(wex, tx, coins);
    for (let i = 0; i < csel.coinPubs.length; i++) {
      const coin = coinsByPub.get(csel.coinPubs[i]);
      if (!coin) {
        throw Error("coin not found anymore");
      }
      const denom = denoms.get(denomRefKey(coin));
      if (!denom) {
        throw Error("denom for coin not found anymore");
      }
      exchangeBaseUrls.add(coin.exchangeBaseUrl);
      infos.push({
        coinPriv: coin.coinPriv,
        coinPub: coin.coinPub,
        denomPubHash: coin.denomPubHash,
        denomSig: coin.denomSig,
        ageCommitmentProof: coin.ageCommitmentProof,
        contribution: csel.contributions[i],
        feeDeposit: denom.feeDeposit,
      });
    }
  });
  for (const exchangeBaseUrl of exchangeBaseUrls) {
    await requireExchangeCoinUseConfirmedOrThrow(wex, exchangeBaseUrl);
  }
  return infos;
}

export async function getTotalPeerPaymentCostInTx(
  wex: WalletExecutionContext,
  tx: WalletDbTransaction,
  pcs: SelectedProspectiveCoin[],
): Promise<AmountJson> {
  if (pcs.length === 0) {
    // Without a coin there is no currency to express the cost in.
    throw Error("can't calculate payment cost, no coin selected");
  }
  const costs: AmountJson[] = [];
  const denoms = await getDenomInfos(wex, tx, pcs);
  const paymentDenoms = pcs.map((coin) => {
    const denomInfo = denoms.get(denomRefKey(coin));
    if (!denomInfo) {
      throw Error(
        "can't calculate payment cost, denomination for coin not found",
      );
    }
    return denomInfo;
  });
  const refreshCosts = await getTotalRefreshCosts(
    wex,
    tx,
    paymentDenoms.map((denomInfo, i) => ({
      refreshedDenom: denomInfo,
      amountLeft: Amounts.sub(denomInfo.value, pcs[i].contribution).amount,
    })),
  );
  for (let i = 0; i < pcs.length; i++) {
    costs.push(Amounts.parseOrThrow(pcs[i].contribution));
    costs.push(refreshCosts[i]);
  }
  return Amounts.sum(costs).amount;
}

export async function getTotalPeerPaymentCost(
  wex: WalletExecutionContext,
  pcs: SelectedProspectiveCoin[],
): Promise<AmountJson> {
  // We first need to make sure we have already validated
  // potential target denomination for the refresh.
  // This must happen *before* we start the transaction.
  if (pcs.length > 0) {
    // P2P payments currently support only one exchange.
    const exchangeBaseUrl = pcs[0].exchangeBaseUrl;
    await updateWithdrawalDenomsForExchange(wex, exchangeBaseUrl);
  }
  return await wex.runWalletDbTx(async (tx) => {
    return await getTotalPeerPaymentCostInTx(wex, tx, pcs);
  });
}

export async function getMergeReserveInfo(
  wex: WalletExecutionContext,
  req: {
    exchangeBaseUrl: string;
  },
): Promise<WalletReserve> {
  // We have to eagerly create the key pair outside of the transaction,
  // due to the async crypto API.
  const newReservePair = await wex.cryptoApi.createEddsaKeypair({});

  const mergeReserveRecord: WalletReserve = await wex.runWalletDbTx(
    async (tx) => {
      const ex = await tx.getExchange(req.exchangeBaseUrl);
      checkDbInvariant(!!ex, `no exchange record for ${req.exchangeBaseUrl}`);
      let reserve: WalletReserve | undefined;
      if (ex.currentMergeReserveRowId != null) {
        reserve = await tx.getReserve(ex.currentMergeReserveRowId);
        checkDbInvariant(
          !!reserve,
          `reserver ${ex.currentMergeReserveRowId} missing in db`,
        );
      } else {
        reserve = {
          reservePriv: newReservePair.priv,
          reservePub: newReservePair.pub,
        };
        reserve.rowId = await tx.upsertReserve(reserve);
        ex.currentMergeReserveRowId = reserve.rowId;
        await tx.upsertExchange(ex);
      }
      // The wallet keeps an account at the exchange now, so the entry must
      // stay around even if no transaction ends up using it.
      await markExchangeUsed(tx, req.exchangeBaseUrl);
      return reserve;
    },
  );

  return mergeReserveRecord;
}

/** Check if a purse is merged */
export function isPurseMerged(purse: ExchangePurseStatus): boolean {
  const mergeTimestamp = purse.merge_timestamp;
  return (
    mergeTimestamp != null && !TalerProtocolTimestamp.isNever(mergeTimestamp)
  );
}

/** Check if a purse is deposited */
export function isPurseDeposited(purse: ExchangePurseStatus): boolean {
  const depositTimestamp = purse.deposit_timestamp;
  return (
    depositTimestamp != null &&
    !TalerProtocolTimestamp.isNever(depositTimestamp)
  );
}

/**
 * Check whether a purse that the exchange reports as gone lapsed.
 *
 * The exchange answers "gone" for a purse that reached its expiration, for
 * one that its owner deleted and for one that was already decided because
 * another wallet got there first.  The purse expiration is part of the
 * contract terms, so the local clock separates the first cause from the other
 * two without having to trust the exchange on it: a purse that is not due yet
 * cannot have lapsed.
 */
export function isPurseGoneByExpiration(
  purseExpiration: TalerProtocolTimestamp,
): boolean {
  return AbsoluteTime.isExpired(
    AbsoluteTime.fromProtocolTimestamp(purseExpiration),
  );
}
