import { codecForAmountString } from "./amounts.js";
import {
  Codec,
  buildCodecForObject,
  buildCodecForUnion,
  codecForBoolean,
  codecForConstString,
  codecForEither,
  codecForList,
  codecForString,
  codecOptional,
} from "./codec.js";
import { codecForTimestamp, TalerProtocolTimestamp } from "./time.js";
import {
  AmountString,
  EddsaPublicKey,
  EddsaSignature,
  Timestamp,
  codecForEddsaPublicKey,
  codecForEddsaSignature,
} from "./types-taler-common.js";

export type SubjectFormat = "SIMPLE" | "URI" | "CH_QR_BILL";

export interface PreparedTransferConfig {
  // Name of the API.
  name: "taler-prepared-transfer";

  // libtool-style representation of the protocol version, see
  // https://www.gnu.org/software/libtool/manual/html_node/Versioning.html#Versioning
  // The format is "current:revision:age".
  version: string;

  // Currency used by this API.
  currency: string;

  // URN of the implementation (needed to interpret 'revision' in version).
  // @since v0, may become mandatory in the future.
  implementation?: string;

  // Supported formats for registration, there must at least one.
  supported_formats: SubjectFormat[];
}

export interface RegistrationRequest {
  credit_account: string;

  // Amount to transfer
  credit_amount: AmountString;

  // Transfer types
  type: "reserve" | "kyc";

  // Public key algorithm
  alg: "EdDSA";

  // Account public key for the exchange
  account_pub: EddsaPublicKey;

  // Public key encoded inside the subject
  authorization_pub: EddsaPublicKey;

  // Signature of the account_pub key using the authorization_pub private key
  authorization_sig: EddsaSignature;

  // Whether the authorization_pub will be reused for recurrent transfers
  // Disable bounces in case of authorization_pub reuse
  recurrent: boolean;
}

// Union discriminated by the "type" field.
export type TransferSubject = SimpleSubject | UriSubject | SwissQrBillSubject;

export interface SimpleSubject {
  // Subject for system accepting large subjects
  type: "SIMPLE";

  // Amount to transfer
  credit_amount: AmountString;

  // Encoded string containing either the full key and transfer type or a
  // derived short subject
  subject: string;
}

export interface UriSubject {
  // Subject for system accepting prepared payments
  type: "URI";

  // Amount to transfer
  credit_amount: AmountString;

  // Prepared payments confirmation URI
  uri: string;
}

export interface SwissQrBillSubject {
  // Subject for Swiss QR Bill
  type: "CH_QR_BILL";

  // Amount to transfer
  credit_amount: AmountString;

  // 27-digit QR Reference number
  qr_reference_number: string;
}

export interface RegistrationResponse {
  // The transfer subject encoded in all supported formats
  subjects: TransferSubject[];

  // Expiration date after which this subject is expected to be reused
  expiration: Timestamp;
}

export interface Unregistration {
  // Current timestamp
  timestamp: TalerProtocolTimestamp;

  // Public key used for registration
  authorization_pub: EddsaPublicKey;

  // Signature of the timestamp using the authorization_pub private key
  // Prevent replay attack
  authorization_sig: EddsaSignature;
}

export const codeForSubjectFormat =
  (): Codec<SubjectFormat> =>
    codecForEither(
      codecForConstString("SIMPLE"),
      codecForConstString("URI"),
      codecForConstString("CH_QR_BILL"),
    );

export const codecForPreparedTransferConfig =
  (): Codec<PreparedTransferConfig> =>
    buildCodecForObject<PreparedTransferConfig>()
      .property("currency", codecForString())
      .property("implementation", codecOptional(codecForString()))
      .property("name", codecForConstString("taler-prepared-transfer"))
      .property("supported_formats", codecForList(codeForSubjectFormat()))
      .property("version", codecForString())
      .build("TalerPreparedTransferApi.PreparedTransferConfig");

export const codecForRegistrationRequest =
  (): Codec<RegistrationRequest> =>
    buildCodecForObject<RegistrationRequest>()
      .property("credit_amount", codecForAmountString())
      .property(
        "type",
        codecForEither(
          codecForConstString("reserve"),
          codecForConstString("kyc"),
        ),
      )
      .property("credit_account", codecForString())
      .property("alg", codecForEither(codecForConstString("EdDSA")))
      .property("account_pub", codecForEddsaPublicKey())
      .property("authorization_pub", codecForEddsaPublicKey())
      .property("authorization_sig", codecForEddsaSignature())
      .property("recurrent", codecForBoolean())
      .build("TalerWireGatewayApi.RegistrationRequest");

export const codecForTransferSubject =
  (): Codec<TransferSubject> =>
    buildCodecForUnion<TransferSubject>()
      .discriminateOn("type")
      .alternative("SIMPLE", codecForSimpleSubject())
      .alternative("URI", codecForUriSubject())
      .alternative("CH_QR_BILL", codecForSwissQrBillSubject())
      .build("TalerPreparedTransferApi.TransferSubject");

export const codecForSimpleSubject =
  (): Codec<SimpleSubject> =>
    buildCodecForObject<SimpleSubject>()
      .property("type", codecForConstString("SIMPLE"))
      .property("credit_amount", codecForAmountString())
      .property("subject", codecForString())
      .build("TalerPreparedTransferApi.SimpleSubject");

export const codecForUriSubject =
  (): Codec<UriSubject> =>
    buildCodecForObject<UriSubject>()
      .property("type", codecForConstString("URI"))
      .property("credit_amount", codecForAmountString())
      .property("uri", codecForString())
      .build("TalerPreparedTransferApi.UriSubject");

export const codecForSwissQrBillSubject =
  (): Codec<SwissQrBillSubject> =>
    buildCodecForObject<SwissQrBillSubject>()
      .property("type", codecForConstString("CH_QR_BILL"))
      .property("credit_amount", codecForAmountString())
      .property("qr_reference_number", codecForString())
      .build("TalerPreparedTransferApi.SwissQrBillSubject");

export const codecForRegistrationResponse =
  (): Codec<RegistrationResponse> =>
    buildCodecForObject<RegistrationResponse>()
      .property("subjects", codecForList(codecForTransferSubject()))
      .property("expiration", codecForTimestamp)
      .build("TalerWireGatewayApi.RegistrationResponse");

export const codecForUnregistration =
  (): Codec<Unregistration> =>
    buildCodecForObject<Unregistration>()
      .property("timestamp", codecForTimestamp)
      .property("authorization_pub", codecForEddsaPublicKey())
      .property("authorization_sig", codecForEddsaSignature())
      .build("TalerPreparedTransferApi.Unregistration");
