/** Native tables that contain wallet records (not schema bookkeeping). */
export const NATIVE_DATA_TABLES = [
  ...SQLITE_BASELINE_SCHEMA.matchAll(/CREATE TABLE IF NOT EXISTS (\w+)/g),
]
  .map((m) => m[1])
  .filter((name) => !NON_DATA_TABLES.includes(name));
