export class NotImplementedError extends Error {
  constructor(method: string) {
    super(`sqlite DAL: ${method} is not implemented yet`);
  }
}

/** Encode an optional boolean the way sqlite wants it. */
function boolToDb(b: boolean | undefined): number | null {
  if (b === undefined) return null;
  return b ? 1 : 0;
}

function dbToBool(v: Sqlite3Value | undefined): boolean {
  return v === 1 || v === 1n;
}

function dbToOptBool(v: Sqlite3Value | undefined): boolean | undefined {
  if (v == null) return undefined;
  return dbToBool(v);
}

function num(v: Sqlite3Value | undefined): number {
  return Number(v);
}

/**
 * Restore a branded timestamp read back from the database.
 *
 * DbProtocolTimestamp and DbPreciseTimestamp are compile-time brands over a
 * microsecond number: there is nothing to convert at runtime.  The brand
 * exists to stop the two being mixed up in business logic, not to prevent
 * construction, so re-applying it at the deserialisation boundary is the one
 * place an assertion is legitimate.  Keeping it in a single named helper means
 * it cannot spread into the mapping code.
 */
function dbTimestamp<T extends DbProtocolTimestamp | DbPreciseTimestamp>(
  v: Sqlite3Value | undefined,
): T {
  return Number(v) as T;
}

/**
 * Restore a branded AmountString read back from the database.
 *
 * Same reasoning as {@link dbTimestamp}: the brand is a compile-time marker
 * over a string, and the deserialisation boundary is where it is reapplied.
 */
function dbAmount(v: Sqlite3Value | undefined): AmountString {
  return v as AmountString;
}

function optNum(v: Sqlite3Value | undefined): number | undefined {
  return v == null ? undefined : Number(v);
}

function str(v: Sqlite3Value | undefined): string {
  return v as string;
}

function optStr(v: Sqlite3Value | undefined): string | undefined {
  return v == null ? undefined : (v as string);
}

/**
 * Encode a Crockford base32 record field for a BLOB column.
 *
 * Applied at the individual field mapping, never folded into a shared row
 * builder: when a record field eventually becomes Uint8Array end to end, that
 * one line loses its call and nothing else moves.
 */
function crockToDb(v: string): Uint8Array {
  return decodeCrock(v);
}

function optCrockToDb(v: string | undefined | null): Uint8Array | null {
  return v == null ? null : decodeCrock(v);
}

/**
 * Decode a BLOB column back into the Crockford string the record exposes.
 *
 * Throws rather than coercing if the column came back as TEXT: that means a
 * write path stored a string into a BLOB column, which otherwise stays
 * invisible until a lookup silently matches nothing.
 */
function dbToCrock(v: Sqlite3Value | undefined): string {
  if (!(v instanceof Uint8Array)) {
    throw Error(
      `expected a BLOB column, got ${typeof v}; a write path is storing` +
        ` TEXT into a BLOB column`,
    );
  }
  return encodeCrock(v);
}

function dbToOptCrock(v: Sqlite3Value | undefined): string | undefined {
  return v == null ? undefined : dbToCrock(v);
}

/** Stable map key for a BLOB value. */
function blobKey(v: Uint8Array): string {
  let out = "";
  for (let i = 0; i < v.length; i++) {
    out += v[i].toString(16).padStart(2, "0");
  }
  return out;
}

function jsonToDb(v: unknown): string {
  return JSON.stringify(v);
}

function dbToJson<T>(v: Sqlite3Value | undefined): T {
  return JSON.parse(v as string) as T;
}

function dbToOptJson<T>(v: Sqlite3Value | undefined): T | undefined {
  return v == null ? undefined : (JSON.parse(v as string) as T);
}

