  reserves: "reserves",
  exchanges: "exchanges",
  exchangeDetails: "exchange_details",
  exchangeSignKeys: "exchange_sign_keys",
  denominationFamilies: "denomination_families",
  denominations: "denominations",
  withdrawalGroups: "withdrawal_groups",
  purchases: "purchases",
  refreshGroups: "refresh_groups",
