  /**
   * Scan a family in expiry order and stop at the first record the caller
   * accepts.
   *
   * The helper protocol has no cursor, so this pages with LIMIT and a keyset
   * continuation.  denom_pub_hash is part of the ordering and of the
   * continuation predicate: rows can share a stamp_expire_withdraw, and a
   * strictly-greater continuation on expiry alone would skip the siblings.
   *
   * The batch size is the read amplification for a single lookup, so it is
   * deliberately small.  The conformance suite asserts the record count stays
   * bounded.
   */
  async findDenominationByFamilyFromExpiry(
    denominationFamilySerial: number,
    minStampExpireWithdraw: DbProtocolTimestamp,
    match: (d: WalletDenomination) => boolean,
  ): Promise<WalletDenomination | undefined> {
    const batchSize = 1;
    let afterExpiry: number = minStampExpireWithdraw;
    // The cursor stays in the column's own representation (a BLOB now) and
    // is fed straight back into the next query.  Decoding it to a string and
    // re-encoding would be pointless work, and binding the string form would
    // silently match nothing.
    let afterHash: Uint8Array | undefined = undefined;
    while (true) {
      const rows: ResultRow[] =
        afterHash === undefined
          ? await this.all(
              "SELECT * FROM denominations" +
                " WHERE denomination_family_serial = $serial" +
                "   AND stamp_expire_withdraw >= $expiry" +
                " ORDER BY stamp_expire_withdraw, denom_pub_hash" +
                " LIMIT $limit",
              {
                serial: denominationFamilySerial,
                expiry: afterExpiry,
                limit: batchSize,
              },
            )
          : await this.all(
              "SELECT * FROM denominations" +
                " WHERE denomination_family_serial = $serial" +
                "   AND (stamp_expire_withdraw, denom_pub_hash) > ($expiry, $hash)" +
                " ORDER BY stamp_expire_withdraw, denom_pub_hash" +
                " LIMIT $limit",
              {
                serial: denominationFamilySerial,
                expiry: afterExpiry,
                hash: afterHash,
                limit: batchSize,
              },
            );
      if (rows.length === 0) {
        return undefined;
      }
      for (const row of rows) {
        const d = this.rowToDenomination(row);
        if (match(d)) {
          return d;
        }
      }
      const last = rows[rows.length - 1];
      afterExpiry = num(last.stamp_expire_withdraw);
      const lastHash = last.denom_pub_hash;
      if (!(lastHash instanceof Uint8Array)) {
        throw Error("denominations.denom_pub_hash must be a BLOB column");
      }
      afterHash = lastHash;
    }
  }

