  async upsertExchangeDetails(rec: WalletExchangeDetails): Promise<number> {
    const names =
      "exchange_base_url, master_public_key, currency, auditors," +
      " protocol_version_range, tiny_amount, reserve_closing_delay," +
      " shopping_url, global_fees, wire_info, age_mask," +
      " wallet_balance_limits, hard_limits, zero_limits," +
      " bank_compliance_language, default_peer_push_expiration";
    const values =
      "$url, $mpk, $cur, $aud, $pvr, $tiny, $rcd, $surl, $gf, $wi, $am," +
      " $wbl, $hl, $zl, $bcl, $dppe";
    const cols = this.exchangeDetailsCols(rec);
    if (rec.rowId != null) {
      await this.run(
        `INSERT INTO exchange_details (row_id, ${names})` +
          ` VALUES ($row_id, ${values})` +
          " ON CONFLICT(row_id) DO UPDATE SET" +
          "   exchange_base_url = excluded.exchange_base_url," +
          "   master_public_key = excluded.master_public_key," +
          "   currency = excluded.currency," +
          "   auditors = excluded.auditors," +
          "   protocol_version_range = excluded.protocol_version_range," +
          "   tiny_amount = excluded.tiny_amount," +
          "   reserve_closing_delay = excluded.reserve_closing_delay," +
          "   shopping_url = excluded.shopping_url," +
          "   global_fees = excluded.global_fees," +
          "   wire_info = excluded.wire_info," +
          "   age_mask = excluded.age_mask," +
          "   wallet_balance_limits = excluded.wallet_balance_limits," +
          "   hard_limits = excluded.hard_limits," +
          "   zero_limits = excluded.zero_limits," +
          "   bank_compliance_language = excluded.bank_compliance_language," +
          "   default_peer_push_expiration =" +
          "     excluded.default_peer_push_expiration",
        { row_id: rec.rowId, ...cols },
      );
      return rec.rowId;
    }
    const res = await this.run(
      `INSERT INTO exchange_details (${names}) VALUES (${values})`,
      cols,
    );
    return Number(res.lastInsertRowid);
  }

