  /**
   * Split wgInfo into its stored columns.
   *
   * talerWithdrawUri is deliberately removed from the JSON payload: the
   * column is the only copy, so the indexed value and the payload cannot
   * drift apart.  {@link rowToWithdrawalGroup} puts it back.
   */
  private wgInfoToCols(wgInfo: WgInfo) {
    const cols = {
      wtype: wgInfo.withdrawalType,
      uri: null as string | null,
      cpriv: null as Uint8Array | null,
      binfo: null as string | null,
      eca: null as string | null,
    };
    switch (wgInfo.withdrawalType) {
      case WithdrawalRecordType.BankIntegrated: {
        const { talerWithdrawUri, ...rest } = wgInfo.bankInfo;
        cols.uri = talerWithdrawUri;
        cols.binfo = jsonToDb(rest);
        cols.eca =
          wgInfo.exchangeCreditAccounts === undefined
            ? null
            : jsonToDb(wgInfo.exchangeCreditAccounts);
        break;
      }
      case WithdrawalRecordType.BankManual:
        cols.eca =
          wgInfo.exchangeCreditAccounts === undefined
            ? null
            : jsonToDb(wgInfo.exchangeCreditAccounts);
        break;
      case WithdrawalRecordType.PeerPullCredit:
        cols.cpriv = crockToDb(wgInfo.contractPriv);
        break;
      case WithdrawalRecordType.PeerPushCredit:
      case WithdrawalRecordType.Recoup:
        break;
    }
    return cols;
  }

  private rowToWgInfo(row: ResultRow): WgInfo {
    const wtype = str(row.withdrawal_type) as WithdrawalRecordType;
    switch (wtype) {
      case WithdrawalRecordType.BankIntegrated: {
        const rest = dbToJson<Omit<ReserveBankInfo, "talerWithdrawUri">>(
          row.bank_info,
        );
        const wg: WgInfoBankIntegrated = {
          withdrawalType: WithdrawalRecordType.BankIntegrated,
          bankInfo: {
            ...rest,
            // Re-inserted from the column, which is the only copy.
            talerWithdrawUri: str(row.taler_withdraw_uri),
          },
          ...(row.exchange_credit_accounts != null
            ? {
                exchangeCreditAccounts: dbToJson(row.exchange_credit_accounts),
              }
            : undefined),
        };
        return wg;
      }
      case WithdrawalRecordType.BankManual: {
        const wg: WgInfoBankManual = {
          withdrawalType: WithdrawalRecordType.BankManual,
          ...(row.exchange_credit_accounts != null
            ? {
                exchangeCreditAccounts: dbToJson(row.exchange_credit_accounts),
              }
            : undefined),
        };
        return wg;
      }
      case WithdrawalRecordType.PeerPullCredit: {
        const wg: WgInfoBankPeerPull = {
          withdrawalType: WithdrawalRecordType.PeerPullCredit,
          contractPriv: dbToCrock(row.contract_priv),
        };
        return wg;
      }
      case WithdrawalRecordType.PeerPushCredit: {
        const wg: WgInfoBankPeerPush = {
          withdrawalType: WithdrawalRecordType.PeerPushCredit,
        };
        return wg;
      }
      case WithdrawalRecordType.Recoup: {
        const wg: WgInfoBankRecoup = {
          withdrawalType: WithdrawalRecordType.Recoup,
        };
        return wg;
      }
    }
  }

