  /**
   * Allocate a stable, per-type local number once.  The mapping is not tied
   * to transactions_meta because that view is periodically rebuilt.
   */
  private async ensureLocalTransactionIdentifier(
    transactionId: string,
  ): Promise<void> {
    const existing = await this.first(
      "SELECT 1 FROM transaction_local_ids WHERE transaction_id = $id",
      { id: transactionId },
    );
    if (existing != null) {
      return;
    }
    const [prefix, transactionType] = transactionId.split(":", 3);
    if (prefix !== "txn" || transactionType == null || transactionType === "") {
      throw Error(`invalid transaction identifier '${transactionId}'`);
    }
    await this.run(
      "INSERT OR IGNORE INTO transaction_local_id_counters" +
        " (transaction_type, next_ident) VALUES ($type, 1)",
      { type: transactionType },
    );
    const counter = await this.first(
      "SELECT next_ident FROM transaction_local_id_counters" +
        " WHERE transaction_type = $type",
      { type: transactionType },
    );
    const localIdent = num(counter?.next_ident);
    await this.run(
      "INSERT INTO transaction_local_ids" +
        " (transaction_id, transaction_type, local_ident)" +
        " VALUES ($id, $type, $localIdent)",
      { id: transactionId, type: transactionType, localIdent },
    );
    await this.run(
      "UPDATE transaction_local_id_counters SET next_ident = next_ident + 1" +
        " WHERE transaction_type = $type",
      { type: transactionType },
    );
  }

