  async getLocalTransactionIdentifiers(
    transactionIds: string[],
  ): Promise<Map<string, string>> {
    const result = new Map<string, string>();
    // SQLite commonly limits a statement to 999 bind parameters.  Chunks keep
    // a large transaction history to a handful of indexed lookups.
    for (let start = 0; start < transactionIds.length; start += 500) {
      const ids = transactionIds.slice(start, start + 500);
      const params: Record<string, string> = {};
      const placeholders = ids.map((id, i) => {
        const name = `id${i}`;
        params[name] = id;
        return `$${name}`;
      });
      const rows = await this.all(
        "SELECT transaction_id, local_ident FROM transaction_local_ids" +
          ` WHERE transaction_id IN (${placeholders.join(", ")})`,
        params,
      );
      for (const row of rows) {
        result.set(str(row.transaction_id), String(row.local_ident));
      }
    }
    return result;
  }

  async getTransactionIdByLocalIdentifier(
    transactionType: string,
    localIdent: string,
  ): Promise<string | undefined> {
    // Integer comparison deliberately accepts the canonical decimal strings
    // emitted by the wallet.  Future local-ID schemes can use another
    // backend without exposing that storage detail in the API.
    const row = await this.first(
      "SELECT transaction_id FROM transaction_local_ids" +
        " WHERE transaction_type = $type AND local_ident = $localIdent",
      { type: transactionType, localIdent },
    );
    return row == null ? undefined : str(row.transaction_id);
  }

