  async getTransactionMetaAtTimestamp(
    timestamp: DbPreciseTimestamp,
  ): Promise<WalletTransactionMeta | undefined> {
    // Ties broken by transaction_id, so "the record at this timestamp" is
    // deterministic rather than whatever the storage engine returns first.
    const row = await this.first(
      "SELECT * FROM transactions_meta WHERE timestamp = $ts" +
        " ORDER BY transaction_id LIMIT 1",
      { ts: timestamp },
    );
    return row ? this.rowToTransactionMeta(row) : undefined;
  }

  async getTransactionMetaBefore(
    timestamp: DbPreciseTimestamp,
  ): Promise<WalletTransactionMeta | undefined> {
    // The IndexedDB version reads the whole range and takes the last entry;
    // this asks for that entry directly.  Inclusive upper bound, matching
    // KeyRange.upperBound(timestamp, false).
    const row = await this.first(
      "SELECT * FROM transactions_meta WHERE timestamp <= $ts" +
        " ORDER BY timestamp DESC, transaction_id DESC LIMIT 1",
      { ts: timestamp },
    );
    return row ? this.rowToTransactionMeta(row) : undefined;
  }

  async getTransactionMetaAfter(
    timestamp: DbPreciseTimestamp,
  ): Promise<WalletTransactionMeta | undefined> {
    const row = await this.first(
      "SELECT * FROM transactions_meta WHERE timestamp >= $ts" +
        " ORDER BY timestamp, transaction_id LIMIT 1",
      { ts: timestamp },
    );
    return row ? this.rowToTransactionMeta(row) : undefined;
  }

  async listTransactionMetaByTimestamp(req: {
    afterTimestamp?: DbPreciseTimestamp;
    limit?: number;
  }): Promise<WalletTransactionMeta[]> {
    // afterTimestamp is exclusive, matching KeyRange.lowerBound(ts, true).
    const where = req.afterTimestamp != null ? " WHERE timestamp > $after" : "";
    const limit = req.limit != null ? " LIMIT $limit" : "";
    const rows = await this.all(
      `SELECT * FROM transactions_meta${where}` +
        ` ORDER BY timestamp, transaction_id${limit}`,
      {
        ...(req.afterTimestamp != null ? { after: req.afterTimestamp } : {}),
        ...(req.limit != null ? { limit: req.limit } : {}),
      },
    );
    return rows.map((r) => this.rowToTransactionMeta(r));
  }

  async listTransactionMetaPage(req: {
    cursor?: WalletTransactionMetaCursor;
    direction: "forward" | "backward";
    limit: number;
  }): Promise<WalletTransactionMeta[]> {
    const backwards = req.direction === "backward";
    const comparison = backwards ? "<" : ">";
    const ordering = backwards ? " DESC" : "";
    const where = req.cursor
      ? ` WHERE (timestamp, transaction_id) ${comparison} ($ts, $id)`
      : "";
    const rows = await this.all(
      `SELECT * FROM transactions_meta${where}` +
        ` ORDER BY timestamp${ordering}, transaction_id${ordering}` +
        " LIMIT $limit",
      {
        ...(req.cursor
          ? { ts: req.cursor.timestamp, id: req.cursor.transactionId }
          : {}),
        limit: req.limit,
      },
    );
    return rows.map((r) => this.rowToTransactionMeta(r));
  }

  async listTransactionMetaByStatus(req: {
    onlyActive: boolean;
  }): Promise<WalletTransactionMeta[]> {
    const rows = req.onlyActive
      ? await this.all(
          "SELECT * FROM transactions_meta WHERE status BETWEEN $lo AND $hi" +
            " ORDER BY status, transaction_id",
          {
            lo: OPERATION_STATUS_NONFINAL_FIRST,
            hi: OPERATION_STATUS_NONFINAL_LAST,
          },
        )
      : await this.all(
          "SELECT * FROM transactions_meta ORDER BY status, transaction_id",
        );
    return rows.map((r) => this.rowToTransactionMeta(r));
  }

