  // --------------------------------------------------------- purchases

  /**
   * Rebuild a purchase from its row plus its exchange rows.
   *
   * Takes the exchange list separately because it lives in a junction table:
   * that table is the only copy, so it has to be read to reconstruct the
   * record.
   */
  private rowToPurchase(
    row: ResultRow,
    exchanges: string[] | undefined,
  ): WalletPurchase {
    const download = dbToOptJson<WalletProposalDownloadInfo>(row.download);
    if (download && row.download_fulfillment_url != null) {
      // Re-inserted from the column, which is the only copy.
      download.fulfillmentUrl = str(row.download_fulfillment_url);
    }
    return {
      proposalId: str(row.proposal_id),
      orderId: str(row.order_id),
      merchantBaseUrl: str(row.merchant_base_url),
      claimToken: optStr(row.claim_token),
      downloadSessionId: optStr(row.download_session_id),
      repurchaseProposalId: optStr(row.repurchase_proposal_id),
      purchaseStatus: num(row.purchase_status),
      noncePriv: dbToCrock(row.nonce_priv),
      noncePub: dbToCrock(row.nonce_pub),
      secretSeed: dbToOptCrock(row.secret_seed),
      download,
      payInfo: dbToOptJson(row.pay_info),
      timestampFirstSuccessfulPay:
        row.timestamp_first_successful_pay == null
          ? undefined
          : dbTimestamp(row.timestamp_first_successful_pay),
      merchantPaySig: dbToOptCrock(row.merchant_pay_sig),
      posConfirmation: optStr(row.pos_confirmation),
      shared: dbToBool(row.shared),
      timestamp: dbTimestamp(row.timestamp),
      timestampAccept:
        row.timestamp_accept == null
          ? undefined
          : dbTimestamp(row.timestamp_accept),
      timestampLastRefundStatus:
        row.timestamp_last_refund_status == null
          ? undefined
          : dbTimestamp(row.timestamp_last_refund_status),
      lastSessionId: optStr(row.last_session_id),
      autoRefundDeadline:
        row.auto_refund_deadline == null
          ? undefined
          : dbTimestamp(row.auto_refund_deadline),
      refundAmountAwaiting:
        row.refund_amount_awaiting == null
          ? undefined
          : dbAmount(row.refund_amount_awaiting),
      ...(exchanges !== undefined ? { exchanges } : undefined),
      ...(row.abort_refresh_group_id != null
        ? { abortRefreshGroupId: str(row.abort_refresh_group_id) }
        : undefined),
      ...(row.abort_reason != null
        ? { abortReason: dbToJson(row.abort_reason) }
        : undefined),
      ...(row.fail_reason != null
        ? { failReason: dbToJson(row.fail_reason) }
        : undefined),
      ...(row.choice_index != null
        ? { choiceIndex: num(row.choice_index) }
        : undefined),
      ...(row.pending_removed_coin_pubs != null
        ? { pendingRemovedCoinPubs: dbToJson(row.pending_removed_coin_pubs) }
        : undefined),
      ...(row.donau_output_index != null
        ? { donauOutputIndex: num(row.donau_output_index) }
        : undefined),
      ...(row.donau_base_url != null
        ? { donauBaseUrl: str(row.donau_base_url) }
        : undefined),
      ...(row.donau_amount != null
        ? { donauAmount: dbAmount(row.donau_amount) }
        : undefined),
      ...(row.donau_tax_id_hash != null
        ? { donauTaxIdHash: dbToCrock(row.donau_tax_id_hash) }
        : undefined),
      ...(row.donau_tax_id_salt != null
        ? { donauTaxIdSalt: str(row.donau_tax_id_salt) }
        : undefined),
      ...(row.donau_tax_id != null
        ? { donauTaxId: str(row.donau_tax_id) }
        : undefined),
      ...(row.donau_year != null
        ? { donauYear: num(row.donau_year) }
        : undefined),
      ...(row.created_from_shared != null
        ? { createdFromShared: dbToBool(row.created_from_shared) }
        : undefined),
      ...(row.timestamp_expired != null
        ? { timestampExpired: dbTimestamp(row.timestamp_expired) }
        : undefined),
      ...(row.taler_uri != null ? { talerUri: str(row.taler_uri) } : undefined),
    };
  }

  private async loadPurchaseExchanges(
    proposalId: string,
  ): Promise<string[] | undefined> {
    const rows = await this.all(
      "SELECT exchange_base_url FROM purchase_exchanges" +
        " WHERE proposal_id = $id ORDER BY idx",
      { id: proposalId },
    );
    // No rows means the field was absent, not an empty array: an empty array
    // would have produced no rows either, but the record type makes the
    // field optional and the wallet never stores an empty list.
    return rows.length === 0
      ? undefined
      : rows.map((r) => str(r.exchange_base_url));
  }

  private async hydratePurchases(rows: ResultRow[]): Promise<WalletPurchase[]> {
    if (rows.length === 0) {
      return [];
    }
    const exchangesByProposal = new Map<string, string[]>();
    const proposalIds = rows.map((r) => str(r.proposal_id));
    for (let offset = 0; offset < proposalIds.length; offset += 400) {
      const chunk = proposalIds.slice(offset, offset + 400);
      const params: Record<string, string> = {};
      const placeholders = chunk.map((id, i) => {
        params[`id${i}`] = id;
        return `$id${i}`;
      });
      const exchangeRows = await this.all(
        "SELECT proposal_id, exchange_base_url FROM purchase_exchanges" +
          ` WHERE proposal_id IN (${placeholders.join(", ")})` +
          " ORDER BY proposal_id, idx",
        params,
      );
      for (const exchangeRow of exchangeRows) {
        const proposalId = str(exchangeRow.proposal_id);
        const exchanges = exchangesByProposal.get(proposalId) ?? [];
        exchanges.push(str(exchangeRow.exchange_base_url));
        exchangesByProposal.set(proposalId, exchanges);
      }
    }
    return rows.map((row) =>
      this.rowToPurchase(row, exchangesByProposal.get(str(row.proposal_id))),
    );
  }

