  async upsertPurchase(rec: WalletPurchase): Promise<void> {
    // download is stored without its fulfillmentUrl; the column holds it.
    let downloadJson: string | null = null;
    let fulfillmentUrl: string | null = null;
    if (rec.download) {
      const { fulfillmentUrl: fu, ...rest } = rec.download;
      fulfillmentUrl = fu ?? null;
      downloadJson = jsonToDb(rest);
    }
    await this.run(
      `INSERT INTO purchases (
         proposal_id, order_id, merchant_base_url, claim_token,
         download_session_id, repurchase_proposal_id, purchase_status,
         abort_refresh_group_id, abort_reason, fail_reason, nonce_priv,
         nonce_pub, choice_index, secret_seed, download,
         download_fulfillment_url, pay_info, pending_removed_coin_pubs,
         timestamp_first_successful_pay, merchant_pay_sig, pos_confirmation,
         donau_output_index, donau_base_url, donau_amount,
         donau_tax_id_hash, donau_tax_id_salt, donau_tax_id, donau_year,
         shared, created_from_shared, timestamp, timestamp_accept,
         timestamp_last_refund_status, timestamp_expired, last_session_id,
         auto_refund_deadline, refund_amount_awaiting, taler_uri
       ) VALUES (
         $id, $oid, $url, $ct, $dsid, $rpid, $status, $argi, $abort, $fail,
         $npriv, $npub, $ci, $seed, $dl, $ffu, $pi, $prcp, $tfsp, $mps,
         $posc, $doi, $dbu, $damt, $dtih, $dtis, $dti, $dy, $shared,
         $cfs, $ts, $tsa, $tslrs, $tse, $lsid, $ard, $raa, $turi
       )
       ON CONFLICT(proposal_id) DO UPDATE SET
         order_id = excluded.order_id,
         merchant_base_url = excluded.merchant_base_url,
         claim_token = excluded.claim_token,
         download_session_id = excluded.download_session_id,
         repurchase_proposal_id = excluded.repurchase_proposal_id,
         purchase_status = excluded.purchase_status,
         abort_refresh_group_id = excluded.abort_refresh_group_id,
         abort_reason = excluded.abort_reason,
         fail_reason = excluded.fail_reason,
         nonce_priv = excluded.nonce_priv,
         nonce_pub = excluded.nonce_pub,
         choice_index = excluded.choice_index,
         secret_seed = excluded.secret_seed,
         download = excluded.download,
         download_fulfillment_url = excluded.download_fulfillment_url,
         pay_info = excluded.pay_info,
         pending_removed_coin_pubs = excluded.pending_removed_coin_pubs,
         timestamp_first_successful_pay =
           excluded.timestamp_first_successful_pay,
         merchant_pay_sig = excluded.merchant_pay_sig,
         pos_confirmation = excluded.pos_confirmation,
         donau_output_index = excluded.donau_output_index,
         donau_base_url = excluded.donau_base_url,
         donau_amount = excluded.donau_amount,
         donau_tax_id_hash = excluded.donau_tax_id_hash,
         donau_tax_id_salt = excluded.donau_tax_id_salt,
         donau_tax_id = excluded.donau_tax_id,
         donau_year = excluded.donau_year,
         shared = excluded.shared,
         created_from_shared = excluded.created_from_shared,
         timestamp = excluded.timestamp,
         timestamp_accept = excluded.timestamp_accept,
         timestamp_last_refund_status =
           excluded.timestamp_last_refund_status,
         timestamp_expired = excluded.timestamp_expired,
         last_session_id = excluded.last_session_id,
         auto_refund_deadline = excluded.auto_refund_deadline,
         refund_amount_awaiting = excluded.refund_amount_awaiting,
         taler_uri = excluded.taler_uri`,
      {
        id: rec.proposalId,
        oid: rec.orderId,
        url: rec.merchantBaseUrl,
        ct: rec.claimToken ?? null,
        dsid: rec.downloadSessionId ?? null,
        rpid: rec.repurchaseProposalId ?? null,
        status: rec.purchaseStatus,
        argi: rec.abortRefreshGroupId ?? null,
        abort: rec.abortReason === undefined ? null : jsonToDb(rec.abortReason),
        fail: rec.failReason === undefined ? null : jsonToDb(rec.failReason),
        npriv: crockToDb(rec.noncePriv),
        npub: crockToDb(rec.noncePub),
        ci: rec.choiceIndex ?? null,
        seed: optCrockToDb(rec.secretSeed),
        dl: downloadJson,
        ffu: fulfillmentUrl,
        pi: rec.payInfo === undefined ? null : jsonToDb(rec.payInfo),
        prcp:
          rec.pendingRemovedCoinPubs === undefined
            ? null
            : jsonToDb(rec.pendingRemovedCoinPubs),
        tfsp: rec.timestampFirstSuccessfulPay ?? null,
        mps: optCrockToDb(rec.merchantPaySig),
        posc: rec.posConfirmation ?? null,
        doi: rec.donauOutputIndex ?? null,
        dbu: rec.donauBaseUrl ?? null,
        damt: rec.donauAmount ?? null,
        dtih: optCrockToDb(rec.donauTaxIdHash),
        dtis: rec.donauTaxIdSalt ?? null,
        dti: rec.donauTaxId ?? null,
        dy: rec.donauYear ?? null,
        shared: boolToDb(rec.shared),
        cfs: boolToDb(rec.createdFromShared),
        ts: rec.timestamp,
        tsa: rec.timestampAccept ?? null,
        tslrs: rec.timestampLastRefundStatus ?? null,
        tse: rec.timestampExpired ?? null,
        lsid: rec.lastSessionId ?? null,
        ard: rec.autoRefundDeadline ?? null,
        raa: rec.refundAmountAwaiting ?? null,
        turi: rec.talerUri ?? null,
      },
    );
    const oldExchanges = await this.loadPurchaseExchanges(rec.proposalId);
    const newExchanges = rec.exchanges;
    const oldList = oldExchanges ?? [];
    const newList = newExchanges ?? [];
    if (
      oldList.length === newList.length &&
      oldList.every((url, i) => url === newList[i])
    ) {
      return;
    }
    await this.run("DELETE FROM purchase_exchanges WHERE proposal_id = $id", {
      id: rec.proposalId,
    });
    if (newExchanges?.length) {
      const params: Record<string, string | number> = { id: rec.proposalId };
      const values = newExchanges.map((url, i) => {
        params[`idx${i}`] = i;
        params[`url${i}`] = url;
        return `($id, $idx${i}, $url${i})`;
      });
      await this.run(
        "INSERT INTO purchase_exchanges (proposal_id, idx, exchange_base_url)" +
          ` VALUES ${values.join(", ")}`,
        params,
      );
    }
  }

