/**
 * @fileoverview
 * Implementation of taldir in wallet-core.
 */

import {
  Logger,
  TaldirLookupRequest,
  TalerDirectoryInstanceHttpClient,
  encodeCrock,
  TaldirLookupResponse,
  sha512,
  HttpStatusCode,
  TaldirRegistrationRequest,
  TaldirRegistrationResponse,
  TaldirRegistrationCompletionRequest,
  EmptyObject,
  TalerError,
  TalerErrorCode,
} from "@gnu-taler/taler-util";
import { WalletExecutionContext } from "./wallet.js";

const logger = new Logger("taldir.ts");

function createHAliasBuffer(aliasType: string, alias: string): Uint8Array {
  const encoder = new TextEncoder();
  const typeBytes = encoder.encode(aliasType);
  const aliasBytes = encoder.encode(alias);
  const payloadLength = typeBytes.length + aliasBytes.length;
  const totalBuffer = new Uint8Array(4 + payloadLength);
  const view = new DataView(totalBuffer.buffer);
  view.setUint32(0, payloadLength, false); // 'false' specifies Big-Endian / NBO
  totalBuffer.set(typeBytes, 4);
  totalBuffer.set(aliasBytes, 4 + typeBytes.length);
  return totalBuffer;
}

/**
 * Lookup alias
 */
export async function lookupAlias(
  wex: WalletExecutionContext,
  lookupRequest: TaldirLookupRequest,
): Promise<TaldirLookupResponse> {
  const taldirClient = new TalerDirectoryInstanceHttpClient(
    lookupRequest.taldirBaseUrl,
    wex.http,
  );
  // Refresh message size
  const resConf = await taldirClient.getConfig();
  switch (resConf.case) {
    case "ok": {
      let supported_types = resConf.body.alias_types;
      let typeFound = false;
      for (var t of supported_types) {
        if (t.name === lookupRequest.aliasType) {
          typeFound = true;
          break;
        }
      }
      if (!typeFound) {
        logger.warn(`queried type not supported by directory`);
        return {};
      }
      break;
    }
    default:
      throw TalerError.fromDetail(
        TalerErrorCode.WALLET_ALIAS_REGISTRATION_FAILED,
        { directoryBaseUrl: lookupRequest.taldirBaseUrl },
        "could not read the configuration of the directory service",
      );
  }
  // SHA-512(len($ALIASTYPE)+len($ALIAS)||$ALIASTYPE||$ALIAS)
  const hAliasBuffer = createHAliasBuffer(
    lookupRequest.aliasType,
    lookupRequest.alias,
  );
  const hAlias = encodeCrock(sha512(hAliasBuffer));
  const res = await taldirClient.lookupAlias({ hAlias: hAlias });
  switch (res.case) {
    case "ok":
      return {
        targetUri: res.body.target_uri,
      };
    case HttpStatusCode.NotFound:
      return {};
    default:
      throw TalerError.fromDetail(
        TalerErrorCode.WALLET_ALIAS_REGISTRATION_FAILED,
        { directoryBaseUrl: lookupRequest.taldirBaseUrl },
        "the directory service did not answer the alias lookup",
      );
  }
}

/**
 * Initiate registration
 */
export async function registerAlias(
  wex: WalletExecutionContext,
  registerRequest: TaldirRegistrationRequest,
): Promise<TaldirRegistrationResponse> {
  const taldirClient = new TalerDirectoryInstanceHttpClient(
    registerRequest.taldirBaseUrl,
    wex.http,
  );
  const res = await taldirClient.postRegistrationRequest({
    alias: registerRequest.alias,
    aliasType: registerRequest.aliasType,
    targetUri: registerRequest.targetUri,
    duration: registerRequest.duration,
  });
  switch (res.case) {
    case "ok":
      return res.body;
    case HttpStatusCode.NotFound:
      throw TalerError.fromDetail(
        TalerErrorCode.WALLET_ALIAS_REGISTRATION_FAILED,
        { directoryBaseUrl: registerRequest.taldirBaseUrl },
        `the directory service does not support the alias type "${registerRequest.aliasType}"`,
      );
    default:
      throw TalerError.fromDetail(
        TalerErrorCode.WALLET_ALIAS_REGISTRATION_FAILED,
        { directoryBaseUrl: registerRequest.taldirBaseUrl },
        "the directory service did not accept the registration request",
      );
  }
}

/**
 * Complete
 */
export async function completeAliasRegistration(
  wex: WalletExecutionContext,
  completionRequest: TaldirRegistrationCompletionRequest,
): Promise<EmptyObject> {
  const taldirClient = new TalerDirectoryInstanceHttpClient(
    completionRequest.taldirBaseUrl,
    wex.http,
  );
  const encoder = new TextEncoder();
  const bytes1 = encoder.encode(completionRequest.challenge);
  const bytes2 = encoder.encode(completionRequest.targetUri);
  const combined = new Uint8Array(bytes1.length + bytes2.length);
  combined.set(bytes1, 0);
  combined.set(bytes2, bytes1.length);
  const solution = encodeCrock(sha512(combined));
  // SHA-512(len($ALIASTYPE)+len($ALIAS)||$ALIASTYPE||$ALIAS)
  const hAliasBuffer = createHAliasBuffer(
    completionRequest.aliasType,
    completionRequest.alias,
  );
  const hAlias = encodeCrock(sha512(hAliasBuffer));
  const res = await taldirClient.postRegistration({
    hAlias: hAlias,
    solution: solution,
  });
  switch (res.case) {
    case "ok":
      return {};
    case HttpStatusCode.NotFound:
      throw TalerError.fromDetail(
        TalerErrorCode.WALLET_ALIAS_REGISTRATION_FAILED,
        { directoryBaseUrl: completionRequest.taldirBaseUrl },
        "the directory service does not know this registration, it may have expired",
      );
    case HttpStatusCode.Forbidden:
      throw TalerError.fromDetail(
        TalerErrorCode.GENERIC_FORBIDDEN,
        {},
        "the directory service rejected the answer to the challenge",
      );
    case HttpStatusCode.TooManyRequests:
      throw TalerError.fromDetail(
        TalerErrorCode.WALLET_ALIAS_REGISTRATION_FAILED,
        { directoryBaseUrl: completionRequest.taldirBaseUrl },
        "too many attempts have been made to answer this registration challenge",
      );
    default:
      throw TalerError.fromDetail(
        TalerErrorCode.WALLET_ALIAS_REGISTRATION_FAILED,
        { directoryBaseUrl: completionRequest.taldirBaseUrl },
        "the directory service did not accept the registration",
      );
  }
}
