  async upsertGlobalCurrencyExchange(
    rec: WalletGlobalCurrencyExchange,
  ): Promise<void> {
    // The row id is generated, so putting a record that is already stored
    // would insert a second row and violate the unique index over the three
    // identifying fields, which aborts the whole transaction.
    const existing = await this.getGlobalCurrencyExchange(
      rec.currency,
      rec.exchangeBaseUrl,
      rec.exchangeMasterPub,
    );
    if (existing) {
      return;
    }
    await this.tx.globalCurrencyExchanges.put(rec);
  }

