  async deleteDenominationFamily(
    denominationFamilySerial: number,
  ): Promise<void> {
    const tx = this.tx;
    // Cascade to the denominations of that family.  There is no accessor for
    // "denominations by family" on its own, so this walks the index whose
    // first component is the family serial.
    const doomed =
      await tx.denominationsV2.indexes.byDenominationFamilySerialAndStampExpireWithdraw.getAll(
        GlobalIDB.KeyRange.bound(
          [denominationFamilySerial, Number.MIN_SAFE_INTEGER],
          [denominationFamilySerial, Number.MAX_SAFE_INTEGER],
        ),
      );
    for (const d of doomed) {
      await tx.denominationsV2.delete([d.exchangeMasterPub, d.denomPubHash]);
    }
    await tx.denominationFamilies.delete(denominationFamilySerial);
  }

