  async findDenominationByFamilyFromExpiry(
    denominationFamilySerial: number,
    minStampExpireWithdraw: DbProtocolTimestamp,
    match: (d: WalletDenomination) => boolean,
  ): Promise<WalletDenomination | undefined> {
    const tx = this.tx;
    const cursor =
      tx.denominationsV2.indexes.byDenominationFamilySerialAndStampExpireWithdraw.iter();
    // The cursor has to be positioned before it can be moved.
    const first = await cursor.current();
    if (!first.hasValue) {
      return undefined;
    }
    // Denominations without a family are not part of the index.
    const firstSerial = first.value.denominationFamilySerial;
    if (
      firstSerial == null ||
      firstSerial < denominationFamilySerial ||
      (firstSerial === denominationFamilySerial &&
        first.value.stampExpireWithdraw < minStampExpireWithdraw)
    ) {
      cursor.continue([denominationFamilySerial, minStampExpireWithdraw]);
    }
    while (true) {
      const cur = await cursor.current();
      if (!cur.hasValue) {
        return undefined;
      }
      if (cur.value.denominationFamilySerial != denominationFamilySerial) {
        // Moved past this family.
        return undefined;
      }
      if (match(cur.value)) {
        return cur.value;
      }
      cursor.continue();
    }
  }

