  async checkExchangeInScope(
    exchangeBaseUrl: string,
    scope: ScopeInfo,
    denomPubHash?: string,
  ): Promise<boolean> {
    switch (scope.type) {
      case ScopeType.Exchange: {
        return scope.url === exchangeBaseUrl;
      }
      case ScopeType.Global: {
        const exchangeDetails = await this.getExchangeDetails(exchangeBaseUrl);
        if (!exchangeDetails) {
          return false;
        }
        const gr =
          await this.tx.globalCurrencyExchanges.indexes.byCurrencyAndUrlAndPub.get(
            [
              exchangeDetails.currency,
              exchangeBaseUrl,
              exchangeDetails.masterPublicKey,
            ],
          );
        return gr != null;
      }
      case ScopeType.Auditor: {
        const exchangeDetails = await this.getExchangeDetails(exchangeBaseUrl);
        if (!exchangeDetails || exchangeDetails.currency !== scope.currency) {
          return false;
        }
        for (const auditor of exchangeDetails.auditors) {
          if (
            !auditorProvidesVerifiedTrust(auditor, {
              auditorBaseUrl: scope.url,
              denomPubHash,
            })
          ) {
            continue;
          }
          const configured =
            await this.tx.globalCurrencyAuditors.indexes.byCurrencyAndUrlAndPub.get(
              [
                exchangeDetails.currency,
                auditor.auditor_url,
                auditor.auditor_pub,
              ],
            );
          if (configured) {
            return true;
          }
        }
        return false;
      }
      case ScopeType.ExchangeLegacyKeys:
        // See checkExchangeInScopeGeneric: an entry stands for its current
        // key set, which is never a superseded one.
        return false;
      default:
        assertUnreachable(scope);
    }
  }

  async getExchangeScopeInfo(
    exchangeBaseUrl: string,
    currency: string,
    denomPubHash?: string,
  ): Promise<ScopeInfo> {
    const det = await this.getExchangeDetails(exchangeBaseUrl);
    if (!det) {
      return {
        type: ScopeType.Exchange,
        currency: currency,
        url: exchangeBaseUrl,
      };
    }
    const globalExchangeRec =
      await this.tx.globalCurrencyExchanges.indexes.byCurrencyAndUrlAndPub.get([
        det.currency,
        det.exchangeBaseUrl,
        det.masterPublicKey,
      ]);
    if (globalExchangeRec) {
      return {
        currency: det.currency,
        type: ScopeType.Global,
      };
    } else {
      for (const aud of denomPubHash == null ? [] : det.auditors) {
        if (!auditorProvidesVerifiedTrust(aud, { denomPubHash })) {
          continue;
        }
        const globalAuditorRec =
          await this.tx.globalCurrencyAuditors.indexes.byCurrencyAndUrlAndPub.get(
            [det.currency, aud.auditor_url, aud.auditor_pub],
          );
        if (globalAuditorRec) {
          return {
            currency: det.currency,
            type: ScopeType.Auditor,
            url: aud.auditor_url,
          };
        }
      }
    }
    return {
      currency: det.currency,
      type: ScopeType.Exchange,
      url: det.exchangeBaseUrl,
    };
  }
