/**
 * @fileoverview
 * Implementation of contacts management in wallet-core.
 * The details of contacts management are specified in DD48.
 */

import {
  AddContactRequest,
  ContactEntry,
  ContactListResponse,
  DeleteContactRequest,
  EmptyObject,
  Logger,
  NotificationType,
} from "@gnu-taler/taler-util";
import { WalletDbTransaction } from "./db/transaction.js";
import { WalletExecutionContext } from "./wallet.js";

const logger = new Logger("contacts.ts");

async function makeContactListItem(
  wex: WalletExecutionContext,
  tx: WalletDbTransaction,
  r: ContactEntry,
  //lastError: TalerErrorDetail | undefined,
): Promise<ContactEntry> {
  const listItem: ContactEntry = {
    alias: r.alias,
    aliasType: r.aliasType,
    mailboxBaseUri: r.mailboxBaseUri,
    mailboxAddress: r.mailboxAddress,
    source: r.source,
    petname: r.petname,
  };
  return listItem;
}

/**
 * Add contact to the database.
 */
export async function addContact(
  wex: WalletExecutionContext,
  req: AddContactRequest,
): Promise<EmptyObject> {
  await wex.runWalletDbTx(async (tx) => {
    await tx.addContact(req.contact);
    tx.notify({
      type: NotificationType.ContactAdded,
      contact: req.contact,
    });
  });
  return {};
}

/**
 * Delete contact from the database.
 */
export async function deleteContact(
  wex: WalletExecutionContext,
  req: DeleteContactRequest,
): Promise<EmptyObject> {
  await wex.runWalletDbTx(async (tx) => {
    await tx.deleteContact(req.contact.alias, req.contact.aliasType);
    tx.notify({
      type: NotificationType.ContactDeleted,
      contact: req.contact,
    });
  });
  return {};
}

/**
 * Get contacts from the database.
 */
export async function listContacts(
  wex: WalletExecutionContext,
  req: EmptyObject,
): Promise<ContactListResponse> {
  const contacts: ContactEntry[] = [];
  await wex.runWalletDbTx(async (tx) => {
    const contactsRecords = await tx.listContacts();
    for (const contactRec of contactsRecords) {
      const li = await makeContactListItem(wex, tx, contactRec);
      contacts.push(li);
    }
  });
  return { contacts: contacts };
}
