/**
 * https://developer.mozilla.org/en-US/docs/Web/JavaScript/Reference/Global_Objects/encodeURIComponent#encoding_for_rfc3986
 */
function encodeRFC3986URIComponent(str: string): string {
  return encodeURIComponent(str).replace(
    /[!'()*]/g,
    (c) => `%${c.charCodeAt(0).toString(16).toUpperCase()}`,
  );
}
const rfc3986 = encodeRFC3986URIComponent;

/**
 * Encode a value as a single taler:// URI path segment.
 *
 * "." and ".." are resolved away by the URL parser, even when percent-encoded,
 * so a component equal to either cannot be represented and is rejected rather
 * than silently erasing the preceding path.
 */
function encodeUriSegment(s: string): string {
  if (s === "." || s === "..") {
    throw Error(`cannot represent taler:// path segment ${JSON.stringify(s)}`);
  }
  // Only the characters that would break the positional/query parsing are
  // escaped, so that components without them keep their on-the-wire form.
  // Tab, LF and CR are among them because the URL parser removes them before
  // parsing, which would otherwise turn "..\t" back into a dot segment.
  return s.replace(
    /[%/?#\t\n\r]/g,
    (c) => `%${c.charCodeAt(0).toString(16).toUpperCase().padStart(2, "0")}`,
  );
}

/**
 * Decode a single taler:// URI path segment.  Falls back to the raw value for
 * input that is not valid percent-encoding, so parsing never throws on it.
 */
function decodeUriSegment(s: string): string {
  try {
    return decodeURIComponent(s);
  } catch (e) {
    return s;
  }
}

/**
 *
 * https://www.rfc-editor.org/rfc/rfc3986
 */
function createSearchParams(paramList: [string, string][]): string {
  return paramList
    .map(([key, value]) => `${rfc3986(key)}=${rfc3986(value)}`)
    .join("&");
}
