/**
 * Context for a merchant pay transaction.
 *
 * Used in every task and request handlers.
 */
export class PayMerchantTransactionContext implements TransactionContext {
  readonly transactionId: TransactionIdStr;
  readonly taskId: TaskIdStr;

  constructor(
    public wex: WalletExecutionContext,
    public proposalId: string,
  ) {
    this.transactionId = constructTransactionIdentifier({
      tag: TransactionType.Payment,
      proposalId,
    });
    this.taskId = constructTaskIdentifier({
      tag: PendingTaskType.Purchase,
      proposalId,
    });
  }

  /**
   * Function that updates the metadata of the transaction.
   *
   * Must be called each time the DB record for the transaction is updated.
   */
  async updateTransactionMeta(tx: WalletDbTransaction): Promise<void> {
    const purchaseRec = await tx.getPurchase(this.proposalId);
    if (!purchaseRec) {
      await tx.deleteTransactionMeta(this.transactionId);
      return;
    }
    if (!purchaseRec.download) {
      // Not ready yet.
      await tx.deleteTransactionMeta(this.transactionId);
      return;
    }

    await tx.upsertTransactionMeta({
      transactionId: this.transactionId,
      status: purchaseRec.purchaseStatus,
      timestamp: purchaseRec.timestamp,
      currency: purchaseRec.download?.currency ?? "UNKNOWN",
      exchanges: purchaseRec.exchanges ?? [],
    });
  }

  async lookupFullTransaction(
    tx: WalletDbTransaction,
    req?: LookupFullTransactionOpts,
  ): Promise<Transaction | undefined> {
    const proposalId = this.proposalId;
    const purchaseRec = await tx.getPurchase(proposalId);
    if (!purchaseRec) {
      throw makeTransactionNotFoundError(this.transactionId);
    }

    const txState = computePayMerchantTransactionState(purchaseRec);
    const unclaimedPayUri =
      purchaseRec.purchaseStatus === PurchaseStatus.DialogUnclaimed
        ? makePublicPayUri(purchaseRec)
        : undefined;
    const payOpId = TaskIdentifiers.forPay(purchaseRec);
    const payRetryRec = await tx.getOperationRetry(payOpId);
    const unk = "UNKNOWN:0";
    let nfc: boolean | undefined;
    if (purchaseRec.talerUri) {
      const uri = Result.orUndefined(TalerUris.parse(purchaseRec.talerUri));
      if (
        uri?.type === TalerUriAction.Pay ||
        uri?.type === TalerUriAction.PayTemplate
      ) {
        nfc = uri.nfc;
      }
    }
    if (!purchaseRec.download) {
      return {
        type: TransactionType.Payment,
        txState,
        unclaimedPayUri,
        stId: purchaseRec.purchaseStatus,
        scopes: [
          {
            type: ScopeType.Global,
            currency: "UNKNOWN",
          },
        ],
        txActions: computePayMerchantTransactionActions(purchaseRec),
        amountRaw: unk,
        amountEffective: unk,
        totalRefundRaw: unk,
        totalRefundEffective: unk,
        refundPending: unk,
        refunds: [],
        posConfirmation: purchaseRec.posConfirmation,
        timestamp: timestampPreciseFromDb(purchaseRec.timestamp),
        transactionId: this.transactionId,
        abortReason: purchaseRec.abortReason,
        failReason: purchaseRec.failReason,
        error: undefined,
        info: undefined,
        contractTerms: undefined,
        refundQueryActive: false,
        choiceIndex: purchaseRec.choiceIndex,
        posConfirmationViaNfc: nfc,
      };
    }

    const download = await expectProposalDownloadInTx(
      this.wex,
      tx,
      purchaseRec,
    );
    const contractData = download.contractTerms;

    const refundsInfo = await tx.getRefundGroupsByProposal(
      purchaseRec.proposalId,
    );

    let amountRaw: AmountString = "UNKNOWN:0";
    if (
      contractData.version === undefined ||
      contractData.version === MerchantContractVersion.V0
    ) {
      amountRaw = contractData.amount;
    } else if (contractData.version === MerchantContractVersion.V1) {
      const index = purchaseRec.choiceIndex;
      if (index !== undefined) {
        if (!(index in contractData.choices))
          throw Error(`invalid choice index ${index}`);
        amountRaw = contractData.choices[index].amount;
      }
    }

    let zero = Amounts.zeroOfAmount(amountRaw);
    const refundTotals = getRefundTotals(refundsInfo, zero.currency);

    const info: OrderShortInfo = {
      merchant: {
        name: contractData.merchant.name,
        address: contractData.merchant.address,
        email: contractData.merchant.email,
        jurisdiction: contractData.merchant.jurisdiction,
        website: contractData.merchant.website,
      },
      orderId: contractData.order_id,
      summary: contractData.summary,
      summary_i18n: contractData.summary_i18n,
      contractTermsHash: download.contractTermsHash,
    };

    if (contractData.fulfillment_url !== "") {
      info.fulfillmentUrl = contractData.fulfillment_url;
    }

    const refunds: RefundInfoShort[] = refundsInfo.map((r) => ({
      amountEffective: r.amountEffective,
      amountRaw: r.amountRaw,
      timestamp: TalerPreciseTimestamp.round(
        timestampPreciseFromDb(r.timestampCreated),
      ),
      transactionId: constructTransactionIdentifier({
        tag: TransactionType.Refund,
        refundGroupId: r.refundGroupId,
      }),
    }));

    const scopes = await computePayMerchantTransactionScopesInTx(
      tx,
      purchaseRec,
    );
    let amountEffective: AmountString;

    if (!purchaseRec.payInfo) {
      amountEffective = Amounts.stringify(zero);
    } else {
      amountEffective = isUnsuccessfulTransaction(txState)
        ? Amounts.stringify(zero)
        : Amounts.stringify(purchaseRec.payInfo.totalPayCost);
    }

    let contractTerms: MerchantContractTerms | undefined;
    if (req?.includeContractTerms) {
      contractTerms = download.contractTerms;
    }

    return {
      type: TransactionType.Payment,
      txState,
      unclaimedPayUri,
      stId: purchaseRec.purchaseStatus,
      scopes,
      txActions: computePayMerchantTransactionActions(purchaseRec),
      amountRaw,
      amountEffective,
      totalRefundRaw: refundTotals.raw,
      totalRefundEffective: refundTotals.effective,
      refundPending:
        purchaseRec.refundAmountAwaiting === undefined
          ? undefined
          : Amounts.stringify(purchaseRec.refundAmountAwaiting),
      refunds,
      posConfirmation: purchaseRec.posConfirmation,
      timestamp: timestampPreciseFromDb(purchaseRec.timestamp),
      transactionId: constructTransactionIdentifier({
        tag: TransactionType.Payment,
        proposalId: purchaseRec.proposalId,
      }),
      abortReason: purchaseRec.abortReason,
      failReason: purchaseRec.failReason,
      error: payRetryRec?.lastError ? payRetryRec?.lastError : undefined,
      info,
      contractTerms,
      repurchaseTransactionId:
        purchaseRec.repurchaseProposalId == null
          ? undefined
          : constructTransactionIdentifier({
              tag: TransactionType.Payment,
              proposalId: purchaseRec.repurchaseProposalId,
            }),
      refundQueryActive:
        purchaseRec.purchaseStatus === PurchaseStatus.PendingQueryingRefund,
      ...(payRetryRec?.lastError ? { error: payRetryRec.lastError } : {}),
      choiceIndex: purchaseRec.choiceIndex,
      posConfirmationViaNfc: nfc,
    };
  }

  async userDeleteTransaction(): Promise<void> {
    await this.wex.runWalletDbTx(async (tx) => {
      return this.deleteTransactionInTx(tx);
    });
  }

  async deleteTransactionInTx(
    tx: WalletDbTransaction,
    opts: {
      keepRelated?: boolean;
      causeHint?: string;
      errorInfo?: ErrorInfoSummary;
    } = {},
  ): Promise<void> {
    const [rec, h] = await this.getRecordHandle(tx);
    if (!rec) {
      return;
    }
    let relatedTransactions: WalletPurchase[] = [];
    // Automatically delete transactions that are a repurchase of this transaction,
    // as they're typically hidden.
    if (
      !opts?.keepRelated &&
      rec.download?.fulfillmentUrl &&
      rec.purchaseStatus !== PurchaseStatus.DoneRepurchaseDetected
    ) {
      const otherTransactions = await tx.getPurchasesByFulfillmentUrl(
        rec.download.fulfillmentUrl,
      );
      for (const otx of otherTransactions) {
        if (
          otx.purchaseStatus === PurchaseStatus.DoneRepurchaseDetected &&
          otx.repurchaseProposalId === rec.proposalId
        ) {
          relatedTransactions.push(otx);
        }
      }
    }
    for (const rt of relatedTransactions) {
      const otherCtx = new PayMerchantTransactionContext(
        this.wex,
        rt.proposalId,
      );
      await otherCtx.deleteTransactionInTx(tx, { keepRelated: true });
    }
    await releasePaymentTokensInTx(
      tx,
      this.transactionId,
      rec.payInfo?.payTokenSelection?.tokenPubs ?? [],
    );
    await h.update(
      undefined,
      opts.causeHint ?? "delete",
      undefined,
      opts.errorInfo,
    );
  }

  async userSuspendTransaction(): Promise<void> {
    const { wex } = this;
    wex.taskScheduler.stopShepherdTask(this.taskId);
    await wex.runWalletDbTx(async (tx) => {
      const [purchase, h] = await this.getRecordHandle(tx);
      if (!purchase) {
        throw Error("purchase not found");
      }
      const nextStatus = getPayMerchantSuspendTransition(
        purchase.purchaseStatus,
      );
      if (nextStatus === undefined) {
        return;
      }
      purchase.purchaseStatus = nextStatus;
      await h.update(purchase, "suspend");
    });
  }

  async failTransaction(
    fromSt: PurchaseStatus,
    reason?: TalerErrorDetail,
  ): Promise<void> {
    const { wex } = this;
    await wex.runWalletDbTx(async (tx) => {
      const [purchase, h] = await this.getRecordHandle(tx);
      if (purchase?.purchaseStatus != fromSt) {
        return;
      }
      purchase.purchaseStatus = PurchaseStatus.Failed;
      purchase.failReason = reason;
      await h.update(purchase, "fail");
    });
  }

  /**
   * Turn a permanent /pay failure into a custody-safe terminal failure.
   *
   * Allocated coins must first pass through the normal abort/refund recovery
   * state.  Keeping failReason set distinguishes this automatic failure from
   * a user-requested abort when recovery finishes.
   */
  async recoverFromPayFailure(reason: TalerErrorDetail): Promise<boolean> {
    const { wex } = this;
    const changed = await wex.runWalletDbTx(async (tx) => {
      const [purchase, h] = await this.getRecordHandle(tx);
      if (purchase?.purchaseStatus !== PurchaseStatus.PendingPaying) {
        return false;
      }
      purchase.abortReason = reason;
      purchase.failReason = reason;
      purchase.purchaseStatus = PurchaseStatus.AbortingWithRefund;
      await h.update(purchase, "pay-failure-recovery");
      return true;
    });
    if (changed) {
      await wex.taskScheduler.resetTask(this.taskId);
    }
    return changed;
  }

  async userAbortTransaction(reason?: TalerErrorDetail): Promise<void> {
    const { wex } = this;
    await wex.runWalletDbTx(async (tx) => {
      const [purchase, h] = await this.getRecordHandle(tx);
      if (!purchase) {
        throw Error("purchase not found");
      }
      const nextStatus = getPayMerchantAbortTransition(
        purchase.purchaseStatus,
        purchase.timestampFirstSuccessfulPay !== undefined,
      );
      if (nextStatus === undefined) {
        return;
      }
      if (nextStatus === PurchaseStatus.AbortingWithRefund) {
        purchase.abortReason = reason;
      }
      purchase.purchaseStatus = nextStatus;
      await h.update(purchase, "abort");
    });
    await wex.taskScheduler.resetTask(this.taskId);
  }

  async userResumeTransaction(): Promise<void> {
    const { wex } = this;
    await wex.runWalletDbTx(async (tx) => {
      const [purchase, h] = await this.getRecordHandle(tx);
      if (!purchase) {
        throw Error("purchase not found");
      }
      const nextStatus = getPayMerchantResumeTransition(
        purchase.purchaseStatus,
      );
      if (nextStatus === undefined) {
        return;
      }
      purchase.purchaseStatus = nextStatus;
      await h.update(purchase, "resume", BalanceEffect.Any);
    });
    await wex.taskScheduler.resetTask(this.taskId);
  }

  async userFailTransaction(reason?: TalerErrorDetail): Promise<void> {
    const { wex } = this;
    await wex.runWalletDbTx(async (tx) => {
      const [purchase, h] = await this.getRecordHandle(tx);
      if (!purchase) {
        throw Error("purchase not found");
      }
      switch (purchase.purchaseStatus) {
        case PurchaseStatus.AbortingWithRefund:
          purchase.purchaseStatus = PurchaseStatus.FailedAbort;
          purchase.failReason = reason;
          break;
        default:
          return;
      }
      await h.update(purchase, "user-fail", BalanceEffect.Any);
      tx.scheduleOnCommit(() =>
        wex.taskScheduler.stopShepherdTask(this.taskId),
      );
    });
  }

  async getRecordHandle(
    tx: WalletDbTransaction,
  ): Promise<[WalletPurchase | undefined, RecordHandle<WalletPurchase>]> {
    return getGenericRecordHandle<WalletPurchase>(
      this,
      tx,
      async () => tx.getPurchase(this.proposalId),
      async (r) => {
        await tx.upsertPurchase(r);
      },
      async () => tx.deletePurchase(this.proposalId),
      (r) => computePayMerchantTransactionState(r),
      (r) => r.purchaseStatus,
      () => this.updateTransactionMeta(tx),
    );
  }
}

async function computePayMerchantExchangesInTx(
  tx: WalletDbTransaction,
  purchaseRecord: WalletPurchase,
): Promise<string[]> {
  if (purchaseRecord?.exchanges) {
    return purchaseRecord.exchanges;
  } else if (purchaseRecord != null && purchaseRecord.download != null) {
    const contractTermsRec = await tx.getContractTerms(
      purchaseRecord.download.contractTermsHash,
    );
    if (contractTermsRec) {
      const contractTerms = codecForMerchantContractTerms().decode(
        contractTermsRec.contractTermsRaw,
      );
      return contractTerms.exchanges.map((x) => x.url);
    }
  }
  return [];
}

async function computePayMerchantTransactionScopesInTx(
  tx: WalletDbTransaction,
  purchaseRec: WalletPurchase,
): Promise<ScopeInfo[]> {
  if (purchaseRec.exchanges && purchaseRec.exchanges.length > 0) {
    return await getScopeForAllExchanges(tx, purchaseRec.exchanges);
  } else if (purchaseRec.payInfo) {
    // This should not be necessary, as we now track
    // involved exchanges directly in the purchase.
    const coinList = !purchaseRec.payInfo.payCoinSelection
      ? []
      : purchaseRec.payInfo.payCoinSelection.coinPubs;
    return await getScopeForAllCoins(tx, coinList);
  } else if (purchaseRec.download != null) {
    const contractTermsRec = await tx.getContractTerms(
      purchaseRec.download.contractTermsHash,
    );
    if (contractTermsRec) {
      const contractTerms = codecForMerchantContractTerms().decode(
        contractTermsRec.contractTermsRaw,
      );
      const exchanges = contractTerms.exchanges.map((x) => x.url);
      return await getScopeForAllExchanges(tx, exchanges);
    }
  }
  return [
    {
      type: ScopeType.Global,
      currency: "UNKNOWN",
    },
  ];
}

export class RefundTransactionContext implements TransactionContext {
  public transactionId: TransactionIdStr;
  public taskId: TaskIdStr | undefined = undefined;

  constructor(
    public wex: WalletExecutionContext,
    public refundGroupId: string,
  ) {
    this.transactionId = constructTransactionIdentifier({
      tag: TransactionType.Refund,
      refundGroupId,
    });
  }

  /**
   * Function that updates the metadata of the transaction.
   *
   * Must be called each time the DB record for the transaction is updated.
   */
  async updateTransactionMeta(tx: WalletDbTransaction): Promise<void> {
    const refundRec = await tx.getRefundGroup(this.refundGroupId);
    if (!refundRec) {
      await tx.deleteTransactionMeta(this.transactionId);
      return;
    }
    const purchaseRecord = await tx.getPurchase(refundRec.proposalId);
    let exchanges: string[] = [];
    if (purchaseRecord) {
      exchanges = await computePayMerchantExchangesInTx(tx, purchaseRecord);
    }
    await tx.upsertTransactionMeta({
      transactionId: this.transactionId,
      status: refundRec.status,
      timestamp: refundRec.timestampCreated,
      currency: Amounts.currencyOf(refundRec.amountEffective),
      exchanges,
    });
  }

  async lookupFullTransaction(
    tx: WalletDbTransaction,
  ): Promise<Transaction | undefined> {
    const refundRecord = await tx.getRefundGroup(this.refundGroupId);
    if (!refundRecord) {
      throw makeTransactionNotFoundError(this.transactionId);
    }
    const maybeContractData = await lookupMaybeContractData(
      tx,
      refundRecord?.proposalId,
    );

    let paymentInfo: RefundPaymentInfo | undefined = undefined;

    if (maybeContractData) {
      paymentInfo = {
        merchant: maybeContractData.contractTerms.merchant,
        summary: maybeContractData.contractTerms.summary,
        summary_i18n: maybeContractData.contractTerms.summary_i18n,
      };
    }
    const purchaseRecord = await tx.getPurchase(refundRecord.proposalId);

    let scopes: ScopeInfo[];
    if (purchaseRecord) {
      scopes = await computePayMerchantTransactionScopesInTx(
        tx,
        purchaseRecord,
      );
    } else {
      scopes = [
        {
          type: ScopeType.Global,
          currency: "UNKNOWN",
        },
      ];
    }

    const txState = computeRefundTransactionState(refundRecord);
    return {
      type: TransactionType.Refund,
      scopes,
      amountEffective: isUnsuccessfulTransaction(txState)
        ? Amounts.stringify(Amounts.zeroOfAmount(refundRecord.amountEffective))
        : refundRecord.amountEffective,
      amountRaw: refundRecord.amountRaw,
      refundedTransactionId: constructTransactionIdentifier({
        tag: TransactionType.Payment,
        proposalId: refundRecord.proposalId,
      }),
      timestamp: timestampPreciseFromDb(refundRecord.timestampCreated),
      transactionId: constructTransactionIdentifier({
        tag: TransactionType.Refund,
        refundGroupId: refundRecord.refundGroupId,
      }),
      txState,
      stId: refundRecord.status,
      txActions: [TransactionAction.Delete],
      paymentInfo,
    };
  }

  async userDeleteTransaction(): Promise<void> {
    const { wex } = this;

    const res = await wex.runWalletDbTx(async (tx) => {
      return await this.deleteTransactionInTx(tx);
    });
    for (const notif of res.notifs) {
      this.wex.ws.notify(notif);
    }
  }

  async deleteTransactionInTx(
    tx: WalletDbTransaction,
  ): Promise<{ notifs: WalletNotification[] }> {
    const notifs: WalletNotification[] = [];
    const refundRecord = await tx.getRefundGroup(this.refundGroupId);
    if (!refundRecord) {
      return { notifs };
    }
    await tx.deleteRefundGroup(this.refundGroupId);
    await this.updateTransactionMeta(tx);
    await tx.upsertTombstone({ id: this.transactionId });
    const items = await tx.getRefundItemsByGroup(refundRecord.refundGroupId);
    for (const item of items) {
      if (item.id != null) {
        await tx.deleteRefundItem(item.id);
      }
    }
    return { notifs };
  }

  userSuspendTransaction(): Promise<void> {
    throw makeTransactionActionUnsupportedError(this.transactionId, "suspend");
  }

  userAbortTransaction(): Promise<void> {
    throw makeTransactionActionUnsupportedError(this.transactionId, "abort");
  }

  userResumeTransaction(): Promise<void> {
    throw makeTransactionActionUnsupportedError(this.transactionId, "resume");
  }

  userFailTransaction(): Promise<void> {
    throw makeTransactionActionUnsupportedError(this.transactionId, "fail");
  }
}

async function lookupMaybeContractData(
  tx: WalletDbTransaction,
  proposalId: string,
): Promise<DownloadedContractData | undefined> {
  let contractData: DownloadedContractData | undefined = undefined;
  const purchaseTx = await tx.getPurchase(proposalId);
  if (purchaseTx && purchaseTx.download) {
    const download = purchaseTx.download;
    const contractTermsRecord = await tx.getContractTerms(
      download.contractTermsHash,
    );
    if (!contractTermsRecord) {
      return;
    }
    contractData = {
      contractTerms: contractTermsRecord.contractTermsRaw,
      contractTermsHash: contractTermsRecord.h,
      contractTermsRaw: codecForMerchantContractTerms().decode(
        contractTermsRecord.contractTermsRaw,
      ),
    };
  }

  return contractData;
}

/**
 * Compute the total cost of a payment to the customer.
 *
 * This includes the amount taken by the merchant, fees (wire/deposit) contributed
 * by the customer, refreshing fees, fees for withdraw-after-refresh and "trimmings"
 * of coins that are too small to spend.
 */
export async function getTotalPaymentCost(
  wex: WalletExecutionContext,
  currency: string,
  pcs: SelectedProspectiveCoin[],
): Promise<AmountJson> {
  return await wex.runWalletDbTx(async (tx) => {
    return await getTotalPaymentCostInTx(wex, tx, currency, pcs);
  });
}

export async function getTotalPaymentCostInTx(
  wex: WalletExecutionContext,
  tx: WalletDbTransaction,
  currency: string,
  pcs: SelectedProspectiveCoin[],
): Promise<AmountJson> {
  const costs: AmountJson[] = [];
  const loadedDenoms = await tx.getDenominationsByRefs(pcs);
  const denoms = new Map(
    loadedDenoms.map((denom) => [denomRefKey(denom), denom]),
  );
  const paymentDenoms = pcs.map((coin) => {
    const denom = denoms.get(denomRefKey(coin));
    if (!denom) {
      throw Error(
        "can't calculate payment cost, denomination for coin not found",
      );
    }
    return denom;
  });
  const refreshCosts = await getTotalRefreshCosts(
    wex,
    tx,
    paymentDenoms.map((denom, i) => ({
      refreshedDenom: WalletDenomination.toDenomInfo(denom),
      amountLeft: Amounts.sub(denom.value, pcs[i].contribution).amount,
    })),
  );
  for (let i = 0; i < pcs.length; i++) {
    costs.push(Amounts.parseOrThrow(pcs[i].contribution));
    costs.push(refreshCosts[i]);
  }
  const zero = Amounts.zeroOfCurrency(currency);
  return Amounts.sum([zero, ...costs]).amount;
}

/**
 * Remember the payments that are still claiming, so that each of them gets
 * exactly one more attempt to claim before being discarded.
 *
 * Must be called before the task loop is started, while no claim of our own
 * can be in flight: a claiming payment in the DB is then necessarily left
 * over from a previous run of the wallet.
 */
export async function collectLeftoverClaims(
  wex: WalletExecutionContext,
): Promise<void> {
  const purchases = await wex.runWalletDbTx(async (tx) => {
    return tx.getActivePurchases();
  });
  for (const p of purchases) {
    if (p.purchaseStatus === PurchaseStatus.PendingDownloadingProposal) {
      wex.ws.leftoverClaims.add(p.proposalId);
    }
  }
  if (wex.ws.leftoverClaims.size > 0) {
    logger.info(
      `retrying ${wex.ws.leftoverClaims.size} leftover claim(s) once`,
    );
  }
}

/**
 * Claim a proposal left over from a previous run of the wallet, discarding
 * the transaction if the attempt does not succeed.
 *
 * The user never got to see the proposal for such a payment, so keeping it
 * around only produces background requests that they have no way to explain.
 * That is why even a transient error discards it here: the payment URI can
 * simply be scanned again. Claiming is idempotent for our nonce, so this one
 * retry also recovers a claim whose response we failed to store earlier.
 */
async function retryLeftoverClaim(
  wex: WalletExecutionContext,
  proposalId: string,
): Promise<TaskRunResult> {
  const ctx = new PayMerchantTransactionContext(wex, proposalId);
  let res: TaskRunResult;
  try {
    res = await processDownloadProposal(wex, proposalId);
  } catch (e) {
    logger.info(
      `discarding leftover claim ${ctx.transactionId}: ${safeStringifyException(e)}`,
    );
    await discardClaim(wex, proposalId);
    return TaskRunResult.finished();
  }
  // A claim that fails permanently discards the purchase itself, but one that
  // merely did not get anywhere leaves it behind for us to clean up. The
  // failed state only occurs for records written before claims were discarded.
  const purchase = await wex.runWalletDbTx(async (tx) => {
    return tx.getPurchase(proposalId);
  });
  switch (purchase?.purchaseStatus) {
    case PurchaseStatus.PendingDownloadingProposal:
    case PurchaseStatus.FailedClaim:
      logger.info(`discarding leftover claim ${ctx.transactionId}`);
      await discardClaim(wex, proposalId);
      return TaskRunResult.finished();
  }
  return res;
}

/**
 * Discard a purchase whose claim did not produce a contract.
 *
 * Such a purchase has no contract terms, so there is nothing to show the user
 * and nothing for them to act on. Keeping it would leave a transaction that
 * the list cannot render and that every later scan of the same order would
 * reuse instead of claiming again.
 *
 * When a reason is given, it travels with the deletion notification, since
 * that transition is the only thing a client still sees of the transaction.
 */
async function discardClaim(
  wex: WalletExecutionContext,
  proposalId: string,
  err?: TalerErrorDetail,
): Promise<void> {
  const ctx = new PayMerchantTransactionContext(wex, proposalId);
  await wex.runWalletDbTx(async (tx) => {
    await ctx.deleteTransactionInTx(tx, {
      causeHint: err ? "claim-failed" : undefined,
      errorInfo: err ? { code: err.code as number, hint: err.hint } : undefined,
    });
  });
  wex.taskScheduler.stopShepherdTask(ctx.taskId);
}

/**
 * Long-poll timeout (in milliseconds) for merchant order-status requests.
 */
const MERCHANT_ORDER_STATUS_LONGPOLL_MS = 30_000;

/**
 * Did the merchant say that it does not have the order (anymore)?
 *
 * The merchant only answers this once the order is gone from its database, so
 * asking again can never yield a different result. Requests that are repeated
 * anyway accumulate at the merchant: every wallet that still holds a
 * transaction for a long-deleted order would keep asking about it forever.
 *
 * A bare 404 is not enough to conclude this, since that is also what
 * misconfigured infrastructure in front of a merchant responds with.
 */
function isOrderUnknown(resp: {
  case: unknown;
  detail?: TalerErrorDetail;
}): boolean {
  return (
    resp.case === HttpStatusCode.NotFound &&
    resp.detail?.code === TalerErrorCode.MERCHANT_GENERIC_ORDER_UNKNOWN
  );
}

export function recoveredPayFailureStatus(
  reason: TalerErrorDetail | undefined,
): PurchaseStatus.Failed | PurchaseStatus.FailedPaidByOther {
  return reason?.code ===
    TalerErrorCode.MERCHANT_POST_ORDERS_ID_PAY_ALREADY_PAID
    ? PurchaseStatus.FailedPaidByOther
    : PurchaseStatus.Failed;
}

/**
 * Parse the merchant refund permissions attached to an already-paid reply.
 *
 * The merchant backend only returns permissions for newly deposited coins.
 * Any malformed, duplicate or unrelated entry is ignored; refresh then still
 * gets a chance to prove that the corresponding deposit never happened.
 */
export function getAlreadyPaidRefundRequests(
  detail: TalerErrorDetail,
  payCoinSelection: WalletPurchasePayInfo["payCoinSelection"],
  contractTermsHash: string,
  merchantPub: string,
): Map<string, ExchangeRefundRequest> {
  const result = new Map<string, ExchangeRefundRequest>();
  if (!payCoinSelection || !Array.isArray(detail.refunds)) {
    return result;
  }
  const contributions = new Map<string, AmountString>();
  for (let i = 0; i < payCoinSelection.coinPubs.length; i++) {
    contributions.set(
      payCoinSelection.coinPubs[i],
      payCoinSelection.coinContributions[i],
    );
  }
  for (const raw of detail.refunds) {
    if (typeof raw !== "object" || raw === null || Array.isArray(raw)) {
      continue;
    }
    const refund = raw as Record<string, unknown>;
    const coinPub = refund.coin_pub;
    const amount = refund.amount;
    const merchantSig = refund.merchant_sig;
    const rtransactionId = refund.rtransaction_id;
    const expectedContribution =
      typeof coinPub === "string" ? contributions.get(coinPub) : undefined;
    if (
      typeof coinPub !== "string" ||
      typeof amount !== "string" ||
      typeof merchantSig !== "string" ||
      typeof rtransactionId !== "number" ||
      !Number.isSafeInteger(rtransactionId) ||
      rtransactionId < 0 ||
      expectedContribution === undefined ||
      result.has(coinPub)
    ) {
      continue;
    }
    try {
      if (Amounts.cmp(amount, expectedContribution) !== 0) {
        continue;
      }
    } catch {
      continue;
    }
    result.set(coinPub, {
      refund_amount: amount as AmountString,
      h_contract_terms: contractTermsHash,
      rtransaction_id: rtransactionId,
      merchant_pub: merchantPub,
      merchant_sig: merchantSig,
    });
  }
  return result;
}

/**
 * Recover inputs after the merchant proves that the order is already
 * complete.  Calling /abort is forbidden for a complete order, so use the
 * attached refund permissions (when present) as refresh fallbacks instead.
 */
async function recoverPayFailureForCompleteOrder(
  wex: WalletExecutionContext,
  ctx: PayMerchantTransactionContext,
  reason: TalerErrorDetail,
): Promise<TaskRunResult> {
  const changed = await wex.runWalletDbTx(async (tx) => {
    const [purchase, h] = await ctx.getRecordHandle(tx);
    if (purchase?.purchaseStatus !== PurchaseStatus.PendingPaying) {
      return false;
    }
    const download = await expectProposalDownloadByIdInTx(
      wex,
      tx,
      purchase.proposalId,
    );
    const payCoinSelection = purchase.payInfo?.payCoinSelection;
    purchase.abortReason = reason;
    purchase.failReason = reason;
    if (!payCoinSelection || payCoinSelection.coinPubs.length === 0) {
      await releasePaymentTokensInTx(
        tx,
        ctx.transactionId,
        purchase.payInfo?.payTokenSelection?.tokenPubs ?? [],
      );
      purchase.purchaseStatus = recoveredPayFailureStatus(reason);
      await h.update(purchase, "pay-complete-failure-no-coins");
      return true;
    }

    const refundRequests = getAlreadyPaidRefundRequests(
      reason,
      payCoinSelection,
      download.contractTermsHash,
      download.contractTerms.merchant_pub,
    );
    const refreshCoins = payCoinSelection.coinPubs.map((coinPub, i) => ({
      coinPub,
      amount: payCoinSelection.coinContributions[i],
      refundRequest: refundRequests.get(coinPub),
    }));
    const refresh = await createRefreshGroup(
      wex,
      tx,
      Amounts.currencyOf(purchase.payInfo!.totalPayCost),
      refreshCoins,
      RefreshReason.AbortPay,
      ctx.transactionId,
    );
    purchase.abortRefreshGroupId = refresh.refreshGroupId;
    purchase.purchaseStatus = PurchaseStatus.AbortingWithRefund;
    await h.update(purchase, "pay-complete-failure-recovery");
    return true;
  });
  if (!changed) {
    return TaskRunResult.finished();
  }
  await wex.taskScheduler.resetTask(ctx.taskId);
  return TaskRunResult.progress();
}

async function recoverPayAfterStableFailure(
  ctx: PayMerchantTransactionContext,
  reason: TalerErrorDetail,
): Promise<TaskRunResult> {
  await ctx.recoverFromPayFailure(reason);
  return TaskRunResult.progress();
}

/**
 * Give up on paying an order that the merchant does not have anymore.
 *
 * This takes the payment through the regular abort path, which recovers the
 * coins that were already allocated for it. The abort request runs into the
 * same deleted order and then settles the transaction for good.
 */
async function abortPayForDeletedOrder(
  wex: WalletExecutionContext,
  ctx: PayMerchantTransactionContext,
): Promise<TaskRunResult> {
  const aborted = await wex.runWalletDbTx(async (tx) => {
    const [p, h] = await ctx.getRecordHandle(tx);
    if (p?.purchaseStatus !== PurchaseStatus.PendingPaying) {
      return false;
    }
    p.abortReason = makeTalerErrorDetail(
      TalerErrorCode.WALLET_MERCHANT_ORDER_NOT_FOUND,
      {},
      "merchant deleted the order",
    );
    p.purchaseStatus = PurchaseStatus.AbortingWithRefund;
    await h.update(p, "pay-order-gone");
    return true;
  });
  if (!aborted) {
    // Something else moved the payment on already. Retrying the request would
    // only ask the merchant about the same deleted order again.
    return TaskRunResult.finished();
  }
  await wex.taskScheduler.resetTask(ctx.taskId);
  return TaskRunResult.progress();
}

function getPayRequestTimeout(purchase: WalletPurchase): Duration {
  return Duration.multiply(
    { d_ms: 15000 },
    1 + (purchase.payInfo?.payCoinSelection?.coinPubs.length ?? 0) / 5,
  );
}

export async function expectProposalDownloadByIdInTx(
  wex: WalletExecutionContext,
  tx: WalletDbTransaction,
  proposalId: string,
): Promise<DownloadedContractData> {
  const rec = await tx.getPurchase(proposalId);
  if (!rec) {
    throw Error("purchase record not found");
  }
  return await expectProposalDownloadInTx(wex, tx, rec);
}

export async function expectProposalDownloadInTx(
  wex: WalletExecutionContext,
  tx: WalletDbTransaction,
  p: WalletPurchase,
): Promise<DownloadedContractData> {
  if (!p.download) {
    throw Error("expected proposal to be downloaded");
  }
  const download = p.download;

  const contractTermsRec = await tx.getContractTerms(
    download.contractTermsHash,
  );
  if (!contractTermsRec) {
    throw Error("contract terms not found");
  }

  return {
    contractTerms: codecForMerchantContractTerms().decode(
      contractTermsRec.contractTermsRaw,
    ),
    contractTermsRaw: contractTermsRec.contractTermsRaw,
    contractTermsHash: contractTermsRec.h,
  };
}

/**
 * Return the proposal download data for a purchase, throw if not available.
 */
async function expectProposalDownload(
  wex: WalletExecutionContext,
  p: WalletPurchase,
): Promise<DownloadedContractData> {
  return await wex.runWalletDbTx(async (tx) => {
    return expectProposalDownloadInTx(wex, tx, p);
  });
}

async function processDownloadProposal(
  wex: WalletExecutionContext,
  proposalId: string,
): Promise<TaskRunResult> {
  const proposal = await wex.runWalletDbTx(async (tx) => {
    return await tx.getPurchase(proposalId);
  });

  if (!proposal) {
    return TaskRunResult.finished();
  }

  const ctx = new PayMerchantTransactionContext(wex, proposalId);

  if (proposal.purchaseStatus != PurchaseStatus.PendingDownloadingProposal) {
    logger.error(
      `unexpected state ${proposal.purchaseStatus}/${
        PurchaseStatus[proposal.purchaseStatus]
      } for ${ctx.transactionId} in processDownloadProposal`,
    );
    return TaskRunResult.finished();
  }

  const orderClaimUrl = new URL(
    `orders/${proposal.orderId}/claim`,
    proposal.merchantBaseUrl,
  );
  logger.trace(`downloading contract from ${orderClaimUrl.href}`);

  const requestBody: {
    nonce: string;
    token?: string;
  } = {
    nonce: proposal.noncePub,
  };
  if (proposal.claimToken) {
    requestBody.token = proposal.claimToken;
  }

  const merchantClient = walletMerchantClient(proposal.merchantBaseUrl, wex);

  const claimResp = await merchantClient.claimOrder({
    orderId: proposal.orderId,
    body: requestBody,
  });

  switch (claimResp.case) {
    case "ok":
      break;
    case HttpStatusCode.Conflict:
      await discardClaim(
        wex,
        proposalId,
        makeTalerErrorDetail(
          TalerErrorCode.WALLET_ORDER_ALREADY_CLAIMED,
          {
            orderId: proposal.orderId,
            claimUrl: orderClaimUrl.href,
          },
          "order already claimed (likely by other wallet)",
        ),
      );
      return TaskRunResult.finished();
    case TalerErrorCode.MERCHANT_POST_ORDERS_ID_CLAIM_NOT_FOUND: {
      await discardClaim(
        wex,
        proposalId,
        makeTalerErrorDetail(
          TalerErrorCode.WALLET_MERCHANT_ORDER_NOT_FOUND,
          {},
          "order not found (expired?)",
        ),
      );
      return TaskRunResult.finished();
    }
    default:
      assertUnreachable(claimResp);
  }

  const proposalResp = claimResp.body;

  // The proposalResp contains the contract terms as raw JSON,
  // as the code to parse them doesn't necessarily round-trip.
  // We need this raw JSON to compute the contract terms hash.

  // FIXME: Do better error handling, check if the
  // contract terms have all their forgettable information still
  // present.  The wallet should never accept contract terms
  // with missing information from the merchant.

  var isWellFormed = ContractTermsUtil.validateForgettable(
    proposalResp.contract_terms,
  );

  if (!isWellFormed) {
    logger.trace(
      `malformed contract terms (validateForgettable): ${j2s(proposalResp.contract_terms)}`,
    );
    const err = makeErrorDetail(
      TalerErrorCode.WALLET_CONTRACT_TERMS_MALFORMED,
      {},
      "validation for well-formedness failed",
    );
    await discardClaim(wex, proposalId, err);
    return TaskRunResult.finished();
  }

  const contractTermsHash = ContractTermsUtil.hashContractTerms(
    proposalResp.contract_terms,
  );

  let parsedContractTerms: MerchantContractTerms;

  try {
    parsedContractTerms = codecForMerchantContractTerms().decode(
      proposalResp.contract_terms,
    );
  } catch (e) {
    const err = makeErrorDetail(
      TalerErrorCode.WALLET_CONTRACT_TERMS_MALFORMED,
      {},
      `schema validation failed: ${e}`,
    );
    await discardClaim(wex, proposalId, err);
    return TaskRunResult.finished();
  }

  isWellFormed = ContractTermsUtil.validateParsed(parsedContractTerms);

  if (!isWellFormed) {
    logger.trace(
      `malformed contract terms: ${j2s(proposalResp.contract_terms)}`,
    );
    const err = makeErrorDetail(
      TalerErrorCode.WALLET_CONTRACT_TERMS_MALFORMED,
      {},
      "validation for well-formedness failed (validateParsed)",
    );
    await discardClaim(wex, proposalId, err);
    return TaskRunResult.finished();
  }

  const bindingError = validateClaimResponseBindings(
    proposal.orderId,
    proposal.noncePub,
    parsedContractTerms,
  );
  if (bindingError) {
    const err = makeErrorDetail(
      TalerErrorCode.WALLET_CONTRACT_TERMS_MALFORMED,
      {},
      bindingError,
    );
    await discardClaim(wex, proposalId, err);
    return TaskRunResult.finished();
  }

  const sigValid = await wex.cryptoApi.isValidContractTermsSignature({
    contractTermsHash,
    merchantPub: parsedContractTerms.merchant_pub,
    sig: proposalResp.sig,
  });

  if (!sigValid) {
    const err = makeErrorDetail(
      TalerErrorCode.WALLET_CONTRACT_TERMS_SIGNATURE_INVALID,
      {
        merchantPub: parsedContractTerms.merchant_pub,
        orderId: parsedContractTerms.order_id,
      },
      "merchant's signature on contract terms is invalid",
    );
    await discardClaim(wex, proposalId, err);
    return TaskRunResult.finished();
  }

  const fulfillmentUrl = parsedContractTerms.fulfillment_url;

  const baseUrlForDownload = proposal.merchantBaseUrl;
  const baseUrlFromContractTerms = parsedContractTerms.merchant_base_url;

  if (baseUrlForDownload !== baseUrlFromContractTerms) {
    // We only write a warning here, since there are various real-world scenarios where
    // a mismatch is possible:
    // - Case mismatch between instance name (since the merchant treats them case-insensitively)
    // - Merchant wants to use some shortened URL for the QR code
    // It used to be an error in the past, but it turned out to not be useful.
    logger.warn(
      `base URL mismatch between taler:// URI and contract terms: ${baseUrlForDownload} / ${baseUrlFromContractTerms}`,
    );
  }

  const contractData: DownloadedContractData = {
    contractTerms: codecForMerchantContractTerms().decode(
      proposalResp.contract_terms,
    ),
    contractTermsHash: contractTermsHash,
    contractTermsRaw: proposalResp.contract_terms,
  };

  logger.trace(`extracted contract data: ${j2s(contractData)}`);

  await wex.runWalletDbTx(async (tx) => {
    const [p, h] = await ctx.getRecordHandle(tx);
    if (!p) {
      return;
    }
    if (p.purchaseStatus !== PurchaseStatus.PendingDownloadingProposal) {
      return;
    }

    // We consider this base URL to be the authoritative / stable one.
    p.merchantBaseUrl = baseUrlFromContractTerms;

    const secretSeed = encodeCrock(getRandomBytes(32));
    p.secretSeed = secretSeed;

    // v1: currency is resolved after choice selection
    let currency: string = "UNKNOWN";
    if (
      contractData.contractTerms.version === undefined ||
      contractData.contractTerms.version === MerchantContractVersion.V0
    ) {
      currency = Amounts.currencyOf(contractData.contractTerms.amount);
    } else if (
      contractData.contractTerms.version === MerchantContractVersion.V1
    ) {
      // if there is only one choice, or all choices have the same currency
      if (contractData.contractTerms.choices.length === 1) {
        currency = Amounts.currencyOf(
          contractData.contractTerms.choices[0].amount,
        );
      } else if (contractData.contractTerms.choices.length > 1) {
        const firstCurrency = Amounts.currencyOf(
          contractData.contractTerms.choices[0].amount,
        );
        const allSame = contractData.contractTerms.choices.every(
          (c) => Amounts.currencyOf(c.amount) === firstCurrency,
        );
        if (allSame) {
          currency = firstCurrency;
        }
      }
    }

    p.download = {
      contractTermsHash,
      contractTermsMerchantSig: proposalResp.sig,
      currency,
      fulfillmentUrl: contractData.contractTerms.fulfillment_url,
    };
    await tx.upsertContractTerms({
      h: contractTermsHash,
      contractTermsRaw: proposalResp.contract_terms,
    });
    const isResourceFulfillmentUrl =
      fulfillmentUrl &&
      (fulfillmentUrl.startsWith("http://") ||
        fulfillmentUrl.startsWith("https://"));
    let repurchase: WalletPurchase | undefined = undefined;
    // Only consumed under isResourceFulfillmentUrl, which implies
    // fulfillmentUrl is set.  Previously this passed undefined straight to
    // the index, which scans the whole store for a result that is then unused.
    const otherPurchases = fulfillmentUrl
      ? await tx.getPurchasesByFulfillmentUrl(fulfillmentUrl)
      : [];
    if (isResourceFulfillmentUrl) {
      for (const otherPurchase of otherPurchases) {
        if (
          otherPurchase.purchaseStatus == PurchaseStatus.Done ||
          otherPurchase.purchaseStatus == PurchaseStatus.PendingPaying ||
          otherPurchase.purchaseStatus == PurchaseStatus.PendingPayingReplay
        ) {
          repurchase = otherPurchase;
          break;
        }
      }
    }

    // FIXME: Adjust this to account for refunds, don't count as repurchase
    // if original order is refunded.
    if (repurchase) {
      logger.warn("repurchase detected");
      p.purchaseStatus = PurchaseStatus.DoneRepurchaseDetected;
      p.repurchaseProposalId = repurchase.proposalId;
      await startPayReplay(wex, tx, repurchase.proposalId, p.downloadSessionId);
    } else {
      p.purchaseStatus = isSharedPurchase(p)
        ? PurchaseStatus.DialogShared
        : PurchaseStatus.DialogProposed;
    }
    // Downloading the proposal only presents the offer to the user, no
    // funds are committed until the payment is confirmed.
    await h.update(p, "download-proposal", BalanceEffect.None);
  });

  return TaskRunResult.progress();
}

export function validateClaimResponseBindings(
  expectedOrderId: string,
  expectedNonce: string,
  contractTerms: MerchantContractTerms,
): string | undefined {
  if (contractTerms.order_id !== expectedOrderId) {
    return "merchant contract terms contain a different order ID";
  }
  if (contractTerms.nonce !== expectedNonce) {
    return "merchant contract terms contain a different wallet nonce";
  }
  return undefined;
}

async function startPayReplay(
  wex: WalletExecutionContext,
  tx: WalletDbTransaction,
  proposalId: string,
  sessionId: string | undefined,
): Promise<void> {
  logger.info(`starting pay replay of ${proposalId} under ${sessionId}`);
  const ctx = new PayMerchantTransactionContext(wex, proposalId);
  const [rec, h] = await ctx.getRecordHandle(tx);
  if (rec && rec.purchaseStatus === PurchaseStatus.Done) {
    rec.purchaseStatus = PurchaseStatus.PendingPayingReplay;
    rec.lastSessionId = sessionId;
  }
  // The coins were already spent by the original payment, replaying it
  // for a new session does not spend anything on top of that.
  await h.update(rec, "start-replay", BalanceEffect.None);
  tx.scheduleOnCommit(() => {
    wex.taskScheduler.resetTask(ctx.taskId).catch((e) => {
      logger.error(safeStringifyException(e));
    });
  });
}

async function generateSlate(
  wex: WalletExecutionContext,
  purchase: WalletPurchase,
  contractData: MerchantContractTermsV1,
  contractTermsRaw: any,
  choiceIndex: number,
  outputIndex: number,
  repeatIndex: number,
): Promise<void> {
  checkDbInvariant(
    purchase.secretSeed !== undefined,
    "can't process slates without secretSeed",
  );

  logger.trace(
    `generating slate (${choiceIndex}, ${outputIndex}, ${repeatIndex}) for purchase ${purchase.proposalId}`,
  );

  let slate = await wex.runWalletDbTx(async (tx) => {
    return await tx.getSlate(
      purchase.proposalId,
      choiceIndex,
      outputIndex,
      repeatIndex,
    );
  });

  if (slate) {
    return;
  }

  const choice = contractData.choices[choiceIndex];
  const output = choice.outputs[outputIndex];
  if (output.type !== MerchantContractOutputType.Token) {
    throw TalerError.fromDetail(
      TalerErrorCode.WALLET_CONTRACT_TERMS_UNSUPPORTED,
      {},
      `this wallet does not support contract output type "${output.type}"`,
    );
  }

  const family = contractData.token_families[output.token_family_slug];
  const tokenIssuePub = family.keys[output.key_index];
  const r = await wex.cryptoApi.createSlate({
    secretSeed: purchase.secretSeed,
    choiceIndex: choiceIndex,
    outputIndex: outputIndex,
    tokenIssuePub,
    genTokenUseSig: true,
    contractTerms: contractData,
    contractTermsHash: ContractTermsUtil.hashContractTerms(contractTermsRaw),
    repeatIndex,
  });

  const newSlate: WalletSlate = {
    purchaseId: purchase.proposalId,
    choiceIndex: choiceIndex,
    outputIndex: outputIndex,
    merchantBaseUrl: contractData.merchant_base_url,
    kind: family.details.class,
    slug: output.token_family_slug,
    name: family.name,
    description: family.description,
    descriptionI18n: family.description_i18n,
    extraData: family.details,
    tokenIssuePub: tokenIssuePub,
    validAfter: timestampProtocolToDb(tokenIssuePub.signature_validity_start),
    validBefore: timestampProtocolToDb(tokenIssuePub.signature_validity_end),
    tokenIssuePubHash: r.tokenIssuePubHash,
    tokenUsePub: r.tokenPub,
    tokenUsePriv: r.tokenPriv,
    tokenEv: r.tokenEv,
    tokenEvHash: r.tokenEvHash,
    blindingKey: r.blindingKey,
    repeatIndex,
  };

  newSlate.tokenFamilyHash = WalletToken.hashInfo(newSlate);

  await wex.runWalletDbTx(async (tx) => {
    const s = await tx.getSlate(
      purchase.proposalId,
      choiceIndex,
      outputIndex,
      repeatIndex,
    );
    if (s) {
      return;
    }
    await tx.upsertSlate(newSlate);
  });
}

/**
 * Create a new purchase transaction if necessary.  If a purchase
 * record for the provided arguments already exists,
 * return the old proposal ID.
 */
export function isSharedPurchase(
  purchase: Pick<WalletPurchase, "shared" | "createdFromShared">,
): boolean {
  return purchase.shared || purchase.createdFromShared === true;
}

export async function createOrReusePurchase(
  wex: WalletExecutionContext,
  merchantBaseUrl: string,
  orderId: string,
  sessionId: string | undefined,
  claimToken: string | undefined,
  noncePriv: string | undefined,
  talerUri: string | undefined,
): Promise<{
  proposalId: string;
  transactionId: TransactionIdStr;
}> {
  // Find existing proposals from the same merchant
  // with the same order ID.
  //
  // Once a proposal has been downloaded its merchantBaseUrl is the one from
  // the contract terms, which always spells the instance in lower case.  A
  // taler:// URI may spell it differently -- the merchant accepts any casing
  // -- so look the record up under the canonical spelling as well, or
  // re-scanning such a URI would claim the order a second time instead of
  // returning the transaction that already exists.
  const canonicalBaseUrl = canonicalizeMerchantInstanceUrl(merchantBaseUrl);
  const oldProposals = await wex.runWalletDbTx(async (tx) => {
    const found = await tx.getPurchasesByUrlAndOrderId(
      merchantBaseUrl,
      orderId,
    );
    if (found.length > 0 || canonicalBaseUrl === merchantBaseUrl) {
      return found;
    }
    return tx.getPurchasesByUrlAndOrderId(canonicalBaseUrl, orderId);
  });

  if (oldProposals.length > 1) {
    logger.error(
      "BUG: more than one existing purchase transaction for same order ID and merchant base URL, this should never happen",
    );
  }

  let oldProposal = oldProposals.find((p) => {
    return (
      (!noncePriv || p.noncePriv === noncePriv) && p.claimToken === claimToken
    );
  });
  if (!oldProposal && oldProposals.length > 0) {
    // Should never happen, except for backwards compat.
    oldProposal = oldProposals[0];
  }
  if (oldProposal?.purchaseStatus === PurchaseStatus.FailedClaim) {
    // Written by an older version of the wallet, which kept a record for a
    // claim that never produced a contract. Reusing it would hand back a
    // transaction the user cannot see instead of claiming again.
    await discardClaim(wex, oldProposal.proposalId);
    oldProposal = undefined;
  }
  // If we have already claimed this proposal with the same
  // nonce and claim token, reuse it.
  if (oldProposal) {
    logger.info(
      `Found old proposal (status=${
        PurchaseStatus[oldProposal.purchaseStatus]
      }) for order ${orderId} at ${merchantBaseUrl}`,
    );
    const oldCtx = new PayMerchantTransactionContext(
      wex,
      oldProposal.proposalId,
    );
    if (
      (oldProposal.lastSessionId !== sessionId &&
        oldProposal.timestampFirstSuccessfulPay != null) ||
      oldProposal.purchaseStatus === PurchaseStatus.DoneRepurchaseDetected
    ) {
      logger.info(`replaying payment with old proposal`);
      switch (oldProposal.purchaseStatus) {
        case PurchaseStatus.Done:
        case PurchaseStatus.PendingPayingReplay:
        case PurchaseStatus.SuspendedPayingReplay:
          await wex.runWalletDbTx(async (tx) => {
            await startPayReplay(wex, tx, oldProposal.proposalId, sessionId);
          });
          break;
        case PurchaseStatus.DoneRepurchaseDetected: {
          // Trigger replay on *old* payment
          const repId = oldProposal.repurchaseProposalId;
          if (repId != null) {
            await wex.runWalletDbTx(async (tx) => {
              await startPayReplay(wex, tx, repId, sessionId);
            });
          }
          break;
        }
      }
    }
    if (isSharedPurchase(oldProposal)) {
      // Preparing a payment is deliberately local-only. Wake the transaction
      // task so that it can check the merchant asynchronously.
      await wex.taskScheduler.resetTask(oldCtx.taskId);
    }
    return {
      proposalId: oldProposal.proposalId,
      transactionId: oldCtx.transactionId,
    };
  }

  let noncePair: EddsaKeyPairStrings;
  let createdFromShared = false;
  if (noncePriv) {
    createdFromShared = true;
    noncePair = {
      priv: noncePriv,
      pub: (await wex.cryptoApi.eddsaGetPublic({ priv: noncePriv })).pub,
    };
  } else {
    noncePair = await wex.cryptoApi.createEddsaKeypair({});
  }

  const { priv, pub } = noncePair;
  const proposalId = encodeCrock(getRandomBytes(32));

  logger.info(
    `created new proposal for ${orderId} at ${merchantBaseUrl} session ${sessionId}`,
  );

  const secretSeed = encodeCrock(getRandomBytes(32));

  const proposalRecord: WalletPurchase = {
    download: undefined,
    noncePriv: priv,
    noncePub: pub,
    claimToken,
    timestamp: timestampPreciseToDb(TalerPreciseTimestamp.now()),
    merchantBaseUrl,
    orderId,
    proposalId: proposalId,
    purchaseStatus: PurchaseStatus.PendingDownloadingProposal,
    repurchaseProposalId: undefined,
    downloadSessionId: sessionId,
    autoRefundDeadline: undefined,
    lastSessionId: undefined,
    merchantPaySig: undefined,
    secretSeed: secretSeed,
    payInfo: undefined,
    refundAmountAwaiting: undefined,
    timestampAccept: undefined,
    timestampFirstSuccessfulPay: undefined,
    timestampLastRefundStatus: undefined,
    pendingRemovedCoinPubs: undefined,
    posConfirmation: undefined,
    shared: false,
    createdFromShared,
    talerUri,
  };

  const ctx = new PayMerchantTransactionContext(wex, proposalId);

  await wex.runWalletDbTx(async (tx) => {
    await tx.upsertPurchase(proposalRecord);
    await ctx.updateTransactionMeta(tx);
    const oldTxState: TransactionState = {
      major: TransactionMajorState.None,
    };
    const newTxState = computePayMerchantTransactionState(proposalRecord);
    applyNotifyTransition(tx.notify, ctx.transactionId, {
      causeHint: "create",
      oldTxState,
      newTxState,
      balanceEffect: BalanceEffect.None,
      oldStId: 0,
      newStId: proposalRecord.purchaseStatus,
    });
    tx.scheduleOnCommit(() => {
      wex.taskScheduler.resetTask(ctx.taskId).catch((e) => {
        logger.error(safeStringifyException(e));
      });
    });
  });

  return {
    proposalId,
    transactionId: ctx.transactionId,
  };
}

export function applyFirstPaySuccessState(
  purchase: WalletPurchase,
  sessionId: string | undefined,
  payResponse: MerchantPayResponse,
  timestamp: TalerPreciseTimestamp,
): boolean {
  let completePaymentState = false;
  switch (purchase.purchaseStatus) {
    case PurchaseStatus.PendingPaying:
    case PurchaseStatus.SuspendedPaying:
      purchase.purchaseStatus = PurchaseStatus.Done;
      completePaymentState = true;
      break;
  }
  purchase.timestampFirstSuccessfulPay = timestampPreciseToDb(timestamp);
  purchase.lastSessionId = sessionId;
  purchase.merchantPaySig = payResponse.sig;
  purchase.posConfirmation = payResponse.pos_confirmation;
  return completePaymentState;
}

export async function storeFirstPaySuccess(
  wex: WalletExecutionContext,
  proposalId: string,
  sessionId: string | undefined,
  payResponse: MerchantPayResponse,
  tokenFinalization?: {
    inputTokenPubs: string[];
    outputTokens: WalletToken[];
    outputSlates: WalletSlate[];
    slateTokenSigs: SignedTokenEnvelope[];
  },
): Promise<void> {
  const ctx = new PayMerchantTransactionContext(wex, proposalId);
  const now = AbsoluteTime.toPreciseTimestamp(AbsoluteTime.now());
  await wex.runWalletDbTx(async (tx) => {
    const [purchase, h] = await ctx.getRecordHandle(tx);
    if (!purchase) {
      return;
    }
    const isFirst = purchase.timestampFirstSuccessfulPay === undefined;
    if (!isFirst) {
      logger.warn("payment success already stored");
      return;
    }

    if (tokenFinalization) {
      for (let i = 0; i < tokenFinalization.outputTokens.length; i++) {
        await tx.upsertToken(tokenFinalization.outputTokens[i]);
        await tx.deleteSlate(tokenFinalization.outputSlates[i].tokenUsePub);
      }
      for (const tokenPub of tokenFinalization.inputTokenPubs) {
        const token = await tx.getToken(tokenPub);
        if (token && token.transactionId !== ctx.transactionId) {
          throw Error(
            `payment input token ${tokenPub} is reserved by another transaction`,
          );
        }
        await tx.deleteToken(tokenPub);
      }
      const payInfo = purchase.payInfo;
      checkDbInvariant(
        !!payInfo,
        `purchase ${purchase.orderId} without payInfo`,
      );
      payInfo.slateTokenSigs = tokenFinalization.slateTokenSigs;
    }

    const completePaymentState = applyFirstPaySuccessState(
      purchase,
      sessionId,
      payResponse,
      now,
    );
    const dl = purchase.download;
    checkDbInvariant(
      !!dl,
      `purchase ${purchase.orderId} without ct downloaded`,
    );
    const contractTermsRecord = await tx.getContractTerms(dl.contractTermsHash);
    checkDbInvariant(
      !!contractTermsRecord,
      `no contract terms found for purchase ${purchase.orderId}`,
    );
    const contractTerms = codecForMerchantContractTerms().decode(
      contractTermsRecord.contractTermsRaw,
    );
    const protoAr = contractTerms.auto_refund;
    if (completePaymentState && protoAr && protoAr.d_us != 0) {
      const ar = Duration.fromTalerProtocolDuration(protoAr);
      logger.info("auto_refund present");
      purchase.purchaseStatus = PurchaseStatus.FinalizingQueryingAutoRefund;
      purchase.autoRefundDeadline = timestampProtocolToDb(
        AbsoluteTime.toProtocolTimestamp(
          AbsoluteTime.addDuration(AbsoluteTime.now(), ar),
        ),
      );
    }
    await h.update(purchase, "pay-success");
  });
}

export function splitPaymentOutputTokenSignatures(
  responseTokenSigs: SignedTokenEnvelope[] | undefined,
  slateOutputIndexes: number[],
  donauOutputIndex: number | undefined,
  donauCount: number,
  cachedSlateSigs?: SignedTokenEnvelope[],
): {
  slateTokenSigs: SignedTokenEnvelope[];
  donauTokenSigs: SignedTokenEnvelope[];
} {
  const tokenSigs = responseTokenSigs ?? [];
  const slateCount = slateOutputIndexes.length;
  const expectedCount = slateCount + donauCount;

  if (
    cachedSlateSigs &&
    cachedSlateSigs.length === slateCount &&
    tokenSigs.length === 0 &&
    donauCount === 0
  ) {
    // Recover databases written by older wallets that committed the slate
    // signatures before committing payment success.
    return {
      slateTokenSigs: cachedSlateSigs,
      donauTokenSigs: [],
    };
  }

  if (tokenSigs.length !== expectedCount) {
    throw TalerError.fromDetail(
      TalerErrorCode.WALLET_TRANSACTION_PROTOCOL_VIOLATION,
      {},
      `merchant returned ${tokenSigs.length} token signatures, expected ${expectedCount}`,
    );
  }

  if (donauCount > 0 && donauOutputIndex === undefined) {
    throw Error("donation signatures require a contract output index");
  }

  const responsePositions: Array<
    | { outputIndex: number; subIndex: number; kind: "slate"; index: number }
    | { outputIndex: number; subIndex: number; kind: "donau"; index: number }
  > = slateOutputIndexes.map((outputIndex, index) => ({
    outputIndex,
    subIndex: index,
    kind: "slate",
    index,
  }));
  for (let index = 0; index < donauCount; index++) {
    responsePositions.push({
      outputIndex: donauOutputIndex!,
      subIndex: index,
      kind: "donau",
      index,
    });
  }
  responsePositions.sort(
    (a, b) => a.outputIndex - b.outputIndex || a.subIndex - b.subIndex,
  );

  const slateTokenSigs: SignedTokenEnvelope[] = new Array(slateCount);
  const donauTokenSigs: SignedTokenEnvelope[] = new Array(donauCount);
  for (
    let responseIndex = 0;
    responseIndex < tokenSigs.length;
    responseIndex++
  ) {
    const position = responsePositions[responseIndex];
    if (position.kind === "slate") {
      slateTokenSigs[position.index] = tokenSigs[responseIndex];
    } else {
      donauTokenSigs[position.index] = tokenSigs[responseIndex];
    }
  }
  return {
    slateTokenSigs,
    donauTokenSigs,
  };
}

async function storePayReplaySuccess(
  wex: WalletExecutionContext,
  proposalId: string,
  sessionId: string | undefined,
): Promise<void> {
  const ctx = new PayMerchantTransactionContext(wex, proposalId);
  await wex.runWalletDbTx(async (tx) => {
    const [purchase, h] = await ctx.getRecordHandle(tx);
    if (!purchase) {
      return;
    }
    const isFirst = purchase.timestampFirstSuccessfulPay === undefined;
    if (isFirst) {
      throw Error("invalid payment state");
    }
    switch (purchase.purchaseStatus) {
      case PurchaseStatus.PendingPaying:
      case PurchaseStatus.PendingPayingReplay:
        purchase.purchaseStatus = PurchaseStatus.Done;
        break;
    }
    purchase.lastSessionId = sessionId;
    // A replay only demonstrates the earlier payment to the merchant,
    // no additional funds are spent.
    await h.update(purchase, "replay-success", BalanceEffect.None);
  });
}

function setCoinSel(rec: WalletPurchase, coinSel: PayCoinSelection): void {
  checkLogicInvariant(!!rec.payInfo);
  rec.payInfo.payCoinSelection = {
    coinContributions: coinSel.coins.map((x) => x.contribution),
    coinPubs: coinSel.coins.map((x) => x.coinPub),
  };
  rec.payInfo.payCoinSelectionUid = encodeCrock(getRandomBytes(32));
  rec.exchanges = [...new Set(coinSel.coins.map((x) => x.exchangeBaseUrl))];
  rec.exchanges.sort();
}

export function getCoinsToSpendForMerchantRepair(
  previous: PreviousPayCoins,
  selected: SelectedCoin[],
): SelectedCoin[] {
  return coinsAddedByRepair(previous, selected);
}

export function getPayRepairAcceptedExchanges(
  contractTerms: MerchantContractTerms,
  excludedExchangeBaseUrls: Set<string> | undefined,
): AllowedExchangeInfo[] {
  return contractTerms.exchanges
    .filter((ex) => !excludedExchangeBaseUrls?.has(ex.url))
    .map((ex) => ({
      exchangeBaseUrl: ex.url,
      exchangePub: ex.master_pub,
    }));
}

async function reselectCoinsTx(
  tx: WalletDbTransaction,
  ctx: PayMerchantTransactionContext,
  opts: {
    excludeCoinPub?: string;
    excludeExchangeBaseUrls?: Set<string>;
  } = {},
): Promise<"success" | "insufficient" | "gone"> {
  const p = await tx.getPurchase(ctx.proposalId);
  if (!p) {
    return "gone";
  }
  if (!p.payInfo) {
    return "gone";
  }

  const contractData = await expectProposalDownloadByIdInTx(
    ctx.wex,
    tx,
    ctx.proposalId,
  );

  const { available, amountRaw, maxFee } = ContractTermsUtil.extractAmounts(
    contractData.contractTerms,
    p.choiceIndex,
  );
  if (!available) {
    throw Error("choice index not specified for contract v1");
  }

  const prevPayCoins: PreviousPayCoins = [];
  const prevTokensPubs: string[] = [];
  let payCoinsToSpend: SelectedCoin[] = [];
  const removedExchangeCoins: CoinRefreshRequest[] = [];

  const payCoinSelection = p.payInfo.payCoinSelection;
  const payTokenSelection = p.payInfo.payTokenSelection;

  if (payCoinSelection) {
    const selectedCoins = await tx.getCoinsByPubs(payCoinSelection.coinPubs);
    const selectedCoinsByPub = new Map(
      selectedCoins.map((coin) => [coin.coinPub, coin]),
    );
    for (let i = 0; i < payCoinSelection.coinPubs.length; i++) {
      const coinPub = payCoinSelection.coinPubs[i];
      if (opts.excludeCoinPub != null && coinPub === opts.excludeCoinPub) {
        // Exclude the coin that the exchange reported as broken
        // (e.g. double-spent) so re-selection doesn't just pick the
        // same failing coin again.
        continue;
      }
      const contrib = payCoinSelection.coinContributions[i];
      const coin = selectedCoinsByPub.get(coinPub);
      checkDbInvariant(!!coin, `selected payment coin ${coinPub} is missing`);
      if (opts.excludeExchangeBaseUrls?.has(coin.exchangeBaseUrl)) {
        // A legal refusal is definitive for this exchange and this payment.
        // The exchange did not accept the deposit, so recover the allocated
        // contribution while replacing it with a coin from another exchange
        // accepted by the signed contract.
        removedExchangeCoins.push({ coinPub, amount: contrib });
        continue;
      }
      prevPayCoins.push({
        coinPub,
        contribution: Amounts.parseOrThrow(contrib),
      });
    }

    const acceptedExchanges = getPayRepairAcceptedExchanges(
      contractData.contractTerms,
      opts.excludeExchangeBaseUrls,
    );

    if (
      opts.excludeExchangeBaseUrls &&
      (removedExchangeCoins.length === 0 || acceptedExchanges.length === 0)
    ) {
      return "insufficient";
    }

    const res = await selectPayCoinsInTx(ctx.wex, tx, {
      restrictExchanges: {
        auditors: [],
        exchanges: acceptedExchanges,
      },
      restrictWireMethod: contractData.contractTerms.wire_method,
      contractTermsAmount: Amounts.parseOrThrow(amountRaw),
      depositFeeLimit: Amounts.parseOrThrow(maxFee),
      prevPayCoins,
      requiredMinimumAge: contractData.contractTerms.minimum_age,
    });

    switch (res.type) {
      case "failure":
        logger.trace("insufficient funds for coin re-selection");
        return "insufficient";
      case "success":
        break;
      default:
        assertUnreachable(res);
    }
    payCoinsToSpend = getCoinsToSpendForMerchantRepair(
      prevPayCoins,
      res.coinSel.coins,
    );
    setCoinSel(p, res.coinSel);
  }

  if (payTokenSelection) {
    prevTokensPubs.push(...payTokenSelection.tokenPubs);

    if (p.choiceIndex === undefined) throw Error("assertion failed");

    if (contractData.contractTerms.version !== MerchantContractVersion.V1)
      throw Error("assertion failed");

    const res = await selectPayTokensInTx(tx, {
      proposalId: p.proposalId,
      choiceIndex: p.choiceIndex,
      contractTerms: contractData.contractTerms,
      existingReservation: {
        transactionId: ctx.transactionId,
        tokenPubs: prevTokensPubs,
      },
    });

    switch (res.type) {
      case "failure":
        logger.trace("insufficient tokens for token re-selection");
        return "insufficient";
      case "success":
        break;
      default:
        assertUnreachable(res);
    }

    p.payInfo.payTokenSelection = {
      tokenPubs: res.tokens.map((t) => t.tokenUsePub),
    };
    const selectedTokenPubs = new Set(p.payInfo.payTokenSelection.tokenPubs);
    await releasePaymentTokensInTx(
      tx,
      ctx.transactionId,
      prevTokensPubs.filter((x) => !selectedTokenPubs.has(x)),
    );
  }

  await tx.upsertPurchase(p);
  await ctx.updateTransactionMeta(tx);

  if (removedExchangeCoins.length > 0) {
    await createRefreshGroup(
      ctx.wex,
      tx,
      Amounts.currencyOf(p.payInfo.totalPayCost),
      removedExchangeCoins,
      RefreshReason.AbortPay,
      ctx.transactionId,
    );
  }

  if (p.payInfo.payCoinSelection) {
    await spendCoins(ctx.wex, tx, {
      transactionId: ctx.transactionId,
      coinPubs: payCoinsToSpend.map((x) => x.coinPub),
      contributions: payCoinsToSpend.map((x) =>
        Amounts.parseOrThrow(x.contribution),
      ),
      refreshReason: RefreshReason.PayMerchant,
    });
  }

  if (p.payInfo.payTokenSelection) {
    await spendTokens(tx, {
      transactionId: ctx.transactionId,
      tokenPubs: p.payInfo.payTokenSelection.tokenPubs,
    });
  }
  return "success";
}

/**
 * Handle a 409 Conflict or 400 Bad Request response from the merchant.
 *
 * We do this by going through the coin history provided by the exchange and
 * (1) verifying the signatures from the exchange
 * (2) adjusting the remaining coin value and refreshing it
 * (3) re-do coin selection with the bad coin removed
 */
async function handleInsufficientFunds(
  wex: WalletExecutionContext,
  proposalId: string,
  err: TalerErrorDetail,
): Promise<TaskRunResult> {
  logger.trace("handling insufficient funds, trying to re-select coins");

  const ctx = new PayMerchantTransactionContext(wex, proposalId);

  const proposal = await wex.runWalletDbTx(async (tx) => {
    return tx.getPurchase(proposalId);
  });
  if (!proposal) {
    return TaskRunResult.finished();
  }

  logger.trace(`got error details: ${j2s(err)}`);

  let brokenCoinPub: string | undefined;

  if (
    err.code === TalerErrorCode.MERCHANT_POST_ORDERS_ID_PAY_INSUFFICIENT_FUNDS
  ) {
    const exchangeReply = (err as any).exchange_reply;
    if (exchangeReply == null) {
      return recoverPayAfterStableFailure(ctx, {
        code: TalerErrorCode.WALLET_TRANSACTION_PROTOCOL_VIOLATION,
        message:
          "merchant claimed insufficient funds without an exchange reply",
      });
    }
    if (
      exchangeReply.code !== TalerErrorCode.EXCHANGE_GENERIC_INSUFFICIENT_FUNDS
    ) {
      if (logger.shouldLogTrace()) {
        logger.trace("got exchange error reply (see below)");
        logger.trace(j2s(exchangeReply));
      }
      return recoverPayAfterStableFailure(ctx, {
        code: TalerErrorCode.WALLET_TRANSACTION_PROTOCOL_VIOLATION,
        message: `unable to handle /pay exchange error response (${exchangeReply.code})`,
        exchangeReply,
      });
    }

    brokenCoinPub = (exchangeReply as any).coin_pub;
    logger.trace(`excluding broken coin pub=${brokenCoinPub}`);

    if (!brokenCoinPub) {
      return recoverPayAfterStableFailure(ctx, {
        code: TalerErrorCode.WALLET_TRANSACTION_PROTOCOL_VIOLATION,
        message: "Exchange claimed bad coin, but coin was not used.",
        brokenCoinPub,
      });
    }
    if (!proposal.payInfo?.payCoinSelection?.coinPubs.includes(brokenCoinPub)) {
      return recoverPayAfterStableFailure(ctx, {
        code: TalerErrorCode.WALLET_TRANSACTION_PROTOCOL_VIOLATION,
        message: "Exchange claimed a bad coin that was not used in payment.",
        brokenCoinPub,
      });
    }
  } else if (
    err.code ===
    TalerErrorCode.MERCHANT_POST_ORDERS_ID_PAY_DENOMINATION_KEY_NOT_FOUND
  ) {
    // We might support this in the future.
    return recoverPayAfterStableFailure(ctx, {
      code: TalerErrorCode.WALLET_TRANSACTION_PROTOCOL_VIOLATION,
      message: "Denomination used in payment became invalid.",
      errorDetails: err,
    });
  } else {
    // Caller should have checked.
    throw Error(`unsupported error code: ${err.code}`);
  }

  if (!proposal.payInfo) {
    return TaskRunResult.backoff();
  }

  // FIXME: Above code should go into the transaction.
  // TODO: also do token re-selection.

  const repair = await wex.runWalletDbTx(async (tx) => {
    return reselectCoinsTx(tx, ctx, { excludeCoinPub: brokenCoinPub });
  });

  if (repair === "insufficient") {
    return recoverPayAfterStableFailure(ctx, err);
  }
  if (repair === "gone") {
    return TaskRunResult.finished();
  }

  wex.ws.notify({
    type: NotificationType.BalanceChange,
    hintTransactionId: constructTransactionIdentifier({
      tag: TransactionType.Payment,
      proposalId,
    }),
  });

  return TaskRunResult.progress();
}

export function isStableMerchantPayFailure(httpStatus: number): boolean {
  switch (httpStatus) {
    case HttpStatusCode.BadRequest:
    case HttpStatusCode.PaymentRequired:
    case HttpStatusCode.Forbidden:
    case HttpStatusCode.NotFound:
    case HttpStatusCode.Conflict:
    case HttpStatusCode.Gone:
    case HttpStatusCode.PreconditionFailed:
    case HttpStatusCode.PayloadTooLarge:
    case HttpStatusCode.UnavailableForLegalReasons:
    case HttpStatusCode.NotImplemented:
      return true;
    default:
      return false;
  }
}

async function repairPayAfterExchangeFailure(
  wex: WalletExecutionContext,
  ctx: PayMerchantTransactionContext,
  refusedExchangeBaseUrls: string[],
  reason: TalerErrorDetail,
): Promise<TaskRunResult> {
  const refused = new Set(refusedExchangeBaseUrls);
  if (refused.size === 0) {
    return recoverPayAfterStableFailure(ctx, reason);
  }
  const repair = await wex.runWalletDbTx(async (tx) => {
    return reselectCoinsTx(tx, ctx, {
      excludeExchangeBaseUrls: refused,
    });
  });
  if (repair === "gone") {
    return TaskRunResult.finished();
  }
  if (repair === "insufficient") {
    return recoverPayAfterStableFailure(ctx, reason);
  }
  wex.ws.notify({
    type: NotificationType.BalanceChange,
    hintTransactionId: ctx.transactionId,
  });
  return TaskRunResult.progress();
}

function exactAcceptedExchangeHint(
  purchase: WalletPurchase,
  contractTerms: MerchantContractTerms,
  detail: TalerErrorDetail,
): string[] {
  if (typeof detail.hint !== "string") {
    return [];
  }
  const accepted = contractTerms.exchanges.some((x) => x.url === detail.hint);
  const selected = purchase.exchanges?.includes(detail.hint) ?? false;
  return accepted && selected ? [detail.hint] : [];
}

export async function preparePayForUriV2(
  wex: WalletExecutionContext,
  talerPayUri: string,
): Promise<PreparePayV2Result> {
  const uriResult = Result.orUndefined(
    TalerUris.parseRestricted(talerPayUri, TalerUriAction.Pay),
  );

  if (!uriResult) {
    throw TalerError.fromDetail(
      TalerErrorCode.WALLET_INVALID_TALER_PAY_URI,
      {
        talerPayUri,
      },
      `invalid taler://pay URI (${talerPayUri})`,
    );
  }

  const proposalRes = await createOrReusePurchase(
    wex,
    uriResult.merchantBaseUrl,
    uriResult.orderId,
    uriResult.sessionId,
    uriResult.claimToken,
    uriResult.noncePriv,
    talerPayUri,
  );

  return {
    transactionId: proposalRes.transactionId,
  };
}

export async function preparePayForTemplateV2(
  wex: WalletExecutionContext,
  req: PreparePayTemplateRequest,
): Promise<PreparePayV2Result> {
  return runWithMaybeProgressContext(
    wex,
    "preparePayForTemplateV2",
    req.progressToken,
    async () => {
      const res = await instantiateTemplateRaw(wex, req);
      const proposalRes = await createOrReusePurchase(
        wex,
        res.merchantBaseUrl,
        res.orderId,
        res.sessionId,
        res.claimToken,
        undefined,
        req.talerPayTemplateUri,
      );

      return {
        transactionId: proposalRes.transactionId,
      };
    },
  );
}

/**
 * Generate deposit permissions for a purchase.
 *
 * Accesses the database and the crypto worker.
 */
export async function generateDepositPermissions(
  wex: WalletExecutionContext,
  payCoinSel: WalletCoinSelection,
  contractData: MerchantContractTerms,
  contractTermsHash: HashCodeString,
  walletData?: PayWalletData,
  cacheScope?: string,
): Promise<CoinDepositPermission[]> {
  const coinWithDenom: Array<{
    coin: WalletCoin;
    denom: WalletDenomination;
  }> = [];
  await wex.runWalletDbTx(async (tx) => {
    const coins = await tx.getCoinsByPubs(payCoinSel.coinPubs);
    const coinsByPub = new Map(coins.map((coin) => [coin.coinPub, coin]));
    const loadedDenoms = await tx.getDenominationsByRefs(coins);
    const denoms = new Map(
      loadedDenoms.map((denom) => [denomRefKey(denom), denom]),
    );
    for (const coinPub of payCoinSel.coinPubs) {
      const coin = coinsByPub.get(coinPub);
      if (!coin) {
        throw Error("can't pay, allocated coin not found anymore");
      }
      const denom = denoms.get(denomRefKey(coin));
      if (!denom) {
        throw Error(
          "can't pay, denomination of allocated coin not found anymore",
        );
      }
      coinWithDenom.push({ coin, denom });
    }
  });

  for (const exchangeBaseUrl of new Set(
    coinWithDenom.map(({ coin }) => coin.exchangeBaseUrl),
  )) {
    await requireExchangeCoinUseConfirmedOrThrow(wex, exchangeBaseUrl);
  }

  const walletDataHash = walletData
    ? encodeCrock(hashPayWalletData(walletData))
    : undefined;
  const signRequests = coinWithDenom.map(({ coin, denom }, i) => {
    return {
      coinPriv: coin.coinPriv,
      coinPub: coin.coinPub,
      contractTermsHash,
      denomPubHash: coin.denomPubHash,
      denomKeyType: denom.denomPub.cipher,
      denomSig: coin.denomSig,
      exchangeBaseUrl: coin.exchangeBaseUrl,
      feeDeposit: Amounts.parseOrThrow(denom.fees.feeDeposit),
      merchantPub: contractData.merchant_pub,
      refundDeadline: contractData.refund_deadline,
      spendAmount: Amounts.parseOrThrow(payCoinSel.coinContributions[i]),
      timestamp: contractData.timestamp,
      wireInfoHash: contractData.h_wire,
      ageCommitmentProof: coin.ageCommitmentProof,
      requiredMinimumAge: contractData.minimum_age,
      walletDataHash,
    };
  });

  if (!cacheScope) {
    return await Promise.all(
      signRequests.map((req) => wex.cryptoApi.signDepositPermission(req)),
    );
  }
  const cacheKey = encodeCrock(
    hash(stringToBytes(JSON.stringify([cacheScope, signRequests]))),
  );
  const cached = wex.ws.depositPermissionCache.get(cacheKey);
  if (cached) {
    return await cached;
  }
  const generated = Promise.all(
    signRequests.map((req) => wex.cryptoApi.signDepositPermission(req)),
  );
  wex.ws.cacheDepositPermissions(cacheScope, cacheKey, generated);
  try {
    return await generated;
  } catch (e) {
    wex.ws.forgetDepositPermission(cacheScope, cacheKey);
    throw e;
  }
}

/**
 * Wait until either:
 * a) the payment succeeded (if provided under the {@param waitSessionId}), or
 * b) the attempt to pay failed (merchant unavailable, etc.)
 */
async function waitPaymentResult(
  wex: WalletExecutionContext,
  proposalId: string,
  waitSessionId?: string,
): Promise<ConfirmPayResult> {
  const ctx = new PayMerchantTransactionContext(wex, proposalId);
  wex.taskScheduler.startShepherdTask(ctx.taskId);

  logger.info(`waiting for payment result on ${ctx.transactionId}`);

  return await genericWaitForStateVal<ConfirmPayResult>(wex, {
    filterNotification(notif) {
      return (
        notif.type === NotificationType.TransactionStateTransition &&
        notif.transactionId === ctx.transactionId
      );
    },
    async checkState() {
      const txRes = await ctx.wex.runWalletDbTx(async (tx) => {
        const purchase = await tx.getPurchase(ctx.proposalId);
        const retryRecord = await tx.getOperationRetry(ctx.taskId);
        return { purchase, retryRecord };
      });

      if (!txRes.purchase) {
        throw Error("purchase gone");
      }

      const purchase = txRes.purchase;

      logger.info(
        `purchase is in state ${PurchaseStatus[purchase.purchaseStatus]}`,
      );

      const d = await expectProposalDownload(ctx.wex, purchase);

      if (isPaymentSessionComplete(txRes.purchase, waitSessionId)) {
        return {
          type: ConfirmPayResultType.Done,
          contractTerms: d.contractTermsRaw,
          transactionId: ctx.transactionId,
        };
      }

      if (txRes.retryRecord && txRes.retryRecord.retryInfo.retryCounter > 0) {
        logger.info(
          `stopping waiting for payment result, got retry record: ${j2s(
            txRes.retryRecord,
          )}`,
        );
        return {
          type: ConfirmPayResultType.Pending,
          lastError: txRes.retryRecord.lastError,
          transactionId: ctx.transactionId,
        };
      }

      if (
        isUnsuccessfulTransaction(computePayMerchantTransactionState(purchase))
      ) {
        // The payment gave up instead of going through. Reporting it as done
        // would tell the caller that the purchase succeeded, so it is
        // reported like a payment that has not happened (yet), with whatever
        // reason the transaction recorded for giving up.
        return {
          type: ConfirmPayResultType.Pending,
          lastError: purchase.failReason ?? purchase.abortReason,
          transactionId: ctx.transactionId,
        };
      }

      if (txRes.purchase.purchaseStatus >= PurchaseStatus.Done) {
        return {
          type: ConfirmPayResultType.Done,
          contractTerms: d.contractTermsRaw,
          transactionId: ctx.transactionId,
        };
      }

      return undefined;
    },
  });
}

export function isPaymentSessionComplete(
  purchase: Pick<
    WalletPurchase,
    "timestampFirstSuccessfulPay" | "lastSessionId" | "purchaseStatus"
  >,
  waitSessionId?: string,
): boolean {
  if (!purchase.timestampFirstSuccessfulPay) {
    return false;
  }
  if (waitSessionId == null) {
    return true;
  }
  if (purchase.lastSessionId !== waitSessionId) {
    return false;
  }
  return ![
    PurchaseStatus.PendingPayingReplay,
    PurchaseStatus.SuspendedPayingReplay,
  ].includes(purchase.purchaseStatus);
}

export async function getChoicesForPayment(
  wex: WalletExecutionContext,
  transactionId: string,
  forcedCoinSel?: ForcedCoinSel,
): Promise<GetChoicesForPaymentResult> {
  const parsedTx = parseTransactionIdentifier(transactionId);
  if (parsedTx?.tag !== TransactionType.Payment) {
    throw makeInvalidTransactionIdError(transactionId, TransactionType.Payment);
  }
  const proposalId = parsedTx.proposalId;
  const { proposal, d } = await wex.runWalletDbTx(async (tx) => {
    const proposal = await tx.getPurchase(proposalId);
    let d: DownloadedContractData | undefined = undefined;
    if (proposal) {
      const download = proposal.download;
      if (!download) {
        return { proposal };
      }
      const contractTermsRec = await tx.getContractTerms(
        download.contractTermsHash,
      );
      if (contractTermsRec) {
        d = {
          contractTerms: codecForMerchantContractTerms().decode(
            contractTermsRec.contractTermsRaw,
          ),
          contractTermsRaw: contractTermsRec.contractTermsRaw,
          contractTermsHash: contractTermsRec.h,
        };
      }
    }
    return { proposal, d };
  });

  if (!proposal) {
    throw makeTransactionNotFoundError(transactionId);
  }

  if (!d) {
    throw TalerError.fromDetail(
      TalerErrorCode.WALLET_REQUEST_TRANSACTION_STATE_UNSUPPORTED,
      {
        txState: computePayMerchantTransactionState(proposal),
        debugStateNum: proposal.purchaseStatus,
      },
    );
  }

  const choices: ChoiceSelectionDetail[] = [];
  await wex.runWalletDbTx(async (tx) => {
    const tokenSels: SelectPayTokensResult[] = [];
    const contractTerms: MerchantContractTerms = d.contractTerms;
    switch (contractTerms.version) {
      case undefined:
      case MerchantContractVersion.V0:
        tokenSels.push({
          type: "success",
          tokens: [],
          details: {
            tokensRequested: 0,
            tokensAvailable: 0,
            tokensUnexpected: 0,
            tokensUntrusted: 0,
            perTokenFamily: {},
          },
        });
        break;
      case MerchantContractVersion.V1:
        for (let i = 0; i < contractTerms.choices.length; i++) {
          tokenSels.push(
            await selectPayTokensInTx(tx, {
              proposalId,
              choiceIndex: i,
              contractTerms: contractTerms,
            }),
          );
        }
        break;
      default:
        assertUnreachable(contractTerms);
    }

    for (let i = 0; i < tokenSels.length; i++) {
      const choiceIndex = i;
      const tokenSelection = tokenSels[choiceIndex];
      logger.trace("token selection result", tokenSelection);

      let balanceDetails: PaymentInsufficientBalanceDetails | undefined =
        undefined;

      const { available, amountRaw, maxFee } = ContractTermsUtil.extractAmounts(
        contractTerms,
        choiceIndex,
      );
      if (!available) {
        throw TalerError.fromDetail(
          TalerErrorCode.WALLET_CORE_API_BAD_REQUEST,
          { parameter: "choiceIndex" },
          "a contract v1 payment requires a choice index",
        );
      }

      let amountEffective: AmountJson | undefined = undefined;
      const currency = Amounts.currencyOf(amountRaw);

      const selectCoinsResult = await selectPayCoinsInTx(wex, tx, {
        restrictExchanges: {
          auditors: [],
          exchanges: contractTerms.exchanges.map((ex) => ({
            exchangeBaseUrl: ex.url,
            exchangePub: ex.master_pub,
          })),
        },
        restrictWireMethod: contractTerms.wire_method,
        contractTermsAmount: Amounts.parseOrThrow(amountRaw),
        depositFeeLimit: Amounts.parseOrThrow(maxFee),
        prevPayCoins: [],
        requiredMinimumAge: contractTerms.minimum_age,
        forcedSelection: forcedCoinSel,
      });

      logger.trace("coin selection result", selectCoinsResult);

      const exchanges: Set<string> = new Set();

      switch (selectCoinsResult.type) {
        case "success": {
          amountEffective = await getTotalPaymentCostInTx(
            wex,
            tx,
            currency,
            selectCoinsResult.coinSel.coins,
          );
          selectCoinsResult.coinSel.coins.forEach((x) => {
            exchanges.add(x.exchangeBaseUrl);
          });
          break;
        }
        case "failure": {
          logger.info("choice not payable, insufficient coins");
          balanceDetails = selectCoinsResult.insufficientBalanceDetails;
          break;
        }
        default:
          assertUnreachable(selectCoinsResult);
      }

      let choice: ChoiceSelectionDetail;
      if (
        tokenSelection.type === "failure" ||
        selectCoinsResult.type === "failure"
      ) {
        choice = {
          status: ChoiceSelectionDetailType.InsufficientBalance,
          amountRaw: amountRaw,
          balanceDetails: balanceDetails,
          tokenDetails: tokenSelection.details,
        };
      } else {
        // We use the first known scope for the
        // exchanges of the selected coins.
        let scopeInfo: ScopeInfo | undefined = undefined;
        for (const exch of exchanges) {
          const s = await getExchangeScopeInfoOrUndefined(tx, exch);
          if (s != null) {
            scopeInfo = s;
            break;
          }
        }
        choice = {
          status: ChoiceSelectionDetailType.PaymentPossible,
          scopeInfo,
          amountRaw: amountRaw,
          amountEffective: Amounts.stringify(amountEffective!),
          tokenDetails: tokenSelection.details,
        };
      }

      choices.push(choice);
    }
  });

  return {
    choices,
    contractTerms: d.contractTerms,
    ...(await calculateDefaultChoice(wex, choices, d.contractTerms)),
  };
}

async function calculateDefaultChoice(
  wex: WalletExecutionContext,
  choiceDetails: ChoiceSelectionDetail[],
  contractTerms: MerchantContractTerms,
): Promise<{
  defaultChoiceIndex?: number;
  automaticExecution?: boolean;
  automaticExecutableIndex?: number;
}> {
  let defaultChoiceIndex: number | undefined;
  let automaticExecution: boolean | undefined;
  let automaticExecutableIndex: number | undefined;
  switch (contractTerms.version) {
    case undefined:
    case MerchantContractVersion.V0:
      return {
        defaultChoiceIndex: 0,
        automaticExecution: false,
      };
    case MerchantContractVersion.V1: {
      if (contractTerms.choices.length === 0)
        throw TalerError.fromDetail(
          TalerErrorCode.WALLET_CONTRACT_TERMS_MALFORMED,
          {},
          "a contract v1 must offer at least one choice",
        );

      // If there's only one choice, use it.
      if (
        contractTerms.choices.length === 1 &&
        choiceDetails[0].status === ChoiceSelectionDetailType.PaymentPossible
      ) {
        defaultChoiceIndex = 0;
        break;
      }

      // If there are more, choose the payable one with lowest amount.
      let cheapestPayableIndex: number | undefined;
      let cheapestPayableChoice:
        | (typeof contractTerms.choices)[number]
        | undefined;
      for (let i = 0; i < contractTerms.choices.length; i++) {
        const choice = contractTerms.choices[i];
        const details = choiceDetails[i];
        if (details.status !== ChoiceSelectionDetailType.PaymentPossible) {
          continue;
        }
        if (
          cheapestPayableChoice == null ||
          Amounts.cmp(choice.amount, cheapestPayableChoice.amount) < 0
        ) {
          cheapestPayableIndex = i;
          cheapestPayableChoice = choice;
        }
      }

      defaultChoiceIndex = cheapestPayableIndex;

      // If the cheapest choice has one subscription input and one
      // subscription output of the same type, and it's free, then it can be
      // automatically confirmed without user confirmation.
      //
      // TODO: in the future, a setting should allow the user to specify
      // merchants where discounts should be automatically spent.
      automaticExecution = false;
      for (let i = 0; i < contractTerms.choices.length; i++) {
        const choice = contractTerms.choices[i];
        const details = choiceDetails[i];
        if (
          Amounts.isZero(choice.amount) &&
          choice.inputs.length === 1 &&
          choice.outputs.length === 1 &&
          !details.tokenDetails?.tokensUnexpected &&
          choice.inputs[0].type === MerchantContractInputType.Token &&
          choice.outputs[0].type === MerchantContractOutputType.Token &&
          (choice.inputs[0].count ?? 1) === 1 &&
          (choice.outputs[0].count ?? 1) === 1 &&
          choice.inputs[0].token_family_slug ===
            choice.outputs[0].token_family_slug
        ) {
          automaticExecution =
            details.status === ChoiceSelectionDetailType.PaymentPossible;
          automaticExecutableIndex = i;
          break;
        }
      }
      break;
    }
    default:
      assertUnreachable(contractTerms);
  }

  return {
    defaultChoiceIndex,
    automaticExecution,
    automaticExecutableIndex,
  };
}

/**
 * Confirm payment for a proposal previously claimed by the wallet.
 */
export async function confirmPay(
  wex: WalletExecutionContext,
  args: {
    transactionId: string;
    sessionIdOverride?: string;
    forcedCoinSel?: ForcedCoinSel;
    choiceIndex?: number;
    useDonau?: boolean;
    noWait?: boolean;
  },
): Promise<ConfirmPayResult> {
  const { transactionId, sessionIdOverride, forcedCoinSel } = args;
  let { choiceIndex } = args;

  const parsedTx = parseTransactionIdentifier(transactionId);
  if (parsedTx?.tag !== TransactionType.Payment) {
    throw makeInvalidTransactionIdError(transactionId, TransactionType.Payment);
  }
  const proposalId = parsedTx.proposalId;
  const ctx = new PayMerchantTransactionContext(wex, proposalId);
  logger.trace(
    `executing confirmPay with proposalId ${proposalId} and sessionIdOverride ${sessionIdOverride}`,
  );
  const proposal = await wex.runWalletDbTx(async (tx) => {
    return tx.getPurchase(proposalId);
  });

  if (!proposal) {
    throw makeTransactionNotFoundError(transactionId);
  }

  const d = await expectProposalDownload(wex, proposal);
  if (!d) {
    throw TalerError.fromDetail(
      TalerErrorCode.WALLET_REQUEST_TRANSACTION_STATE_UNSUPPORTED,
      {
        txState: computePayMerchantTransactionState(proposal),
        debugStateNum: proposal.purchaseStatus,
      },
      "the contract terms of this payment have not been downloaded yet",
    );
  }

  const existingPurchase = await wex.runWalletDbTx(async (tx) => {
    const purchase = await tx.getPurchase(proposalId);
    if (
      purchase &&
      sessionIdOverride !== undefined &&
      sessionIdOverride != purchase.lastSessionId
    ) {
      logger.trace(`changing session ID to ${sessionIdOverride}`);
      purchase.lastSessionId = sessionIdOverride;
      if (purchase.purchaseStatus === PurchaseStatus.Done) {
        purchase.purchaseStatus = PurchaseStatus.PendingPayingReplay;
      }
      await tx.upsertPurchase(purchase);
      await ctx.updateTransactionMeta(tx);
    }
    return purchase;
  });

  if (existingPurchase && existingPurchase.payInfo) {
    if (
      choiceIndex !== undefined &&
      choiceIndex !== existingPurchase.choiceIndex
    ) {
      throw TalerError.fromDetail(
        TalerErrorCode.WALLET_CORE_API_BAD_REQUEST,
        { parameter: "choiceIndex" },
        "the choice index of an existing purchase cannot be changed",
      );
    }

    logger.trace("confirmPay: submitting payment for existing purchase");
    const ctx = new PayMerchantTransactionContext(
      wex,
      existingPurchase.proposalId,
    );
    await wex.taskScheduler.resetTask(ctx.taskId);
    if (args.noWait) {
      return {
        type: ConfirmPayResultType.Pending,
        transactionId: transactionId as TransactionIdStr,
        lastError: undefined,
      };
    }
    return waitPaymentResult(wex, proposalId, sessionIdOverride);
  }

  logger.trace("confirmPay: purchase record does not exist yet");

  const contractTerms = d.contractTerms;

  const { available, amountRaw, maxFee } = ContractTermsUtil.extractAmounts(
    contractTerms,
    choiceIndex,
  );
  if (!available) {
    throw TalerError.fromDetail(
      TalerErrorCode.WALLET_CORE_API_BAD_REQUEST,
      { parameter: "choiceIndex" },
      "a contract v1 payment requires a choice index",
    );
  }

  const currency = Amounts.currencyOf(amountRaw);

  let sessionId: string | undefined;
  if (sessionIdOverride) {
    sessionId = sessionIdOverride;
  } else {
    sessionId = proposal.downloadSessionId;
  }

  logger.trace(
    `recording payment on ${proposal.orderId} with session ID ${sessionId}`,
  );

  await wex.runWalletDbTx(async (tx) => {
    const [p, h] = await ctx.getRecordHandle(tx);
    if (!p) {
      return;
    }

    let selectTokensResult: SelectPayTokensResult | undefined;

    if (contractTerms.version === MerchantContractVersion.V1) {
      selectTokensResult = await selectPayTokensInTx(tx, {
        proposalId,
        choiceIndex: choiceIndex!,
        contractTerms,
      });

      switch (selectTokensResult.type) {
        case "failure": {
          logger.warn("not confirming payment, insufficient tokens");
          throw TalerError.fromDetail(
            TalerErrorCode.WALLET_REQUEST_TRANSACTION_STATE_UNSUPPORTED,
            {
              txState: computePayMerchantTransactionState(proposal),
              debugStateNum: proposal.purchaseStatus,
            },
            "the wallet does not hold the tokens that this choice requires",
          );
        }
      }

      logger.trace("token selection result", selectTokensResult);
    }

    const selectCoinsResult = await selectPayCoinsInTx(wex, tx, {
      restrictExchanges: {
        auditors: [],
        exchanges: contractTerms.exchanges.map((ex) => ({
          exchangeBaseUrl: ex.url,
          exchangePub: ex.master_pub,
        })),
      },
      restrictWireMethod: contractTerms.wire_method,
      contractTermsAmount: Amounts.parseOrThrow(amountRaw),
      depositFeeLimit: Amounts.parseOrThrow(maxFee),
      prevPayCoins: [],
      requiredMinimumAge: contractTerms.minimum_age,
      forcedSelection: forcedCoinSel,
    });

    let coins: SelectedProspectiveCoin[] | undefined = undefined;

    switch (selectCoinsResult.type) {
      case "failure": {
        logger.warn("not confirming payment, insufficient coins");
        throw TalerError.fromDetail(
          TalerErrorCode.WALLET_PAY_MERCHANT_INSUFFICIENT_BALANCE,
          {
            insufficientBalanceDetails:
              selectCoinsResult.insufficientBalanceDetails,
          },
        );
      }
      case "success":
        coins = selectCoinsResult.coinSel.coins;
        break;
      default:
        assertUnreachable(selectCoinsResult);
    }

    logger.trace("coin selection result", selectCoinsResult);

    const payCostInfo = await getTotalPaymentCostInTx(wex, tx, currency, coins);

    p.choiceIndex = choiceIndex;
    if (
      p.download &&
      choiceIndex !== undefined &&
      contractTerms.version === MerchantContractVersion.V1
    ) {
      const amount = contractTerms.choices[choiceIndex].amount;
      p.download.currency = Amounts.currencyOf(amount);
    }

    const confRes = await tx.getConfig(ConfigRecordKey.DonauConfig);

    if (
      confRes != null &&
      args.useDonau &&
      choiceIndex != null &&
      contractTerms.version === MerchantContractVersion.V1 &&
      p.donauOutputIndex == null
    ) {
      const choice = contractTerms.choices[choiceIndex];

      for (let j = 0; j < choice.outputs.length; j++) {
        const out = choice.outputs[j];
        if (
          out.type === MerchantContractOutputType.TaxReceipt &&
          out.donau_urls.includes(confRes.value.donauBaseUrl)
        ) {
          p.donauOutputIndex = j;
          p.donauBaseUrl = confRes.value.donauBaseUrl;
          p.donauYear = new Date().getFullYear();
          p.donauAmount =
            out.amount ?? contractTerms.choices[choiceIndex].amount;
          p.donauTaxIdHash = confRes.value.donauTaxIdHash;
          p.donauTaxId = confRes.value.donauTaxId;
          p.donauTaxIdSalt = confRes.value.donauSalt;
          break;
        }
      }
    }

    switch (p.purchaseStatus) {
      case PurchaseStatus.DialogShared:
      case PurchaseStatus.DialogProposed:
        p.payInfo = {
          totalPayCost: Amounts.stringify(payCostInfo),
        };
        if (selectTokensResult?.type === "success") {
          const tokens = selectTokensResult.tokens;
          p.payInfo.payTokenSelection = {
            tokenPubs: tokens.map((t) => t.tokenUsePub),
          };
        }
        if (selectCoinsResult.type === "success") {
          setCoinSel(p, selectCoinsResult.coinSel);
        }
        p.lastSessionId = sessionId;
        p.timestampAccept = timestampPreciseToDb(TalerPreciseTimestamp.now());
        p.purchaseStatus = PurchaseStatus.PendingPaying;
        await h.update(p, "confirm-pay");
        if (p.payInfo.payTokenSelection) {
          await spendTokens(tx, {
            tokenPubs: p.payInfo.payTokenSelection.tokenPubs,
            transactionId: ctx.transactionId,
          });
        }
        if (p.payInfo.payCoinSelection) {
          const sel = p.payInfo.payCoinSelection;
          await spendCoins(wex, tx, {
            transactionId: transactionId as TransactionIdStr,
            coinPubs: sel.coinPubs,
            contributions: sel.coinContributions.map((x) =>
              Amounts.parseOrThrow(x),
            ),
            refreshReason: RefreshReason.PayMerchant,
          });
        }
        break;
      case PurchaseStatus.Done:
      case PurchaseStatus.PendingPaying:
      default:
        break;
    }
  });

  // TODO: pre-generate slates based on choice priority!
  if (
    choiceIndex != null &&
    contractTerms.version === MerchantContractVersion.V1
  ) {
    const choice = contractTerms.choices[choiceIndex];
    for (let j = 0; j < choice.outputs.length; j++) {
      const tok = choice.outputs[j];
      switch (tok.type) {
        case MerchantContractOutputType.Token: {
          const tokCount = tok.count ?? 1;
          for (let repeatIndex = 0; repeatIndex < tokCount; repeatIndex++) {
            await generateSlate(
              wex,
              proposal,
              contractTerms,
              d.contractTermsRaw,
              choiceIndex,
              j,
              repeatIndex,
            );
          }

          break;
        }
        case MerchantContractOutputType.TaxReceipt:
          // FIXME: What if we have multiple?
          await generateDonauPlanchets(wex, proposalId);
          break;
      }
    }
  }

  // In case we're sharing the payment and we're long-polling
  await wex.taskScheduler.resetTask(ctx.taskId);

  if (args.noWait) {
    wex.taskScheduler.startShepherdTask(ctx.taskId);
    return {
      type: ConfirmPayResultType.Pending,
      transactionId: transactionId as TransactionIdStr,
      lastError: undefined,
    };
  }

  // Wait until we have completed the first attempt to pay.
  return waitPaymentResult(wex, proposalId);
}

export async function processPurchase(
  wex: WalletExecutionContext,
  proposalId: string,
): Promise<TaskRunResult> {
  const purchase = await wex.runWalletDbTx(async (tx) => {
    return tx.getPurchase(proposalId);
  });
  if (!purchase) {
    return {
      type: TaskRunResultType.Error,
      errorDetail: {
        // FIXME: allocate more specific error code
        code: TalerErrorCode.WALLET_UNEXPECTED_EXCEPTION,
        when: AbsoluteTime.now(),
        hint: `trying to pay for purchase that is not in the database`,
        proposalId: proposalId,
      },
    };
  }

  if (!wex.ws.networkAvailable) {
    return TaskRunResult.networkRequired();
  }

  switch (purchase.purchaseStatus) {
    case PurchaseStatus.PendingDownloadingProposal:
      // Consumes the entry, so that only the first attempt after a cold
      // start is the decisive one.
      if (wex.ws.leftoverClaims.delete(proposalId)) {
        return retryLeftoverClaim(wex, proposalId);
      }
      return processDownloadProposal(wex, proposalId);
    case PurchaseStatus.PendingPaying:
    case PurchaseStatus.PendingPayingReplay:
      return processPurchasePay(wex, proposalId);
    case PurchaseStatus.PendingQueryingRefund:
      return processPurchaseQueryRefund(wex, purchase);
    case PurchaseStatus.FinalizingQueryingAutoRefund:
    case PurchaseStatus.PendingQueryingAutoRefund:
      return processPurchaseAutoRefund(wex, purchase);
    case PurchaseStatus.AbortingWithRefund:
      return processPurchaseAbortingRefund(wex, purchase);
    case PurchaseStatus.PendingAcceptRefund:
      return processPurchaseAcceptRefund(wex, purchase);
    case PurchaseStatus.DialogShared:
      return processPurchaseDialogShared(wex, purchase);
    case PurchaseStatus.DialogUnclaimed:
      return processPurchaseDialogUnclaimed(wex, purchase);
    case PurchaseStatus.DialogProposed:
      return processPurchaseDialogProposed(wex, purchase);
    case PurchaseStatus.FailedClaim:
    case PurchaseStatus.Done:
    case PurchaseStatus.DoneRepurchaseDetected:
    case PurchaseStatus.AbortedProposalRefused:
    case PurchaseStatus.AbortedIncompletePayment:
    case PurchaseStatus.AbortedClaimedByOther:
    case PurchaseStatus.AbortedOrderDeleted:
    case PurchaseStatus.AbortedRefunded:
    case PurchaseStatus.SuspendedAbortingWithRefund:
    case PurchaseStatus.SuspendedDownloadingProposal:
    case PurchaseStatus.SuspendedPaying:
    case PurchaseStatus.SuspendedPayingReplay:
    case PurchaseStatus.SuspendedPendingAcceptRefund:
    case PurchaseStatus.SuspendedQueryingAutoRefund:
    case PurchaseStatus.SuspendedQueryingRefund:
    case PurchaseStatus.SuspendedFinalizingQueryingAutoRefund:
    case PurchaseStatus.Failed:
    case PurchaseStatus.FailedAbort:
    case PurchaseStatus.FailedPaidByOther:
    case PurchaseStatus.Expired:
      return TaskRunResult.finished();
    default:
      assertUnreachable(purchase.purchaseStatus);
  }
}

async function processPurchasePay(
  wex: WalletExecutionContext,
  proposalId: string,
): Promise<TaskRunResult> {
  const purchase = await wex.runWalletDbTx(async (tx) => {
    return tx.getPurchase(proposalId);
  });
  if (!purchase) {
    return {
      type: TaskRunResultType.Error,
      errorDetail: {
        // FIXME: allocate more specific error code
        code: TalerErrorCode.WALLET_UNEXPECTED_EXCEPTION,
        when: AbsoluteTime.now(),
        hint: `trying to pay for purchase that is not in the database`,
        proposalId: proposalId,
      },
    };
  }
  switch (purchase.purchaseStatus) {
    case PurchaseStatus.PendingPaying:
    case PurchaseStatus.PendingPayingReplay:
      break;
    default:
      return TaskRunResult.finished();
  }
  logger.trace(`processing purchase pay ${proposalId}`);

  const ctx = new PayMerchantTransactionContext(wex, proposalId);

  const sessionId = purchase.lastSessionId;

  logger.trace(`paying with session ID ${sessionId}`);
  const payInfo = purchase.payInfo;
  checkDbInvariant(!!payInfo, `purchase ${purchase.orderId} without payInfo`);

  const download = await expectProposalDownload(wex, purchase);

  if (isSharedPurchase(purchase)) {
    const orderStatus = await checkIfOrderIsAlreadyPaid(wex, download, false);

    if (orderStatus === "gone") {
      return abortPayForDeletedOrder(wex, ctx);
    }

    if (orderStatus === "paid") {
      await wex.runWalletDbTx(async (tx) => {
        const [p, h] = await ctx.getRecordHandle(tx);
        if (!p) {
          return;
        }
        p.purchaseStatus = PurchaseStatus.FailedPaidByOther;
        await h.update(p, "pay-paid-by-other");
      });

      return {
        type: TaskRunResultType.Error,
        errorDetail: makeErrorDetail(TalerErrorCode.WALLET_ORDER_ALREADY_PAID, {
          orderId: purchase.orderId,
          fulfillmentUrl: download.contractTerms.fulfillment_url,
        }),
      };
    }
  }

  const choiceIndex = purchase.choiceIndex;
  const { available, amountRaw, maxFee } = ContractTermsUtil.extractAmounts(
    download.contractTerms,
    choiceIndex,
  );
  if (!available) {
    throw Error("choice index not specified for contract v1");
  }

  const currency = Amounts.currencyOf(amountRaw);

  if (!payInfo.payCoinSelection) {
    const selectCoinsResult = await selectPayCoins(wex, {
      restrictExchanges: {
        auditors: [],
        exchanges: download.contractTerms.exchanges.map((ex) => ({
          exchangeBaseUrl: ex.url,
          exchangePub: ex.master_pub,
        })),
      },
      restrictWireMethod: download.contractTerms.wire_method,
      contractTermsAmount: Amounts.parseOrThrow(amountRaw),
      depositFeeLimit: Amounts.parseOrThrow(maxFee),
      prevPayCoins: [],
      requiredMinimumAge: download.contractTerms.minimum_age,
    });
    switch (selectCoinsResult.type) {
      case "failure": {
        throw TalerError.fromDetail(
          TalerErrorCode.WALLET_PAY_MERCHANT_INSUFFICIENT_BALANCE,
          {
            insufficientBalanceDetails:
              selectCoinsResult.insufficientBalanceDetails,
          },
        );
      }
      case "success":
        break;
      default:
        assertUnreachable(selectCoinsResult);
    }

    logger.trace("coin selection result", selectCoinsResult);

    const payCostInfo = await getTotalPaymentCost(
      wex,
      currency,
      selectCoinsResult.coinSel.coins,
    );

    const transitionDone = await wex.runWalletDbTx(async (tx) => {
      const p = await tx.getPurchase(proposalId);
      if (!p) {
        return false;
      }
      if (p.payInfo?.payCoinSelection) {
        return false;
      }
      switch (p.purchaseStatus) {
        case PurchaseStatus.DialogShared:
        case PurchaseStatus.DialogProposed:
        case PurchaseStatus.PendingPaying:
          p.payInfo = {
            totalPayCost: Amounts.stringify(payCostInfo),
            payCoinSelection: {
              coinContributions: selectCoinsResult.coinSel.coins.map(
                (x) => x.contribution,
              ),
              coinPubs: selectCoinsResult.coinSel.coins.map((x) => x.coinPub),
            },
          };
          p.payInfo.payCoinSelectionUid = encodeCrock(getRandomBytes(16));
          p.purchaseStatus = PurchaseStatus.PendingPaying;
          await tx.upsertPurchase(p);
          await ctx.updateTransactionMeta(tx);
          await spendCoins(wex, tx, {
            transactionId: ctx.transactionId,
            coinPubs: selectCoinsResult.coinSel.coins.map((x) => x.coinPub),
            contributions: selectCoinsResult.coinSel.coins.map((x) =>
              Amounts.parseOrThrow(x.contribution),
            ),
            refreshReason: RefreshReason.PayMerchant,
          });
          return true;
        case PurchaseStatus.Done:
        default:
          break;
      }
      return false;
    });

    if (transitionDone) {
      return TaskRunResult.progress();
    } else {
      return TaskRunResult.backoff();
    }
  }

  if (!purchase.merchantPaySig) {
    let slates: WalletSlate[] | undefined = undefined;
    let donauPlanchets: WalletDonationPlanchet[] | undefined = undefined;
    let wallet_data: PayWalletData | undefined = undefined;
    if (
      download.contractTerms.version === MerchantContractVersion.V1 &&
      purchase.choiceIndex !== undefined
    ) {
      logger.info("assembling tokens");
      logger.info(`donau output index: ${purchase.donauOutputIndex}`);
      const index = purchase.choiceIndex;
      slates = [];
      wallet_data = { choice_index: index, tokens_evs: [] };
      await wex.runWalletDbTx(async (tx) => {
        const slateRes = await tx.getSlatesByPurchaseAndChoice(
          purchase.proposalId,
          index,
        );
        logger.info(
          `got ${slateRes.length} slates from DB, req=${[
            purchase.proposalId,
            index,
          ]}`,
        );
        slateRes.sort(
          (a, b) =>
            (a.outputIndex ?? 0) - (b.outputIndex ?? 0) ||
            (a.repeatIndex ?? 0) - (b.repeatIndex ?? 0),
        );
        slateRes.forEach((s) => {
          slates?.push(s);
          wallet_data?.tokens_evs.push(s.tokenEv);
        });
      });
      if (purchase.donauOutputIndex != null) {
        if (purchase.donauBaseUrl == null || purchase.donauYear == null) {
          throw Error("incomplete donau info in DB");
        }
        const budikeypairs: BlindedDonationReceiptKeyPair[] = [];
        // FIXME: Merge with transaction above
        const res = await wex.runWalletDbTx(async (tx) => {
          const recs = await tx.getDonationPlanchetsByProposal(proposalId);
          recs.sort((a, b) => a.udiIndex - b.udiIndex);
          for (const rec of recs) {
            budikeypairs.push({
              blinded_udi: rec.blindedUdi,
              h_donation_unit_pub: rec.donationUnitPubHash,
            });
          }
          if (recs.length > 0) {
            return {
              donauPlanchets: recs,
            };
          }
          return undefined;
        });
        if (res?.donauPlanchets) {
          donauPlanchets = res.donauPlanchets;
        }
        wallet_data.donau = {
          url: purchase.donauBaseUrl,
          year: purchase.donauYear,
          budikeypairs,
        };
        logger.info(`sending donau data: ${j2s(wallet_data.donau)}`);
      }
      // Note that we may have fewer slates that output tokens,
      // as there are other output types (e.g. slates).
    }

    let depositPermissions: CoinDepositPermission[];
    // FIXME: Cache!
    depositPermissions = await generateDepositPermissions(
      wex,
      payInfo.payCoinSelection,
      download.contractTerms,
      download.contractTermsHash,
      wallet_data,
      proposalId,
    );

    const reqBody: any = {
      coins: depositPermissions,
      wallet_data,
      session_id: purchase.lastSessionId,
    };

    if (wallet_data && payInfo.payTokenSelection) {
      reqBody.tokens = await generateTokenSigs(
        wex,
        proposalId,
        download.contractTermsHash,
        encodeCrock(hashPayWalletData(wallet_data)),
        payInfo.payTokenSelection.tokenPubs,
      );
    }

    if (logger.shouldLogTrace()) {
      logger.trace(`making pay request ... ${j2s(reqBody)}`);
    }

    const merchantClient = walletMerchantClient(
      download.contractTerms.merchant_base_url,
      wex,
      getPayRequestTimeout(purchase),
    );
    const resp = await wex.ws.runSequentialized(
      [EXCHANGE_COINS_LOCK],
      async () => {
        for (const exchangeBaseUrl of new Set(
          depositPermissions.map((x) => x.exchange_url),
        )) {
          await requireExchangeCoinUseConfirmedOrThrow(wex, exchangeBaseUrl);
        }
        return merchantClient.makePayment(
          download.contractTerms.order_id,
          reqBody,
        );
      },
    );

    logger.trace(`got resp ${JSON.stringify(resp)}`);

    switch (resp.case) {
      case "ok":
        break;
      case HttpStatusCode.Conflict: {
        const err = resp.detail!;
        if (
          err.code ===
          TalerErrorCode.MERCHANT_POST_ORDERS_ID_PAY_INSUFFICIENT_FUNDS
        ) {
          return handleInsufficientFunds(wex, proposalId, err);
        }
        if (
          err.code ===
            TalerErrorCode.MERCHANT_POST_ORDERS_ID_PAY_ALREADY_PAID ||
          err.code ===
            TalerErrorCode.MERCHANT_POST_ORDERS_ID_PAY_CHOICE_INDEX_MISMATCH
        ) {
          return recoverPayFailureForCompleteOrder(wex, ctx, err);
        }
        return recoverPayAfterStableFailure(ctx, err);
      }
      case HttpStatusCode.BadRequest: {
        const err = resp.detail!;
        if (
          err.code ===
          TalerErrorCode.MERCHANT_POST_ORDERS_ID_PAY_DENOMINATION_KEY_NOT_FOUND
        ) {
          return handleInsufficientFunds(wex, proposalId, err);
        }
        if (err.code === TalerErrorCode.MERCHANT_GENERIC_EXCHANGE_UNTRUSTED) {
          return repairPayAfterExchangeFailure(
            wex,
            ctx,
            exactAcceptedExchangeHint(purchase, download.contractTerms, err),
            err,
          );
        }
        return recoverPayAfterStableFailure(ctx, err);
      }
      case HttpStatusCode.BadGateway: {
        const err = resp.detail!;
        switch (err.code) {
          case TalerErrorCode.MERCHANT_GENERIC_EXCHANGE_UNEXPECTED_STATUS: {
            const exchangeEc = (err.exchange_reply as any)?.code;
            switch (exchangeEc) {
              case TalerErrorCode.EXCHANGE_GENERIC_DENOMINATION_KEY_UNKNOWN:
                // We might want to handle this in the future by re-denomination,
                // for now we just abort.
                return recoverPayAfterStableFailure(ctx, {
                  code: TalerErrorCode.WALLET_TRANSACTION_PROTOCOL_VIOLATION,
                  message: "Denomination used in payment became invalid.",
                  errorDetails: err,
                });
            }
            break;
          }
        }
        // We don't know the specific error, so it's safer to retry.
        return throwUnexpectedRequestError(resp.response, err);
      }
      case HttpStatusCode.UnavailableForLegalReasons: {
        logger.warn(`exchange refused merchant payment for legal reasons`);
        const legalReason: TalerErrorDetail =
          resp.body.code ===
            TalerErrorCode.MERCHANT_POST_ORDERS_ID_PAY_EXCHANGE_LEGALLY_REFUSED ||
          resp.body.code ===
            TalerErrorCode.MERCHANT_POST_ORDERS_ID_PAY_EXCHANGE_TRANSACTION_LIMIT_VIOLATION
            ? {
                code: resp.body.code,
                exchangeBaseUrls: resp.body.exchange_base_urls,
              }
            : {
                code: TalerErrorCode.WALLET_TRANSACTION_PROTOCOL_VIOLATION,
                message: `merchant returned invalid legal-refusal error code ${resp.body.code}`,
              };
        return repairPayAfterExchangeFailure(
          wex,
          ctx,
          resp.body.exchange_base_urls,
          legalReason,
        );
      }
      case HttpStatusCode.Gone:
        logger.warn(`pay transaction aborted, order expired`);
        await ctx.userAbortTransaction(
          makeTalerErrorDetail(
            TalerErrorCode.WALLET_PAY_MERCHANT_ORDER_GONE,
            {},
          ),
        );
        return TaskRunResult.progress();
      case HttpStatusCode.NotFound: {
        if (!isOrderUnknown(resp)) {
          return recoverPayAfterStableFailure(ctx, resp.detail!);
        }
        logger.warn(`pay transaction aborted, merchant deleted the order`);
        return abortPayForDeletedOrder(wex, ctx);
      }
      case HttpStatusCode.PreconditionFailed: {
        const err = resp.detail!;
        const refusedExchanges = exactAcceptedExchangeHint(
          purchase,
          download.contractTerms,
          err,
        );
        if (refusedExchanges.length > 0) {
          return repairPayAfterExchangeFailure(wex, ctx, refusedExchanges, err);
        }
        return recoverPayAfterStableFailure(ctx, err);
      }
      default:
        logger.info(
          `got error response (http status ${resp.response.status}) from merchant`,
        );
        if (logger.shouldLogTrace()) {
          logger.trace(`error body: ${j2s(resp.detail)}`);
        }
        if (isStableMerchantPayFailure(resp.response.status)) {
          return recoverPayAfterStableFailure(
            ctx,
            resp.detail ??
              makeTalerErrorDetail(
                TalerErrorCode.WALLET_UNEXPECTED_REQUEST_ERROR,
                {
                  requestUrl: resp.response.requestUrl,
                  requestMethod: resp.response.requestMethod,
                  httpStatusCode: resp.response.status,
                },
              ),
          );
        }
        return throwUnexpectedRequestError(resp.response, resp.detail!);
    }

    const merchantResp = resp.body;

    logger.trace("got success from pay URL", merchantResp);

    const merchantPub = download.contractTerms.merchant_pub;
    const { valid } = await wex.cryptoApi.isValidPaymentSignature({
      contractHash: download.contractTermsHash,
      merchantPub,
      sig: merchantResp.sig,
    });

    if (!valid) {
      logger.error("merchant payment signature invalid");
      // FIXME: properly display error
      throw Error("merchant payment signature invalid");
    }

    logger.trace(`have slates: ${slates?.length}`);
    const slateList = slates ?? [];
    const donauPlanchetList = donauPlanchets ?? [];
    const { slateTokenSigs, donauTokenSigs } =
      splitPaymentOutputTokenSignatures(
        merchantResp.token_sigs,
        slateList.map((slate) => {
          checkDbInvariant(
            slate.outputIndex !== undefined,
            `slate ${slate.tokenUsePub} has no output index`,
          );
          return slate.outputIndex;
        }),
        purchase.donauOutputIndex,
        donauPlanchetList.length,
        payInfo.slateTokenSigs,
      );

    // Verify every token output before making any of the payment's token
    // state durable.  The verified records, consumed inputs and payment
    // success are committed together below.
    const outputTokens = await Promise.all(
      slateList.map((slate, i) => validateToken(wex, slate, slateTokenSigs[i])),
    );

    if (donauPlanchetList.length > 0) {
      logger.info(`got ${donauPlanchetList.length} donau sigs`);
      const donauUrl = purchase.donauBaseUrl;
      if (!donauUrl) {
        throw Error("bad db: no donau URL");
      }
      await acceptDonauBlindSigs(
        wex,
        donauUrl,
        donauPlanchetList,
        donauTokenSigs,
      );
    }

    await storeFirstPaySuccess(wex, proposalId, sessionId, merchantResp, {
      inputTokenPubs: payInfo.payTokenSelection?.tokenPubs ?? [],
      outputTokens,
      outputSlates: slateList,
      slateTokenSigs,
    });
  } else if (!sessionId) {
    // There is no session to bind the payment to, and /paid only makes
    // sense for an actual session (the merchant rejects an empty session
    // ID).  The payment itself is already done, so there is nothing to
    // demonstrate to the merchant here.
    logger.trace(`skipping /paid, payment is not bound to a session`);
    await storePayReplaySuccess(wex, proposalId, undefined);
  } else {
    const reqBody = {
      sig: purchase.merchantPaySig,
      h_contract: download.contractTermsHash,
      session_id: sessionId,
    };
    logger.trace(`/paid request body: ${j2s(reqBody)}`);
    const merchantClient = walletMerchantClient(
      download.contractTerms.merchant_base_url,
      wex,
    );
    const resp = await wex.ws.runSequentialized([EXCHANGE_COINS_LOCK], () =>
      merchantClient.demostratePayment(
        download.contractTerms.order_id,
        reqBody,
      ),
    );
    logger.trace(`/paid response status: ${resp.response.status}`);
    if (isOrderUnknown(resp)) {
      // The merchant deleted the order, so there is no session left to bind
      // the payment to. The payment itself stays valid, and repeating the
      // request could only produce the same answer.
      logger.warn(`session rebinding failed, merchant deleted the order`);
      await wex.runWalletDbTx(async (tx) => {
        const [p, h] = await ctx.getRecordHandle(tx);
        switch (p?.purchaseStatus) {
          case PurchaseStatus.PendingPaying:
          case PurchaseStatus.PendingPayingReplay:
            break;
          default:
            return;
        }
        p.purchaseStatus = PurchaseStatus.Done;
        await h.update(p, "replay-order-gone", BalanceEffect.None);
      });
      return TaskRunResult.progress();
    }
    if (resp.case !== "ok") {
      throw TalerError.fromDetail(
        TalerErrorCode.WALLET_UNEXPECTED_REQUEST_ERROR,
        getHttpResponseErrorDetails(resp.response),
        "/paid failed",
      );
    }
    await storePayReplaySuccess(wex, proposalId, sessionId);
  }

  return TaskRunResult.progress();
}

export async function validateAndStoreToken(
  wex: WalletExecutionContext,
  slate: WalletSlate,
  blindedEv: SignedTokenEnvelope,
): Promise<void> {
  const token = await validateToken(wex, slate, blindedEv);

  // insert token and delete slate
  await wex.runWalletDbTx(async (tx) => {
    await tx.upsertToken(token);
    await tx.deleteSlate(slate.tokenUsePub);
  });
}

export async function validateToken(
  wex: WalletExecutionContext,
  slate: WalletSlate,
  blindedEv: SignedTokenEnvelope,
): Promise<WalletToken> {
  const { tokenIssuePub, tokenIssuePubHash, tokenUsePub, blindingKey } = slate;
  logger.trace(
    `validating token ${tokenIssuePubHash} for purchase ${slate.purchaseId}`,
  );
  const tokenIssueSig = await wex.cryptoApi.unblindTokenIssueSignature({
    slate: {
      tokenIssuePub,
      blindingKey,
    },
    evSig: blindedEv.blind_sig,
  });

  if (tokenIssueSig.cipher !== tokenIssuePub.cipher)
    throw Error("token issue signature mismatch");

  if (!(tokenIssuePub.cipher === DenomKeyType.Rsa))
    throw Error("unsupported cipher");
  if (tokenIssueSig.cipher !== DenomKeyType.Rsa)
    throw Error("unsupported cipher");

  const rsaVerifyResp = await wex.cryptoApi.rsaVerify({
    hm: tokenUsePub,
    pk: tokenIssuePub.rsa_pub,
    sig: tokenIssueSig.rsa_signature,
  });

  if (!rsaVerifyResp.valid) {
    logger.error("token issue signature invalid");
    // TODO: properly display error
    throw Error("token issue signature invalid");
  }

  logger.trace(
    `token ${tokenIssuePubHash} for purchase ${slate.purchaseId} is valid, will be stored`,
  );

  const token: WalletToken = {
    tokenIssueSig,
    ...slate,
  };
  return token;
}

export async function generateTokenSigs(
  wex: WalletExecutionContext,
  proposalId: string,
  contractTermsHash: string,
  walletDataHash: string,
  tokenPubs: string[],
): Promise<TokenUseSig[]> {
  const tokens: WalletToken[] = [];
  const sigs: TokenUseSig[] = [];
  await wex.runWalletDbTx(async (tx) => {
    for (const pub of tokenPubs) {
      const token = await tx.getToken(pub);
      checkDbInvariant(!!token, `token not found for ${pub}`);
      tokens.push(token);
    }
  });

  for (const token of tokens) {
    if (token.tokenUseSig && token.purchaseId === proposalId) {
      sigs.push(token.tokenUseSig);
      continue;
    }

    const { sig } = await wex.cryptoApi.signTokenUse({
      tokenUsePriv: token.tokenUsePriv,
      walletDataHash,
      contractTermsHash,
    });

    sigs.push({
      token_sig: sig,
      token_pub: token.tokenUsePub,
      ub_sig: token.tokenIssueSig,
      h_issue: token.tokenIssuePubHash,
    });
  }

  await wex.runWalletDbTx(async (tx) => {
    for (let i = 0; i < sigs.length; i++) {
      const token = tokens[i];
      const sig = sigs[i];
      token.tokenUseSig = sig;
      await tx.upsertToken(token);
    }
  });

  return sigs;
}

export async function cleanupUsedTokens(
  wex: WalletExecutionContext,
  tokenPubs: string[],
): Promise<void> {
  await wex.runWalletDbTx(async (tx) => {
    for (const pub of tokenPubs) {
      logger.trace(`cleaning up used token ${pub}`);
      await tx.deleteToken(pub);
    }
  });
}

export async function refuseProposal(
  wex: WalletExecutionContext,
  proposalId: string,
): Promise<void> {
  const ctx = new PayMerchantTransactionContext(wex, proposalId);
  await wex.runWalletDbTx(async (tx) => {
    const [proposal, h] = await ctx.getRecordHandle(tx);
    switch (proposal?.purchaseStatus) {
      case PurchaseStatus.DialogProposed:
      case PurchaseStatus.DialogShared:
        break;
      default:
        return;
    }
    proposal.purchaseStatus = PurchaseStatus.AbortedProposalRefused;
    await h.update(proposal, "refuse-proposal");
  });
}

const transitionSuspend: {
  [x in PurchaseStatus]?: {
    next: PurchaseStatus | undefined;
  };
} = {
  [PurchaseStatus.PendingDownloadingProposal]: {
    next: PurchaseStatus.SuspendedDownloadingProposal,
  },
  [PurchaseStatus.AbortingWithRefund]: {
    next: PurchaseStatus.SuspendedAbortingWithRefund,
  },
  [PurchaseStatus.PendingPaying]: {
    next: PurchaseStatus.SuspendedPaying,
  },
  [PurchaseStatus.PendingPayingReplay]: {
    next: PurchaseStatus.SuspendedPayingReplay,
  },
  [PurchaseStatus.PendingQueryingAutoRefund]: {
    next: PurchaseStatus.SuspendedQueryingAutoRefund,
  },
  [PurchaseStatus.FinalizingQueryingAutoRefund]: {
    next: PurchaseStatus.SuspendedFinalizingQueryingAutoRefund,
  },
  [PurchaseStatus.PendingQueryingRefund]: {
    next: PurchaseStatus.SuspendedQueryingRefund,
  },
  [PurchaseStatus.PendingAcceptRefund]: {
    next: PurchaseStatus.SuspendedPendingAcceptRefund,
  },
};

const transitionResume: {
  [x in PurchaseStatus]?: {
    next: PurchaseStatus | undefined;
  };
} = {
  [PurchaseStatus.SuspendedDownloadingProposal]: {
    next: PurchaseStatus.PendingDownloadingProposal,
  },
  [PurchaseStatus.SuspendedAbortingWithRefund]: {
    next: PurchaseStatus.AbortingWithRefund,
  },
  [PurchaseStatus.SuspendedPaying]: {
    next: PurchaseStatus.PendingPaying,
  },
  [PurchaseStatus.SuspendedPayingReplay]: {
    next: PurchaseStatus.PendingPayingReplay,
  },
  [PurchaseStatus.SuspendedQueryingAutoRefund]: {
    next: PurchaseStatus.PendingQueryingAutoRefund,
  },
  [PurchaseStatus.SuspendedFinalizingQueryingAutoRefund]: {
    next: PurchaseStatus.FinalizingQueryingAutoRefund,
  },
  [PurchaseStatus.SuspendedQueryingRefund]: {
    next: PurchaseStatus.PendingQueryingRefund,
  },
  [PurchaseStatus.SuspendedPendingAcceptRefund]: {
    next: PurchaseStatus.PendingAcceptRefund,
  },
};

export function getPayMerchantSuspendTransition(
  status: PurchaseStatus,
): PurchaseStatus | undefined {
  return transitionSuspend[status]?.next;
}

export function getPayMerchantResumeTransition(
  status: PurchaseStatus,
): PurchaseStatus | undefined {
  return transitionResume[status]?.next;
}

export function getPayMerchantAbortTransition(
  status: PurchaseStatus,
  hasSuccessfulPay: boolean,
): PurchaseStatus | undefined {
  switch (status) {
    case PurchaseStatus.PendingDownloadingProposal:
    case PurchaseStatus.SuspendedDownloadingProposal:
    case PurchaseStatus.DialogProposed:
      return PurchaseStatus.AbortedProposalRefused;
    case PurchaseStatus.PendingPaying:
    case PurchaseStatus.SuspendedPaying:
      return PurchaseStatus.AbortingWithRefund;
    case PurchaseStatus.PendingPayingReplay:
    case PurchaseStatus.SuspendedPayingReplay:
      return PurchaseStatus.Done;
    case PurchaseStatus.PendingQueryingAutoRefund:
    case PurchaseStatus.SuspendedQueryingAutoRefund:
    case PurchaseStatus.PendingAcceptRefund:
    case PurchaseStatus.SuspendedPendingAcceptRefund:
    case PurchaseStatus.PendingQueryingRefund:
    case PurchaseStatus.SuspendedQueryingRefund:
      if (!hasSuccessfulPay) {
        throw Error("invalid payment state for refund processing");
      }
      return PurchaseStatus.Done;
    default:
      return undefined;
  }
}

export function computePayMerchantTransactionState(
  purchaseRecord: WalletPurchase,
): TransactionState {
  switch (purchaseRecord.purchaseStatus) {
    // Pending States
    case PurchaseStatus.PendingDownloadingProposal:
      return {
        major: TransactionMajorState.Pending,
        minor: TransactionMinorState.ClaimProposal,
        working: true,
      };
    case PurchaseStatus.PendingPaying:
      return {
        major: TransactionMajorState.Pending,
        minor: TransactionMinorState.SubmitPayment,
        working: true,
      };
    case PurchaseStatus.PendingPayingReplay:
      return {
        major: TransactionMajorState.Pending,
        minor: TransactionMinorState.RebindSession,
        working: true,
      };
    case PurchaseStatus.PendingQueryingAutoRefund:
      return {
        major: TransactionMajorState.Pending,
        minor: TransactionMinorState.AutoRefund,
        working: true,
      };
    case PurchaseStatus.PendingQueryingRefund:
      return {
        major: TransactionMajorState.Pending,
        minor: TransactionMinorState.CheckRefund,
        working: true,
      };
    case PurchaseStatus.PendingAcceptRefund:
      return {
        major: TransactionMajorState.Pending,
        minor: TransactionMinorState.AcceptRefund,
        working: true,
      };
    // Suspended Pending States
    case PurchaseStatus.SuspendedDownloadingProposal:
      return {
        major: TransactionMajorState.Suspended,
        minor: TransactionMinorState.ClaimProposal,
      };
    case PurchaseStatus.SuspendedPaying:
      return {
        major: TransactionMajorState.Suspended,
        minor: TransactionMinorState.SubmitPayment,
      };
    case PurchaseStatus.SuspendedPayingReplay:
      return {
        major: TransactionMajorState.Suspended,
        minor: TransactionMinorState.RebindSession,
        working: true,
      };
    case PurchaseStatus.SuspendedQueryingAutoRefund:
      return {
        major: TransactionMajorState.Suspended,
        minor: TransactionMinorState.AutoRefund,
      };
    case PurchaseStatus.SuspendedQueryingRefund:
      return {
        major: TransactionMajorState.Suspended,
        minor: TransactionMinorState.CheckRefund,
      };
    case PurchaseStatus.SuspendedPendingAcceptRefund:
      return {
        major: TransactionMajorState.Suspended,
        minor: TransactionMinorState.AcceptRefund,
      };
    // Aborting States
    case PurchaseStatus.AbortingWithRefund:
      return {
        major: TransactionMajorState.Aborting,
        working: true,
      };
    // Suspended Aborting States
    case PurchaseStatus.SuspendedAbortingWithRefund:
      return {
        major: TransactionMajorState.SuspendedAborting,
      };
    // Dialog States
    case PurchaseStatus.DialogProposed:
      return {
        major: TransactionMajorState.Dialog,
        minor: TransactionMinorState.Proposed,
      };
    case PurchaseStatus.DialogShared:
      return {
        major: TransactionMajorState.Dialog,
        minor: TransactionMinorState.Proposed,
      };
    case PurchaseStatus.DialogUnclaimed:
      return {
        major: TransactionMajorState.Dialog,
        minor: TransactionMinorState.WaitingForOtherWallet,
      };
    // Final States
    case PurchaseStatus.AbortedProposalRefused:
      return {
        major: TransactionMajorState.Aborted,
        minor: TransactionMinorState.Refused,
      };
    case PurchaseStatus.AbortedOrderDeleted:
    case PurchaseStatus.AbortedRefunded:
      return {
        major: TransactionMajorState.Aborted,
      };
    case PurchaseStatus.Done:
      return {
        major: TransactionMajorState.Done,
      };
    case PurchaseStatus.DoneRepurchaseDetected:
      return {
        major: TransactionMajorState.Failed,
        minor: TransactionMinorState.Repurchase,
      };
    case PurchaseStatus.AbortedIncompletePayment:
      return {
        major: TransactionMajorState.Aborted,
      };
    case PurchaseStatus.AbortedClaimedByOther:
      return {
        major: TransactionMajorState.Aborted,
        minor: TransactionMinorState.ContinuedWithOtherWallet,
      };
    case PurchaseStatus.Expired:
      return {
        major: TransactionMajorState.Expired,
      };
    case PurchaseStatus.Failed:
      return {
        major: TransactionMajorState.Failed,
      };
    case PurchaseStatus.FailedClaim:
      return {
        major: TransactionMajorState.Failed,
        minor: TransactionMinorState.ClaimProposal,
      };
    case PurchaseStatus.FailedAbort:
      return {
        major: TransactionMajorState.Failed,
        minor: TransactionMinorState.Abort,
      };
    case PurchaseStatus.FailedPaidByOther:
      return {
        major: TransactionMajorState.Failed,
        minor: TransactionMinorState.PaidByOther,
      };
    case PurchaseStatus.FinalizingQueryingAutoRefund:
      return {
        major: TransactionMajorState.Finalizing,
        minor: TransactionMinorState.AutoRefund,
      };
    case PurchaseStatus.SuspendedFinalizingQueryingAutoRefund:
      return {
        major: TransactionMajorState.SuspendedFinalizing,
        minor: TransactionMinorState.AutoRefund,
      };
    default:
      assertUnreachable(purchaseRecord.purchaseStatus);
  }
}

export function computePayMerchantTransactionActions(
  purchaseRecord: WalletPurchase,
): TransactionAction[] {
  switch (purchaseRecord.purchaseStatus) {
    // Pending States
    case PurchaseStatus.PendingDownloadingProposal:
      return [
        TransactionAction.Retry,
        TransactionAction.Suspend,
        TransactionAction.Abort,
      ];
    case PurchaseStatus.PendingPaying:
      return [
        TransactionAction.Retry,
        TransactionAction.Suspend,
        TransactionAction.Abort,
      ];
    case PurchaseStatus.PendingPayingReplay:
      // Special "abort" since it goes back to "done".
      return [
        TransactionAction.Retry,
        TransactionAction.Suspend,
        TransactionAction.Abort,
      ];
    case PurchaseStatus.PendingQueryingAutoRefund:
      // Special "abort" since it goes back to "done".
      return [
        TransactionAction.Retry,
        TransactionAction.Suspend,
        TransactionAction.Abort,
      ];
    case PurchaseStatus.PendingQueryingRefund:
      // Special "abort" since it goes back to "done".
      return [
        TransactionAction.Retry,
        TransactionAction.Suspend,
        TransactionAction.Abort,
      ];
    case PurchaseStatus.PendingAcceptRefund:
      // Special "abort" since it goes back to "done".
      return [
        TransactionAction.Retry,
        TransactionAction.Suspend,
        TransactionAction.Abort,
      ];
    // Suspended Pending States
    case PurchaseStatus.SuspendedDownloadingProposal:
      return [TransactionAction.Resume, TransactionAction.Abort];
    case PurchaseStatus.SuspendedPaying:
      return [TransactionAction.Resume, TransactionAction.Abort];
    case PurchaseStatus.SuspendedPayingReplay:
      // Special "abort" since it goes back to "done".
      return [TransactionAction.Resume, TransactionAction.Abort];
    case PurchaseStatus.SuspendedQueryingAutoRefund:
      // Special "abort" since it goes back to "done".
      return [TransactionAction.Resume, TransactionAction.Abort];
    case PurchaseStatus.SuspendedQueryingRefund:
      // Special "abort" since it goes back to "done".
      return [TransactionAction.Resume, TransactionAction.Abort];
    case PurchaseStatus.SuspendedPendingAcceptRefund:
      // Special "abort" since it goes back to "done".
      return [TransactionAction.Resume, TransactionAction.Abort];
    // Aborting States
    case PurchaseStatus.AbortingWithRefund:
      return [
        TransactionAction.Retry,
        TransactionAction.Fail,
        TransactionAction.Suspend,
      ];
    case PurchaseStatus.SuspendedAbortingWithRefund:
      return [TransactionAction.Fail, TransactionAction.Resume];
    // Dialog States
    case PurchaseStatus.DialogProposed:
      return [TransactionAction.Retry, TransactionAction.Delete];
    case PurchaseStatus.DialogShared:
      return [TransactionAction.Retry, TransactionAction.Delete];
    case PurchaseStatus.DialogUnclaimed:
      return [TransactionAction.Delete];
    // Final States
    case PurchaseStatus.AbortedProposalRefused:
    case PurchaseStatus.AbortedOrderDeleted:
    case PurchaseStatus.AbortedRefunded:
      return [TransactionAction.Delete];
    case PurchaseStatus.Done:
      return [TransactionAction.Delete];
    case PurchaseStatus.Expired:
      return [TransactionAction.Delete];
    case PurchaseStatus.DoneRepurchaseDetected:
      return [TransactionAction.Delete];
    case PurchaseStatus.AbortedIncompletePayment:
    case PurchaseStatus.AbortedClaimedByOther:
      return [TransactionAction.Delete];
    case PurchaseStatus.Failed:
      return [TransactionAction.Delete];
    case PurchaseStatus.FailedClaim:
      return [TransactionAction.Delete];
    case PurchaseStatus.FailedAbort:
      return [TransactionAction.Delete];
    case PurchaseStatus.FailedPaidByOther:
      return [TransactionAction.Delete];
    case PurchaseStatus.FinalizingQueryingAutoRefund:
      return [
        TransactionAction.Suspend,
        TransactionAction.Retry,
        TransactionAction.Delete,
      ];
    case PurchaseStatus.SuspendedFinalizingQueryingAutoRefund:
      return [TransactionAction.Resume, TransactionAction.Delete];
    default:
      assertUnreachable(purchaseRecord.purchaseStatus);
  }
}

/** @deprecated Use unclaimPayment() for cross-wallet payment handoff. */
export async function sharePayment(
  wex: WalletExecutionContext,
  merchantBaseUrl: string,
  orderId: string,
): Promise<SharePaymentResult> {
  // First, translate the order ID into a proposal ID
  const proposalId = await wex.runWalletDbTx(async (tx) => {
    const p = await tx.getPurchaseByUrlAndOrderId(merchantBaseUrl, orderId);
    return p?.proposalId;
  });

  if (!proposalId) {
    throw TalerError.fromDetail(
      TalerErrorCode.WALLET_PURCHASE_NOT_FOUND,
      { merchantBaseUrl, orderId },
      `no purchase found for order ${orderId}`,
    );
  }

  const ctx = new PayMerchantTransactionContext(wex, proposalId);

  // "gone" and "wrong state" need different error codes, so they cannot both
  // come back as undefined.
  const result = await wex.runWalletDbTx(async (tx) => {
    const [p, h] = await ctx.getRecordHandle(tx);
    if (!p) {
      logger.warn("purchase does not exist anymore");
      return { type: "gone" as const };
    }
    if (
      p.purchaseStatus !== PurchaseStatus.DialogProposed &&
      p.purchaseStatus !== PurchaseStatus.DialogShared
    ) {
      // FIXME: purchase can be shared before being paid
      return { type: "bad-state" as const, purchase: p };
    }
    if (p.purchaseStatus === PurchaseStatus.DialogProposed) {
      p.purchaseStatus = PurchaseStatus.DialogShared;
      p.shared = true;
      await h.update(p, "share");
    }
    return {
      type: "ok" as const,
      proposalId: p.proposalId,
      nonce: p.noncePriv,
      session: p.lastSessionId ?? p.downloadSessionId,
      token: p.claimToken,
    };
  });

  switch (result.type) {
    case "ok":
      break;
    case "gone":
      throw makeTransactionNotFoundError(ctx.transactionId);
    case "bad-state":
      throw TalerError.fromDetail(
        TalerErrorCode.WALLET_REQUEST_TRANSACTION_STATE_UNSUPPORTED,
        {
          txState: computePayMerchantTransactionState(result.purchase),
          debugStateNum: result.purchase.purchaseStatus,
        },
        "this payment can only be shared before it is paid",
      );
    default:
      assertUnreachable(result);
  }

  // schedule a task to watch for the status
  wex.taskScheduler.startShepherdTask(ctx.taskId);

  const privatePayUri = TalerUris.stringify({
    type: TalerUriAction.Pay,
    merchantBaseUrl: merchantBaseUrl as HostPortPath, // FIXME: change function argument
    orderId,
    sessionId: result.session,
    noncePriv: result.nonce,
    claimToken: result.token,
  });

  return { privatePayUri };
}

function makePublicPayUri(purchase: WalletPurchase) {
  return TalerUris.stringify({
    type: TalerUriAction.Pay,
    merchantBaseUrl: purchase.merchantBaseUrl as HostPortPath,
    orderId: purchase.orderId,
    sessionId: purchase.lastSessionId ?? purchase.downloadSessionId,
    claimToken: purchase.claimToken,
  });
}

/**
 * Release this wallet's claim on an order and return a public payment URI that
 * another wallet can claim.  Unlike sharePayment(), the URI contains no
 * private nonce.
 */
export async function unclaimPayment(
  wex: WalletExecutionContext,
  proposalId: string,
): Promise<UnclaimPaymentResult> {
  const ctx = new PayMerchantTransactionContext(wex, proposalId);
  const snapshot = await wex.runWalletDbTx(async (tx) => {
    const purchase = await tx.getPurchase(proposalId);
    if (!purchase) {
      throw makeTransactionNotFoundError(ctx.transactionId);
    }
    if (purchase.purchaseStatus === PurchaseStatus.DialogUnclaimed) {
      return { type: "already-unclaimed" as const, purchase };
    }
    if (purchase.purchaseStatus !== PurchaseStatus.DialogProposed) {
      throw TalerError.fromDetail(
        TalerErrorCode.WALLET_REQUEST_TRANSACTION_STATE_UNSUPPORTED,
        {
          txState: computePayMerchantTransactionState(purchase),
          debugStateNum: purchase.purchaseStatus,
        },
        "this payment can only be released before it is paid",
      );
    }
    const download = await expectProposalDownloadByIdInTx(wex, tx, proposalId);
    return { type: "unclaim" as const, purchase, download };
  });

  if (snapshot.type === "already-unclaimed") {
    return { talerPayUri: makePublicPayUri(snapshot.purchase) };
  }

  const { sig } = await wex.cryptoApi.signOrderUnclaim({
    noncePriv: snapshot.purchase.noncePriv,
    contractTermsHash: snapshot.download.contractTermsHash,
  });
  const merchantClient = walletMerchantClient(
    snapshot.purchase.merchantBaseUrl,
    wex,
  );
  const response = await merchantClient.unclaimOrder({
    orderId: snapshot.purchase.orderId,
    body: {
      unclaim_sig: sig,
      nonce: snapshot.purchase.noncePub as EddsaPublicKeyString,
      h_contract: snapshot.download.contractTermsHash,
    },
  });
  if (response.case !== "ok") {
    throw TalerError.fromDetail(
      TalerErrorCode.WALLET_UNEXPECTED_REQUEST_ERROR,
      getHttpResponseErrorDetails(response.response),
      "/unclaim failed",
    );
  }

  const purchase = await wex.runWalletDbTx(async (tx) => {
    const [current, handle] = await ctx.getRecordHandle(tx);
    if (!current) {
      throw makeTransactionNotFoundError(ctx.transactionId);
    }
    if (current.purchaseStatus === PurchaseStatus.DialogProposed) {
      current.purchaseStatus = PurchaseStatus.DialogUnclaimed;
      await handle.update(current, "unclaim");
    } else if (current.purchaseStatus !== PurchaseStatus.DialogUnclaimed) {
      throw TalerError.fromDetail(
        TalerErrorCode.WALLET_REQUEST_TRANSACTION_STATE_UNSUPPORTED,
        {
          txState: computePayMerchantTransactionState(current),
          debugStateNum: current.purchaseStatus,
        },
        "payment state changed while releasing the order",
      );
    }
    return current;
  });
  wex.taskScheduler.startShepherdTask(ctx.taskId);
  return { talerPayUri: makePublicPayUri(purchase) };
}

/**
 * Status of an order from the point of view of a wallet that is not the one
 * that (possibly) paid it. "gone" means that the merchant does not have the
 * order anymore, and thus nobody can pay it.
 */
type ForeignOrderStatus = "paid" | "unpaid" | "gone";

async function checkIfOrderIsAlreadyPaid(
  wex: WalletExecutionContext,
  contract: DownloadedContractData,
  doLongPolling: boolean,
): Promise<ForeignOrderStatus> {
  const merchantClient = walletMerchantClient(
    contract.contractTerms.merchant_base_url,
    wex,
  );
  const resp = await merchantClient.getPaymentStatus(
    contract.contractTerms.order_id,
    {
      contractTermHash: contract.contractTermsHash,
      timeout: doLongPolling ? MERCHANT_ORDER_STATUS_LONGPOLL_MS : undefined,
    },
  );

  if (isOrderUnknown(resp)) {
    return "gone";
  }

  switch (resp.case) {
    case "ok": // 200 paid
    case HttpStatusCode.Accepted: // 202 goto
      return "paid";
    case HttpStatusCode.PaymentRequired: // 402 unpaid
      return "unpaid";
    default:
      // forbidden, not found, not acceptable
      throw Error(`this order cant be paid: ${resp.response.status}`);
  }
}

async function processPurchaseDialogProposed(
  wex: WalletExecutionContext,
  purchase: WalletPurchase,
): Promise<TaskRunResult> {
  const proposalId = purchase.proposalId;
  const ctx = new PayMerchantTransactionContext(wex, proposalId);
  if (purchase.createdFromShared) {
    await wex.runWalletDbTx(async (tx) => {
      const [rec, h] = await ctx.getRecordHandle(tx);
      if (rec?.purchaseStatus !== PurchaseStatus.DialogProposed) {
        return;
      }
      rec.purchaseStatus = PurchaseStatus.DialogShared;
      await h.update(rec, "upgrade-shared-dialog");
    });
    return TaskRunResult.progress();
  }
  const txRes = await wex.runWalletDbTx(async (tx) => {
    const rec = await tx.getPurchase(proposalId);
    if (!rec) {
      return undefined;
    }
    const download = await expectProposalDownloadByIdInTx(wex, tx, proposalId);
    return { download, rec };
  });
  if (!txRes) {
    // Transaction longer exists.
    return TaskRunResult.finished();
  }
  const payDeadline = AbsoluteTime.fromProtocolTimestamp(
    txRes.download.contractTerms.pay_deadline,
  );

  const expiry = AbsoluteTime.addDuration(
    payDeadline,
    Duration.fromSpec({ seconds: 10 }),
  );

  if (AbsoluteTime.isExpired(expiry)) {
    await wex.runWalletDbTx(async (tx) => {
      const [r2, h] = await ctx.getRecordHandle(tx);
      if (r2?.purchaseStatus !== PurchaseStatus.DialogProposed) {
        return;
      }
      r2.timestampExpired = timestampPreciseToDb(TalerPreciseTimestamp.now());
      r2.purchaseStatus = PurchaseStatus.Expired;
      await h.update(r2, "proposal-expired");
    });
    return TaskRunResult.progress();
  }
  return TaskRunResult.runAgainAt(expiry);
}

/**
 * While the transaction is in the dialog(shared) state,
 * we long-poll the merchant. We do this to find out if
 * another wallet paid for the order.
 */
async function processPurchaseDialogShared(
  wex: WalletExecutionContext,
  purchase: WalletPurchase,
): Promise<TaskRunResult> {
  const proposalId = purchase.proposalId;
  logger.trace(`processing dialog-shared for proposal ${proposalId}`);
  const ctx = new PayMerchantTransactionContext(wex, proposalId);
  const txRes = await wex.runWalletDbTx(async (tx) => {
    const rec = await tx.getPurchase(proposalId);
    if (!rec) {
      return undefined;
    }
    const download = await expectProposalDownloadByIdInTx(wex, tx, proposalId);
    return { download, rec };
  });
  if (!txRes) {
    // Transaction longer exists.
    return TaskRunResult.finished();
  }
  const { download, rec } = txRes;
  if (purchase.purchaseStatus !== PurchaseStatus.DialogShared) {
    return TaskRunResult.finished();
  }

  const contractTerms = download.contractTerms;

  let paidByOther = false;

  const merchantClient = walletMerchantClient(
    contractTerms.merchant_base_url,
    wex,
  );
  const resp = await merchantClient.getPaymentStatus(contractTerms.order_id, {
    contractTermHash: download.contractTermsHash,
    sessionId: rec.lastSessionId ?? undefined,
    timeout: MERCHANT_ORDER_STATUS_LONGPOLL_MS,
  });

  if (isOrderUnknown(resp)) {
    // The merchant deleted the order, so no other wallet can pay it anymore
    // and there is nothing left to watch for.
    await wex.runWalletDbTx(async (tx) => {
      const [p, h] = await ctx.getRecordHandle(tx);
      if (p?.purchaseStatus !== PurchaseStatus.DialogShared) {
        return;
      }
      p.purchaseStatus = PurchaseStatus.AbortedOrderDeleted;
      await h.update(p, "shared-order-gone");
    });
    return TaskRunResult.progress();
  }

  switch (resp.case) {
    case "ok": // 200 paid
    case HttpStatusCode.Accepted: // 202 goto
      paidByOther = true;
      break;
    case HttpStatusCode.PaymentRequired: // 402 unpaid
      if (resp.body.already_paid_order_id != null) {
        paidByOther = true;
      }
      break;
  }

  if (!paidByOther) {
    return TaskRunResult.backoff();
  }

  await wex.runWalletDbTx(async (tx) => {
    const [p, h] = await ctx.getRecordHandle(tx);
    switch (p?.purchaseStatus) {
      case PurchaseStatus.DialogShared:
        p.purchaseStatus = PurchaseStatus.FailedPaidByOther;
        break;
      default:
        return;
    }
    await h.update(p, "shared-paid-by-other");
  });
  return TaskRunResult.progress();
}

async function processPurchaseDialogUnclaimed(
  wex: WalletExecutionContext,
  purchase: WalletPurchase,
): Promise<TaskRunResult> {
  const proposalId = purchase.proposalId;
  const ctx = new PayMerchantTransactionContext(wex, proposalId);
  const txRes = await wex.runWalletDbTx(async (tx) => {
    const rec = await tx.getPurchase(proposalId);
    if (!rec) {
      return undefined;
    }
    const download = await expectProposalDownloadByIdInTx(wex, tx, proposalId);
    return { download, rec };
  });
  if (!txRes || txRes.rec.purchaseStatus !== PurchaseStatus.DialogUnclaimed) {
    return TaskRunResult.finished();
  }

  const expiry = AbsoluteTime.addDuration(
    AbsoluteTime.fromProtocolTimestamp(
      txRes.download.contractTerms.pay_deadline,
    ),
    Duration.fromSpec({ seconds: 10 }),
  );
  if (AbsoluteTime.isExpired(expiry)) {
    await wex.runWalletDbTx(async (tx) => {
      const [rec, handle] = await ctx.getRecordHandle(tx);
      if (rec?.purchaseStatus !== PurchaseStatus.DialogUnclaimed) {
        return;
      }
      rec.timestampExpired = timestampPreciseToDb(TalerPreciseTimestamp.now());
      rec.purchaseStatus = PurchaseStatus.Expired;
      await handle.update(rec, "unclaimed-order-expired");
    });
    return TaskRunResult.progress();
  }

  const merchantClient = walletMerchantClient(
    txRes.download.contractTerms.merchant_base_url,
    wex,
  );
  let response = await merchantClient.getPaymentStatus(
    txRes.download.contractTerms.order_id,
    {
      claimToken: txRes.rec.claimToken,
      sessionId: txRes.rec.lastSessionId ?? undefined,
      timeout: MERCHANT_ORDER_STATUS_LONGPOLL_MS,
    },
  );

  // The claim token keeps the long-poll authorized while the order is
  // unclaimed.  A 402 response alone does not reveal whether another wallet
  // has claimed it, because the token remains valid for the newly generated
  // contract.  Probe once with the old contract hash after the long-poll
  // returns: the merchant distinguishes the unclaimed order from a new claim
  // with its error code.
  if (
    response.case === HttpStatusCode.PaymentRequired &&
    response.body.already_paid_order_id == null
  ) {
    response = await merchantClient.getPaymentStatus(
      txRes.download.contractTerms.order_id,
      {
        contractTermHash: txRes.download.contractTermsHash,
        sessionId: txRes.rec.lastSessionId ?? undefined,
      },
    );
  }

  if (isOrderUnknown(response)) {
    await wex.runWalletDbTx(async (tx) => {
      const [rec, handle] = await ctx.getRecordHandle(tx);
      if (rec?.purchaseStatus !== PurchaseStatus.DialogUnclaimed) {
        return;
      }
      rec.purchaseStatus = PurchaseStatus.AbortedOrderDeleted;
      await handle.update(rec, "unclaimed-order-gone");
    });
    return TaskRunResult.progress();
  }

  if (
    response.case === HttpStatusCode.Forbidden &&
    response.detail?.code ===
      TalerErrorCode.MERCHANT_GET_ORDERS_ID_INVALID_CONTRACT_HASH
  ) {
    return TaskRunResult.longpollReturnedPending();
  }

  const claimed =
    response.case === "ok" ||
    response.case === HttpStatusCode.Accepted ||
    response.case === HttpStatusCode.PaymentRequired ||
    (response.case === HttpStatusCode.Forbidden &&
      response.detail?.code ===
        TalerErrorCode.MERCHANT_GENERIC_CONTRACT_HASH_DOES_NOT_MATCH_ORDER);
  if (!claimed) {
    throw TalerError.fromDetail(
      TalerErrorCode.WALLET_UNEXPECTED_REQUEST_ERROR,
      getHttpResponseErrorDetails(response.response),
      "checking whether the released order was claimed failed",
    );
  }

  await wex.runWalletDbTx(async (tx) => {
    const [rec, handle] = await ctx.getRecordHandle(tx);
    if (rec?.purchaseStatus !== PurchaseStatus.DialogUnclaimed) {
      return;
    }
    rec.purchaseStatus = PurchaseStatus.AbortedClaimedByOther;
    await handle.update(rec, "unclaimed-order-claimed-by-other");
  });
  return TaskRunResult.progress();
}

async function processPurchaseAutoRefund(
  wex: WalletExecutionContext,
  purchase: WalletPurchase,
): Promise<TaskRunResult> {
  const proposalId = purchase.proposalId;
  const ctx = new PayMerchantTransactionContext(wex, proposalId);

  logger.trace(`processing auto-refund for proposal ${proposalId}`);

  const download = await expectProposalDownload(wex, purchase);
  const { available, amountRaw } = ContractTermsUtil.extractAmounts(
    download.contractTerms,
    purchase.choiceIndex,
  );
  if (!available) {
    throw Error("choice index not specified for contract v1");
  }

  const noAutoRefundOrExpired =
    !purchase.autoRefundDeadline ||
    AbsoluteTime.isExpired(
      AbsoluteTime.fromProtocolTimestamp(
        timestampProtocolFromDb(purchase.autoRefundDeadline),
      ),
    );

  const totalKnownRefund = await wex.runWalletDbTx(async (tx) => {
    const refunds = await tx.getRefundGroupsByProposal(purchase.proposalId);
    const am = Amounts.parseOrThrow(amountRaw);
    return refunds.reduce((prev, cur) => {
      if (
        cur.status === RefundGroupStatus.Done ||
        cur.status === RefundGroupStatus.Pending
      ) {
        return Amounts.add(prev, cur.amountRaw).amount;
      }
      return prev;
    }, Amounts.zeroOfAmount(am));
  });

  const fullyRefunded = Amounts.cmp(amountRaw, totalKnownRefund) <= 0;

  // We stop with the auto-refund state when the auto-refund period
  // is over or the product is already fully refunded.

  if (noAutoRefundOrExpired || fullyRefunded) {
    await wex.runWalletDbTx(async (tx) => {
      const [p, h] = await ctx.getRecordHandle(tx);
      switch (p?.purchaseStatus) {
        case PurchaseStatus.PendingQueryingAutoRefund:
        case PurchaseStatus.FinalizingQueryingAutoRefund:
          break;
        default:
          return;
      }
      p.purchaseStatus = PurchaseStatus.Done;
      p.refundAmountAwaiting = undefined;
      await h.update(p, "auto-refund-done");
    });
    return TaskRunResult.progress();
  }

  const merchantClient = walletMerchantClient(
    download.contractTerms.merchant_base_url,
    wex,
  );
  const resp = await merchantClient.getPaymentStatus(
    download.contractTerms.order_id,
    {
      contractTermHash: download.contractTermsHash,
      refund: Amounts.stringify(totalKnownRefund),
      timeout: MERCHANT_ORDER_STATUS_LONGPOLL_MS,
    },
  );

  if (isOrderUnknown(resp)) {
    // The merchant deleted the order, so no auto-refund can arrive for it
    // anymore. That leaves the payment where the auto-refund deadline would
    // have left it.
    await wex.runWalletDbTx(async (tx) => {
      const [p, h] = await ctx.getRecordHandle(tx);
      switch (p?.purchaseStatus) {
        case PurchaseStatus.PendingQueryingAutoRefund:
        case PurchaseStatus.FinalizingQueryingAutoRefund:
          break;
        default:
          return;
      }
      p.purchaseStatus = PurchaseStatus.Done;
      p.refundAmountAwaiting = undefined;
      await h.update(p, "auto-refund-order-gone");
    });
    return TaskRunResult.progress();
  }

  // FIXME: Check other status codes!
  if (resp.case !== "ok") {
    throw Error(`expected paid order status, got HTTP ${resp.response.status}`);
  }
  const orderStatus = resp.body;

  if (!orderStatus.refund_pending) {
    return TaskRunResult.longpollReturnedPending();
  }

  await wex.runWalletDbTx(async (tx) => {
    const [rec, h] = await ctx.getRecordHandle(tx);
    switch (rec?.purchaseStatus) {
      case PurchaseStatus.PendingQueryingAutoRefund:
      case PurchaseStatus.FinalizingQueryingAutoRefund:
        break;
      default:
        return;
    }
    rec.purchaseStatus = PurchaseStatus.PendingAcceptRefund;
    await h.update(rec, "auto-refund-found");
  });
  return TaskRunResult.progress();
}

async function processPurchaseAbortingRefund(
  wex: WalletExecutionContext,
  purchase: WalletPurchase,
): Promise<TaskRunResult> {
  const proposalId = purchase.proposalId;
  const ctx = new PayMerchantTransactionContext(wex, proposalId);
  const download = await expectProposalDownload(wex, purchase);
  logger.trace(`processing aborting-refund for proposal ${proposalId}`);

  const merchantAlreadyCompletedOrder =
    purchase.failReason?.code ===
      TalerErrorCode.MERCHANT_POST_ORDERS_ID_PAY_ALREADY_PAID ||
    purchase.failReason?.code ===
      TalerErrorCode.MERCHANT_POST_ORDERS_ID_PAY_CHOICE_INDEX_MISMATCH;
  if (merchantAlreadyCompletedOrder && purchase.abortRefreshGroupId) {
    // A complete order cannot be aborted.  Its /pay response either carried
    // the refund permissions needed by refresh (already-paid), or rejected
    // the choice before accepting these inputs (choice mismatch).
    return waitForRefreshOnAbortedPayment(
      wex,
      purchase,
      PurchaseStatus.AbortedRefunded,
    );
  }

  const abortingCoins: AbortingCoin[] = [];

  const payCoinSelection = purchase.payInfo?.payCoinSelection;
  if (!payCoinSelection) {
    await wex.runWalletDbTx(async (tx) => {
      const [rec, h] = await ctx.getRecordHandle(tx);
      if (rec?.purchaseStatus !== PurchaseStatus.AbortingWithRefund) {
        return;
      }
      if (purchase.payInfo?.payCoinSelection != null) {
        return;
      }
      await releasePaymentTokensInTx(
        tx,
        ctx.transactionId,
        rec.payInfo?.payTokenSelection?.tokenPubs ?? [],
      );
      rec.purchaseStatus = rec.failReason
        ? recoveredPayFailureStatus(rec.failReason)
        : PurchaseStatus.AbortedOrderDeleted;
      await h.update(rec, "abort-unpaid");
    });
    return TaskRunResult.finished();
  }

  await wex.runWalletDbTx(async (tx) => {
    const [rec, h] = await ctx.getRecordHandle(tx);
    if (!rec) {
      return;
    }
    if (rec.payInfo?.payCoinSelection && rec.abortRefreshGroupId == null) {
      const coinSel = rec.payInfo.payCoinSelection;
      const currency = Amounts.currencyOf(rec.payInfo.totalPayCost);
      const refreshCoins: CoinRefreshRequest[] = [];
      for (let i = 0; i < coinSel.coinPubs.length; i++) {
        refreshCoins.push({
          amount: coinSel.coinContributions[i],
          coinPub: coinSel.coinPubs[i],
        });
      }
      const res = await createRefreshGroup(
        wex,
        tx,
        currency,
        refreshCoins,
        RefreshReason.AbortPay,
        ctx.transactionId,
      );
      rec.abortRefreshGroupId = res.refreshGroupId;
      await h.update(rec, "abort-refresh");
    }

    const abortCoins = await tx.getCoinsByPubs(payCoinSelection.coinPubs);
    const abortCoinsByPub = new Map(
      abortCoins.map((coin) => [coin.coinPub, coin]),
    );
    for (let i = 0; i < payCoinSelection.coinPubs.length; i++) {
      const coinPub = payCoinSelection.coinPubs[i];
      const coin = abortCoinsByPub.get(coinPub);
      checkDbInvariant(!!coin, `coin not found for ${coinPub}`);
      abortingCoins.push({
        coin_pub: coinPub,
        exchange_url: coin.exchangeBaseUrl,
      });
    }
  });

  const abortReq: AbortRequest = {
    h_contract: download.contractTermsHash,
    coins: abortingCoins,
  };

  logger.trace(
    `making order abort request for ${download.contractTerms.order_id}`,
  );

  const merchantClient = walletMerchantClient(
    download.contractTerms.merchant_base_url,
    wex,
  );
  const abortHttpResp = await merchantClient.abortIncompletePayment(
    download.contractTerms.order_id,
    abortReq,
  );

  logger.trace(`abort response status: ${j2s(abortHttpResp.response.status)}`);

  if (
    (abortHttpResp.case === HttpStatusCode.NotFound &&
      abortHttpResp.detail?.code ===
        TalerErrorCode.MERCHANT_POST_ORDERS_ID_ABORT_CONTRACT_NOT_FOUND) ||
    isOrderUnknown(abortHttpResp)
  ) {
    return await waitForRefreshOnAbortedPayment(
      wex,
      purchase,
      PurchaseStatus.AbortedOrderDeleted,
    );
  }

  if (
    abortHttpResp.case === HttpStatusCode.PreconditionFailed &&
    abortHttpResp.detail?.code ===
      TalerErrorCode.MERCHANT_POST_ORDERS_ID_ABORT_REFUND_REFUSED_PAYMENT_COMPLETE
  ) {
    // A payment can become complete between /pay failing and /abort arriving.
    // The precautionary refresh already in progress is then the only sound
    // evidence of whether these particular coins were accepted.
    return waitForRefreshOnAbortedPayment(
      wex,
      purchase,
      PurchaseStatus.AbortedRefunded,
    );
  }

  if (
    abortHttpResp.case !== "ok" &&
    abortHttpResp.case !== HttpStatusCode.BadGateway
  ) {
    return throwUnexpectedRequestError(
      abortHttpResp.response,
      abortHttpResp.detail!,
    );
  }

  const abortResp = abortHttpResp.body;

  if (logger.shouldLogTrace()) {
    logger.trace(`abort response: ${j2s(abortResp)}`);
  }

  const refunds: MerchantCoinRefundStatus[] = [];
  const abortResponseTime = AbsoluteTime.toProtocolTimestamp(
    AbsoluteTime.now(),
  );

  if (abortResp.refunds.length != abortingCoins.length) {
    throw TalerError.fromDetail(
      TalerErrorCode.WALLET_TRANSACTION_PROTOCOL_VIOLATION,
      {},
      `merchant returned ${abortResp.refunds.length} refunds for ${abortingCoins.length} aborted coins`,
    );
  }

  for (let i = 0; i < abortResp.refunds.length; i++) {
    const r = abortResp.refunds[i];
    if (r.type === "undeposited") {
      continue;
    }
    refunds.push({
      ...r,
      coin_pub: payCoinSelection.coinPubs[i],
      refund_amount: Amounts.stringify(payCoinSelection.coinContributions[i]),
      rtransaction_id: 0,
      // The abort API does not carry the exchange's signing time.  Use the
      // time at which this fresh response was received to select the exchange
      // signing key, rather than the potentially much older contract time.
      execution_time: abortResponseTime,
    });
  }
  const storeResult = await storeRefunds(
    wex,
    purchase,
    refunds,
    RefundReason.AbortRefund,
  );
  if (storeResult.type !== TaskRunResultType.Progress) {
    return storeResult;
  }
  return await waitForRefreshOnAbortedPayment(
    wex,
    purchase,
    PurchaseStatus.AbortedRefunded,
  );
}

/**
 * Wait for the precautionary refresh created while aborting a payment.
 *
 * The merchant's abort response only tells us what happened to the deposits.
 * The payment is not fully aborted until the wallet has also recovered (or
 * conclusively failed to recover) the selected coins.
 */
async function waitForRefreshOnAbortedPayment(
  wex: WalletExecutionContext,
  purchase: WalletPurchase,
  finalStatus:
    | PurchaseStatus.AbortedOrderDeleted
    | PurchaseStatus.AbortedRefunded,
): Promise<TaskRunResult> {
  const abortRefreshGroupId = await wex.runWalletDbTx(async (tx) => {
    return (await tx.getPurchase(purchase.proposalId))?.abortRefreshGroupId;
  });
  checkLogicInvariant(!!abortRefreshGroupId);

  const ctx = new PayMerchantTransactionContext(wex, purchase.proposalId);
  const refreshCtx = new RefreshTransactionContext(wex, abortRefreshGroupId);

  await genericWaitForState(wex, {
    async checkState() {
      return await wex.runWalletDbTx(async (tx) => {
        const refreshGroup = await tx.getRefreshGroup(abortRefreshGroupId);
        return (
          classifyRecoveryRefresh(refreshGroup?.operationStatus) !== "pending"
        );
      });
    },
    filterNotification(notif) {
      return (
        notif.type === NotificationType.TransactionStateTransition &&
        notif.transactionId === refreshCtx.transactionId
      );
    },
  });

  const didTransition = await wex.runWalletDbTx(async (tx) => {
    const refreshGroup = await tx.getRefreshGroup(abortRefreshGroupId);
    const recovery = classifyRecoveryRefresh(refreshGroup?.operationStatus);
    if (recovery === "pending") {
      return false;
    }
    const [rec, h] = await ctx.getRecordHandle(tx);
    if (rec?.purchaseStatus !== PurchaseStatus.AbortingWithRefund) {
      return false;
    }
    await releasePaymentTokensInTx(
      tx,
      ctx.transactionId,
      rec.payInfo?.payTokenSelection?.tokenPubs ?? [],
    );
    if (recovery === "recovered") {
      rec.purchaseStatus = rec.failReason
        ? recoveredPayFailureStatus(rec.failReason)
        : finalStatus;
      await h.update(rec, "abort-refresh-done");
    } else {
      rec.purchaseStatus = PurchaseStatus.FailedAbort;
      rec.failReason = makeErrorDetail(
        TalerErrorCode.WALLET_UNEXPECTED_EXCEPTION,
        {},
        `abort recovery refresh ${abortRefreshGroupId} failed or disappeared`,
      );
      await h.update(rec, "abort-refresh-failed");
    }
    return true;
  });

  return didTransition ? TaskRunResult.progress() : TaskRunResult.backoff();
}

/**
 * Release token reservations owned by one payment.
 *
 * The ownership check keeps retries and stale cleanup calls from making a
 * token allocated by another transaction available.  A token-use signature
 * is contract-specific and must not survive release.
 */
export async function releasePaymentTokensInTx(
  tx: WalletDbTransaction,
  transactionId: TransactionIdStr,
  tokenPubs: string[],
): Promise<void> {
  for (const tokenPub of tokenPubs) {
    const token = await tx.getToken(tokenPub);
    if (token?.transactionId !== transactionId) {
      continue;
    }
    delete token.transactionId;
    delete token.tokenUseSig;
    await tx.upsertToken(token);
  }
}

async function processPurchaseQueryRefund(
  wex: WalletExecutionContext,
  purchase: WalletPurchase,
): Promise<TaskRunResult> {
  const proposalId = purchase.proposalId;
  logger.trace(`processing query-refund for proposal ${proposalId}`);

  const download = await expectProposalDownload(wex, purchase);

  const merchantClient = walletMerchantClient(
    download.contractTerms.merchant_base_url,
    wex,
  );
  const resp = await merchantClient.getPaymentStatus(
    download.contractTerms.order_id,
    {
      contractTermHash: download.contractTermsHash,
    },
  );

  const ctx = new PayMerchantTransactionContext(wex, proposalId);

  if (isOrderUnknown(resp)) {
    // The merchant deleted the order, so it can never report a refund for it.
    // The payment itself remains valid, so the transaction goes back to being
    // a plain successful payment.
    await wex.runWalletDbTx(async (tx) => {
      const [p, h] = await ctx.getRecordHandle(tx);
      if (p?.purchaseStatus !== PurchaseStatus.PendingQueryingRefund) {
        return;
      }
      p.purchaseStatus = PurchaseStatus.Done;
      p.refundAmountAwaiting = undefined;
      await h.update(p, "query-refund-order-gone");
    });
    return TaskRunResult.progress();
  }

  if (resp.case !== "ok") {
    throw Error(`expected paid order status, got HTTP ${resp.response.status}`);
  }
  const orderStatus = resp.body;

  if (!orderStatus.refund_pending) {
    await wex.runWalletDbTx(async (tx) => {
      const [p, h] = await ctx.getRecordHandle(tx);
      if (p?.purchaseStatus !== PurchaseStatus.PendingQueryingRefund) {
        return;
      }
      p.purchaseStatus = PurchaseStatus.Done;
      p.refundAmountAwaiting = undefined;
      await h.update(p, "query-refund-done");
    });
  } else {
    const refundAwaiting = Amounts.sub(
      Amounts.parseOrThrow(orderStatus.refund_amount),
      Amounts.parseOrThrow(orderStatus.refund_taken),
    ).amount;

    await wex.runWalletDbTx(async (tx) => {
      const [p, h] = await ctx.getRecordHandle(tx);
      if (p?.purchaseStatus !== PurchaseStatus.PendingQueryingRefund) {
        return;
      }
      p.refundAmountAwaiting = Amounts.stringify(refundAwaiting);
      p.purchaseStatus = PurchaseStatus.PendingAcceptRefund;
      await h.update(p, "query-refund-found");
    });
  }
  return TaskRunResult.progress();
}

async function processPurchaseAcceptRefund(
  wex: WalletExecutionContext,
  purchase: WalletPurchase,
): Promise<TaskRunResult> {
  const download = await expectProposalDownload(wex, purchase);

  logger.trace(`making refund request for ${download.contractTerms.order_id}`);

  const merchantClient = walletMerchantClient(
    download.contractTerms.merchant_base_url,
    wex,
  );
  const request = await merchantClient.obtainRefund(
    download.contractTerms.order_id,
    {
      h_contract: download.contractTermsHash,
    },
  );
  if (isOrderUnknown(request)) {
    // The merchant deleted the order, so the refund it announced can never be
    // collected anymore. The payment itself stays valid.
    const ctx = new PayMerchantTransactionContext(wex, purchase.proposalId);
    await wex.runWalletDbTx(async (tx) => {
      const [p, h] = await ctx.getRecordHandle(tx);
      if (p?.purchaseStatus !== PurchaseStatus.PendingAcceptRefund) {
        return;
      }
      p.purchaseStatus = PurchaseStatus.Done;
      p.refundAmountAwaiting = undefined;
      await h.update(p, "accept-refund-order-gone");
    });
    return TaskRunResult.progress();
  }
  if (request.case !== "ok") {
    throw TalerError.fromDetail(
      TalerErrorCode.WALLET_UNEXPECTED_REQUEST_ERROR,
      getHttpResponseErrorDetails(request.response),
      "refund request failed",
    );
  }
  const refundResponse = request.body;
  return await storeRefunds(
    wex,
    purchase,
    refundResponse.refunds,
    RefundReason.AbortRefund,
  );
}

export async function startRefundQueryForUri(
  wex: WalletExecutionContext,
  talerUri: string,
): Promise<StartRefundQueryForUriResponse> {
  const parsedUri = Result.orUndefined(TalerUris.parse(talerUri));
  if (parsedUri?.type !== TalerUriAction.Refund) {
    throw TalerError.fromDetail(
      TalerErrorCode.WALLET_TALER_URI_MALFORMED,
      { talerUri, expectedAction: TalerUriAction.Refund },
      "expected a taler://refund URI",
    );
  }
  const purchaseRecord = await wex.runWalletDbTx(async (tx) => {
    return tx.getPurchaseByUrlAndOrderId(
      parsedUri.merchantBaseUrl,
      parsedUri.orderId,
    );
  });
  if (!purchaseRecord) {
    // Scanning a refund QR code for an order that was paid with a different
    // wallet is a normal user mistake, so the caller must be able to tell it
    // apart from an internal failure.
    throw TalerError.fromDetail(
      TalerErrorCode.WALLET_PURCHASE_NOT_FOUND,
      {
        merchantBaseUrl: parsedUri.merchantBaseUrl,
        orderId: parsedUri.orderId,
      },
      "no purchase found for the refund",
    );
  }
  const proposalId = purchaseRecord.proposalId;
  const transactionId = constructTransactionIdentifier({
    tag: TransactionType.Payment,
    proposalId,
  });
  await startQueryRefund(wex, proposalId);
  return {
    transactionId,
  };
}

export async function startQueryRefund(
  wex: WalletExecutionContext,
  proposalId: string,
): Promise<void> {
  const ctx = new PayMerchantTransactionContext(wex, proposalId);
  await wex.runWalletDbTx(async (tx) => {
    const [p, h] = await ctx.getRecordHandle(tx);
    if (!p) {
      logger.warn(`purchase ${proposalId} does not exist anymore`);
      return;
    }
    if (p.purchaseStatus !== PurchaseStatus.Done) {
      return;
    }
    p.purchaseStatus = PurchaseStatus.PendingQueryingRefund;
    await h.update(p, "start-query-refund");
  });
  wex.taskScheduler.startShepherdTask(ctx.taskId);
}

async function computeRefreshRequest(
  wex: WalletExecutionContext,
  tx: WalletDbTransaction,
  items: WalletRefundItem[],
): Promise<CoinRefreshRequest[]> {
  const refreshCoins: CoinRefreshRequest[] = [];
  const coins = await tx.getCoinsByPubs(items.map((item) => item.coinPub));
  const coinsByPub = new Map(coins.map((coin) => [coin.coinPub, coin]));
  const denoms = await getDenomInfos(wex, tx, coins);
  for (const item of items) {
    const coin = coinsByPub.get(item.coinPub);
    if (!coin) {
      throw Error("coin not found");
    }
    const denomInfo = denoms.get(denomRefKey(coin));
    if (!denomInfo) {
      throw Error("denom not found");
    }
    if (item.status === RefundItemStatus.Done) {
      const refundedAmount = Amounts.sub(
        item.refundAmount,
        denomInfo.feeRefund,
      ).amount;
      refreshCoins.push({
        amount: Amounts.stringify(refundedAmount),
        coinPub: item.coinPub,
      });
    }
  }
  return refreshCoins;
}

/**
 * Compute the refund item status based on the merchant's response.
 */
function getItemStatus(rf: MerchantCoinRefundStatus): RefundItemStatus {
  if (rf.type === "success") {
    return RefundItemStatus.Done;
  } else {
    if (rf.exchange_status >= 500 && rf.exchange_status <= 599) {
      return RefundItemStatus.Pending;
    } else {
      return RefundItemStatus.Failed;
    }
  }
}

export function getRefundTotals(
  refundGroups: WalletRefundGroup[],
  currency: string,
): { raw: AmountString; effective: AmountString } {
  return {
    raw: Amounts.stringify(
      Amounts.sumOrZero(
        currency,
        refundGroups.map((x) => x.amountRaw),
      ).amount,
    ),
    effective: Amounts.stringify(
      Amounts.sumOrZero(
        currency,
        refundGroups.map((x) => x.amountEffective),
      ).amount,
    ),
  };
}

export function setRefundGroupEffectiveAmount(
  refundGroup: WalletRefundGroup,
  outputAmounts: AmountJson[],
): void {
  refundGroup.amountEffective = Amounts.stringify(
    Amounts.sumOrZero(Amounts.currencyOf(refundGroup.amountRaw), outputAmounts)
      .amount,
  );
}

/**
 * Store refunds, possibly creating a new refund group.
 */
async function storeRefunds(
  wex: WalletExecutionContext,
  purchase: WalletPurchase,
  refunds: MerchantCoinRefundStatus[],
  reason: RefundReason,
): Promise<TaskRunResult> {
  logger.info(`storing refunds: ${j2s(refunds)}`);

  const ctx = new PayMerchantTransactionContext(wex, purchase.proposalId);

  const newRefundGroupId = encodeCrock(randomBytes(32));
  const now = TalerPreciseTimestamp.now();

  const download = await expectProposalDownload(wex, purchase);
  const { available, amountRaw } = ContractTermsUtil.extractAmounts(
    download.contractTerms,
    purchase.choiceIndex,
  );
  if (!available) {
    throw Error("choice index not specified for contract v1");
  }

  const currency = Amounts.currencyOf(amountRaw);

  const successfulRefunds = refunds.filter(
    (refund) => refund.type === "success",
  );
  if (successfulRefunds.length > 0) {
    const coins = await wex.runWalletDbTx((tx) =>
      tx.getCoinsByPubs(successfulRefunds.map((refund) => refund.coin_pub)),
    );
    const coinsByPub = new Map(coins.map((coin) => [coin.coinPub, coin]));
    for (const refund of successfulRefunds) {
      const coin = coinsByPub.get(refund.coin_pub);
      if (!coin) {
        throw TalerError.fromDetail(
          TalerErrorCode.WALLET_TRANSACTION_PROTOCOL_VIOLATION,
          {},
          `merchant returned a refund for unknown coin ${refund.coin_pub}`,
        );
      }
      await requireValidExchangeRefundConfirmation(wex, {
        exchangeBaseUrl: coin.exchangeBaseUrl,
        contractTermsHash: download.contractTermsHash,
        coinPub: refund.coin_pub,
        merchantPub: download.contractTerms.merchant_pub,
        rtransactionId: refund.rtransaction_id,
        refundAmount: refund.refund_amount,
        executionTime: refund.execution_time,
        exchangePub: refund.exchange_pub,
        exchangeSig: refund.exchange_sig,
      });
    }
  }

  const result = await wex.runWalletDbTx(async (tx) => {
    const [myPurchase, h] = await ctx.getRecordHandle(tx);
    if (!myPurchase) {
      logger.warn("purchase group not found anymore");
      return;
    }
    let isAborting: boolean;
    switch (myPurchase.purchaseStatus) {
      case PurchaseStatus.PendingAcceptRefund:
        isAborting = false;
        break;
      case PurchaseStatus.AbortingWithRefund:
        isAborting = true;
        break;
      default:
        logger.warn("wrong state, not accepting refund");
        return;
    }

    let newGroup: WalletRefundGroup | undefined = undefined;
    // Pending, but not part of an aborted refund group.
    let numPendingItemsTotal = 0;
    const newGroupRefunds: WalletRefundItem[] = [];

    for (const rf of refunds) {
      const oldItem = await tx.getRefundItemByCoinAndRtxid(
        rf.coin_pub,
        rf.rtransaction_id,
      );
      if (oldItem) {
        logger.info("already have refund in database");
        if (oldItem.status === RefundItemStatus.Done) {
          continue;
        }
        if (rf.type === "success") {
          oldItem.status = RefundItemStatus.Done;
        } else {
          if (rf.exchange_status >= 500 && rf.exchange_status <= 599) {
            oldItem.status = RefundItemStatus.Pending;
            numPendingItemsTotal += 1;
          } else {
            oldItem.status = RefundItemStatus.Failed;
          }
        }
        await tx.upsertRefundItem(oldItem);
      } else {
        // Put refund item into a new group!
        if (!newGroup) {
          newGroup = {
            proposalId: purchase.proposalId,
            refundGroupId: newRefundGroupId,
            status: RefundGroupStatus.Pending,
            timestampCreated: timestampPreciseToDb(now),
            amountEffective: Amounts.stringify(
              Amounts.zeroOfCurrency(currency),
            ),
            amountRaw: Amounts.stringify(Amounts.zeroOfCurrency(currency)),
          };
        }
        const status: RefundItemStatus = getItemStatus(rf);
        const newItem: WalletRefundItem = {
          coinPub: rf.coin_pub,
          executionTime: timestampProtocolToDb(rf.execution_time),
          obtainedTime: timestampPreciseToDb(now),
          refundAmount: rf.refund_amount,
          refundGroupId: newGroup.refundGroupId,
          rtxid: rf.rtransaction_id,
          status,
        };
        if (status === RefundItemStatus.Pending) {
          numPendingItemsTotal += 1;
        }
        newGroupRefunds.push(newItem);
        await tx.upsertRefundItem(newItem);
      }
    }

    // Now that we know all the refunds for the new refund group,
    // we can compute the raw/effective amounts.
    if (newGroup) {
      const amountsRaw = newGroupRefunds.map((x) => x.refundAmount);
      const refreshCoins = await computeRefreshRequest(
        wex,
        tx,
        newGroupRefunds,
      );
      const outInfo = await calculateRefreshOutput(
        wex,
        tx,
        currency,
        refreshCoins,
      );
      setRefundGroupEffectiveAmount(newGroup, outInfo.outputPerCoin);
      newGroup.amountRaw = Amounts.stringify(
        Amounts.sumOrZero(currency, amountsRaw).amount,
      );
      const refundCtx = new RefundTransactionContext(
        wex,
        newGroup.refundGroupId,
      );
      await tx.upsertRefundGroup(newGroup);
      await refundCtx.updateTransactionMeta(tx);
      applyNotifyTransition(tx.notify, refundCtx.transactionId, {
        causeHint: "refund-group-create",
        oldTxState: { major: TransactionMajorState.None },
        newTxState: computeRefundTransactionState(newGroup),
        balanceEffect: BalanceEffect.Any,
        newStId: newGroup.status,
        oldStId: 0,
      });
    }

    const refundGroups = await tx.getRefundGroupsByProposal(
      myPurchase.proposalId,
    );

    for (const refundGroup of refundGroups) {
      const refundCtx = new RefundTransactionContext(
        wex,
        refundGroup.refundGroupId,
      );
      switch (refundGroup.status) {
        case RefundGroupStatus.Aborted:
        case RefundGroupStatus.Expired:
        case RefundGroupStatus.Failed:
        case RefundGroupStatus.Done:
          continue;
        case RefundGroupStatus.Pending:
          break;
        default:
          assertUnreachable(refundGroup.status);
      }
      const items = await tx.getRefundItemsByGroup(refundGroup.refundGroupId);
      const refreshCoins = await computeRefreshRequest(wex, tx, items);
      const outInfo = await calculateRefreshOutput(
        wex,
        tx,
        currency,
        refreshCoins,
      );
      setRefundGroupEffectiveAmount(refundGroup, outInfo.outputPerCoin);
      let numPending = 0;
      let numFailed = 0;
      for (const item of items) {
        if (item.status === RefundItemStatus.Pending) {
          numPending++;
        }
        if (item.status === RefundItemStatus.Failed) {
          numFailed++;
        }
      }
      const oldTxState: TransactionState =
        computeRefundTransactionState(refundGroup);
      const oldStId = refundGroup.status;
      if (numPending === 0) {
        // We're done for this refund group!
        if (numFailed === 0) {
          refundGroup.status = RefundGroupStatus.Done;
        } else {
          refundGroup.status = RefundGroupStatus.Failed;
        }
        await tx.upsertRefundGroup(refundGroup);
        await refundCtx.updateTransactionMeta(tx);
        const refreshCoins = await computeRefreshRequest(wex, tx, items);
        const newTxState: TransactionState =
          computeRefundTransactionState(refundGroup);
        const newStId = refundGroup.status;
        applyNotifyTransition(tx.notify, refundCtx.transactionId, {
          causeHint: "refund-group-final",
          oldTxState,
          newTxState,
          balanceEffect: BalanceEffect.Any,
          newStId,
          oldStId,
        });
        await createRefreshGroup(
          wex,
          tx,
          Amounts.currencyOf(amountRaw),
          refreshCoins,
          RefreshReason.Refund,
          // Since refunds are really just pseudo-transactions,
          // the originating transaction for the refresh is the payment transaction.
          constructTransactionIdentifier({
            tag: TransactionType.Payment,
            proposalId: myPurchase.proposalId,
          }),
        );
      } else {
        await tx.upsertRefundGroup(refundGroup);
      }
    }
    const shouldCheckAutoRefund =
      myPurchase.autoRefundDeadline &&
      !AbsoluteTime.isExpired(
        AbsoluteTime.fromProtocolTimestamp(
          timestampProtocolFromDb(myPurchase.autoRefundDeadline),
        ),
      );

    if (numPendingItemsTotal === 0) {
      if (!isAborting && shouldCheckAutoRefund) {
        myPurchase.purchaseStatus = PurchaseStatus.FinalizingQueryingAutoRefund;
      } else if (!isAborting) {
        myPurchase.purchaseStatus = PurchaseStatus.Done;
      }
      myPurchase.refundAmountAwaiting = undefined;
    }
    await h.update(myPurchase, "refunds-stored");

    return {
      numPendingItemsTotal,
    };
  });

  if (!result) {
    return TaskRunResult.finished();
  }

  if (result.numPendingItemsTotal > 0) {
    return TaskRunResult.backoff();
  } else {
    return TaskRunResult.progress();
  }
}

export function computeRefundTransactionState(
  refundGroupRecord: WalletRefundGroup,
): TransactionState {
  switch (refundGroupRecord.status) {
    case RefundGroupStatus.Aborted:
      return {
        major: TransactionMajorState.Aborted,
      };
    case RefundGroupStatus.Done:
      return {
        major: TransactionMajorState.Done,
      };
    case RefundGroupStatus.Failed:
      return {
        major: TransactionMajorState.Failed,
      };
    case RefundGroupStatus.Pending:
      return {
        major: TransactionMajorState.Pending,
      };
    case RefundGroupStatus.Expired:
      return {
        major: TransactionMajorState.Expired,
      };
  }
}
