    this.pad[3] = (key[22] & 0xff) | ((key[23] & 0xff) << 8);
    this.pad[4] = (key[24] & 0xff) | ((key[25] & 0xff) << 8);
    this.pad[5] = (key[26] & 0xff) | ((key[27] & 0xff) << 8);
