      h1 += ((t0 >>> 13) | (t1 << 3)) & 0x1fff;
      t2 = (m[mpos + 4] & 0xff) | ((m[mpos + 5] & 0xff) << 8);
      h2 += ((t1 >>> 10) | (t2 << 6)) & 0x1fff;
      t3 = (m[mpos + 6] & 0xff) | ((m[mpos + 7] & 0xff) << 8);
      h3 += ((t2 >>> 7) | (t3 << 9)) & 0x1fff;
      t4 = (m[mpos + 8] & 0xff) | ((m[mpos + 9] & 0xff) << 8);
