import {
  EddsaPrivP,
  EncryptionNonceP,
  LockedAccount,
  OfficerSession,
  OfficerId,
  ReserveAccount,
  createEddsaKeyPair,
  decodeCrock,
  decryptWithDerivedKey,
  eddsaGetPublic,
  encodeCrock,
  encryptWithDerivedKey,
  getRandomBytes,
  kdf,
  stringToBytes,
} from "@gnu-taler/taler-util";

/**
 * Restore previous session and unlock account with password
 *
 * @param salt string from which crypto params will be derived
 * @param key secured private key
 * @param password password for the private key
 * @returns
 */
export async function unlockOfficerAccount(
  account: LockedAccount,
  password: Password,
): Promise<OfficerSession> {
  const rawKey = decodeCrock(account);
  const rawPassword = stringToBytes(password.__pwd);

  const __signingKey = (await decryptWithDerivedKey(
    rawKey,
    rawPassword,
    password.__pwd,
  ).catch((e) => {
    throw new UnwrapKeyError(e instanceof Error ? e.message : String(e));
  })) as EddsaPrivP;

  const publicKey = eddsaGetPublic(__signingKey);

  const accountId = encodeCrock(publicKey) as OfficerId;

  return { id: accountId, __signingKey };
}
declare const __password: unique symbol;
export function asPassword(__pwd: string): Password {
  return { __pwd } as Password;
}
/**
 * Opaque password type
 * Useful to prevent accidentally printing when serializing into JSON
 */
export type Password = { __pwd: string; [__password]: true };

/**
 * Create new account (secured private key)
 * secured with the given password
 *
 * @param sessionId
 * @param password
 * @returns
 */
export async function createNewOfficerAccount(
  password: Password,
  extraNonce: EncryptionNonceP,
): Promise<OfficerSession & { safe: LockedAccount }> {
  const { eddsaPriv, eddsaPub } = createEddsaKeyPair();

  const key = stringToBytes(password.__pwd);

  const localRnd = getRandomBytes(24);
  const mergedRnd: EncryptionNonceP = extraNonce
    ? kdf(24, stringToBytes("aml-officer"), extraNonce, localRnd)
    : localRnd;

  const protectedPrivKey = await encryptWithDerivedKey(
    mergedRnd,
    key,
    eddsaPriv,
    password.__pwd,
  );

  const __signingKey = eddsaPriv as EddsaPrivP;
  const accountId = encodeCrock(eddsaPub) as OfficerId;
  const safe = encodeCrock(protectedPrivKey) as LockedAccount;

  return { id: accountId, __signingKey, safe };
}

/**
 * Create new account (secured private key)
 * secured with the given password
 *
 * @param extraNonce
 * @param password
 * @returns
 */
export async function createNewWalletKycAccount(
  extraNonce: EncryptionNonceP,
  password?: Password,
): Promise<ReserveAccount & { safe?: LockedAccount }> {
  const { eddsaPriv, eddsaPub } = createEddsaKeyPair();

  const mergedRnd: EncryptionNonceP =
    extraNonce && password
      ? kdf(24, stringToBytes("aml-officer"), extraNonce, getRandomBytes(24))
      : getRandomBytes(24);

  const protectedPrivKey = password
    ? await encryptWithDerivedKey(
        mergedRnd,
        stringToBytes(password.__pwd),
        eddsaPriv,
        password.__pwd,
      )
    : undefined;

  const __signingKey = eddsaPriv as EddsaPrivP;
  const accountId = encodeCrock(eddsaPub);
  const safe = protectedPrivKey
    ? (encodeCrock(protectedPrivKey) as LockedAccount)
    : undefined;

  return { id: accountId, __signingKey, safe };
}

export class UnwrapKeyError extends Error {
  public cause: string;
  constructor(cause: string) {
    super(`Recovering private key failed on: ${cause}`);
    this.cause = cause;
  }
}
