/**
 * Token and token family management requests.
 *
 * @author Iván Ávalos
 */
import {
  DiscountListDetail,
  EmptyObject,
  ListDiscountsResponse,
  ListSubscriptionsResponse,
  Logger,
  MerchantContractTokenKind,
  MerchantInfo,
  SubscriptionListDetail,
  TalerError,
  TalerErrorCode,
} from "@gnu-taler/taler-util";
import { WalletToken } from "./db/records.js";
import { WalletExecutionContext } from "./wallet.js";
import { expectProposalDownloadInTx } from "./pay-merchant.js";
import { isTokenInUse, isTokenValid } from "./tokenSelection.js";

const logger = new Logger("tokenFamilies.ts");

export type MerchantInfos = { [purchaseId: string]: MerchantInfo };

// FIXME: unit test for discount grouping
function groupDiscounts(
  tokens: WalletToken[],
  merchantInfos: MerchantInfos,
): DiscountListDetail[] {
  const grouped = new Map<string, DiscountListDetail>();
  const sortedTokens = tokens
    .filter((t) => t.tokenFamilyHash)
    .sort((a, b) => a.validBefore - b.validBefore);
  for (const token of sortedTokens) {
    const familyHash = token.tokenFamilyHash!;
    const existing = grouped.get(familyHash);
    if (existing) {
      existing.tokensAvailable++;
      continue;
    }
    grouped.set(familyHash, {
      tokenFamilyHash: familyHash,
      tokenIssuePubHash: token.tokenIssuePubHash,
      merchantBaseUrl: token.merchantBaseUrl,
      merchantInfo: merchantInfos[token.purchaseId],
      name: token.name,
      description: token.description,
      descriptionI18n: token.descriptionI18n,
      validityStart: token.tokenIssuePub.signature_validity_start,
      validityEnd: token.tokenIssuePub.signature_validity_end,
      tokensAvailable: 1,
    });
  }
  return [...grouped.values()];
}

// FIXME: unit test for subscription grouping
function groupSubscriptions(
  tokens: WalletToken[],
  merchantInfos: MerchantInfos,
): SubscriptionListDetail[] {
  const grouped = new Map<string, SubscriptionListDetail>();
  const sortedTokens = tokens
    .filter((t) => t.tokenFamilyHash)
    .sort((a, b) => a.validBefore - b.validBefore);

  for (const token of sortedTokens) {
    const familyHash = token.tokenFamilyHash!;
    if (grouped.has(familyHash)) {
      continue;
    }
    grouped.set(familyHash, {
      tokenFamilyHash: familyHash,
      tokenIssuePubHash: token.tokenIssuePubHash,
      merchantBaseUrl: token.merchantBaseUrl,
      merchantInfo: merchantInfos[token.purchaseId],
      name: token.name,
      description: token.description,
      descriptionI18n: token.descriptionI18n,
      validityStart: token.tokenIssuePub.signature_validity_start,
      validityEnd: token.tokenIssuePub.signature_validity_end,
    });
  }
  return [...grouped.values()];
}

async function getMerchantInfos(
  wex: WalletExecutionContext,
  tokens: WalletToken[],
): Promise<MerchantInfos> {
  const merchantInfos: MerchantInfos = {};
  await wex.runWalletDbTx(async (tx) => {
    const purchaseIds = [...new Set(tokens.map((t) => t.purchaseId))];
    const purchases = await tx.getPurchasesByIds(purchaseIds);
    for (const purchase of purchases) {
      const download = await expectProposalDownloadInTx(wex, tx, purchase);
      const contractData = download.contractTerms;
      merchantInfos[purchase.proposalId] = contractData.merchant;
    }
  });
  return merchantInfos;
}

export async function listDiscounts(
  wex: WalletExecutionContext,
  tokenIssuePubHash?: string,
  merchantBaseUrl?: string,
): Promise<ListDiscountsResponse> {
  const tokens: WalletToken[] = await wex.runWalletDbTx(async (tx) => {
    const candidates = tokenIssuePubHash
      ? await tx.getTokensByIssuePubHash(tokenIssuePubHash)
      : await tx.listTokens();
    return candidates
      .filter((t) => isTokenValid(t))
      .filter((t) => t.kind === MerchantContractTokenKind.Discount)
      .filter(
        (t) => !tokenIssuePubHash || t.tokenIssuePubHash === tokenIssuePubHash,
      )
      .filter((t) => !merchantBaseUrl || t.merchantBaseUrl === merchantBaseUrl);
  });

  if (tokens.length === 0) {
    return { discounts: [] };
  }

  return {
    discounts: groupDiscounts(tokens, await getMerchantInfos(wex, tokens)),
  };
}

export async function listSubscriptions(
  wex: WalletExecutionContext,
  tokenIssuePubHash?: string,
  merchantBaseUrl?: string,
): Promise<ListSubscriptionsResponse> {
  const tokens: WalletToken[] = await wex.runWalletDbTx(async (tx) => {
    const candidates = tokenIssuePubHash
      ? await tx.getTokensByIssuePubHash(tokenIssuePubHash)
      : await tx.listTokens();
    return candidates
      .filter((t) => isTokenValid(t))
      .filter((t) => t.kind === MerchantContractTokenKind.Subscription)
      .filter(
        (t) => !tokenIssuePubHash || t.tokenIssuePubHash === tokenIssuePubHash,
      )
      .filter((t) => !merchantBaseUrl || t.merchantBaseUrl === merchantBaseUrl);
  });

  if (tokens.length === 0) {
    return { subscriptions: [] };
  }

  return {
    subscriptions: groupSubscriptions(
      tokens,
      await getMerchantInfos(wex, tokens),
    ),
  };
}

export async function deleteDiscount(
  wex: WalletExecutionContext,
  tokenFamilyHash: string,
): Promise<EmptyObject> {
  await wex.runWalletDbTx(async (tx) => {
    const tokens = (await tx.getTokensByFamilyHash(tokenFamilyHash))
      .filter((t) => t.kind === MerchantContractTokenKind.Discount)
      .filter((t) => t.tokenFamilyHash === tokenFamilyHash);

    let inUse: boolean = false;
    for (const token of tokens) {
      if (isTokenInUse(token)) {
        inUse = true;
        break;
      }
    }

    if (inUse) {
      throw TalerError.fromDetail(
        TalerErrorCode.WALLET_TOKENS_IN_USE,
        { tokenFamilyHash },
        "one or more tokens in this family are in use",
      );
    }

    for (const token of tokens) {
      if (logger.shouldLogTrace()) {
        logger.trace(
          `deleting token in ${token.tokenIssuePubHash} token family`,
        );
      }
      await tx.deleteToken(token.tokenUsePub);
    }
  });

  return {};
}

export async function deleteSubscription(
  wex: WalletExecutionContext,
  tokenFamilyHash: string,
): Promise<EmptyObject> {
  await wex.runWalletDbTx(async (tx) => {
    const tokens = (await tx.getTokensByFamilyHash(tokenFamilyHash))
      .filter((t) => t.kind === MerchantContractTokenKind.Subscription)
      .filter((t) => t.tokenFamilyHash === tokenFamilyHash)
      .sort((a, b) => a.validBefore - b.validBefore);

    let inUse: boolean = false;
    for (const token of tokens) {
      if (isTokenInUse(token)) {
        inUse = true;
        break;
      }
    }

    if (inUse) {
      throw TalerError.fromDetail(
        TalerErrorCode.WALLET_TOKENS_IN_USE,
        { tokenFamilyHash },
        "one or more tokens in this family are in use",
      );
    }

    for (const token of tokens) {
      if (logger.shouldLogTrace()) {
        logger.trace(
          `deleting token in ${token.tokenIssuePubHash} token family`,
        );
      }
      await tx.deleteToken(token.tokenUsePub);
    }
  });

  return {};
}
