import { Paytos } from "./payto.js";
import { Result } from "./result.js";
import { InternationalizedString } from "./types-taler-common.js";
import { AccountRestriction } from "./types-taler-exchange.js";

/**
 * Restrictions apply to the normalized payto://-URI.  Callers hand us
 * whatever the bank or the user supplied, which typically still carries a
 * receiver-name parameter, so normalize here.  A URI we cannot parse is
 * matched as given rather than rejected outright, leaving the verdict to
 * the regex.
 */
function normalizeForMatching(
  paytoUri: Paytos.FullPaytoString | Paytos.NormalizedPaytoString | string,
): string {
  const parsed = Paytos.fromString(paytoUri as Paytos.FullPaytoString);
  if (Result.isError(parsed)) {
    return paytoUri;
  }
  return Paytos.toNormalizedString(parsed.value);
}

export function checkAccountRestriction(
  paytoUri: Paytos.FullPaytoString | Paytos.NormalizedPaytoString | string,
  restrictions: AccountRestriction[],
): { ok: boolean; hint?: string; hintI18n?: InternationalizedString } {
  const normalizedPayto = normalizeForMatching(paytoUri);
  for (const myRestriction of restrictions) {
    switch (myRestriction.type) {
      case "deny":
        return { ok: false };
      case "regex": {
        let regex: RegExp;
        try {
          regex = new RegExp(myRestriction.payto_regex);
        } catch (e) {
          // A pattern we cannot compile is a restriction we cannot honour.
          return {
            ok: false,
            hint: myRestriction.human_hint,
            hintI18n: myRestriction.human_hint_i18n,
          };
        }
        if (!regex.test(normalizedPayto)) {
          return {
            ok: false,
            hint: myRestriction.human_hint,
            hintI18n: myRestriction.human_hint_i18n,
          };
        }
        break;
      }
      default:
        // Fail closed, as the C implementation does.
        return { ok: false };
    }
  }
  return {
    ok: true,
  };
}
