const logger = new Logger("operations/recoup.ts");

/**
 * Store a recoup group record in the database after marking
 * a coin in the group as finished.
 */
export async function putGroupAsFinished(
  wex: WalletExecutionContext,
  tx: WalletDbTransaction,
  recoupGroup: WalletRecoupGroup,
  coinIdx: number,
): Promise<void> {
  const ctx = new RecoupTransactionContext(wex, recoupGroup.recoupGroupId);
  logger.trace(
    `setting coin ${coinIdx} of ${recoupGroup.coinPubs.length} as finished`,
  );
  if (recoupGroup.timestampFinished) {
    return;
  }
  recoupGroup.recoupFinishedPerCoin[coinIdx] = true;
  await tx.upsertRecoupGroup(recoupGroup);
  await ctx.updateTransactionMeta(tx);
}

async function recoupRewardCoin(
  wex: WalletExecutionContext,
  recoupGroupId: string,
  coinIdx: number,
  coin: WalletCoin,
): Promise<void> {
  // We can't really recoup a coin we got via tipping.
  // Thus we just put the coin to sleep.
  // FIXME: somehow report this to the user
  await wex.runWalletDbTx(async (tx) => {
    const recoupGroup = await tx.getRecoupGroup(recoupGroupId);
    if (!recoupGroup) {
      return;
    }
    if (recoupGroup.recoupFinishedPerCoin[coinIdx]) {
      return;
    }
    await putGroupAsFinished(wex, tx, recoupGroup, coinIdx);
  });
}

async function recoupRefreshCoin(
  wex: WalletExecutionContext,
  recoupGroupId: string,
  coinIdx: number,
  coin: WalletCoin,
  cs: WalletRefreshCoinSource,
): Promise<void> {
  const d = await wex.runWalletDbTx(async (tx) => {
    const denomInfo = await getDenomInfo(wex, tx, coin);
    if (!denomInfo) {
      return;
    }
    return { denomInfo };
  });
  if (!d) {
    // FIXME:  We should at least emit some pending operation / warning for this?
    return;
  }

  await requireExchangeCoinUseConfirmedOrThrow(wex, coin.exchangeBaseUrl);

  const recoupRequest = await wex.cryptoApi.createRecoupRefreshRequest({
    blindingKey: coin.blindingKey,
    coinPriv: coin.coinPriv,
    coinPub: coin.coinPub,
    denomPub: d.denomInfo.denomPub,
    denomPubHash: coin.denomPubHash,
    denomSig: coin.denomSig,
  });
  logger.trace(`making recoup request for ${coin.coinPub}`);

  const exchangeClient = walletExchangeClient(coin.exchangeBaseUrl, wex);
  await requireExchangeCoinUseConfirmedOrThrow(wex, coin.exchangeBaseUrl);
  const recoupResp = await exchangeClient.recoupRefreshCoin(
    coin.coinPub,
    recoupRequest,
  );
  const recoupConfirmation = recoupResp.body;

  if (recoupConfirmation.old_coin_pub != cs.oldCoinPub) {
    throw Error(`Coin's oldCoinPub doesn't match reserve on recoup`);
  }

  await wex.runWalletDbTx(async (tx) => {
    const recoupGroup = await tx.getRecoupGroup(recoupGroupId);
    if (!recoupGroup) {
      return;
    }
    if (recoupGroup.recoupFinishedPerCoin[coinIdx]) {
      return;
    }
    const oldCoin = await tx.getCoin(cs.oldCoinPub);
    const revokedCoin = await tx.getCoin(coin.coinPub);
    if (!revokedCoin) {
      logger.warn("revoked coin for recoup not found");
      return;
    }
    if (!oldCoin) {
      logger.warn("refresh old coin for recoup not found");
      return;
    }
    const oldCoinDenom = await getDenomInfo(wex, tx, oldCoin);
    const revokedCoinDenom = await getDenomInfo(wex, tx, revokedCoin);
    checkDbInvariant(
      !!oldCoinDenom,
      `no denom for coin, hash ${oldCoin.denomPubHash}`,
    );
    checkDbInvariant(
      !!revokedCoinDenom,
      `no revoked denom for coin, hash ${revokedCoin.denomPubHash}`,
    );
    revokedCoin.status = CoinStatus.Dormant;
    scheduleRecoupRefresh(recoupGroup, oldCoin.coinPub, revokedCoinDenom.value);
    await tx.upsertCoin(revokedCoin);
    await tx.upsertCoin(oldCoin);
    await putGroupAsFinished(wex, tx, recoupGroup, coinIdx);
  });
}

export function scheduleRecoupRefresh(
  recoupGroup: WalletRecoupGroup,
  oldCoinPub: string,
  recoveredAmount: AmountLike,
): void {
  const existingIndex = recoupGroup.scheduleRefreshCoins.findIndex(
    (x) => x.coinPub === oldCoinPub,
  );
  if (existingIndex >= 0) {
    const existing = recoupGroup.scheduleRefreshCoins[existingIndex];
    recoupGroup.scheduleRefreshCoins[existingIndex] = {
      ...existing,
      amount: Amounts.stringify(
        Amounts.add(existing.amount, recoveredAmount).amount,
      ),
    };
    return;
  }
  recoupGroup.scheduleRefreshCoins.push({
    coinPub: oldCoinPub,
    amount: Amounts.stringify(recoveredAmount),
  });
}

export async function recoupWithdrawCoin(
  wex: WalletExecutionContext,
  recoupGroupId: string,
  coinIdx: number,
  coin: WalletCoin,
  cs: WalletWithdrawCoinSource,
): Promise<void> {
  const reservePub = cs.reservePub;
  const denomInfo = await wex.runWalletDbTx(async (tx) => {
    const denomInfo = await getDenomInfo(wex, tx, coin);
    return denomInfo;
  });
  if (!denomInfo) {
    // FIXME:  We should at least emit some pending operation / warning for this?
    return;
  }

  await requireExchangeCoinUseConfirmedOrThrow(wex, coin.exchangeBaseUrl);

  const recoupRequest = await wex.cryptoApi.createRecoupRequest({
    blindingKey: coin.blindingKey,
    coinPriv: coin.coinPriv,
    coinPub: coin.coinPub,
    denomPub: denomInfo.denomPub,
    denomPubHash: coin.denomPubHash,
    denomSig: coin.denomSig,
  });
  logger.trace(`requesting recoup for coin ${coin.coinPub}`);
  const exchangeClient = walletExchangeClient(coin.exchangeBaseUrl, wex);
  await requireExchangeCoinUseConfirmedOrThrow(wex, coin.exchangeBaseUrl);
  const recoupResp = await exchangeClient.recoupCoin(
    coin.coinPub,
    recoupRequest,
  );
  const recoupConfirmation = recoupResp.body;

  logger.trace(`got recoup confirmation ${j2s(recoupConfirmation)}`);

  if (recoupConfirmation.reserve_pub !== reservePub) {
    throw Error(`Coin's reserve doesn't match reserve on recoup`);
  }

  // FIXME: verify that our expectations about the amount match
  await wex.runWalletDbTx(async (tx) => {
    const recoupGroup = await tx.getRecoupGroup(recoupGroupId);
    if (!recoupGroup) {
      return;
    }
    if (recoupGroup.recoupFinishedPerCoin[coinIdx]) {
      return;
    }
    const updatedCoin = await tx.getCoin(coin.coinPub);
    if (!updatedCoin) {
      return;
    }
    updatedCoin.status = CoinStatus.Dormant;
    await tx.upsertCoin(updatedCoin);
    await putGroupAsFinished(wex, tx, recoupGroup, coinIdx);
  });
}

export async function processRecoupGroup(
  wex: WalletExecutionContext,
  recoupGroupId: string,
): Promise<TaskRunResult> {
  if (!wex.ws.networkAvailable) {
    return TaskRunResult.networkRequired();
  }

  let recoupGroup = await wex.runWalletDbTx(async (tx) => {
    // Drops a meta record left behind by an older wallet version, which would
    // otherwise keep breaking getTransactions until the next DB migration.
    await new RecoupTransactionContext(
      wex,
      recoupGroupId,
    ).updateTransactionMeta(tx);
    return tx.getRecoupGroup(recoupGroupId);
  });
  if (!recoupGroup) {
    return TaskRunResult.finished();
  }
  if (recoupGroup.timestampFinished) {
    logger.trace("recoup group finished");
    return TaskRunResult.finished();
  }
  const ps = recoupGroup.coinPubs.map(async (x, i) => {
    try {
      await processRecoupForCoin(wex, recoupGroupId, i);
    } catch (e) {
      logger.warn(`processRecoup failed: ${e}`);
      throw e;
    }
  });
  await Promise.all(ps);

  recoupGroup = await wex.runWalletDbTx(async (tx) => {
    return tx.getRecoupGroup(recoupGroupId);
  });
  if (!recoupGroup) {
    return TaskRunResult.finished();
  }

  for (const b of recoupGroup.recoupFinishedPerCoin) {
    if (!b) {
      // Some coin still needs to be recouped, come back later.
      return TaskRunResult.backoff();
    }
  }

  logger.info("all recoups of recoup group are finished");

  const reserveSet = new Set<string>();
  const reservePrivMap: Record<string, string> = {};
  await wex.runWalletDbTx(async (tx) => {
    const coins = await tx.getCoinsByPubs(recoupGroup.coinPubs);
    const coinsByPub = new Map(coins.map((coin) => [coin.coinPub, coin]));
    const reservePubs: string[] = [];
    for (const coinPub of recoupGroup.coinPubs) {
      const coin = coinsByPub.get(coinPub);
      if (!coin) {
        throw Error(`Coin ${coinPub} not found, can't request recoup`);
      }
      if (coin.coinSource.type === CoinSourceType.Withdraw) {
        reservePubs.push(coin.coinSource.reservePub);
      }
    }
    const uniqueReservePubs = [...new Set(reservePubs)];
    const reserves = await tx.getReservesByPubs(uniqueReservePubs);
    for (const reserve of reserves) {
      reserveSet.add(reserve.reservePub);
      reservePrivMap[reserve.reservePub] = reserve.reservePriv;
    }
  });

  for (const reservePub of reserveSet) {
    logger.info(`querying reserve status for recoup of ${reservePub}`);

    const exchangeClient = walletExchangeClient(
      recoupGroup.exchangeBaseUrl,
      wex,
    );
    const reserveResp = await exchangeClient.getReserveStatus(reservePub);
    if (reserveResp.case !== "ok") {
      throw Error(
        `could not query reserve status for recoup (${reserveResp.case})`,
      );
    }
    const result = reserveResp.body;
    await internalCreateWithdrawalGroup(wex, {
      amount: Amounts.parseOrThrow(result.balance),
      exchangeBaseUrl: recoupGroup.exchangeBaseUrl,
      reserveStatus: WithdrawalGroupStatus.PendingQueryingStatus,
      reserveKeyPair: {
        pub: reservePub,
        priv: reservePrivMap[reservePub],
      },
      wgInfo: {
        withdrawalType: WithdrawalRecordType.Recoup,
      },
    });
  }

  const ctx = new RecoupTransactionContext(wex, recoupGroupId);

  await wex.runWalletDbTx(async (tx) => {
    const rg2 = await tx.getRecoupGroup(recoupGroupId);
    if (!rg2) {
      return;
    }
    rg2.timestampFinished = timestampPreciseToDb(TalerPreciseTimestamp.now());
    rg2.operationStatus = RecoupOperationStatus.Finished;
    if (rg2.scheduleRefreshCoins.length > 0) {
      await createRefreshGroup(
        wex,
        tx,
        Amounts.currencyOf(rg2.scheduleRefreshCoins[0].amount),
        rg2.scheduleRefreshCoins,
        RefreshReason.Recoup,
        constructTransactionIdentifier({
          tag: TransactionType.Recoup,
          recoupGroupId: rg2.recoupGroupId,
        }),
      );
    }
    await tx.upsertRecoupGroup(rg2);
    await ctx.updateTransactionMeta(tx);
  });
  return TaskRunResult.finished();
}

export class RecoupTransactionContext implements TransactionContext {
  public transactionId: TransactionIdStr;
  public taskId: TaskIdStr;

  constructor(
    public wex: WalletExecutionContext,
    private recoupGroupId: string,
  ) {
    this.transactionId = constructTransactionIdentifier({
      tag: TransactionType.Recoup,
      recoupGroupId,
    });
    this.taskId = constructTaskIdentifier({
      tag: PendingTaskType.Recoup,
      recoupGroupId,
    });
  }

  /**
   * A recoup group is not a materialized transaction yet: lookupFullTransaction
   * below, getContextForTransaction, rematerializeTransactions and the
   * shepherd's retry notifications all leave recoup out.  Writing a meta record
   * anyway would put an entry in the transaction list that nothing can render,
   * and getTransactions would then fail for the *whole* wallet.
   *
   * So only ever remove the record here.  That also repairs wallets that
   * already stored one before this was fixed.
   */
  async updateTransactionMeta(tx: WalletDbTransaction): Promise<void> {
    await tx.deleteTransactionMeta(this.transactionId);
  }

  userAbortTransaction(): Promise<void> {
    throw makeTransactionActionUnsupportedError(this.transactionId, "abort");
  }

  userSuspendTransaction(): Promise<void> {
    throw makeTransactionActionUnsupportedError(this.transactionId, "suspend");
  }

  userResumeTransaction(): Promise<void> {
    throw makeTransactionActionUnsupportedError(this.transactionId, "resume");
  }

  userFailTransaction(): Promise<void> {
    throw makeTransactionActionUnsupportedError(this.transactionId, "fail");
  }

  async userDeleteTransaction(): Promise<void> {
    const res = await this.wex.runWalletDbTx(async (tx) => {
      return this.deleteTransactionInTx(tx);
    });
    for (const notif of res.notifs) {
      this.wex.ws.notify(notif);
    }
  }

  async deleteTransactionInTx(
    tx: WalletDbTransaction,
  ): Promise<{ notifs: WalletNotification[] }> {
    const notifs: WalletNotification[] = [];
    const rec = await tx.getRecoupGroup(this.recoupGroupId);
    if (!rec) {
      return { notifs };
    }
    await tx.deleteRecoupGroup(this.recoupGroupId);
    await this.updateTransactionMeta(tx);
    return { notifs };
  }

  lookupFullTransaction(
    tx: WalletDbTransaction,
  ): Promise<Transaction | undefined> {
    throw makeTransactionActionUnsupportedError(
      this.transactionId,
      "lookup",
      "recoup transactions are not materialized and cannot be looked up",
    );
  }
}

export async function createRecoupGroup(
  wex: WalletExecutionContext,
  tx: WalletDbTransaction,
  exchangeBaseUrl: string,
  coinPubs: string[],
): Promise<string> {
  const recoupGroupId = encodeCrock(getRandomBytes(32));

  const ctx = new RecoupTransactionContext(wex, recoupGroupId);
  const recoupGroup: WalletRecoupGroup = {
    recoupGroupId,
    exchangeBaseUrl: exchangeBaseUrl,
    coinPubs: coinPubs,
    timestampFinished: undefined,
    timestampStarted: timestampPreciseToDb(TalerPreciseTimestamp.now()),
    recoupFinishedPerCoin: coinPubs.map(() => false),
    scheduleRefreshCoins: [],
    operationStatus: RecoupOperationStatus.Pending,
  };

  const coins = await tx.getCoinsByPubs(coinPubs);
  const coinsByPub = new Map(coins.map((coin) => [coin.coinPub, coin]));
  for (let coinIdx = 0; coinIdx < coinPubs.length; coinIdx++) {
    const coinPub = coinPubs[coinIdx];
    const coin = coinsByPub.get(coinPub);
    if (!coin) {
      await putGroupAsFinished(wex, tx, recoupGroup, coinIdx);
      continue;
    }
    await tx.upsertCoin(coin);
  }

  await tx.upsertRecoupGroup(recoupGroup);
  await ctx.updateTransactionMeta(tx);

  wex.taskScheduler.startShepherdTask(ctx.taskId);

  return recoupGroupId;
}

/**
 * Run the recoup protocol for a single coin in a recoup group.
 */
async function processRecoupForCoin(
  wex: WalletExecutionContext,
  recoupGroupId: string,
  coinIdx: number,
): Promise<void> {
  const coin = await wex.runWalletDbTx(async (tx) => {
    const recoupGroup = await tx.getRecoupGroup(recoupGroupId);
    if (!recoupGroup) {
      return;
    }
    if (recoupGroup.timestampFinished) {
      return;
    }
    if (recoupGroup.recoupFinishedPerCoin[coinIdx]) {
      return;
    }

    const coinPub = recoupGroup.coinPubs[coinIdx];

    const coin = await tx.getCoin(coinPub);
    if (!coin) {
      throw Error(`Coin ${coinPub} not found, can't request recoup`);
    }
    return coin;
  });

  if (!coin) {
    return;
  }

  const cs = coin.coinSource;

  switch (cs.type) {
    case CoinSourceType.Reward:
      return recoupRewardCoin(wex, recoupGroupId, coinIdx, coin);
    case CoinSourceType.Refresh:
      return recoupRefreshCoin(wex, recoupGroupId, coinIdx, coin, cs);
    case CoinSourceType.Withdraw:
      return recoupWithdrawCoin(wex, recoupGroupId, coinIdx, coin, cs);
    default:
      throw Error("unknown coin source type");
  }
}
