export type WithArg<X> = X extends (req: infer T) => infer R
  ? (tci: TalerCryptoInterfaceR, req: T) => R
  : never;

export type TalerCryptoInterfaceR = {
  [x in keyof TalerCryptoInterface]: WithArg<TalerCryptoInterface[x]>;
};

