/** Maximum number of new coins. */
const maxRefreshSessionSize = 64;

const logger = new Logger("refresh.ts");

export class RefreshTransactionContext implements TransactionContext {
  readonly transactionId: TransactionIdStr;
  readonly taskId: TaskIdStr;

  constructor(
    public wex: WalletExecutionContext,
    public refreshGroupId: string,
  ) {
    this.transactionId = constructTransactionIdentifier({
      tag: TransactionType.Refresh,
      refreshGroupId,
    });
    this.taskId = constructTaskIdentifier({
      tag: PendingTaskType.Refresh,
      refreshGroupId,
    });
  }

  async updateTransactionMeta(tx: WalletDbTransaction): Promise<void> {
    const rgRec = await tx.getRefreshGroup(this.refreshGroupId);
    if (!rgRec) {
      await tx.deleteTransactionMeta(this.transactionId);
      return;
    }
    await tx.upsertTransactionMeta({
      transactionId: this.transactionId,
      status: rgRec.operationStatus,
      timestamp: rgRec.timestampCreated,
      currency: rgRec.currency,
      exchanges: Object.keys(rgRec.infoPerExchange ?? {}),
    });
  }

  /**
   * Get the full transaction details for the transaction.
   *
   * Returns undefined if the transaction is in a state where we do not have a
   * transaction item (e.g. if it was deleted).
   */
  async lookupFullTransaction(
    tx: WalletDbTransaction,
  ): Promise<Transaction | undefined> {
    const refreshGroupRecord = await tx.getRefreshGroup(this.refreshGroupId);
    if (!refreshGroupRecord) {
      return undefined;
    }
    const ort = await tx.getOperationRetry(this.taskId);
    const inputAmount = Amounts.sumOrZero(
      refreshGroupRecord.currency,
      refreshGroupRecord.inputPerCoin,
    ).amount;
    const outputAmount = Amounts.sumOrZero(
      refreshGroupRecord.currency,
      refreshGroupRecord.expectedOutputPerCoin,
    ).amount;
    const txState = computeRefreshTransactionState(refreshGroupRecord);
    return {
      type: TransactionType.Refresh,
      txState,
      stId: refreshGroupRecord.operationStatus,
      scopes: await getScopeForAllExchanges(
        tx,
        !refreshGroupRecord.infoPerExchange
          ? []
          : Object.keys(refreshGroupRecord.infoPerExchange),
      ),
      txActions: computeRefreshTransactionActions(refreshGroupRecord),
      refreshReason: refreshGroupRecord.reason,
      amountEffective: isUnsuccessfulTransaction(txState)
        ? Amounts.stringify(Amounts.zeroOfAmount(inputAmount))
        : Amounts.stringify(Amounts.sub(outputAmount, inputAmount).amount),
      amountRaw: Amounts.stringify(
        Amounts.zeroOfCurrency(refreshGroupRecord.currency),
      ),
      refreshInputAmount: Amounts.stringify(inputAmount),
      refreshOutputAmount: Amounts.stringify(outputAmount),
      originatingTransactionId: refreshGroupRecord.originatingTransactionId,
      timestamp: timestampPreciseFromDb(refreshGroupRecord.timestampCreated),
      transactionId: constructTransactionIdentifier({
        tag: TransactionType.Refresh,
        refreshGroupId: refreshGroupRecord.refreshGroupId,
      }),
      failReason: refreshGroupRecord.failReason,
      ...(ort?.lastError ? { error: ort.lastError } : {}),
    };
  }

  async getRecordHandle(
    tx: WalletDbTransaction,
  ): Promise<
    [WalletRefreshGroup | undefined, RecordHandle<WalletRefreshGroup>]
  > {
    return getGenericRecordHandle<WalletRefreshGroup>(
      this,
      tx,
      async () => tx.getRefreshGroup(this.refreshGroupId),
      async (r) => {
        await tx.upsertRefreshGroup(r);
      },
      async () => tx.deleteRefreshGroup(this.refreshGroupId),
      (r) => computeRefreshTransactionState(r),
      (r) => r.operationStatus,
      () => this.updateTransactionMeta(tx),
    );
  }

  async userDeleteTransaction(): Promise<void> {
    const res = await this.wex.runWalletDbTx(async (tx) => {
      return this.deleteTransactionInTx(tx);
    });
  }

  async deleteTransactionInTx(tx: WalletDbTransaction): Promise<void> {
    const [rg, h] = await this.getRecordHandle(tx);
    if (!rg) {
      logger.warn(
        `unable to delete transaction ${this.transactionId}, not found`,
      );
      return;
    }
    const sessions = await tx.getRefreshSessionsByGroup(rg.refreshGroupId);
    for (const s of sessions) {
      await tx.deleteRefreshSession(s.refreshGroupId, s.coinIndex);
    }
    await h.update(undefined, "delete");
    await tx.deleteRefreshGroup(rg.refreshGroupId);
  }

  async userSuspendTransaction(): Promise<void> {
    await this.wex.runWalletDbTx(async (tx) => {
      const [rec, h] = await this.getRecordHandle(tx);
      if (!rec) {
        return;
      }
      switch (rec.operationStatus) {
        case RefreshOperationStatus.Finished:
        case RefreshOperationStatus.Suspended:
        case RefreshOperationStatus.SuspendedRedenominate:
        case RefreshOperationStatus.Failed:
          break;
        case RefreshOperationStatus.Pending: {
          rec.operationStatus = RefreshOperationStatus.Suspended;
          await h.update(rec, "suspend");
          break;
        }
        case RefreshOperationStatus.PendingRedenominate: {
          rec.operationStatus = RefreshOperationStatus.SuspendedRedenominate;
          await h.update(rec, "suspend");
          break;
        }
        default:
          assertUnreachable(rec.operationStatus);
      }
    });
  }

  async userAbortTransaction(): Promise<void> {
    throw makeTransactionActionUnsupportedError(
      this.transactionId,
      "abort",
      "refresh transactions cannot be aborted because their input value must remain recoverable",
    );
  }

  async userResumeTransaction(): Promise<void> {
    await this.wex.runWalletDbTx(async (tx) => {
      const [rec, h] = await this.getRecordHandle(tx);
      if (!rec) {
        return;
      }
      switch (rec.operationStatus) {
        case RefreshOperationStatus.Finished:
        case RefreshOperationStatus.Failed:
        case RefreshOperationStatus.Pending:
        case RefreshOperationStatus.PendingRedenominate:
          break;
        case RefreshOperationStatus.Suspended: {
          rec.operationStatus = RefreshOperationStatus.Pending;
          await h.update(rec, "resume");
          break;
        }
        case RefreshOperationStatus.SuspendedRedenominate: {
          rec.operationStatus = RefreshOperationStatus.PendingRedenominate;
          await h.update(rec, "resume");
          break;
        }
        default:
          assertUnreachable(rec.operationStatus);
      }
    });
  }

  userFailTransaction(): Promise<void> {
    throw makeTransactionActionUnsupportedError(
      this.transactionId,
      "fail",
      "refresh transactions cannot be failed because their input value must remain recoverable",
    );
  }
}

export async function getTotalRefreshCost(
  wex: WalletExecutionContext,
  tx: WalletDbTransaction,
  refreshedDenom: DenominationInfo,
  amountLeft: AmountJson,
): Promise<AmountJson> {
  return (
    await getTotalRefreshCosts(wex, tx, [{ refreshedDenom, amountLeft }])
  )[0];
}

function refreshCostCacheKey(
  refreshedDenom: DenominationInfo,
  amountLeft: AmountJson,
): string {
  return `denom=${refreshedDenom.exchangeBaseUrl}/${
    refreshedDenom.denomPubHash
  };left=${Amounts.stringify(amountLeft)}`;
}

/** Compute many refresh costs while loading withdrawable denoms once per exchange. */
export async function getTotalRefreshCosts(
  wex: WalletExecutionContext,
  tx: WalletDbTransaction,
  requests: Array<{
    refreshedDenom: DenominationInfo;
    amountLeft: AmountJson;
  }>,
): Promise<AmountJson[]> {
  const results: Array<AmountJson | undefined> = new Array(requests.length);
  const groups = new Map<string, number[]>();
  for (let i = 0; i < requests.length; i++) {
    const request = requests[i];
    const cached = wex.ws.refreshCostCache.get(
      refreshCostCacheKey(request.refreshedDenom, request.amountLeft),
    );
    if (cached) {
      results[i] = cached;
      continue;
    }
    const groupKey = `${request.refreshedDenom.exchangeBaseUrl}\0${Amounts.currencyOf(
      request.amountLeft,
    )}`;
    const indices = groups.get(groupKey) ?? [];
    indices.push(i);
    groups.set(groupKey, indices);
  }
  for (const indices of groups.values()) {
    const first = requests[indices[0]];
    const exchangeBaseUrl = first.refreshedDenom.exchangeBaseUrl;
    const currency = Amounts.currencyOf(first.amountLeft);
    await requireExchangeReadyTx(wex, tx, exchangeBaseUrl);
    const allDenoms = await getWithdrawableDenomsTx(
      wex,
      tx,
      exchangeBaseUrl,
      currency,
    );
    for (const index of indices) {
      const request = requests[index];
      const cost = getTotalRefreshCostInternal(
        allDenoms,
        request.refreshedDenom,
        request.amountLeft,
      );
      wex.ws.refreshCostCache.put(
        refreshCostCacheKey(request.refreshedDenom, request.amountLeft),
        cost,
      );
      results[index] = cost;
    }
  }
  return results as AmountJson[];
}

/**
 * Get the amount that we lose when refreshing a coin of the given denomination
 * with a certain amount left.
 *
 * If the amount left is zero, then the refresh cost
 * is also considered to be zero.  If a refresh isn't possible (e.g. due to lack of
 * the right denominations), then the cost is the full amount left.
 *
 * Considers refresh fees, withdrawal fees after refresh and amounts too small
 * to refresh.
 */
export function getTotalRefreshCostInternal(
  denoms: WalletDenomination[],
  refreshedDenom: DenominationInfo,
  amountLeft: AmountJson,
): AmountJson {
  logger.trace(
    `computing total refresh cost, denom value ${
      refreshedDenom.value
    }, amount left ${Amounts.stringify(amountLeft)}`,
  );
  if (denoms.length === 0) {
    return Amounts.copy(amountLeft);
  }
  const withdrawAmount = Amounts.sub(
    amountLeft,
    refreshedDenom.feeRefresh,
  ).amount;
  const denomMap = Object.fromEntries(denoms.map((x) => [x.denomPubHash, x]));
  const withdrawDenoms = selectWithdrawalDenominations(withdrawAmount, denoms, {
    limitCoins: maxRefreshSessionSize,
  });
  const resultingAmount = Amounts.add(
    Amounts.zeroOfCurrency(withdrawAmount.currency),
    ...withdrawDenoms.selectedDenoms.map(
      (d) => Amounts.mult(denomMap[d.denomPubHash].value, d.count).amount,
    ),
  ).amount;
  const totalCost = Amounts.sub(amountLeft, resultingAmount).amount;
  logger.trace(
    `total refresh cost for ${Amounts.toPretty(
      amountLeft,
    )} is ${Amounts.toPretty(totalCost)}`,
  );
  return totalCost;
}

async function getCoinAvailabilityForDenom(
  wex: WalletExecutionContext,
  tx: WalletDbTransaction,
  denom: DenominationInfo,
  ageRestriction: number,
): Promise<WalletCoinAvailability> {
  let car = await tx.getCoinAvailability({
    exchangeMasterPub: denom.exchangeMasterPub,
    denomPubHash: denom.denomPubHash,
    maxAge: ageRestriction,
  });
  if (!car) {
    car = {
      maxAge: ageRestriction,
      value: denom.value,
      currency: Amounts.currencyOf(denom.value),
      denomPubHash: denom.denomPubHash,
      exchangeBaseUrl: denom.exchangeBaseUrl,
      exchangeMasterPub: denom.exchangeMasterPub,
      freshCoinCount: 0,
      hasFreshCoins: 0,
      visibleCoinCount: 0,
    };
  }
  return car;
}

/**
 * Create a refresh session for one particular coin inside a refresh group.
 */
async function initRefreshSession(
  wex: WalletExecutionContext,
  tx: WalletDbTransaction,
  refreshGroup: WalletRefreshGroup,
  coinIndex: number,
): Promise<void> {
  const refreshGroupId = refreshGroup.refreshGroupId;
  logger.trace(
    `creating refresh session for coin ${coinIndex} in refresh group ${refreshGroupId}`,
  );
  const oldCoinPub = refreshGroup.oldCoinPubs[coinIndex];
  const oldCoin = await tx.getCoin(oldCoinPub);
  if (!oldCoin) {
    throw Error("Can't refresh, coin not found");
  }

  const exchangeBaseUrl = oldCoin.exchangeBaseUrl;

  const oldDenom = await getDenomInfo(wex, tx, {
    exchangeMasterPub: oldCoin.exchangeMasterPub,
    denomPubHash: oldCoin.denomPubHash,
  });

  if (!oldDenom) {
    throw Error("db inconsistent: denomination for coin not found");
  }

  const currency = refreshGroup.currency;

  const availableDenoms = await getWithdrawableDenomsTx(
    wex,
    tx,
    exchangeBaseUrl,
    currency,
  );

  const availableAmount = Amounts.sub(
    refreshGroup.inputPerCoin[coinIndex],
    oldDenom.feeRefresh,
  ).amount;

  const newCoinDenoms = selectWithdrawalDenominations(
    availableAmount,
    availableDenoms,
    {
      limitCoins: maxRefreshSessionSize,
    },
  );

  if (newCoinDenoms.selectedDenoms.length === 0) {
    logger.trace(
      `not refreshing, available amount ${Amounts.toPretty(
        availableAmount,
      )} too small`,
    );
    refreshGroup.statusPerCoin[coinIndex] = RefreshCoinStatus.Finished;
    return;
  }

  for (let i = 0; i < newCoinDenoms.selectedDenoms.length; i++) {
    const dph = newCoinDenoms.selectedDenoms[i].denomPubHash;
    const denom = await getDenomInfo(wex, tx, {
      exchangeMasterPub: oldDenom.exchangeMasterPub,
      denomPubHash: dph,
    });
    if (!denom) {
      logger.error(`denom ${dph} not in DB`);
      continue;
    }
    const car = await getCoinAvailabilityForDenom(
      wex,
      tx,
      denom,
      oldCoin.maxAge,
    );
    car.pendingRefreshOutputCount =
      (car.pendingRefreshOutputCount ?? 0) +
      newCoinDenoms.selectedDenoms[i].count;
    await tx.upsertCoinAvailability(car);
  }

  const newSession: WalletRefreshSession = {
    coinIndex,
    refreshGroupId,
    norevealIndex: undefined,
    newDenoms: newCoinDenoms.selectedDenoms.map((x) => ({
      count: x.count,
      denomPubHash: x.denomPubHash,
    })),
    amountRefreshOutput: Amounts.stringify(newCoinDenoms.totalCoinValue),
  };
  await tx.upsertRefreshSession(newSession);
}

/**
 * Uninitialize a refresh session.
 *
 * Adjust the coin availability of involved coins.
 */
async function destroyRefreshSession(
  wex: WalletExecutionContext,
  tx: WalletDbTransaction,
  refreshGroup: WalletRefreshGroup,
  refreshSession: WalletRefreshSession,
): Promise<void> {
  for (let i = 0; i < refreshSession.newDenoms.length; i++) {
    const oldCoin = await tx.getCoin(
      refreshGroup.oldCoinPubs[refreshSession.coinIndex],
    );
    if (!oldCoin) {
      continue;
    }
    const dph = refreshSession.newDenoms[i].denomPubHash;
    const denom = await getDenomInfo(wex, tx, {
      exchangeMasterPub: oldCoin.exchangeMasterPub,
      denomPubHash: dph,
    });
    if (!denom) {
      logger.error(`denom ${dph} not in DB`);
      continue;
    }
    const car = await getCoinAvailabilityForDenom(
      wex,
      tx,
      denom,
      oldCoin.maxAge,
    );
    checkDbInvariant(
      car.pendingRefreshOutputCount != null,
      `no pendingRefreshOutputCount for denom ${dph}`,
    );
    car.pendingRefreshOutputCount =
      car.pendingRefreshOutputCount - refreshSession.newDenoms[i].count;
    await tx.upsertCoinAvailability(car);
  }
}

function getRefreshRequestTimeout(rg: WalletRefreshGroup): Duration {
  return Duration.fromSpec({
    seconds: 60,
  });
}

/**
 * Refresh protocol variants the wallet speaks, named after the exchange
 * protocol version that introduced them.
 *
 * In v27, the fresh coins of a cut-and-choose candidate batch are derived from
 * a signature by the old coin over a nonce, and the reveal step discloses
 * those signatures.  In v32 they are derived via transfer keys again: the
 * reveal step discloses batch seeds instead, and the melt step publishes the
 * transfer public keys, which is what lets the owner of the old coin recover
 * the fresh coins from the exchange's link data.
 */
const REFRESH_PROTOCOL_V27 = 27;
const REFRESH_PROTOCOL_V32 = 32;

/**
 * Which refresh protocol a session speaks.
 *
 * Fixed when the melt request is prepared and stored with the session, since
 * melt and reveal must agree on it even if the exchange is upgraded in
 * between.
 */
function refreshProtocolVersionOf(
  rs: WalletRefreshSession,
): typeof REFRESH_PROTOCOL_V27 | typeof REFRESH_PROTOCOL_V32 {
  const v = rs.refreshProtocolVersion;
  // Absent means the session was melted before the field existed.
  if (v == null || v === REFRESH_PROTOCOL_V27) {
    return REFRESH_PROTOCOL_V27;
  }
  if (v === REFRESH_PROTOCOL_V32) {
    return REFRESH_PROTOCOL_V32;
  }
  // Guessing here would make us reveal secrets that do not match what we
  // committed to in the melt step, which permanently loses the coin.
  throw Error(
    `refresh session ${rs.refreshGroupId}/${rs.coinIndex} uses unknown refresh protocol version ${v}`,
  );
}

interface DerivedRefreshCommon {
  confirmSig: string;
  planchets: RefreshPlanchetInfo[][];
  /** The refresh commitment, i.e. the session hash. */
  hash: string;
  meltValueWithFee: AmountJson;
  blindingSeed?: string;
}

type DerivedRefresh =
  | (DerivedRefreshCommon & {
      protocolVersion: typeof REFRESH_PROTOCOL_V27;
      /** kappa signatures by the old coin's private key. */
      signatures: EddsaSignatureString[];
    })
  | (DerivedRefreshCommon & {
      protocolVersion: typeof REFRESH_PROTOCOL_V32;
      /** kappa batch seeds, one per cut-and-choose candidate batch. */
      batchSeeds: HashCodeString[];
      /** kappa arrays of one transfer public key per fresh coin. */
      transferPubs: EddsaPublicKeyString[][];
    });

/**
 * Re-derive everything about a refresh session from the stored seed, using the
 * refresh protocol the session melted with.
 *
 * The derivation is deterministic, so the melt and the reveal step both call
 * this instead of carrying the derived secrets across the two requests.
 */
async function deriveRefreshSession(
  wex: WalletExecutionContext,
  refreshSession: WalletRefreshSession,
  oldCoin: WalletCoin,
  oldDenom: DenominationInfo,
  newCoinDenoms: RefreshNewDenomInfo[],
): Promise<DerivedRefresh> {
  checkLogicInvariant(refreshSession.sessionPublicSeed != null);
  const nks: { coin_offset: number; denom_pub_hash: string }[] = [];
  let coinOffset = 0;
  for (const nd of newCoinDenoms) {
    for (let i = 0; i < nd.count; i++, coinOffset++) {
      if (nd.denomPub.cipher === DenomKeyType.ClauseSchnorr) {
        nks.push({ coin_offset: coinOffset, denom_pub_hash: nd.denomPubHash });
      }
    }
  }
  let blindingSeed: string | undefined;
  let exchangeWithdrawValues: (ExchangeWithdrawValue | undefined)[] | undefined;
  if (nks.length > 0) {
    blindingSeed = encodeCrock(
      deriveCsRefreshBlindingSeed(
        decodeCrock(refreshSession.sessionPublicSeed),
        decodeCrock(oldCoin.coinPriv),
      ),
    );
    const prep = succeedOrThrow(
      await walletExchangeClient(
        oldCoin.exchangeBaseUrl,
        wex,
      ).postBlindingPrepare({
        body: {
          cipher: DenomKeyType.ClauseSchnorr,
          operation: "melt",
          seed: blindingSeed,
          nks,
        },
      }),
    );
    if (prep.r_pubs.length !== nks.length) {
      throw Error("exchange returned wrong number of Clause-Schnorr R-pairs");
    }
    exchangeWithdrawValues = new Array(coinOffset);
    for (let i = 0; i < nks.length; i++) {
      exchangeWithdrawValues[nks[i].coin_offset] = {
        cipher: DenomKeyType.ClauseSchnorr,
        r_pub_0: prep.r_pubs[i][0],
        r_pub_1: prep.r_pubs[i][1],
      };
    }
  }
  const req = {
    kappa: 3,
    meltCoinDenomPubHash: oldCoin.denomPubHash,
    meltCoinPriv: oldCoin.coinPriv,
    meltCoinPub: oldCoin.coinPub,
    feeRefresh: Amounts.parseOrThrow(oldDenom.feeRefresh),
    meltCoinMaxAge: oldCoin.maxAge,
    meltCoinAgeCommitmentProof: oldCoin.ageCommitmentProof,
    newCoinDenoms,
    sessionPublicSeed: refreshSession.sessionPublicSeed,
    blindingSeed,
    exchangeWithdrawValues,
  };
  const protocolVersion = refreshProtocolVersionOf(refreshSession);
  switch (protocolVersion) {
    case REFRESH_PROTOCOL_V32: {
      const derived = await wex.cryptoApi.deriveRefreshSessionV3(req);
      return {
        protocolVersion,
        confirmSig: derived.confirmSig,
        planchets: derived.planchets,
        hash: derived.hash,
        meltValueWithFee: derived.meltValueWithFee,
        batchSeeds: derived.batchSeeds,
        transferPubs: derived.transferPubs,
        blindingSeed,
      };
    }
    case REFRESH_PROTOCOL_V27: {
      const derived = await wex.cryptoApi.deriveRefreshSessionV2(req);
      return {
        protocolVersion,
        confirmSig: derived.confirmSig,
        planchets: derived.planchets,
        hash: derived.hash,
        meltValueWithFee: derived.meltValueWithFee,
        signatures: derived.signatures,
        blindingSeed,
      };
    }
    default:
      assertUnreachable(protocolVersion);
  }
}

/**
 * Run the melt step of a refresh session.
 *
 * If the melt step succeeds or fails permanently,
 * the status in the refresh group is updated.
 *
 * Returns true if the coin has been melted and the noreveal index is
 * stored in the refresh session, i.e. the reveal step can proceed.
 *
 * When a transient error occurs, an exception is thrown.
 */
async function refreshMelt(
  wex: WalletExecutionContext,
  refreshGroupId: string,
  coinIndex: number,
): Promise<boolean> {
  const ctx = new RefreshTransactionContext(wex, refreshGroupId);
  const d = await wex.runWalletDbTx(async (tx) => {
    const refreshGroup = await tx.getRefreshGroup(refreshGroupId);
    if (!refreshGroup) {
      return;
    }
    const refreshSession = await tx.getRefreshSession(
      refreshGroupId,
      coinIndex,
    );
    if (!refreshSession) {
      return;
    }
    if (refreshSession.norevealIndex !== undefined) {
      return "already-melted" as const;
    }

    const oldCoin = await tx.getCoin(refreshGroup.oldCoinPubs[coinIndex]);
    checkDbInvariant(!!oldCoin, "melt coin doesn't exist");
    const oldDenom = await getDenomInfo(wex, tx, oldCoin);
    checkDbInvariant(!!oldDenom, "denomination for melted coin doesn't exist");

    const newCoinDenoms: RefreshNewDenomInfo[] = [];

    for (const dh of refreshSession.newDenoms) {
      const newDenom = await getDenomInfo(wex, tx, {
        exchangeMasterPub: oldCoin.exchangeMasterPub,
        denomPubHash: dh.denomPubHash,
      });
      checkDbInvariant(
        !!newDenom,
        "new denomination for refresh not in database",
      );
      newCoinDenoms.push({
        count: dh.count,
        denomPub: newDenom.denomPub,
        denomPubHash: newDenom.denomPubHash,
        feeWithdraw: newDenom.feeWithdraw,
        value: Amounts.stringify(newDenom.value),
      });
    }
    return { newCoinDenoms, oldCoin, oldDenom, refreshGroup, refreshSession };
  });

  if (!d) {
    // The refresh group or session is gone, nothing left to do.
    return false;
  }

  if (d === "already-melted") {
    return true;
  }

  // Make sure that we have a seed and know which refresh protocol to speak.
  if (d.refreshSession.sessionPublicSeed == null) {
    const exchange = await fetchFreshExchange(wex, d.oldCoin.exchangeBaseUrl);
    const exchangeVer = LibtoolVersion.parseVersion(
      exchange.protocolVersionRange,
    );
    checkDbInvariant(!!exchangeVer, "bad exchange version string");
    if (exchangeVer.current < 27) {
      throw Error("unsupported exchange version");
    }
    const refreshProtocolVersion =
      exchangeVer.current >= REFRESH_PROTOCOL_V32
        ? REFRESH_PROTOCOL_V32
        : REFRESH_PROTOCOL_V27;
    const seed = encodeCrock(getRandomBytes(64));
    const updatedSession = await wex.runWalletDbTx(async (tx) => {
      const refreshSession = await tx.getRefreshSession(
        refreshGroupId,
        coinIndex,
      );
      if (!refreshSession) {
        return undefined;
      }
      if (refreshSession.sessionPublicSeed != null) {
        return refreshSession;
      }
      refreshSession.sessionPublicSeed = seed;
      refreshSession.refreshProtocolVersion = refreshProtocolVersion;
      await tx.upsertRefreshSession(refreshSession);
      return refreshSession;
    });
    if (!updatedSession) {
      throw Error("Could not update refresh session (concurrent deletion?).");
    }
    d.refreshSession = updatedSession;
  }

  const { newCoinDenoms, oldCoin, oldDenom, refreshGroup, refreshSession } = d;

  checkLogicInvariant(refreshSession.sessionPublicSeed != null);

  await requireExchangeCoinUseConfirmedOrThrow(wex, oldCoin.exchangeBaseUrl);

  let maybeAch: HashCodeString | undefined;
  if (oldCoin.ageCommitmentProof) {
    maybeAch = AgeRestriction.hashCommitment(
      oldCoin.ageCommitmentProof.commitment,
    );
  }
  const derived = await deriveRefreshSession(
    wex,
    refreshSession,
    oldCoin,
    oldDenom,
    newCoinDenoms,
  );

  // Wallet stores new denoms run-length encoded,
  // we need to expand the list of denominations
  // for the exchange.
  const newDenomsFlat: string[] = [];
  for (let i = 0; i < newCoinDenoms.length; i++) {
    const dsel = newCoinDenoms[i];
    for (let j = 0; j < dsel.count; j++) {
      newDenomsFlat.push(dsel.denomPubHash);
    }
  }

  const meltReqBody: ExchangeMeltRequestV2 = {
    old_coin_pub: oldCoin.coinPub,
    old_denom_pub_h: oldCoin.denomPubHash,
    old_denom_sig: oldCoin.denomSig,
    old_age_commitment_h: maybeAch,
    refresh_seed: refreshSession.sessionPublicSeed,
    blinding_seed: derived.blindingSeed,
    confirm_sig: derived.confirmSig,
    coin_evs: derived.planchets.map((x) => x.map((y) => y.coinEv)),
    // Absent for v27; its absence is how the exchange tells the two refresh
    // protocols apart.
    transfer_pubs:
      derived.protocolVersion === REFRESH_PROTOCOL_V32
        ? derived.transferPubs
        : undefined,
    denoms_h: newDenomsFlat,
    value_with_fee: Amounts.stringify(derived.meltValueWithFee),
  };
  const exchangeClient = walletExchangeClient(
    oldCoin.exchangeBaseUrl,
    wex,
    getRefreshRequestTimeout(refreshGroup),
  );
  const resp = await wex.ws.runSequentialized(
    [EXCHANGE_COINS_LOCK],
    async () => {
      await requireExchangeCoinUseConfirmedOrThrow(
        wex,
        oldCoin.exchangeBaseUrl,
      );
      return exchangeClient.postMelt({ body: meltReqBody });
    },
  );

  switch (resp.case) {
    case HttpStatusCode.NotFound:
      await handleRefreshMeltNotFound(
        ctx,
        coinIndex,
        resp.response,
        resp.detail!,
      );
      return false;
    case HttpStatusCode.Gone:
      await handleRefreshMeltGone(ctx, coinIndex, resp.detail!);
      return false;
    case HttpStatusCode.Conflict:
      await handleRefreshMeltConflict(
        ctx,
        refreshGroup,
        coinIndex,
        resp.detail!,
        derived.meltValueWithFee,
        oldCoin,
      );
      return false;
    case "ok":
      break;
    default:
      throwUnexpectedRequestError(resp.response, resp.detail!);
  }

  const meltResponse = resp.body;
  const norevealIndex = meltResponse.noreveal_index;
  requireValidNorevealIndex(norevealIndex, derived.planchets.length);

  const signingKeyKnown = await wex.runWalletDbTx(async (tx) => {
    const details = await tx.getExchangeDetails(oldCoin.exchangeBaseUrl);
    if (details?.rowId == null) {
      return false;
    }
    const signKeys = await tx.getExchangeSignKeysByDetailsRowId(details.rowId);
    const now = AbsoluteTime.now();
    const tolerance = Duration.fromSpec({ hours: 1 });
    const latestStart = AbsoluteTime.addDuration(now, tolerance);
    const earliestExpiry = AbsoluteTime.subtractDuraction(now, tolerance);
    return signKeys.some(
      (x) =>
        x.signkeyPub === meltResponse.exchange_pub &&
        AbsoluteTime.cmp(
          AbsoluteTime.fromProtocolTimestamp(
            timestampProtocolFromDb(x.stampStart),
          ),
          latestStart,
        ) <= 0 &&
        AbsoluteTime.cmp(
          AbsoluteTime.fromProtocolTimestamp(
            timestampProtocolFromDb(x.stampExpire),
          ),
          earliestExpiry,
        ) > 0,
    );
  });
  const { valid: signatureValid } = await wex.cryptoApi.isValidMeltConfirmation(
    {
      refreshCommitment: derived.hash,
      norevealIndex,
      exchangePub: meltResponse.exchange_pub,
      exchangeSig: meltResponse.exchange_sig,
    },
  );
  if (!signingKeyKnown || !signatureValid) {
    throw TalerError.fromDetail(
      TalerErrorCode.WALLET_TRANSACTION_PROTOCOL_VIOLATION,
      {},
      "exchange returned an invalid melt confirmation signature",
    );
  }

  refreshSession.norevealIndex = norevealIndex;

  return await wex.runWalletDbTx(async (tx) => {
    const rg = await tx.getRefreshGroup(refreshGroupId);
    if (!rg) {
      return false;
    }
    if (rg.timestampFinished) {
      return false;
    }
    const rs = await tx.getRefreshSession(refreshGroupId, coinIndex);
    if (!rs) {
      return false;
    }
    if (rs.norevealIndex !== undefined) {
      return true;
    }
    rs.norevealIndex = norevealIndex;
    await tx.upsertRefreshSession(rs);
    return true;
  });
}

export function requireValidNorevealIndex(index: number, kappa: number): void {
  if (Number.isInteger(index) && index >= 0 && index < kappa) {
    return;
  }
  throw TalerError.fromDetail(
    TalerErrorCode.WALLET_TRANSACTION_PROTOCOL_VIOLATION,
    {},
    `exchange returned invalid noreveal index ${index} for kappa ${kappa}`,
  );
}

export type RecoveryRefreshOutcome = "pending" | "recovered" | "failed";

export function classifyRecoveryRefresh(
  status: RefreshOperationStatus | undefined,
): RecoveryRefreshOutcome {
  switch (status) {
    case RefreshOperationStatus.Finished:
      return "recovered";
    case undefined:
    case RefreshOperationStatus.Failed:
      return "failed";
    case RefreshOperationStatus.Pending:
    case RefreshOperationStatus.PendingRedenominate:
    case RefreshOperationStatus.Suspended:
    case RefreshOperationStatus.SuspendedRedenominate:
      return "pending";
    default:
      assertUnreachable(status);
  }
}

/**
 * Handle a "Gone" response from the exchange to a melt request.
 */
async function handleRefreshMeltGone(
  ctx: RefreshTransactionContext,
  coinIndex: number,
  errDetails: TalerErrorDetail,
): Promise<void> {
  // const expiredMsg = codecForDenominationExpiredMessage().decode(errDetails);

  // FIXME: Validate signature, possibly even store.

  logger.warn(`handling melt Gone response from exchange`);

  ctx.wex.ws.addFdr({
    event: FlightRecordEvent.MeltGone,
    target: ctx.transactionId,
  });

  await ctx.wex.runWalletDbTx(async (tx) => {
    const [rg, h] = await ctx.getRecordHandle(tx);
    if (!rg) {
      return;
    }
    if (rg.timestampFinished) {
      return;
    }
    if (rg.statusPerCoin[coinIndex] !== RefreshCoinStatus.Pending) {
      return;
    }
    rg.statusPerCoin[coinIndex] = RefreshCoinStatus.PendingRedenominate;
    const refreshSession = await tx.getRefreshSession(
      ctx.refreshGroupId,
      coinIndex,
    );
    if (!refreshSession) {
      throw Error("db invariant failed: missing refresh session in database");
    }
    refreshSession.lastError = errDetails;
    await tx.upsertRefreshSession(refreshSession);
    await h.update(rg, "melt-gone");
  });
}

async function handleRefreshMeltConflict(
  ctx: RefreshTransactionContext,
  refreshGroup: WalletRefreshGroup,
  coinIndex: number,
  errDetails: TalerErrorDetail,
  meltValueWithFee: AmountLike,
  oldCoin: WalletCoin,
): Promise<void> {
  // Just log for better diagnostics here, error status
  // will be handled later.
  logger.error(
    `melt request for ${Amounts.stringify(
      meltValueWithFee,
    )} failed in refresh group ${ctx.refreshGroupId} due to conflict`,
  );

  const refundReq = refreshGroup.refundRequests[coinIndex];
  if (refundReq != null) {
    logger.trace(`Doing deposit in refresh for coin ${coinIndex}`);
    const exchangeClient = walletExchangeClient(
      oldCoin.exchangeBaseUrl,
      ctx.wex,
    );
    const refundResp = await exchangeClient.refundCoin(
      oldCoin.coinPub,
      refundReq,
    );
    if (refundResp.case === "ok") {
      await requireValidDirectExchangeRefundConfirmation(ctx.wex, {
        exchangeBaseUrl: oldCoin.exchangeBaseUrl,
        contractTermsHash: refundReq.h_contract_terms,
        coinPub: oldCoin.coinPub,
        merchantPub: refundReq.merchant_pub,
        rtransactionId: refundReq.rtransaction_id,
        refundAmount: refundReq.refund_amount,
        response: refundResp.body,
      });
      await ctx.wex.runWalletDbTx(async (tx) => {
        const rg = await tx.getRefreshGroup(refreshGroup.refreshGroupId);
        if (!rg || rg.operationStatus != RefreshOperationStatus.Pending) {
          return;
        }
        delete rg.refundRequests[coinIndex];
        await tx.upsertRefreshGroup(rg);
      });
    } else {
      // FIXME: Store the error somewhere in the DB?
      logger.warn(
        `Refund request during refresh failed: ${j2s(refundResp.detail)}`,
      );
    }
    return;
  }

  const historySig = await ctx.wex.cryptoApi.signCoinHistoryRequest({
    coinPriv: oldCoin.coinPriv,
    coinPub: oldCoin.coinPub,
    startOffset: 0,
  });

  const exchangeClient = walletExchangeClient(oldCoin.exchangeBaseUrl, ctx.wex);
  const historyResp = await exchangeClient.getCoinHistory(
    oldCoin.coinPub,
    historySig.sig,
  );

  const historyJson = historyResp.body;
  logger.info(`coin history: ${j2s(historyJson)}`);

  // FIXME: If response seems wrong, report to auditor (in the future!);

  await ctx.wex.runWalletDbTx(async (tx) => {
    const [rg, h] = await ctx.getRecordHandle(tx);
    if (!rg) {
      return;
    }
    if (rg.timestampFinished) {
      return;
    }
    if (rg.statusPerCoin[coinIndex] !== RefreshCoinStatus.Pending) {
      return;
    }
    if (Amounts.isZero(historyJson.balance)) {
      const refreshSession = await tx.getRefreshSession(
        ctx.refreshGroupId,
        coinIndex,
      );
      if (!refreshSession) {
        throw Error("db invariant failed: missing refresh session in database");
      }
      if (rg.reason === RefreshReason.AbortPay) {
        // A coin selected for a partially completed payment can legitimately
        // have no balance left: the merchant deposited it before the wallet
        // started the precautionary abort refresh.  The merchant's abort
        // refund is responsible for recovering that value, so this refresh
        // coin has no output and is complete rather than failed.
        await destroyRefreshSession(ctx.wex, tx, rg, refreshSession);
        await tx.deleteRefreshSession(ctx.refreshGroupId, coinIndex);
        rg.expectedOutputPerCoin[coinIndex] = Amounts.stringify(
          Amounts.zeroOfCurrency(rg.currency),
        );
        rg.statusPerCoin[coinIndex] = RefreshCoinStatus.Finished;
        await h.update(rg, "melt-conflict-abort-pay-spent");
      } else {
        rg.statusPerCoin[coinIndex] = RefreshCoinStatus.Failed;
        refreshSession.lastError = errDetails;
        await tx.upsertRefreshSession(refreshSession);
        await h.update(rg, "melt-conflict");
      }
    } else {
      // Try again with new denoms!
      rg.inputPerCoin[coinIndex] = historyJson.balance;
      const refreshSession = await tx.getRefreshSession(
        ctx.refreshGroupId,
        coinIndex,
      );
      if (!refreshSession) {
        throw Error("db invariant failed: missing refresh session in database");
      }
      await destroyRefreshSession(ctx.wex, tx, rg, refreshSession);
      await tx.deleteRefreshSession(ctx.refreshGroupId, coinIndex);
      await initRefreshSession(ctx.wex, tx, rg, coinIndex);
      // The new session was computed from the corrected input amount,
      // so that amount must be stored as well.
      await h.update(rg, "melt-conflict-retry");
    }
  });
}

async function handleRefreshMeltNotFound(
  ctx: RefreshTransactionContext,
  coinIndex: number,
  resp: HttpResponse,
  errDetails: TalerErrorDetail,
): Promise<void> {
  // Make sure that we only act on a 404 that indicates a final problem
  // with the coin.
  switch (errDetails.code) {
    case TalerErrorCode.EXCHANGE_GENERIC_COIN_UNKNOWN:
    case TalerErrorCode.EXCHANGE_GENERIC_DENOMINATION_KEY_UNKNOWN:
      break;
    default:
      throwUnexpectedRequestError(resp, errDetails);
  }
  await ctx.wex.runWalletDbTx(async (tx) => {
    const [rg, h] = await ctx.getRecordHandle(tx);
    if (!rg) {
      return;
    }
    if (rg.timestampFinished) {
      return;
    }
    if (rg.statusPerCoin[coinIndex] !== RefreshCoinStatus.Pending) {
      return;
    }
    rg.statusPerCoin[coinIndex] = RefreshCoinStatus.Failed;
    const refreshSession = await tx.getRefreshSession(
      ctx.refreshGroupId,
      coinIndex,
    );
    if (!refreshSession) {
      throw Error("db invariant failed: missing refresh session in database");
    }
    refreshSession.lastError = errDetails;
    await tx.upsertRefreshSession(refreshSession);
    await destroyRefreshSession(ctx.wex, tx, rg, refreshSession);
    await h.update(rg, "melt-not-found");
  });
}

async function refreshReveal(
  wex: WalletExecutionContext,
  refreshGroupId: string,
  coinIndex: number,
): Promise<void> {
  logger.trace(
    `doing refresh reveal for ${refreshGroupId} (old coin ${coinIndex})`,
  );
  const ctx = new RefreshTransactionContext(wex, refreshGroupId);
  const d = await wex.runWalletDbTx(async (tx) => {
    const refreshGroup = await tx.getRefreshGroup(refreshGroupId);
    if (!refreshGroup) {
      return;
    }
    const refreshSession = await tx.getRefreshSession(
      refreshGroupId,
      coinIndex,
    );
    if (!refreshSession) {
      return;
    }
    const norevealIndex = refreshSession.norevealIndex;
    if (norevealIndex === undefined) {
      // The caller only reveals after a successful melt.
      throw Error("can't reveal without melting first");
    }

    const oldCoin = await tx.getCoin(refreshGroup.oldCoinPubs[coinIndex]);
    checkDbInvariant(!!oldCoin, "melt coin doesn't exist");
    const oldDenom = await getDenomInfo(wex, tx, oldCoin);
    checkDbInvariant(!!oldDenom, "denomination for melted coin doesn't exist");

    const newCoinDenoms: RefreshNewDenomInfo[] = [];

    // The key that signed the outputs.  RefreshNewDenomInfo is a crypto-layer
    // type and deliberately carries no exchange identity, so it is taken from
    // the denomination here; every output of one refresh comes from the same
    // key set.
    let newDenomMasterPub: string | undefined = undefined;

    for (const dh of refreshSession.newDenoms) {
      const newDenom = await getDenomInfo(wex, tx, {
        exchangeMasterPub: oldCoin.exchangeMasterPub,
        denomPubHash: dh.denomPubHash,
      });
      checkDbInvariant(
        !!newDenom,
        "new denomination for refresh not in database",
      );
      newDenomMasterPub = newDenom.exchangeMasterPub;
      newCoinDenoms.push({
        count: dh.count,
        denomPub: newDenom.denomPub,
        denomPubHash: newDenom.denomPubHash,
        feeWithdraw: newDenom.feeWithdraw,
        value: Amounts.stringify(newDenom.value),
      });
    }
    return {
      oldCoin,
      oldDenom,
      newCoinDenoms,
      newDenomMasterPub,
      refreshSession,
      refreshGroup,
      norevealIndex,
    };
  });

  if (!d) {
    return;
  }

  const {
    oldCoin,
    oldDenom,
    newCoinDenoms,
    newDenomMasterPub,
    refreshSession,
    refreshGroup,
    norevealIndex,
  } = d;
  checkLogicInvariant(newDenomMasterPub != null);

  // Blinded signatures, either from the old or the new reveal protocol.
  let resEvSigs: BlindedDenominationSignature[];
  let planchets: RefreshPlanchetInfo[][];

  checkLogicInvariant(refreshSession.sessionPublicSeed != null);

  const derived = await deriveRefreshSession(
    wex,
    refreshSession,
    oldCoin,
    oldDenom,
    newCoinDenoms,
  );
  // Everything but the candidate batch the exchange told us to keep secret.
  const disclosed = (_: unknown, i: number): boolean => i !== norevealIndex;
  const req: ExchangeRefreshRevealRequestV2 = {
    rc: derived.hash,
    age_commitment: oldCoin.ageCommitmentProof?.commitment?.publicKeys,
    ...(derived.protocolVersion === REFRESH_PROTOCOL_V32
      ? { batch_seeds: derived.batchSeeds.filter(disclosed) }
      : { signatures: derived.signatures.filter(disclosed) }),
  };
  const exchangeClient = walletExchangeClient(
    oldCoin.exchangeBaseUrl,
    wex,
    getRefreshRequestTimeout(refreshGroup),
  );
  const resp = await wex.ws.runSequentialized([EXCHANGE_COINS_LOCK], async () =>
    exchangeClient.postRevealMelt({ body: req }),
  );

  switch (resp.case) {
    case "ok":
      break;
    case HttpStatusCode.Conflict:
    case HttpStatusCode.Gone:
      await handleRefreshRevealError(ctx, coinIndex, resp.detail!);
      return;
    default:
      throwUnexpectedRequestError(resp.response, resp.detail!);
  }

  const reveal = resp.body;
  resEvSigs = reveal.ev_sigs;
  planchets = derived.planchets;

  const coins: WalletCoin[] = [];

  for (let i = 0; i < refreshSession.newDenoms.length; i++) {
    const ncd = newCoinDenoms[i];
    for (let j = 0; j < refreshSession.newDenoms[i].count; j++) {
      const newCoinIndex = coins.length;
      const pc = planchets[norevealIndex][newCoinIndex];
      const evSig = resEvSigs[newCoinIndex];
      const denomSig = await wex.cryptoApi.unblindDenominationSignature({
        planchet: {
          blindingKey: pc.blindingKey,
          denomPub: ncd.denomPub,
          exchangeWithdrawValues: pc.exchangeWithdrawValues,
        },
        evSig,
      });
      const coinPubHash = hashCoinPub(
        pc.coinPub,
        pc.ageCommitmentProof
          ? AgeRestriction.hashCommitment(pc.ageCommitmentProof.commitment)
          : undefined,
      );
      const verification = await wex.cryptoApi.verifyDenominationSignature({
        coinPubHash: encodeCrock(coinPubHash),
        denomPub: ncd.denomPub,
        denomSig,
      });
      if (!verification.valid) {
        throw Error("invalid denomination signature on refreshed coin");
      }
      const coin: WalletCoin = {
        blindingKey: pc.blindingKey,
        exchangeWithdrawValues: pc.exchangeWithdrawValues,
        coinPriv: pc.coinPriv,
        coinPub: pc.coinPub,
        denomPubHash: ncd.denomPubHash,
        denomSig,
        exchangeBaseUrl: oldCoin.exchangeBaseUrl,
        exchangeMasterPub: newDenomMasterPub,
        status: CoinStatus.Fresh,
        coinSource: {
          type: CoinSourceType.Refresh,
          refreshGroupId,
          oldCoinPub: refreshGroup.oldCoinPubs[coinIndex],
        },
        sourceTransactionId: ctx.transactionId,
        coinEvHash: pc.coinEvHash,
        maxAge: pc.maxAge,
        ageCommitmentProof: pc.ageCommitmentProof,
      };

      coins.push(coin);
    }
  }

  await wex.runWalletDbTx(async (tx) => {
    const [rg, h] = await ctx.getRecordHandle(tx);
    if (!rg) {
      logger.warn("no refresh session found");
      return;
    }
    if (rg.statusPerCoin[coinIndex] !== RefreshCoinStatus.Pending) {
      return;
    }
    const rs = await tx.getRefreshSession(refreshGroupId, coinIndex);
    if (!rs) {
      return;
    }
    rg.statusPerCoin[coinIndex] = RefreshCoinStatus.Finished;
    const existingCoins = await tx.getCoinsByPubs(
      coins.map((coin) => coin.coinPub),
    );
    const existingCoinPubs = new Set(existingCoins.map((coin) => coin.coinPub));
    const newCoins = coins.filter(
      (coin) => !existingCoinPubs.has(coin.coinPub),
    );
    const denoms = await getDenomInfos(wex, tx, newCoins);
    const loadedAvailabilities = await tx.getCoinAvailabilitiesByRefs(newCoins);
    const availabilities = new Map(
      loadedAvailabilities.map((availability) => [
        coinAvailabilityRefKey(availability),
        availability,
      ]),
    );
    for (const coin of newCoins) {
      await tx.upsertCoin(coin);
      const denomInfo = denoms.get(denomRefKey(coin));
      checkDbInvariant(!!denomInfo, `no denom with hash ${coin.denomPubHash}`);
      const availabilityKey = coinAvailabilityRefKey(coin);
      let car = availabilities.get(availabilityKey);
      if (!car) {
        car = {
          maxAge: coin.maxAge,
          value: denomInfo.value,
          currency: Amounts.currencyOf(denomInfo.value),
          denomPubHash: denomInfo.denomPubHash,
          exchangeBaseUrl: denomInfo.exchangeBaseUrl,
          exchangeMasterPub: denomInfo.exchangeMasterPub,
          freshCoinCount: 0,
          hasFreshCoins: 0,
          visibleCoinCount: 0,
        };
        availabilities.set(availabilityKey, car);
      }
      checkDbInvariant(
        car.pendingRefreshOutputCount != null &&
          car.pendingRefreshOutputCount > 0,
        `no pendingRefreshOutputCount for denom ${coin.denomPubHash} age ${coin.maxAge}`,
      );
      car.pendingRefreshOutputCount--;
      car.freshCoinCount++;
    }
    for (const availability of availabilities.values()) {
      await tx.upsertCoinAvailability(availability);
    }
    await h.update(rg, "reveal");
  });
  logger.trace("refresh finished (end of reveal)");
}

async function handleRefreshRevealError(
  ctx: RefreshTransactionContext,
  coinIndex: number,
  errDetails: TalerErrorDetail,
): Promise<void> {
  await ctx.wex.runWalletDbTx(async (tx) => {
    const [rg, h] = await ctx.getRecordHandle(tx);
    if (!rg) {
      return;
    }
    if (rg.timestampFinished) {
      return;
    }
    if (rg.statusPerCoin[coinIndex] !== RefreshCoinStatus.Pending) {
      return;
    }
    rg.statusPerCoin[coinIndex] = RefreshCoinStatus.Failed;
    const refreshSession = await tx.getRefreshSession(
      ctx.refreshGroupId,
      coinIndex,
    );
    if (!refreshSession) {
      throw Error("db invariant failed: missing refresh session in database");
    }
    refreshSession.lastError = errDetails;
    await destroyRefreshSession(ctx.wex, tx, rg, refreshSession);
    await tx.upsertRefreshSession(refreshSession);
    await h.update(rg, "reveal-error");
  });
}

export async function processRefreshGroup(
  wex: WalletExecutionContext,
  refreshGroupId: string,
): Promise<TaskRunResult> {
  if (!wex.ws.networkAvailable) {
    return TaskRunResult.networkRequired();
  }

  logger.trace(`processing refresh group ${refreshGroupId}`);

  const refreshGroup = await wex.runWalletDbTx(async (tx) =>
    tx.getRefreshGroup(refreshGroupId),
  );
  if (!refreshGroup) {
    return TaskRunResult.finished();
  }

  switch (refreshGroup.operationStatus) {
    case RefreshOperationStatus.Pending:
      break;
    case RefreshOperationStatus.PendingRedenominate:
      return redenominateRefresh(wex, refreshGroupId);
    default:
      return TaskRunResult.finished();
  }

  if (refreshGroup.timestampFinished) {
    return TaskRunResult.finished();
  }

  if (
    wex.ws.config.testing.devModeActive &&
    wex.ws.devExperimentState.blockRefreshes
  ) {
    throw Error("refresh blocked");
  }

  // If any redenomination is pending, first make sure the
  // info about exchanges is recent enough.
  {
    let shouldReloadExchanges = false;
    for (let i = 0; i < refreshGroup.statusPerCoin.length; i++) {
      if (
        refreshGroup.statusPerCoin[i] === RefreshCoinStatus.PendingRedenominate
      ) {
        shouldReloadExchanges = true;
      }
    }

    if (shouldReloadExchanges && refreshGroup.infoPerExchange != null) {
      for (const e of Object.keys(refreshGroup.infoPerExchange)) {
        // FIXME: Maybe have some "soft" force update
        // so we don't do this too often?
        await fetchFreshExchange(wex, e, {
          forceUpdate: true,
        });
        await updateWithdrawalDenomsForExchange(wex, e);
      }
    }
  }

  logger.trace(
    `processing refresh sessions for ${refreshGroup.oldCoinPubs.length} old coins`,
  );
  let errors: TalerErrorDetail[] = [];

  // Process refresh sessions in sequence.
  // In the future, we could parallelize request, in particular when multiple
  // exchanges are involved.
  // But we need to make sure that we write results to DB with high priority,
  // otherwise we run into problems with very large refresh groups, where we'd first
  // do many many network requests before even going to the DB.

  for (let i = 0; i < refreshGroup.oldCoinPubs.length; i++) {
    try {
      await processRefreshSession(wex, refreshGroupId, i);
    } catch (x) {
      if (wex.cancellationToken.isCancelled) {
        return TaskRunResult.cancelled();
      }
      if (x instanceof CryptoApiStoppedError) {
        logger.trace(
          "crypto API stopped while processing refresh group, probably the wallet is currently shutting down.",
        );
        return TaskRunResult.cancelled();
      }
      const err = getErrorDetailFromException(x);
      logger.warn(`exception in refresh session: ${j2s(err)}`);
      errors.push(err);
    }
  }

  const ctx = new RefreshTransactionContext(wex, refreshGroupId);

  // We've processed all refresh session and can now update the
  // status of the whole refresh group.

  const didTransition: boolean = await wex.runWalletDbTx(async (tx) => {
    const [rg, h] = await ctx.getRecordHandle(tx);
    if (!rg) {
      return false;
    }
    switch (rg.operationStatus) {
      case RefreshOperationStatus.Pending:
        break;
      default:
        return false;
    }
    const allFinal = fnutil.all(
      rg.statusPerCoin,
      (x) => x === RefreshCoinStatus.Finished || x === RefreshCoinStatus.Failed,
    );
    const anyFailed = fnutil.any(
      rg.statusPerCoin,
      (x) => x === RefreshCoinStatus.Failed,
    );
    if (allFinal) {
      if (anyFailed) {
        rg.timestampFinished = timestampPreciseToDb(
          TalerPreciseTimestamp.now(),
        );
        rg.operationStatus = RefreshOperationStatus.Failed;
      } else {
        rg.timestampFinished = timestampPreciseToDb(
          TalerPreciseTimestamp.now(),
        );
        rg.operationStatus = RefreshOperationStatus.Finished;
      }
      await makeCoinsVisible(wex, tx, ctx.transactionId);
      await h.update(rg, "refresh-done");
      return true;
    }
    return false;
  });

  if (didTransition) {
    return TaskRunResult.progress();
  }

  if (errors.length > 0) {
    return {
      type: TaskRunResultType.Error,
      errorDetail: makeErrorDetail(
        TalerErrorCode.WALLET_REFRESH_GROUP_INCOMPLETE,
        {
          numErrors: errors.length,
          errors: errors.slice(0, 5),
        },
      ),
    };
  }

  return TaskRunResult.backoff();
}

async function processRefreshSession(
  wex: WalletExecutionContext,
  refreshGroupId: string,
  coinIndex: number,
): Promise<void> {
  logger.trace(
    `processing refresh session for coin ${coinIndex} of group ${refreshGroupId}`,
  );
  let { refreshGroup, refreshSession } = await wex.runWalletDbTx(async (tx) => {
    const rg = await tx.getRefreshGroup(refreshGroupId);
    let rs = await tx.getRefreshSession(refreshGroupId, coinIndex);

    if (
      rg != null &&
      rg.statusPerCoin[coinIndex] === RefreshCoinStatus.PendingRedenominate
    ) {
      if (rs != null) {
        await destroyRefreshSession(wex, tx, rg, rs);
      }
      await tx.deleteRefreshSession(refreshGroupId, coinIndex);
      // Set the status before initializing the session, as the
      // initialization marks the coin as finished when the remaining
      // amount is too small to be refreshed at all.
      rg.statusPerCoin[coinIndex] = RefreshCoinStatus.Pending;
      await initRefreshSession(wex, tx, rg, coinIndex);
      await tx.upsertRefreshGroup(rg);
      // The old session has been replaced, don't act on it anymore.
      rs = await tx.getRefreshSession(refreshGroupId, coinIndex);
    }

    return {
      refreshGroup: rg,
      refreshSession: rs,
    };
  });
  if (!refreshGroup) {
    return;
  }
  if (refreshGroup.statusPerCoin[coinIndex] === RefreshCoinStatus.Finished) {
    return;
  }
  if (!refreshSession) {
    // No refresh session for that coin.
    return;
  }
  if (refreshSession.norevealIndex === undefined) {
    const melted = await refreshMelt(wex, refreshGroupId, coinIndex);
    if (!melted) {
      // The melt didn't happen.  The reason for it has already been
      // recorded in the database, so there's nothing to report here.
      return;
    }
  }
  await refreshReveal(wex, refreshGroupId, coinIndex);
}

export interface RefreshOutputInfo {
  outputPerCoin: AmountJson[];
  perExchangeInfo: Record<string, WalletRefreshGroupPerExchangeInfo>;
}

interface LoadedRefreshCoin {
  request: CoinRefreshRequest;
  coin: WalletCoin;
  denom: DenominationInfo;
}

async function loadRefreshCoins(
  wex: WalletExecutionContext,
  tx: WalletDbTransaction,
  requests: CoinRefreshRequest[],
): Promise<LoadedRefreshCoin[]> {
  const coins = await tx.getCoinsByPubs(requests.map((x) => x.coinPub));
  const coinsByPub = new Map(coins.map((coin) => [coin.coinPub, coin]));
  const denoms = await getDenomInfos(wex, tx, coins);
  return requests.map((request) => {
    const coin = coinsByPub.get(request.coinPub);
    checkDbInvariant(!!coin, "coin must be in database");
    const denom = denoms.get(denomRefKey(coin));
    checkDbInvariant(
      !!denom,
      "denomination for existing coin must be in database",
    );
    return { request, coin, denom };
  });
}

async function calculateRefreshOutputFromLoaded(
  wex: WalletExecutionContext,
  tx: WalletDbTransaction,
  loadedCoins: LoadedRefreshCoin[],
): Promise<RefreshOutputInfo> {
  const estimatedOutputPerCoin: AmountJson[] = [];
  const infoPerExchange: Record<string, WalletRefreshGroupPerExchangeInfo> = {};
  const refreshAmounts = loadedCoins.map(({ request }) =>
    Amounts.parseOrThrow(request.amount),
  );
  const costs = await getTotalRefreshCosts(
    wex,
    tx,
    loadedCoins.map(({ denom }, i) => ({
      refreshedDenom: denom,
      amountLeft: refreshAmounts[i],
    })),
  );

  for (let i = 0; i < loadedCoins.length; i++) {
    const { request, coin } = loadedCoins[i];
    const refreshAmount = request.amount;
    const cost = costs[i];
    const output = Amounts.sub(refreshAmount, cost).amount;
    let exchInfo = infoPerExchange[coin.exchangeBaseUrl];
    if (!exchInfo) {
      infoPerExchange[coin.exchangeBaseUrl] = exchInfo = {
        outputEffective: Amounts.stringify(Amounts.zeroOfAmount(cost)),
      };
    }
    exchInfo.outputEffective = Amounts.stringify(
      Amounts.add(exchInfo.outputEffective, output).amount,
    );
    estimatedOutputPerCoin.push(output);
  }

  return {
    outputPerCoin: estimatedOutputPerCoin,
    perExchangeInfo: infoPerExchange,
  };
}

export async function calculateRefreshOutput(
  wex: WalletExecutionContext,
  tx: WalletDbTransaction,
  _currency: string,
  oldCoinPubs: CoinRefreshRequest[],
): Promise<RefreshOutputInfo> {
  const loadedCoins = await loadRefreshCoins(wex, tx, oldCoinPubs);
  return calculateRefreshOutputFromLoaded(wex, tx, loadedCoins);
}

async function applyRefreshToOldCoins(
  tx: WalletDbTransaction,
  loadedCoins: LoadedRefreshCoin[],
  refreshGroupId: string,
): Promise<void> {
  const availabilities = await tx.getCoinAvailabilitiesByRefs(
    loadedCoins.map((x) => x.coin),
  );
  const availabilitiesByRef = new Map(
    availabilities.map((availability) => [
      coinAvailabilityRefKey(availability),
      availability,
    ]),
  );
  const histories = await tx.getCoinHistoriesByPubs(
    loadedCoins.map((x) => x.coin.coinPub),
  );
  const historiesByPub = new Map(
    histories.map((history) => [history.coinPub, history]),
  );
  const changedAvailabilities = new Map<string, WalletCoinAvailability>();
  const changedHistories = new Map<string, WalletCoinHistory>();
  const changedCoins = new Map<string, WalletCoin>();
  for (const { request, coin } of loadedCoins) {
    switch (coin.status) {
      case CoinStatus.Dormant:
        break;
      case CoinStatus.Fresh: {
        coin.status = CoinStatus.Dormant;
        const coinAv = availabilitiesByRef.get(coinAvailabilityRefKey(coin));
        checkDbInvariant(
          !!coinAv,
          `no denom info for ${coin.denomPubHash} age ${coin.maxAge}`,
        );
        checkDbInvariant(
          coinAv.freshCoinCount > 0,
          `no fresh coins for ${coin.denomPubHash}`,
        );
        coinAv.freshCoinCount--;
        if (coin.visible) {
          // Clamped rather than thrown: the visible count is a display
          // figure, and refusing to spend a coin over it would be worse
          // than showing a stale number.  The fresh count above is the
          // one that guards spendability, and that does throw.
          if (!coinAv.visibleCoinCount) {
            logger.error(
              `visible coin count underflow for denom ${coin.denomPubHash}` +
                ` age ${coin.maxAge} at ${coinAv.exchangeBaseUrl}:` +
                ` a visible coin was spent but the count is` +
                ` ${coinAv.visibleCoinCount}`,
            );
          } else {
            coinAv.visibleCoinCount--;
          }
        }
        changedAvailabilities.set(coinAvailabilityRefKey(coinAv), coinAv);
        break;
      }
      case CoinStatus.FreshSuspended: {
        // For suspended coins, we don't have to adjust coin
        // availability, as they are not counted as available.
        coin.status = CoinStatus.Dormant;
        break;
      }
      case CoinStatus.DenomLoss:
        break;
      default:
        assertUnreachable(coin.status);
    }
    let histEntry: WalletCoinHistory | undefined = historiesByPub.get(
      coin.coinPub,
    );
    if (!histEntry) {
      histEntry = {
        coinPub: coin.coinPub,
        history: [],
      };
    }
    histEntry.history.push({
      type: "refresh",
      transactionId: constructTransactionIdentifier({
        tag: TransactionType.Refresh,
        refreshGroupId,
      }),
      amount: Amounts.stringify(request.amount),
    });
    historiesByPub.set(coin.coinPub, histEntry);
    changedHistories.set(coin.coinPub, histEntry);
    changedCoins.set(coin.coinPub, coin);
  }
  for (const availability of changedAvailabilities.values()) {
    await tx.upsertCoinAvailability(availability);
  }
  for (const history of changedHistories.values()) {
    await tx.upsertCoinHistory(history);
  }
  for (const coin of changedCoins.values()) {
    await tx.upsertCoin(coin);
  }
}

export interface CreateRefreshGroupResult {
  refreshGroupId: string;
}

/**
 * Create a refresh group for a list of coins.
 *
 * Refreshes the remaining amount on the coin, effectively capturing the remaining
 * value in the refresh group.
 *
 * The caller must also ensure that the coins that should be refreshed exist
 * in the current database transaction.
 */
export async function createRefreshGroup(
  wex: WalletExecutionContext,
  tx: WalletDbTransaction,
  currency: string,
  oldCoinPubs: CoinRefreshRequest[],
  refreshReason: RefreshReason,
  originatingTransactionId: string | undefined,
): Promise<CreateRefreshGroupResult> {
  const exchanges: Set<string> = new Set();
  const loadedCoins = await loadRefreshCoins(wex, tx, oldCoinPubs);
  for (const { coin } of loadedCoins) {
    exchanges.add(coin.exchangeBaseUrl);
  }

  for (const exch of exchanges) {
    await requireExchangeReadyTx(wex, tx, exch);
  }

  const refreshGroupId = encodeCrock(getRandomBytes(32));

  const outInfo = await calculateRefreshOutputFromLoaded(wex, tx, loadedCoins);

  const estimatedOutputPerCoin = outInfo.outputPerCoin;

  if (logger.shouldLogTrace()) {
    logger.trace(
      `creating refresh group, inputs ${j2s(oldCoinPubs.map((x) => x.amount))}`,
    );
  }

  await applyRefreshToOldCoins(tx, loadedCoins, refreshGroupId);

  const refundRequests: { [n: number]: ExchangeRefundRequest } = {};

  for (let i = 0; i < oldCoinPubs.length; i++) {
    const req = oldCoinPubs[i].refundRequest;
    if (req != null) {
      refundRequests[i] = req;
    }
  }

  const refreshGroup: WalletRefreshGroup = {
    operationStatus: RefreshOperationStatus.Pending,
    currency,
    timestampFinished: undefined,
    statusPerCoin: oldCoinPubs.map(() => RefreshCoinStatus.Pending),
    oldCoinPubs: oldCoinPubs.map((x) => x.coinPub),
    originatingTransactionId,
    reason: refreshReason,
    refreshGroupId,
    inputPerCoin: oldCoinPubs.map((x) => x.amount),
    expectedOutputPerCoin: estimatedOutputPerCoin.map((x) =>
      Amounts.stringify(x),
    ),
    refundRequests,
    infoPerExchange: outInfo.perExchangeInfo,
    timestampCreated: timestampPreciseToDb(TalerPreciseTimestamp.now()),
  };

  if (oldCoinPubs.length == 0) {
    logger.warn("created refresh group with zero coins");
    refreshGroup.timestampFinished = timestampPreciseToDb(
      TalerPreciseTimestamp.now(),
    );
    refreshGroup.operationStatus = RefreshOperationStatus.Finished;
  }

  for (let i = 0; i < oldCoinPubs.length; i++) {
    await initRefreshSession(wex, tx, refreshGroup, i);
  }

  const ctx = new RefreshTransactionContext(wex, refreshGroupId);

  await tx.upsertRefreshGroup(refreshGroup);
  await ctx.updateTransactionMeta(tx);

  const newTxState = computeRefreshTransactionState(refreshGroup);

  logger.trace(`created refresh group ${refreshGroupId}`);

  // Shepherd the task.
  // If the current transaction fails to commit the refresh
  // group to the DB, the shepherd will give up.
  wex.taskScheduler.startShepherdTask(ctx.taskId);

  tx.notify({
    type: NotificationType.TransactionStateTransition,
    causeHint: "create-refresh-group",
    transactionId: ctx.transactionId,
    oldTxState: {
      major: TransactionMajorState.None,
    },
    newTxState,
    newStId: 0,
  });

  return {
    refreshGroupId,
  };
}

async function redenominateRefresh(
  wex: WalletExecutionContext,
  refreshGroupId: string,
): Promise<TaskRunResult> {
  const ctx = new RefreshTransactionContext(wex, refreshGroupId);
  logger.info(`re-denominating refresh group ${refreshGroupId}`);

  const exchanges = await wex.runWalletDbTx(async (tx) => {
    const [rg, _] = await ctx.getRecordHandle(tx);
    if (rg?.infoPerExchange) {
      return Object.keys(rg.infoPerExchange);
    }
    return [];
  });

  for (const e of exchanges) {
    await fetchFreshExchange(wex, e);
    await updateWithdrawalDenomsForExchange(wex, e);
  }

  return await wex.runWalletDbTx(async (tx) => {
    const [refreshGroup, h] = await ctx.getRecordHandle(tx);
    if (!refreshGroup) {
      return TaskRunResult.finished();
    }
    const inputs: CoinRefreshRequest[] = [];
    for (let i = 0; i < refreshGroup.oldCoinPubs.length; i++) {
      inputs.push({
        amount: refreshGroup.inputPerCoin[i],
        coinPub: refreshGroup.oldCoinPubs[i],
      });
    }

    const outInfo = await calculateRefreshOutput(
      wex,
      tx,
      refreshGroup.currency,
      inputs,
    );

    logger.info(`input per coin: ${j2s(refreshGroup.inputPerCoin)}`);
    logger.info(
      `old output per coin: ${j2s(refreshGroup.expectedOutputPerCoin)}`,
    );
    logger.info(`new out info: ${j2s(outInfo)}`);

    for (let i = 0; i < refreshGroup.oldCoinPubs.length; i++) {
      if (
        Amounts.isZero(refreshGroup.expectedOutputPerCoin[i]) &&
        Amounts.isNonZero(outInfo.outputPerCoin[i]) &&
        refreshGroup.statusPerCoin[i] === RefreshCoinStatus.Finished
      ) {
        refreshGroup.expectedOutputPerCoin[i] = Amounts.stringify(
          outInfo.outputPerCoin[i],
        );
        refreshGroup.statusPerCoin[i] = RefreshCoinStatus.Pending;
        await initRefreshSession(wex, tx, refreshGroup, i);
      }
    }

    logger.info(
      `new output per coin: ${j2s(refreshGroup.expectedOutputPerCoin)}`,
    );

    refreshGroup.operationStatus = RefreshOperationStatus.Pending;
    await h.update(refreshGroup, "redenominate");
    return TaskRunResult.progress();
  });
}

export function computeRefreshTransactionState(
  rg: WalletRefreshGroup,
): TransactionState {
  switch (rg.operationStatus) {
    case RefreshOperationStatus.Finished:
      return {
        major: TransactionMajorState.Done,
      };
    case RefreshOperationStatus.Failed:
      return {
        major: TransactionMajorState.Failed,
      };
    case RefreshOperationStatus.PendingRedenominate:
      // Internal state, not shown to UI.
      return {
        major: TransactionMajorState.Pending,
        working: true,
      };
    case RefreshOperationStatus.Pending:
      return {
        major: TransactionMajorState.Pending,
        working: true,
      };
    case RefreshOperationStatus.SuspendedRedenominate:
      // Internal state, not shown to UI.
      return {
        major: TransactionMajorState.Suspended,
      };
    case RefreshOperationStatus.Suspended:
      return {
        major: TransactionMajorState.Suspended,
      };
  }
}

export function computeRefreshTransactionActions(
  rg: WalletRefreshGroup,
): TransactionAction[] {
  switch (rg.operationStatus) {
    case RefreshOperationStatus.Finished:
      return [TransactionAction.Delete];
    case RefreshOperationStatus.Failed:
      return [TransactionAction.Delete];
    case RefreshOperationStatus.PendingRedenominate:
    case RefreshOperationStatus.Pending:
      return [TransactionAction.Retry, TransactionAction.Suspend];
    case RefreshOperationStatus.SuspendedRedenominate:
    case RefreshOperationStatus.Suspended:
      return [TransactionAction.Resume];
  }
}

export function getRefreshesForTransaction(
  wex: WalletExecutionContext,
  transactionId: string,
): Promise<string[]> {
  return wex.runWalletDbTx(async (tx) => {
    const groups =
      await tx.getRefreshGroupsByOriginatingTransaction(transactionId);
    return groups.map((x) =>
      constructTransactionIdentifier({
        tag: TransactionType.Refresh,
        refreshGroupId: x.refreshGroupId,
      }),
    );
  });
}

export async function forceRefresh(
  wex: WalletExecutionContext,
  req: ForceRefreshRequest,
): Promise<ForceRefreshResponse> {
  if (req.refreshCoinSpecs.length == 0) {
    throw Error("refusing to create empty refresh group");
  }
  const res = await wex.runWalletDbTx(async (tx) => {
    const coinPubs: CoinRefreshRequest[] = [];
    const coins = await tx.getCoinsByPubs(
      req.refreshCoinSpecs.map((spec) => spec.coinPub),
    );
    const coinsByPub = new Map(coins.map((coin) => [coin.coinPub, coin]));
    const denoms = await getDenomInfos(wex, tx, coins);
    for (const c of req.refreshCoinSpecs) {
      const coin = coinsByPub.get(c.coinPub);
      if (!coin) {
        throw Error(`coin (pubkey ${c}) not found`);
      }
      const denom = denoms.get(denomRefKey(coin));
      checkDbInvariant(!!denom, `no denom hash: ${coin.denomPubHash}`);
      coinPubs.push({
        coinPub: c.coinPub,
        amount: c.amount ?? denom.value,
      });
    }
    return await createRefreshGroup(
      wex,
      tx,
      Amounts.currencyOf(coinPubs[0].amount),
      coinPubs,
      RefreshReason.Manual,
      undefined,
    );
  });

  return {
    refreshGroupId: res.refreshGroupId,
  };
}

/**
 * Wait until a refresh operation is final.
 */
export async function waitRefreshFinal(
  wex: WalletExecutionContext,
  refreshGroupId: string,
): Promise<void> {
  const ctx = new RefreshTransactionContext(wex, refreshGroupId);
  wex.taskScheduler.startShepherdTask(ctx.taskId);

  await genericWaitForState(wex, {
    async checkState(): Promise<boolean> {
      // Check if refresh is final
      const res = await ctx.wex.runWalletDbTx(async (tx) => {
        return {
          rg: await tx.getRefreshGroup(ctx.refreshGroupId),
        };
      });
      const { rg } = res;
      if (!rg) {
        // Must've been deleted, we consider that final.
        return true;
      }
      switch (rg.operationStatus) {
        case RefreshOperationStatus.Failed:
        case RefreshOperationStatus.Finished:
          // Transaction is final
          return true;
        case RefreshOperationStatus.Pending:
        case RefreshOperationStatus.Suspended:
          break;
      }
      return false;
    },
    filterNotification(notif): boolean {
      return (
        notif.type === NotificationType.TransactionStateTransition &&
        notif.transactionId === ctx.transactionId
      );
    },
  });
}
