const codecForCsRPair = (): Codec<[string, string]> => ({
  decode(x, c) {
    const values = codecForList(codecForString()).decode(x, c);
    if (values.length !== 2) {
      throw new DecodingError(
        `expected Clause-Schnorr R-pair at ${renderContext(c)}`,
      );
    }
    return [values[0], values[1]];
  },
});

