/**
 * Operations built on top of {@link WalletDbTransaction} rather than on any
 * one backend.
 *
 * Scope resolution is business logic that happens to read from the database:
 * it is identical for every backend, so it lives here once instead of being
 * reimplemented (and drifting) in each.
 */

import { assertUnreachable, ScopeInfo, ScopeType } from "@gnu-taler/taler-util";
import { WalletDbTransaction } from "./transaction.js";
import { PurchaseStatus, WalletPurchase } from "./records.js";
import { auditorProvidesVerifiedTrust } from "../auditorTrust.js";

/**
 * Does the exchange fall within the given scope?
 */
export async function checkExchangeInScopeGeneric(
  tx: WalletDbTransaction,
  exchangeBaseUrl: string,
  scope: ScopeInfo,
  denomPubHash?: string,
): Promise<boolean> {
  switch (scope.type) {
    case ScopeType.Exchange:
      return scope.url === exchangeBaseUrl;
    case ScopeType.Global: {
      const details = await tx.getExchangeDetails(exchangeBaseUrl);
      if (!details) {
        return false;
      }
      const gr = await tx.getGlobalCurrencyExchange(
        details.currency,
        exchangeBaseUrl,
        details.masterPublicKey,
      );
      return gr != null;
    }
    case ScopeType.Auditor: {
      const details = await tx.getExchangeDetails(exchangeBaseUrl);
      if (!details || details.currency !== scope.currency) {
        return false;
      }
      for (const auditor of details.auditors) {
        if (
          !auditorProvidesVerifiedTrust(auditor, {
            auditorBaseUrl: scope.url,
            denomPubHash,
          })
        ) {
          continue;
        }
        if (
          await tx.getGlobalCurrencyAuditor(
            details.currency,
            auditor.auditor_url,
            auditor.auditor_pub,
          )
        ) {
          return true;
        }
      }
      return false;
    }
    case ScopeType.ExchangeLegacyKeys:
      // Asked of an exchange entry, which always stands for the key set it
      // currently uses.  That is by definition not a superseded one, so the
      // answer is no even when the URLs agree.
      return false;
    default:
      assertUnreachable(scope);
  }
}

/**
 * Compute the scope (global, auditor or exchange) an exchange belongs to.
 */
export async function getExchangeScopeInfoGeneric(
  tx: WalletDbTransaction,
  exchangeBaseUrl: string,
  currency: string,
  denomPubHash?: string,
): Promise<ScopeInfo> {
  const det = await tx.getExchangeDetails(exchangeBaseUrl);
  if (!det) {
    return {
      type: ScopeType.Exchange,
      currency,
      url: exchangeBaseUrl,
    };
  }
  const globalExchangeRec = await tx.getGlobalCurrencyExchange(
    det.currency,
    det.exchangeBaseUrl,
    det.masterPublicKey,
  );
  if (globalExchangeRec) {
    return {
      currency: det.currency,
      type: ScopeType.Global,
    };
  }
  for (const aud of denomPubHash == null ? [] : det.auditors) {
    if (
      !auditorProvidesVerifiedTrust(aud, {
        denomPubHash,
      })
    ) {
      continue;
    }
    const globalAuditorRec = await tx.getGlobalCurrencyAuditor(
      det.currency,
      aud.auditor_url,
      aud.auditor_pub,
    );
    if (globalAuditorRec) {
      return {
        currency: det.currency,
        type: ScopeType.Auditor,
        url: aud.auditor_url,
      };
    }
  }
  return {
    type: ScopeType.Exchange,
    currency: det.currency,
    url: det.exchangeBaseUrl,
  };
}

/**
 * DAL methods after which the wallet's in-memory caches are stale.
 *
 * The caches hold exchange summaries, denomination info and refresh costs,
 * all derived from these entities.  Listing the methods here rather than
 * having each backend decide keeps the two implementations from drifting: a
 * cache that is dropped on one backend and not the other is a bug that only
 * shows up as stale data much later.
 *
 * Mutations only.  Reading a denomination cannot invalidate anything derived
 * from denominations.
 */
export const CACHE_INVALIDATING_METHODS: ReadonlySet<string> = new Set([
  "upsertExchange",
  "deleteExchange",
  "upsertExchangeDetails",
  "deleteExchangeDetails",
  "upsertDenomination",
  "deleteDenomination",
  // Cascades to denominations, so it invalidates the same caches.
  "deleteDenominationFamily",
  "upsertGlobalCurrencyExchange",
  "deleteGlobalCurrencyExchange",
  "upsertGlobalCurrencyAuditor",
  "deleteGlobalCurrencyAuditor",
]);

/**
 * Wrap a transaction so that calls to cache-invalidating methods are noticed.
 *
 * `flag.dirty` is set as a side effect; the caller drops the caches after the
 * transaction commits, never before, so a rolled-back transaction does not
 * invalidate anything.
 */
export function watchForCacheInvalidation<T extends WalletDbTransaction>(
  tx: T,
  flag: { dirty: boolean; terminalPaymentIds?: Set<string> },
): T {
  return new Proxy(tx, {
    get(target, prop, receiver) {
      const value = Reflect.get(target, prop, receiver);
      if (prop === "upsertPurchase" && typeof value === "function") {
        return (...args: unknown[]) => {
          const purchase = args[0] as WalletPurchase;
          if (purchase.purchaseStatus >= PurchaseStatus.Done) {
            flag.terminalPaymentIds?.add(purchase.proposalId);
          }
          return value.apply(target, args);
        };
      }
      if (prop === "deletePurchase" && typeof value === "function") {
        return (...args: unknown[]) => {
          flag.terminalPaymentIds?.add(args[0] as string);
          return value.apply(target, args);
        };
      }
      if (typeof prop === "string" && CACHE_INVALIDATING_METHODS.has(prop)) {
        if (typeof value === "function") {
          return (...args: unknown[]) => {
            flag.dirty = true;
            return value.apply(target, args);
          };
        }
      }
      if (typeof value === "function") {
        return value.bind(target);
      }
      return value;
    },
  });
}
