import {
  NotificationType,
  TimerAPI,
  TimerHandle,
  WalletNotification,
  performanceNow,
} from "@gnu-taler/taler-util";

export const DATABASE_MAINTENANCE_NOTIFICATION_INTERVAL_MS = 500;
const DATABASE_MAINTENANCE_NOTIFICATION_INTERVAL_NS =
  BigInt(DATABASE_MAINTENANCE_NOTIFICATION_INTERVAL_MS) * 1_000_000n;

interface MaintenanceNotificationState {
  lastDelivered: bigint;
  pending?: WalletNotification;
  timer?: TimerHandle;
}

/**
 * Keep database-maintenance progress useful without flooding native hosts.
 *
 * Maintenance runs while the database gate is held.  In the Qt host the
 * sqlite calls underneath it are synchronous, so the ordinary asynchronous
 * notification delivery can be starved until all queued callbacks arrive as
 * one burst.  The first and terminal events are therefore delivered directly;
 * intermediate state is coalesced behind a single timer per operation.
 */
export class MaintenanceNotificationThrottler {
  private readonly states = new Map<string, MaintenanceNotificationState>();

  constructor(
    private readonly timer: TimerAPI,
    private readonly deliver: (notification: WalletNotification) => void,
    private readonly now: () => bigint = performanceNow,
  ) {}

  offer(
    notification: Extract<
      WalletNotification,
      { type: NotificationType.DatabaseMaintenanceProgress }
    >,
  ): void {
    const key = notification.operation;
    const terminal =
      notification.phase === "complete" || notification.phase === "failed";
    const previous = this.states.get(key);
    if (terminal) {
      previous?.timer?.clear();
      this.states.delete(key);
      this.deliver(notification);
      return;
    }

    const now = this.now();
    if (
      !previous ||
      now - previous.lastDelivered >=
        DATABASE_MAINTENANCE_NOTIFICATION_INTERVAL_NS
    ) {
      previous?.timer?.clear();
      this.states.set(key, { lastDelivered: now });
      this.deliver(notification);
      return;
    }

    previous.pending = notification;
    if (previous.timer) return;
    const remainingNs =
      DATABASE_MAINTENANCE_NOTIFICATION_INTERVAL_NS -
      (now - previous.lastDelivered);
    const remainingMs = Math.max(1, Math.ceil(Number(remainingNs) / 1_000_000));
    previous.timer = this.timer.after(remainingMs, () => {
      previous.timer = undefined;
      const pending = previous.pending;
      previous.pending = undefined;
      if (!pending) return;
      previous.lastDelivered = this.now();
      this.deliver(pending);
    });
  }

  stop(): void {
    for (const state of this.states.values()) state.timer?.clear();
    this.states.clear();
  }
}
