/**
 * Backend runners shared by the conformance suite and the benchmark.
 *
 * Both must exercise the two implementations through exactly the same setup,
 * or a measured difference could be an artefact of how the database was
 * opened rather than of the implementation.
 */

import { BridgeIDBFactory, createSqliteBackend } from "@gnu-taler/idb-bridge";
import { createNodeHelperSqlite3Impl } from "@gnu-taler/idb-bridge/node-helper-sqlite3-impl";

import { DbTxRunner } from "./conformance.js";
import { IdbWalletDbHandle } from "../indexeddb/handle.js";
import { openNativeSqliteWalletDb } from "../sqlite/database.js";
import { SqliteWalletDbHandle } from "../sqlite/handle.js";

/**
 * Runner for the IndexedDB implementation, on an in-memory sqlite-backed
 * BridgeIDB.  Each runner gets a fresh database so cases cannot leak into
 * each other.
 */
export async function makeIdbRunner(
  filename = ":memory:",
): Promise<DbTxRunner> {
  const sqlite3Impl = await createNodeHelperSqlite3Impl({
    enableTracing: false,
  });
  const backend = await createSqliteBackend(sqlite3Impl, {
    filename,
  });
  backend.enableTracing = false;
  backend.trackStats = true;
  BridgeIDBFactory.enableTracing = false;
  const idbFactory = new BridgeIDBFactory(backend);
  const handle = new IdbWalletDbHandle(
    idbFactory as any,
    () => backend.accessStats,
  );
  await handle.ensureOpen();
  return handle;
}

/**
 * Runner for the native sqlite3 implementation.
 *
 * Both runners return the handle the wallet itself uses, so the suite
 * exercises transaction serialisation, the shared statement cache,
 * checkpoint-on-idle and post-commit notification delivery rather than a
 * reimplementation of them.
 */
export async function makeSqliteRunner(
  filename = ":memory:",
): Promise<DbTxRunner> {
  const sqlite3Impl = await createNodeHelperSqlite3Impl({
    enableTracing: false,
  });
  const ndb = await openNativeSqliteWalletDb(await sqlite3Impl.open(filename));
  return new SqliteWalletDbHandle(ndb);
}

export const runnerFactories: Array<
  (filename?: string) => Promise<DbTxRunner>
> = [makeIdbRunner, makeSqliteRunner];
