import type { FollowOptions, RedirectableRequest } from "follow-redirects";
import followRedirects from "follow-redirects";
import type { ClientRequest, IncomingMessage } from "node:http";
import { RequestOptions } from "node:http";
import * as net from "node:net";
import { deflateSync, gzipSync } from "node:zlib";
import {
  HeadersImpl,
  HttpRawLib,
  HttpRawRequestOptions,
  HttpRawResponse,
  RequestCancelledError,
  RequestTimeoutError,
} from "./http-common.js";
import { Logger } from "./logging.js";
import { typedArrayConcat } from "./taler-crypto.js";
import { URL } from "./url.js";

const http = followRedirects.http;
const https = followRedirects.https;

// Work around a node v20.0.0, v20.1.0, and v20.2.0 bug. The issue was fixed
// in v20.3.0.
// https://github.com/nodejs/node/issues/47822#issuecomment-1564708870
// The issues is not fixed on 22 and 24.
// More info https://bugs.gnunet.org/view.php?id=9942
if (
  // check for `node` in case we want to use this in "exotic" JS envs
  process.versions.node &&
  process.versions.node.match(/(20|22|24)\./)
) {
  //@ts-ignore
  net.setDefaultAutoSelectFamily(false);
}

const logger = new Logger("http-impl.node.ts");

const textDecoder = new TextDecoder();
let SHOW_CURL_HTTP_REQUEST = false;
export function setPrintHttpRequestAsCurl(b: boolean) {
  SHOW_CURL_HTTP_REQUEST = b;
}

function printAsCurl(url: string, opt: HttpRawRequestOptions): void {
  const payload =
    !opt.body || opt.body.byteLength === 0
      ? undefined
      : textDecoder.decode(opt.body);
  const headers = Object.entries(opt.headers).reduce((prev, [key, value]) => {
    return `${prev} -H "${key}: ${value}"`;
  }, "");
  function ifUndefined<T>(arg: string, v: undefined | T): string {
    if (v === undefined) return "";
    return arg + " '" + String(v) + "'";
  }
  console.log(
    `TALER_API_DEBUG: curl -X ${opt.method} "${url}" ${headers} ${ifUndefined(
      "-d",
      payload,
    )}`,
  );
}

/**
 * Implementation of the raw HTTP layer for node, using follow-redirects on
 * top of node's own http/https modules.
 */
export const rawLib: HttpRawLib = {
  async compress(alg, body) {
    return alg === "gzip"
      ? new Uint8Array(gzipSync(body))
      : new Uint8Array(deflateSync(body));
  },

  fetch(url: string, opt: HttpRawRequestOptions): Promise<HttpRawResponse> {
    const parsedUrl = new URL(url);

    // The shared HTTP layer has already completely encoded (and possibly
    // compressed) the body.  Tell Node its final length so that it does not
    // select chunked transfer encoding when req.write() is called below.
    // Keep an explicitly supplied Content-Length, including one with unusual
    // casing, for callers that need to control the header themselves.
    const headers = { ...opt.headers };
    const hasContentLength = Object.keys(headers).some(
      (name) => name.toLowerCase() === "content-length",
    );
    if (opt.body !== undefined && !hasContentLength) {
      headers["Content-Length"] = String(opt.body.byteLength);
    }

    let path = parsedUrl.pathname;
    if (parsedUrl.search != null) {
      path += parsedUrl.search;
    }

    const options: RequestOptions & FollowOptions<RequestOptions> = {
      protocol: parsedUrl.protocol,
      port: parsedUrl.port,
      host: parsedUrl.hostname,
      method: opt.method,
      path,
      headers,
      timeout: opt.timeoutMs,
      followRedirects: opt.redirect !== "manual",
    };

    const chunks: Uint8Array[] = [];

    if (SHOW_CURL_HTTP_REQUEST) {
      printAsCurl(parsedUrl.href, { ...opt, headers });
    }

    let timeoutHandle: NodeJS.Timeout | undefined = undefined;
    let cancelCancelledHandler: (() => void) | undefined = undefined;

    const doCleanup = () => {
      if (timeoutHandle != null) {
        clearTimeout(timeoutHandle);
        timeoutHandle = undefined;
      }
      if (cancelCancelledHandler) {
        cancelCancelledHandler();
        cancelCancelledHandler = undefined;
      }
    };

    return new Promise<HttpRawResponse>((resolve, reject) => {
      const handler = (res: IncomingMessage) => {
        res.on("data", (d) => {
          chunks.push(d);
        });
        res.on("end", () => {
          const headers: HeadersImpl = new HeadersImpl();
          for (const [k, v] of Object.entries(res.headers)) {
            if (!v) {
              continue;
            }
            if (typeof v === "string") {
              headers.set(k, v);
            } else {
              headers.set(k, v.join(", "));
            }
          }
          const data = typedArrayConcat(chunks);
          doCleanup();
          if (SHOW_CURL_HTTP_REQUEST) {
            console.log(
              `TALER_API_DEBUG: ${res.statusCode} ${textDecoder.decode(data)}`,
            );
          }
          resolve({
            status: res.statusCode || 0,
            headers,
            async bytes() {
              return data;
            },
          });
        });
        res.on("error", (e) => {
          const code = "code" in e ? e.code : "unknown";
          doCleanup();
          reject(new Error(`Error in HTTP response handler: ${code}`));
        });
      };

      let req: RedirectableRequest<ClientRequest, IncomingMessage>;
      if (options.protocol === "http:") {
        req = http.request(options, handler);
      } else if (options.protocol === "https:") {
        req = https.request(options, handler);
      } else {
        throw new Error(`unsupported protocol ${options.protocol}`);
      }

      if (opt.timeoutMs != null) {
        timeoutHandle = setTimeout(() => {
          logger.info(`request to ${url} timed out`);
          timeoutHandle = undefined;
          req.destroy();
          doCleanup();
          reject(new RequestTimeoutError());
        }, opt.timeoutMs);
      }

      if (opt.cancellationToken) {
        cancelCancelledHandler = opt.cancellationToken.onCancelled(() => {
          req.destroy();
          doCleanup();
          reject(new RequestCancelledError());
        });
      }

      req.on("error", (e: Error) => {
        const code = "code" in e ? e.code : "unknown";
        doCleanup();
        reject(new Error(`Error in HTTP request: ${code}`));
      });

      if (opt.body) {
        req.write(opt.body);
      }
      req.end();
    });
  },
};
