/**
 * Selection of denominations for withdrawals.
 *
 * @author Florian Dold
 */

/**
 * Imports.
 */
import {
  AbsoluteTime,
  AmountJson,
  Amounts,
  DenominationInfo,
  DenomSelectionState,
  ForcedDenomSel,
  Logger,
} from "@gnu-taler/taler-util";
import {
  DenominationVerificationStatus,
  timestampAbsoluteFromDb,
} from "./db/records.js";
import { WalletDenomination } from "./db/records.js";
import { isWithdrawableDenom } from "./denominations.js";

const logger = new Logger("denomSelection.ts");

/**
 * Exception to signal that a denomination that is intended
 * to be used has not been verified yet.
 *
 * Thrown from transactions to trigger a verification
 * and re-try of the transaction.
 */
export class UnverifiedDenomError extends Error {
  constructor(
    message: string,
    public readonly denomInfo: DenominationInfo,
  ) {
    super(message);
    Object.setPrototypeOf(this, new.target.prototype);
    this.name = this.constructor.name;
  }
}

/**
 * Greedily select a list of denominations (with repetitions possible) whose
 * total withdrawal cost does not exceed the available amount.
 *
 * This is deterministic best-effort selection, not a closest-fit or
 * fee-optimal algorithm.  It consumes as many coins as possible in the
 * caller-supplied descending denomination order before considering the next
 * denomination.  Thus a smaller-denomination combination can sometimes yield
 * more coin value or leave a smaller remainder.  Exact bounded optimization
 * is deliberately deferred until its resource policy is specified.
 *
 * Throws if any of the denoms is invalid.
 *
 * @param amountAvailable available withdrawal amount
 * @param denoms list of denominations that can be used,
 *        must be validated to be withdrawable and sorted
 *        by descending denom value
 * @param opts extra options
 */
export function selectWithdrawalDenominations(
  amountAvailable: AmountJson,
  denoms: WalletDenomination[],
  opts: { limitCoins?: number } = {},
): DenomSelectionState {
  if (denoms.length == 0) {
    // This is a protocol violation.
    // We won't proceed.
    throw Error("no withdrawal denominations available");
  }

  let remaining = Amounts.copy(amountAvailable);

  const selectedDenoms: {
    count: number;
    denomPubHash: string;
  }[] = [];

  let totalCoinValue = Amounts.zeroOfCurrency(amountAvailable.currency);
  let totalWithdrawCost = Amounts.zeroOfCurrency(amountAvailable.currency);
  let earliestDepositExpiration: AbsoluteTime | undefined;
  let hasDenomWithAgeRestriction = false;

  // Precondition check
  for (let i = 0; i < denoms.length; i++) {
    const d = denoms[i];
    if (d.verificationStatus === DenominationVerificationStatus.Unverified) {
      throw new UnverifiedDenomError(
        "unverified denomination",
        WalletDenomination.toDenomInfo(d),
      );
    }
    if (!isWithdrawableDenom(d)) {
      throw Error(
        "non-withdrawable denom passed to selectWithdrawalDenominations",
      );
    }
    if (
      i < denoms.length - 1 &&
      Amounts.cmp(denoms[i].value, denoms[i + 1].value) < 0
    ) {
      throw Error("denoms must be sorted by descending value");
    }
  }

  if (logger.shouldLogTrace()) {
    logger.trace(
      `selecting withdrawal denoms for ${Amounts.stringify(amountAvailable)}`,
    );
  }

  let totalCount = 0;

  for (const d of denoms) {
    const cost = Amounts.add(d.value, d.fees.feeWithdraw).amount;
    const res = Amounts.divmod(remaining, cost);
    let count = res.quotient;
    if (opts.limitCoins != null && totalCount + count > opts.limitCoins) {
      count = opts.limitCoins - totalCount;
    }
    remaining = Amounts.sub(remaining, Amounts.mult(cost, count).amount).amount;
    if (count > 0) {
      totalCount += count;
      totalCoinValue = Amounts.add(
        totalCoinValue,
        Amounts.mult(d.value, count).amount,
      ).amount;
      totalWithdrawCost = Amounts.add(
        totalWithdrawCost,
        Amounts.mult(cost, count).amount,
      ).amount;
      selectedDenoms.push({
        count,
        denomPubHash: d.denomPubHash,
      });
      hasDenomWithAgeRestriction =
        hasDenomWithAgeRestriction || d.denomPub.age_mask > 0;
      const expireDeposit = timestampAbsoluteFromDb(d.stampExpireDeposit);
      if (!earliestDepositExpiration) {
        earliestDepositExpiration = expireDeposit;
      } else {
        earliestDepositExpiration = AbsoluteTime.min(
          expireDeposit,
          earliestDepositExpiration,
        );
      }
    }

    if (logger.shouldLogTrace()) {
      logger.trace(
        `denom_pub_hash=${
          d.denomPubHash
        }, count=${count}, val=${Amounts.stringify(
          d.value,
        )}, wdfee=${Amounts.stringify(d.fees.feeWithdraw)}`,
      );
    }

    if (Amounts.isZero(remaining)) {
      break;
    }
  }

  if (logger.shouldLogTrace()) {
    logger.trace("(end of denom selection)");
  }

  earliestDepositExpiration ??= AbsoluteTime.never();

  return {
    selectedDenoms,
    totalCoinValue: Amounts.stringify(totalCoinValue),
    totalWithdrawCost: Amounts.stringify(totalWithdrawCost),
    hasDenomWithAgeRestriction,
  };
}

export function selectForcedWithdrawalDenominations(
  amountAvailable: AmountJson,
  denoms: WalletDenomination[],
  forcedDenomSel: ForcedDenomSel,
): DenomSelectionState {
  const selectedDenoms: {
    count: number;
    denomPubHash: string;
  }[] = [];

  let totalCoinValue = Amounts.zeroOfCurrency(amountAvailable.currency);
  let totalWithdrawCost = Amounts.zeroOfCurrency(amountAvailable.currency);
  let earliestDepositExpiration: AbsoluteTime | undefined;
  let hasDenomWithAgeRestriction = false;

  // Since this is a forced withdrawal (used for testing), we do *not* check
  // if the denoms are actually withdrawable.

  denoms.sort((d1, d2) => Amounts.cmp(d2.value, d1.value));

  for (const fds of forcedDenomSel.denoms) {
    const count = fds.count;
    const denom = denoms.find((x) => {
      return Amounts.cmp(x.value, fds.value) == 0;
    });
    if (!denom) {
      throw Error(
        `unable to find denom for forced selection (value ${fds.value})`,
      );
    }
    const cost = Amounts.add(denom.value, denom.fees.feeWithdraw).amount;
    totalCoinValue = Amounts.add(
      totalCoinValue,
      Amounts.mult(denom.value, count).amount,
    ).amount;
    totalWithdrawCost = Amounts.add(
      totalWithdrawCost,
      Amounts.mult(cost, count).amount,
    ).amount;
    selectedDenoms.push({
      count,
      denomPubHash: denom.denomPubHash,
    });
    hasDenomWithAgeRestriction =
      hasDenomWithAgeRestriction || denom.denomPub.age_mask > 0;
    const expireDeposit = timestampAbsoluteFromDb(denom.stampExpireDeposit);
    if (!earliestDepositExpiration) {
      earliestDepositExpiration = expireDeposit;
    } else {
      earliestDepositExpiration = AbsoluteTime.min(
        expireDeposit,
        earliestDepositExpiration,
      );
    }
  }

  earliestDepositExpiration ??= AbsoluteTime.never();

  return {
    selectedDenoms,
    totalCoinValue: Amounts.stringify(totalCoinValue),
    totalWithdrawCost: Amounts.stringify(totalWithdrawCost),
    hasDenomWithAgeRestriction,
  };
}
