import {
  ResultRow,
  Sqlite3Database,
  Sqlite3Statement,
  Sqlite3Value,
} from "@gnu-taler/idb-bridge";
import {
  decodeCrock,
  encodeCrock,
  Logger,
  WalletNotification,
} from "@gnu-taler/taler-util";
import { WalletDbTransaction } from "../transaction.js";
import {
  DATA_TABLES_CONDITION,
  SchemaMigration,
  schemaMigrations,
  SQLITE_BASELINE_SCHEMA,
  SQLITE_SCHEMA_VERSION,
} from "./schema.js";
import { SqliteAccessStats, SqliteWalletTransaction } from "./transaction.js";

const logger = new Logger("db/sqlite/database.ts");

/**
 * Transaction control for the helper protocol.
 *
 * These must go through prepared statements.  `exec` commits implicitly, which
 * has two consequences worth stating plainly:
 *
 * 1. A BEGIN issued with `exec` reports success and then does nothing.  The
 *    following COMMIT fails with "no transaction is active" and the writes
 *    have already been committed individually — indistinguishable from a
 *    working transaction until something needs to roll back, which is exactly
 *    when a wallet can least afford it.
 * 2. An `exec` *inside* an explicit transaction ends that transaction.  So
 *    `exec` must not be used for anything that has to be atomic with
 *    surrounding work; use prepared statements throughout instead.
 */
export class SqliteTxControl {
  private constructor(
    private beginStmt: Sqlite3Statement,
    private commitStmt: Sqlite3Statement,
    private rollbackStmt: Sqlite3Statement,
  ) {}

  static async create(db: Sqlite3Database): Promise<SqliteTxControl> {
    return new SqliteTxControl(
      await db.prepare("BEGIN"),
      await db.prepare("COMMIT"),
      await db.prepare("ROLLBACK"),
    );
  }

  async begin(): Promise<void> {
    await this.beginStmt.run({});
  }
  async commit(): Promise<void> {
    await this.commitStmt.run({});
  }
  async rollback(): Promise<void> {
    await this.rollbackStmt.run({});
  }
}

/**
 * How long to wait for a lock held by another connection before giving up.
 *
 * Without this a concurrent writer surfaces as an immediate SQLITE_BUSY.
 * Within one process TxQueue serialises transactions so it cannot happen, but
 * nothing stops a second process -- a CLI command run against a wallet the
 * shepherd has open, say -- from touching the same file.  Five seconds is long
 * enough to outlast any transaction this code issues and short enough that a
 * genuine deadlock still surfaces as an error rather than a hang.
 */
const SQLITE_BUSY_TIMEOUT_MS = 5000;

/** Current time in the microseconds the schema's INTEGER timestamps use. */
function nowMicros(): number {
  return Date.now() * 1000;
}

/**
 * Check the migration list before running any of it.
 *
 * A duplicate or out-of-order version does not fail on its own: migrations are
 * skipped by looking up the version in schema_migrations, so a reused version
 * silently never runs, and the database ends up missing a change while
 * claiming to have applied it.  Better to refuse to open.
 */
function validateSchemaMigrations(migrations: SchemaMigration[]): void {
  let prev = 1; // the baseline occupies version 1
  for (const mig of migrations) {
    if (mig.version <= prev) {
      throw Error(
        `schema migration ${mig.version} (${mig.name}) is not greater than` +
          ` the preceding version ${prev}: versions must strictly increase` +
          ` and may not be reused`,
      );
    }
    prev = mig.version;
  }
}

function validateAppliedSchemaMigrations(
  applied: ResultRow[],
  extraMigrations: SchemaMigration[],
): void {
  const expected = new Map<number, string>([[1, "baseline"]]);
  for (const migration of [...schemaMigrations, ...extraMigrations]) {
    const previous = expected.get(migration.version);
    if (previous !== undefined && previous !== migration.name) {
      throw Error(
        `schema migration ${migration.version} has conflicting names` +
          ` (${previous} and ${migration.name})`,
      );
    }
    expected.set(migration.version, migration.name);
  }
  for (const row of applied) {
    const version = Number(row.version);
    const name = String(row.name);
    const expectedName = expected.get(version);
    if (expectedName === undefined) {
      throw Error(`database records unknown schema migration ${version}`);
    }
    if (name !== expectedName) {
      throw Error(
        `database schema migration ${version} is named ${name},` +
          ` expected ${expectedName}`,
      );
    }
  }
}

/**
 * Open the database and bring its schema up to date.
 *
 * Each migration runs in its own transaction with its schema_migrations row
 * written inside that transaction, so a crash part-way through cannot leave a
 * half-applied migration recorded as done.
 *
 * The migration list is a parameter so that tests can exercise the path with
 * a synthetic migration.  Until a real one exists this is the only thing that
 * runs it at all.
 */
export async function initSqliteWalletDb(
  db: Sqlite3Database,
  migrations: SchemaMigration[] = schemaMigrations,
): Promise<void> {
  validateSchemaMigrations(migrations);
  await db.exec("PRAGMA foreign_keys = ON");
  await db.exec(`PRAGMA busy_timeout = ${SQLITE_BUSY_TIMEOUT_MS}`);
  const versionRows = await (await db.prepare("PRAGMA user_version")).getAll();
  const databaseVersion = Number(versionRows[0]?.user_version ?? 0);
  if (databaseVersion > SQLITE_SCHEMA_VERSION) {
    throw Error(
      `database schema version ${databaseVersion} is newer than this wallet` +
        ` (version ${SQLITE_SCHEMA_VERSION})`,
    );
  }
  const migrationTable = await (
    await db.prepare(
      "SELECT 1 AS present FROM sqlite_master" +
        " WHERE type = 'table' AND name = 'schema_migrations'",
    )
  ).getAll();
  if (migrationTable.length !== 0) {
    const recorded = await (
      await db.prepare("SELECT version, name FROM schema_migrations")
    ).getAll();
    validateAppliedSchemaMigrations(recorded, migrations);
  }
  // WAL: readers do not block the writer, and a commit appends to the log
  // instead of fsyncing the whole database.
  //
  // The cost is that a WAL database is three files (db, -wal, -shm), so
  // copying just the database file is not a snapshot.  That matters because
  // callers do treat the wallet DB as one file they can copy.  Rather than
  // give up WAL, {@link runNativeSqliteWalletTx} checkpoints with TRUNCATE
  // whenever the transaction queue drains: under load the WAL accumulates
  // normally, and the moment the wallet goes idle the main file is complete
  // again and the -wal is empty.  Idle is also the only moment at which an
  // external copy could be coherent at all, so this makes single-file copies
  // valid exactly when they can be.
  //
  // It also means a killed process leaves an empty -wal behind, so restoring
  // a database file over it cannot replay stale frames from the old one.
  await db.exec("PRAGMA journal_mode = WAL");
  // NORMAL is safe against process crashes in WAL mode; only a power loss
  // can cost the most recent commits, and never corruption.
  await db.exec("PRAGMA synchronous = NORMAL");

  const txc = await SqliteTxControl.create(db);

  // The baseline is exec'd outside a transaction: every statement is
  // CREATE ... IF NOT EXISTS, so re-running it is a no-op, and exec would end
  // an enclosing transaction anyway.
  await db.exec(SQLITE_BASELINE_SCHEMA);
  const baselineStmt = await db.prepare(
    "INSERT OR IGNORE INTO schema_migrations (version, name, applied_at)" +
      " VALUES ($version, $name, $applied_at)",
  );
  await baselineStmt.run({
    version: 1,
    name: "baseline",
    applied_at: nowMicros(),
  });

  const applied = await (
    await db.prepare("SELECT version, name FROM schema_migrations")
  ).getAll();
  validateAppliedSchemaMigrations(applied, migrations);
  const have = new Set(applied.map((r) => Number(r.version)));

  for (const mig of migrations) {
    if (have.has(mig.version)) {
      continue;
    }
    logger.info(`applying schema migration ${mig.version} (${mig.name})`);
    await txc.begin();
    try {
      for (const sql of mig.statements) {
        await (await db.prepare(sql)).run({});
      }
      const stmt = await db.prepare(
        "INSERT INTO schema_migrations (version, name, applied_at)" +
          " VALUES ($version, $name, $applied_at)",
      );
      await stmt.run({
        version: mig.version,
        name: mig.name,
        applied_at: nowMicros(),
      });
      await txc.commit();
    } catch (e) {
      await txc.rollback();
      throw e;
    }
  }
  await db.exec(`PRAGMA user_version = ${SQLITE_SCHEMA_VERSION}`);
}

/**
 * A native sqlite wallet database, ready to run transactions against.
 *
 * Holds the connection together with its prepared transaction-control
 * statements, because those must be prepared once per connection and must not
 * go through `exec` (see {@link SqliteTxControl}).
 */
export interface NativeSqliteWalletDb {
  db: Sqlite3Database;
  txc: SqliteTxControl;
  /** Cumulative across transactions on this connection. */
  stats: SqliteAccessStats;
  /** Shared across transactions; see SqliteWalletTransaction.stmtCache. */
  stmtCache: Map<string, Sqlite3Statement>;
  /**
   * Serialises transactions on this connection.
   *
   * One sqlite connection can only have one transaction open at a time, so
   * two overlapping callers produce "cannot start a transaction within a
   * transaction".  IndexedDB does not have this problem because its
   * scheduler queues transactions; this queue is the equivalent, and keeps
   * the DAL contract ("runWalletDbTx runs f in its own transaction") true
   * for concurrent callers.
   */
  lock: TxQueue;
}

/**
 * A minimal FIFO async mutex.
 *
 * Deliberately not reentrant: a transaction opened while another is already
 * held on the same connection is a bug in the caller, and blocking makes it
 * visible instead of silently merging two transactions into one — where a
 * rollback of the inner would discard the outer's writes.
 */
export class TxQueue {
  private tail: Promise<void> = Promise.resolve();

  /**
   * Transactions queued but not finished, including the running one.
   *
   * Used to detect the moment the queue drains, which is when the database
   * can be checkpointed without stalling anybody.
   */
  private outstanding = 0;

  /**
   * True when the caller is the only transaction in the queue.
   *
   * Checked from inside a running transaction, which is still counted in
   * `outstanding` at that point -- the decrement happens in this class's
   * finally block, after the transaction body returns.  So "nobody else is
   * waiting" is 1, not 0.
   */
  get noOtherWaiting(): boolean {
    return this.outstanding <= 1;
  }

  async run<T>(f: () => Promise<T>): Promise<T> {
    this.outstanding++;
    const prev = this.tail;
    let release: () => void;
    this.tail = new Promise<void>((resolve) => {
      release = resolve;
    });
    await prev;
    try {
      return await f();
    } finally {
      this.outstanding--;
      release!();
    }
  }
}

/**
 * Open a native sqlite wallet database and bring its schema up to date.
 */
export async function openNativeSqliteWalletDb(
  db: Sqlite3Database,
): Promise<NativeSqliteWalletDb> {
  await initSqliteWalletDb(db);
  const txc = await SqliteTxControl.create(db);
  return {
    db,
    txc,
    lock: new TxQueue(),
    stmtCache: new Map(),
    stats: { rowsRead: 0 },
  };
}

/**
 * Run f in one native sqlite transaction.
 *
 * Notifications and commit hooks are released only after COMMIT succeeds: a
 * transaction that rolls back must not have told anyone it happened.
 */
export async function runNativeSqliteWalletTx<T>(
  ndb: NativeSqliteWalletDb,
  notifyFn: (n: WalletNotification) => void,
  f: (tx: SqliteWalletTransaction) => Promise<T>,
): Promise<T> {
  return await ndb.lock.run(() =>
    runNativeSqliteWalletTxLocked(ndb, notifyFn, f),
  );
}

async function runNativeSqliteWalletTxLocked<T>(
  ndb: NativeSqliteWalletDb,
  notifyFn: (n: WalletNotification) => void,
  f: (tx: SqliteWalletTransaction) => Promise<T>,
): Promise<T> {
  const tx = new SqliteWalletTransaction(ndb.db, ndb.stmtCache, ndb.stats);
  await ndb.txc.begin();
  let res: T;
  try {
    res = await f(tx);
  } catch (e) {
    // Best-effort rollback: if ROLLBACK itself fails, the original error is
    // the interesting one and must not be masked by it.
    try {
      await ndb.txc.rollback();
    } catch (rollbackErr) {
      logger.warn(`rollback failed: ${rollbackErr}`);
    }
    throw e;
  }
  try {
    await ndb.txc.commit();
  } catch (e) {
    // A COMMIT can fail on its own: deferred foreign keys are checked
    // here, not when the row was written.  Leaving it at that keeps the
    // connection *inside* the transaction, and every transaction after it
    // fails with "cannot start a transaction within a transaction" -- one
    // bad write and the wallet's database is unusable until it restarts.
    try {
      await ndb.txc.rollback();
    } catch (rollbackErr) {
      logger.warn(`rollback after a failed commit failed: ${rollbackErr}`);
    }
    throw e;
  }
  await checkpointIfIdle(ndb);
  // Same order as the IndexedDB backend: the handlers run before a client
  // can observe the notification.
  for (const h of tx.afterCommitHandlers) {
    h();
  }
  for (const notif of tx.pendingNotifications) {
    notifyFn(notif);
  }
  return res;
}

/**
 * Fold the write-ahead log back into the database file, if nothing else is
 * queued.
 *
 * This is what keeps the database file self-contained between operations, so
 * that copying it is a valid snapshot (see the WAL note in
 * {@link initSqliteWalletDb}).  Skipped whenever another transaction is
 * waiting: under load the log is allowed to grow, which is the point of WAL.
 *
 * TRUNCATE rather than PASSIVE so the -wal ends up zero-length rather than
 * merely folded in; a leftover non-empty -wal next to a restored database
 * file is the failure mode this exists to prevent.
 *
 * Best-effort: a failed checkpoint costs a stale snapshot, not correctness,
 * and must not fail the transaction that already committed.
 */
async function checkpointIfIdle(ndb: NativeSqliteWalletDb): Promise<void> {
  if (!ndb.lock.noOtherWaiting) {
    return;
  }
  try {
    await ndb.db.exec("PRAGMA wal_checkpoint(TRUNCATE)");
  } catch (e) {
    logger.warn(`WAL checkpoint failed: ${e}`);
  }
}

/**
 * Delete every row from the native wallet database.
 *
 * The schema itself is kept, including schema_migrations: this clears data,
 * it does not reset the database to "never initialised".
 */
export async function clearNativeSqliteWalletDb(
  ndb: NativeSqliteWalletDb,
): Promise<void> {
  await ndb.lock.run(async () => {
    await ndb.txc.begin();
    try {
      await clearNativeSqliteWalletDbInTransaction(ndb);
      await ndb.txc.commit();
    } catch (e) {
      try {
        await ndb.txc.rollback();
      } catch (rollbackErr) {
        logger.warn(`rollback failed: ${rollbackErr}`);
      }
      throw e;
    }
  });
}

/** Delete native wallet rows inside a transaction already owned by caller. */
export async function clearNativeSqliteWalletDbInTransaction(
  ndb: NativeSqliteWalletDb,
): Promise<void> {
  const rows = await (
    await ndb.db.prepare(
      `SELECT name FROM sqlite_master WHERE ${DATA_TABLES_CONDITION}`,
    )
  ).getAll();
  for (const row of rows) {
    // Table names come from sqlite_master, not from user input.
    await (await ndb.db.prepare(`DELETE FROM "${row.name}"`)).run({});
  }
}

/**
 * Names of the tables holding wallet data, in a stable order.
 *
 * See DATA_TABLES_CONDITION for what is left out and why.
 */
async function listDataTables(ndb: NativeSqliteWalletDb): Promise<string[]> {
  const rows = await (
    await ndb.db.prepare(
      `SELECT name FROM sqlite_master WHERE ${DATA_TABLES_CONDITION}` +
        ` ORDER BY name`,
    )
  ).getAll();
  return rows.map((r) => r.name as string);
}

/**
 * A dump of every row in the native wallet database.
 *
 * Deliberately a plain row dump rather than a file copy so that it can be
 * represented as JSON, like an IndexedDB export.
 */
export interface NativeSqliteDbDump {
  schemaVersion: number;
  tables: Record<string, Record<string, DumpValue>[]>;
}

/**
 * A BLOB column in a dump.
 *
 * Tagged rather than raw bytes because the dump must be JSON-compatible;
 * typed arrays otherwise lose their type when serialized.
 */
export interface DumpBlob {
  $blob: string;
}

export type DumpValue = string | number | null | DumpBlob;

function isDumpBlob(v: unknown): v is DumpBlob {
  return (
    typeof v === "object" && v !== null && typeof (v as any).$blob === "string"
  );
}

export async function exportNativeSqliteDb(
  ndb: NativeSqliteWalletDb,
): Promise<NativeSqliteDbDump> {
  return await ndb.lock.run(async () => {
    const tables = await listDataTables(ndb);
    const out: NativeSqliteDbDump = {
      schemaVersion: SQLITE_SCHEMA_VERSION,
      tables: {},
    };
    for (const table of tables) {
      const rows = await (
        await ndb.db.prepare(`SELECT * FROM "${table}"`)
      ).getAll();
      out.tables[table] = rows.map((row) => {
        const clean: Record<string, DumpValue> = {};
        for (const [k, v] of Object.entries(row)) {
          if (v instanceof Uint8Array) {
            clean[k] = { $blob: encodeCrock(v) };
          } else if (typeof v === "bigint") {
            // The helper can return INTEGER columns as bigint, which JSON
            // cannot represent.  Every integer in this schema (timestamps in
            // microseconds, row ids, statuses) is inside the safe range.
            clean[k] = Number(v);
          } else {
            clean[k] = v;
          }
        }
        return clean;
      });
    }
    return out;
  });
}

export async function importNativeSqliteDb(
  ndb: NativeSqliteWalletDb,
  dump: NativeSqliteDbDump,
  finalize: (tx: WalletDbTransaction) => Promise<void>,
  notifyFn: (n: WalletNotification) => void,
): Promise<void> {
  if (dump.schemaVersion !== SQLITE_SCHEMA_VERSION) {
    throw Error(
      `cannot import a native wallet DB dump of schema version` +
        ` ${dump.schemaVersion} into version ${SQLITE_SCHEMA_VERSION}`,
    );
  }
  await ndb.lock.run(async () => {
    const tables = await listDataTables(ndb);
    await runNativeSqliteWalletTxLocked(ndb, notifyFn, async (tx) => {
      // Clear and refill in one transaction: a partial import would leave
      // the wallet with a mix of two databases.
      for (const table of tables) {
        await (await ndb.db.prepare(`DELETE FROM "${table}"`)).run({});
      }
      for (const table of tables) {
        const rows = dump.tables[table];
        if (!rows || rows.length === 0) {
          continue;
        }
        for (const row of rows) {
          const cols = Object.keys(row);
          const params: Record<string, Sqlite3Value> = {};
          for (const c of cols) {
            const v = row[c];
            params[c] = isDumpBlob(v) ? decodeCrock(v.$blob) : v;
          }
          const colList = cols.map((c) => `"${c}"`).join(", ");
          const valList = cols.map((c) => `$${c}`).join(", ");
          await (
            await ndb.db.prepare(
              `INSERT INTO "${table}" (${colList}) VALUES (${valList})`,
            )
          ).run(params);
        }
      }
      // Derived wallet state is part of the restore.  Running this before the
      // same COMMIT means an error cannot expose imported records with stale
      // or absent materialized transactions.
      await finalize(tx);
    });
  });
}
