/**
 * Get exchange details from the database.
 */
async function getExchangeRecordsInternal(
  tx: WalletDbTransaction,
  exchangeBaseUrl: string,
  knownExchange?: WalletExchangeEntry,
): Promise<WalletExchangeDetails | undefined> {
  const r = knownExchange ?? (await tx.getExchange(exchangeBaseUrl));
  if (!r) {
    logger.warn(`no exchange found for ${exchangeBaseUrl}`);
    return;
  }
  const dp = r.detailsPointer;
  if (!dp) {
    switch (r.updateStatus) {
      case ExchangeEntryDbUpdateStatus.Ready:
      case ExchangeEntryDbUpdateStatus.ReadyUpdate:
      case ExchangeEntryDbUpdateStatus.OutdatedUpdate:
        logger.error(
          `Database invariant violated: no exchange details in wallet database for ${exchangeBaseUrl}.`,
        );
        break;
      case ExchangeEntryDbUpdateStatus.Initial:
      case ExchangeEntryDbUpdateStatus.InitialUpdate:
      case ExchangeEntryDbUpdateStatus.Suspended:
      case ExchangeEntryDbUpdateStatus.UnavailableUpdate:
        // In these states, not having exchange details in the wallet DB
        // is expected.
        break;
      default:
        assertUnreachable(r.updateStatus);
    }
    return;
  }
  const { currency, masterPublicKey } = dp;
  const details = await tx.getExchangeDetailsByPointer(
    r.baseUrl,
    currency,
    masterPublicKey,
  );
  if (!details) {
    logger.warn(
      `no exchange details with pointer ${j2s(dp)} for ${exchangeBaseUrl}`,
    );
  }
  return details;
}

/**
 * Base URL to talk to for an exchange master public key.
 *
 * A master public key can map to more than one details row while a base-URL
 * migration is in progress, so the choice is made explicit rather than left to
 * whichever row the index happens to yield first: the row that its own
 * exchange entry currently points at wins, then one whose currency matches,
 * then the lowest base URL so that the answer is at least stable.
 */
export async function getExchangeBaseUrlForMasterPub(
  tx: WalletDbTransaction,
  masterPub: string,
  options: { currency?: string } = {},
): Promise<string | undefined> {
  const candidates = await tx.listExchangeDetailsByMasterPub(masterPub);
  if (candidates.length === 0) {
    return undefined;
  }
  if (candidates.length === 1) {
    return candidates[0].exchangeBaseUrl;
  }
  for (const det of candidates) {
    const exch = await tx.getExchange(det.exchangeBaseUrl);
    if (
      exch?.detailsPointer?.masterPublicKey === masterPub &&
      exch.detailsPointer.currency === det.currency
    ) {
      return det.exchangeBaseUrl;
    }
  }
  const byCurrency = options.currency
    ? candidates.filter((d) => d.currency === options.currency)
    : candidates;
  const pool = byCurrency.length > 0 ? byCurrency : candidates;
  return pool.map((d) => d.exchangeBaseUrl).reduce((a, b) => (a < b ? a : b));
}

/**
 * Like {@link getExchangeBaseUrlForMasterPub}, for callers that cannot carry
 * on without an answer.
 *
 * Failing loudly matters here: a coin that silently resolves to nothing drops
 * out of balances and scopes with no trace, which looks like the funds are
 * gone rather than like a lookup failed.
 */
export async function getExchangeBaseUrlForMasterPubOrThrow(
  tx: WalletDbTransaction,
  masterPub: string,
  options: { currency?: string } = {},
): Promise<string> {
  const url = await getExchangeBaseUrlForMasterPub(tx, masterPub, options);
  if (url == null) {
    throw TalerError.fromDetail(
      TalerErrorCode.WALLET_EXCHANGE_ENTRY_NOT_FOUND,
      { masterPub },
      "no exchange entry for the master public key that signed this denomination",
    );
  }
  return url;
}

/**
 * Every denomination the wallet has for an exchange, across all of its key
 * sets.
 *
 * Denominations are stored under the key that signed them, so "all
 * denominations at this URL" is the union over the key sets the URL has
 * served.  Only callers that really mean every key set want this -- purging
 * an entry, or judging a response against what is already stored.  Anything
 * about what can be withdrawn or cherry-picked wants the accepted key set
 * alone and should call getDenominationsByMasterPub directly.
 */
export async function getAllDenominationsForExchange(
  tx: WalletDbTransaction,
  exchangeBaseUrl: string,
): Promise<WalletDenomination[]> {
  const details = await tx.listExchangeDetailsByBaseUrl(exchangeBaseUrl);
  const seen = new Set<string>();
  const out: WalletDenomination[] = [];
  for (const det of details) {
    if (seen.has(det.masterPublicKey)) {
      continue;
    }
    seen.add(det.masterPublicKey);
    out.push(...(await tx.getDenominationsByMasterPub(det.masterPublicKey)));
  }
  return out;
}

export async function getScopeForAllCoins(
  tx: WalletDbTransaction,
  coinPubs: string[],
): Promise<ScopeInfo[]> {
  const scopes: ScopeInfo[] = [];
  const scopeSet = new Set<string>();
  const coins = await tx.getCoinsByPubs(coinPubs);
  const coinsByPub = new Map(coins.map((coin) => [coin.coinPub, coin]));
  const denoms = await tx.getDenominationsByRefs(coins);
  const denomsByRef = new Map(denoms.map((d) => [denomRefKey(d), d]));
  const exchangeBaseUrls = [...new Set(coins.map((c) => c.exchangeBaseUrl))];
  const detailsByUrl = new Map<string, WalletExchangeDetails | undefined>();
  for (const url of exchangeBaseUrls) {
    detailsByUrl.set(url, await getExchangeRecordsInternal(tx, url));
  }
  for (const pub of coinPubs) {
    const coin = coinsByPub.get(pub);
    if (!coin) {
      logger.warn(`coin ${coinPubs} not found, unable to compute full scope`);
      continue;
    }
    const denom = denomsByRef.get(denomRefKey(coin));
    const details = detailsByUrl.get(coin.exchangeBaseUrl);
    let scope: ScopeInfo;
    if (details && coin.exchangeMasterPub !== details.masterPublicKey) {
      scope = {
        type: ScopeType.ExchangeLegacyKeys,
        currency: denom?.currency ?? details.currency,
        url: coin.exchangeBaseUrl,
        masterPub: coin.exchangeMasterPub,
      };
    } else if (details) {
      scope = await internalGetExchangeScopeInfo(
        tx,
        details,
        coin.denomPubHash,
      );
    } else {
      continue;
    }
    const scopeKey = stringifyScopeInfo(scope);
    if (!scopeSet.has(scopeKey)) {
      scopeSet.add(scopeKey);
      scopes.push(scope);
    }
  }
  return scopes;
}

/**
 * Get a list of scope infos applicable to a list of exchanges.
 */
export async function getScopeForAllExchanges(
  tx: WalletDbTransaction,
  exs: string[],
): Promise<ScopeInfo[]> {
  const scopes: ScopeInfo[] = [];
  const scSet = new Set<string>();
  for (const exchange of exs) {
    const sc = await getExchangeScopeInfoOrUndefined(tx, exchange);
    if (!sc) {
      continue;
    }
    const scStr = stringifyScopeInfo(sc);
    if (!scSet.has(scStr)) {
      scSet.add(scStr);
      scopes.push(sc);
    }
  }
  return scopes;
}

export async function getExchangeScopeInfoOrUndefined(
  tx: WalletDbTransaction,
  exchangeBaseUrl: string,
  denomPubHash?: string,
): Promise<ScopeInfo | undefined> {
  const det = await getExchangeRecordsInternal(tx, exchangeBaseUrl);
  if (!det) {
    return undefined;
  }
  return internalGetExchangeScopeInfo(tx, det, denomPubHash);
}

export async function getExchangeScopeInfo(
  tx: WalletDbTransaction,
  exchangeBaseUrl: string,
  currency: string,
  denomPubHash?: string,
): Promise<ScopeInfo> {
  const det = await getExchangeRecordsInternal(tx, exchangeBaseUrl);
  if (!det) {
    return {
      type: ScopeType.Exchange,
      currency: currency,
      url: exchangeBaseUrl,
    };
  }
  return internalGetExchangeScopeInfo(tx, det, denomPubHash);
}

async function internalGetExchangeScopeInfo(
  tx: WalletDbTransaction,
  exchangeDetails: WalletExchangeDetails,
  denomPubHash?: string,
): Promise<ScopeInfo> {
  const globalExchangeRec = await tx.getGlobalCurrencyExchange(
    exchangeDetails.currency,
    exchangeDetails.exchangeBaseUrl,
    exchangeDetails.masterPublicKey,
  );
  if (globalExchangeRec) {
    return {
      currency: exchangeDetails.currency,
      type: ScopeType.Global,
    };
  } else {
    for (const aud of denomPubHash == null ? [] : exchangeDetails.auditors) {
      if (!hasVerifiedAuditorTrust([aud], { denomPubHash })) {
        continue;
      }
      const globalAuditorRec = await tx.getGlobalCurrencyAuditor(
        exchangeDetails.currency,
        aud.auditor_url,
        aud.auditor_pub,
      );
      if (globalAuditorRec) {
        return {
          currency: exchangeDetails.currency,
          type: ScopeType.Auditor,
          url: aud.auditor_url,
        };
      }
    }
  }
  return {
    currency: exchangeDetails.currency,
    type: ScopeType.Exchange,
    url: exchangeDetails.exchangeBaseUrl,
  };
}

function getKycStatusFromReserveStatus(
  status: ReserveRecordStatus,
): ExchangeWalletKycStatus {
  switch (status) {
    case ReserveRecordStatus.Done:
      return ExchangeWalletKycStatus.Done;
    // FIXME: Do we handle the suspended state?
    case ReserveRecordStatus.SuspendedLegiInit:
    case ReserveRecordStatus.PendingLegiInit:
      return ExchangeWalletKycStatus.LegiInit;
    // FIXME: Do we handle the suspended state?
    case ReserveRecordStatus.SuspendedLegi:
    case ReserveRecordStatus.PendingLegi:
      return ExchangeWalletKycStatus.Legi;
  }
}

/**
 * Return persisted provenance, with conservative defaults for legacy records.
 */
export function getExchangeEntrySource(
  r: WalletExchangeEntry,
): ExchangeEntrySource {
  if (r.source != null) {
    return r.source;
  }
  if (
    r.entryStatus === ExchangeEntryDbRecordStatus.Preset ||
    r.presetType != null ||
    r.presetCurrencyHint != null ||
    r.presetCurrencySpec != null
  ) {
    return ExchangeEntrySource.Builtin;
  }
  if (r.entryStatus === ExchangeEntryDbRecordStatus.Ephemeral) {
    return ExchangeEntrySource.Discovered;
  }
  return ExchangeEntrySource.Unknown;
}

async function makeExchangeListItem(
  wex: WalletExecutionContext,
  tx: WalletDbTransaction,
  r: WalletExchangeEntry,
  exchangeDetails: WalletExchangeDetails | undefined,
  reserveRec: WalletReserve | undefined,
  lastError: TalerErrorDetail | undefined,
): Promise<ExchangeListItem> {
  let scopeInfo: ScopeInfo | undefined = undefined;

  if (exchangeDetails) {
    scopeInfo = await internalGetExchangeScopeInfo(tx, exchangeDetails);
  }

  const currency =
    exchangeDetails?.currency ?? r.presetCurrencyHint ?? "UNKNOWN";

  scopeInfo = scopeInfo ?? {
    type: ScopeType.Exchange,
    currency,
    url: r.baseUrl,
  };

  let currencySpec = (await tx.getCurrencyInfo(scopeInfo))?.currencySpec;

  currencySpec = currencySpec ??
    r.presetCurrencySpec ?? {
      alt_unit_names: {},
      name: currency,
      num_fractional_input_digits: 2,
      num_fractional_normal_digits: 2,
      num_fractional_trailing_zero_digits: 2,
    };

  let walletKycStatus: ExchangeWalletKycStatus | undefined =
    reserveRec && reserveRec.status
      ? getKycStatusFromReserveStatus(reserveRec.status)
      : undefined;

  let noFees = r.noFees ?? false;

  if (wex.ws.devExperimentState.pretendNoFees) {
    noFees = true;
  }

  let unconfirmedKeyChange: ExchangeKeyChangeInfo | undefined = undefined;
  if (r.supersededKeySet && exchangeDetails) {
    unconfirmedKeyChange = {
      currentMasterPub: exchangeDetails.masterPublicKey,
      currentCurrency: exchangeDetails.currency,
      supersededMasterPub: r.supersededKeySet.masterPublicKey,
      supersededCurrency: r.supersededKeySet.currency,
      sharesDenominations: r.supersededKeySet.sharesDenominations,
      firstSeen: timestampPreciseFromDb(r.supersededKeySet.firstSeen),
    };
  }

  const listItem: ExchangeListItem = {
    exchangeBaseUrl: r.baseUrl,
    source: getExchangeEntrySource(r),
    masterPub: exchangeDetails?.masterPublicKey,
    ...(unconfirmedKeyChange ? { unconfirmedKeyChange } : undefined),
    noFees,
    peerPaymentsDisabled: r.peerPaymentsDisabled ?? false,
    directDepositsDisabled: r.directDepositDisabled ?? false,
    currency: exchangeDetails?.currency ?? r.presetCurrencyHint ?? "UNKNOWN",
    exchangeUpdateStatus: getExchangeUpdateStatusFromRecord(r),
    exchangeEntryStatus: getExchangeEntryStatusFromRecord(r),
    walletKycStatus,
    walletKycReservePub: reserveRec?.reservePub,
    walletKycUrl: reserveRec?.kycAccessToken
      ? new URL(`kyc-spa/${reserveRec.kycAccessToken}`, r.baseUrl).href
      : undefined,
    walletKycAccessToken: reserveRec?.kycAccessToken,
    walletKycRequestedThreshold: reserveRec?.thresholdRequested,
    tosStatus: getExchangeTosStatusFromRecord(r),
    ageRestrictionOptions: exchangeDetails?.ageMask
      ? AgeRestriction.getAgeGroupsFromMask(exchangeDetails.ageMask)
      : [],
    paytoUris: exchangeDetails?.wireInfo.accounts.map((x) => x.payto_uri) ?? [],
    bankComplianceLanguage: exchangeDetails?.bankComplianceLanguage,
    lastUpdateTimestamp: timestampOptionalPreciseFromDb(r.lastUpdate),
    lastWithdrawal: timestampOptionalPreciseFromDb(r.lastWithdrawal),
    currencySpec,
    scopeInfo,
  };
  if (lastError) {
    listItem.lastUpdateErrorInfo = {
      error: lastError,
    };
  } else {
    switch (listItem.exchangeUpdateStatus) {
      case ExchangeUpdateStatus.UnavailableUpdate:
        if (r.unavailableReason) {
          listItem.lastUpdateErrorInfo = {
            error: r.unavailableReason,
          };
        }
        break;
    }
  }
  return listItem;
}

export interface ExchangeDetails {
  currency: string;
  tinyAmount: AmountString;
  masterPublicKey: EddsaPublicKeyString;
  wireInfo: WireInfo;
  exchangeBaseUrl: string;
  auditors: WalletExchangeAuditor[];
  globalFees: ExchangeGlobalFees[];
  reserveClosingDelay: TalerProtocolDuration;
  defaultPeerPushExpiration?: TalerProtocolDuration;
  shoppingUrl?: string;
}

export async function getExchangeDetailsInTx(
  tx: WalletDbTransaction,
  exchangeBaseUrl: string,
  knownExchange?: WalletExchangeEntry,
): Promise<ExchangeDetails | undefined> {
  const det = await getExchangeRecordsInternal(
    tx,
    exchangeBaseUrl,
    knownExchange,
  );
  if (!det) {
    return undefined;
  }
  return {
    currency: det.currency,
    tinyAmount: det.tinyAmount,
    masterPublicKey: det.masterPublicKey,
    wireInfo: det.wireInfo,
    exchangeBaseUrl: det.exchangeBaseUrl,
    auditors: det.auditors,
    globalFees: det.globalFees,
    reserveClosingDelay: det.reserveClosingDelay,
    shoppingUrl: det.shoppingUrl,
    defaultPeerPushExpiration: det.defaultPeerPushExpiration,
  };
}

export async function lookupExchangeByUri(
  wex: WalletExecutionContext,
  req: GetExchangeEntryByUrlRequest,
): Promise<ExchangeListItem> {
  const res = await wex.runWalletDbTx(async (tx) => {
    const exchangeRec = await tx.getExchange(req.exchangeBaseUrl);
    if (!exchangeRec) {
      return undefined;
    }
    const exchangeDetails = await getExchangeRecordsInternal(
      tx,
      exchangeRec.baseUrl,
    );
    const opRetryRecord = await tx.getOperationRetry(
      TaskIdentifiers.forExchangeUpdate(exchangeRec),
    );
    let reserveRec: WalletReserve | undefined = undefined;
    if (exchangeRec.currentMergeReserveRowId != null) {
      reserveRec = await tx.getReserve(exchangeRec.currentMergeReserveRowId);
      checkDbInvariant(!!reserveRec, "reserve record not found");
    }
    return await makeExchangeListItem(
      wex,
      tx,
      exchangeRec,
      exchangeDetails,
      reserveRec,
      opRetryRecord?.lastError,
    );
  });
  if (!res) {
    throw TalerError.fromDetail(
      TalerErrorCode.WALLET_EXCHANGE_ENTRY_NOT_FOUND,
      {},
    );
  }
  return res;
}

/**
 * Mark the current ToS version as accepted by the user.
 */
/**
 * Confirm that a changed key set is legitimate.
 *
 * The change was adopted when it was observed; this only clears the record
 * that gates withdrawing.  Nothing about the key material is re-checked here,
 * because there is nothing to check against: the protocol has no signature
 * linking a new master key to the one it replaces, which is exactly why the
 * decision is the user's.
 */
export async function confirmExchangeKeyChange(
  wex: WalletExecutionContext,
  req: ConfirmExchangeKeyChangeRequest,
): Promise<void> {
  await wex.runWalletDbTx(async (tx) => {
    const r = await tx.getExchange(req.exchangeBaseUrl);
    if (!r) {
      throw TalerError.fromDetail(
        TalerErrorCode.WALLET_EXCHANGE_ENTRY_NOT_FOUND,
        { exchangeBaseUrl: req.exchangeBaseUrl },
        "no exchange entry for that base URL",
      );
    }
    if (!r.supersededKeySet) {
      throw TalerError.fromDetail(
        TalerErrorCode.WALLET_EXCHANGE_NO_KEY_CHANGE_PENDING,
        { exchangeBaseUrl: req.exchangeBaseUrl },
        "the exchange has no unconfirmed key change",
      );
    }
    // Guards a stale UI: the key on screen when the user decided must be the
    // one in force now, or they confirmed something else.
    if (r.detailsPointer?.masterPublicKey !== req.currentMasterPub) {
      throw TalerError.fromDetail(
        TalerErrorCode.WALLET_EXCHANGE_KEY_CHANGE_MISMATCH,
        {
          exchangeBaseUrl: req.exchangeBaseUrl,
          currentMasterPub: r.detailsPointer?.masterPublicKey,
          confirmedMasterPub: req.currentMasterPub,
        },
        "the confirmed master public key is not the one the exchange uses",
      );
    }
    const oldExchangeState = getExchangeState(r);
    delete r.supersededKeySet;
    await tx.upsertExchange(r);
    tx.notify({
      type: NotificationType.ExchangeStateTransition,
      exchangeBaseUrl: req.exchangeBaseUrl,
      causeHint: "key-change-confirmed",
      newExchangeState: getExchangeState(r),
      oldExchangeState,
    });
  });
  wex.ws.exchangeCache.clear();
  // Coin-using tasks may be sleeping on the confirmation error.  Wake them
  // now that the policy gate has been removed.
  await wex.taskScheduler.reload();
}

/**
 * Refuse to disclose an authorization over wallet coins while the exchange's
 * replacement master key is still awaiting explicit user confirmation.
 *
 * This check belongs immediately next to the network operation that carries
 * the authorization.  Coin selection performs the same policy check, but a
 * transaction can have persisted its selection before the key change was
 * observed.
 */
export async function requireExchangeCoinUseConfirmedOrThrow(
  wex: WalletExecutionContext,
  exchangeBaseUrl: string,
): Promise<void> {
  const change = await wex.runWalletDbTx(async (tx) => {
    const exchange = await tx.getExchange(exchangeBaseUrl);
    if (!exchange?.supersededKeySet) {
      return undefined;
    }
    checkDbInvariant(
      !!exchange.detailsPointer,
      "exchange with a pending key change has no current details pointer",
    );
    return {
      currentMasterPub: exchange.detailsPointer.masterPublicKey,
      supersededMasterPub: exchange.supersededKeySet.masterPublicKey,
    };
  });
  if (!change) {
    return;
  }
  throw TalerError.fromDetail(
    TalerErrorCode.WALLET_EXCHANGE_KEYS_NOT_ACCEPTED,
    {
      exchangeBaseUrl,
      currentMasterPub: change.currentMasterPub,
      supersededMasterPub: change.supersededMasterPub,
    },
    "coin use is blocked until the exchange's new master public key is confirmed",
  );
}

export async function acceptExchangeTermsOfService(
  wex: WalletExecutionContext,
  exchangeBaseUrl: string,
): Promise<void> {
  await wex.runWalletDbTx(async (tx) => {
    const exch = await tx.getExchange(exchangeBaseUrl);
    if (exch && exch.tosCurrentEtag) {
      const oldExchangeState = getExchangeState(exch);
      exch.tosAcceptedEtag = exch.tosCurrentEtag;
      exch.tosAcceptedTimestamp = timestampPreciseToDb(
        TalerPreciseTimestamp.now(),
      );
      await tx.upsertExchange(exch);
      const newExchangeState = getExchangeState(exch);
      wex.ws.exchangeCache.clear();
      tx.notify({
        type: NotificationType.ExchangeStateTransition,
        causeHint: "tos-accepted",
        exchangeBaseUrl,
        newExchangeState: newExchangeState,
        oldExchangeState: oldExchangeState,
      });
    }
  });
}

/**
 * Set the ToS status of the exchange as not accepted.
 */
export async function forgetExchangeTermsOfService(
  wex: WalletExecutionContext,
  exchangeBaseUrl: string,
): Promise<void> {
  await wex.runWalletDbTx(async (tx) => {
    const exch = await tx.getExchange(exchangeBaseUrl);
    if (!exch) {
      return;
    }
    const oldExchangeState = getExchangeState(exch);
    exch.tosAcceptedEtag = undefined;
    exch.tosAcceptedTimestamp = undefined;
    await tx.upsertExchange(exch);
    const newExchangeState = getExchangeState(exch);
    wex.ws.exchangeCache.clear();
    tx.notify({
      type: NotificationType.ExchangeStateTransition,
      exchangeBaseUrl,
      causeHint: "tos-unaccepted",
      newExchangeState: newExchangeState,
      oldExchangeState: oldExchangeState,
    });
  });
}

/**
 * Validate wire fees and wire accounts.
 *
 * Throw an exception if they are invalid.
 */
export function makeWireAccountValidationRequest(
  account: ExchangeWireAccount,
  versionCurrent: number,
  masterPublicKey: string,
) {
  return {
    masterPub: masterPublicKey,
    paytoUri: account.payto_uri,
    sig: account.master_sig,
    versionCurrent,
    conversionUrl: account.conversion_url,
    openBankingGatewayUrl: account.open_banking_gateway,
    creditRestrictions: account.credit_restrictions,
    debitRestrictions: account.debit_restrictions,
    wireTransferGatewayUrl: account.prepared_transfer_url,
  };
}

async function validateWireInfo(
  wex: WalletExecutionContext,
  versionCurrent: number,
  wireInfo: ExchangeKeysResponse,
  masterPublicKey: string,
): Promise<WireInfo> {
  for (const a of wireInfo.accounts) {
    logger.trace("validating exchange acct");
    let isValid = false;
    if (wex.ws.config.testing.insecureTrustExchange) {
      isValid = true;
    } else {
      const { valid: v } = await wex.ws.cryptoApi.isValidWireAccount(
        makeWireAccountValidationRequest(a, versionCurrent, masterPublicKey),
      );
      isValid = v;
    }
    if (!isValid) {
      throw TalerError.fromDetail(
        TalerErrorCode.WALLET_EXCHANGE_SIGNATURE_INVALID,
        {},
        `signature of exchange account ${a.payto_uri} is invalid`,
      );
    }
  }
  logger.trace("account validation done");
  const feesForType: WireFeeMap = {};
  for (const wireMethod of Object.keys(wireInfo.wire_fees)) {
    const feeList: WireFee[] = [];
    for (const x of wireInfo.wire_fees[wireMethod]) {
      const startStamp = x.start_date;
      const endStamp = x.end_date;
      const fee: WireFee = {
        closingFee: Amounts.stringify(x.closing_fee),
        endStamp,
        sig: x.sig,
        startStamp,
        wireFee: Amounts.stringify(x.wire_fee),
      };
      let isValid = false;
      if (wex.ws.config.testing.insecureTrustExchange) {
        isValid = true;
      } else {
        const { valid: v } = await wex.ws.cryptoApi.isValidWireFee({
          masterPub: masterPublicKey,
          type: wireMethod,
          wf: fee,
        });
        isValid = v;
      }
      if (!isValid) {
        throw TalerError.fromDetail(
          TalerErrorCode.WALLET_EXCHANGE_SIGNATURE_INVALID,
          {},
          `signature of the exchange's wire fee for ${wireMethod} is invalid`,
        );
      }
      feeList.push(fee);
    }
    feesForType[wireMethod] = feeList;
  }

  return {
    accounts: wireInfo.accounts,
    feesForType,
  };
}

/**
 * Validate global fees.
 *
 * Throw an exception if they are invalid.
 */
/**
 * Check the master signature of every online signing key of the exchange.
 */
async function validateSignKeys(
  wex: WalletExecutionContext,
  signKeys: ExchangeSignKeyJson[],
  masterPub: string,
): Promise<void> {
  for (const sk of signKeys) {
    logger.trace("validating exchange signing key");
    let isValid = false;
    if (wex.ws.config.testing.insecureTrustExchange) {
      isValid = true;
    } else {
      const { valid: v } = await wex.cryptoApi.isValidSignKey({
        masterPub,
        sk,
      });
      isValid = v;
    }
    if (!isValid) {
      throw TalerError.fromDetail(
        TalerErrorCode.WALLET_EXCHANGE_SIGNATURE_INVALID,
        {},
        `signature of the exchange's signing key ${sk.key} is invalid`,
      );
    }
  }
}

/**
 * Verify auditor attestations independently for every denomination.
 *
 * A bad auditor signature is not an exchange /keys failure: it merely means
 * that this auditor does not confer trust on that denomination.  The returned
 * entries contain only verified signatures and carry an internal persistence
 * marker so unverified entries from older databases fail closed.
 */
async function validateAuditorDenominations(
  wex: WalletExecutionContext,
  auditors: ExchangeAuditor[],
  denoms: DenominationInfo[],
): Promise<WalletExchangeAuditor[]> {
  const denomByHash = new Map(denoms.map((d) => [d.denomPubHash, d]));
  const result: WalletExchangeAuditor[] = [];
  for (const auditor of auditors) {
    const verifiedKeys: ExchangeAuditor["denomination_keys"] = [];
    let rejectedCount = 0;
    // Bound the number of outstanding worker RPCs.  Large /keys responses can
    // contain thousands of denominations.
    for (
      let offset = 0;
      offset < auditor.denomination_keys.length;
      offset += 70
    ) {
      const batch = auditor.denomination_keys.slice(offset, offset + 70);
      const validations = await Promise.all(
        batch.map(async (auditorDenom) => {
          const denom = denomByHash.get(auditorDenom.denom_pub_h);
          if (!denom) {
            return false;
          }
          if (wex.ws.config.testing.insecureTrustExchange) {
            return true;
          }
          try {
            const { valid } = await wex.cryptoApi.isValidAuditorDenom({
              auditorBaseUrl: auditor.auditor_url,
              auditorPub: auditor.auditor_pub,
              auditorSig: auditorDenom.auditor_sig,
              denomPubHash: denom.denomPubHash,
              masterPub: denom.exchangeMasterPub,
              stampStart: denom.stampStart,
              stampExpireWithdraw: denom.stampExpireWithdraw,
              stampExpireDeposit: denom.stampExpireDeposit,
              stampExpireLegal: denom.stampExpireLegal,
              value: Amounts.parseOrThrow(denom.value),
              feeWithdraw: Amounts.parseOrThrow(denom.feeWithdraw),
              feeDeposit: Amounts.parseOrThrow(denom.feeDeposit),
              feeRefresh: Amounts.parseOrThrow(denom.feeRefresh),
              feeRefund: Amounts.parseOrThrow(denom.feeRefund),
            });
            return valid;
          } catch {
            return false;
          }
        }),
      );
      for (let i = 0; i < batch.length; i++) {
        if (validations[i]) {
          verifiedKeys.push(batch[i]);
        } else {
          rejectedCount++;
        }
      }
    }
    if (rejectedCount > 0) {
      logger.warn(
        `ignoring ${rejectedCount} invalid auditor denomination ` +
          `signature(s) from ${auditor.auditor_url}`,
      );
    }
    if (verifiedKeys.length > 0) {
      result.push({
        ...auditor,
        denomination_keys: verifiedKeys,
        walletAuditorSignaturesVerified: true,
      });
    }
  }
  return result;
}

/** Preserve verified attestations outside a cherry-picked response. */
function mergeCherryPickedAuditors(
  current: WalletExchangeAuditor[],
  previous: WalletExchangeAuditor[],
  coveredDenomHashes: Set<string>,
): WalletExchangeAuditor[] {
  const merged = new Map<string, WalletExchangeAuditor>();
  const add = (
    auditor: WalletExchangeAuditor,
    keys: ExchangeAuditor["denomination_keys"],
  ): void => {
    if (auditor.walletAuditorSignaturesVerified !== true || keys.length === 0) {
      return;
    }
    const id = `${auditor.auditor_url}\0${auditor.auditor_pub}`;
    const existing = merged.get(id);
    if (!existing) {
      merged.set(id, {
        ...auditor,
        denomination_keys: [...keys],
        walletAuditorSignaturesVerified: true,
      });
      return;
    }
    const known = new Set(
      existing.denomination_keys.map(
        (x) => `${x.denom_pub_h}\0${x.auditor_sig}`,
      ),
    );
    for (const key of keys) {
      const id = `${key.denom_pub_h}\0${key.auditor_sig}`;
      if (!known.has(id)) {
        known.add(id);
        existing.denomination_keys.push(key);
      }
    }
  };
  for (const auditor of current) {
    add(auditor, auditor.denomination_keys);
  }
  for (const auditor of previous) {
    add(
      auditor,
      auditor.denomination_keys.filter(
        (x) => !coveredDenomHashes.has(x.denom_pub_h),
      ),
    );
  }
  return [...merged.values()];
}

async function validateGlobalFees(
  wex: WalletExecutionContext,
  fees: GlobalFees[],
  masterPub: string,
): Promise<ExchangeGlobalFees[]> {
  const egf: ExchangeGlobalFees[] = [];
  for (const gf of fees) {
    logger.trace("validating exchange global fees");
    let isValid = false;
    if (wex.ws.config.testing.insecureTrustExchange) {
      isValid = true;
    } else {
      const { valid: v } = await wex.cryptoApi.isValidGlobalFees({
        masterPub,
        gf,
      });
      isValid = v;
    }

    if (!isValid) {
      throw TalerError.fromDetail(
        TalerErrorCode.WALLET_EXCHANGE_SIGNATURE_INVALID,
        {},
        `signature of the exchange's global fees is invalid`,
      );
    }
    egf.push({
      accountFee: Amounts.stringify(gf.account_fee),
      historyFee: Amounts.stringify(gf.history_fee),
      purseFee: Amounts.stringify(gf.purse_fee),
      startDate: gf.start_date,
      endDate: gf.end_date,
      signature: gf.master_sig,
      historyTimeout: gf.history_expiration,
      purseLimit: gf.purse_account_limit,
      purseTimeout: gf.purse_timeout,
    });
  }

  return egf;
}

/**
 * Add or update exchange entry to the wallet database.
 * If it is a new entry, it is created in the
 * entry state "preset".
 *
 * Returns the notification to the caller that should be emitted
 * if the DB transaction succeeds.
 */
export async function putPresetExchangeEntry(
  tx: WalletDbTransaction,
  exchangeBaseUrl: string,
  exchangeType: string,
  currencyHint?: string,
  currencySpec?: CurrencySpecification,
): Promise<void> {
  let exchange = await tx.getExchange(exchangeBaseUrl);
  if (!exchange) {
    const r: WalletExchangeEntry = {
      entryStatus: ExchangeEntryDbRecordStatus.Preset,
      source: ExchangeEntrySource.Builtin,
      updateStatus: ExchangeEntryDbUpdateStatus.Initial,
      baseUrl: exchangeBaseUrl,
      presetType: exchangeType,
      presetCurrencySpec: currencySpec,
      presetCurrencyHint: currencyHint,
      detailsPointer: undefined,
      lastUpdate: undefined,
      lastKeysEtag: undefined,
      nextRefreshCheckStamp: timestampPreciseToDb(
        AbsoluteTime.toPreciseTimestamp(AbsoluteTime.never()),
      ),
      nextUpdateStamp: timestampPreciseToDb(
        AbsoluteTime.toPreciseTimestamp(AbsoluteTime.never()),
      ),
      tosAcceptedEtag: undefined,
      tosAcceptedTimestamp: undefined,
      tosCurrentEtag: undefined,
    };
    await tx.upsertExchange(r);
    tx.notify({
      type: NotificationType.ExchangeStateTransition,
      exchangeBaseUrl: exchangeBaseUrl,
      causeHint: "creation-preset",
      // Exchange did not exist yet
      oldExchangeState: undefined,
      newExchangeState: getExchangeState(r),
    });
  } else {
    exchange.presetCurrencySpec = currencySpec;
    exchange.presetCurrencyHint = currencyHint;
    exchange.presetType = exchangeType;
    await tx.upsertExchange(exchange);
  }
}

async function provideExchangeRecordInTx(
  ws: InternalWalletState,
  tx: WalletDbTransaction,
  baseUrl: string,
): Promise<{
  exchange: WalletExchangeEntry;
  exchangeDetails: WalletExchangeDetails | undefined;
}> {
  let exchange = await tx.getExchange(baseUrl);
  if (!exchange) {
    const r: WalletExchangeEntry = {
      entryStatus: ExchangeEntryDbRecordStatus.Ephemeral,
      source: ExchangeEntrySource.Discovered,
      updateStatus: ExchangeEntryDbUpdateStatus.InitialUpdate,
      baseUrl: baseUrl,
      detailsPointer: undefined,
      lastUpdate: undefined,
      nextUpdateStamp: timestampPreciseToDb(
        AbsoluteTime.toPreciseTimestamp(AbsoluteTime.never()),
      ),
      nextRefreshCheckStamp: timestampPreciseToDb(
        AbsoluteTime.toPreciseTimestamp(AbsoluteTime.never()),
      ),
      // The first update should always be done in a way that ignores the cache,
      // so that removing and re-adding an exchange works properly, even
      // if /keys is cached in the browser.
      cachebreakNextUpdate: true,
      lastKeysEtag: undefined,
      tosAcceptedEtag: undefined,
      tosAcceptedTimestamp: undefined,
      tosCurrentEtag: undefined,
    };
    await tx.upsertExchange(r);
    exchange = r;
    tx.notify({
      type: NotificationType.ExchangeStateTransition,
      exchangeBaseUrl: r.baseUrl,
      causeHint: "creation",
      oldExchangeState: undefined,
      newExchangeState: getExchangeState(r),
    });
  }
  const exchangeDetails = await getExchangeRecordsInternal(tx, baseUrl);
  return { exchange, exchangeDetails };
}

export type ExchangeKeysDownloadResult =
  | { type: "ok"; res: ExchangeKeysResponse }
  | { type: "version-incompatible"; exchangeProtocolVersion: string };

/**
 * Download and validate an exchange's /keys data.
 *
 * When @a lastIssueDate is given, the exchange is asked to cherry-pick, i.e.
 * to leave out the denominations that started before that timestamp.  See
 * {@link getKeysCherryPickDate} for how the caller arrives at it.
 *
 * FIXME: Use the HTTP client lib for this!
 */
async function downloadExchangeKeysInfo(
  baseUrl: string,
  http: HttpRequestLibrary,
  timeout: Duration,
  cancellationToken: CancellationToken,
  noCache: boolean,
  lastIssueDate?: number,
): Promise<ExchangeKeysDownloadResult> {
  const exchangeClient = new TalerExchangeHttpClient(baseUrl, {
    httpClient: http,
    cancelationToken: cancellationToken,
    timeout,
  });
  const resp = await exchangeClient.getKeys({ noCache, lastIssueDate });

  logger.trace("got response to /keys request");

  const exchangeKeysResponseParsed = succeedOrThrow(resp);

  if (
    !TalerExchangeHttpClient.isCompatible(exchangeKeysResponseParsed.version)
  ) {
    return {
      type: "version-incompatible",
      exchangeProtocolVersion: exchangeKeysResponseParsed.version,
    };
  }

  if (exchangeKeysResponseParsed.denominations.length === 0) {
    throw TalerError.fromDetail(
      TalerErrorCode.WALLET_EXCHANGE_DENOMINATIONS_INSUFFICIENT,
      {
        exchangeBaseUrl: baseUrl,
      },
      "exchange doesn't offer any denominations",
    );
  }

  return {
    type: "ok",
    res: exchangeKeysResponseParsed,
  };
}

type TosMetaResult =
  | { type: "not-found" }
  | { type: "ok"; etag: string | undefined };

/**
 * Download metadata about an exchange's terms of service.
 */
async function downloadTosMeta(
  wex: WalletExecutionContext,
  exchangeBaseUrl: string,
): Promise<TosMetaResult> {
  logger.trace(`downloading exchange tos metadata for ${exchangeBaseUrl}`);
  const exchangeClient = walletExchangeClient(exchangeBaseUrl, wex);
  const resp = await exchangeClient.getTermsMeta();

  switch (resp.case) {
    case "ok":
      return { type: "ok", etag: resp.body.etag };
    case HttpStatusCode.NotFound:
    case HttpStatusCode.NotImplemented:
      return { type: "not-found" };
    default:
      return assertUnreachable(resp);
  }
}

/**
 * Check if an exchange entry should be considered
 * to be outdated.
 */
async function checkExchangeEntryOutdated(
  wex: WalletExecutionContext,
  tx: WalletDbTransaction,
  exchangeBaseUrl: string,
  exchangeMasterPub: string | undefined,
): Promise<boolean> {
  // We currently consider the exchange outdated when no
  // denominations can be used for withdrawal.

  logger.trace(`checking if exchange entry for ${exchangeBaseUrl} is outdated`);
  let numOkay = 0;
  // Only the accepted key set can be withdrawn from, so only it can make the
  // entry look current; a superseded one is still spendable.
  let denoms =
    exchangeMasterPub != null
      ? await tx.getDenominationsByMasterPub(exchangeMasterPub)
      : await getAllDenominationsForExchange(tx, exchangeBaseUrl);
  logger.trace(`exchange entry has ${denoms.length} denominations`);
  for (const denom of denoms) {
    const denomOkay = isCandidateWithdrawableDenomRec(denom);
    if (denomOkay) {
      numOkay++;
    }
  }
  logger.trace(`Of these, ${numOkay} are usable`);
  return numOkay === 0;
}

/**
 * Key identifying a denomination family, for looking one up without a query
 * per denomination.  Mirrors the unique index the DB layer has on these
 * columns; amounts are canonical strings, so comparing them as text is what
 * the query would do anyway.
 *
 * Joined on a character none of the components can contain, so that two
 * different tuples cannot spell the same key.
 */
function denomFamilyParamsKey(p: WalletDenomFamilyParams): string {
  return [
    p.exchangeBaseUrl,
    p.exchangeMasterPub,
    p.value,
    p.feeWithdraw,
    p.feeDeposit,
    p.feeRefresh,
    p.feeRefund,
  ].join("\u0000");
}

/**
 * Is a denomination we have not seen before worth a row in the database?
 *
 * Only denominations that can still be withdrawn from are: the wallet gets a
 * coin of a denomination by withdrawing or refreshing into it, and both pick
 * from the withdrawable ones.  A denomination it already has a row for is
 * never dropped on this basis -- that row may be what a coin in the wallet
 * refers to, and losing it would count the coin as vanished.
 */
function isDenomWorthStoring(d: DenominationInfo): boolean {
  const expireWithdraw = AbsoluteTime.fromProtocolTimestamp(
    d.stampExpireWithdraw,
  );
  return !AbsoluteTime.isExpired(expireWithdraw);
}

/**
 * Timestamp (in seconds) to ask the exchange to cherry-pick /keys by, or
 * undefined when the whole response should be downloaded.
 *
 * The protocol wants the largest stamp_start among the denominations the
 * client already knows, and the exchange answers with exactly the
 * denominations that started at or after it.  Deriving that from the
 * denominations in the database rather than remembering it separately means
 * the request can never claim knowledge the wallet does not have.
 */
async function getKeysCherryPickDate(
  tx: WalletDbTransaction,
  exchangeBaseUrl: string,
  exchangeMasterPub: string,
): Promise<number | undefined> {
  let maxStampStart: DbProtocolTimestamp | undefined;
  // Only the accepted key set: denominations of a superseded one are in no
  // /keys the current key signs, so their start date names no cherry-picking
  // point either.
  const denoms = await tx.getDenominationsByMasterPub(exchangeMasterPub);
  for (const denom of denoms) {
    // Only denominations the exchange should still be listing are candidates.
    // A revoked or retired one is gone from /keys, so its start date names no
    // cherry-picking point and would cost us the full response every time.
    if (denom.isRevoked || !denom.isOffered) {
      continue;
    }
    if (maxStampStart == null || denom.stampStart > maxStampStart) {
      maxStampStart = denom.stampStart;
    }
  }
  if (maxStampStart == null) {
    return undefined;
  }
  const stampStart = timestampProtocolFromDb(maxStampStart);
  if (stampStart.t_s === "never") {
    return undefined;
  }
  return stampStart.t_s;
}

export interface StartUpdateExchangeResult {
  /**
   * Canonical or updated base URL.
   */
  exchangeBaseUrl: string;

  readySummary?: ReadyExchangeSummary;
}

/**
 * Transition an exchange into an updating state.
 *
 * If the update is forced, the exchange is put into an updating state
 * even if the old information should still be up to date.
 *
 * If the exchange entry doesn't exist,
 * a new ephemeral entry is created.
 *
 * If options.forceUnavailable is set, the exchange is put into
 * an unavailable state.  This flag should be set whenever
 * some other operation notices that something is wrong
 * with the exchange.
 */
export async function startUpdateExchangeEntry(
  wex: WalletExecutionContext,
  exchangeBaseUrl: string,
  options: { forceUpdate?: boolean; forceUnavailable?: boolean } = {},
): Promise<StartUpdateExchangeResult> {
  logger.trace(
    `starting update of exchange entry ${exchangeBaseUrl}, forced=${
      options.forceUpdate ?? false
    }`,
  );

  await wex.runWalletDbTx(async (tx) => {
    const rec = await tx.getExchangeBaseUrlFixup(exchangeBaseUrl);
    if (rec) {
      logger.warn(
        `using replacement ${rec.replacement} for ${exchangeBaseUrl}`,
      );
      exchangeBaseUrl = rec.replacement;
    }
  });

  // Writing an exchange record marks the transaction as cache-invalidating,
  // so the caches are dropped after it commits and this lookup sees a summary
  // only while it is still current.
  await wex.runWalletDbTx(async (tx) => {
    return provideExchangeRecordInTx(wex.ws, tx, exchangeBaseUrl);
  });

  if (!options.forceUpdate) {
    const cachedSummary = wex.ws.exchangeCache.get(exchangeBaseUrl);
    if (cachedSummary) {
      return {
        exchangeBaseUrl: cachedSummary.exchangeBaseUrl,
        readySummary: cachedSummary,
      };
    }
  } else {
    wex.ws.exchangeCache.clear();
  }

  let readySummary: ReadyExchangeSummary | undefined = undefined;

  const res = await wex.runWalletDbTx(async (tx) => {
    const r = await tx.getExchange(exchangeBaseUrl);
    if (!r) {
      throw Error("exchange not found");
    }

    const taskId = TaskIdentifiers.forExchangeUpdate(r);

    const oldExchangeState = getExchangeState(r);
    if (options.forceUnavailable) {
      switch (r.updateStatus) {
        case ExchangeEntryDbUpdateStatus.UnavailableUpdate:
          break;
        default:
          r.lastUpdate = undefined;
          r.nextUpdateStamp = timestampPreciseToDb(TalerPreciseTimestamp.now());
          r.cachebreakNextUpdate = options.forceUpdate;
          r.updateStatus = ExchangeEntryDbUpdateStatus.UnavailableUpdate;
      }
    } else {
      switch (r.updateStatus) {
        case ExchangeEntryDbUpdateStatus.UnavailableUpdate:
          r.cachebreakNextUpdate = options.forceUpdate;
          break;
        case ExchangeEntryDbUpdateStatus.Suspended:
          r.cachebreakNextUpdate = options.forceUpdate;
          break;
        case ExchangeEntryDbUpdateStatus.ReadyUpdate: {
          const outdated = await checkExchangeEntryOutdated(
            wex,
            tx,
            exchangeBaseUrl,
            r.detailsPointer?.masterPublicKey,
          );
          if (outdated) {
            r.updateStatus = ExchangeEntryDbUpdateStatus.OutdatedUpdate;
          } else {
            r.updateStatus = ExchangeEntryDbUpdateStatus.ReadyUpdate;
            readySummary = await loadReadyExchangeSummary(tx, r);
          }
          r.cachebreakNextUpdate = options.forceUpdate;
          break;
        }
        case ExchangeEntryDbUpdateStatus.OutdatedUpdate:
          r.cachebreakNextUpdate = options.forceUpdate;
          break;
        case ExchangeEntryDbUpdateStatus.Ready: {
          const nextUpdateTimestamp = AbsoluteTime.fromPreciseTimestamp(
            timestampPreciseFromDb(r.nextUpdateStamp),
          );
          // Only update if entry is outdated or update is forced.
          if (
            !(
              options.forceUpdate || AbsoluteTime.isExpired(nextUpdateTimestamp)
            )
          ) {
            readySummary = await loadReadyExchangeSummary(tx, r);
            return undefined;
          }
          const outdated = await checkExchangeEntryOutdated(
            wex,
            tx,
            exchangeBaseUrl,
            r.detailsPointer?.masterPublicKey,
          );
          if (outdated) {
            r.updateStatus = ExchangeEntryDbUpdateStatus.OutdatedUpdate;
          } else {
            r.updateStatus = ExchangeEntryDbUpdateStatus.ReadyUpdate;
          }
          r.cachebreakNextUpdate = options.forceUpdate;
          break;
        }
        case ExchangeEntryDbUpdateStatus.Initial:
          r.cachebreakNextUpdate = options.forceUpdate;
          r.updateStatus = ExchangeEntryDbUpdateStatus.InitialUpdate;
          break;
        case ExchangeEntryDbUpdateStatus.InitialUpdate:
          r.cachebreakNextUpdate = options.forceUpdate;
          break;
      }
    }
    wex.ws.exchangeCache.clear();
    await tx.upsertExchange(r);
    const newExchangeState = getExchangeState(r);
    tx.notify({
      type: NotificationType.ExchangeStateTransition,
      exchangeBaseUrl,
      causeHint: "update-started",
      newExchangeState: newExchangeState,
      oldExchangeState: oldExchangeState,
    });
    return { taskId };
  });

  if (res) {
    const { taskId } = res;
    if (options.forceUpdate) {
      // FIXME: Do we throttle forced updates somehow?
      await wex.taskScheduler.resetTask(taskId);
    } else {
      wex.taskScheduler.startShepherdTask(taskId);
    }
  }

  return {
    exchangeBaseUrl: exchangeBaseUrl,
    readySummary,
  };
}

/**
 * Basic information about an exchange in a ready state.
 */
export interface ReadyExchangeSummary {
  exchangeBaseUrl: string;
  currency: string;
  masterPub: string;
  tosStatus: ExchangeTosStatus;
  tosAcceptedEtag: string | undefined;
  tosCurrentEtag: string | undefined;
  wireInfo: WireInfo;
  protocolVersionRange: string;
  tosAcceptedTimestamp: TalerPreciseTimestamp | undefined;
  scopeInfo: ScopeInfo;
  walletBalanceLimitWithoutKyc: AmountString[] | undefined;
  tinyAmount: AmountString;
  zeroLimits: ZeroLimitedOperation[];
  hardLimits: AccountLimit[];
  /**
   * Set when the exchange changed its key set and the user has not confirmed
   * the change.  Present here rather than looked up separately because every
   * operation that could act on it already holds a summary.
   */
  unconfirmedKeyChange?: ExchangeKeyChangeInfo;
}

/**
 * Exception to signal that an exchange that is intented
 * to be used in a transaction is outdated.
 *
 * Thrown from transactions to trigger an exchange entry update
 * and re-try of the transaction.
 */
export class OutdatedExchangeError extends Error {
  constructor(
    message: string,
    public readonly exchangeBaseUrl: string,
  ) {
    super(message);
    Object.setPrototypeOf(this, new.target.prototype);
    this.name = this.constructor.name;
  }
}

/**
 * Require that an exchange entry is reasonably up to date
 * within a transaction.
 *
 * If the exchange entry is not up to date, an exception is thrown
 * that will cause the transaction to be re-tried after updating
 * the exchange.
 */
export async function requireExchangeReadyTx(
  wex: WalletExecutionContext,
  tx: WalletDbTransaction,
  exchangeBaseUrl: string,
): Promise<void> {
  const exchange = await tx.getExchange(exchangeBaseUrl);
  if (!exchange) {
    // This is fatal, outer transaction will not be retried.
    throw Error("exchange does not exist in database");
  }
  const isOutdated = await checkExchangeEntryOutdated(
    wex,
    tx,
    exchangeBaseUrl,
    exchange.detailsPointer?.masterPublicKey,
  );
  if (isOutdated) {
    logger.warn(`exchange ${exchangeBaseUrl} outdated`);
    throw new OutdatedExchangeError("exchange entry outdated", exchangeBaseUrl);
  }
}

/**
 * Reset retries for updating an exchange entry.
 */
export async function resetExchangeRetries(
  wex: WalletExecutionContext,
  baseUrl: string,
): Promise<void> {
  const taskId = TaskIdentifiers.forExchangeUpdateFromUrl(baseUrl);
  await wex.taskScheduler.resetTask(taskId);
}

/**
 * Ensure that a fresh exchange entry exists for the given
 * exchange base URL.
 *
 * If an exchange entry for the database doesn't exist in the
 * DB, it will be added ephemerally.
 *
 * If the expectedMasterPub is given and does not match the actual
 * master pub, an exception will be thrown.  However, the exchange
 * will still have been added as an ephemeral exchange entry.
 *
 * If options.noBail is set, do not stop waiting when
 * the exchange is in an unavailable or error state.
 *
 * If options.forceUpdate is set, only return when
 * the exchange is really not updating anymore,
 * even when the exchange entry still looks recent enough.
 */
export async function fetchFreshExchange(
  wex: WalletExecutionContext,
  baseUrl: string,
  options: {
    forceUpdate?: boolean;
    expectedMasterPub?: string;
    noBail?: boolean;
  } = {},
): Promise<ReadyExchangeSummary> {
  logger.trace(`fetch fresh ${baseUrl} forced ${options.forceUpdate}`);

  // Under a progress context the client can cancel and retry the request, so
  // the sensible default is to keep waiting for the exchange rather than give
  // up on it: the client decides when to stop.  A caller that instead wants
  // best-effort behaviour (fail fast and try another exchange) passes
  // noBail: false explicitly.
  const noBail = options.noBail ?? wex.progressContext != null;

  const startRes = await startUpdateExchangeEntry(wex, baseUrl, {
    forceUpdate: options.forceUpdate,
  });

  if (startRes.readySummary) {
    // Fast path: Ready exchange is already available!
    checkExpectedMasterPub(startRes.readySummary, options.expectedMasterPub);
    return startRes.readySummary;
  }

  return await waitReadyExchange(wex, startRes.exchangeBaseUrl, {
    ...options,
    noBail,
  });
}

/**
 * Like fetchFreshExchange, but while it waits, a client's "retry now" resets
 * the backoff of the exchange update task — which is what actually holds the
 * request up.  Used by request handlers that block on a specific exchange
 * becoming ready before there is a transaction to watch.
 */
export async function fetchFreshExchangeWithRetryNow(
  wex: WalletExecutionContext,
  baseUrl: string,
  options: {
    forceUpdate?: boolean;
    expectedMasterPub?: string;
    noBail?: boolean;
  } = {},
): Promise<ReadyExchangeSummary> {
  const progressContext = wex.progressContext;
  if (progressContext) {
    progressContext.onRetryNow = async () => {
      await resetExchangeRetries(wex, baseUrl);
    };
  }
  try {
    return await fetchFreshExchange(wex, baseUrl, options);
  } finally {
    if (progressContext) {
      progressContext.onRetryNow = undefined;
    }
  }
}

/**
 * Reject a summary that belongs to a different exchange than the caller
 * expected.
 */
function checkExpectedMasterPub(
  summary: ReadyExchangeSummary,
  expectedMasterPub: string | undefined,
): void {
  if (expectedMasterPub && summary.masterPub !== expectedMasterPub) {
    throw TalerError.fromDetail(
      TalerErrorCode.WALLET_EXCHANGE_SIGNATURE_INVALID,
      {},
      "the exchange's master public key does not match the expected one",
    );
  }
}

/**
 * Wait until an exchange is in a ready state.
 *
 * If options.noBail is set, do not stop waiting when
 * the exchange is in an unavailable or error state.
 *
 * If options.forceUpdate is set, only return when
 * the exchange is really not updating anymore,
 * even when the exchange entry still looks recent enough.
 */
export async function waitReadyExchange(
  wex: WalletExecutionContext,
  exchangeBaseUrl: string,
  options: {
    forceUpdate?: boolean;
    expectedMasterPub?: string;
    noBail?: boolean;
    waitAutoRefresh?: boolean;
  } = {},
): Promise<ReadyExchangeSummary> {
  logger.trace(`waiting for exchange ${exchangeBaseUrl} to become ready`);

  await wex.runWalletDbTx(async (tx) => {
    const rec = await tx.getExchangeBaseUrlFixup(exchangeBaseUrl);
    if (rec) {
      logger.warn(
        `using replacement ${rec.replacement} for ${exchangeBaseUrl}`,
      );
      exchangeBaseUrl = rec.replacement;
    }
  });

  const operationId = constructTaskIdentifier({
    tag: PendingTaskType.ExchangeUpdate,
    exchangeBaseUrl: exchangeBaseUrl,
  });

  let res: ReadyExchangeSummary | undefined = undefined;

  await genericWaitForState(wex, {
    filterNotification(notif): boolean {
      return (
        notif.type === NotificationType.ExchangeStateTransition &&
        notif.exchangeBaseUrl === exchangeBaseUrl
      );
    },
    async checkState(): Promise<boolean> {
      const { exchange, exchangeDetails, retryInfo, scopeInfo } =
        await wex.runWalletDbTx(async (tx) => {
          const exchange = await tx.getExchange(exchangeBaseUrl);
          const exchangeDetails = await getExchangeRecordsInternal(
            tx,
            exchangeBaseUrl,
          );
          const retryInfo = await tx.getOperationRetry(operationId);
          let scopeInfo: ScopeInfo | undefined = undefined;
          if (exchange && exchangeDetails) {
            scopeInfo = await internalGetExchangeScopeInfo(tx, exchangeDetails);
          }
          return { exchange, exchangeDetails, retryInfo, scopeInfo };
        });

      if (!exchange) {
        throw Error(
          `exchange entry for ${exchangeBaseUrl} does not exist anymore`,
        );
      }

      let ready = false;

      switch (exchange.updateStatus) {
        case ExchangeEntryDbUpdateStatus.Ready:
          ready = true;
          break;
        case ExchangeEntryDbUpdateStatus.ReadyUpdate:
          // If the update is forced,
          // we wait until we're in a full "ready" state,
          // as we're not happy with the stale information.
          if (!options.forceUpdate) {
            ready = true;
          }
          if (
            !options.noBail &&
            retryInfo &&
            retryInfo.retryInfo.retryCounter > 1
          ) {
            logger.trace(
              `exchange in ready-update with retryInfo=${j2s(retryInfo)}`,
            );
            const reason = retryInfo?.lastError ?? exchange.unavailableReason;
            if (reason) {
              throw TalerError.fromUncheckedDetail(reason);
            } else {
              // Unlikely, but could happen.
              throw Error(
                "updating exchange failed, error code unavailable (internal error, check logs)",
              );
            }
          }
          break;
        case ExchangeEntryDbUpdateStatus.UnavailableUpdate: {
          if (
            !options.noBail &&
            retryInfo &&
            retryInfo.retryInfo.retryCounter > 1
          ) {
            throw TalerError.fromDetail(
              TalerErrorCode.WALLET_EXCHANGE_UNAVAILABLE,
              {
                exchangeBaseUrl: exchangeBaseUrl,
                innerError: retryInfo?.lastError ?? exchange.unavailableReason,
              },
            );
          }
          break;
        }
        case ExchangeEntryDbUpdateStatus.OutdatedUpdate:
        default: {
          if (
            !options.noBail &&
            retryInfo &&
            retryInfo.retryInfo.retryCounter > 1
          ) {
            throw TalerError.fromDetail(
              TalerErrorCode.WALLET_EXCHANGE_UNAVAILABLE,
              {
                exchangeBaseUrl: exchangeBaseUrl,
                innerError: retryInfo?.lastError ?? exchange.unavailableReason,
              },
            );
          }
          break;
        }
      }

      if (!ready) {
        // The exchange update runs as its own task, so its retry info is the
        // only progress a request waiting here can report.
        const progressContext = wex.progressContext;
        if (progressContext != null && retryInfo != null) {
          wex.ws.notify({
            type: NotificationType.RequestProgressError,
            progressToken: progressContext.progressToken,
            operation: progressContext.operation,
            error: retryInfo?.lastError ?? {
              code: TalerErrorCode.GENERIC_TIMEOUT,
            },
            retryCounter: retryInfo.retryInfo.retryCounter,
            nextRetryDelay: Duration.toTalerProtocolDuration(
              AbsoluteTime.difference(
                AbsoluteTime.now(),
                timestampAbsoluteFromDb(retryInfo.retryInfo.nextRetry),
              ),
            ),
          });
        }
        return false;
      }

      if (options.waitAutoRefresh) {
        logger.info(`checking for exchange auto-refresh status`);
        if (
          AbsoluteTime.isExpired(
            timestampAbsoluteFromDb(exchange.nextRefreshCheckStamp),
          )
        ) {
          // Next planned refresh check is in the past, we need to wait.
          logger.info(
            `exchange ${exchange.baseUrl} not ready, waiting for auto-refresh`,
          );
          // FIXME: Emit progress notification here.
          return false;
        }
      }

      if (!exchangeDetails) {
        throw Error("invariant failed");
      }

      if (!scopeInfo) {
        throw Error("invariant failed");
      }

      const mySummary = constructReadyExchangeSummary(
        exchange,
        exchangeDetails,
        scopeInfo,
      );

      checkExpectedMasterPub(mySummary, options.expectedMasterPub);
      res = mySummary;
      return true;
    },
  });

  checkLogicInvariant(!!res);
  wex.ws.exchangeCache.put(exchangeBaseUrl, res);
  return res;
}

function constructReadyExchangeSummary(
  exchangeRec: WalletExchangeEntry,
  exchangeDetails: WalletExchangeDetails,
  scopeInfo: ScopeInfo,
): ReadyExchangeSummary {
  return {
    currency: exchangeDetails.currency,
    exchangeBaseUrl: exchangeRec.baseUrl,
    masterPub: exchangeDetails.masterPublicKey,
    tosStatus: getExchangeTosStatusFromRecord(exchangeRec),
    tosAcceptedEtag: exchangeRec.tosAcceptedEtag,
    wireInfo: exchangeDetails.wireInfo,
    protocolVersionRange: exchangeDetails.protocolVersionRange,
    tosCurrentEtag: exchangeRec.tosCurrentEtag,
    tosAcceptedTimestamp: timestampOptionalPreciseFromDb(
      exchangeRec.tosAcceptedTimestamp,
    ),
    tinyAmount: exchangeDetails.tinyAmount,
    scopeInfo,
    walletBalanceLimitWithoutKyc: exchangeDetails.walletBalanceLimits,
    hardLimits: exchangeDetails.hardLimits ?? [],
    zeroLimits: exchangeDetails.zeroLimits ?? [],
    ...(exchangeRec.supersededKeySet
      ? {
          unconfirmedKeyChange: {
            currentMasterPub: exchangeDetails.masterPublicKey,
            currentCurrency: exchangeDetails.currency,
            supersededMasterPub: exchangeRec.supersededKeySet.masterPublicKey,
            supersededCurrency: exchangeRec.supersededKeySet.currency,
            sharesDenominations:
              exchangeRec.supersededKeySet.sharesDenominations,
            firstSeen: timestampPreciseFromDb(
              exchangeRec.supersededKeySet.firstSeen,
            ),
          },
        }
      : undefined),
  };
}

async function loadReadyExchangeSummary(
  tx: WalletDbTransaction,
  exchangeRec: WalletExchangeEntry,
): Promise<ReadyExchangeSummary | undefined> {
  const exchangeDetails = await getExchangeRecordsInternal(
    tx,
    exchangeRec.baseUrl,
  );
  if (!exchangeDetails) {
    return undefined;
  }
  const scopeInfo = await internalGetExchangeScopeInfo(tx, exchangeDetails);
  if (!scopeInfo) {
    return undefined;
  }
  return constructReadyExchangeSummary(exchangeRec, exchangeDetails, scopeInfo);
}

function checkPeerPaymentsDisabled(keysInfo: ExchangeKeysResponse): boolean {
  const now = AbsoluteTime.now();
  for (let gf of keysInfo.global_fees) {
    const isActive = AbsoluteTime.isBetween(
      now,
      AbsoluteTime.fromProtocolTimestamp(gf.start_date),
      AbsoluteTime.fromProtocolTimestamp(gf.end_date),
    );
    if (!isActive) {
      continue;
    }
    return false;
  }
  // No global fees, we can't do p2p payments!
  return true;
}

function checkNoFees(keysInfo: ExchangeKeysResponse): boolean {
  for (const gf of keysInfo.global_fees) {
    if (!Amounts.isZero(gf.account_fee)) {
      return false;
    }
    if (!Amounts.isZero(gf.history_fee)) {
      return false;
    }
    if (!Amounts.isZero(gf.purse_fee)) {
      return false;
    }
  }
  for (const denomFamily of keysInfo.denominations) {
    if (!Amounts.isZero(denomFamily.fee_withdraw)) {
      return false;
    }
    if (!Amounts.isZero(denomFamily.fee_deposit)) {
      return false;
    }
    if (!Amounts.isZero(denomFamily.fee_refund)) {
      return false;
    }
    if (!Amounts.isZero(denomFamily.fee_refresh)) {
      return false;
    }
  }
  for (const wft of Object.values(keysInfo.wire_fees)) {
    for (const wf of wft) {
      if (!Amounts.isZero(wf.wire_fee)) {
        return false;
      }
    }
  }
  return true;
}

async function handleExchageUpdateIncompatible(
  wex: WalletExecutionContext,
  exchangeBaseUrl: string,
  exchangeProtocolVersion: string,
): Promise<TaskRunResult> {
  await wex.runWalletDbTx(async (tx) => {
    const r = await tx.getExchange(exchangeBaseUrl);
    if (!r) {
      logger.warn(`exchange ${exchangeBaseUrl} no longer present`);
      return;
    }
    switch (r.updateStatus) {
      case ExchangeEntryDbUpdateStatus.InitialUpdate:
      case ExchangeEntryDbUpdateStatus.OutdatedUpdate:
      case ExchangeEntryDbUpdateStatus.ReadyUpdate:
      case ExchangeEntryDbUpdateStatus.UnavailableUpdate:
        break;
      default:
        return;
    }
    const oldExchangeState = getExchangeState(r);
    r.updateStatus = ExchangeEntryDbUpdateStatus.UnavailableUpdate;
    r.unavailableReason = makeTalerErrorDetail(
      TalerErrorCode.WALLET_EXCHANGE_PROTOCOL_VERSION_INCOMPATIBLE,
      {
        exchangeProtocolVersion: exchangeProtocolVersion,
        walletProtocolVersion: WALLET_EXCHANGE_PROTOCOL_VERSION,
      },
    );
    const newExchangeState = getExchangeState(r);
    await tx.upsertExchange(r);
    tx.notify({
      type: NotificationType.ExchangeStateTransition,
      exchangeBaseUrl,
      causeHint: "update-incompatible",
      newExchangeState,
      oldExchangeState,
    });
  });
  return TaskRunResult.backoff();
}

/**
 * Update an exchange entry in the wallet's database
 * by fetching the /keys and /wire information.
 * Optionally link the reserve entry to the new or existing
 * exchange entry in then DB.
 */
export async function updateExchangeFromUrlHandler(
  wex: WalletExecutionContext,
  exchangeBaseUrl: string,
): Promise<TaskRunResult> {
  if (!wex.ws.networkAvailable) {
    return TaskRunResult.networkRequired();
  }

  logger.trace(`updating exchange info for ${exchangeBaseUrl}`);

  const oldExchangeRec = await wex.runWalletDbTx(async (tx) => {
    return await tx.getExchange(exchangeBaseUrl);
  });

  if (!oldExchangeRec) {
    logger.warn(`not updating exchange ${exchangeBaseUrl}, no record in DB`);
    return TaskRunResult.finished();
  }

  let updateRequestedExplicitly = false;
  switch (oldExchangeRec.updateStatus) {
    case ExchangeEntryDbUpdateStatus.Suspended:
      logger.trace(`not updating exchange in status "suspended"`);
      return TaskRunResult.finished();
    case ExchangeEntryDbUpdateStatus.Initial:
      logger.trace(`not updating exchange in status "initial"`);
      return TaskRunResult.finished();
    case ExchangeEntryDbUpdateStatus.OutdatedUpdate:
      updateRequestedExplicitly = true;
      break;
    case ExchangeEntryDbUpdateStatus.InitialUpdate:
      updateRequestedExplicitly = true;
      break;
    case ExchangeEntryDbUpdateStatus.ReadyUpdate:
      updateRequestedExplicitly = true;
      break;
    case ExchangeEntryDbUpdateStatus.UnavailableUpdate:
      // Only retry when scheduled to respect backoff
      break;
    case ExchangeEntryDbUpdateStatus.Ready:
      break;
    default:
      assertUnreachable(oldExchangeRec.updateStatus);
  }

  if (!updateRequestedExplicitly) {
    // If the update wasn't requested explicitly,
    // check if we really need to update.

    let nextUpdateStamp = timestampAbsoluteFromDb(
      oldExchangeRec.nextUpdateStamp,
    );

    if (
      oldExchangeRec.lastUpdate != null &&
      !AbsoluteTime.isNever(nextUpdateStamp) &&
      !AbsoluteTime.isExpired(nextUpdateStamp)
    ) {
      logger.trace(
        `exchange update for ${exchangeBaseUrl} not necessary, scheduled for ${AbsoluteTime.toIsoString(
          nextUpdateStamp,
        )}`,
      );
      logger.trace("update not necessary, running again later");
      return TaskRunResult.runAgainAt(nextUpdateStamp);
    }
  }

  // Only an entry that is otherwise healthy is cherry-picked.  After an
  // error, a conflict or an entry that ran out of usable denominations it is
  // the wallet's picture of the denominations that is in doubt, so those
  // updates ask for the whole response instead.
  let cherryPickDate: number | undefined = undefined;
  const acceptedMasterPub = oldExchangeRec.detailsPointer?.masterPublicKey;
  switch (oldExchangeRec.updateStatus) {
    case ExchangeEntryDbUpdateStatus.Ready:
    case ExchangeEntryDbUpdateStatus.ReadyUpdate:
      if (acceptedMasterPub != null) {
        cherryPickDate = await wex.runWalletDbTx(async (tx) => {
          return await getKeysCherryPickDate(
            tx,
            exchangeBaseUrl,
            acceptedMasterPub,
          );
        });
      }
      break;
  }

  // When doing the auto-refresh check, we always update
  // the key info before that.

  logger.trace("updating exchange /keys info");

  const timeout = getExchangeRequestTimeout();

  let keysInfoRes: ExchangeKeysDownloadResult;

  try {
    keysInfoRes = await downloadExchangeKeysInfo(
      exchangeBaseUrl,
      wex.http,
      timeout,
      wex.cancellationToken,
      oldExchangeRec.cachebreakNextUpdate ?? false,
      cherryPickDate,
    );
  } catch (e) {
    logger.warn(`unable to download exchange keys for ${exchangeBaseUrl}`);
    // If keys download fails, check if there's a migration.
    // Only if the migration target is reachable, migrate there!
    const plan = wex.ws.exchangeMigrationPlan.get(exchangeBaseUrl);
    if (plan) {
      logger.warn(
        `trying migration from ${exchangeBaseUrl} to ${plan.newExchangeBaseUrl}`,
      );
      const newExchangeClient = walletExchangeClient(
        plan.newExchangeBaseUrl,
        wex,
      );
      const newExchangeKeys = await newExchangeClient.getKeys();
      logger.info(`new exchange status ${newExchangeKeys.case}`);
      if (
        newExchangeKeys.case !== "ok" ||
        newExchangeKeys.body.base_url !== plan.newExchangeBaseUrl
      ) {
        logger.info(`not migrating`);
        throw e;
      }
      logger.info(`migrating`);
      await migrateExchange(wex, {
        oldExchangeBaseUrl: exchangeBaseUrl,
        newExchangeBaseUrl: plan.newExchangeBaseUrl,
        trigger: ExchangeMigrationReason.UnavailableOldUrl,
      });
      return TaskRunResult.finished();
    }
    throw e;
  }

  logger.trace("validating exchange wire info");

  switch (keysInfoRes.type) {
    case "version-incompatible":
      return handleExchageUpdateIncompatible(
        wex,
        exchangeBaseUrl,
        keysInfoRes.exchangeProtocolVersion,
      );
  }

  {
    const fakePub =
      wex.ws.devExperimentState.fakeMasterPub?.get(exchangeBaseUrl);
    if (fakePub) {
      logger.warn("devexperiment: faking exchange pub");
      keysInfoRes.res.master_public_key = fakePub.fakeMasterPub;
    }
  }

  const keysInfo = keysInfoRes.res;

  if (keysInfo.base_url != exchangeBaseUrl) {
    const plan = wex.ws.exchangeMigrationPlan.get(exchangeBaseUrl);
    if (plan?.newExchangeBaseUrl === keysInfo.base_url) {
      const newExchangeClient = walletExchangeClient(
        plan.newExchangeBaseUrl,
        wex,
      );
      const newExchangeKeys = await newExchangeClient.getKeys();
      if (
        newExchangeKeys.case !== "ok" ||
        newExchangeKeys.body.base_url !== plan.newExchangeBaseUrl
      ) {
        logger.warn("ignoring migration record, new URL not reachable");
        const errorDetail: TalerErrorDetail = makeErrorDetail(
          TalerErrorCode.WALLET_EXCHANGE_BASE_URL_MISMATCH,
          {
            urlWallet: exchangeBaseUrl,
            urlExchange: keysInfo.base_url,
          },
        );
        return TaskRunResult.error(errorDetail);
      }
      await migrateExchange(wex, {
        oldExchangeBaseUrl: exchangeBaseUrl,
        newExchangeBaseUrl: plan.newExchangeBaseUrl,
        trigger: ExchangeMigrationReason.MismatchedBaseUrl,
      });
      return TaskRunResult.backoff();
    }
    logger.warn("exchange base URL mismatch");
    const errorDetail: TalerErrorDetail = makeErrorDetail(
      TalerErrorCode.WALLET_EXCHANGE_BASE_URL_MISMATCH,
      {
        urlWallet: exchangeBaseUrl,
        urlExchange: keysInfo.base_url,
      },
    );
    return TaskRunResult.error(errorDetail);
  }

  const version = LibtoolVersion.parseVersion(keysInfo.version);
  if (!version) {
    // Should have been validated earlier.
    throw Error("unexpected invalid version");
  }

  const wireInfo = await validateWireInfo(
    wex,
    version.current,
    keysInfo,
    keysInfo.master_public_key,
  );

  const globalFees = await validateGlobalFees(
    wex,
    keysInfo.global_fees,
    keysInfo.master_public_key,
  );

  await validateSignKeys(wex, keysInfo.signkeys, keysInfo.master_public_key);

  logger.trace("finished validating exchange /wire info");

  const tosMeta = await downloadTosMeta(wex, exchangeBaseUrl);

  logger.trace("updating exchange info in database");

  // Did the exchange honour our cherry-picking request?  It falls back to the
  // full response whenever the timestamp doesn't name a denomination it
  // currently offers, and then echoes that response's own issue date instead.
  const cherryPicked =
    cherryPickDate != null && keysInfo.list_issue_date.t_s === cherryPickDate;

  if (cherryPicked) {
    logger.trace(
      `exchange cherry-picked /keys from ${cherryPickDate}, ` +
        `denominations that started earlier are not in the response`,
    );
  }

  // Age mask advertised by the exchange, i.e. the one shared by its
  // age-restricted denominations.  Zero when it offers none.
  let exchangeAgeMask = 0;

  let noFees = checkNoFees(keysInfo);
  let peerPaymentsDisabled = checkPeerPaymentsDisabled(keysInfo);
  if (cherryPicked && oldExchangeRec.noFees === false) {
    // Part of being fee-free is a property of the denominations, and the ones
    // a cherry-picked response leaves out are exactly the ones that could
    // have carried a fee.  Their fees are signed and cannot have changed, so
    // the verdict from the full list still stands.
    noFees = false;
  }

  const denomInfos: DenominationInfo[] = [];
  const currentDenomSet = new Set<string>();
  for (const denomFamily of keysInfo.denominations) {
    switch (denomFamily.cipher) {
      case "CS":
      case "CS+age_restricted": {
        const ageMask =
          denomFamily.cipher === "CS+age_restricted" ? denomFamily.age_mask : 0;
        if (ageMask !== 0) {
          exchangeAgeMask = ageMask;
        }
        for (const denom of denomFamily.denoms) {
          const denomPub: DenominationPubKey = {
            age_mask: ageMask,
            cipher: DenomKeyType.ClauseSchnorr,
            cs_public_key: denom.cs_pub,
          };
          const denomPubHash = encodeCrock(hashDenomPub(denomPub));
          const di: DenominationInfo = {
            denomPub,
            denomPubHash,
            exchangeBaseUrl,
            exchangeMasterPub: keysInfo.master_public_key,
            feeDeposit: denomFamily.fee_deposit,
            feeRefresh: denomFamily.fee_refresh,
            feeRefund: denomFamily.fee_refund,
            feeWithdraw: denomFamily.fee_withdraw,
            stampExpireDeposit: denom.stamp_expire_deposit,
            stampExpireLegal: denom.stamp_expire_legal,
            stampExpireWithdraw: denom.stamp_expire_withdraw,
            stampStart: denom.stamp_start,
            value: denomFamily.value,
            isOffered: true,
            isLost: denom.lost ?? false,
            masterSig: denom.master_sig,
          };
          denomInfos.push(di);
          currentDenomSet.add(denomPubHash);
        }
        break;
      }
      case "RSA":
      case "RSA+age_restricted": {
        const ageMask =
          denomFamily.cipher === "RSA+age_restricted"
            ? denomFamily.age_mask
            : 0;
        if (ageMask !== 0) {
          exchangeAgeMask = ageMask;
        }
        for (const denom of denomFamily.denoms) {
          const denomPub: DenominationPubKey = {
            age_mask: ageMask,
            cipher: DenomKeyType.Rsa,
            rsa_public_key: denom.rsa_pub,
          };
          const denomPubHash = encodeCrock(hashDenomPub(denomPub));
          const fp: WalletDenomFamilyParams = {
            exchangeBaseUrl: exchangeBaseUrl,
            exchangeMasterPub: keysInfo.master_public_key,
            feeDeposit: denomFamily.fee_deposit,
            feeRefresh: denomFamily.fee_refresh,
            feeRefund: denomFamily.fee_refund,
            feeWithdraw: denomFamily.fee_withdraw,
            value: denomFamily.value,
          };
          const di: DenominationInfo = {
            denomPub,
            denomPubHash,
            exchangeBaseUrl: exchangeBaseUrl,
            exchangeMasterPub: keysInfo.master_public_key,
            feeDeposit: denomFamily.fee_deposit,
            feeRefresh: denomFamily.fee_refresh,
            feeRefund: denomFamily.fee_refund,
            feeWithdraw: denomFamily.fee_withdraw,
            stampExpireDeposit: denom.stamp_expire_deposit,
            stampExpireLegal: denom.stamp_expire_legal,
            stampExpireWithdraw: denom.stamp_expire_withdraw,
            stampStart: denom.stamp_start,
            value: denomFamily.value,
            isOffered: true,
            isLost: denom.lost ?? false,
            masterSig: denom.master_sig,
          };
          denomInfos.push(di);
          currentDenomSet.add(denomPubHash);
        }
      }
    }
  }

  const validatedAuditors = await validateAuditorDenominations(
    wex,
    keysInfo.auditors,
    denomInfos,
  );

  const taskRes = await wex.runWalletDbTx(async (tx) => {
    const r = await tx.getExchange(exchangeBaseUrl);
    if (!r) {
      logger.warn(`exchange ${exchangeBaseUrl} no longer present`);
      return TaskRunResult.progress();
    }

    const oldExchangeState = getExchangeState(r);
    const existingDetails = await getExchangeRecordsInternal(tx, r.baseUrl);
    let detailsPointerChanged = false;
    if (!existingDetails) {
      detailsPointerChanged = true;
    }
    let detailsIncompatible = false;
    let conflictHint: string | undefined = undefined;
    if (existingDetails) {
      if (existingDetails.masterPublicKey !== keysInfo.master_public_key) {
        detailsIncompatible = true;
        detailsPointerChanged = true;
        conflictHint = "master public key changed";
      } else if (existingDetails.currency !== keysInfo.currency) {
        detailsIncompatible = true;
        detailsPointerChanged = true;
        conflictHint = "currency changed";
      }
      // FIXME: We need to do some more consistency checks!
    }
    if (detailsIncompatible) {
      // The exchange presents a different signing authority.  Keep its
      // metadata as the current observed key set so the user can inspect and
      // confirm it, but gate both money sent to it and authorizations over
      // existing coins.  A URL takeover must not receive either before the
      // replacement master public key is explicitly trusted.
      logger.warn(
        `exchange ${r.baseUrl} changed its key set (${conflictHint})`,
      );
      checkLogicInvariant(!!existingDetails);

      // Whether the new key set still advertises denominations the wallet
      // holds coins of.  A claim rather than proof -- denomination public
      // keys are public -- but an exchange that does not list them will
      // certainly not settle them.
      const heldDenoms = await tx.getDenominationsByMasterPub(
        existingDetails.masterPublicKey,
      );
      const sharesDenominations = heldDenoms.some((d) =>
        currentDenomSet.has(d.denomPubHash),
      );

      // Going back to the key set that was in force before the last change
      // is not a new change to confirm -- the wallet is where it started, and
      // the funds frozen in the meantime become spendable again by
      // themselves.  This is the ordinary outcome of a misconfiguration or a
      // failover that gets corrected.
      const revertedToPrevious =
        r.supersededKeySet != null &&
        r.supersededKeySet.masterPublicKey === keysInfo.master_public_key &&
        r.supersededKeySet.currency === keysInfo.currency;
      if (revertedToPrevious) {
        logger.info(`exchange ${r.baseUrl} reverted to its previous key set`);
        delete r.supersededKeySet;
      } else {
        // Keep the first sighting if the same change is seen again, so the
        // record says when the exchange changed, not when it was last polled.
        const alreadyKnown =
          r.supersededKeySet?.masterPublicKey ===
            existingDetails.masterPublicKey &&
          r.supersededKeySet?.currency === existingDetails.currency;
        r.supersededKeySet = {
          masterPublicKey: existingDetails.masterPublicKey,
          currency: existingDetails.currency,
          firstSeen: alreadyKnown
            ? r.supersededKeySet!.firstSeen
            : timestampPreciseToDb(TalerPreciseTimestamp.now()),
          sharesDenominations,
        };
      }
      // Falls through: the update proceeds normally from here, and
      // detailsPointerChanged is already set, so the new key set becomes the
      // current one.
    }

    delete r.unavailableReason;
    const persistedAuditors =
      cherryPicked &&
      existingDetails?.masterPublicKey === keysInfo.master_public_key &&
      existingDetails.currency === keysInfo.currency
        ? mergeCherryPickedAuditors(
            validatedAuditors,
            existingDetails.auditors,
            currentDenomSet,
          )
        : validatedAuditors;
    const newDetails: WalletExchangeDetails = {
      auditors: persistedAuditors,
      currency: keysInfo.currency,
      masterPublicKey: keysInfo.master_public_key,
      protocolVersionRange: keysInfo.version,
      reserveClosingDelay: keysInfo.reserve_closing_delay,
      globalFees,
      exchangeBaseUrl: r.baseUrl,
      wireInfo,
      // A cherry-picked response need not carry an age-restricted
      // denomination even though the exchange offers some, so seeing none
      // there is not evidence that the age mask went away.
      ageMask:
        cherryPicked && exchangeAgeMask === 0
          ? (existingDetails?.ageMask ?? 0)
          : exchangeAgeMask,
      walletBalanceLimits: keysInfo.wallet_balance_limit_without_kyc,
      hardLimits: keysInfo.hard_limits,
      zeroLimits: keysInfo.zero_limits,
      bankComplianceLanguage: keysInfo.bank_compliance_language,
      shoppingUrl: keysInfo.shopping_url,
      defaultPeerPushExpiration: keysInfo.default_p2p_push_expiration,
      tinyAmount:
        keysInfo.tiny_amount != null
          ? keysInfo.tiny_amount
          : `${keysInfo.currency}:0.01`,
    };
    r.noFees = noFees;
    r.peerPaymentsDisabled = peerPaymentsDisabled;
    r.directDepositDisabled = keysInfo.disable_direct_deposit;
    switch (tosMeta.type) {
      case "not-found":
        r.tosCurrentEtag = undefined;
        break;
      case "ok":
        r.tosCurrentEtag = tosMeta.etag;
        break;
    }
    // A different master key is a different signing identity.  Preserve the
    // old details row so historical denomination references keep resolving;
    // confirmation changes authorization policy, not issuance provenance.
    // If the exchange reverts to a previously seen key set, reuse that row as
    // well: (base URL, currency, master key) is a unique provenance pointer.
    const reusableDetails = await tx.getExchangeDetailsByPointer(
      r.baseUrl,
      newDetails.currency,
      newDetails.masterPublicKey,
    );
    if (reusableDetails?.rowId !== undefined) {
      newDetails.rowId = reusableDetails.rowId;
    }
    r.lastUpdate = timestampPreciseToDb(TalerPreciseTimestamp.now());
    r.nextUpdateStamp = timestampPreciseToDb(
      AbsoluteTime.toPreciseTimestamp(
        // FIXME!
        AbsoluteTime.addDuration(
          AbsoluteTime.now(),
          // While a key change is unconfirmed the situation is unresolved and
          // some of the user's funds are frozen, so check back sooner: the
          // change may be a misconfiguration or a failover that gets
          // corrected, and reverting unfreezes them without the user doing
          // anything.
          r.supersededKeySet
            ? Duration.fromSpec({ minutes: 5 })
            : Duration.fromSpec({ hours: 2 }),
        ),
      ),
    );
    // New denominations might be available.
    r.nextRefreshCheckStamp = timestampPreciseToDb(TalerPreciseTimestamp.now());
    if (detailsPointerChanged) {
      r.detailsPointer = {
        currency: newDetails.currency,
        masterPublicKey: newDetails.masterPublicKey,
        updateClock: timestampPreciseToDb(TalerPreciseTimestamp.now()),
      };
    }

    r.updateStatus = ExchangeEntryDbUpdateStatus.Ready;
    r.cachebreakNextUpdate = false;
    await tx.upsertExchange(r);

    if (keysInfo.currency_specification) {
      // Since this is the per-exchange currency info,
      // we update it when the exchange changes it.
      await tx.upsertCurrencyInfo({
        currencySpec: keysInfo.currency_specification,
        scopeInfo: {
          type: ScopeType.Exchange,
          currency: newDetails.currency,
          url: exchangeBaseUrl,
        },
        source: "exchange",
      });
    }

    const drRowId = await tx.upsertExchangeDetails(newDetails);

    for (const sk of keysInfo.signkeys) {
      await tx.upsertExchangeSignKey({
        exchangeDetailsRowId: drRowId,
        masterSig: sk.master_sig,
        signkeyPub: sk.key,
        stampEnd: timestampProtocolToDb(sk.stamp_end),
        stampExpire: timestampProtocolToDb(sk.stamp_expire),
        stampStart: timestampProtocolToDb(sk.stamp_start),
      });
    }

    // In the future: Filter out old denominations by index
    const allOldDenoms = await getAllDenominationsForExchange(
      tx,
      exchangeBaseUrl,
    );
    // Keep one denomination certificate per signing master key.  A new master
    // can re-advertise the same denomination public key, but that endorsement
    // must not rewrite the provenance of coins issued under the old key.
    const currentDenomByDph = new Map<string, WalletDenomination>();
    const knownDenomHashes = new Set<string>();
    for (const denom of allOldDenoms) {
      knownDenomHashes.add(denom.denomPubHash);
      if (denom.exchangeMasterPub === keysInfo.master_public_key) {
        currentDenomByDph.set(denom.denomPubHash, denom);
      }
    }
    // The retirement sweep below, by contrast, may only judge denominations
    // of the key set this response speaks for: those of a superseded key are
    // absent from every /keys the new key signs, and reading that absence as
    // retirement would write the old balance off as a denomination loss.
    const sweepableDenoms = allOldDenoms.filter(
      (d) => d.exchangeMasterPub === keysInfo.master_public_key,
    );

    logger.trace("updating denominations in database");

    // One lookup for all of them: an exchange has a handful of families but
    // its /keys lists a denomination per family and rotation period, so a
    // query per denomination is a query per row of the response.
    const familySerialByParams = new Map<string, number>();
    for (const fam of await tx.getDenominationFamiliesByExchange(
      exchangeBaseUrl,
    )) {
      checkDbInvariant(
        typeof fam.denominationFamilySerial === "number",
        "denominationFamilySerial",
      );
      familySerialByParams.set(
        denomFamilyParamsKey(fam.familyParams),
        fam.denominationFamilySerial,
      );
    }

    let numDenomsSkipped = 0;

    for (const currentDenom of denomInfos) {
      const oldDenom = currentDenomByDph.get(currentDenom.denomPubHash);

      // A denomination that can no longer be withdrawn from is only of
      // interest for coins we already hold, and we cannot hold a coin of one
      // we never stored.  Exchanges keep advertising these for years after
      // they stop issuing them -- on the demo exchange 952 of 1022 -- so not
      // writing them is most of the cost of adding an exchange.
      if (
        !oldDenom &&
        !knownDenomHashes.has(currentDenom.denomPubHash) &&
        !isDenomWorthStoring(currentDenom)
      ) {
        numDenomsSkipped++;
        continue;
      }

      const familyParams: WalletDenomFamilyParams = {
        exchangeBaseUrl: currentDenom.exchangeBaseUrl,
        exchangeMasterPub: currentDenom.exchangeMasterPub,
        value: currentDenom.value,
        feeWithdraw: currentDenom.feeWithdraw,
        feeDeposit: currentDenom.feeDeposit,
        feeRefresh: currentDenom.feeRefresh,
        feeRefund: currentDenom.feeRefund,
      };
      let fpRec: WalletDenominationFamily | undefined = undefined;
      const knownSerial = familySerialByParams.get(
        denomFamilyParamsKey(familyParams),
      );
      if (knownSerial != null) {
        fpRec = { familyParams, denominationFamilySerial: knownSerial };
      }
      let denominationFamilySerial;
      if (fpRec == null) {
        fpRec = {
          familyParams,
        };
        denominationFamilySerial = await tx.upsertDenominationFamily(fpRec);
        checkDbInvariant(
          typeof denominationFamilySerial === "number",
          "denominationFamilySerial",
        );
        familySerialByParams.set(
          denomFamilyParamsKey(familyParams),
          denominationFamilySerial,
        );
      } else {
        denominationFamilySerial = fpRec.denominationFamilySerial;
      }

      checkDbInvariant(
        typeof denominationFamilySerial === "number",
        "denominationFamilySerial",
      );

      const denomRec: WalletDenomination = {
        currency: keysInfo.currency,
        denominationFamilySerial,
        denomPub: currentDenom.denomPub,
        denomPubHash: currentDenom.denomPubHash,
        exchangeBaseUrl: exchangeBaseUrl,
        exchangeMasterPub: keysInfo.master_public_key,
        fees: {
          feeDeposit: currentDenom.feeDeposit,
          feeRefresh: currentDenom.feeRefresh,
          feeRefund: currentDenom.feeRefund,
          feeWithdraw: currentDenom.feeWithdraw,
        },
        isOffered: currentDenom.isOffered,
        // If revoked, should not show up in keys response.
        isRevoked: false,
        masterSig: currentDenom.masterSig,
        stampExpireDeposit: timestampProtocolToDb(
          currentDenom.stampExpireDeposit,
        ),
        stampExpireLegal: timestampProtocolToDb(currentDenom.stampExpireLegal),
        stampExpireWithdraw: timestampProtocolToDb(
          currentDenom.stampExpireWithdraw,
        ),
        stampStart: timestampProtocolToDb(currentDenom.stampStart),
        value: currentDenom.value,
        verificationStatus: DenominationVerificationStatus.Unverified,
        isLost: currentDenom.isLost,
      };

      if (oldDenom) {
        // FIXME: Do consistency check, report to auditor if necessary.
        // See https://bugs.taler.net/n/8594

        let changed = false;
        // Mark lost denominations as lost.
        if (currentDenom.isLost && !oldDenom.isLost) {
          logger.warn(
            `marking denomination ${currentDenom.denomPubHash} of ${exchangeBaseUrl} as lost`,
          );
          oldDenom.isLost = true;
          changed = true;
        }
        if (oldDenom.denominationFamilySerial != denominationFamilySerial) {
          // Can happen in some wallet versions where denominations
          // were not deleted properly when adding an exchange.
          oldDenom.denominationFamilySerial = denominationFamilySerial;
          changed = true;
        }
        if (changed) {
          await tx.upsertDenomination(oldDenom);
        }
      } else {
        await tx.upsertDenomination(denomRec);
      }
    }

    if (numDenomsSkipped > 0) {
      logger.trace(
        `did not store ${numDenomsSkipped} of ${denomInfos.length} denominations of ${exchangeBaseUrl}, no longer withdrawable`,
      );
    }

    // Update list issue date for all denominations,
    // and mark non-offered denominations as such.
    //
    // A cherry-picked response only speaks about the denominations that
    // started at or after the date we asked for.  Absence from it says
    // nothing about the older ones, and taking it as retirement would strand
    // the coins the wallet holds of them, so they are left alone until an
    // update downloads the full list again.
    const coveredFromStampStart = !cherryPicked
      ? undefined
      : timestampProtocolToDb(keysInfo.list_issue_date);
    for (const x of sweepableDenoms) {
      if (
        coveredFromStampStart != null &&
        x.stampStart < coveredFromStampStart
      ) {
        continue;
      }
      if (!currentDenomSet.has(x.denomPubHash)) {
        // FIXME: Here, an auditor report should be created, unless
        // the denomination is really legally expired.
        if (x.isOffered) {
          x.isOffered = false;
          logger.info(
            `setting denomination ${x.denomPubHash} to offered=false`,
          );
          await tx.upsertDenomination(x);
        }
      } else {
        if (!x.isOffered) {
          x.isOffered = true;
          logger.info(`setting denomination ${x.denomPubHash} to offered=true`);
          await tx.upsertDenomination(x);
        }
      }
    }

    logger.trace("done updating denominations in database");

    // Revocations first: a revoked denomination is dropped from the
    // denominations list as well, so handleDenomLoss can only tell a
    // revocation apart from a plain retirement once isRevoked is set.
    if (keysInfo.recoup != null) {
      await handleRecoup(
        wex,
        tx,
        exchangeBaseUrl,
        keysInfo.master_public_key,
        keysInfo.recoup,
      );
    }

    await handleDenomLoss(
      wex,
      tx,
      newDetails.currency,
      exchangeBaseUrl,
      newDetails.masterPublicKey,
    );

    const newExchangeState = getExchangeState(r);

    tx.notify({
      type: NotificationType.ExchangeStateTransition,
      exchangeBaseUrl,
      causeHint: "update-from-response",
      newExchangeState,
      oldExchangeState,
    });

    return TaskRunResult.progress();
  });

  logger.trace("done updating exchange info in database");

  // Always trigger auto-refresh after an exchange update.
  await doExchangeAutoRefresh(wex, exchangeBaseUrl);

  // Make sure an auto-refresh task is scheduled for this exchange.
  const autoRefreshTaskId =
    TaskIdentifiers.forExchangeAutoRefreshFromUrl(exchangeBaseUrl);
  await wex.taskScheduler.resetTask(autoRefreshTaskId);
  await wex.taskScheduler.resetTask(
    constructTaskIdentifier({ tag: PendingTaskType.ValidateDenoms }),
  );

  return taskRes;
}

async function doExchangeAutoRefresh(
  wex: WalletExecutionContext,
  exchangeBaseUrl: string,
): Promise<void> {
  await updateWithdrawalDenomsForExchange(wex, exchangeBaseUrl);

  let minCheckThreshold = AbsoluteTime.addDuration(
    AbsoluteTime.now(),
    Duration.fromSpec({ days: 1 }),
  );

  await wex.runWalletDbTx(async (tx) => {
    const exchange = await tx.getExchange(exchangeBaseUrl);
    if (!exchange || !exchange.detailsPointer) {
      return;
    }
    const coins = await tx.getCoinsByExchange(exchangeBaseUrl);
    const denominations = await tx.getDenominationsByRefs(coins);
    const denominationsByRef = new Map(
      denominations.map((denom) => [denomRefKey(denom), denom]),
    );
    const refreshCoins: CoinRefreshRequest[] = [];
    for (const coin of coins) {
      if (coin.status !== CoinStatus.Fresh) {
        continue;
      }
      const denom = denominationsByRef.get(denomRefKey(coin));
      if (!denom) {
        logger.warn("denomination not in database");
        continue;
      }
      const executeThreshold = getAutoRefreshExecuteThresholdForDenom(denom);
      if (AbsoluteTime.isExpired(executeThreshold)) {
        refreshCoins.push({
          coinPub: coin.coinPub,
          amount: denom.value,
        });
      } else {
        const checkThreshold = getAutoRefreshCheckThreshold(denom);
        minCheckThreshold = AbsoluteTime.min(minCheckThreshold, checkThreshold);
      }
    }
    if (refreshCoins.length > 0) {
      const res = await createRefreshGroup(
        wex,
        tx,
        exchange.detailsPointer?.currency,
        refreshCoins,
        RefreshReason.Scheduled,
        undefined,
      );
      logger.trace(
        `created refresh group for auto-refresh (${res.refreshGroupId})`,
      );
    }
    logger.trace(
      `next refresh check at ${AbsoluteTime.toIsoString(minCheckThreshold)}`,
    );
    exchange.nextRefreshCheckStamp = timestampPreciseToDb(
      AbsoluteTime.toPreciseTimestamp(minCheckThreshold),
    );
    wex.ws.exchangeCache.clear();
    await tx.upsertExchange(exchange);
    const st = getExchangeState(exchange);
    tx.notify({
      type: NotificationType.ExchangeStateTransition,
      exchangeBaseUrl,
      causeHint: "auto-refresh",
      newExchangeState: st,
      oldExchangeState: st,
    });
  });
}

export async function processTaskExchangeAutoRefresh(
  wex: WalletExecutionContext,
  exchangeBaseUrl: string,
): Promise<TaskRunResult> {
  logger.trace(`doing auto-refresh check for '${exchangeBaseUrl}'`);

  const oldExchangeRec = await wex.runWalletDbTx(async (tx) => {
    return await tx.getExchange(exchangeBaseUrl);
  });

  if (!oldExchangeRec) {
    return TaskRunResult.finished();
  }

  switch (oldExchangeRec.entryStatus) {
    case ExchangeEntryDbRecordStatus.Preset:
      logger.trace(
        "exchange auto-refresh check not necessary, exchange is preset",
      );
      return TaskRunResult.finished();
  }

  let nextRefreshCheckStamp = timestampAbsoluteFromDb(
    oldExchangeRec.nextRefreshCheckStamp,
  );
  if (
    !AbsoluteTime.isNever(nextRefreshCheckStamp) &&
    !AbsoluteTime.isExpired(nextRefreshCheckStamp)
  ) {
    logger.trace(
      `exchange refresh check for ${exchangeBaseUrl} not necessary, scheduled for ${AbsoluteTime.toIsoString(
        nextRefreshCheckStamp,
      )}`,
    );
    logger.trace(
      "exchange auto-refresh check not necessary, running again later",
    );
    return TaskRunResult.runAgainAt(nextRefreshCheckStamp);
  }

  logger.trace("exchange auto-refresh check necessary");

  await fetchFreshExchange(wex, exchangeBaseUrl);

  await doExchangeAutoRefresh(wex, exchangeBaseUrl);

  return TaskRunResult.progress();
}

/**
 * Write off the coins of denominations the exchange no longer honours.
 *
 * Scoped to one master public key: coins issued under a key the exchange has
 * since replaced are not lost, they are simply not described by the current
 * /keys, and judging them against it would destroy the balance the wallet is
 * meant to be preserving.
 */
export function filterCoinsByExchangeMasterPub(
  coins: WalletCoin[],
  exchangeMasterPub: string,
): WalletCoin[] {
  return coins.filter((coin) => coin.exchangeMasterPub === exchangeMasterPub);
}

async function handleDenomLoss(
  wex: WalletExecutionContext,
  tx: WalletDbTransaction,
  currency: string,
  exchangeBaseUrl: string,
  exchangeMasterPub: string,
): Promise<void> {
  const coinAvailabilityRecs = (
    await tx.getCoinAvailabilityByExchange(exchangeBaseUrl)
  ).filter(
    // Availability rows written before the master pub was recorded are
    // attributed to the current key set, which is where they came from.
    (ca) =>
      ca.exchangeMasterPub == null ||
      ca.exchangeMasterPub === exchangeMasterPub,
  );
  const denomsVanished: string[] = [];
  const denomsRevoked: string[] = [];
  const denomsUnoffered: string[] = [];
  const denomsExpired: string[] = [];
  let amountVanished = Amount.zeroOfCurrency(currency);
  let amountExpired = Amount.zeroOfCurrency(currency);
  let amountRevoked = Amount.zeroOfCurrency(currency);
  let amountUnoffered = Amount.zeroOfCurrency(currency);
  const denominations = await tx.getDenominationsByRefs(coinAvailabilityRecs);
  const denominationsByRef = new Map(
    denominations.map((denom) => [denomRefKey(denom), denom]),
  );
  const coinsByDenomHash = new Map<string, WalletCoin[]>();
  const affectedCoins = filterCoinsByExchangeMasterPub(
    await tx.getCoinsByDenomPubHashes(
      coinAvailabilityRecs.map((availability) => availability.denomPubHash),
    ),
    exchangeMasterPub,
  );
  for (const coin of affectedCoins) {
    const group = coinsByDenomHash.get(coin.denomPubHash) ?? [];
    group.push(coin);
    coinsByDenomHash.set(coin.denomPubHash, group);
  }

  for (const coinAv of coinAvailabilityRecs) {
    if (coinAv.freshCoinCount <= 0) {
      continue;
    }
    const n = coinAv.freshCoinCount;
    const denom = denominationsByRef.get(denomRefKey(coinAv));
    const timestampExpireDeposit = !denom
      ? undefined
      : timestampAbsoluteFromDb(denom.stampExpireDeposit);
    if (!denom) {
      // Remove availability
      coinAv.freshCoinCount = 0;
      coinAv.visibleCoinCount = 0;
      await tx.upsertCoinAvailability(coinAv);
      denomsVanished.push(coinAv.denomPubHash);
      const total = Amount.from(coinAv.value).mult(n);
      amountVanished = amountVanished.add(total);
    } else if (denom.isRevoked) {
      // Checked before isOffered, because the exchange drops a revoked
      // denomination from /keys and it is therefore unoffered as well.
      // Remove availability
      coinAv.freshCoinCount = 0;
      coinAv.visibleCoinCount = 0;
      await tx.upsertCoinAvailability(coinAv);
      denomsRevoked.push(coinAv.denomPubHash);
      const total = Amount.from(coinAv.value).mult(n);
      amountRevoked = amountRevoked.add(total);
    } else if (!denom.isOffered) {
      // Remove availability
      coinAv.freshCoinCount = 0;
      coinAv.visibleCoinCount = 0;
      await tx.upsertCoinAvailability(coinAv);
      denomsUnoffered.push(coinAv.denomPubHash);
      const total = Amount.from(coinAv.value).mult(n);
      amountUnoffered = amountUnoffered.add(total);
    } else if (
      timestampExpireDeposit &&
      AbsoluteTime.isExpired(timestampExpireDeposit)
    ) {
      // Remove availability
      coinAv.freshCoinCount = 0;
      coinAv.visibleCoinCount = 0;
      await tx.upsertCoinAvailability(coinAv);
      denomsExpired.push(coinAv.denomPubHash);
      const total = Amount.from(coinAv.value).mult(n);
      amountExpired = amountExpired.add(total);
    } else {
      // Denomination is still fine!
      continue;
    }

    logger.warn(`denomination ${coinAv.denomPubHash} is a loss`);

    const coins = coinsByDenomHash.get(coinAv.denomPubHash) ?? [];
    for (const coin of coins) {
      switch (coin.status) {
        case CoinStatus.Fresh:
        case CoinStatus.FreshSuspended: {
          coin.status = CoinStatus.DenomLoss;
          await tx.upsertCoin(coin);
          break;
        }
      }
    }
  }

  if (denomsVanished.length > 0) {
    const denomLossEventId = encodeCrock(getRandomBytes(32));
    const rec: WalletDenomLossEvent = {
      denomLossEventId,
      amount: amountVanished.toString(),
      currency,
      exchangeBaseUrl,
      denomPubHashes: denomsVanished,
      eventType: DenomLossEventType.DenomVanished,
      status: DenomLossStatus.Done,
      timestampCreated: timestampPreciseToDb(TalerPreciseTimestamp.now()),
    };
    await tx.upsertDenomLossEvent(rec);
    const ctx = new DenomLossTransactionContext(wex, denomLossEventId);
    await ctx.updateTransactionMeta(tx);
    tx.notify({
      type: NotificationType.TransactionStateTransition,
      causeHint: "denom-vanished",
      transactionId: ctx.transactionId,
      oldTxState: {
        major: TransactionMajorState.None,
      },
      newTxState: {
        major: TransactionMajorState.Done,
      },
      newStId: rec.status,
    });
    tx.notify({
      type: NotificationType.BalanceChange,
      hintTransactionId: ctx.transactionId,
    });
  }

  if (denomsRevoked.length > 0) {
    const denomLossEventId = encodeCrock(getRandomBytes(32));
    const rec: WalletDenomLossEvent = {
      denomLossEventId,
      amount: amountRevoked.toString(),
      currency,
      exchangeBaseUrl,
      denomPubHashes: denomsRevoked,
      eventType: DenomLossEventType.DenomRevoked,
      status: DenomLossStatus.Done,
      timestampCreated: timestampPreciseToDb(TalerPreciseTimestamp.now()),
    };
    await tx.upsertDenomLossEvent(rec);
    const ctx = new DenomLossTransactionContext(wex, denomLossEventId);
    await ctx.updateTransactionMeta(tx);
    tx.notify({
      type: NotificationType.TransactionStateTransition,
      causeHint: "denom-revoked",
      transactionId: ctx.transactionId,
      oldTxState: {
        major: TransactionMajorState.None,
      },
      newTxState: {
        major: TransactionMajorState.Done,
      },
      newStId: rec.status,
    });
    tx.notify({
      type: NotificationType.BalanceChange,
      hintTransactionId: ctx.transactionId,
    });
  }

  if (denomsUnoffered.length > 0) {
    const denomLossEventId = encodeCrock(getRandomBytes(32));
    const rec: WalletDenomLossEvent = {
      denomLossEventId,
      amount: amountUnoffered.toString(),
      currency,
      exchangeBaseUrl,
      denomPubHashes: denomsUnoffered,
      eventType: DenomLossEventType.DenomUnoffered,
      status: DenomLossStatus.Done,
      timestampCreated: timestampPreciseToDb(TalerPreciseTimestamp.now()),
    };
    await tx.upsertDenomLossEvent(rec);
    const ctx = new DenomLossTransactionContext(wex, denomLossEventId);
    await ctx.updateTransactionMeta(tx);
    tx.notify({
      type: NotificationType.TransactionStateTransition,
      causeHint: "denom-unoffered",
      transactionId: ctx.transactionId,
      oldTxState: {
        major: TransactionMajorState.None,
      },
      newTxState: {
        major: TransactionMajorState.Done,
      },
      newStId: rec.status,
    });
    tx.notify({
      type: NotificationType.BalanceChange,
      hintTransactionId: ctx.transactionId,
    });
  }

  if (denomsExpired.length > 0) {
    const denomLossEventId = encodeCrock(getRandomBytes(32));
    const rec: WalletDenomLossEvent = {
      denomLossEventId,
      amount: amountExpired.toString(),
      currency,
      exchangeBaseUrl,
      denomPubHashes: denomsExpired,
      eventType: DenomLossEventType.DenomExpired,
      status: DenomLossStatus.Done,
      timestampCreated: timestampPreciseToDb(TalerPreciseTimestamp.now()),
    };
    await tx.upsertDenomLossEvent(rec);
    const transactionId = constructTransactionIdentifier({
      tag: TransactionType.DenomLoss,
      denomLossEventId,
    });
    tx.notify({
      type: NotificationType.TransactionStateTransition,
      causeHint: "denom-expired",
      transactionId,
      oldTxState: {
        major: TransactionMajorState.None,
      },
      newTxState: {
        major: TransactionMajorState.Done,
      },
      newStId: rec.status,
    });
    tx.notify({
      type: NotificationType.BalanceChange,
      hintTransactionId: transactionId,
    });
  }
}

export function computeDenomLossTransactionStatus(
  rec: WalletDenomLossEvent,
): TransactionState {
  switch (rec.status) {
    case DenomLossStatus.Aborted:
      return {
        major: TransactionMajorState.Aborted,
      };
    case DenomLossStatus.Done:
      return {
        major: TransactionMajorState.Done,
      };
  }
}

export class DenomLossTransactionContext implements TransactionContext {
  transactionId: TransactionIdStr;

  constructor(
    private wex: WalletExecutionContext,
    public denomLossEventId: string,
  ) {
    this.transactionId = constructTransactionIdentifier({
      tag: TransactionType.DenomLoss,
      denomLossEventId,
    });
  }

  get taskId(): TaskIdStr | undefined {
    return undefined;
  }

  async updateTransactionMeta(tx: WalletDbTransaction): Promise<void> {
    const denomLossRec = await tx.getDenomLossEvent(this.denomLossEventId);
    if (!denomLossRec) {
      await tx.deleteTransactionMeta(this.transactionId);
      return;
    }
    await tx.upsertTransactionMeta({
      transactionId: this.transactionId,
      status: denomLossRec.status,
      timestamp: denomLossRec.timestampCreated,
      currency: denomLossRec.currency,
      exchanges: [denomLossRec.exchangeBaseUrl],
    });
  }

  userAbortTransaction(): Promise<void> {
    throw makeTransactionActionUnsupportedError(this.transactionId, "abort");
  }

  userSuspendTransaction(): Promise<void> {
    throw makeTransactionActionUnsupportedError(this.transactionId, "suspend");
  }

  userResumeTransaction(): Promise<void> {
    throw makeTransactionActionUnsupportedError(this.transactionId, "resume");
  }

  userFailTransaction(): Promise<void> {
    throw makeTransactionActionUnsupportedError(this.transactionId, "fail");
  }

  async userDeleteTransaction(): Promise<void> {
    await this.wex.runWalletDbTx(async (tx) => {
      const rec = await tx.getDenomLossEvent(this.denomLossEventId);
      if (!rec) {
        return;
      }
      const oldTxState = computeDenomLossTransactionStatus(rec);
      await tx.deleteDenomLossEvent(this.denomLossEventId);
      applyNotifyTransition(tx.notify, this.transactionId, {
        causeHint: "delete",
        oldTxState,
        newTxState: {
          major: TransactionMajorState.Deleted,
        },
        balanceEffect: BalanceEffect.Any,
        newStId: -1,
        oldStId: rec.status,
      });
    });
  }

  async lookupFullTransaction(
    tx: WalletDbTransaction,
  ): Promise<Transaction | undefined> {
    const rec = await tx.getDenomLossEvent(this.denomLossEventId);
    if (!rec) {
      return undefined;
    }
    const txState = computeDenomLossTransactionStatus(rec);
    return {
      type: TransactionType.DenomLoss,
      txState,
      scopes: await getScopeForAllExchanges(tx, [rec.exchangeBaseUrl]),
      txActions: [TransactionAction.Delete],
      amountRaw: Amounts.stringify(rec.amount),
      amountEffective: Amounts.stringify(rec.amount),
      timestamp: timestampPreciseFromDb(rec.timestampCreated),
      transactionId: constructTransactionIdentifier({
        tag: TransactionType.DenomLoss,
        denomLossEventId: rec.denomLossEventId,
      }),
      lossEventType: rec.eventType,
      exchangeBaseUrl: rec.exchangeBaseUrl,
      stId: rec.status,
    };
  }
}

async function handleRecoup(
  wex: WalletExecutionContext,
  tx: WalletDbTransaction,
  exchangeBaseUrl: string,
  exchangeMasterPub: string,
  recoup: Recoup[],
): Promise<void> {
  // Handle recoup
  const recoupDenomList = recoup;
  const newlyRevokedCoinPubs: string[] = [];
  logger.trace("recoup list from exchange", recoupDenomList);
  const refs = recoupDenomList.map((recoupInfo) => ({
    exchangeMasterPub,
    denomPubHash: recoupInfo.h_denom_pub,
  }));
  const denominations = await tx.getDenominationsByRefs(refs);
  const denominationsByRef = new Map(
    denominations.map((denom) => [denomRefKey(denom), denom]),
  );
  const coinsByDenomHash = new Map<string, WalletCoin[]>();
  const affectedCoins = filterCoinsByExchangeMasterPub(
    await tx.getCoinsByDenomPubHashes(
      recoupDenomList.map((recoupInfo) => recoupInfo.h_denom_pub),
    ),
    exchangeMasterPub,
  );
  for (const coin of affectedCoins) {
    const group = coinsByDenomHash.get(coin.denomPubHash) ?? [];
    group.push(coin);
    coinsByDenomHash.set(coin.denomPubHash, group);
  }
  for (const recoupInfo of recoupDenomList) {
    // A revocation names a denomination of the key set currently in force:
    // it arrives in that key set's own /keys response.
    const ref = {
      exchangeMasterPub: exchangeMasterPub,
      denomPubHash: recoupInfo.h_denom_pub,
    };
    const oldDenom = denominationsByRef.get(denomRefKey(ref));
    if (!oldDenom) {
      // We never even knew about the revoked denomination, all good.
      continue;
    }
    if (oldDenom.isRevoked) {
      // We already marked the denomination as revoked,
      // this implies we revoked all coins
      logger.trace("denom already revoked");
      continue;
    }
    logger.info("revoking denom", recoupInfo.h_denom_pub);
    oldDenom.isRevoked = true;
    await tx.upsertDenomination(oldDenom);
    const affectedCoins = coinsByDenomHash.get(recoupInfo.h_denom_pub) ?? [];
    for (const ac of affectedCoins) {
      newlyRevokedCoinPubs.push(ac.coinPub);
    }
  }
  if (newlyRevokedCoinPubs.length != 0) {
    logger.info("recouping coins", newlyRevokedCoinPubs);
    await createRecoupGroup(wex, tx, exchangeBaseUrl, newlyRevokedCoinPubs);
  }
}

function getAutoRefreshExecuteThresholdForDenom(
  d: WalletDenomination,
): AbsoluteTime {
  return getAutoRefreshExecuteThreshold({
    stampExpireWithdraw: timestampProtocolFromDb(d.stampExpireWithdraw),
    stampExpireDeposit: timestampProtocolFromDb(d.stampExpireDeposit),
  });
}

/**
 * Timestamp after which the wallet would do the next check for an auto-refresh.
 */
function getAutoRefreshCheckThreshold(d: WalletDenomination): AbsoluteTime {
  const expireWithdraw = AbsoluteTime.fromProtocolTimestamp(
    timestampProtocolFromDb(d.stampExpireWithdraw),
  );
  const expireDeposit = AbsoluteTime.fromProtocolTimestamp(
    timestampProtocolFromDb(d.stampExpireDeposit),
  );
  const delta = AbsoluteTime.difference(expireWithdraw, expireDeposit);
  const deltaDiv = durationMul(delta, 0.75);
  return AbsoluteTime.addDuration(expireWithdraw, deltaDiv);
}

/**
 * Find a payto:// URI of the exchange that is of one
 * of the given target types.
 *
 * Throws if no matching account was found.
 */
export async function getExchangePaytoUri(
  wex: WalletExecutionContext,
  exchangeBaseUrl: string,
  supportedTargetTypes: string[],
): Promise<string> {
  // We do the update here, since the exchange might not even exist
  // yet in our database.
  const details = await wex.runWalletDbTx(async (tx) => {
    return getExchangeRecordsInternal(tx, exchangeBaseUrl);
  });
  const accounts = details?.wireInfo.accounts ?? [];
  for (const account of accounts) {
    const res = Result.orUndefined(Paytos.fromString(account.payto_uri));
    if (!res) {
      continue;
    }
    if (supportedTargetTypes.includes(res.targetType!)) {
      return account.payto_uri;
    }
  }
  throw TalerError.fromDetail(
    TalerErrorCode.WALLET_NO_SUITABLE_EXCHANGE,
    { wireMethod: supportedTargetTypes[0] },
    `no matching account found at exchange ${exchangeBaseUrl} for wire types ${j2s(
      supportedTargetTypes,
    )}`,
  );
}

/**
 * Get the exchange ToS in the requested format.
 * Try to download in the accepted format not cached.
 */
export async function getExchangeTos(
  wex: WalletExecutionContext,
  exchangeBaseUrl: string,
  acceptedFormat?: string[],
  acceptLanguage?: string,
): Promise<GetExchangeTosResult> {
  // noBail follows the progress context (see fetchFreshExchange): with a token
  // we keep waiting for the exchange rather than give up on it.
  const exch = await fetchFreshExchangeWithRetryNow(wex, exchangeBaseUrl);

  switch (exch.tosStatus) {
    case ExchangeTosStatus.MissingTos:
      return {
        tosStatus: ExchangeTosStatus.MissingTos,
        acceptedEtag: undefined,
        contentLanguage: undefined,
        contentType: "text/plain",
        content: "NULL",
        currentEtag: "NULL",
        tosAvailableLanguages: [],
      };
  }

  const exchangeClient = new TalerExchangeHttpClient(exchangeBaseUrl, {
    cancelationToken: wex.cancellationToken,
    httpClient: wex.http,
  });

  let tosDownload: ExchangeTosDownloadResult = await runWithProgressRetries(
    wex,
    async () => {
      const tosRes = await exchangeClient.getTermsText({
        acceptFormats: acceptedFormat,
        acceptLanguage: acceptLanguage,
      });
      succeedOrThrow(tosRes);

      return {
        tosAvailableLanguages:
          tosRes.response.headers.get("avail-languages")?.split(",") ?? [],
        tosContentLanguage:
          tosRes.response.headers.get("content-language") ?? "en",
        tosContentType:
          tosRes.response.headers.get("content-type") ?? "text/plain",
        tosEtag: tosRes.response.headers.get("etag") ?? "",
        tosText: tosRes.body.text,
      };
    },
  );

  checkLogicInvariant(!!tosDownload);

  await wex.runWalletDbTx(async (tx) => {
    const updateExchangeEntry = await tx.getExchange(exchangeBaseUrl);
    if (updateExchangeEntry) {
      updateExchangeEntry.tosCurrentEtag = tosDownload.tosEtag;
      wex.ws.exchangeCache.clear();
      await tx.upsertExchange(updateExchangeEntry);
    }
  });

  return {
    acceptedEtag: exch.tosAcceptedEtag,
    currentEtag: tosDownload.tosEtag,
    content: tosDownload.tosText,
    contentType: tosDownload.tosContentType,
    contentLanguage: tosDownload.tosContentLanguage,
    tosStatus: exch.tosStatus,
    tosAvailableLanguages: tosDownload.tosAvailableLanguages,
  };
}

/**
 * Parsed information about an exchange,
 * obtained by requesting /keys.
 */
export interface ExchangeInfo {
  keys: ExchangeKeysResponse;
}

/**
 * Helper function to download the exchange /keys info.
 *
 * Only used for testing / dbless wallet.
 */
export async function downloadExchangeInfo(
  exchangeBaseUrl: string,
  http: HttpRequestLibrary,
): Promise<ExchangeInfo> {
  const keysInfo = await downloadExchangeKeysInfo(
    exchangeBaseUrl,
    http,
    Duration.getForever(),
    CancellationToken.CONTINUE,
    false,
  );
  if (keysInfo.type !== "ok") {
    throw Error(`bad keys download: ${keysInfo.type}`);
  }
  return {
    keys: keysInfo.res,
  };
}

/**
 * List all exchange entries known to the wallet.
 */
interface ExchangeListItemInternal {
  item: ExchangeListItem;
  record: WalletExchangeEntry;
}

async function listExchangeItemsInternal(
  wex: WalletExecutionContext,
  req: ListExchangesRequest,
): Promise<ExchangeListItemInternal[]> {
  const exchanges: ExchangeListItemInternal[] = [];
  await wex.runWalletDbTx(async (tx) => {
    const exchangeRecords = await tx.getExchanges();
    for (const exchangeRec of exchangeRecords) {
      const taskId = constructTaskIdentifier({
        tag: PendingTaskType.ExchangeUpdate,
        exchangeBaseUrl: exchangeRec.baseUrl,
      });
      const exchangeDetails = await getExchangeRecordsInternal(
        tx,
        exchangeRec.baseUrl,
      );
      const opRetryRecord = await tx.getOperationRetry(taskId);
      let reserveRec: WalletReserve | undefined = undefined;
      if (exchangeRec.currentMergeReserveRowId != null) {
        reserveRec = await tx.getReserve(exchangeRec.currentMergeReserveRowId);
        checkDbInvariant(!!reserveRec, "reserve record not found");
      }
      if (
        req.filterByType != null &&
        exchangeRec.presetType != null &&
        exchangeRec.presetType != req.filterByType
      ) {
        continue;
      }
      if (req.filterByScope) {
        const inScope = await checkExchangeInScopeTx(
          tx,
          exchangeRec.baseUrl,
          req.filterByScope,
        );
        if (!inScope) {
          continue;
        }
      }
      const li = await makeExchangeListItem(
        wex,
        tx,
        exchangeRec,
        exchangeDetails,
        reserveRec,
        opRetryRecord?.lastError,
      );
      if (req.filterByExchangeEntryStatus) {
        if (req.filterByExchangeEntryStatus !== li.exchangeEntryStatus) {
          continue;
        }
      }
      exchanges.push({ item: li, record: exchangeRec });
    }
  });
  return exchanges;
}

/**
 * List all exchange entries known to the wallet.
 */
export async function listExchanges(
  wex: WalletExecutionContext,
  req: ListExchangesRequest,
): Promise<ExchangesListResponse> {
  const items = await listExchangeItemsInternal(wex, req);
  return { exchanges: items.map((x) => x.item) };
}

function hasPresetMetadata(record: WalletExchangeEntry): boolean {
  return (
    record.source === ExchangeEntrySource.Builtin || record.presetType != null
  );
}

function builtinTypeRequested(
  type: BuiltinExchange["type"],
  req: ListWithdrawalExchangeCandidatesRequest,
): boolean {
  switch (type) {
    case "prod":
      return true;
    case "demo":
      return req.withDemo === true;
    case "test":
      return req.withTest === true;
  }
}

function makeBuiltinExchangeCandidate(
  exchange: BuiltinExchange,
): WithdrawalExchangeCandidate {
  return {
    talerUri: TalerUris.stringify({
      type: TalerUriAction.WithdrawExchange,
      exchangeBaseUrl: exchange.exchangeBaseUrl as HostPortPath,
    }),
    exchangeBaseUrl: exchange.exchangeBaseUrl,
    currency: exchange.currencyHint,
    currencySpec: exchange.currencySpec ?? {
      alt_unit_names: {},
      name: exchange.currencyHint,
      num_fractional_input_digits: 2,
      num_fractional_normal_digits: 2,
      num_fractional_trailing_zero_digits: 2,
    },
    exchangeEntryStatus: ExchangeEntryStatus.Preset,
    exchangeUpdateStatus: ExchangeUpdateStatus.Initial,
    source: ExchangeEntrySource.Builtin,
    recommendationReasons: [ExchangeRecommendationReason.Preset],
  };
}

/**
 * List exchanges suitable for presentation in a withdrawal chooser.
 */
export async function listWithdrawalExchangeCandidates(
  wex: WalletExecutionContext,
  req: ListWithdrawalExchangeCandidatesRequest,
): Promise<ListWithdrawalExchangeCandidatesResponse> {
  if (req.presetOnly && req.withBuiltin === false) {
    throw TalerError.fromDetail(
      TalerErrorCode.WALLET_CORE_API_BAD_REQUEST,
      { parameter: "withBuiltin" },
      "presetOnly cannot be combined with withBuiltin=false",
    );
  }

  const builtinByUrl = new Map(
    builtinExchanges.map((exchange) => [exchange.exchangeBaseUrl, exchange]),
  );
  const items = await listExchangeItemsInternal(wex, {});
  const candidatesByUrl = new Map<string, WithdrawalExchangeCandidate>();
  const databaseCandidates = items
    .filter(({ item, record }) => {
      if (
        item.exchangeEntryStatus === ExchangeEntryStatus.Ephemeral ||
        item.currency === "UNKNOWN"
      ) {
        return false;
      }
      const builtin = builtinByUrl.get(item.exchangeBaseUrl);
      if (req.presetOnly) {
        return builtin?.type === "prod";
      }
      const presetType = getEffectiveExchangeType(
        item.exchangeBaseUrl,
        record.presetType,
      );
      if (
        presetType === "demo" ||
        presetType === "test" ||
        presetType === "prod"
      ) {
        return builtinTypeRequested(presetType, req);
      }
      return true;
    })
    .map(({ item, record }) => {
      const source = getExchangeEntrySource(record);
      const recommendationReasons: ExchangeRecommendationReason[] = [];
      if (hasPresetMetadata(record)) {
        recommendationReasons.push(ExchangeRecommendationReason.Preset);
      }
      if (source === ExchangeEntrySource.User) {
        recommendationReasons.push(ExchangeRecommendationReason.UserAdded);
      }
      if (item.lastWithdrawal != null) {
        recommendationReasons.push(
          ExchangeRecommendationReason.PreviousWithdrawal,
        );
      } else if (
        item.exchangeEntryStatus === ExchangeEntryStatus.Used &&
        source !== ExchangeEntrySource.User
      ) {
        recommendationReasons.push(ExchangeRecommendationReason.PreviouslyUsed);
      }
      return {
        talerUri: TalerUris.stringify({
          type: TalerUriAction.WithdrawExchange,
          exchangeBaseUrl: item.exchangeBaseUrl as HostPortPath,
        }),
        exchangeBaseUrl: item.exchangeBaseUrl,
        currency: item.currency,
        currencySpec: item.currencySpec,
        exchangeEntryStatus: item.exchangeEntryStatus,
        exchangeUpdateStatus: item.exchangeUpdateStatus,
        source,
        recommendationReasons,
        ...(item.lastWithdrawal != null
          ? { lastWithdrawal: item.lastWithdrawal }
          : undefined),
      } satisfies WithdrawalExchangeCandidate;
    });

  for (const candidate of databaseCandidates) {
    candidatesByUrl.set(candidate.exchangeBaseUrl, candidate);
  }

  if (req.withBuiltin !== false) {
    for (const exchange of builtinExchanges) {
      if (
        req.presetOnly
          ? exchange.type !== "prod"
          : !builtinTypeRequested(exchange.type, req)
      ) {
        continue;
      }
      if (!candidatesByUrl.has(exchange.exchangeBaseUrl)) {
        candidatesByUrl.set(
          exchange.exchangeBaseUrl,
          makeBuiltinExchangeCandidate(exchange),
        );
      }
    }
  }

  const candidates = [...candidatesByUrl.values()];

  candidates.sort((a, b) => {
    if (a.lastWithdrawal != null || b.lastWithdrawal != null) {
      if (a.lastWithdrawal == null) return 1;
      if (b.lastWithdrawal == null) return -1;
      const byWithdrawal = AbsoluteTime.cmp(
        AbsoluteTime.fromPreciseTimestamp(b.lastWithdrawal),
        AbsoluteTime.fromPreciseTimestamp(a.lastWithdrawal),
      );
      if (byWithdrawal !== 0) return byWithdrawal;
    }
    const rank = (candidate: (typeof candidates)[number]): number => {
      if (candidate.source === ExchangeEntrySource.User) return 0;
      if (candidate.exchangeEntryStatus === ExchangeEntryStatus.Used) return 1;
      if (
        candidate.recommendationReasons.includes(
          ExchangeRecommendationReason.Preset,
        )
      ) {
        return 2;
      }
      return 3;
    };
    return (
      rank(a) - rank(b) || a.exchangeBaseUrl.localeCompare(b.exchangeBaseUrl)
    );
  });

  return { candidates };
}

/**
 * Transition an exchange to the "used" entry state if necessary.
 *
 * Should be called whenever the exchange is actively used by the client (for withdrawals etc.).
 *
 * The caller should emit the returned notification iff the current transaction
 * succeeded.
 */
export async function markExchangeUsed(
  tx: WalletDbTransaction,
  exchangeBaseUrl: string,
): Promise<void> {
  logger.trace(`marking exchange ${exchangeBaseUrl} as used`);
  const exch = await tx.getExchange(exchangeBaseUrl);
  if (!exch) {
    logger.info(`exchange ${exchangeBaseUrl} NOT found`);
    return;
  }

  const oldExchangeState = getExchangeState(exch);
  switch (exch.entryStatus) {
    case ExchangeEntryDbRecordStatus.Ephemeral:
    case ExchangeEntryDbRecordStatus.Preset: {
      exch.entryStatus = ExchangeEntryDbRecordStatus.Used;
      await tx.upsertExchange(exch);
      const newExchangeState = getExchangeState(exch);
      tx.notify({
        type: NotificationType.ExchangeStateTransition,
        exchangeBaseUrl,
        causeHint: "mark-used",
        newExchangeState: newExchangeState,
        oldExchangeState: oldExchangeState,
      });
      return;
    }
    default:
      return;
  }
}

/** Record that the user explicitly chose to retain an exchange. */
export async function markExchangeAddedByUser(
  tx: WalletDbTransaction,
  exchangeBaseUrl: string,
): Promise<void> {
  const exchange = await tx.getExchange(exchangeBaseUrl);
  if (!exchange) {
    return;
  }
  exchange.source = ExchangeEntrySource.User;
  await tx.upsertExchange(exchange);
  await markExchangeUsed(tx, exchangeBaseUrl);
}

/**
 * Get detailed information about the exchange including a timeline
 * for the fees charged by the exchange.
 */
export async function getExchangeDetailedInfo(
  wex: WalletExecutionContext,
  exchangeBaseurl: string,
): Promise<ExchangeDetailedResponse> {
  const exchange = await wex.runWalletDbTx(async (tx) => {
    const ex = await tx.getExchange(exchangeBaseurl);
    const dp = ex?.detailsPointer;
    if (!dp) {
      return;
    }
    const { currency } = dp;
    const exchangeDetails = await getExchangeRecordsInternal(tx, ex.baseUrl);
    if (!exchangeDetails) {
      return;
    }
    const denominationRecords = await getAllDenominationsForExchange(
      tx,
      ex.baseUrl,
    );

    if (!denominationRecords) {
      return;
    }

    const denominations: DenominationInfo[] = denominationRecords.map((x) =>
      WalletDenomination.toDenomInfo(x),
    );

    return {
      info: {
        exchangeBaseUrl: ex.baseUrl,
        currency,
        paytoUris: exchangeDetails.wireInfo.accounts.map((x) => x.payto_uri),
        auditors: exchangeDetails.auditors.map((auditor) => ({
          auditor_pub: auditor.auditor_pub,
          auditor_url: auditor.auditor_url,
          auditor_name: auditor.auditor_name,
          denomination_keys: auditor.denomination_keys,
        })),
        wireInfo: exchangeDetails.wireInfo,
        globalFees: exchangeDetails.globalFees,
      },
      denominations,
    };
  });

  if (!exchange) {
    throw TalerError.fromDetail(
      TalerErrorCode.WALLET_EXCHANGE_ENTRY_NOT_FOUND,
      {},
      `exchange with base URL "${exchangeBaseurl}" not found`,
    );
  }

  const denoms = exchange.denominations.map((d) => ({
    ...d,
    group: Amounts.stringifyValue(d.value),
  }));
  const denomFees: DenomOperationMap<FeeDescription[]> = {
    deposit: createTimeline(
      denoms,
      "denomPubHash",
      "stampStart",
      "stampExpireDeposit",
      "feeDeposit",
      "group",
      selectBestForOverlappingDenominations,
    ),
    refresh: createTimeline(
      denoms,
      "denomPubHash",
      "stampStart",
      "stampExpireWithdraw",
      "feeRefresh",
      "group",
      selectBestForOverlappingDenominations,
    ),
    refund: createTimeline(
      denoms,
      "denomPubHash",
      "stampStart",
      "stampExpireWithdraw",
      "feeRefund",
      "group",
      selectBestForOverlappingDenominations,
    ),
    withdraw: createTimeline(
      denoms,
      "denomPubHash",
      "stampStart",
      "stampExpireWithdraw",
      "feeWithdraw",
      "group",
      selectBestForOverlappingDenominations,
    ),
  };

  const transferFees = Object.entries(
    exchange.info.wireInfo.feesForType,
  ).reduce(
    (prev, [wireType, infoForType]) => {
      const feesByGroup = [
        ...infoForType.map((w) => ({
          ...w,
          fee: Amounts.stringify(w.closingFee),
          group: "closing",
        })),
        ...infoForType.map((w) => ({ ...w, fee: w.wireFee, group: "wire" })),
      ];
      prev[wireType] = createTimeline(
        feesByGroup,
        "sig",
        "startStamp",
        "endStamp",
        "fee",
        "group",
        selectMinimumFee,
      );
      return prev;
    },
    {} as Record<string, FeeDescription[]>,
  );

  const globalFeesByGroup = [
    ...exchange.info.globalFees.map((w) => ({
      ...w,
      fee: w.accountFee,
      group: "account",
    })),
    ...exchange.info.globalFees.map((w) => ({
      ...w,
      fee: w.historyFee,
      group: "history",
    })),
    ...exchange.info.globalFees.map((w) => ({
      ...w,
      fee: w.purseFee,
      group: "purse",
    })),
  ];

  const globalFees = createTimeline(
    globalFeesByGroup,
    "signature",
    "startDate",
    "endDate",
    "fee",
    "group",
    selectMinimumFee,
  );

  return {
    exchange: {
      ...exchange.info,
      denomFees,
      transferFees,
      globalFees,
    },
  };
}

async function internalGetExchangeResources(
  tx: WalletDbTransaction,
  exchangeBaseUrl: string,
): Promise<GetExchangeResourcesResponse> {
  let numWithdrawals = 0;
  let numCoins = 0;
  numCoins = await tx.countCoinsByExchange(exchangeBaseUrl);
  numWithdrawals = await tx.countWithdrawalGroupsByExchange(exchangeBaseUrl);
  const total = numWithdrawals + numCoins;
  return {
    hasResources: total != 0,
  };
}

/**
 * Purge information in the database associated with the exchange.
 *
 * Deletes information specific to the exchange and withdrawals,
 * but keeps some transactions (payments, p2p, refreshes) around.
 */
async function purgeExchange(
  wex: WalletExecutionContext,
  tx: WalletDbTransaction,
  exchangeRec: WalletExchangeEntry,
  purgeTransactions?: boolean,
): Promise<void> {
  const exchangeBaseUrl = exchangeRec.baseUrl;
  const detRecs = await tx.listAllExchangeDetails();
  // Remove all exchange detail records for that exchange
  for (const r of detRecs) {
    if (r.rowId == null) {
      // Should never happen, as rowId is the primary key.
      continue;
    }
    if (r.exchangeBaseUrl !== exchangeBaseUrl) {
      continue;
    }
    await tx.deleteExchangeDetails(r.rowId);
    const signkeyRecs = await tx.getExchangeSignKeysByDetailsRowId(r.rowId);
    for (const rec of signkeyRecs) {
      await tx.deleteExchangeSignKey(r.rowId, rec.signkeyPub);
    }
  }

  const oldExchangeState = getExchangeState(exchangeRec);

  await tx.deleteExchange(exchangeBaseUrl);
  tx.notify({
    type: NotificationType.ExchangeStateTransition,
    oldExchangeState,
    causeHint: "purge",
    newExchangeState: undefined,
    exchangeBaseUrl,
  });

  {
    const coinAvailabilityRecs =
      await tx.getCoinAvailabilityByExchange(exchangeBaseUrl);
    for (const rec of coinAvailabilityRecs) {
      await tx.deleteCoinAvailability(rec);
    }
  }

  {
    const coinRecs = await tx.getCoinsByExchange(exchangeBaseUrl);
    for (const rec of coinRecs) {
      await tx.deleteCoin(rec.coinPub);
      await tx.deleteCoinHistory(rec.coinPub);
    }
  }

  {
    const denomRecs = await getAllDenominationsForExchange(tx, exchangeBaseUrl);
    for (const rec of denomRecs) {
      await tx.deleteDenomination(rec);
    }
  }

  {
    const denomFamilyRecs =
      await tx.getDenominationFamiliesByExchange(exchangeBaseUrl);
    for (const rec of denomFamilyRecs) {
      checkDbInvariant(
        rec.denominationFamilySerial != null,
        "denominationFamilySerial",
      );
      await tx.deleteDenominationFamily(rec.denominationFamilySerial);
    }
  }

  // Always delete withdrawals, even if no explicit
  // transaction deletion was requested.
  {
    const withdrawalGroupRecs =
      await tx.getWithdrawalGroupsByExchange(exchangeBaseUrl);
    for (const wg of withdrawalGroupRecs) {
      const ctx = new WithdrawTransactionContext(wex, wg.withdrawalGroupId);
      await ctx.deleteTransactionInTx(tx);
    }
  }

  if (purgeTransactions) {
    // Remove from refreshGroups and refreshSessions
    {
      const refreshGroups = await tx.listAllRefreshGroups();
      for (const rg of refreshGroups) {
        if (rg.infoPerExchange && rg.infoPerExchange[exchangeBaseUrl] != null) {
          const ctx = new RefreshTransactionContext(wex, rg.refreshGroupId);
          await ctx.deleteTransactionInTx(tx);
        }
      }
    }
    // Remove from recoupGroups
    {
      const recoupGroups = await tx.getRecoupGroupsByExchange(exchangeBaseUrl);
      for (const rg of recoupGroups) {
        const ctx = new RecoupTransactionContext(wex, rg.recoupGroupId);
        await ctx.deleteTransactionInTx(tx);
      }
    }
    // Remove from deposits
    {
      // FIXME: Index would be useful here
      const depositGroups = await tx.listAllDepositGroups();
      for (const dg of depositGroups) {
        if (dg.infoPerExchange && dg.infoPerExchange[exchangeBaseUrl]) {
          const ctx = new DepositTransactionContext(wex, dg.depositGroupId);
          await ctx.deleteTransactionInTx(tx);
        }
      }
    }
    // Remove from purchases, refundGroups, refundItems
    {
      const purchases = await tx.getPurchasesByExchange(exchangeBaseUrl);
      for (const purch of purchases) {
        const refunds = await tx.getRefundGroupsByProposal(purch.proposalId);
        for (const r of refunds) {
          const refundCtx = new RefundTransactionContext(wex, r.refundGroupId);
          await refundCtx.deleteTransactionInTx(tx);
        }
        const payCtx = new PayMerchantTransactionContext(wex, purch.proposalId);
        const res = await payCtx.deleteTransactionInTx(tx);
      }
    }
    // Remove from peerPullCredit
    {
      const recs = await tx.listAllPeerPullCredits();
      for (const rec of recs) {
        if (rec.exchangeBaseUrl === exchangeBaseUrl) {
          const ctx = new PeerPullCreditTransactionContext(wex, rec.pursePub);
          await ctx.deleteTransactionInTx(tx);
        }
      }
    }
    // Remove from peerPullDebit
    {
      const recs = await tx.listAllPeerPullDebits();
      for (const rec of recs) {
        if (rec.exchangeBaseUrl === exchangeBaseUrl) {
          const ctx = new PeerPullDebitTransactionContext(
            wex,
            rec.peerPullDebitId,
          );
          await ctx.deleteTransactionInTx(tx);
        }
      }
    }
    // Remove from peerPushCredit
    {
      const recs = await tx.listAllPeerPushCredits();
      for (const rec of recs) {
        if (rec.exchangeBaseUrl === exchangeBaseUrl) {
          const ctx = new PeerPushCreditTransactionContext(
            wex,
            rec.peerPushCreditId,
          );
          await ctx.deleteTransactionInTx(tx);
        }
      }
    }
    // Remove from peerPushDebit
    {
      const recs = await tx.listAllPeerPushDebits();
      for (const rec of recs) {
        if (rec.exchangeBaseUrl === exchangeBaseUrl) {
          const ctx = new PeerPushDebitTransactionContext(wex, rec.pursePub);
          await ctx.deleteTransactionInTx(tx);
        }
      }
    }
  }

  // FIXME: Is this even necessary? Each deletion should already do it.
  await rematerializeTransactions(wex, tx);
}

/**
 * Remove all exchange entries that are still ephemeral, i.e. that the wallet
 * only ever contacted to show something about them (fees, terms of service,
 * ...) without anything in the wallet depending on them.
 *
 * Must be called before the task loop is started, while no operation of our
 * own can be in flight: an ephemeral entry in the DB is then necessarily left
 * over from a previous run of the wallet.
 *
 * An entry the wallet depends on is never ephemeral, since every resource
 * created at an exchange (a transaction, an account, a reserve) marks the
 * entry as used.  An ephemeral entry that is in use anyway means that the
 * marking was missed somewhere, so such an entry is repaired instead of
 * being removed.
 */
export async function deleteEphemeralExchanges(
  wex: WalletExecutionContext,
): Promise<void> {
  const numDeleted = await wex.runWalletDbTx(async (tx) => {
    let n = 0;
    const exchangeRecs = (await tx.getExchanges()).filter(
      (x) => x.entryStatus === ExchangeEntryDbRecordStatus.Ephemeral,
    );
    if (exchangeRecs.length === 0) {
      return 0;
    }
    const exchangesInTransactions = new Set<string>();
    const metaRecs = await tx.listTransactionMetaByStatus({
      onlyActive: false,
    });
    for (const metaRec of metaRecs) {
      for (const exchangeBaseUrl of metaRec.exchanges) {
        exchangesInTransactions.add(exchangeBaseUrl);
      }
    }
    for (const exchangeRec of exchangeRecs) {
      const res = await internalGetExchangeResources(tx, exchangeRec.baseUrl);
      if (
        res.hasResources ||
        exchangesInTransactions.has(exchangeRec.baseUrl)
      ) {
        // Whatever depends on the exchange should have marked the entry as
        // used when it was created.  Removing the entry anyway would silently
        // discard it, so repair the entry status instead.
        logger.warn(
          `ephemeral exchange entry ${exchangeRec.baseUrl} is in use, marking it as used instead of removing it`,
        );
        await markExchangeUsed(tx, exchangeRec.baseUrl);
        continue;
      }
      logger.info(`removing ephemeral exchange entry ${exchangeRec.baseUrl}`);
      await purgeExchange(wex, tx, exchangeRec, true);
      n++;
    }
    return n;
  });
  if (numDeleted > 0) {
    wex.ws.exchangeCache.clear();
  }
}

export async function deleteExchange(
  wex: WalletExecutionContext,
  req: DeleteExchangeRequest,
): Promise<void> {
  let inUse: boolean = false;
  const exchangeBaseUrl = req.exchangeBaseUrl;
  await wex.runWalletDbTx(async (tx) => {
    const exchangeRec = await tx.getExchange(exchangeBaseUrl);
    if (!exchangeRec) {
      // Nothing to delete!
      logger.info("no exchange found to delete");
      return;
    }
    const res = await internalGetExchangeResources(tx, exchangeBaseUrl);
    if (res.hasResources && !req.purge) {
      inUse = true;
      return;
    }
    await purgeExchange(wex, tx, exchangeRec, true);
    wex.ws.exchangeCache.clear();
    return;
  });

  if (inUse) {
    throw TalerError.fromUncheckedDetail({
      code: TalerErrorCode.WALLET_EXCHANGE_ENTRY_USED,
      hint: "Exchange in use.",
    });
  }
}

export async function getExchangeResources(
  wex: WalletExecutionContext,
  exchangeBaseUrl: string,
): Promise<GetExchangeResourcesResponse> {
  // Withdrawals include internal withdrawals from peer transactions
  const res = await wex.runWalletDbTx(async (tx) => {
    const exchangeRecord = await tx.getExchange(exchangeBaseUrl);
    if (!exchangeRecord) {
      return undefined;
    }
    return internalGetExchangeResources(tx, exchangeBaseUrl);
  });
  if (!res) {
    throw Error("exchange not found");
  }
  return res;
}

/**
 * Find the currently applicable wire fee for an exchange.
 */
export async function getExchangeWireFee(
  wex: WalletExecutionContext,
  wireType: string,
  baseUrl: string,
  time: TalerProtocolTimestamp,
): Promise<WireFee> {
  const exchangeDetails = await wex.runWalletDbTx(async (tx) => {
    const ex = await tx.getExchange(baseUrl);
    if (!ex || !ex.detailsPointer) return undefined;
    return await tx.getExchangeDetailsByPointer(
      baseUrl,
      ex.detailsPointer.currency,
      ex.detailsPointer.masterPublicKey,
    );
  });

  if (!exchangeDetails) {
    throw Error(`exchange missing: ${baseUrl}`);
  }

  return findExchangeWireFee(exchangeDetails, wireType, time);
}

/** Find the applicable wire fee in already-loaded exchange details. */
export function findExchangeWireFee(
  exchangeDetails: WalletExchangeDetails,
  wireType: string,
  time: TalerProtocolTimestamp,
): WireFee {
  const fees = exchangeDetails.wireInfo.feesForType[wireType];
  if (!fees || fees.length === 0) {
    throw Error(
      `exchange ${exchangeDetails.exchangeBaseUrl} doesn't have fees for wire type ${wireType}`,
    );
  }
  const fee = fees.find((x) => {
    return AbsoluteTime.isBetween(
      AbsoluteTime.fromProtocolTimestamp(time),
      AbsoluteTime.fromProtocolTimestamp(x.startStamp),
      AbsoluteTime.fromProtocolTimestamp(x.endStamp),
    );
  });
  if (!fee) {
    throw Error(
      `exchange ${exchangeDetails.exchangeBaseUrl} doesn't have fees for wire type ${wireType} at ${time.t_s}`,
    );
  }

  return fee;
}

export type BalanceThresholdCheckResult =
  | {
      result: "ok";
    }
  | {
      result: "violation";
      /** Threshold that needs to be requested to proceed. */
      nextThreshold: AmountString;
      walletKycStatus: ExchangeWalletKycStatus | undefined;
      walletKycAccessToken: string | undefined;
    };

export async function checkIncomingAmountLegalUnderKycBalanceThreshold(
  wex: WalletExecutionContext,
  exchangeBaseUrl: string,
  amountIncoming: AmountLike,
): Promise<BalanceThresholdCheckResult> {
  logger.trace(`checking ${exchangeBaseUrl} +${amountIncoming} for KYC`);
  return await wex.runWalletDbTx(
    async (tx): Promise<BalanceThresholdCheckResult> => {
      const exchangeRec = await tx.getExchange(exchangeBaseUrl);
      if (!exchangeRec) {
        throw Error("exchange not found");
      }
      const det = await getExchangeRecordsInternal(tx, exchangeBaseUrl);
      if (!det) {
        throw Error("exchange not found");
      }
      const coinAvRecs =
        await tx.getCoinAvailabilityByExchange(exchangeBaseUrl);
      let balAmount = Amounts.zeroOfCurrency(det.currency);
      for (const av of coinAvRecs) {
        const n = av.freshCoinCount + (av.pendingRefreshOutputCount ?? 0);
        balAmount = Amounts.add(
          balAmount,
          Amounts.mult(av.value, n).amount,
        ).amount;
      }
      const balExpected = Amounts.add(balAmount, amountIncoming).amount;

      // Check if we already have KYC for a sufficient threshold.

      const reserveId = exchangeRec.currentMergeReserveRowId;
      let reserveRec: WalletReserve | undefined;
      if (reserveId) {
        reserveRec = await tx.getReserve(reserveId);
        checkDbInvariant(!!reserveRec, "reserve");
        // FIXME: also consider KYC expiration!
        if (reserveRec.thresholdNext) {
          logger.trace(
            `Checking expected balance ${Amounts.stringify(
              balExpected,
            )} against threshold ${Amounts.stringify(
              reserveRec.thresholdNext,
            )}`,
          );
          if (Amounts.cmp(balExpected, reserveRec.thresholdNext) <= 0) {
            logger.trace(
              `Next threshold ${Amounts.stringify(
                reserveRec.thresholdNext,
              )} not yet breached`,
            );
            return {
              result: "ok",
            };
          }
        } else if (reserveRec.status === ReserveRecordStatus.Done) {
          // We don't know what the next threshold is, but we've passed *some* KYC
          // check. We don't have enough information, so we allow the balance increase.
          logger.warn(
            `No next balance threshold, assuming balance KYC is okay`,
          );
          return {
            result: "ok",
          };
        }
      }

      // No luck, check the next limit we should request, if any.

      const limits = det.walletBalanceLimits;
      if (!limits) {
        logger.info("no balance limits defined");
        return {
          result: "ok",
        };
      }
      limits.sort((a, b) => Amounts.cmp(a, b));
      logger.trace(`applicable limits: ${j2s(limits)}`);
      let limViolated: AmountString | undefined = undefined;
      // A threshold is only crossed once the balance exceeds it, reaching it
      // exactly is still allowed.
      for (let i = 0; i < limits.length; i++) {
        if (Amounts.cmp(limits[i], balExpected) < 0) {
          limViolated = limits[i];
          const limNext = limits[i + 1];
          if (limNext == null || Amounts.cmp(limNext, balExpected) >= 0) {
            break;
          }
        }
      }
      if (!limViolated) {
        logger.trace("balance limit okay");
        return {
          result: "ok",
        };
      } else {
        logger.info(`balance limit ${limViolated} would be violated`);
        return {
          result: "violation",
          nextThreshold: limViolated,
          walletKycStatus: reserveRec?.status
            ? getKycStatusFromReserveStatus(reserveRec.status)
            : undefined,
          walletKycAccessToken: reserveRec?.kycAccessToken,
        };
      }
    },
  );
}

/**
 * Wait until kyc has passed for the wallet.
 *
 * If passed==false, already return when legitimization
 * is requested.
 */
export async function waitExchangeWalletKyc(
  wex: WalletExecutionContext,
  exchangeBaseUrl: string,
  amount: AmountLike,
  passed: boolean,
): Promise<void> {
  await genericWaitForState(wex, {
    async checkState(): Promise<boolean> {
      return await wex.runWalletDbTx(async (tx) => {
        const exchange = await tx.getExchange(exchangeBaseUrl);
        if (!exchange) {
          throw new Error("exchange not found");
        }
        const reserveId = exchange.currentMergeReserveRowId;
        if (reserveId == null) {
          logger.warn("KYC does not exist yet");
          return false;
        }
        const reserve = await tx.getReserve(reserveId);
        if (!reserve) {
          throw Error("reserve not found");
        }
        if (passed) {
          if (
            reserve.thresholdGranted &&
            Amounts.cmp(reserve.thresholdGranted, amount) >= 0
          ) {
            return true;
          }
          return false;
        } else {
          if (
            reserve.thresholdGranted &&
            Amounts.cmp(reserve.thresholdGranted, amount) >= 0
          ) {
            return true;
          }
          if (reserve.status === ReserveRecordStatus.PendingLegi) {
            return true;
          }
          return false;
        }
      });
    },
    filterNotification(notif) {
      return (
        notif.type === NotificationType.ExchangeStateTransition &&
        notif.exchangeBaseUrl === exchangeBaseUrl
      );
    },
  });
}

export async function handleTestingWaitExchangeState(
  wex: WalletExecutionContext,
  req: TestingWaitExchangeStateRequest,
): Promise<EmptyObject> {
  await genericWaitForState(wex, {
    async checkState(): Promise<boolean> {
      const exchangeEntry = await lookupExchangeByUri(wex, {
        exchangeBaseUrl: req.exchangeBaseUrl,
      });
      if (req.walletKycStatus) {
        if (req.walletKycStatus !== exchangeEntry.walletKycStatus) {
          return false;
        }
      }
      return true;
    },
    filterNotification(notif) {
      return (
        notif.type === NotificationType.ExchangeStateTransition &&
        notif.exchangeBaseUrl === req.exchangeBaseUrl
      );
    },
  });
  return {};
}

export async function handleTestingWaitExchangeWalletKyc(
  wex: WalletExecutionContext,
  req: TestingWaitWalletKycRequest,
): Promise<EmptyObject> {
  await waitExchangeWalletKyc(wex, req.exchangeBaseUrl, req.amount, req.passed);
  return {};
}

export async function handleTestingPlanMigrateExchangeBaseUrl(
  wex: WalletExecutionContext,
  req: TestingPlanMigrateExchangeBaseUrlRequest,
): Promise<EmptyObject> {
  wex.ws.exchangeMigrationPlan.set(req.oldExchangeBaseUrl, {
    newExchangeBaseUrl: req.newExchangeBaseUrl,
  });
  return {};
}

/**
 * Start a wallet KYC process.
 *
 * Does nothing if the KYC process has already been started.
 */
export async function handleStartExchangeWalletKyc(
  wex: WalletExecutionContext,
  req: StartExchangeWalletKycRequest,
): Promise<EmptyObject> {
  const newReservePair = await wex.cryptoApi.createEddsaKeypair({});
  await wex.runWalletDbTx(async (tx) => {
    const exchange = await tx.getExchange(req.exchangeBaseUrl);
    if (!exchange) {
      throw Error("exchange not found");
    }
    const oldExchangeState = getExchangeState(exchange);
    let mergeReserveRowId = exchange.currentMergeReserveRowId;
    if (mergeReserveRowId == null) {
      mergeReserveRowId = await tx.upsertReserve({
        reservePriv: newReservePair.priv,
        reservePub: newReservePair.pub,
      });
      exchange.currentMergeReserveRowId = mergeReserveRowId;
      await tx.upsertExchange(exchange);
    }
    const reserveRec = await tx.getReserve(mergeReserveRowId);
    checkDbInvariant(reserveRec != null, "reserve record exists");
    if (
      reserveRec.thresholdGranted == null ||
      Amounts.cmp(reserveRec.thresholdGranted, req.amount) < 0
    ) {
      if (
        reserveRec.thresholdRequested == null ||
        Amounts.cmp(reserveRec.thresholdRequested, req.amount) < 0
      ) {
        reserveRec.thresholdRequested = req.amount;
        reserveRec.status = ReserveRecordStatus.PendingLegiInit;
        await tx.upsertReserve(reserveRec);
        tx.notify({
          type: NotificationType.ExchangeStateTransition,
          exchangeBaseUrl: exchange.baseUrl,
          causeHint: "wallet-kyc",
          oldExchangeState,
          newExchangeState: getExchangeState(exchange),
        });
        // The wallet keeps an account at the exchange now, so the entry must
        // stay around even if no transaction ends up using it.
        await markExchangeUsed(tx, req.exchangeBaseUrl);
      } else {
        logger.info(
          `another KYC process is already active for ${req.exchangeBaseUrl} over ${reserveRec.thresholdRequested}`,
        );
        return undefined;
      }
    } else {
      // FIXME: Check expiration once exchange tells us!
      logger.info(
        `KYC already granted for ${req.exchangeBaseUrl} over ${req.amount}, granted ${reserveRec.thresholdGranted}`,
      );
      return undefined;
    }
  });
  const taskId = constructTaskIdentifier({
    tag: PendingTaskType.ExchangeWalletKyc,
    exchangeBaseUrl: req.exchangeBaseUrl,
  });
  wex.taskScheduler.startShepherdTask(taskId);
  return {};
}

async function handleExchangeKycPendingWallet(
  wex: WalletExecutionContext,
  exchange: WalletExchangeEntry,
  reserve: WalletReserve,
): Promise<TaskRunResult> {
  checkDbInvariant(!!reserve.thresholdRequested, "threshold");
  const threshold = reserve.thresholdRequested;
  const sigResp = await wex.cryptoApi.signWalletAccountSetup({
    reservePriv: reserve.reservePriv,
    reservePub: reserve.reservePub,
    threshold,
  });
  const body: WalletKycRequest = {
    balance: reserve.thresholdRequested,
    reserve_pub: reserve.reservePub,
    reserve_sig: sigResp.sig,
  };
  logger.info(`kyc-wallet request body: ${j2s(body)}`);
  const exchangeClient = walletExchangeClient(exchange.baseUrl, wex);
  const res = await exchangeClient.notifyKycBalanceLimit(body);

  logger.info(`kyc-wallet response status is ${res.response.status}`);

  switch (res.case) {
    case "ok":
      // 200: KYC somehow already passed (with a next threshold);
      // 204: KYC disabled at the exchange.
      return handleExchangeKycSuccess(
        wex,
        exchange.baseUrl,
        res.body?.next_threshold,
      );
    case HttpStatusCode.UnavailableForLegalReasons:
      return handleExchangeKycRespLegi(
        wex,
        exchange.baseUrl,
        reserve,
        res.body,
      );
    default:
      // Forbidden (or, via the client, any unexpected status) => error.
      return throwUnexpectedRequestError(res.response, res.detail!);
  }
}

async function handleExchangeKycSuccess(
  wex: WalletExecutionContext,
  exchangeBaseUrl: string,
  nextThreshold: AmountLike | undefined,
): Promise<TaskRunResult> {
  logger.info(`kyc check for ${exchangeBaseUrl} satisfied`);
  await wex.runWalletDbTx(async (tx) => {
    const exchange = await tx.getExchange(exchangeBaseUrl);
    if (!exchange) {
      throw Error("exchange not found");
    }
    const oldExchangeState = getExchangeState(exchange);
    const reserveId = exchange.currentMergeReserveRowId;
    if (reserveId == null) {
      throw Error("expected exchange to have reserve ID");
    }
    const reserve = await tx.getReserve(reserveId);
    checkDbInvariant(!!reserve, "merge reserve should exist");
    switch (reserve.status) {
      case ReserveRecordStatus.PendingLegiInit:
      case ReserveRecordStatus.PendingLegi:
        break;
      default:
        throw Error("unexpected state (concurrent modification?)");
    }
    reserve.status = ReserveRecordStatus.Done;
    reserve.thresholdGranted = reserve.thresholdRequested;
    delete reserve.thresholdRequested;
    delete reserve.requirementRow;

    if (nextThreshold) {
      reserve.thresholdNext = Amounts.stringify(nextThreshold);
    }

    await tx.upsertReserve(reserve);
    logger.info(`newly granted threshold: ${reserve.thresholdGranted}`);
    tx.notify({
      type: NotificationType.ExchangeStateTransition,
      exchangeBaseUrl: exchange.baseUrl,
      causeHint: "wallet-kyc-success",
      oldExchangeState,
      newExchangeState: getExchangeState(exchange),
    });
  });
  return TaskRunResult.progress();
}

function findNextBalanceLimit(
  accountKycStatus: AccountKycStatus,
  currentGranted: AmountLike | undefined,
): AmountString | undefined {
  for (const lim of accountKycStatus.limits ?? []) {
    if (
      lim.operation_type === LimitOperationType.balance &&
      (currentGranted == null || Amounts.cmp(lim.threshold, currentGranted) > 0)
    ) {
      return lim.threshold;
    }
  }
  return undefined;
}

/**
 * The exchange has just told us that we need some legitimization
 * from the user. Request more details and store the result in the database.
 */
async function handleExchangeKycRespLegi(
  wex: WalletExecutionContext,
  exchangeBaseUrl: string,
  reserve: WalletReserve,
  kycBody: LegitimizationNeededResponse,
): Promise<TaskRunResult> {
  const sigResp = await wex.cryptoApi.signWalletKycAuth({
    accountPriv: reserve.reservePriv,
    accountPub: reserve.reservePub,
  });
  const exchangeClient = walletExchangeClient(exchangeBaseUrl, wex);
  const resp = await exchangeClient.checkKycStatus({
    paytoHash: kycBody.h_payto,
    accountPub: reserve.reservePub,
    accountSig: sigResp.sig,
  });

  logger.info(`kyc-check response status ${resp.response.status}`);

  switch (resp.case) {
    case "ok": {
      // FIXME: Store information about next limit!
      logger.trace(`balance KYC account status: ${j2s(resp.body)}`);
      const nextLimit = findNextBalanceLimit(
        resp.body,
        reserve.thresholdGranted,
      );
      return handleExchangeKycSuccess(wex, exchangeBaseUrl, nextLimit);
    }
    case HttpStatusCode.Accepted:
      // Store the result in the DB (below).
      break;
    case HttpStatusCode.NoContent:
      // KYC not configured, so already satisfied
      return handleExchangeKycSuccess(wex, exchangeBaseUrl, undefined);
    default:
      return throwUnexpectedRequestError(resp.response, resp.detail!);
  }

  const accountKycStatusResp = resp.body;

  await wex.runWalletDbTx(async (tx) => {
    const exchange = await tx.getExchange(exchangeBaseUrl);
    if (!exchange) {
      throw Error("exchange not found");
    }
    const oldExchangeState = getExchangeState(exchange);
    const reserveId = exchange.currentMergeReserveRowId;
    if (reserveId == null) {
      throw Error("expected exchange to have reserve ID");
    }
    const reserve = await tx.getReserve(reserveId);
    checkDbInvariant(!!reserve, "merge reserve should exist");
    switch (reserve.status) {
      case ReserveRecordStatus.PendingLegiInit:
        break;
      default:
        throw Error("unexpected state (concurrent modification?)");
    }
    reserve.status = ReserveRecordStatus.PendingLegi;
    reserve.requirementRow = kycBody.requirement_row;
    reserve.amlReview = accountKycStatusResp.aml_review;
    reserve.kycAccessToken = accountKycStatusResp.access_token;

    await tx.upsertReserve(reserve);
    tx.notify({
      type: NotificationType.ExchangeStateTransition,
      exchangeBaseUrl: exchange.baseUrl,
      causeHint: "wallet-kyc-resp-legi",
      oldExchangeState,
      newExchangeState: getExchangeState(exchange),
    });
  });
  return TaskRunResult.progress();
}

/**
 * Legitimization was requested from the user by the exchange.
 *
 * Long-poll for the legitimization to succeed.
 */
async function handleExchangeKycPendingLegitimization(
  wex: WalletExecutionContext,
  exchange: WalletExchangeEntry,
  reserve: WalletReserve,
): Promise<TaskRunResult> {
  // FIXME: Cache this signature
  const sigResp = await wex.cryptoApi.signWalletKycAuth({
    accountPriv: reserve.reservePriv,
    accountPub: reserve.reservePub,
  });

  const reservePayto = reservePaytoFromExchange(
    exchange.baseUrl,
    reserve.reservePub,
  );

  const paytoHash = encodeCrock(Paytos.hashFull(reservePayto));

  // We already have the access token.
  // Long-poll for target 3 <-> KYC status to be OK.
  logger.info(`long-polling wallet KYC status for ${paytoHash}`);
  const exchangeClient = walletExchangeClient(exchange.baseUrl, wex);
  const resp = await exchangeClient.checkKycStatus({
    paytoHash,
    accountPub: reserve.reservePub,
    accountSig: sigResp.sig,
    longpoll: true,
    lpt: 3,
  });

  logger.info(`kyc-check (long-poll) response status ${resp.response.status}`);

  switch (resp.case) {
    case "ok": {
      // FIXME: Store information about next limit!
      logger.info(`balance KYC account status: ${j2s(resp.body)}`);
      const nextLimit = findNextBalanceLimit(
        resp.body,
        reserve.thresholdGranted,
      );
      logger.info(
        `setting next limit to: ${
          nextLimit ? Amounts.stringify(nextLimit) : "undefined"
        }`,
      );
      return handleExchangeKycSuccess(wex, exchange.baseUrl, nextLimit);
    }
    case HttpStatusCode.Accepted:
      // FIXME: Do we ever need to update the access token?
      return TaskRunResult.longpollReturnedPending();
    case HttpStatusCode.NoContent:
      // KYC not configured, so already satisfied
      return handleExchangeKycSuccess(wex, exchange.baseUrl, undefined);
    default:
      return throwUnexpectedRequestError(resp.response, resp.detail!);
  }
}

export async function processExchangeKyc(
  wex: WalletExecutionContext,
  exchangeBaseUrl: string,
): Promise<TaskRunResult> {
  const res = await wex.runWalletDbTx(async (tx) => {
    const exchange = await tx.getExchange(exchangeBaseUrl);
    if (!exchange) {
      return undefined;
    }
    const reserveId = exchange.currentMergeReserveRowId;
    let reserve: WalletReserve | undefined = undefined;
    if (reserveId != null) {
      reserve = await tx.getReserve(reserveId);
    }
    return { exchange, reserve };
  });
  if (!res) {
    logger.warn(`exchange ${exchangeBaseUrl} not found, not processing KYC`);
    return TaskRunResult.finished();
  }
  if (!res.reserve) {
    return TaskRunResult.finished();
  }
  switch (res.reserve.status) {
    case undefined:
      // No KYC requested
      return TaskRunResult.finished();
    case ReserveRecordStatus.Done:
      return TaskRunResult.finished();
    case ReserveRecordStatus.SuspendedLegiInit:
    case ReserveRecordStatus.SuspendedLegi:
      return TaskRunResult.finished();
    case ReserveRecordStatus.PendingLegiInit:
      return handleExchangeKycPendingWallet(wex, res.exchange, res.reserve);
    case ReserveRecordStatus.PendingLegi:
      return handleExchangeKycPendingLegitimization(
        wex,
        res.exchange,
        res.reserve,
      );
  }
}

export async function checkExchangeInScopeTx(
  tx: WalletDbTransaction,
  exchangeBaseUrl: string,
  scope: ScopeInfo,
  knownDetails?: Pick<
    ExchangeDetails,
    "currency" | "masterPublicKey" | "auditors"
  >,
  denomPubHash?: string,
): Promise<boolean> {
  logger.trace(
    `checking if exchange ${exchangeBaseUrl} is in scope ${j2s(scope)}`,
  );
  switch (scope.type) {
    case ScopeType.Exchange: {
      return scope.url === exchangeBaseUrl;
    }
    case ScopeType.Global: {
      const exchangeDetails =
        knownDetails ?? (await getExchangeRecordsInternal(tx, exchangeBaseUrl));
      if (!exchangeDetails) {
        logger.trace(`no details for ${exchangeBaseUrl}`);
        return false;
      }
      const gr = await tx.getGlobalCurrencyExchange(
        exchangeDetails.currency,
        exchangeBaseUrl,
        exchangeDetails.masterPublicKey,
      );
      logger.trace(`global currency record: ${j2s(gr)}`);
      return gr != null;
    }
    case ScopeType.Auditor: {
      const exchangeDetails =
        knownDetails ?? (await getExchangeRecordsInternal(tx, exchangeBaseUrl));
      if (!exchangeDetails || exchangeDetails.currency !== scope.currency) {
        return false;
      }
      for (const auditor of exchangeDetails.auditors) {
        if (
          !hasVerifiedAuditorTrust([auditor], {
            auditorBaseUrl: scope.url,
            denomPubHash,
          })
        ) {
          continue;
        }
        if (
          await tx.getGlobalCurrencyAuditor(
            exchangeDetails.currency,
            auditor.auditor_url,
            auditor.auditor_pub,
          )
        ) {
          return true;
        }
      }
      return false;
    }
    case ScopeType.ExchangeLegacyKeys:
      // See checkExchangeInScopeGeneric: an entry stands for its current key
      // set, which is never a superseded one.
      return false;
  }
}

/**
 * Find a preferred exchange based on when we withdrew last from this exchange.
 */
export async function getPreferredExchangeForCurrency(
  wex: WalletExecutionContext,
  currency: string,
  restrictScope?: ScopeInfo,
): Promise<string | undefined> {
  if (restrictScope) {
    checkLogicInvariant(restrictScope.currency === currency);
  }
  if (logger.shouldLogTrace()) {
    logger.trace(
      `finding preferred exchange for currency ${currency}, scope ${j2s(
        restrictScope,
      )}`,
    );
  }
  // Find an exchange with the matching currency.
  // Prefer exchanges with the most recent withdrawal.
  const url = await wex.runWalletDbTx(async (tx) => {
    const exchanges = await tx.getExchanges();
    logger.trace(`have ${exchanges.length} exchanges`);
    let candidate = undefined;
    for (const e of exchanges) {
      if (e.detailsPointer?.currency !== currency) {
        logger.trace("no details pointer");
        continue;
      }
      const inScope =
        !restrictScope ||
        (await checkExchangeInScopeTx(tx, e.baseUrl, restrictScope));
      if (!inScope) {
        logger.trace("not in scope");
        continue;
      }
      if (!candidate) {
        candidate = e;
        continue;
      }
      if (candidate.lastWithdrawal && !e.lastWithdrawal) {
        continue;
      }
      const exchangeLastWithdrawal = timestampOptionalPreciseFromDb(
        e.lastWithdrawal,
      );
      const candidateLastWithdrawal = timestampOptionalPreciseFromDb(
        candidate.lastWithdrawal,
      );
      if (exchangeLastWithdrawal && candidateLastWithdrawal) {
        if (
          AbsoluteTime.cmp(
            AbsoluteTime.fromPreciseTimestamp(exchangeLastWithdrawal),
            AbsoluteTime.fromPreciseTimestamp(candidateLastWithdrawal),
          ) > 0
        ) {
          candidate = e;
        }
      }
    }
    if (candidate) {
      return candidate.baseUrl;
    }
    return undefined;
  });
  return url;
}

interface MigrateExchangeRequest {
  oldExchangeBaseUrl: string;
  newExchangeBaseUrl: string;
  trigger: ExchangeMigrationReason;
}

export async function migrateExchange(
  wex: WalletExecutionContext,
  req: MigrateExchangeRequest,
): Promise<void> {
  await wex.runWalletDbTx(async (tx) => {
    const migrationRec = await tx.getExchangeMigrationLog(
      req.oldExchangeBaseUrl,
      req.newExchangeBaseUrl,
    );
    if (migrationRec) {
      logger.warn(
        `exchange ${migrationRec.oldExchangeBaseUrl} already migrated`,
      );
      return;
    }

    const exch = await tx.getExchange(req.oldExchangeBaseUrl);
    if (!exch) {
      logger.warn(`exchange ${req.oldExchangeBaseUrl} does not exist anymore`);
      return;
    }

    let existingNewExchangeSt: ExchangeEntryState | undefined = undefined;

    await tx.upsertExchangeMigrationLog({
      oldExchangeBaseUrl: req.oldExchangeBaseUrl,
      newExchangeBaseUrl: req.newExchangeBaseUrl,
      timestamp: timestampPreciseToDb(TalerPreciseTimestamp.now()),
      reason: req.trigger,
    });

    await tx.upsertExchangeBaseUrlFixup({
      exchangeBaseUrl: req.oldExchangeBaseUrl,
      replacement: req.newExchangeBaseUrl,
    });

    {
      // Denominations are stored under the key that signed them, which a
      // change of base URL does not touch, so their identity needs no
      // rewriting.  The URL they carry is a routing hint kept in step here so
      // that the by-URL lookups still find them.
      const denoms = await getAllDenominationsForExchange(
        tx,
        req.oldExchangeBaseUrl,
      );
      for (const rec of denoms) {
        rec.exchangeBaseUrl = req.newExchangeBaseUrl;
        await tx.upsertDenomination(rec);
      }
    }

    {
      // Denomination families are looked up by base URL, so one left behind
      // at the old URL is invisible at the new one: the next /keys finds no
      // family for any denomination and creates a second, complete set.  The
      // denominations of coins already held keep pointing at the first set,
      // which a later purge of the old URL would then cascade-delete.
      const families = await tx.getDenominationFamiliesByExchange(
        req.oldExchangeBaseUrl,
      );
      for (const fam of families) {
        const moved: WalletDenomFamilyParams = {
          ...fam.familyParams,
          exchangeBaseUrl: req.newExchangeBaseUrl,
        };
        // Migrating onto an exchange the wallet already knows can produce two
        // families with identical parameters.  Keep the one already at the
        // new URL and point this one's denominations at it, rather than
        // storing a duplicate the next update would have to disambiguate.
        const existing = await tx.getDenominationFamilyByParams(moved);
        if (
          existing?.denominationFamilySerial != null &&
          existing.denominationFamilySerial !== fam.denominationFamilySerial
        ) {
          checkDbInvariant(
            typeof fam.denominationFamilySerial === "number",
            "denominationFamilySerial",
          );
          for (const denom of await tx.getDenominationsByMasterPub(
            moved.exchangeMasterPub,
          )) {
            if (
              denom.denominationFamilySerial === fam.denominationFamilySerial
            ) {
              denom.denominationFamilySerial =
                existing.denominationFamilySerial;
              await tx.upsertDenomination(denom);
            }
          }
          await tx.deleteDenominationFamily(fam.denominationFamilySerial);
          continue;
        }
        fam.familyParams = moved;
        await tx.upsertDenominationFamily(fam);
      }
    }

    {
      const recs = await tx.listAllDenomLossEvents();
      for (const rec of recs) {
        if (rec.exchangeBaseUrl === req.oldExchangeBaseUrl) {
          rec.exchangeBaseUrl = req.newExchangeBaseUrl;
          await tx.upsertDenomLossEvent(rec);
        }
      }
    }

    {
      const recs = await tx.getRecoupGroupsByExchange(req.oldExchangeBaseUrl);
      for (const rec of recs) {
        rec.exchangeBaseUrl = req.newExchangeBaseUrl;
        await tx.upsertRecoupGroup(rec);
      }
    }

    {
      const existingNewExchangeDetails = await tx.getExchangeDetailsByBaseUrl(
        req.newExchangeBaseUrl,
      );
      if (!existingNewExchangeDetails) {
        const oldDetails = await tx.listExchangeDetailsByBaseUrl(
          req.oldExchangeBaseUrl,
        );
        for (const rec of oldDetails) {
          rec.exchangeBaseUrl = req.newExchangeBaseUrl;
          await tx.upsertExchangeDetails(rec);
        }
      }
    }

    {
      const rec = await tx.getExchange(req.oldExchangeBaseUrl);
      if (rec) {
        existingNewExchangeSt = {
          exchangeEntryStatus: getExchangeEntryStatusFromRecord(rec),
          exchangeUpdateStatus: getExchangeUpdateStatusFromRecord(rec),
          tosStatus: getExchangeTosStatusFromRecord(rec),
        };
        rec.baseUrl = req.newExchangeBaseUrl;
        await tx.deleteExchange(req.oldExchangeBaseUrl);
        await tx.upsertExchange(rec);
      }
    }

    {
      const recs = await tx.getCoinsByExchange(req.oldExchangeBaseUrl);
      for (const rec of recs) {
        rec.exchangeBaseUrl = req.newExchangeBaseUrl;
        await tx.upsertCoin(rec);
      }
    }

    {
      const recs = await tx.getCoinAvailabilityByExchange(
        req.oldExchangeBaseUrl,
      );
      for (const rec of recs) {
        await tx.deleteCoinAvailability(rec);
        rec.exchangeBaseUrl = req.newExchangeBaseUrl;
        await tx.upsertCoinAvailability(rec);
      }
    }

    {
      const recs = await tx.listAllPeerPullCredits();
      for (const rec of recs) {
        if (rec.exchangeBaseUrl === req.oldExchangeBaseUrl) {
          rec.exchangeBaseUrl = req.newExchangeBaseUrl;
          await tx.upsertPeerPullCredit(rec);
        }
      }
    }

    {
      const recs = await tx.listAllPeerPullDebits();
      for (const rec of recs) {
        if (rec.exchangeBaseUrl === req.oldExchangeBaseUrl) {
          rec.exchangeBaseUrl = req.newExchangeBaseUrl;
          await tx.upsertPeerPullDebit(rec);
        }
      }
    }

    {
      const recs = await tx.listAllPeerPushCredits();
      for (const rec of recs) {
        if (rec.exchangeBaseUrl === req.oldExchangeBaseUrl) {
          rec.exchangeBaseUrl = req.newExchangeBaseUrl;
          await tx.upsertPeerPushCredit(rec);
        }
      }
    }

    {
      const recs = await tx.listAllPeerPushDebits();
      for (const rec of recs) {
        if (rec.exchangeBaseUrl === req.oldExchangeBaseUrl) {
          rec.exchangeBaseUrl = req.newExchangeBaseUrl;
          await tx.upsertPeerPushDebit(rec);
        }
      }
    }

    {
      const recs = await tx.getWithdrawalGroupsByExchangeForRekey(
        req.oldExchangeBaseUrl,
      );
      for (const rec of recs) {
        rec.exchangeBaseUrl = req.newExchangeBaseUrl;
        await tx.upsertWithdrawalGroup(rec);
      }
    }

    {
      const recs = await tx.listAllRefreshGroups();
      for (const rec of recs) {
        if (
          rec.infoPerExchange &&
          rec.infoPerExchange[req.oldExchangeBaseUrl] != null
        ) {
          rec.infoPerExchange[req.newExchangeBaseUrl] =
            rec.infoPerExchange[req.oldExchangeBaseUrl];
          delete rec.infoPerExchange[req.oldExchangeBaseUrl];
          await tx.upsertRefreshGroup(rec);
        }
      }
    }

    {
      const recs = await tx.listAllDepositGroups();
      for (const rec of recs) {
        if (
          rec.infoPerExchange &&
          rec.infoPerExchange[req.oldExchangeBaseUrl] != null
        ) {
          rec.infoPerExchange[req.newExchangeBaseUrl] =
            rec.infoPerExchange[req.oldExchangeBaseUrl];
          delete rec.infoPerExchange[req.oldExchangeBaseUrl];
          await tx.upsertDepositGroup(rec);
        }
      }
    }

    tx.notify({
      type: NotificationType.ExchangeStateTransition,
      exchangeBaseUrl: req.oldExchangeBaseUrl,
      causeHint: "migration-old",
      oldExchangeState: getExchangeState(exch),
      newExchangeState: undefined,
    });

    tx.notify({
      type: NotificationType.ExchangeStateTransition,
      exchangeBaseUrl: req.newExchangeBaseUrl,
      oldExchangeState: existingNewExchangeSt,
      causeHint: "migration-new",
      newExchangeState: getExchangeState(exch),
    });
  });
}
