const logger = new Logger("pay-peer-push-debit.ts");

export class PeerPushDebitTransactionContext implements TransactionContext {
  readonly transactionId: TransactionIdStr;
  readonly taskId: TaskIdStr;

  constructor(
    public wex: WalletExecutionContext,
    public pursePub: string,
  ) {
    this.transactionId = constructTransactionIdentifier({
      tag: TransactionType.PeerPushDebit,
      pursePub,
    });
    this.taskId = constructTaskIdentifier({
      tag: PendingTaskType.PeerPushDebit,
      pursePub,
    });
  }

  async updateTransactionMeta(tx: WalletDbTransaction): Promise<void> {
    const rec = await tx.getPeerPushDebit(this.pursePub);
    logger.info(
      `updating peer-push-debit meta for ${this.transactionId},` +
        ` status=${rec?.status ?? "deleted"}`,
    );
    if (rec == null) {
      await tx.deleteTransactionMeta(this.transactionId);
    } else {
      await tx.upsertTransactionMeta({
        currency: Amounts.currencyOf(rec.amount),
        exchanges: [rec.exchangeBaseUrl],
        status: rec.status,
        timestamp: rec.timestampCreated,
        transactionId: this.transactionId,
      });
    }
  }

  /**
   * Get the full transaction details for the transaction.
   *
   * Returns undefined if the transaction is in a state where we do not have a
   * transaction item (e.g. if it was deleted).
   */
  async lookupFullTransaction(
    tx: WalletDbTransaction,
  ): Promise<Transaction | undefined> {
    const pushDebitRec = await tx.getPeerPushDebit(this.pursePub);
    if (pushDebitRec == null) {
      return undefined;
    }
    const retryRec = await tx.getOperationRetry(this.taskId);

    const ctRec = await tx.getContractTerms(pushDebitRec.contractTermsHash);
    checkDbInvariant(
      !!ctRec,
      `no contract terms for p2p push ${this.pursePub}`,
    );

    const contractTerms = ctRec.contractTermsRaw;

    let talerUri: string | undefined = undefined;
    switch (pushDebitRec.status) {
      case PeerPushDebitStatus.PendingReady:
      case PeerPushDebitStatus.SuspendedReady:
        talerUri = TalerUris.stringify({
          type: TalerUriAction.PayPush,
          exchangeBaseUrl: pushDebitRec.exchangeBaseUrl as HostPortPath, // FIXME: change record type
          contractPriv: pushDebitRec.contractPriv,
        });
    }
    const txState = computePeerPushDebitTransactionState(pushDebitRec);
    return {
      type: TransactionType.PeerPushDebit,
      txState,
      stId: pushDebitRec.status,
      scopes: await getScopeForAllExchanges(tx, [pushDebitRec.exchangeBaseUrl]),
      txActions: computePeerPushDebitTransactionActions(pushDebitRec),
      amountEffective: isUnsuccessfulTransaction(txState)
        ? Amounts.stringify(Amounts.zeroOfAmount(pushDebitRec.totalCost))
        : pushDebitRec.totalCost,
      amountRaw: pushDebitRec.amount,
      exchangeBaseUrl: pushDebitRec.exchangeBaseUrl,
      info: {
        expiration: contractTerms.purse_expiration,
        summary: contractTerms.summary,
        iconId: contractTerms.icon_id,
      },
      timestamp: timestampPreciseFromDb(pushDebitRec.timestampCreated),
      talerUri,
      transactionId: constructTransactionIdentifier({
        tag: TransactionType.PeerPushDebit,
        pursePub: pushDebitRec.pursePub,
      }),
      failReason: pushDebitRec.failReason,
      abortReason: pushDebitRec.abortReason,
      ...(retryRec?.lastError ? { error: retryRec.lastError } : {}),
    };
  }

  async getRecordHandle(
    tx: WalletDbTransaction,
  ): Promise<
    [WalletPeerPushDebit | undefined, RecordHandle<WalletPeerPushDebit>]
  > {
    return getGenericRecordHandle<WalletPeerPushDebit>(
      this,
      tx,
      async () => tx.getPeerPushDebit(this.pursePub),
      async (r) => {
        await tx.upsertPeerPushDebit(r);
      },
      async () => tx.deletePeerPushDebit(this.pursePub),
      (r) => computePeerPushDebitTransactionState(r),
      (r) => r.status,
      () => this.updateTransactionMeta(tx),
    );
  }

  async userDeleteTransaction(): Promise<void> {
    await this.wex.runWalletDbTx(async (tx) => {
      await this.deleteTransactionInTx(tx);
    });
  }

  async deleteTransactionInTx(tx: WalletDbTransaction): Promise<void> {
    const [rec, h] = await this.getRecordHandle(tx);
    if (!rec) {
      return;
    }
    await h.update(undefined, "delete");
  }

  async userSuspendTransaction(): Promise<void> {
    await this.wex.runWalletDbTx(async (tx) => {
      const [rec, h] = await this.getRecordHandle(tx);
      if (!rec) {
        return;
      }
      switch (rec.status) {
        case PeerPushDebitStatus.PendingCreatePurse:
          rec.status = PeerPushDebitStatus.SuspendedCreatePurse;
          break;
        case PeerPushDebitStatus.AbortingDeletePurse:
          rec.status = PeerPushDebitStatus.SuspendedAbortingDeletePurse;
          break;
        case PeerPushDebitStatus.ExpiredDeletePurse:
          rec.status = PeerPushDebitStatus.SuspendedExpiredDeletePurse;
          break;
        case PeerPushDebitStatus.PendingReady:
          rec.status = PeerPushDebitStatus.SuspendedReady;
          break;
        case PeerPushDebitStatus.SuspendedExpiredDeletePurse:
        case PeerPushDebitStatus.SuspendedAbortingDeletePurse:
        case PeerPushDebitStatus.SuspendedReady:
        case PeerPushDebitStatus.SuspendedCreatePurse:
        case PeerPushDebitStatus.Done:
        case PeerPushDebitStatus.Aborted:
        case PeerPushDebitStatus.Failed:
        case PeerPushDebitStatus.Expired:
          // Do nothing
          return;
        default:
          assertUnreachable(rec.status);
      }
      await h.update(rec, "suspend");
    });
    this.wex.taskScheduler.stopShepherdTask(this.taskId);
  }

  async userAbortTransaction(reason?: TalerErrorDetail): Promise<void> {
    await this.wex.runWalletDbTx(async (tx) => {
      const [rec, h] = await this.getRecordHandle(tx);
      if (!rec) {
        return;
      }
      switch (rec.status) {
        case PeerPushDebitStatus.PendingReady:
        case PeerPushDebitStatus.SuspendedReady:
          rec.abortReason = reason;
          rec.status = PeerPushDebitStatus.AbortingDeletePurse;
          break;
        case PeerPushDebitStatus.SuspendedCreatePurse:
        case PeerPushDebitStatus.PendingCreatePurse:
          // Network request might already be in-flight!
          rec.abortReason = reason;
          rec.status = PeerPushDebitStatus.AbortingDeletePurse;
          break;
        case PeerPushDebitStatus.SuspendedAbortingDeletePurse:
        case PeerPushDebitStatus.SuspendedExpiredDeletePurse:
        case PeerPushDebitStatus.Done:
        case PeerPushDebitStatus.AbortingDeletePurse:
        case PeerPushDebitStatus.ExpiredDeletePurse:
        case PeerPushDebitStatus.Aborted:
        case PeerPushDebitStatus.Expired:
        case PeerPushDebitStatus.Failed:
          // Do nothing
          return;
        default:
          assertUnreachable(rec.status);
      }
      await h.update(rec, "abort");
    });
    await this.wex.taskScheduler.resetTask(this.taskId);
  }

  async userResumeTransaction(): Promise<void> {
    await this.wex.runWalletDbTx(async (tx) => {
      const [rec, h] = await this.getRecordHandle(tx);
      if (!rec) {
        return;
      }
      switch (rec.status) {
        case PeerPushDebitStatus.SuspendedAbortingDeletePurse:
          rec.status = PeerPushDebitStatus.AbortingDeletePurse;
          break;
        case PeerPushDebitStatus.SuspendedExpiredDeletePurse:
          rec.status = PeerPushDebitStatus.ExpiredDeletePurse;
          break;
        case PeerPushDebitStatus.SuspendedReady:
          rec.status = PeerPushDebitStatus.PendingReady;
          break;
        case PeerPushDebitStatus.SuspendedCreatePurse:
          rec.status = PeerPushDebitStatus.PendingCreatePurse;
          break;
        case PeerPushDebitStatus.PendingCreatePurse:
        case PeerPushDebitStatus.AbortingDeletePurse:
        case PeerPushDebitStatus.ExpiredDeletePurse:
        case PeerPushDebitStatus.PendingReady:
        case PeerPushDebitStatus.Done:
        case PeerPushDebitStatus.Aborted:
        case PeerPushDebitStatus.Failed:
        case PeerPushDebitStatus.Expired:
          // Do nothing
          return;
        default:
          assertUnreachable(rec.status);
      }
      await h.update(rec, "resume");
    });
    await this.wex.taskScheduler.resetTask(this.taskId);
  }

  async failTransaction(
    fromSt: PeerPushDebitStatus,
    reason?: TalerErrorDetail,
  ): Promise<void> {
    const { wex } = this;
    await wex.runWalletDbTx(async (tx) => {
      const [rec, h] = await this.getRecordHandle(tx);
      if (rec?.status != fromSt) {
        return;
      }
      rec.status = PeerPushDebitStatus.Failed;
      rec.failReason = reason;
      await h.update(rec, "fail");
    });
  }

  async userFailTransaction(reason?: TalerErrorDetail): Promise<void> {
    await this.wex.runWalletDbTx(async (tx) => {
      const [rec, h] = await this.getRecordHandle(tx);
      if (!rec) {
        return;
      }
      switch (rec.status) {
        case PeerPushDebitStatus.PendingReady:
        case PeerPushDebitStatus.SuspendedReady:
        case PeerPushDebitStatus.SuspendedCreatePurse:
        case PeerPushDebitStatus.PendingCreatePurse:
          // Failure is not advertised while value can still be recovered by
          // completing or aborting the purse operation.
          return;
        case PeerPushDebitStatus.AbortingDeletePurse:
        case PeerPushDebitStatus.SuspendedAbortingDeletePurse:
        case PeerPushDebitStatus.ExpiredDeletePurse:
        case PeerPushDebitStatus.SuspendedExpiredDeletePurse:
          rec.status = PeerPushDebitStatus.Failed;
          rec.failReason = reason;
          break;
        case PeerPushDebitStatus.Done:
        case PeerPushDebitStatus.Aborted:
        case PeerPushDebitStatus.Failed:
        case PeerPushDebitStatus.Expired:
          // Do nothing
          return;
        default:
          assertUnreachable(rec.status);
      }
      await h.update(rec, "user-fail");
    });
    await this.wex.taskScheduler.resetTask(this.taskId);
  }
}

/**
 * @deprecated use V2 instead
 */
export async function checkPeerPushDebit(
  wex: WalletExecutionContext,
  req: CheckPeerPushDebitRequest,
): Promise<CheckPeerPushDebitOkResponse> {
  const res = await checkPeerPushDebitV2(wex, req);
  switch (res.type) {
    case "ok":
      return res;
    case "insufficient-balance":
      throw TalerError.fromDetail(
        TalerErrorCode.WALLET_PEER_PUSH_PAYMENT_INSUFFICIENT_BALANCE,
        {
          insufficientBalanceDetails: res.insufficientBalanceDetails,
        },
      );
    default:
      assertUnreachable(res);
  }
}

export async function checkPeerPushDebitV2(
  wex: WalletExecutionContext,
  req: CheckPeerPushDebitRequest,
): Promise<CheckPeerPushDebitResponse> {
  return runWithMaybeProgressContext(
    wex,
    "checkPeerPushDebit",
    req.progressToken,
    () => internalCheckPeerPushDebit(wex, req),
  );
}

const fallbackDefaultPeerPushExpiration = Duration.toTalerProtocolDuration(
  Duration.fromSpec({ days: 7 }),
);

interface PeerPushDebitQuoteV1 {
  version: 1;
  amount: string;
  amountEffective: string;
  exchangeBaseUrl: string;
  restrictScope?: ScopeInfo;
  maxExpirationDate: TalerProtocolTimestamp;
}

const peerPushDebitQuotePrefix = "PPDQ1-";

export function encodePeerPushDebitQuote(quote: PeerPushDebitQuoteV1): string {
  return (
    peerPushDebitQuotePrefix + encodeCrock(stringToBytes(canonicalJson(quote)))
  );
}

export function decodePeerPushDebitQuote(token: string): PeerPushDebitQuoteV1 {
  if (!token.startsWith(peerPushDebitQuotePrefix)) {
    throw Error("unsupported peer push debit quote version");
  }
  const value: unknown = JSON.parse(
    bytesToString(decodeCrock(token.slice(peerPushDebitQuotePrefix.length))),
  );
  if (!value || typeof value !== "object") {
    throw Error("peer push debit quote is not an object");
  }
  const quote = value as Partial<PeerPushDebitQuoteV1>;
  let canonicalExchange: string | undefined;
  let restrictScope: ScopeInfo | undefined;
  let scopeValid = true;
  try {
    canonicalExchange =
      typeof quote.exchangeBaseUrl === "string"
        ? canonicalizeBaseUrl(quote.exchangeBaseUrl)
        : undefined;
  } catch {
    canonicalExchange = undefined;
  }
  try {
    restrictScope =
      quote.restrictScope === undefined
        ? undefined
        : codecForScopeInfo().decode(quote.restrictScope);
  } catch {
    scopeValid = false;
  }
  const amount =
    typeof quote.amount === "string" ? Amounts.parse(quote.amount) : undefined;
  const amountEffective =
    typeof quote.amountEffective === "string"
      ? Amounts.parse(quote.amountEffective)
      : undefined;
  const maxExpiration = quote.maxExpirationDate?.t_s;
  if (
    quote.version !== 1 ||
    !amount ||
    !amountEffective ||
    amount.currency !== amountEffective.currency ||
    (restrictScope !== undefined &&
      restrictScope.currency !== amount.currency) ||
    !scopeValid ||
    typeof quote.exchangeBaseUrl !== "string" ||
    canonicalExchange !== quote.exchangeBaseUrl ||
    !TalerProtocolTimestamp.isTimestamp(quote.maxExpirationDate) ||
    (maxExpiration !== "never" &&
      (typeof maxExpiration !== "number" ||
        !Number.isSafeInteger(maxExpiration) ||
        maxExpiration < 0))
  ) {
    throw Error("peer push debit quote has invalid fields");
  }
  return {
    version: 1,
    amount: quote.amount!,
    amountEffective: quote.amountEffective!,
    exchangeBaseUrl: quote.exchangeBaseUrl,
    ...(restrictScope === undefined ? {} : { restrictScope }),
    maxExpirationDate: quote.maxExpirationDate!,
  };
}

function sameScope(left: ScopeInfo | undefined, right: ScopeInfo | undefined) {
  return canonicalJson(left ?? null) === canonicalJson(right ?? null);
}

function timestampAfter(
  left: TalerProtocolTimestamp,
  right: TalerProtocolTimestamp,
): boolean {
  if (right.t_s === "never") return false;
  if (left.t_s === "never") return true;
  return left.t_s > right.t_s;
}

function quoteChanged(message: string): never {
  throw TalerError.fromDetail(
    TalerErrorCode.WALLET_PEER_PUSH_PAYMENT_QUOTE_CHANGED,
    {},
    message,
  );
}

async function getDefaultPeerPushExpiration(
  wex: WalletExecutionContext,
  exchangeBaseUrl: string,
): Promise<TalerProtocolDuration> {
  return await wex.runWalletDbTx(async (tx) => {
    const ex = await getExchangeDetailsInTx(tx, exchangeBaseUrl);
    return ex?.defaultPeerPushExpiration ?? fallbackDefaultPeerPushExpiration;
  });
}

async function internalCheckPeerPushDebit(
  wex: WalletExecutionContext,
  req: CheckPeerPushDebitRequest,
): Promise<CheckPeerPushDebitResponse> {
  const instructedAmount = Amounts.parseOrThrow(req.amount);
  const currency = instructedAmount.currency;
  logger.trace(
    `checking peer push debit for ${Amounts.stringify(instructedAmount)}`,
  );
  let restrictScope: ScopeInfo | undefined = undefined;
  if (req.restrictScope) {
    restrictScope = req.restrictScope;
  } else if (req.exchangeBaseUrl) {
    restrictScope = {
      type: ScopeType.Exchange,
      currency,
      url: req.exchangeBaseUrl,
    };
  }
  if (Amounts.isZero(req.amount)) {
    const exchangeBaseUrl = await getPreferredExchangeForCurrency(
      wex,
      currency,
      restrictScope,
    );
    if (!exchangeBaseUrl) {
      throw TalerError.fromDetail(
        TalerErrorCode.WALLET_NO_SUITABLE_EXCHANGE,
        { currency },
        "no exchange in the wallet can be used for this payment",
      );
    }

    return {
      type: "ok",
      amountEffective: req.amount,
      amountRaw: req.amount,
      exchangeBaseUrl,
      maxExpirationDate: TalerProtocolTimestamp.never(),
      defaultExpiration: await getDefaultPeerPushExpiration(
        wex,
        exchangeBaseUrl,
      ),
      peerPushDebitQuote: encodePeerPushDebitQuote({
        version: 1,
        amount: req.amount,
        amountEffective: req.amount,
        exchangeBaseUrl,
        restrictScope: req.restrictScope,
        maxExpirationDate: TalerProtocolTimestamp.never(),
      }),
    };
  }
  const coinSelRes = await selectPeerCoins(wex, {
    instructedAmount,
    restrictScope,
    feesCoveredByCounterparty: false,
  });
  let coins: SelectedProspectiveCoin[] | undefined = undefined;
  switch (coinSelRes.type) {
    case "failure":
      return {
        type: "insufficient-balance",
        insufficientBalanceDetails: coinSelRes.insufficientBalanceDetails,
      };
    case "success":
      coins = coinSelRes.result.coins;
      break;
    default:
      assertUnreachable(coinSelRes);
  }
  logger.trace(`selected peer coins (len=${coins.length})`);
  // We might need to do a refresh later, so it's important
  // that we have up-to-date info about the exchange.
  await fetchFreshExchange(wex, coinSelRes.result.exchangeBaseUrl);
  const totalAmount = await getTotalPeerPaymentCost(wex, coins);
  logger.trace("computed total peer payment cost");
  const exchangeBaseUrl = coinSelRes.result.exchangeBaseUrl;
  let defaultExpiration = await getDefaultPeerPushExpiration(
    wex,
    exchangeBaseUrl,
  );

  const defaultExp = Duration.min(
    Duration.fromTalerProtocolDuration(defaultExpiration),
    AbsoluteTime.difference(
      AbsoluteTime.now(),
      AbsoluteTime.fromProtocolTimestamp(coinSelRes.result.maxExpirationDate),
    ),
  );

  return {
    type: "ok",
    exchangeBaseUrl,
    amountEffective: Amounts.stringify(totalAmount),
    amountRaw: req.amount,
    maxExpirationDate: coinSelRes.result.maxExpirationDate,
    defaultExpiration: Duration.toTalerProtocolDuration(defaultExp),
    peerPushDebitQuote: encodePeerPushDebitQuote({
      version: 1,
      amount: req.amount,
      amountEffective: Amounts.stringify(totalAmount),
      exchangeBaseUrl,
      restrictScope: req.restrictScope,
      maxExpirationDate: coinSelRes.result.maxExpirationDate,
    }),
  };
}

async function handlePurseCreationConflict(
  wex: WalletExecutionContext,
  peerPushInitiation: WalletPeerPushDebit,
  conflict: PurseConflict,
): Promise<TaskRunResult> {
  const pursePub = peerPushInitiation.pursePub;
  const ctx = new PeerPushDebitTransactionContext(wex, pursePub);
  if (conflict.code !== TalerErrorCode.EXCHANGE_GENERIC_INSUFFICIENT_FUNDS) {
    await ctx.failTransaction(peerPushInitiation.status, { ...conflict });
    return TaskRunResult.finished();
  }

  const brokenCoinPub = conflict.coin_pub;
  logger.trace(`excluded broken coin pub=${brokenCoinPub}`);

  const instructedAmount = Amounts.parseOrThrow(peerPushInitiation.amount);
  const currency = instructedAmount.currency;
  const sel = peerPushInitiation.coinSel;
  const exchangeBaseUrl = peerPushInitiation.exchangeBaseUrl;

  checkDbInvariant(
    !!sel,
    `no coin selected for peer push initiation ${peerPushInitiation.pursePub}`,
  );

  const repair: PreviousPayCoins = [];

  for (let i = 0; i < sel.coinPubs.length; i++) {
    if (sel.coinPubs[i] != brokenCoinPub) {
      repair.push({
        coinPub: sel.coinPubs[i],
        contribution: Amounts.parseOrThrow(sel.contributions[i]),
      });
    }
  }

  // FIXME: We don't handle the case where we would
  // have sufficient funds at another exchange,
  // but not at the one selected first. Tricky!
  const coinSelRes = await selectPeerCoins(wex, {
    instructedAmount,
    restrictScope: {
      type: ScopeType.Exchange,
      currency,
      url: exchangeBaseUrl,
    },
    repair,
    feesCoveredByCounterparty: false,
  });

  switch (coinSelRes.type) {
    case "failure":
      throw Error(
        "insufficient balance to re-select coins to repair double spending",
      );
    case "success":
      break;
    default:
      assertUnreachable(coinSelRes);
  }

  const totalAmount = await getTotalPeerPaymentCost(
    ctx.wex,
    coinSelRes.result.coins,
  );

  await ctx.wex.runWalletDbTx(async (tx) => {
    const [rec, h] = await ctx.getRecordHandle(tx);
    if (!rec) {
      return;
    }
    switch (rec.status) {
      case PeerPushDebitStatus.PendingCreatePurse:
      case PeerPushDebitStatus.SuspendedCreatePurse: {
        const sel = coinSelRes.result;
        rec.coinSel = {
          coinPubs: sel.coins.map((x) => x.coinPub),
          contributions: sel.coins.map((x) => x.contribution),
        };
        // The replacement coins come with their own fees.
        rec.totalCost = Amounts.stringify(totalAmount);
        // The carried-over coins were spent when they were first selected,
        // the ones that replace the double-spent coin still have to be.
        const added = coinsAddedByRepair(repair, sel.coins);
        await spendCoins(ctx.wex, tx, {
          transactionId: ctx.transactionId,
          coinPubs: added.map((x) => x.coinPub),
          contributions: added.map((x) => Amounts.parseOrThrow(x.contribution)),
          refreshReason: RefreshReason.PayPeerPush,
        });
        await h.update(rec, "purse-conflict-repair");
      }
    }
  });
  return TaskRunResult.progress();
}

/**
 * Pick the clean-up state for a purse that the exchange reports as gone.
 *
 * Both states delete the purse and reclaim the coins; they only differ in the
 * terminal state they lead to, so that a purse that simply ran out of time is
 * not reported as if somebody had called the payment off.
 */
function purseGoneStatus(rec: WalletPeerPushDebit): PeerPushDebitStatus {
  return isPurseGoneByExpiration(timestampProtocolFromDb(rec.purseExpiration))
    ? PeerPushDebitStatus.ExpiredDeletePurse
    : PeerPushDebitStatus.AbortingDeletePurse;
}

async function beginPeerPushDebitExpirationCleanup(
  wex: WalletExecutionContext,
  peerPushInitiation: WalletPeerPushDebit,
  reason: string,
): Promise<void> {
  const ctx = new PeerPushDebitTransactionContext(
    wex,
    peerPushInitiation.pursePub,
  );
  await wex.runWalletDbTx(async (tx) => {
    const [rec, h] = await ctx.getRecordHandle(tx);
    if (!rec) {
      return;
    }
    switch (rec.status) {
      case PeerPushDebitStatus.PendingCreatePurse:
      case PeerPushDebitStatus.PendingReady:
        rec.status = PeerPushDebitStatus.ExpiredDeletePurse;
        await h.update(rec, reason);
        break;
      default:
        break;
    }
  });
}

function peerPushDebitExpired(rec: WalletPeerPushDebit): boolean {
  return isPurseGoneByExpiration(timestampProtocolFromDb(rec.purseExpiration));
}

async function processPeerPushDebitCreateReserve(
  wex: WalletExecutionContext,
  peerPushInitiation: WalletPeerPushDebit,
): Promise<TaskRunResult> {
  const { pursePub, purseExpiration, contractTermsHash, exchangeBaseUrl } =
    peerPushInitiation;
  const ctx = new PeerPushDebitTransactionContext(wex, pursePub);

  logger.trace(`processing ${ctx.transactionId} pending(create-reserve)`);

  if (peerPushDebitExpired(peerPushInitiation)) {
    await beginPeerPushDebitExpirationCleanup(
      wex,
      peerPushInitiation,
      "create-purse-expired",
    );
    return TaskRunResult.progress();
  }

  const contractTermsRecord = await wex.runWalletDbTx(async (tx) => {
    return tx.getContractTerms(contractTermsHash);
  });

  if (!contractTermsRecord) {
    throw Error(
      `db invariant failed, contract terms for ${ctx.transactionId} missing`,
    );
  }

  const instructedAmount = Amounts.parseOrThrow(peerPushInitiation.amount);
  const currency = instructedAmount.currency;

  if (!peerPushInitiation.coinSel) {
    const coinSelRes = await selectPeerCoins(wex, {
      instructedAmount,
      restrictScope: {
        type: ScopeType.Exchange,
        currency,
        url: exchangeBaseUrl,
      },
      feesCoveredByCounterparty: false,
    });

    switch (coinSelRes.type) {
      case "failure":
        throw TalerError.fromDetail(
          TalerErrorCode.WALLET_PEER_PUSH_PAYMENT_INSUFFICIENT_BALANCE,
          {
            insufficientBalanceDetails: coinSelRes.insufficientBalanceDetails,
          },
        );
      case "success":
        break;
      default:
        assertUnreachable(coinSelRes);
    }

    return await wex.runWalletDbTx(async (tx) => {
      const [rec, h] = await ctx.getRecordHandle(tx);
      if (!rec) {
        return TaskRunResult.backoff();
      }
      if (rec.coinSel != null) {
        return TaskRunResult.backoff();
      }
      rec.coinSel = {
        coinPubs: coinSelRes.result.coins.map((x) => x.coinPub),
        contributions: coinSelRes.result.coins.map((x) => x.contribution),
      };
      // FIXME: Instead of directly doing a spendCoin here,
      // we might want to mark the coins as used and spend them
      // after we've been able to create the purse.
      await spendCoins(wex, tx, {
        transactionId: ctx.transactionId,
        coinPubs: coinSelRes.result.coins.map((x) => x.coinPub),
        contributions: coinSelRes.result.coins.map((x) =>
          Amounts.parseOrThrow(x.contribution),
        ),
        refreshReason: RefreshReason.PayPeerPush,
      });
      await h.update(rec, "select-coins");
      return TaskRunResult.progress();
    });
  }

  const purseAmount = peerPushInitiation.amount;

  const purseSigResp = await wex.cryptoApi.signPurseCreation({
    hContractTerms: contractTermsHash,
    mergePub: peerPushInitiation.mergePub,
    minAge: 0,
    purseAmount,
    purseExpiration: timestampProtocolFromDb(purseExpiration),
    pursePriv: peerPushInitiation.pursePriv,
  });

  const coins = await queryCoinInfosForSelection(
    wex,
    peerPushInitiation.coinSel,
  );

  const encryptContractRequest: EncryptContractRequest = {
    contractTerms: contractTermsRecord.contractTermsRaw,
    mergePriv: peerPushInitiation.mergePriv,
    pursePriv: peerPushInitiation.pursePriv,
    pursePub: peerPushInitiation.pursePub,
    contractPriv: peerPushInitiation.contractPriv,
    contractPub: peerPushInitiation.contractPub,
    nonce: peerPushInitiation.contractEncNonce,
  };

  const econtractResp = await wex.cryptoApi.encryptContractForMerge(
    encryptContractRequest,
  );

  const maxBatchSize = 64;
  const exchangeClient = walletExchangeClient(exchangeBaseUrl, wex);

  for (let i = 0; i < coins.length; i += maxBatchSize) {
    if (peerPushDebitExpired(peerPushInitiation)) {
      await beginPeerPushDebitExpirationCleanup(
        wex,
        peerPushInitiation,
        "deposit-purse-expired",
      );
      return TaskRunResult.progress();
    }
    const batchSize = Math.min(maxBatchSize, coins.length - i);
    const batchCoins = coins.slice(i, i + batchSize);

    const depositSigsResp = await wex.cryptoApi.signPurseDeposits({
      exchangeBaseUrl: peerPushInitiation.exchangeBaseUrl,
      pursePub: peerPushInitiation.pursePub,
      coins: batchCoins,
    });

    if (i == 0) {
      // First batch creates the purse!

      const reqBody = {
        // Older wallets do not have amountPurse
        amount: purseAmount,
        merge_pub: peerPushInitiation.mergePub,
        purse_sig: purseSigResp.sig,
        h_contract_terms: contractTermsHash,
        purse_expiration: timestampProtocolFromDb(purseExpiration),
        deposits: depositSigsResp.deposits,
        min_age: 0,
        econtract: econtractResp.econtract,
      };

      await requireExchangeCoinUseConfirmedOrThrow(wex, exchangeBaseUrl);
      const resp = await exchangeClient.createPurseFromDeposit(
        peerPushInitiation.pursePub,
        reqBody,
      );
      switch (resp.case) {
        case "ok":
          await requireValidExchangePurseCreateConfirmation(wex, {
            exchangeBaseUrl,
            pursePub: peerPushInitiation.pursePub,
            contractTermsHash,
            purseValueAfterFees: purseAmount,
            purseExpiration: timestampProtocolFromDb(purseExpiration),
            response: resp.body,
          });
          // Possibly on to the next batch.
          continue;
        case HttpStatusCode.Forbidden:
        case HttpStatusCode.NotFound:
          await ctx.failTransaction(peerPushInitiation.status, resp.detail);
          return TaskRunResult.finished();
        case HttpStatusCode.Conflict:
          return handlePurseCreationConflict(
            wex,
            peerPushInitiation,
            resp.body,
          );
        case HttpStatusCode.TooEarly:
          return TaskRunResult.backoff();
        case TalerErrorCode.EXCHANGE_PURSE_CREATE_EXPIRATION_BEFORE_NOW:
          await beginPeerPushDebitExpirationCleanup(
            wex,
            peerPushInitiation,
            "create-purse-expiration-rejected",
          );
          return TaskRunResult.progress();
        case TalerErrorCode.EXCHANGE_PURSE_CREATE_EXPIRATION_IS_NEVER:
          await ctx.failTransaction(peerPushInitiation.status, resp.detail);
          return TaskRunResult.finished();
        default:
          assertUnreachable(resp);
      }
    } else {
      const depositPayload: ExchangePurseDeposits = {
        deposits: depositSigsResp.deposits,
      };
      await requireExchangeCoinUseConfirmedOrThrow(wex, exchangeBaseUrl);
      const resp = await exchangeClient.depositIntoPurse(
        peerPushInitiation.pursePub,
        depositPayload,
      );
      switch (resp.case) {
        case "ok":
          await requireValidExchangePurseDepositConfirmation(wex, {
            exchangeBaseUrl,
            pursePub: peerPushInitiation.pursePub,
            contractTermsHash,
            purseValueAfterFees: purseAmount,
            purseExpiration: timestampProtocolFromDb(purseExpiration),
            response: resp.body,
          });
          // Possibly on to the next batch.
          continue;
        case HttpStatusCode.Gone:
          await wex.runWalletDbTx(async (tx) => {
            const [rec, h] = await ctx.getRecordHandle(tx);
            if (!rec) {
              return;
            }
            switch (rec.status) {
              case PeerPushDebitStatus.PendingCreatePurse:
                rec.status = purseGoneStatus(rec);
                break;
              default:
                // Do nothing
                return;
            }
            await h.update(rec, "deposit-purse-gone");
          });
          return TaskRunResult.progress();
        case HttpStatusCode.Conflict:
          // Handle double-spending
          return handlePurseCreationConflict(
            wex,
            peerPushInitiation,
            resp.body,
          );
        case HttpStatusCode.Forbidden:
        case HttpStatusCode.NotFound:
          await ctx.failTransaction(peerPushInitiation.status, resp.detail);
          return TaskRunResult.finished();
        default:
          assertUnreachable(resp);
      }
    }
  }

  // All batches done!
  const resp = await exchangeClient.getPurseStatusAtDeposit(pursePub);
  switch (resp.case) {
    case "ok":
      await requireValidExchangePurseStatus(
        wex,
        peerPushInitiation.exchangeBaseUrl,
        resp.body,
      );
      await wex.runWalletDbTx(async (tx) => {
        const [rec, h] = await ctx.getRecordHandle(tx);
        if (!rec) {
          return;
        }
        switch (rec.status) {
          case PeerPushDebitStatus.PendingCreatePurse:
            rec.status = PeerPushDebitStatus.PendingReady;
            break;
          default:
            // Do nothing
            return;
        }
        await h.update(rec, "create-purse");
      });
      return TaskRunResult.progress();
    case HttpStatusCode.Gone:
      await wex.runWalletDbTx(async (tx) => {
        const [rec, h] = await ctx.getRecordHandle(tx);
        if (!rec) {
          return;
        }
        switch (rec.status) {
          case PeerPushDebitStatus.PendingCreatePurse:
            rec.status = purseGoneStatus(rec);
            break;
          default:
            // Do nothing
            return;
        }
        await h.update(rec, "create-purse-gone");
      });
      return TaskRunResult.progress();
    case HttpStatusCode.NotFound:
      await ctx.failTransaction(peerPushInitiation.status, resp.detail);
      return TaskRunResult.finished();
    default:
      assertUnreachable(resp);
  }
}

/**
 * Delete the purse and reclaim the coins that went into it.
 *
 * Runs for both clean-up states: `fromSt` says which one, and with it whether
 * the transaction ends up aborted or expired.
 */
async function processPeerPushDebitDeletePurse(
  wex: WalletExecutionContext,
  peerPushInitiation: WalletPeerPushDebit,
  fromSt:
    | PeerPushDebitStatus.AbortingDeletePurse
    | PeerPushDebitStatus.ExpiredDeletePurse,
): Promise<TaskRunResult> {
  const { pursePub, pursePriv, exchangeBaseUrl } = peerPushInitiation;
  const ctx = new PeerPushDebitTransactionContext(wex, pursePub);
  const exchangeClient = walletExchangeClient(exchangeBaseUrl, wex);
  const sigResp = await wex.cryptoApi.signDeletePurse({
    pursePriv,
  });
  const resp = await exchangeClient.deletePurse(pursePub, sigResp.sig);

  switch (resp.case) {
    case "ok":
      // Successfully deleted the purse, we now refresh.
      break;
    case HttpStatusCode.NotFound:
      // Not found => Previous deletion succeeded.
      // FIXME: Look at response error code more closely
      break;
    case HttpStatusCode.Conflict: {
      // The purse was already decided, which the exchange reports the same way
      // whether it was merged or refunded.  Only the purse itself tells us
      // which: if the recipient merged it, the money is theirs and the coins
      // must not be refreshed.
      const statusResp = await exchangeClient.getPurseStatusAtMerge(pursePub);
      if (statusResp.case === "ok") {
        await requireValidExchangePurseStatus(
          wex,
          exchangeBaseUrl,
          statusResp.body,
        );
      }
      if (statusResp.case === "ok" && isPurseMerged(statusResp.body)) {
        await wex.runWalletDbTx(async (tx) => {
          const [rec, h] = await ctx.getRecordHandle(tx);
          if (!rec) {
            return;
          }
          if (rec.status !== fromSt) {
            return;
          }
          // The abort did not happen, so its reason must not be reported.
          delete rec.abortReason;
          rec.status = PeerPushDebitStatus.Done;
          await h.update(rec, "abort-purse-deposited");
        });
        return TaskRunResult.finished();
      }
      break;
    }
    case HttpStatusCode.Forbidden:
      await ctx.failTransaction(peerPushInitiation.status, resp.detail);
      return TaskRunResult.finished();
    default:
      throwUnexpectedResponse(resp);
  }

  await wex.runWalletDbTx(async (tx) => {
    const [rec, h] = await ctx.getRecordHandle(tx);
    if (!rec) {
      return;
    }

    if (rec.status !== fromSt) {
      return;
    }

    const currency = Amounts.currencyOf(rec.amount);
    const coinPubs: CoinRefreshRequest[] = [];

    if (rec.coinSel) {
      for (let i = 0; i < rec.coinSel.coinPubs.length; i++) {
        coinPubs.push({
          amount: rec.coinSel.contributions[i],
          coinPub: rec.coinSel.coinPubs[i],
        });
      }

      const refresh = await createRefreshGroup(
        wex,
        tx,
        currency,
        coinPubs,
        RefreshReason.AbortPeerPushDebit,
        ctx.transactionId,
      );
      rec.abortRefreshGroupId = refresh.refreshGroupId;
    }

    if (fromSt === PeerPushDebitStatus.ExpiredDeletePurse) {
      rec.status = PeerPushDebitStatus.Expired;
      await h.update(rec, "expire-purse-deleted");
    } else {
      rec.status = PeerPushDebitStatus.Aborted;
      await h.update(rec, "abort-purse-deleted");
    }
  });

  return TaskRunResult.backoff();
}

/**
 * Process the "pending(ready)" state of a peer-push-debit transaction.
 */
async function processPeerPushDebitReady(
  wex: WalletExecutionContext,
  peerPushInitiation: WalletPeerPushDebit,
): Promise<TaskRunResult> {
  logger.trace("processing peer-push-debit pending(ready)");
  const pursePub = peerPushInitiation.pursePub;
  const ctx = new PeerPushDebitTransactionContext(wex, pursePub);
  const exchangeClient = walletExchangeClient(
    peerPushInitiation.exchangeBaseUrl,
    wex,
  );
  const resp = await exchangeClient.getPurseStatusAtMerge(pursePub, true);

  switch (resp.case) {
    case "ok": {
      await requireValidExchangePurseStatus(
        wex,
        peerPushInitiation.exchangeBaseUrl,
        resp.body,
      );
      if (!isPurseMerged(resp.body)) {
        return TaskRunResult.longpollReturnedPending();
      } else {
        await wex.runWalletDbTx(async (tx) => {
          const [rec, h] = await ctx.getRecordHandle(tx);
          if (!rec) {
            return;
          }
          switch (rec.status) {
            case PeerPushDebitStatus.PendingReady:
              rec.status = PeerPushDebitStatus.Done;
              break;
            default:
              // Do nothing
              return;
          }
          await h.update(rec, "ready-done");
        });
        return TaskRunResult.progress();
      }
    }
    case HttpStatusCode.Gone:
      // The exchange answers the merge long-poll with "gone" only when the
      // purse expired.  Nobody aborted here, so the transaction is expired
      // and not aborted, but the coins still have to come back to us.
      logger.info(`purse ${pursePub} expired, refreshing peer-push-debit`);
      await wex.runWalletDbTx(async (tx) => {
        const [rec, h] = await ctx.getRecordHandle(tx);
        if (!rec) {
          return;
        }
        if (rec.status !== PeerPushDebitStatus.PendingReady) {
          return;
        }
        const currency = Amounts.currencyOf(rec.amount);
        const coinPubs: CoinRefreshRequest[] = [];

        if (rec.coinSel) {
          for (let i = 0; i < rec.coinSel.coinPubs.length; i++) {
            coinPubs.push({
              amount: rec.coinSel.contributions[i],
              coinPub: rec.coinSel.coinPubs[i],
            });
          }

          const refresh = await createRefreshGroup(
            wex,
            tx,
            currency,
            coinPubs,
            RefreshReason.AbortPeerPushDebit,
            ctx.transactionId,
          );

          rec.abortRefreshGroupId = refresh.refreshGroupId;
        }
        rec.status = PeerPushDebitStatus.Expired;
        await h.update(rec, "ready-expired");
      });
      return TaskRunResult.backoff();
    case HttpStatusCode.NotFound:
      throw Error("peer push credit disappeared");
    default:
      assertUnreachable(resp);
  }
}

export async function processPeerPushDebit(
  wex: WalletExecutionContext,
  pursePub: string,
): Promise<TaskRunResult> {
  const peerPushInitiation = await wex.runWalletDbTx(async (tx) => {
    return tx.getPeerPushDebit(pursePub);
  });
  if (!peerPushInitiation) {
    return TaskRunResult.finished();
  }

  switch (peerPushInitiation.status) {
    case PeerPushDebitStatus.PendingCreatePurse:
    case PeerPushDebitStatus.PendingReady:
      if (peerPushDebitExpired(peerPushInitiation)) {
        await beginPeerPushDebitExpirationCleanup(
          wex,
          peerPushInitiation,
          "purse-expired",
        );
        return TaskRunResult.progress();
      }
      break;
    default:
      break;
  }

  switch (peerPushInitiation.status) {
    case PeerPushDebitStatus.SuspendedCreatePurse:
    case PeerPushDebitStatus.SuspendedReady:
    case PeerPushDebitStatus.SuspendedAbortingDeletePurse:
    case PeerPushDebitStatus.SuspendedExpiredDeletePurse:
    case PeerPushDebitStatus.Done:
    case PeerPushDebitStatus.Aborted:
    case PeerPushDebitStatus.Failed:
    case PeerPushDebitStatus.Expired:
      return TaskRunResult.finished();
    default:
      break;
  }

  if (!wex.ws.networkAvailable) {
    switch (peerPushInitiation.status) {
      case PeerPushDebitStatus.PendingCreatePurse:
      case PeerPushDebitStatus.PendingReady:
        return TaskRunResult.runAgainAt(
          AbsoluteTime.fromProtocolTimestamp(
            timestampProtocolFromDb(peerPushInitiation.purseExpiration),
          ),
        );
      default:
        return TaskRunResult.networkRequired();
    }
  }

  switch (peerPushInitiation.status) {
    case PeerPushDebitStatus.PendingCreatePurse:
      return processPeerPushDebitCreateReserve(wex, peerPushInitiation);
    case PeerPushDebitStatus.PendingReady:
      return processPeerPushDebitReady(wex, peerPushInitiation);
    case PeerPushDebitStatus.AbortingDeletePurse:
    case PeerPushDebitStatus.ExpiredDeletePurse:
      return processPeerPushDebitDeletePurse(
        wex,
        peerPushInitiation,
        peerPushInitiation.status,
      );
    default: {
      const txState = computePeerPushDebitTransactionState(peerPushInitiation);
      logger.warn(
        `not processing peer-push-debit transaction in state ${j2s(txState)}`,
      );
    }
  }

  return TaskRunResult.finished();
}

/**
 * Initiate sending a peer-to-peer push payment.
 */
export async function initiatePeerPushDebit(
  wex: WalletExecutionContext,
  req: InitiatePeerPushDebitRequest,
): Promise<InitiatePeerPushDebitResponse> {
  const instructedAmount = Amounts.parseOrThrow(
    req.partialContractTerms.amount,
  );
  const currency = Amounts.currencyOf(instructedAmount);

  const requestedExpiration = req.partialContractTerms.purse_expiration;
  if (
    requestedExpiration &&
    (TalerProtocolTimestamp.isNever(requestedExpiration) ||
      isPurseGoneByExpiration(requestedExpiration))
  ) {
    throw TalerError.fromDetail(
      TalerErrorCode.WALLET_CORE_API_BAD_REQUEST,
      { parameter: "partialContractTerms.purse_expiration" },
      "peer push payment expiration must be in the future and finite",
    );
  }

  let quote: PeerPushDebitQuoteV1 | undefined;
  if (req.peerPushDebitQuote) {
    try {
      quote = decodePeerPushDebitQuote(req.peerPushDebitQuote);
    } catch (cause) {
      throw TalerError.fromDetail(
        TalerErrorCode.WALLET_CORE_API_BAD_REQUEST,
        { parameter: "peerPushDebitQuote" },
        cause instanceof Error
          ? cause.message
          : "invalid peer push debit quote",
      );
    }
    if (
      quote.amount !== req.partialContractTerms.amount ||
      !sameScope(quote.restrictScope, req.restrictScope) ||
      (req.exchangeBaseUrl != null &&
        req.exchangeBaseUrl !== quote.exchangeBaseUrl)
    ) {
      throw TalerError.fromDetail(
        TalerErrorCode.WALLET_CORE_API_BAD_REQUEST,
        { parameter: "peerPushDebitQuote" },
        "peer push debit quote does not match the request",
      );
    }
    if (!req.partialContractTerms.purse_expiration) {
      throw TalerError.fromDetail(
        TalerErrorCode.WALLET_CORE_API_BAD_REQUEST,
        { parameter: "partialContractTerms.purse_expiration" },
        "quoted peer push debit requires an explicit expiration",
      );
    }
  }

  if (req.exchangeBaseUrl != null && req.restrictScope != null) {
    throw TalerError.fromDetail(
      TalerErrorCode.WALLET_CORE_API_BAD_REQUEST,
      { parameter: "restrictScope" },
      "exchangeBaseUrl and restrictScope are mutually exclusive",
    );
  }

  let restrictScope: ScopeInfo | undefined;

  if (req.exchangeBaseUrl != null) {
    restrictScope = {
      type: ScopeType.Exchange,
      currency,
      url: req.exchangeBaseUrl,
    };
  } else if (req.restrictScope != null) {
    restrictScope = req.restrictScope;
  }

  const pursePair = await wex.cryptoApi.createEddsaKeypair({});
  const mergePair = await wex.cryptoApi.createEddsaKeypair({});

  const contractKeyPair = await wex.cryptoApi.createEddsaKeypair({});

  const pursePub = pursePair.pub;

  const ctx = new PeerPushDebitTransactionContext(wex, pursePub);

  const contractEncNonce = encodeCrock(getRandomBytes(24));

  await updateWithdrawalDenomsForCurrency(wex, instructedAmount.currency);

  let exchangeBaseUrl: string | undefined;

  await wex.runWalletDbTx(async (tx) => {
    const coinSelRes = await selectPeerCoinsInTx(wex, tx, {
      instructedAmount,
      restrictScope: restrictScope,
      exchangeBaseUrl: quote?.exchangeBaseUrl,
      feesCoveredByCounterparty: false,
    });

    let coins: SelectedProspectiveCoin[] | undefined = undefined;

    switch (coinSelRes.type) {
      case "failure":
        if (quote) {
          quoteChanged("the reviewed funds are no longer available");
        }
        throw TalerError.fromDetail(
          TalerErrorCode.WALLET_PEER_PUSH_PAYMENT_INSUFFICIENT_BALANCE,
          {
            insufficientBalanceDetails: coinSelRes.insufficientBalanceDetails,
          },
        );
      case "success":
        coins = coinSelRes.result.coins;
        break;
      default:
        assertUnreachable(coinSelRes);
    }

    logger.trace(j2s(coinSelRes));

    const sel = coinSelRes.result;

    logger.trace(
      `peer debit instructed amount: ${Amounts.stringify(instructedAmount)}`,
    );
    logger.trace(
      `peer debit contract terms amount: ${Amounts.stringify(
        req.partialContractTerms.amount,
      )}`,
    );
    logger.trace(
      `peer debit deposit fees: ${Amounts.stringify(sel.totalDepositFees)}`,
    );

    exchangeBaseUrl = coinSelRes.result.exchangeBaseUrl;

    if (quote && exchangeBaseUrl !== quote.exchangeBaseUrl) {
      quoteChanged("the selected exchange changed");
    }

    const ex = await getExchangeDetailsInTx(tx, exchangeBaseUrl);
    const myExpiration =
      req.partialContractTerms.purse_expiration ??
      AbsoluteTime.toProtocolTimestamp(
        AbsoluteTime.addDuration(
          AbsoluteTime.now(),
          Duration.fromTalerProtocolDuration(
            ex?.defaultPeerPushExpiration ?? fallbackDefaultPeerPushExpiration,
          ),
        ),
      );

    if (
      TalerProtocolTimestamp.isNever(myExpiration) ||
      isPurseGoneByExpiration(myExpiration)
    ) {
      throw TalerError.fromDetail(
        TalerErrorCode.WALLET_CORE_API_BAD_REQUEST,
        { parameter: "partialContractTerms.purse_expiration" },
        "peer push payment expiration must be in the future and finite",
      );
    }

    if (
      quote &&
      (timestampAfter(myExpiration, quote.maxExpirationDate) ||
        timestampAfter(myExpiration, coinSelRes.result.maxExpirationDate))
    ) {
      quoteChanged("the reviewed expiration is no longer available");
    }

    const contractTerms: PeerContractTerms = {
      ...req.partialContractTerms,
      purse_expiration: myExpiration,
    };

    // We can only compute the contract terms after we've set
    // the expiration.
    const hContractTerms = ContractTermsUtil.hashContractTerms(contractTerms);

    const totalAmount = await getTotalPeerPaymentCostInTx(wex, tx, coins);
    if (
      quote &&
      Amounts.cmp(totalAmount, Amounts.parseOrThrow(quote.amountEffective)) !==
        0
    ) {
      quoteChanged("the effective amount changed");
    }
    const ppi: WalletPeerPushDebit = {
      amount: Amounts.stringify(instructedAmount),
      restrictScope: req.restrictScope,
      contractPriv: contractKeyPair.priv,
      contractPub: contractKeyPair.pub,
      contractTermsHash: hContractTerms,
      exchangeBaseUrl: sel.exchangeBaseUrl,
      mergePriv: mergePair.priv,
      mergePub: mergePair.pub,
      purseExpiration: timestampProtocolToDb(myExpiration),
      pursePriv: pursePair.priv,
      pursePub: pursePair.pub,
      timestampCreated: timestampPreciseToDb(TalerPreciseTimestamp.now()),
      status: PeerPushDebitStatus.PendingCreatePurse,
      contractEncNonce,
      totalCost: Amounts.stringify(totalAmount),
    };

    if (coinSelRes.type === "success") {
      ppi.coinSel = {
        coinPubs: coinSelRes.result.coins.map((x) => x.coinPub),
        contributions: coinSelRes.result.coins.map((x) => x.contribution),
      };
      // FIXME: Instead of directly doing a spendCoin here,
      // we might want to mark the coins as used and spend them
      // after we've been able to create the purse.
      await spendCoins(wex, tx, {
        transactionId: ctx.transactionId,
        coinPubs: coinSelRes.result.coins.map((x) => x.coinPub),
        contributions: coinSelRes.result.coins.map((x) =>
          Amounts.parseOrThrow(x.contribution),
        ),
        refreshReason: RefreshReason.PayPeerPush,
      });
    }
    await tx.upsertContractTerms({
      h: hContractTerms,
      contractTermsRaw: contractTerms,
    });
    const [oldRec, h] = await ctx.getRecordHandle(tx);
    if (oldRec) {
      throw Error("record for peer-push-debit already exists");
    }
    await h.update(ppi, "initiate");
  });

  wex.taskScheduler.startShepherdTask(ctx.taskId);

  return {
    contractPriv: contractKeyPair.priv,
    mergePriv: mergePair.priv,
    pursePub: pursePair.pub,
    exchangeBaseUrl: exchangeBaseUrl!,
    transactionId: constructTransactionIdentifier({
      tag: TransactionType.PeerPushDebit,
      pursePub: pursePair.pub,
    }),
  };
}

export function computePeerPushDebitTransactionActions(
  ppiRecord: WalletPeerPushDebit,
): TransactionAction[] {
  switch (ppiRecord.status) {
    case PeerPushDebitStatus.PendingCreatePurse:
      return [
        TransactionAction.Retry,
        TransactionAction.Abort,
        TransactionAction.Suspend,
      ];
    case PeerPushDebitStatus.PendingReady:
      return [
        TransactionAction.Retry,
        TransactionAction.Abort,
        TransactionAction.Suspend,
      ];
    case PeerPushDebitStatus.Aborted:
      return [TransactionAction.Delete];
    case PeerPushDebitStatus.AbortingDeletePurse:
    case PeerPushDebitStatus.ExpiredDeletePurse:
      return [
        TransactionAction.Retry,
        TransactionAction.Suspend,
        TransactionAction.Fail,
      ];
    case PeerPushDebitStatus.SuspendedAbortingDeletePurse:
    case PeerPushDebitStatus.SuspendedExpiredDeletePurse:
      return [TransactionAction.Resume, TransactionAction.Fail];
    case PeerPushDebitStatus.SuspendedCreatePurse:
      return [TransactionAction.Resume, TransactionAction.Abort];
    case PeerPushDebitStatus.SuspendedReady:
      return [TransactionAction.Resume, TransactionAction.Abort];
    case PeerPushDebitStatus.Done:
      return [TransactionAction.Delete];
    case PeerPushDebitStatus.Expired:
      return [TransactionAction.Delete];
    case PeerPushDebitStatus.Failed:
      return [TransactionAction.Delete];
  }
}

export function computePeerPushDebitTransactionState(
  ppiRecord: WalletPeerPushDebit,
): TransactionState {
  switch (ppiRecord.status) {
    case PeerPushDebitStatus.PendingCreatePurse:
      return {
        major: TransactionMajorState.Pending,
        minor: TransactionMinorState.CreatePurse,
        working: true,
      };
    case PeerPushDebitStatus.PendingReady:
      return {
        major: TransactionMajorState.Pending,
        minor: TransactionMinorState.Ready,
      };
    case PeerPushDebitStatus.Aborted:
      return {
        major: TransactionMajorState.Aborted,
      };
    case PeerPushDebitStatus.AbortingDeletePurse:
    case PeerPushDebitStatus.ExpiredDeletePurse:
      return {
        major: TransactionMajorState.Aborting,
        minor: TransactionMinorState.DeletePurse,
        working: true,
      };
    case PeerPushDebitStatus.SuspendedAbortingDeletePurse:
    case PeerPushDebitStatus.SuspendedExpiredDeletePurse:
      return {
        major: TransactionMajorState.SuspendedAborting,
        minor: TransactionMinorState.DeletePurse,
      };
    case PeerPushDebitStatus.SuspendedCreatePurse:
      return {
        major: TransactionMajorState.Suspended,
        minor: TransactionMinorState.CreatePurse,
      };
    case PeerPushDebitStatus.SuspendedReady:
      return {
        major: TransactionMajorState.Suspended,
        minor: TransactionMinorState.Ready,
      };
    case PeerPushDebitStatus.Done:
      return {
        major: TransactionMajorState.Done,
      };
    case PeerPushDebitStatus.Failed:
      return {
        major: TransactionMajorState.Failed,
      };
    case PeerPushDebitStatus.Expired:
      return {
        major: TransactionMajorState.Expired,
      };
  }
}
