/**
 * Benchmark for {@link WalletDbTransaction} implementations.
 *
 * Populates a synthetic wallet of a given size and times the queries the
 * wallet actually runs on its hot paths, against every backend.
 *
 * This exists because the integration suite cannot answer questions about the
 * storage layer.  Its timings are dominated by network long-polls -- the task
 * shepherd sleeps 10s whenever a long-poller returns sooner than 20s, and both
 * backends hit that in some runs -- so a storage change of a few per cent is
 * invisible under that noise.  It also never builds a wallet large enough for
 * index size to matter.  This benchmark touches no services and no scheduler.
 *
 * Every measurement is reported as a median of repeated runs, not a single
 * sample: single samples of this system have repeatedly proved misleading.
 */

import {
  AmountString,
  CoinStatus,
  DenomKeyType,
  encodeCrock,
  Logger,
} from "@gnu-taler/taler-util";
import {
  CoinSourceType,
  DenominationVerificationStatus,
  DbProtocolTimestamp,
  WalletCoin,
  WalletCoinAvailability,
  WalletDenomination,
} from "../records.js";
import type { DbTxRunner } from "./conformance.js";

const logger = new Logger("db/testing/benchmark.ts");

export interface DbBenchOptions {
  /** Coins to insert.  The default is small enough to run in seconds. */
  numCoins: number;
  /** Denominations to spread those coins over. */
  numDenominations: number;
  /** Exchanges to spread the denominations over. */
  numExchanges: number;
  /** How many times each query is repeated; the median is reported. */
  repeats: number;
}

export const defaultDbBenchOptions: DbBenchOptions = {
  numCoins: 20000,
  numDenominations: 200,
  numExchanges: 3,
  repeats: 5,
};

export interface DbBenchQueryResult {
  name: string;
  /** Median wall-clock time over `repeats` runs. */
  medianMs: number;
  minMs: number;
  maxMs: number;
  /** Rows the query returned, to catch a "fast because it found nothing". */
  rows: number;
}

export interface DbBenchResult {
  backend: string;
  options: DbBenchOptions;
  populateMs: number;
  /** Size of the database on disk, when it is file-backed. */
  dbSizeBytes?: number;
  queries: DbBenchQueryResult[];
}

function median(xs: number[]): number {
  const s = [...xs].sort((a, b) => a - b);
  const mid = Math.floor(s.length / 2);
  return s.length % 2 ? s[mid] : (s[mid - 1] + s[mid]) / 2;
}

/**
 * Deterministic Crockford value of the right length.
 *
 * Built by encoding bytes rather than by picking characters.  Real wallet
 * values are always canonical encodings, and picking characters produces
 * non-canonical ones: 52 Crockford characters carry 260 bits while a key is
 * 256, so only about one random string in 16 is a spelling the database will
 * hand back.  Generating those measured a workload the wallet never runs.
 */
function crockLike(seed: string, numBytes: number): string {
  const bytes = new Uint8Array(numBytes);
  // Math.imul, not `*`: 32-bit hash multiplication overflows a double and
  // silently loses the low bits, which collapses distinct seeds onto the same
  // output.  An earlier version did that and produced 4 distinct coin public
  // keys for 500 coins -- every insert after the fourth was an upsert over an
  // existing row, and the benchmark then measured a nearly empty database.
  let h = 2166136261;
  for (let i = 0; i < seed.length; i++) {
    h = Math.imul(h ^ seed.charCodeAt(i), 16777619);
  }
  for (let i = 0; i < numBytes; i++) {
    h = Math.imul(h ^ (h >>> 15), 2246822519);
    h = (h ^ (h >>> 13)) >>> 0;
    bytes[i] = h & 0xff;
  }
  return encodeCrock(bytes);
}

const key = (s: string) => crockLike(s, 32);
const hash = (s: string) => crockLike(s, 64);

function exchangeUrl(i: number): string {
  return `https://exchange-${i}.test/`;
}

export async function populateDbBench(
  runner: DbTxRunner,
  opts: DbBenchOptions,
): Promise<void> {
  // Denominations and their availability rows.
  await runner.runReadWriteTx(async (tx) => {
    const familySerials: number[] = [];
    for (let exchange = 0; exchange < opts.numExchanges; exchange++) {
      familySerials.push(
        await tx.upsertDenominationFamily({
          familyParams: {
            exchangeBaseUrl: exchangeUrl(exchange),
            exchangeMasterPub: key(`master-${exchange}`),
            value: "TESTKUDOS:1" as AmountString,
            feeWithdraw: "TESTKUDOS:0.01" as AmountString,
            feeDeposit: "TESTKUDOS:0.01" as AmountString,
            feeRefresh: "TESTKUDOS:0.01" as AmountString,
            feeRefund: "TESTKUDOS:0.01" as AmountString,
          },
        }),
      );
    }
    for (let d = 0; d < opts.numDenominations; d++) {
      const exchange = d % opts.numExchanges;
      const ex = exchangeUrl(exchange);
      const dph = hash(`denom-${d}`);
      const masterPub = key(`master-${exchange}`);
      const denom: WalletDenomination = {
        denomPubHash: dph,
        denomPub: {
          cipher: DenomKeyType.Rsa,
          rsa_public_key: `rsa-${d}`,
          age_mask: 0,
        },
        exchangeBaseUrl: ex,
        exchangeMasterPub: masterPub,
        currency: "TESTKUDOS",
        value: "TESTKUDOS:1" as AmountString,
        denominationFamilySerial: familySerials[exchange],
        stampStart: (1000 + d) as DbProtocolTimestamp,
        stampExpireWithdraw: (2000 + d) as DbProtocolTimestamp,
        stampExpireDeposit: (3000 + d) as DbProtocolTimestamp,
        stampExpireLegal: (4000 + d) as DbProtocolTimestamp,
        fees: {
          feeDeposit: "TESTKUDOS:0.01" as AmountString,
          feeRefresh: "TESTKUDOS:0.01" as AmountString,
          feeRefund: "TESTKUDOS:0.01" as AmountString,
          feeWithdraw: "TESTKUDOS:0.01" as AmountString,
        },
        isOffered: true,
        isRevoked: false,
        masterSig: hash(`msig-${d}`),
        verificationStatus: DenominationVerificationStatus.VerifiedGood,
      };
      await tx.upsertDenomination(denom);
      const avail: WalletCoinAvailability = {
        exchangeBaseUrl: ex,
        exchangeMasterPub: masterPub,
        denomPubHash: dph,
        maxAge: d % 2 === 0 ? 0 : 21,
        currency: "TESTKUDOS",
        value: "TESTKUDOS:1" as AmountString,
        freshCoinCount: 10,
        hasFreshCoins: 1,
        visibleCoinCount: 10,
      };
      await tx.upsertCoinAvailability(avail);
    }
  });

  // Coins, in batches so a single transaction does not grow unbounded.
  const batch = 2000;
  for (let start = 0; start < opts.numCoins; start += batch) {
    await runner.runReadWriteTx(async (tx) => {
      for (let i = start; i < Math.min(start + batch, opts.numCoins); i++) {
        const d = i % opts.numDenominations;
        const coin: WalletCoin = {
          coinPub: key(`coin-${i}`),
          coinPriv: key(`coinpriv-${i}`),
          exchangeBaseUrl: exchangeUrl(d % opts.numExchanges),
          exchangeMasterPub: key(`master-${d % opts.numExchanges}`),
          denomPubHash: hash(`denom-${d}`),
          denomSig: { cipher: DenomKeyType.Rsa, rsa_signature: `sig-${i}` },
          blindingKey: key(`bk-${i}`),
          exchangeWithdrawValues: { cipher: DenomKeyType.Rsa },
          coinEvHash: hash(`evh-${i}`),
          // Derived from the row *within* a denomination, not from i: with
          // `i % 4` the dormant coins land on multiples of 4, which for many
          // denomination counts means every coin of some denominations is
          // dormant and the fresh-coin query then measures an empty result.
          status:
            Math.floor(i / opts.numDenominations) % 4 === 0
              ? CoinStatus.Dormant
              : CoinStatus.Fresh,
          maxAge: d % 2 === 0 ? 0 : 21,
          ageCommitmentProof: undefined,
          coinSource: {
            type: CoinSourceType.Withdraw,
            withdrawalGroupId: key(`wg-${i % 100}`),
            coinIndex: i,
            reservePub: key(`rp-${i % 100}`),
          },
        };
        await tx.upsertCoin(coin);
      }
    });
  }
}

/**
 * Run the benchmark against one already-populated runner.
 */
export async function measureDbBenchQueries(
  runner: DbTxRunner,
  opts: DbBenchOptions,
): Promise<DbBenchQueryResult[]> {
  const results: DbBenchQueryResult[] = [];

  const time = async (
    name: string,
    f: () => Promise<number>,
  ): Promise<void> => {
    const samples: number[] = [];
    let rows = 0;
    for (let i = 0; i < opts.repeats; i++) {
      const t0 = performance.now();
      rows = await f();
      samples.push(performance.now() - t0);
    }
    results.push({
      name,
      medianMs: median(samples),
      minMs: Math.min(...samples),
      maxMs: Math.max(...samples),
      rows,
    });
  };

  // A point lookup on the primary key, the single most common operation.
  const someCoin = key(`coin-${Math.floor(opts.numCoins / 2)}`);
  await time("getCoin (point lookup)", async () =>
    runner.runReadWriteTx(async (tx) => ((await tx.getCoin(someCoin)) ? 1 : 0)),
  );

  // Batch lookup: this is the shape refresh uses, and was an N+1 until
  // recently, so it is worth keeping an eye on.
  const pubs: string[] = [];
  for (let i = 0; i < Math.min(200, opts.numCoins); i++) {
    pubs.push(key(`coin-${i}`));
  }
  await time("getCoinsByPubs (200)", async () =>
    runner.runReadWriteTx(async (tx) => (await tx.getCoinsByPubs(pubs)).length),
  );

  await time("getCoinsByExchange", async () =>
    runner.runReadWriteTx(
      async (tx) => (await tx.getCoinsByExchange(exchangeUrl(0))).length,
    ),
  );

  await time("countCoinsByExchange", async () =>
    runner.runReadWriteTx(async (tx) =>
      tx.countCoinsByExchange(exchangeUrl(0)),
    ),
  );

  await time("getCoinsByDenomPubHash", async () =>
    runner.runReadWriteTx(
      async (tx) => (await tx.getCoinsByDenomPubHash(hash("denom-0"))).length,
    ),
  );

  // Indexed multi-column lookup with a limit -- coin selection's hot path.
  await time("getFreshCoinsByDenomAndAge (limit 10)", async () =>
    runner.runReadWriteTx(
      async (tx) =>
        (
          await tx.getFreshCoinsByDenomAndAge(
            {
              exchangeMasterPub: key("master-0"),
              denomPubHash: hash("denom-0"),
              maxAge: 0,
            },
            10,
          )
        ).length,
    ),
  );

  await time("getCoinAvailabilityByExchangeAndAgeRange", async () =>
    runner.runReadWriteTx(
      async (tx) =>
        (
          await tx.getCoinAvailabilityByExchangeAndAgeRange(
            exchangeUrl(0),
            0,
            21,
          )
        ).length,
    ),
  );

  // The early-terminating keyset scan.  Deliberately matches nothing until
  // late, so a backend that materialises the whole family shows up here.
  await time("findDenominationByFamilyFromExpiry", async () =>
    runner.runReadWriteTx(async (tx) => {
      const found = await tx.findDenominationByFamilyFromExpiry(
        1,
        0 as DbProtocolTimestamp,
        () => true,
      );
      return found ? 1 : 0;
    }),
  );

  await time("getDenominationsByMasterPub", async () =>
    runner.runReadWriteTx(
      async (tx) =>
        (await tx.getDenominationsByMasterPub(key("master-0"))).length,
    ),
  );

  // Full scans: the wallet does these on balance computation and purge.
  await time("listAllCoins (full scan)", async () =>
    runner.runReadWriteTx(async (tx) => (await tx.listAllCoins()).length),
  );

  await time("getCoinAvailabilities (full scan)", async () =>
    runner.runReadWriteTx(
      async (tx) => (await tx.getCoinAvailabilities()).length,
    ),
  );

  // A write-heavy transaction, to keep an eye on commit cost.
  await time("upsertCoin x100 (one tx)", async () =>
    runner.runReadWriteTx(async (tx) => {
      for (let i = 0; i < 100; i++) {
        const coin = await tx.getCoin(key(`coin-${i}`));
        if (coin) {
          coin.status =
            coin.status === CoinStatus.Fresh
              ? CoinStatus.Dormant
              : CoinStatus.Fresh;
          await tx.upsertCoin(coin);
        }
      }
      return 100;
    }),
  );

  return results;
}

/**
 * Populate and measure one backend.
 */
export async function benchmarkOneBackend(
  runner: DbTxRunner,
  opts: DbBenchOptions,
  dbSizeBytes?: () => number | undefined,
): Promise<DbBenchResult> {
  logger.info(`populating ${runner.name}: ${opts.numCoins} coins`);
  const t0 = performance.now();
  await populateDbBench(runner, opts);
  const populateMs = performance.now() - t0;
  logger.info(`populated in ${populateMs.toFixed(0)} ms, measuring`);

  // Verify the database really holds what was asked for.  A benchmark on a
  // database that silently failed to populate reports beautiful numbers for
  // queries that match nothing, which is worse than no benchmark at all.
  const actualCoins = await runner.runReadWriteTx(
    async (tx) => (await tx.listAllCoins()).length,
  );
  if (actualCoins !== opts.numCoins) {
    throw Error(
      `benchmark population is wrong: asked for ${opts.numCoins} coins, ` +
        `database holds ${actualCoins}. Refusing to report timings.`,
    );
  }
  const queries = await measureDbBenchQueries(runner, opts);
  return {
    backend: runner.name,
    options: opts,
    populateMs,
    dbSizeBytes: dbSizeBytes?.(),
    queries,
  };
}

/**
 * Render results as a table, with the second and later backends shown
 * relative to the first.
 */
export function formatDbBenchResults(results: DbBenchResult[]): string {
  const lines: string[] = [];
  const base = results[0];
  lines.push("");
  lines.push(
    `wallet DB benchmark: ${base.options.numCoins} coins, ` +
      `${base.options.numDenominations} denominations, ` +
      `${base.options.numExchanges} exchanges, ` +
      `median of ${base.options.repeats}`,
  );
  lines.push("");
  for (const r of results) {
    const size =
      r.dbSizeBytes != null
        ? `, db ${(r.dbSizeBytes / 1024 / 1024).toFixed(1)} MiB`
        : "";
    lines.push(
      `${r.backend}: populate ${(r.populateMs / 1000).toFixed(1)} s${size}`,
    );
  }
  lines.push("");
  const nameWidth = Math.max(
    ...base.queries.map((q) => q.name.length),
    "query".length,
  );
  const head = ["query".padEnd(nameWidth), ...results.map((r) => r.backend)];
  lines.push(head.join("  |  "));
  lines.push("-".repeat(head.join("  |  ").length));
  for (let i = 0; i < base.queries.length; i++) {
    const cells = [base.queries[i].name.padEnd(nameWidth)];
    for (let j = 0; j < results.length; j++) {
      const q = results[j].queries[i];
      let cell = `${q.medianMs.toFixed(2)} ms (${q.rows})`;
      if (j > 0) {
        const ratio = q.medianMs / base.queries[i].medianMs;
        cell += ` ${ratio.toFixed(2)}x`;
      }
      cells.push(cell);
    }
    lines.push(cells.join("  |  "));
  }
  lines.push("");
  lines.push(
    "Row counts are shown in parentheses: a query that got faster by " +
      "returning nothing is a bug, not a win.",
  );
  return lines.join("\n");
}
