/**
 * Imports.
 */
import {
  BridgeIDBFactory,
  createSqliteBackendOverDb,
  shimIndexedDB,
} from "@gnu-taler/idb-bridge";
import { createNodeHelperSqlite3Impl } from "@gnu-taler/idb-bridge/node-helper-sqlite3-impl";
import {
  Logger,
  SetTimeoutTimerAPI,
  WalletRunConfig,
} from "@gnu-taler/taler-util";
import { createPlatformHttpLib } from "@gnu-taler/taler-util/http";
import { NodeThreadCryptoWorkerFactory } from "./crypto/workers/nodeThreadWorker.js";
import { SynchronousCryptoWorkerFactoryPlain } from "./crypto/workers/synchronousWorkerFactoryPlain.js";
import {
  acquireSqliteWalletDbOwnership,
  DefaultNodeWalletArgs,
  getSqlite3FilenameFromStoragePath,
} from "./host-common.js";
import { openNativeSqliteWalletDb } from "./db/sqlite/database.js";
import { Wallet } from "./wallet.js";
import { WalletDbHandle } from "./db/handle.js";
import {
  dropExpiredMigrationBackup,
  inspectWalletDbFile,
  inspectWalletDbFileDetails,
  MigrationAuthority,
  migrateWalletDbToNative,
  NativeMigrationInfo,
  openNativeWalletDbForEmptyStorage,
  readNativeMigrationInfo,
  restoreMigrationBackup,
  resolveAmbiguousWalletDb,
  WalletDbFileKind,
} from "./db/migration/native.js";
import * as fs from "node:fs";
import { IdbWalletDbHandle } from "./db/indexeddb/handle.js";
import { SqliteWalletDbHandle } from "./db/sqlite/handle.js";

const logger = new Logger("host-impl.node.ts");

async function makeSqliteDb(
  args: DefaultNodeWalletArgs,
): Promise<WalletDbHandle> {
  const tracing = !!process.env.TALER_WALLET_DBTRACING;
  BridgeIDBFactory.enableTracing = tracing;
  const dbFilename = getSqlite3FilenameFromStoragePath(
    args.persistentStoragePath,
  );

  // One connection for both schemas: a migration reads one and writes the
  // other in this same file, and a second connection to it would bring its
  // own transaction state and its own locks.
  const imp = await createNodeHelperSqlite3Impl();
  const db = await imp.open(dbFilename);
  try {
    await acquireSqliteWalletDbOwnership(db);
  } catch (e) {
    await db.close();
    throw e;
  }

  // Exactly one backend is opened.  Opening both meant every operation that
  // works on the whole database had to pick one, and picking wrong produced a
  // valid empty database rather than an error.
  //
  // Which schema the file's records are already in decides that; the
  // environment variable only says what a database that does not exist yet
  // should be created as.
  const kind = await inspectWalletDbFile(db);
  if (kind === "ambiguous") {
    await db.close();
    throw Error(
      `${dbFilename} contains records in both wallet schemas and has no trustworthy authority marker; inspect it and use advanced db-migration-resolve`,
    );
  }
  if (
    kind === "native" ||
    (kind === "empty" && process.env.TALER_WALLET_NATIVE_DB)
  ) {
    logger.info(`using NATIVE sqlite3 wallet DB at ${dbFilename}`);
    logger.warn("the native sqlite3 wallet DB backend is experimental");
    // Opening is the moment nothing holds the database, which is what
    // dropping tables needs.
    await dropExpiredMigrationBackup(db);
    const ndb = await openNativeSqliteWalletDb(db);
    return new SqliteWalletDbHandle(ndb);
  }
  if (process.env.TALER_WALLET_NATIVE_DB) {
    logger.warn(
      `${dbFilename} holds an IndexedDB-emulation wallet database; opening` +
        ` it natively would show an empty wallet.  Set` +
        ` TALER_WALLET_MIGRATE_NATIVE_DB=1 to convert it instead.`,
    );
  }

  logger.info(`using database ${dbFilename}`);
  const myBackend = await createSqliteBackendOverDb(imp, db);
  myBackend.enableTracing = tracing;
  if (process.env.TALER_WALLET_STATS) {
    myBackend.trackStats = true;
  }
  const handle = new IdbWalletDbHandle(
    new BridgeIDBFactory(myBackend),
    () => myBackend.accessStats,
  );
  handle.exportToFile = async (directory, stem) => {
    const path = `${directory}/${stem}.sqlite3`;
    await myBackend.backupToFile(path);
    return { path };
  };
  handle.getDiagnosticStats = () => myBackend.accessStats;
  handle.migrateToNative = async (options) =>
    (await migrateWalletDbToNative(db, handle, options)).handle;
  if (kind === "empty") {
    handle.openNativeIfEmpty = async () =>
      openNativeWalletDbForEmptyStorage(db);
  }
  return handle;
}

/**
 * What a wallet database file on disk holds and where it came from.
 *
 * Opens the file directly rather than through a wallet: the questions it
 * answers -- which schema is authoritative, whether a rollback is still
 * possible -- are about a database nobody should be running.
 */
export async function inspectWalletDbPath(dbPath: string): Promise<{
  kind: WalletDbFileKind;
  migration: NativeMigrationInfo | undefined;
  indexedDbRecords: number;
  nativeRecords: number;
  ambiguityReason?: string;
}> {
  if (!fs.existsSync(dbPath)) {
    throw Error(`wallet database ${dbPath} does not exist`);
  }
  const imp = await createNodeHelperSqlite3Impl();
  const db = await imp.open(dbPath);
  try {
    const inspection = await inspectWalletDbFileDetails(db);
    return { ...inspection, migration: await readNativeMigrationInfo(db) };
  } finally {
    await db.close();
  }
}

/** Back up and explicitly select the authoritative schema of an ambiguous file. */
export async function resolveWalletDbMigration(
  dbPath: string,
  keep: MigrationAuthority,
  backupPath: string,
): Promise<void> {
  if (!fs.existsSync(dbPath))
    throw Error(`wallet database ${dbPath} does not exist`);
  if (fs.existsSync(backupPath))
    throw Error(`backup destination ${backupPath} already exists`);
  const imp = await createNodeHelperSqlite3Impl();
  const db = await imp.open(dbPath);
  try {
    const before = await inspectWalletDbFileDetails(db);
    if (before.kind !== "ambiguous") {
      throw Error(
        `database is ${before.kind}, not ambiguous; refusing recovery`,
      );
    }
    // VACUUM INTO is SQLite's consistent full-file snapshot.  It runs before
    // schema initialization or authority changes, and refuses an existing file.
    await (
      await db.prepare("VACUUM INTO $filename")
    ).run({ filename: backupPath });
    await resolveAmbiguousWalletDb(db, keep);
  } finally {
    await db.close();
  }
}

/**
 * Undo an in-place migration, from the copy it retained.
 *
 * Everything the wallet did since the migration is in the native tables and
 * stays there; what comes back is the database as it was the moment before
 * the migration ran.  The wallet must not be running.
 */
export async function rollbackWalletDbMigration(dbPath: string): Promise<void> {
  if (!fs.existsSync(dbPath)) {
    throw Error(`wallet database ${dbPath} does not exist`);
  }
  const imp = await createNodeHelperSqlite3Impl();
  const db = await imp.open(dbPath);
  try {
    await restoreMigrationBackup(db);
  } finally {
    await db.close();
  }
}

/**
 * Get a wallet instance with default settings for node.
 *
 * Extended version that allows getting DB stats.
 */
export async function createNativeWalletHost2(
  args: DefaultNodeWalletArgs = {},
): Promise<{
  wallet: Wallet;
}> {
  const myHttpFactory = (config: WalletRunConfig) => {
    let myHttpLib;
    if (args.httpLib) {
      myHttpLib = args.httpLib;
    } else {
      myHttpLib = createPlatformHttpLib({
        enableThrottling: true,
        requireTls: !config.features.allowHttp,
      });
    }
    return myHttpLib;
  };

  let dbResp: WalletDbHandle;

  if (
    args.persistentStoragePath &&
    args.persistentStoragePath.endsWith(".json")
  ) {
    throw Error("memory backend not supported");
  } else {
    logger.info(`using sqlite3 DB backend`);
    dbResp = await makeSqliteDb(args);
  }

  // Only meaningful for the IndexedDB backend; with the native one there is
  // no emulation to expose as a global.
  if (dbResp instanceof IdbWalletDbHandle) {
    shimIndexedDB(dbResp.factory());
  }

  let workerFactory;
  const cryptoWorkerType = args.cryptoWorkerType ?? "node-worker-thread";
  if (cryptoWorkerType === "sync") {
    logger.info("using synchronous crypto worker");
    workerFactory = new SynchronousCryptoWorkerFactoryPlain();
  } else if (cryptoWorkerType === "node-worker-thread") {
    workerFactory = new NodeThreadCryptoWorkerFactory();
    logger.info("using node thread crypto worker");
  } else {
    throw Error(`unsupported crypto worker type '${cryptoWorkerType}'`);
  }

  const timer = new SetTimeoutTimerAPI();

  const w = await Wallet.create(dbResp, myHttpFactory, timer, workerFactory);

  if (args.notifyHandler) {
    w.addNotificationListener(args.notifyHandler);
  }
  return {
    wallet: w,
  };
}
