const logger = new Logger("coinSelection.ts");

export function denominationTermsMatchAcrossMasterKeys(
  historical: WalletDenomination,
  current: WalletDenomination,
): boolean {
  return (
    historical.denomPubHash === current.denomPubHash &&
    historical.currency === current.currency &&
    Amounts.cmp(historical.value, current.value) === 0 &&
    Amounts.cmp(historical.fees.feeDeposit, current.fees.feeDeposit) === 0 &&
    Amounts.cmp(historical.fees.feeRefresh, current.fees.feeRefresh) === 0 &&
    Amounts.cmp(historical.fees.feeRefund, current.fees.feeRefund) === 0 &&
    Amounts.cmp(historical.fees.feeWithdraw, current.fees.feeWithdraw) === 0 &&
    historical.stampStart === current.stampStart &&
    historical.stampExpireWithdraw === current.stampExpireWithdraw &&
    historical.stampExpireDeposit === current.stampExpireDeposit &&
    historical.stampExpireLegal === current.stampExpireLegal
  );
}

export type PreviousPayCoins = {
  coinPub: string;
  contribution: AmountJson;
}[];

/**
 * Coins that a re-selection added on top of the ones it carried over.
 *
 * A carried-over coin keeps its previous contribution, so each entry of the
 * repair list accounts for exactly one occurrence in the new selection.
 * Occurrences beyond that were selected now and still have to be marked as
 * spent by the caller.
 */
export function coinsAddedByRepair(
  repair: PreviousPayCoins,
  selected: SelectedCoin[],
): SelectedCoin[] {
  const carriedOver = new Map<string, number>();
  for (const prev of repair) {
    carriedOver.set(prev.coinPub, (carriedOver.get(prev.coinPub) ?? 0) + 1);
  }
  const added: SelectedCoin[] = [];
  for (const coin of selected) {
    const remaining = carriedOver.get(coin.coinPub) ?? 0;
    if (remaining > 0) {
      carriedOver.set(coin.coinPub, remaining - 1);
      continue;
    }
    added.push(coin);
  }
  return added;
}

export interface ExchangeRestrictionSpec {
  exchanges: AllowedExchangeInfo[];
  auditors: AllowedAuditorInfo[];
}

export interface CoinSelectionTally {
  /**
   * Amount that still needs to be paid.
   * May increase during the computation when fees need to be covered.
   */
  amountPayRemaining: AmountJson;

  /**
   * Allowance given by the merchant towards deposit fees
   * (and wire fees after wire fee limit is exhausted)
   */
  amountDepositFeeLimitRemaining: AmountJson;

  customerDepositFees: AmountJson;

  totalDepositFees: AmountJson;

  customerWireFees: AmountJson;

  wireFeeCoveredForExchange: Set<string>;
}

function cloneTally(tally: CoinSelectionTally): CoinSelectionTally {
  return {
    amountDepositFeeLimitRemaining: tally.amountDepositFeeLimitRemaining,
    amountPayRemaining: tally.amountPayRemaining,
    customerDepositFees: tally.customerDepositFees,
    customerWireFees: tally.customerWireFees,
    totalDepositFees: tally.totalDepositFees,
    wireFeeCoveredForExchange: new Set(tally.wireFeeCoveredForExchange),
  };
}

/**
 * Account for the fees of spending a coin.
 */
function tallyFees(
  tally: CoinSelectionTally,
  wireFeesPerExchange: Record<string, AmountJson>,
  exchangeBaseUrl: string,
  feeDeposit: AmountJson,
): void {
  const currency = tally.amountPayRemaining.currency;

  if (!tally.wireFeeCoveredForExchange.has(exchangeBaseUrl)) {
    const wf =
      wireFeesPerExchange[exchangeBaseUrl] ?? Amounts.zeroOfCurrency(currency);
    // The remaining, amortized amount needs to be paid by the
    // wallet or covered by the deposit fee allowance.
    let wfRemaining = wf;
    // This is the amount forgiven via the deposit fee allowance.
    const wfDepositForgiven = Amounts.min(
      tally.amountDepositFeeLimitRemaining,
      wfRemaining,
    );
    tally.amountDepositFeeLimitRemaining = Amounts.sub(
      tally.amountDepositFeeLimitRemaining,
      wfDepositForgiven,
    ).amount;
    wfRemaining = Amounts.sub(wfRemaining, wfDepositForgiven).amount;
    tally.customerWireFees = Amounts.add(
      tally.customerWireFees,
      wfRemaining,
    ).amount;
    tally.amountPayRemaining = Amounts.add(
      tally.amountPayRemaining,
      wfRemaining,
    ).amount;
    tally.wireFeeCoveredForExchange.add(exchangeBaseUrl);
  }

  const dfForgiven = Amounts.min(
    feeDeposit,
    tally.amountDepositFeeLimitRemaining,
  );

  tally.amountDepositFeeLimitRemaining = Amounts.sub(
    tally.amountDepositFeeLimitRemaining,
    dfForgiven,
  ).amount;

  // How much does the user spend on deposit fees for this coin?
  const dfRemaining = Amounts.sub(feeDeposit, dfForgiven).amount;
  tally.customerDepositFees = Amounts.add(
    tally.customerDepositFees,
    dfRemaining,
  ).amount;
  tally.amountPayRemaining = Amounts.add(
    tally.amountPayRemaining,
    dfRemaining,
  ).amount;
  tally.totalDepositFees = Amounts.add(
    tally.totalDepositFees,
    feeDeposit,
  ).amount;
}

export type SelectPayCoinsResult =
  | {
      type: "failure";
      insufficientBalanceDetails: PaymentInsufficientBalanceDetails;
    }
  | { type: "success"; coinSel: PayCoinSelection };

async function internalSelectPayCoins(
  wex: WalletExecutionContext,
  tx: WalletDbTransaction,
  req: SelectPayCoinRequestNg,
  includePendingCoins: boolean,
): Promise<
  | { sel: SelResult; coinRes: SelectedCoin[]; tally: CoinSelectionTally }
  | undefined
> {
  let restrictWireMethod;
  if (req.depositPaytoUri) {
    const parsedPayto = Paytos.parseOrThrow(req.depositPaytoUri);
    restrictWireMethod = parsedPayto.targetType;
    if (restrictWireMethod !== req.restrictWireMethod) {
      logger.warn(`conflicting payto URI and wire method restriction`);
    }
  } else {
    restrictWireMethod = req.restrictWireMethod;
  }

  const { contractTermsAmount, depositFeeLimit } = req;
  const candidateRes = await selectPayCandidates(wex, tx, {
    currency: Amounts.currencyOf(req.contractTermsAmount),
    restrictExchanges: req.restrictExchanges,
    restrictWireMethod: req.restrictWireMethod,
    restrictScope: req.restrictScope,
    depositPaytoUri: req.depositPaytoUri,
    requiredMinimumAge: req.requiredMinimumAge,
    includePendingCoins,
  });

  const wireFeesPerExchange = candidateRes.currentWireFeePerExchange;
  const candidateDenoms = candidateRes.coinAvailability;

  const coinRes: SelectedCoin[] = [];
  const currency = contractTermsAmount.currency;

  let tally: CoinSelectionTally = {
    amountPayRemaining: contractTermsAmount,
    amountDepositFeeLimitRemaining: depositFeeLimit,
    customerDepositFees: Amounts.zeroOfCurrency(currency),
    customerWireFees: Amounts.zeroOfCurrency(currency),
    totalDepositFees: Amounts.zeroOfCurrency(currency),
    wireFeeCoveredForExchange: new Set(),
  };

  await maybeRepairCoinSelection(
    wex,
    tx,
    req.prevPayCoins ?? [],
    coinRes,
    tally,
    {
      wireFeesPerExchange: wireFeesPerExchange,
    },
  );

  let selectedDenom: SelResult | undefined;
  if (req.forcedSelection) {
    selectedDenom = selectForced(req, candidateDenoms);
  } else {
    // FIXME:  Here, we should select coins in a smarter way.
    // Instead of always spending the next-largest coin,
    // we should try to find the smallest coin that covers the
    // amount.
    selectedDenom = selectGreedy(
      {
        wireFeesPerExchange: wireFeesPerExchange,
        algorithm: wex.ws.config.testing.coinSelectionAlgorithm,
      },
      candidateDenoms,
      tally,
    );
  }

  if (!selectedDenom) {
    return undefined;
  }
  return {
    sel: selectedDenom,
    coinRes,
    tally,
  };
}

export async function selectPayCoinsInTx(
  wex: WalletExecutionContext,
  tx: WalletDbTransaction,
  req: SelectPayCoinRequestNg,
): Promise<SelectPayCoinsResult> {
  if (logger.shouldLogTrace()) {
    logger.trace(`selecting coins for ${j2s(req)}`);
  }

  if (!!wex.ws.devExperimentState.merchantDepositInsufficient) {
    return {
      type: "failure",
      insufficientBalanceDetails: await reportInsufficientBalanceDetails(
        wex,
        tx,
        {
          restrictExchanges: req.restrictExchanges,
          instructedAmount: req.contractTermsAmount,
          requiredMinimumAge: req.requiredMinimumAge,
          wireMethod: req.restrictWireMethod,
          depositPaytoUri: req.depositPaytoUri,
          restrictScope: req.restrictScope,
          depositFeeLimit: req.depositFeeLimit,
          operation: "pay",
        },
      ),
    } satisfies SelectPayCoinsResult;
  }

  const materialAvSel = await internalSelectPayCoins(wex, tx, req, false);

  if (!materialAvSel) {
    return {
      type: "failure",
      insufficientBalanceDetails: await reportInsufficientBalanceDetails(
        wex,
        tx,
        {
          restrictExchanges: req.restrictExchanges,
          instructedAmount: req.contractTermsAmount,
          requiredMinimumAge: req.requiredMinimumAge,
          wireMethod: req.restrictWireMethod,
          depositPaytoUri: req.depositPaytoUri,
          restrictScope: req.restrictScope,
          depositFeeLimit: req.depositFeeLimit,
          operation: "pay",
        },
      ),
    } satisfies SelectPayCoinsResult;
  }

  const coinSel = await assembleSelectPayCoinsSuccessResult(
    tx,
    materialAvSel.sel,
    materialAvSel.coinRes,
    materialAvSel.tally,
  );

  return {
    type: "success",
    coinSel,
  };
}

/**
 * Select coins to spend under the merchant's constraints.
 *
 * The prevPayCoins can be specified to "repair" a coin selection
 * by adding additional coins, after a broken (e.g. double-spent) coin
 * has been removed from the selection.
 */
export async function selectPayCoins(
  wex: WalletExecutionContext,
  req: SelectPayCoinRequestNg,
): Promise<SelectPayCoinsResult> {
  return await wex.runWalletDbTx(async (tx) => {
    return selectPayCoinsInTx(wex, tx, req);
  });
}

async function maybeRepairCoinSelection(
  wex: WalletExecutionContext,
  tx: WalletDbTransaction,
  prevPayCoins: PreviousPayCoins,
  coinRes: SelectedCoin[],
  tally: CoinSelectionTally,
  feeInfo: {
    wireFeesPerExchange: Record<string, AmountJson>;
  },
): Promise<void> {
  const coins = await tx.getCoinsByPubs(
    prevPayCoins.map((prev) => prev.coinPub),
  );
  const coinsByPub = new Map(coins.map((coin) => [coin.coinPub, coin]));
  const denoms = await getDenomInfos(wex, tx, coins);
  // Look at existing pay coin selection and tally up
  for (const prev of prevPayCoins) {
    const coin = coinsByPub.get(prev.coinPub);
    if (!coin) {
      continue;
    }
    const denom = denoms.get(denomRefKey(coin));
    if (!denom) {
      continue;
    }
    tallyFees(
      tally,
      feeInfo.wireFeesPerExchange,
      coin.exchangeBaseUrl,
      Amounts.parseOrThrow(denom.feeDeposit),
    );
    tally.amountPayRemaining = Amounts.sub(
      tally.amountPayRemaining,
      prev.contribution,
    ).amount;

    coinRes.push({
      exchangeBaseUrl: coin.exchangeBaseUrl,
      exchangeMasterPub: coin.exchangeMasterPub,
      denomPubHash: coin.denomPubHash,
      coinPub: prev.coinPub,
      contribution: Amounts.stringify(prev.contribution),
    });
  }
}

/**
 * Returns undefined if the success response could not be assembled,
 * as not enough coins are actually available.
 */
async function assembleSelectPayCoinsSuccessResult(
  tx: WalletDbTransaction,
  finalSel: SelResult,
  coinRes: SelectedCoin[],
  tally: CoinSelectionTally,
): Promise<PayCoinSelection> {
  for (const dph of Object.keys(finalSel)) {
    const selInfo = finalSel[dph];
    const numRequested = selInfo.contributions.length;
    const coins = await tx.getFreshCoinsByDenomAndAge(selInfo, numRequested);
    if (coins.length != numRequested) {
      throw Error(
        `coin selection failed (not available anymore, got only ${coins.length}/${numRequested})`,
      );
    }

    for (let i = 0; i < selInfo.contributions.length; i++) {
      coinRes.push({
        denomPubHash: coins[i].denomPubHash,
        coinPub: coins[i].coinPub,
        contribution: Amounts.stringify(selInfo.contributions[i]),
        exchangeBaseUrl: coins[i].exchangeBaseUrl,
        exchangeMasterPub: coins[i].exchangeMasterPub,
      });
    }
  }

  return {
    coins: coinRes,
    customerDepositFees: Amounts.stringify(tally.customerDepositFees),
    customerWireFees: Amounts.stringify(tally.customerWireFees),
    totalDepositFees: Amounts.stringify(tally.totalDepositFees),
  };
}

interface ReportInsufficientBalanceRequest {
  instructedAmount: AmountJson;
  requiredMinimumAge: number | undefined;
  restrictExchanges: ExchangeRestrictionSpec | undefined;
  wireMethod: string | undefined;
  depositPaytoUri: string | undefined;
  restrictScope?: ScopeInfo;
  exchangeBaseUrl?: string;
  depositFeeLimit?: AmountJson;
  feesCoveredByCounterparty?: boolean;
  operation: "pay" | "peer";
}

function getHint(
  req: ReportInsufficientBalanceRequest,
  exchDet: PaymentBalanceDetails,
): InsufficientBalanceHint | undefined {
  if (Amounts.cmp(exchDet.balanceAvailable, req.instructedAmount) >= 0) {
    // It looks to the user like funds at this exchange should be sufficient.
    // We now need to explain why that's not the case.

    const isMerchant = !!req.wireMethod;

    if (Amounts.cmp(exchDet.balanceMaterial, req.instructedAmount) < 0) {
      return InsufficientBalanceHint.WalletBalanceMaterialInsufficient;
    } else if (
      Amounts.cmp(exchDet.balanceAgeAcceptable, req.instructedAmount) < 0
    ) {
      return InsufficientBalanceHint.AgeRestricted;
    } else if (
      isMerchant &&
      Amounts.cmp(exchDet.balanceReceiverAcceptable, req.instructedAmount) < 0
    ) {
      return InsufficientBalanceHint.MerchantAcceptInsufficient;
    } else if (
      isMerchant &&
      Amounts.cmp(exchDet.balanceReceiverDepositable, req.instructedAmount) < 0
    ) {
      return InsufficientBalanceHint.MerchantDepositInsufficient;
    } else if (
      isMerchant &&
      Amounts.cmp(
        exchDet.maxMerchantEffectiveDepositAmount,
        req.instructedAmount,
      ) < 0
    ) {
      return InsufficientBalanceHint.FeesNotCovered;
    }
    // We don't exactly know why the balance is insufficient!
    return undefined;
  }
  // Simply not enough funds.
  return InsufficientBalanceHint.WalletBalanceAvailableInsufficient;
}

function appendReason(
  reasons: CoinSelectionFailureReason[],
  reason: CoinSelectionFailureReason,
): void {
  if (!reasons.some((x) => x.type === reason.type)) {
    reasons.push(reason);
  }
}

function addFeeAllowance(
  baseAmount: AmountJson,
  upperBound: AmountJson,
  allowance: AmountJson,
): AmountJson {
  return Amounts.min(upperBound, Amounts.add(baseAmount, allowance).amount);
}

interface MaximumPayableComputation {
  operation: "pay" | "peer";
  combinedBaseMaximum: AmountJson;
  combinedFeeFreeMaximum: AmountJson;
  largestExchangeMaximum: AmountJson;
  allowance: AmountJson;
}

function computeMaximumPayableAmount(
  args: MaximumPayableComputation,
): AmountJson {
  if (args.operation === "peer") {
    return args.largestExchangeMaximum;
  }
  return addFeeAllowance(
    args.combinedBaseMaximum,
    args.combinedFeeFreeMaximum,
    args.allowance,
  );
}

function makeBalanceSnapshot(
  details: Pick<PaymentBalanceDetails, "balanceAvailable" | "balanceMaterial">,
): CoinSelectionBalanceSnapshot {
  checkLogicInvariant(
    Amounts.cmp(details.balanceAvailable, details.balanceMaterial) >= 0,
    "available balance must include the material balance",
  );
  return {
    material: Amounts.stringify(details.balanceMaterial),
    pendingRefresh: Amounts.stringify(
      Amounts.sub(details.balanceAvailable, details.balanceMaterial).amount,
    ),
    available: Amounts.stringify(details.balanceAvailable),
  };
}

function getBalanceAvailabilityReason(
  details: Pick<PaymentBalanceDetails, "balanceAvailable" | "balanceMaterial">,
  instructedAmount: AmountJson,
): CoinSelectionFailureReason | undefined {
  if (Amounts.cmp(details.balanceAvailable, instructedAmount) < 0) {
    return {
      type: CoinSelectionFailureReasonType.AvailableBalanceInsufficient,
      amountAvailable: Amounts.stringify(details.balanceAvailable),
    };
  }
  if (Amounts.cmp(details.balanceMaterial, instructedAmount) < 0) {
    return {
      type: CoinSelectionFailureReasonType.PendingRefresh,
      amountPendingRefresh: Amounts.stringify(
        Amounts.sub(details.balanceAvailable, details.balanceMaterial).amount,
      ),
    };
  }
  return undefined;
}

interface MaximumFailureClassification {
  balanceFragmented: boolean;
  feesNotCovered: boolean;
}

function classifyMaximumFailure(args: {
  operation: "pay" | "peer";
  instructedAmount: AmountJson;
  maximumPayable: AmountJson;
  combinedMaximumPayable: AmountJson;
  feeFreeMaximum: AmountJson;
}): MaximumFailureClassification {
  const balanceFragmented =
    args.operation === "peer" &&
    Amounts.cmp(args.combinedMaximumPayable, args.instructedAmount) >= 0 &&
    Amounts.cmp(args.maximumPayable, args.instructedAmount) < 0;
  return {
    balanceFragmented,
    feesNotCovered:
      !balanceFragmented &&
      Amounts.cmp(args.maximumPayable, args.instructedAmount) < 0 &&
      Amounts.cmp(args.feeFreeMaximum, args.instructedAmount) >= 0,
  };
}

