async function getSupersededCoinBalances(
  wex: WalletExecutionContext,
  tx: WalletDbTransaction,
  currency: string,
  snapshot: PaymentBalanceSnapshot,
): Promise<Map<string, AmountJson>> {
  const amounts = new Map<string, AmountJson>();
  const exchangeMasterPubs = new Map<string, string | undefined>();
  const availabilities = snapshot.availabilities;
  for (const availability of availabilities) {
    if (
      availability.currency !== currency ||
      availability.freshCoinCount === 0
    ) {
      continue;
    }
    let exchangeMasterPub = exchangeMasterPubs.get(
      availability.exchangeBaseUrl,
    );
    if (!exchangeMasterPubs.has(availability.exchangeBaseUrl)) {
      exchangeMasterPub = (
        await snapshot.getExchangeDetails(tx, availability.exchangeBaseUrl)
      )?.masterPublicKey;
      exchangeMasterPubs.set(availability.exchangeBaseUrl, exchangeMasterPub);
    }
    const denom = snapshot.getDenom(availability);
    if (
      !denom ||
      !exchangeMasterPub ||
      denom.exchangeMasterPub === exchangeMasterPub
    ) {
      continue;
    }
    const current =
      amounts.get(availability.exchangeBaseUrl) ??
      Amounts.zeroOfCurrency(currency);
    amounts.set(
      availability.exchangeBaseUrl,
      Amounts.add(
        current,
        Amounts.mult(availability.value, availability.freshCoinCount).amount,
      ).amount,
    );
  }
  return amounts;
}

export async function reportInsufficientBalanceDetails(
  wex: WalletExecutionContext,
  tx: WalletDbTransaction,
  req: ReportInsufficientBalanceRequest,
): Promise<PaymentInsufficientBalanceDetails> {
  const currency = Amounts.currencyOf(req.instructedAmount);
  const zero = Amounts.zeroOfCurrency(currency);
  const effectiveScope =
    req.restrictScope ??
    (req.exchangeBaseUrl
      ? {
          type: ScopeType.Exchange as const,
          currency,
          url: req.exchangeBaseUrl,
        }
      : undefined);
  const balanceSnapshot = await PaymentBalanceSnapshot.load(wex, tx);
  const details = await getPaymentBalanceDetailsInTx(
    wex,
    tx,
    {
      restrictSenderScope: effectiveScope,
      restrictReceiverExchanges: req.restrictExchanges,
      restrictWireMethods: req.wireMethod ? [req.wireMethod] : undefined,
      currency,
      minAge: req.requiredMinimumAge ?? 0,
      depositPaytoUri: req.depositPaytoUri,
    },
    balanceSnapshot,
  );
  const perExchange: PaymentInsufficientBalanceDetails["perExchange"] = {};
  const diagnosticExchanges: PaymentInsufficientBalanceStructuredDetails["exchanges"] =
    {};
  const exchanges = await tx.getExchanges();
  const supersededCoinBalances = await getSupersededCoinBalances(
    wex,
    tx,
    currency,
    balanceSnapshot,
  );
  let combinedBaseMaximum = zero;
  let combinedExchangeMaximum = zero;
  let largestExchangeMaximum = zero;
  let combinedFeeFreeMaximum = zero;
  let largestFeeFreeMaximum = zero;
  let anySameCurrencyExchange = false;
  let allUsablePeerExchangesMissingGlobalFees = req.operation === "peer";
  let sawMasterPubMismatch = false;

  for (const exch of exchanges) {
    if (!exch.detailsPointer) {
      continue;
    }
    let missingGlobalFees = false;
    const exchWire = await balanceSnapshot.getExchangeDetails(tx, exch.baseUrl);
    if (!exchWire) {
      // No wire details about the exchange known, skip!
      continue;
    }
    const globalFees = getGlobalFees(exchWire);
    if (!globalFees) {
      missingGlobalFees = true;
    }
    if (exchWire.currency !== Amounts.currencyOf(req.instructedAmount)) {
      // Do not report anything for an exchange with a different currency.
      continue;
    }
    anySameCurrencyExchange = true;
    const exchDet = await getPaymentBalanceDetailsInTx(
      wex,
      tx,
      {
        restrictSenderScope: {
          type: ScopeType.Exchange,
          currency,
          url: exch.baseUrl,
        },
        restrictReceiverExchanges: req.restrictExchanges,
        restrictWireMethods: req.wireMethod ? [req.wireMethod] : undefined,
        currency: Amounts.currencyOf(req.instructedAmount),
        minAge: req.requiredMinimumAge ?? 0,
        depositPaytoUri: req.depositPaytoUri,
      },
      balanceSnapshot,
    );

    const reasons: CoinSelectionFailureReason[] = [];
    const inRequestedScope =
      (!req.exchangeBaseUrl || req.exchangeBaseUrl === exch.baseUrl) &&
      (!req.restrictScope ||
        (await checkExchangeInScopeTx(
          tx,
          exch.baseUrl,
          req.restrictScope,
          exchWire,
        )));
    if (!inRequestedScope && effectiveScope) {
      appendReason(reasons, {
        type: CoinSelectionFailureReasonType.ScopeRestricted,
        scopeInfo: effectiveScope,
      });
    }

    const supersededBalance = supersededCoinBalances.get(exch.baseUrl) ?? zero;
    if (Amounts.isNonZero(supersededBalance)) {
      appendReason(reasons, {
        type: CoinSelectionFailureReasonType.SupersededExchangeMasterPub,
        amountAffected: Amounts.stringify(supersededBalance),
      });
    }

    if (
      (req.requiredMinimumAge ?? 0) > 0 &&
      Amounts.cmp(exchDet.balanceAgeAcceptable, exchDet.balanceMaterial) < 0
    ) {
      appendReason(reasons, {
        type: CoinSelectionFailureReasonType.MinimumAge,
        requiredMinimumAge: req.requiredMinimumAge ?? 0,
        amountAgeAcceptable: Amounts.stringify(exchDet.balanceAgeAcceptable),
      });
    }

    const acceptance = checkExchangeAccepted(exchWire, req.restrictExchanges);
    if (!acceptance.accepted) {
      if (acceptance.masterPubMismatch) {
        if (Amounts.isNonZero(exchDet.balanceMaterial)) {
          sawMasterPubMismatch = true;
        }
        appendReason(reasons, {
          type: CoinSelectionFailureReasonType.ReceiverExchangeMasterPubMismatch,
          walletMasterPub: exchWire.masterPublicKey,
          receiverMasterPubs: acceptance.receiverMasterPubs,
        });
      } else {
        appendReason(reasons, {
          type: CoinSelectionFailureReasonType.ReceiverNotAccepted,
        });
      }
    }

    let wireMatch: MatchingWireResult | undefined;
    if (req.wireMethod) {
      wireMatch = findMatchingWire(
        req.wireMethod,
        req.depositPaytoUri,
        exchWire,
      );
      switch (wireMatch.status) {
        case "match":
          break;
        case "account-restricted":
          appendReason(reasons, {
            type: CoinSelectionFailureReasonType.DepositAccountRestricted,
            wireMethod: req.wireMethod,
            accountRestrictions: wireMatch.accountRestrictions,
          });
          break;
        case "wire-method-unsupported":
          appendReason(reasons, {
            type: CoinSelectionFailureReasonType.WireMethodUnsupported,
            wireMethod: req.wireMethod,
          });
          break;
        case "wire-fee-unavailable":
          appendReason(reasons, {
            type: CoinSelectionFailureReasonType.WireFeeUnavailable,
            wireMethod: req.wireMethod,
          });
          break;
        default:
          assertUnreachable(wireMatch);
      }
    }

    if (req.operation === "peer" && missingGlobalFees) {
      appendReason(reasons, {
        type: CoinSelectionFailureReasonType.ExchangeGlobalFeesUnavailable,
      });
    } else if (req.operation === "peer" && inRequestedScope) {
      allUsablePeerExchangesMissingGlobalFees = false;
    }

    let baseMaximum = exchDet.maxMerchantEffectiveDepositAmount;
    if (wireMatch?.status === "match") {
      baseMaximum =
        Amounts.cmp(baseMaximum, wireMatch.wireFee) >= 0
          ? Amounts.sub(baseMaximum, wireMatch.wireFee).amount
          : zero;
    }
    const exchangeEligible =
      inRequestedScope &&
      acceptance.accepted &&
      (!wireMatch || wireMatch.status === "match") &&
      !(req.operation === "peer" && missingGlobalFees);
    if (!exchangeEligible) {
      baseMaximum = zero;
    }

    const feeFreeMaximum = exchangeEligible
      ? exchDet.balanceAgeAcceptable
      : zero;
    combinedFeeFreeMaximum = Amounts.add(
      combinedFeeFreeMaximum,
      feeFreeMaximum,
    ).amount;
    largestFeeFreeMaximum = Amounts.max(largestFeeFreeMaximum, feeFreeMaximum);

    const allowance =
      req.depositFeeLimit ??
      (req.feesCoveredByCounterparty ? req.instructedAmount : zero);
    const maximumPayable = exchangeEligible
      ? addFeeAllowance(baseMaximum, exchDet.balanceAgeAcceptable, allowance)
      : zero;
    combinedBaseMaximum = Amounts.add(combinedBaseMaximum, baseMaximum).amount;
    combinedExchangeMaximum = Amounts.add(
      combinedExchangeMaximum,
      maximumPayable,
    ).amount;
    largestExchangeMaximum = Amounts.max(
      largestExchangeMaximum,
      maximumPayable,
    );

    if (
      exchangeEligible &&
      Amounts.cmp(exchDet.balanceAgeAcceptable, req.instructedAmount) >= 0 &&
      Amounts.cmp(maximumPayable, req.instructedAmount) < 0
    ) {
      appendReason(reasons, {
        type: CoinSelectionFailureReasonType.FeesNotCovered,
        maximumPayableAmount: Amounts.stringify(maximumPayable),
      });
    }

    diagnosticExchanges[exch.baseUrl] = {
      balance: makeBalanceSnapshot(exchDet),
      maximumPayableAmount: Amounts.stringify(maximumPayable),
      reasons,
    };

    perExchange[exch.baseUrl] = {
      balanceAvailable: Amounts.stringify(exchDet.balanceAvailable),
      balanceMaterial: Amounts.stringify(exchDet.balanceMaterial),
      balanceExchangeDepositable: Amounts.stringify(
        exchDet.balanceExchangeDepositable,
      ),
      balanceAgeAcceptable: Amounts.stringify(exchDet.balanceAgeAcceptable),
      balanceReceiverAcceptable: Amounts.stringify(
        exchDet.balanceReceiverAcceptable,
      ),
      balanceReceiverExchangeUrlAcceptable: Amounts.stringify(
        exchDet.balanceReceiverExchangeUrlAcceptable,
      ),
      balanceReceiverExchangePubAcceptable: Amounts.stringify(
        exchDet.balanceReceiverExchangePubAcceptable,
      ),
      balanceReceiverAuditorUrlAcceptable: Amounts.stringify(
        exchDet.balanceReceiverAuditorUrlAcceptable,
      ),
      balanceReceiverDepositable: Amounts.stringify(
        exchDet.balanceReceiverDepositable,
      ),
      maxEffectiveSpendAmount: Amounts.stringify(
        exchDet.maxMerchantEffectiveDepositAmount,
      ),
      missingGlobalFees,
      // Balance at an exchange the merchant accepts by URL but whose master
      // public key it does not accept, i.e. the key the merchant configured
      // differs from the one the coins were issued under.  The reverse case
      // is a URL the merchant does not list, not a key mismatch.
      exchangeMasterPubMismatch: acceptance.masterPubMismatch,
      causeHint: !!wex.ws.devExperimentState.merchantDepositInsufficient
        ? InsufficientBalanceHint.MerchantDepositInsufficient
        : req.operation === "peer" && missingGlobalFees
          ? InsufficientBalanceHint.ExchangeMissingGlobalFees
          : getHint(req, exchDet),
    };
  }

  const globalReasons: CoinSelectionFailureReason[] = [];
  const availabilityReason = getBalanceAvailabilityReason(
    details,
    req.instructedAmount,
  );
  if (availabilityReason) {
    appendReason(globalReasons, availabilityReason);
  }
  if (
    (req.requiredMinimumAge ?? 0) > 0 &&
    Amounts.cmp(details.balanceMaterial, req.instructedAmount) >= 0 &&
    Amounts.cmp(details.balanceAgeAcceptable, req.instructedAmount) < 0
  ) {
    appendReason(globalReasons, {
      type: CoinSelectionFailureReasonType.MinimumAge,
      requiredMinimumAge: req.requiredMinimumAge ?? 0,
      amountAgeAcceptable: Amounts.stringify(details.balanceAgeAcceptable),
    });
  }
  if (
    req.restrictExchanges &&
    Amounts.cmp(details.balanceAgeAcceptable, req.instructedAmount) >= 0 &&
    Amounts.cmp(details.balanceReceiverAcceptable, req.instructedAmount) < 0
  ) {
    appendReason(globalReasons, {
      type: CoinSelectionFailureReasonType.ReceiverNotAccepted,
    });
  }
  if (effectiveScope && Amounts.isZero(details.balanceMaterial)) {
    appendReason(globalReasons, {
      type: CoinSelectionFailureReasonType.ScopeRestricted,
      scopeInfo: effectiveScope,
    });
  }
  if (
    req.operation === "peer" &&
    anySameCurrencyExchange &&
    allUsablePeerExchangesMissingGlobalFees
  ) {
    appendReason(globalReasons, {
      type: CoinSelectionFailureReasonType.ExchangeGlobalFeesUnavailable,
    });
  }

  const allowance =
    req.depositFeeLimit ??
    (req.feesCoveredByCounterparty ? req.instructedAmount : zero);
  const maximumPayable = computeMaximumPayableAmount({
    operation: req.operation,
    combinedBaseMaximum,
    combinedFeeFreeMaximum,
    largestExchangeMaximum,
    allowance,
  });
  const feeFreeMaximum =
    req.operation === "peer" ? largestFeeFreeMaximum : combinedFeeFreeMaximum;
  const maximumFailure = classifyMaximumFailure({
    operation: req.operation,
    instructedAmount: req.instructedAmount,
    maximumPayable,
    combinedMaximumPayable: combinedExchangeMaximum,
    feeFreeMaximum,
  });
  if (maximumFailure.balanceFragmented) {
    appendReason(globalReasons, {
      type: CoinSelectionFailureReasonType.BalanceFragmented,
      combinedMaximumPayableAmount: Amounts.stringify(combinedExchangeMaximum),
    });
  }
  if (maximumFailure.feesNotCovered) {
    appendReason(globalReasons, {
      type: CoinSelectionFailureReasonType.FeesNotCovered,
      maximumPayableAmount: Amounts.stringify(maximumPayable),
    });
  }
  for (const type of [
    CoinSelectionFailureReasonType.ReceiverExchangeMasterPubMismatch,
    CoinSelectionFailureReasonType.WireMethodUnsupported,
    CoinSelectionFailureReasonType.WireFeeUnavailable,
    CoinSelectionFailureReasonType.DepositAccountRestricted,
    CoinSelectionFailureReasonType.ExchangeGlobalFeesUnavailable,
    CoinSelectionFailureReasonType.SupersededExchangeMasterPub,
  ]) {
    const exchangeReason = Object.values(diagnosticExchanges)
      .flatMap((x) =>
        x.reasons.filter(
          (reason) =>
            Amounts.isNonZero(x.balance.material) ||
            reason.type ===
              CoinSelectionFailureReasonType.SupersededExchangeMasterPub,
        ),
      )
      .find((x) => x.type === type);
    if (exchangeReason) {
      appendReason(globalReasons, exchangeReason);
    }
  }
  if (globalReasons.length === 0) {
    appendReason(globalReasons, {
      type: CoinSelectionFailureReasonType.SelectionFailed,
    });
  }

  const structuredDetails: PaymentInsufficientBalanceStructuredDetails = {
    balance: makeBalanceSnapshot(details),
    maximumPayableAmount: Amounts.stringify(maximumPayable),
    reasons: globalReasons,
    exchanges: diagnosticExchanges,
  };

  let causeHint = getHint(req, details);
  if (
    req.operation === "peer" &&
    globalReasons.some(
      (x) =>
        x.type === CoinSelectionFailureReasonType.ExchangeGlobalFeesUnavailable,
    )
  ) {
    causeHint = InsufficientBalanceHint.ExchangeMissingGlobalFees;
  } else if (sawMasterPubMismatch) {
    causeHint = InsufficientBalanceHint.MerchantAcceptInsufficient;
  }

  return {
    amountRequested: Amounts.stringify(req.instructedAmount),
    wireMethod: req.wireMethod,
    causeHint: !!wex.ws.devExperimentState.merchantDepositInsufficient
      ? InsufficientBalanceHint.MerchantDepositInsufficient
      : causeHint,
    ...structuredDetails,
    balanceAgeAcceptable: Amounts.stringify(details.balanceAgeAcceptable),
    balanceAvailable: Amounts.stringify(details.balanceAvailable),
    balanceMaterial: Amounts.stringify(details.balanceMaterial),
    balanceReceiverAcceptable: Amounts.stringify(
      details.balanceReceiverAcceptable,
    ),
    balanceReceiverExchangeUrlAcceptable: Amounts.stringify(
      details.balanceReceiverExchangeUrlAcceptable,
    ),
    balanceReceiverExchangePubAcceptable: Amounts.stringify(
      details.balanceReceiverExchangePubAcceptable,
    ),
    balanceReceiverAuditorUrlAcceptable: Amounts.stringify(
      details.balanceReceiverAuditorUrlAcceptable,
    ),
    balanceExchangeDepositable: Amounts.stringify(
      details.balanceExchangeDepositable,
    ),
    balanceReceiverDepositable: Amounts.stringify(
      details.balanceReceiverDepositable,
    ),
    maxEffectiveSpendAmount: Amounts.stringify(
      details.maxMerchantEffectiveDepositAmount,
    ),
    perExchange,
  };
}

function makeAvailabilityKey(
  exchangeBaseUrl: string,
  denomPubHash: string,
  maxAge: number,
): string {
  return `${denomPubHash};${maxAge};${exchangeBaseUrl}`;
}

/**
 * Selection result.
 */
interface SelResult {
  /**
   * Map from an availability key
   * to an array of contributions.
   */
  [avKey: string]: {
    exchangeBaseUrl: string;
    exchangeMasterPub: string;
    denomPubHash: string;
    maxAge: number;
    contributions: AmountJson[];
  };
}

export function testing_selectGreedy(
  ...args: Parameters<typeof selectGreedy>
): ReturnType<typeof selectGreedy> {
  return selectGreedy(...args);
}

export interface SelectGreedyRequest {
  wireFeesPerExchange: Record<string, AmountJson>;

  /**
   * Algorithm to use.  Defaults to "default".
   */
  algorithm?: CoinSelectionAlgorithm;
}

function applyContributions(
  selectedDenom: SelResult,
  contributions: AmountJson[],
  denom: AvailableCoinsOfDenom,
): void {
  if (contributions.length) {
    const avKey = makeAvailabilityKey(
      denom.exchangeBaseUrl,
      denom.denomPubHash,
      denom.maxAge,
    );
    let sd = selectedDenom[avKey];
    if (!sd) {
      sd = {
        contributions: [],
        denomPubHash: denom.denomPubHash,
        exchangeBaseUrl: denom.exchangeBaseUrl,
        exchangeMasterPub: denom.exchangeMasterPub,
        maxAge: denom.maxAge,
      };
    }
    sd.contributions.push(...contributions);
    selectedDenom[avKey] = sd;
  }
}

function selectGreedy(
  req: SelectGreedyRequest,
  candidateDenoms: AvailableCoinsOfDenom[],
  tally: CoinSelectionTally,
): SelResult | undefined {
  const algorithm = req.algorithm ?? "default";
  switch (algorithm) {
    case "default":
      return selectGreedyDefault(req, candidateDenoms, tally);
    case "legacy-2024":
      return selectGreedyLegacy2024(req, candidateDenoms, tally);
    default:
      assertUnreachable(algorithm);
  }
}

/**
 * Coin selection as the wallet did it in 2024.
 *
 * Kept around so that test suites which pin the coin selections it produces
 * (the exchange's auditor tests, most notably) keep seeing the same coins.
 * Two later changes are deliberately *not* applied here: the exact-fit
 * shortcut with smallest-coin-first fallback, and the correction that stops a
 * coin from overspending while the merchant's deposit fee allowance still has
 * room.  The latter is a genuine bug, so this algorithm is only for
 * reproducing old results, never for real spending.
 *
 * The only intentional deviation from the 2024 source is that it no longer
 * records the last deposit fee in the tally: that field fed the insufficient
 * balance hint, which has since been rewritten, and never influenced which
 * coins were picked.
 */
function selectGreedyLegacy2024(
  req: SelectGreedyRequest,
  candidateDenoms: AvailableCoinsOfDenom[],
  tally: CoinSelectionTally,
): SelResult | undefined {
  const selectedDenom: SelResult = {};
  // Candidates are sorted by descending value, so this always spends the
  // largest coin that is still available.
  for (const denom of candidateDenoms) {
    const contributions: AmountJson[] = [];

    // Don't use this coin if depositing it is more expensive than
    // the amount it would give the merchant.
    if (Amounts.cmp(denom.feeDeposit, denom.value) > 0) {
      continue;
    }

    for (
      let i = 0;
      i < denom.numAvailable && Amounts.isNonZero(tally.amountPayRemaining);
      i++
    ) {
      tallyFees(
        tally,
        req.wireFeesPerExchange,
        denom.exchangeBaseUrl,
        Amounts.parseOrThrow(denom.feeDeposit),
      );

      const coinSpend = Amounts.max(
        Amounts.min(tally.amountPayRemaining, denom.value),
        denom.feeDeposit,
      );

      tally.amountPayRemaining = Amounts.sub(
        tally.amountPayRemaining,
        coinSpend,
      ).amount;

      contributions.push(coinSpend);
    }

    applyContributions(selectedDenom, contributions, denom);
  }
  return Amounts.isZero(tally.amountPayRemaining) ? selectedDenom : undefined;
}

function selectGreedyDefault(
  req: SelectGreedyRequest,
  candidateDenoms: AvailableCoinsOfDenom[],
  tally: CoinSelectionTally,
): SelResult | undefined {
  const baseTally = cloneTally(tally);
  const currency = Amounts.currencyOf(tally.amountPayRemaining);
  const candidates = candidateDenoms
    .filter((denom) => {
      const meta = getCandidateSelectionMeta(denom);
      return denom.numAvailable > 0 && meta.depositFee <= meta.value;
    })
    .sort(compareCandidateDenoms);
  const selection: MutableCoinSelection = {
    coins: [],
    selectedCountByDenom: new Map(),
    totals: {
      value: 0n,
      depositFees: 0n,
      wireFees: 0n,
      exchangeCoinCount: new Map(),
    },
  };

  // DD91 pass 1: add the smallest, earliest-expiring coins until the
  // selection covers the payment and the fees not covered by the merchant.
  addCoins: for (const denom of candidates) {
    for (let i = 0; i < denom.numAvailable; i++) {
      addSelectedCoin(selection, denom, req, baseTally);
      if (selectionIsSufficient(selection.totals, baseTally)) {
        break addCoins;
      }
    }
  }
  if (!selectionIsSufficient(selection.totals, baseTally)) {
    return undefined;
  }

  pruneSelection(selection, req, baseTally);

  reduceSelectionFees(selection, candidates, req, baseTally);
  // Lower fees can leave another coin redundant even though replacements
  // preserve the total denomination value.
  pruneSelection(selection, req, baseTally);

  const finalCoins = selection.coins
    .filter((coin) => coin.selected)
    .sort((a, b) => compareCandidateDenoms(a.denom, b.denom));
  checkLogicInvariant(
    finalCoins.length > 0 || Amounts.isZero(tally.amountPayRemaining),
  );

  // Account for all fees before assigning the change to the smallest coin.
  // The selection is irreducible after pass 2, so the excess is smaller than
  // that coin's value.
  for (const coin of finalCoins) {
    tallyFees(
      tally,
      req.wireFeesPerExchange,
      coin.denom.exchangeBaseUrl,
      Amounts.parseOrThrow(coin.denom.feeDeposit),
    );
  }
  const excess = amountFromUnits(
    currency,
    selection.totals.value - amountToUnits(tally.amountPayRemaining),
  );
  if (finalCoins.length > 0) {
    checkLogicInvariant(Amounts.cmp(excess, finalCoins[0].denom.value) < 0);
  }
  const selectedDenom: SelResult = {};
  for (let i = 0; i < finalCoins.length; i++) {
    const denom = finalCoins[i].denom;
    const contribution =
      i === 0
        ? Amounts.sub(denom.value, excess).amount
        : Amounts.parseOrThrow(denom.value);
    applyContributions(selectedDenom, [contribution], denom);
    tally.amountPayRemaining = Amounts.sub(
      tally.amountPayRemaining,
      contribution,
    ).amount;
  }
  checkLogicInvariant(Amounts.isZero(tally.amountPayRemaining));
  return selectedDenom;
}

interface SelectedCandidateCoin {
  denom: AvailableCoinsOfDenom;
  selected: boolean;
}

interface SelectionTotals {
  value: bigint;
  depositFees: bigint;
  wireFees: bigint;
  exchangeCoinCount: Map<string, number>;
}

interface MutableCoinSelection {
  coins: SelectedCandidateCoin[];
  selectedCountByDenom: Map<AvailableCoinsOfDenom, number>;
  totals: SelectionTotals;
}

interface CandidateSelectionMeta {
  value: bigint;
  depositFee: bigint;
  expireDeposit: AbsoluteTime;
}

const candidateSelectionMeta = new WeakMap<
  AvailableCoinsOfDenom,
  CandidateSelectionMeta
>();

function getCandidateSelectionMeta(
  denom: AvailableCoinsOfDenom,
): CandidateSelectionMeta {
  let meta = candidateSelectionMeta.get(denom);
  if (!meta) {
    meta = {
      value: amountToUnits(denom.value),
      depositFee: amountToUnits(denom.feeDeposit),
      expireDeposit: AbsoluteTime.fromProtocolTimestamp(
        denom.stampExpireDeposit,
      ),
    };
    candidateSelectionMeta.set(denom, meta);
  }
  return meta;
}

function compareBigInt(left: bigint, right: bigint): number {
  return left < right ? -1 : left > right ? 1 : 0;
}

/**
 * DD91 pass 2: consider removals from largest to smallest.  Walking the
 * ascending selection backwards also removes later-expiring coins first
 * within one denomination.
 */
function pruneSelection(
  selection: MutableCoinSelection,
  req: SelectGreedyRequest,
  baseTally: CoinSelectionTally,
): void {
  for (let i = selection.coins.length - 1; i >= 0; i--) {
    const coin = selection.coins[i];
    if (!coin.selected) {
      continue;
    }
    removeSelectedCoin(selection, coin, req, baseTally);
    if (!selectionIsSufficient(selection.totals, baseTally)) {
      restoreSelectedCoin(selection, coin, req, baseTally);
    }
  }
}

function compareCandidateDenoms(
  left: AvailableCoinsOfDenom,
  right: AvailableCoinsOfDenom,
): number {
  const leftMeta = getCandidateSelectionMeta(left);
  const rightMeta = getCandidateSelectionMeta(right);
  return (
    compareBigInt(leftMeta.value, rightMeta.value) ||
    AbsoluteTime.cmp(leftMeta.expireDeposit, rightMeta.expireDeposit) ||
    compareBigInt(leftMeta.depositFee, rightMeta.depositFee) ||
    strcmp(left.exchangeBaseUrl, right.exchangeBaseUrl) ||
    strcmp(left.denomPubHash, right.denomPubHash) ||
    left.maxAge - right.maxAge
  );
}

function selectionCustomerFees(
  totals: SelectionTotals,
  baseTally: CoinSelectionTally,
): bigint {
  const fees = totals.depositFees + totals.wireFees;
  const allowance = amountToUnits(baseTally.amountDepositFeeLimitRemaining);
  return fees > allowance ? fees - allowance : 0n;
}

function selectionIsSufficient(
  totals: SelectionTotals,
  baseTally: CoinSelectionTally,
): boolean {
  const required =
    amountToUnits(baseTally.amountPayRemaining) +
    selectionCustomerFees(totals, baseTally);
  return totals.value >= required;
}

function addSelectionTotals(
  totals: SelectionTotals,
  denom: AvailableCoinsOfDenom,
  req: SelectGreedyRequest,
  baseTally: CoinSelectionTally,
): void {
  const meta = getCandidateSelectionMeta(denom);
  totals.value += meta.value;
  totals.depositFees += meta.depositFee;
  const oldCount = totals.exchangeCoinCount.get(denom.exchangeBaseUrl) ?? 0;
  if (
    oldCount === 0 &&
    !baseTally.wireFeeCoveredForExchange.has(denom.exchangeBaseUrl)
  ) {
    const wireFee = req.wireFeesPerExchange[denom.exchangeBaseUrl];
    totals.wireFees += wireFee ? amountToUnits(wireFee) : 0n;
  }
  totals.exchangeCoinCount.set(denom.exchangeBaseUrl, oldCount + 1);
}

function removeSelectionTotals(
  totals: SelectionTotals,
  denom: AvailableCoinsOfDenom,
  req: SelectGreedyRequest,
  baseTally: CoinSelectionTally,
): void {
  const meta = getCandidateSelectionMeta(denom);
  totals.value -= meta.value;
  totals.depositFees -= meta.depositFee;
  const oldCount = totals.exchangeCoinCount.get(denom.exchangeBaseUrl) ?? 0;
  checkLogicInvariant(oldCount > 0);
  if (oldCount === 1) {
    totals.exchangeCoinCount.delete(denom.exchangeBaseUrl);
    if (!baseTally.wireFeeCoveredForExchange.has(denom.exchangeBaseUrl)) {
      const wireFee = req.wireFeesPerExchange[denom.exchangeBaseUrl];
      totals.wireFees -= wireFee ? amountToUnits(wireFee) : 0n;
    }
  } else {
    totals.exchangeCoinCount.set(denom.exchangeBaseUrl, oldCount - 1);
  }
}

function addSelectedCoin(
  selection: MutableCoinSelection,
  denom: AvailableCoinsOfDenom,
  req: SelectGreedyRequest,
  baseTally: CoinSelectionTally,
): SelectedCandidateCoin {
  const coin = { denom, selected: false };
  selection.coins.push(coin);
  restoreSelectedCoin(selection, coin, req, baseTally);
  return coin;
}

function restoreSelectedCoin(
  selection: MutableCoinSelection,
  coin: SelectedCandidateCoin,
  req: SelectGreedyRequest,
  baseTally: CoinSelectionTally,
): void {
  checkLogicInvariant(!coin.selected);
  coin.selected = true;
  selection.selectedCountByDenom.set(
    coin.denom,
    (selection.selectedCountByDenom.get(coin.denom) ?? 0) + 1,
  );
  addSelectionTotals(selection.totals, coin.denom, req, baseTally);
}

function removeSelectedCoin(
  selection: MutableCoinSelection,
  coin: SelectedCandidateCoin,
  req: SelectGreedyRequest,
  baseTally: CoinSelectionTally,
): void {
  checkLogicInvariant(coin.selected);
  coin.selected = false;
  const oldCount = selection.selectedCountByDenom.get(coin.denom) ?? 0;
  checkLogicInvariant(oldCount > 0);
  if (oldCount === 1) {
    selection.selectedCountByDenom.delete(coin.denom);
  } else {
    selection.selectedCountByDenom.set(coin.denom, oldCount - 1);
  }
  removeSelectionTotals(selection.totals, coin.denom, req, baseTally);
}

function denominationFactor(
  larger: AvailableCoinsOfDenom,
  smaller: AvailableCoinsOfDenom,
  exact: boolean,
): number | undefined {
  const largerUnits = getCandidateSelectionMeta(larger).value;
  const smallerUnits = getCandidateSelectionMeta(smaller).value;
  if (smallerUnits === 0n) {
    return undefined;
  }
  const quotient = largerUnits / smallerUnits;
  const hasRemainder = largerUnits % smallerUnits !== 0n;
  const factor = quotient + (hasRemainder ? 1n : 0n);
  if ((exact && hasRemainder) || factor > BigInt(Number.MAX_SAFE_INTEGER)) {
    return undefined;
  }
  return Number(factor);
}

const amountFractionalBaseBigInt = 100_000_000n;

function amountToUnits(amount: AmountJson | string): bigint {
  const parsed = Amounts.parseOrThrow(amount);
  return (
    BigInt(parsed.value) * amountFractionalBaseBigInt + BigInt(parsed.fraction)
  );
}

function amountFromUnits(currency: string, units: bigint): AmountJson {
  checkLogicInvariant(units >= 0n);
  const value = Number(units / amountFractionalBaseBigInt);
  checkLogicInvariant(Number.isSafeInteger(value));
  return {
    currency,
    value,
    fraction: Number(units % amountFractionalBaseBigInt),
  };
}

/**
 * DD91 pass 3: replace exact groups of small coins with a larger coin when
 * this lowers the customer's fees and the wallet does not have an excess of
 * that small denomination.
 */
function reduceSelectionFees(
  selection: MutableCoinSelection,
  candidates: AvailableCoinsOfDenom[],
  req: SelectGreedyRequest,
  baseTally: CoinSelectionTally,
): void {
  if (selectionCustomerFees(selection.totals, baseTally) === 0n) {
    return;
  }

  const groups: AvailableCoinsOfDenom[][] = [];
  for (const candidate of candidates) {
    const last = groups[groups.length - 1];
    if (
      !last ||
      getCandidateSelectionMeta(last[0]).value !==
        getCandidateSelectionMeta(candidate).value
    ) {
      groups.push([candidate]);
    } else {
      last.push(candidate);
    }
  }

  const selectedCoinsByValue = new Map<bigint, SelectedCandidateCoin[]>();
  for (const coin of selection.coins) {
    if (!coin.selected) {
      continue;
    }
    const value = getCandidateSelectionMeta(coin.denom).value;
    const coins = selectedCoinsByValue.get(value) ?? [];
    coins.push(coin);
    selectedCoinsByValue.set(value, coins);
  }

  // An excess in any non-largest denomination means that reducing coin
  // count would work against DD91's primary goal of draining small coins.
  for (let i = 0; i + 1 < groups.length; i++) {
    const factor = denominationFactor(groups[i + 1][0], groups[i][0], false);
    if (factor === undefined || factor < 2) {
      continue;
    }
    const numAvailable = groups[i].reduce(
      (sum, candidate) => sum + candidate.numAvailable,
      0,
    );
    if (numAvailable > 5 * factor) {
      return;
    }
  }

  for (let smallIndex = 0; smallIndex + 1 < groups.length; smallIndex++) {
    const smallGroup = groups[smallIndex];
    const smallValue = getCandidateSelectionMeta(smallGroup[0]).value;
    const selectedSmallCoins = selectedCoinsByValue.get(smallValue) ?? [];
    selectedSmallCoins.sort((a, b) => compareCandidateDenoms(b.denom, a.denom));
    for (
      let largeIndex = smallIndex + 1;
      largeIndex < groups.length;
      largeIndex++
    ) {
      const largeGroup = groups[largeIndex];
      const factor = denominationFactor(largeGroup[0], smallGroup[0], true);
      if (factor === undefined || factor < 2) {
        continue;
      }

      while (selectedSmallCoins.length >= factor) {
        const smallCoins = selectedSmallCoins.slice(0, factor);

        let replacementMade = false;
        for (const largeDenom of largeGroup) {
          const numSelected =
            selection.selectedCountByDenom.get(largeDenom) ?? 0;
          if (numSelected >= largeDenom.numAvailable) {
            continue;
          }
          const feesBefore = selectionCustomerFees(selection.totals, baseTally);
          for (const coin of smallCoins) {
            removeSelectedCoin(selection, coin, req, baseTally);
          }
          const replacement = addSelectedCoin(
            selection,
            largeDenom,
            req,
            baseTally,
          );
          const feesAfter = selectionCustomerFees(selection.totals, baseTally);
          if (
            feesAfter < feesBefore &&
            selectionIsSufficient(selection.totals, baseTally)
          ) {
            replacementMade = true;
            selectedSmallCoins.splice(0, factor);
            const largeValue = getCandidateSelectionMeta(largeDenom).value;
            const selectedLargeCoins =
              selectedCoinsByValue.get(largeValue) ?? [];
            selectedLargeCoins.push(replacement);
            selectedCoinsByValue.set(largeValue, selectedLargeCoins);
            break;
          }
          removeSelectedCoin(selection, replacement, req, baseTally);
          for (const coin of smallCoins) {
            restoreSelectedCoin(selection, coin, req, baseTally);
          }
        }
        if (!replacementMade) {
          break;
        }
        if (selectionCustomerFees(selection.totals, baseTally) === 0n) {
          return;
        }
      }
    }
  }
}

function selectForced(
  req: SelectPayCoinRequestNg,
  candidateDenoms: AvailableCoinsOfDenom[],
): SelResult | undefined {
  const selectedDenom: SelResult = {};

  const forcedSelection = req.forcedSelection;
  checkLogicInvariant(!!forcedSelection);

  for (const forcedCoin of forcedSelection.coins) {
    let found = false;
    for (const aci of candidateDenoms) {
      if (aci.numAvailable <= 0) {
        continue;
      }
      if (Amounts.cmp(aci.value, forcedCoin.value) === 0) {
        aci.numAvailable--;
        const avKey = makeAvailabilityKey(
          aci.exchangeBaseUrl,
          aci.denomPubHash,
          aci.maxAge,
        );
        let sd = selectedDenom[avKey];
        if (!sd) {
          sd = {
            contributions: [],
            denomPubHash: aci.denomPubHash,
            exchangeBaseUrl: aci.exchangeBaseUrl,
            exchangeMasterPub: aci.exchangeMasterPub,
            maxAge: aci.maxAge,
          };
        }
        sd.contributions.push(Amounts.parseOrThrow(forcedCoin.value));
        selectedDenom[avKey] = sd;
        found = true;
        break;
      }
    }
    if (!found) {
      throw Error("can't find coin for forced coin selection");
    }
  }
  return selectedDenom;
}

export interface SelectPayCoinRequestNg {
  restrictExchanges: ExchangeRestrictionSpec | undefined;
  restrictScope?: ScopeInfo;
  restrictWireMethod: string;
  contractTermsAmount: AmountJson;
  depositFeeLimit: AmountJson;
  prevPayCoins?: PreviousPayCoins;
  requiredMinimumAge?: number;
  forcedSelection?: ForcedCoinSel;

  /**
   * Deposit payto URI, in case we already know the account that
   * will be deposited into.
   *
   * That is typically the case when the wallet does a deposit to
   * return funds to the user's own bank account.
   */
  depositPaytoUri?: string;
}

export type AvailableCoinsOfDenom = DenominationInfo & {
  maxAge: number;
  numAvailable: number;
};

export type MatchingWireResult =
  | { status: "match"; wireFee: AmountJson }
  | {
      status: "account-restricted";
      accountRestrictions: Record<string, AccountRestriction[]>;
    }
  | { status: "wire-method-unsupported" }
  | { status: "wire-fee-unavailable" };

export function findMatchingWire(
  wireMethod: string,
  depositPaytoUri: string | undefined,
  exchangeWireDetails: { wireInfo: WireInfo },
): MatchingWireResult {
  const accountRestrictions: Record<string, AccountRestriction[]> = {};
  let supportsWireMethod = false;
  const wireFeeStr = exchangeWireDetails.wireInfo.feesForType[wireMethod]?.find(
    (x) => {
      return AbsoluteTime.isBetween(
        AbsoluteTime.now(),
        AbsoluteTime.fromProtocolTimestamp(x.startStamp),
        AbsoluteTime.fromProtocolTimestamp(x.endStamp),
      );
    },
  )?.wireFee;

  for (const acc of exchangeWireDetails.wireInfo.accounts) {
    const ppRes = Paytos.fromString(acc.payto_uri);
    if (Result.isError(ppRes)) {
      throw Error(`failed to parse payto ${acc.payto_uri}`);
    }
    const pp = ppRes.value;
    checkLogicInvariant(!!pp);
    if (pp.targetType !== wireMethod) {
      continue;
    }
    supportsWireMethod = true;
    if (!wireFeeStr) {
      return { status: "wire-fee-unavailable" };
    }

    let debitAccountCheckOk = false;
    if (depositPaytoUri) {
      const checkResult = checkAccountRestriction(
        depositPaytoUri,
        acc.debit_restrictions,
      );
      if (checkResult.ok) {
        debitAccountCheckOk = true;
      }
    } else {
      debitAccountCheckOk = true;
    }

    if (!debitAccountCheckOk) {
      // Keep the restrictions that rejected the account, so that the caller
      // can say why the exchange cannot be used.  They carry the human
      // readable hints.
      accountRestrictions[acc.payto_uri] = acc.debit_restrictions;
      continue;
    }

    return { status: "match", wireFee: Amounts.parseOrThrow(wireFeeStr) };
  }
  if (Object.keys(accountRestrictions).length > 0) {
    return {
      status: "account-restricted",
      accountRestrictions,
    };
  }
  return supportsWireMethod
    ? { status: "wire-fee-unavailable" }
    : { status: "wire-method-unsupported" };
}

export interface ExchangeAcceptanceResult {
  accepted: boolean;
  acceptedByExchangePub: boolean;
  acceptedByAuditorPub: boolean;
  exchangeUrlListed: boolean;
  receiverMasterPubs: string[];
  masterPubMismatch: boolean;
}

export function checkExchangeAccepted(
  exchangeDetails: Pick<
    ExchangeDetails,
    "masterPublicKey" | "exchangeBaseUrl" | "auditors"
  >,
  exchangeRestrictions: ExchangeRestrictionSpec | undefined,
  denomPubHash?: string,
): ExchangeAcceptanceResult {
  if (!exchangeRestrictions) {
    return {
      accepted: true,
      acceptedByExchangePub: true,
      acceptedByAuditorPub: true,
      exchangeUrlListed: true,
      receiverMasterPubs: [exchangeDetails.masterPublicKey],
      masterPubMismatch: false,
    };
  }
  let acceptedByExchangePub = false;
  let acceptedByAuditorPub = false;
  const receiverMasterPubs: string[] = [];
  for (const allowedExchange of exchangeRestrictions.exchanges) {
    if (allowedExchange.exchangeBaseUrl === exchangeDetails.exchangeBaseUrl) {
      receiverMasterPubs.push(allowedExchange.exchangePub);
    }
    if (allowedExchange.exchangePub === exchangeDetails.masterPublicKey) {
      acceptedByExchangePub = true;
      break;
    }
  }
  for (const allowedAuditor of exchangeRestrictions.auditors) {
    if (
      hasVerifiedAuditorTrust(exchangeDetails.auditors, {
        auditorBaseUrl: allowedAuditor.auditorBaseUrl,
        auditorPub: allowedAuditor.auditorPub,
        denomPubHash,
      })
    ) {
      acceptedByAuditorPub = true;
      break;
    }
  }
  const accepted = acceptedByExchangePub || acceptedByAuditorPub;
  const exchangeUrlListed = receiverMasterPubs.length > 0;
  return {
    accepted,
    acceptedByExchangePub,
    acceptedByAuditorPub,
    exchangeUrlListed,
    receiverMasterPubs,
    masterPubMismatch:
      !acceptedByExchangePub && exchangeUrlListed && !acceptedByAuditorPub,
  };
}

interface SelectPayCandidatesRequest {
  currency: string;
  restrictWireMethod: string | undefined;
  depositPaytoUri?: string;
  restrictScope?: ScopeInfo;
  restrictExchanges: ExchangeRestrictionSpec | undefined;
  requiredMinimumAge?: number;

  /**
   * If set to true, the coin selection will also use coins that are not
   * materially available yet, but that are expected to become available
   * as the output of a refresh operation.
   */
  includePendingCoins: boolean;
}

export interface PayCoinCandidates {
  coinAvailability: AvailableCoinsOfDenom[];
  currentWireFeePerExchange: Record<string, AmountJson>;
}

async function selectPayCandidates(
  wex: WalletExecutionContext,
  tx: WalletDbTransaction,
  req: SelectPayCandidatesRequest,
): Promise<PayCoinCandidates> {
  // FIXME: Use the existing helper (from balance.ts) to
  // get acceptable exchanges.
  logger.shouldLogTrace() &&
    logger.trace(`selecting available coin candidates for ${j2s(req)}`);
  const denoms: AvailableCoinsOfDenom[] = [];
  const exchanges = await tx.getExchanges();
  const wfPerExchange: Record<string, AmountJson> = {};
  for (const exchange of exchanges) {
    const exchangeDetails = await getExchangeDetailsInTx(
      tx,
      exchange.baseUrl,
      exchange,
    );
    // Exchange has same currency
    if (exchangeDetails?.currency !== req.currency) {
      logger.shouldLogTrace() &&
        logger.trace(`skipping ${exchange.baseUrl} due to currency mismatch`);
      continue;
    }

    // Exchange supports wire method (only for pay/deposit)
    if (req.restrictWireMethod) {
      const wireMatch = findMatchingWire(
        req.restrictWireMethod,
        req.depositPaytoUri,
        exchangeDetails,
      );
      switch (wireMatch.status) {
        case "match":
          wfPerExchange[exchange.baseUrl] = wireMatch.wireFee;
          break;
        case "account-restricted":
          continue;
        case "wire-method-unsupported":
        case "wire-fee-unavailable":
          logger.shouldLogTrace() &&
            logger.trace(
              `skipping ${exchange.baseUrl} due to ${wireMatch.status}`,
            );
          continue;
        default:
          assertUnreachable(wireMatch);
      }
    }

    // Exchange is trusted in the exchange list or auditor list
    const acceptance = checkExchangeAccepted(
      exchangeDetails,
      req.restrictExchanges,
    );
    if (!acceptance.accepted) {
      if (logger.shouldLogTrace()) {
        logger.trace(`skipping ${exchange.baseUrl} due to unacceptability`);
      }
      continue;
    }

    const isInScope = req.restrictScope
      ? await checkExchangeInScopeTx(
          tx,
          exchange.baseUrl,
          req.restrictScope,
          exchangeDetails,
        )
      : true;

    if (!isInScope) {
      continue;
    }

    // Filter coins restricted by age
    let ageLower = 0;
    let ageUpper = AgeRestriction.AGE_UNRESTRICTED;
    if (req.requiredMinimumAge) {
      ageLower = req.requiredMinimumAge;
    }

    const myExchangeCoins = req.includePendingCoins
      ? (
          await tx.getCoinAvailabilityByExchange(
            exchangeDetails.exchangeBaseUrl,
          )
        ).filter(
          (x) =>
            x.maxAge >= ageLower &&
            x.maxAge <= ageUpper &&
            (x.freshCoinCount > 0 || (x.pendingRefreshOutputCount ?? 0) > 0),
        )
      : await tx.getCoinAvailabilityByExchangeAndAgeRange(
          exchangeDetails.exchangeBaseUrl,
          ageLower,
          ageUpper,
        );

    if (logger.shouldLogTrace()) {
      logger.trace(
        `exchange ${exchange.baseUrl} has ${myExchangeCoins.length} candidate records`,
      );
    }

    let numUsable = 0;
    const currentEndorsementRefs = new Map(
      myExchangeCoins
        .filter((x) => x.exchangeMasterPub !== exchangeDetails.masterPublicKey)
        .map((x) => {
          const ref = {
            exchangeMasterPub: exchangeDetails.masterPublicKey,
            denomPubHash: x.denomPubHash,
          };
          return [denomRefKey(ref), ref] as const;
        }),
    );
    const candidateDenoms = await tx.getDenominationsByRefs([
      ...myExchangeCoins,
      ...currentEndorsementRefs.values(),
    ]);
    const candidateDenomsByRef = new Map(
      candidateDenoms.map((denom) => [denomRefKey(denom), denom]),
    );

    // Save denoms with how many coins are available.
    for (const coinAvail of myExchangeCoins) {
      const denom = candidateDenomsByRef.get(denomRefKey(coinAvail));
      checkDbInvariant(
        !!denom,
        `denomination of a coin is missing hash: ${coinAvail.denomPubHash}`,
      );
      if (denom.isRevoked) {
        logger.trace("denom is revoked");
        continue;
      }
      if (
        !checkExchangeAccepted(
          exchangeDetails,
          req.restrictExchanges,
          denom.denomPubHash,
        ).accepted
      ) {
        logger.trace("denom is not accepted by the receiver");
        continue;
      }
      if (
        req.restrictScope &&
        !(await checkExchangeInScopeTx(
          tx,
          exchange.baseUrl,
          req.restrictScope,
          exchangeDetails,
          denom.denomPubHash,
        ))
      ) {
        logger.trace("denom is outside the requested scope");
        continue;
      }
      if (denom.exchangeMasterPub === exchangeDetails.masterPublicKey) {
        if (!denom.isOffered) {
          logger.trace("denom is unoffered");
          continue;
        }
      } else {
        // The current key set is not allowed to receive authorizations over
        // old coins until the user explicitly confirms that master key.
        if (exchange.supersededKeySet) {
          logger.trace(
            `denom ${denom.denomPubHash} is frozen by an unconfirmed master-key change`,
          );
          continue;
        }
        // Confirmation alone is not an assertion that the new operator can
        // settle every historical denomination.  Require a valid current-key
        // certificate for the identical economic terms, while retaining the
        // old certificate as the coin's issuance provenance.
        const endorsement = candidateDenomsByRef.get(
          denomRefKey({
            exchangeMasterPub: exchangeDetails.masterPublicKey,
            denomPubHash: denom.denomPubHash,
          }),
        );
        if (
          !endorsement ||
          endorsement.verificationStatus !==
            DenominationVerificationStatus.VerifiedGood ||
          endorsement.isRevoked ||
          !endorsement.isOffered ||
          !denominationTermsMatchAcrossMasterKeys(denom, endorsement)
        ) {
          logger.trace(
            `denom ${denom.denomPubHash} has no matching current-key endorsement`,
          );
          continue;
        }
      }
      numUsable++;
      let numAvailable = coinAvail.freshCoinCount ?? 0;
      if (req.includePendingCoins) {
        numAvailable += coinAvail.pendingRefreshOutputCount ?? 0;
      }
      denoms.push({
        ...WalletDenomination.toDenomInfo(denom),
        numAvailable,
        maxAge: coinAvail.maxAge,
      });
    }

    if (logger.shouldLogTrace()) {
      logger.trace(
        `exchange ${exchange.baseUrl} has ${numUsable} candidate records with usable denominations`,
      );
    }
  }
  // Sort by available amount (descending),  deposit fee (ascending) and
  // denomPub (ascending) if deposit fee is the same
  // (to guarantee deterministic results)
  denoms.sort(
    (o1, o2) =>
      -Amounts.cmp(o1.value, o2.value) ||
      Amounts.cmp(o1.feeDeposit, o2.feeDeposit) ||
      strcmp(o1.denomPubHash, o2.denomPubHash),
  );
  return {
    coinAvailability: denoms,
    currentWireFeePerExchange: wfPerExchange,
  };
}

export interface PeerCoinSelectionDetails {
  exchangeBaseUrl: string;

  /**
   * Info of Coins that were selected.
   */
  coins: SelectedCoin[];

  /**
   * How much of the deposit fees is the customer paying?
   */
  customerDepositFees: AmountJson;

  totalDepositFees: AmountJson;

  maxExpirationDate: TalerProtocolTimestamp;
}

export type SelectPeerCoinsResult =
  | { type: "success"; result: PeerCoinSelectionDetails }
  | {
      type: "failure";
      insufficientBalanceDetails: PaymentInsufficientBalanceDetails;
    };

export interface PeerCoinSelectionRequest {
  instructedAmount: AmountJson;

  /**
   * Are deposit fees covered by the counterparty?
   *
   * Defaults to false.
   */
  feesCoveredByCounterparty?: boolean;

  /**
   * Restrict the scope of funds that can be spent via the given
   * scope info.
   */
  restrictScope?: ScopeInfo;

  /** Additionally pin selection to this exchange. */
  exchangeBaseUrl?: string;

  /**
   * Instruct the coin selection to repair this coin
   * selection instead of selecting completely new coins.
   */
  repair?: PreviousPayCoins;
}

export async function computeCoinSelMaxExpirationDate(
  wex: WalletExecutionContext,
  tx: WalletDbTransaction,
  selectedDenom: SelResult,
): Promise<TalerProtocolTimestamp> {
  let minAutorefreshExecuteThreshold = TalerProtocolTimestamp.never();
  const selections = Object.values(selectedDenom);
  const denoms = await getDenomInfos(wex, tx, selections);
  for (const selInfo of selections) {
    const denom = denoms.get(denomRefKey(selInfo));
    if (!denom) {
      continue;
    }
    // Compute earliest time that a selected denom
    // would have its coins auto-refreshed.
    minAutorefreshExecuteThreshold = TalerProtocolTimestamp.min(
      minAutorefreshExecuteThreshold,
      AbsoluteTime.toProtocolTimestamp(
        getAutoRefreshExecuteThreshold({
          stampExpireDeposit: denom.stampExpireDeposit,
          stampExpireWithdraw: denom.stampExpireWithdraw,
        }),
      ),
    );
  }
  return minAutorefreshExecuteThreshold;
}

export function emptyTallyForPeerPayment(
  req: PeerCoinSelectionRequest,
): CoinSelectionTally {
  const instructedAmount = req.instructedAmount;
  const currency = instructedAmount.currency;
  const zero = Amounts.zeroOfCurrency(currency);
  return {
    amountPayRemaining: instructedAmount,
    customerDepositFees: zero,
    amountDepositFeeLimitRemaining: req.feesCoveredByCounterparty
      ? instructedAmount
      : zero,
    customerWireFees: zero,
    wireFeeCoveredForExchange: new Set(),
    totalDepositFees: zero,
  };
}

function getGlobalFees(
  wireDetails: ExchangeDetails,
): ExchangeGlobalFees | undefined {
  const now = AbsoluteTime.now();
  for (let gf of wireDetails.globalFees) {
    const isActive = AbsoluteTime.isBetween(
      now,
      AbsoluteTime.fromProtocolTimestamp(gf.startDate),
      AbsoluteTime.fromProtocolTimestamp(gf.endDate),
    );
    if (!isActive) {
      continue;
    }
    return gf;
  }
  return undefined;
}

async function internalSelectPeerCoins(
  wex: WalletExecutionContext,
  tx: WalletDbTransaction,
  req: PeerCoinSelectionRequest,
  exch: ExchangeDetails,
  includePendingCoins: boolean,
): Promise<
  | { sel: SelResult; tally: CoinSelectionTally; resCoins: SelectedCoin[] }
  | undefined
> {
  const candidatesRes = await selectPayCandidates(wex, tx, {
    currency: Amounts.currencyOf(req.instructedAmount),
    restrictExchanges: {
      auditors: [],
      exchanges: [
        {
          exchangeBaseUrl: exch.exchangeBaseUrl,
          exchangePub: exch.masterPublicKey,
        },
      ],
    },
    restrictWireMethod: undefined,
    includePendingCoins,
  });
  const candidates = candidatesRes.coinAvailability;
  if (logger.shouldLogTrace()) {
    logger.trace(`peer payment candidate coins: ${j2s(candidates)}`);
  }
  const tally = emptyTallyForPeerPayment(req);
  const resCoins: SelectedCoin[] = [];

  await maybeRepairCoinSelection(wex, tx, req.repair ?? [], resCoins, tally, {
    wireFeesPerExchange: {},
  });

  const selRes = selectGreedy(
    {
      wireFeesPerExchange: {},
      algorithm: wex.ws.config.testing.coinSelectionAlgorithm,
    },
    candidates,
    tally,
  );
  if (!selRes) {
    return undefined;
  }

  return {
    sel: selRes,
    tally,
    resCoins,
  };
}

export async function selectPeerCoinsInTx(
  wex: WalletExecutionContext,
  tx: WalletDbTransaction,
  req: PeerCoinSelectionRequest,
): Promise<SelectPeerCoinsResult> {
  const instructedAmount = req.instructedAmount;
  if (Amounts.isZero(instructedAmount)) {
    // Other parts of the code assume that we have at least
    // one coin to spend.
    throw new Error(
      "coin selection for peer-to-peer payment with amount of zero not supported",
    );
  }

  const exchanges = await tx.getExchanges();
  const currency = Amounts.currencyOf(instructedAmount);
  for (const exch of exchanges) {
    if (exch.detailsPointer?.currency !== currency) {
      continue;
    }
    if (req.exchangeBaseUrl && req.exchangeBaseUrl !== exch.baseUrl) {
      continue;
    }
    const exchWire = await getExchangeDetailsInTx(tx, exch.baseUrl);
    if (!exchWire) {
      continue;
    }
    const isInScope = req.restrictScope
      ? await checkExchangeInScopeTx(tx, exch.baseUrl, req.restrictScope)
      : true;
    if (!isInScope) {
      continue;
    }
    if (
      req.restrictScope &&
      req.restrictScope.type === ScopeType.Exchange &&
      req.restrictScope.url !== exch.baseUrl
    ) {
      continue;
    }
    const globalFees = getGlobalFees(exchWire);
    if (!globalFees) {
      continue;
    }

    const avRes = await internalSelectPeerCoins(wex, tx, req, exchWire, false);

    if (avRes) {
      const r = await assembleSelectPayCoinsSuccessResult(
        tx,
        avRes.sel,
        avRes.resCoins,
        avRes.tally,
      );

      const maxExpirationDate = await computeCoinSelMaxExpirationDate(
        wex,
        tx,
        avRes.sel,
      );

      return {
        type: "success",
        result: {
          coins: r.coins,
          customerDepositFees: Amounts.parseOrThrow(r.customerDepositFees),
          totalDepositFees: Amounts.parseOrThrow(r.totalDepositFees),
          exchangeBaseUrl: exch.baseUrl,
          maxExpirationDate,
        },
      };
    }
  }
  const insufficientBalanceDetails = await reportInsufficientBalanceDetails(
    wex,
    tx,
    {
      restrictExchanges: undefined,
      instructedAmount: req.instructedAmount,
      requiredMinimumAge: undefined,
      wireMethod: undefined,
      depositPaytoUri: undefined,
      restrictScope: req.restrictScope,
      exchangeBaseUrl: req.exchangeBaseUrl,
      feesCoveredByCounterparty: req.feesCoveredByCounterparty,
      operation: "peer",
    },
  );
  return {
    type: "failure",
    insufficientBalanceDetails,
  };
}

export async function selectPeerCoins(
  wex: WalletExecutionContext,
  req: PeerCoinSelectionRequest,
): Promise<SelectPeerCoinsResult> {
  return await wex.runWalletDbTx(async (tx): Promise<SelectPeerCoinsResult> => {
    return selectPeerCoinsInTx(wex, tx, req);
  });
}

interface DepositMaximumComputation {
  total: DepositMaximum;
  byExchange: Record<string, DepositMaximum>;
}

function zeroDepositMaximum(currency: string): DepositMaximum {
  const zero = Amounts.stringify(Amounts.zeroOfCurrency(currency));
  return {
    instructedAmount: zero,
    effectiveAmount: zero,
    rawAmount: zero,
    fees: {
      coin: zero,
      wire: zero,
      refresh: zero,
    },
  };
}

/**
 * Calculate coherent full-drain deposit plans from the available candidates.
 *
 * A full drain produces no refresh change.  Under the direct-deposit fee
 * policy, the instructed amount is also the fee allowance.  Thus all fees
 * are deducted from the destination amount when they fit within the selected
 * coin value.  If they do not fit, no instructed amount using that exchange
 * can make the selection executable.
 */
function getMaxDepositAmountForAvailableCoins(
  req: GetMaxDepositAmountRequest,
  candidateRes: PayCoinCandidates,
): DepositMaximumComputation {
  interface ExchangeTotals {
    effective: AmountJson;
    coinFees: AmountJson;
  }

  const zero = Amounts.zeroOfCurrency(req.currency);
  const totalsByExchange = new Map<string, ExchangeTotals>();

  for (const cc of candidateRes.coinAvailability) {
    if (cc.numAvailable <= 0) {
      continue;
    }

    // Don't count a coin if depositing it is more expensive than the amount
    // it would give the merchant.  This is the same rule selectGreedy uses,
    // so counting it here would promise an amount that can't be selected.
    if (Amounts.cmp(cc.feeDeposit, cc.value) > 0) {
      continue;
    }

    const exchangeTotals = totalsByExchange.get(cc.exchangeBaseUrl) ?? {
      effective: zero,
      coinFees: zero,
    };
    exchangeTotals.effective = Amounts.add(
      exchangeTotals.effective,
      Amounts.mult(cc.value, cc.numAvailable).amount,
    ).amount;
    exchangeTotals.coinFees = Amounts.add(
      exchangeTotals.coinFees,
      Amounts.mult(cc.feeDeposit, cc.numAvailable).amount,
    ).amount;
    totalsByExchange.set(cc.exchangeBaseUrl, exchangeTotals);
  }

  const byExchange: Record<string, DepositMaximum> = {};
  let total = zeroDepositMaximum(req.currency);
  for (const [exchangeBaseUrl, exchangeTotals] of totalsByExchange) {
    const wireFees =
      candidateRes.currentWireFeePerExchange[exchangeBaseUrl] ?? zero;
    const settlementFees = Amounts.add(
      exchangeTotals.coinFees,
      wireFees,
    ).amount;
    if (Amounts.cmp(settlementFees, exchangeTotals.effective) > 0) {
      byExchange[exchangeBaseUrl] = zeroDepositMaximum(req.currency);
      continue;
    }

    const maximum: DepositMaximum = {
      instructedAmount: Amounts.stringify(exchangeTotals.effective),
      effectiveAmount: Amounts.stringify(exchangeTotals.effective),
      rawAmount: Amounts.stringify(
        Amounts.sub(exchangeTotals.effective, settlementFees).amount,
      ),
      fees: {
        coin: Amounts.stringify(exchangeTotals.coinFees),
        wire: Amounts.stringify(wireFees),
        refresh: Amounts.stringify(zero),
      },
    };
    byExchange[exchangeBaseUrl] = maximum;
    total = {
      instructedAmount: Amounts.stringify(
        Amounts.add(total.instructedAmount, maximum.instructedAmount).amount,
      ),
      effectiveAmount: Amounts.stringify(
        Amounts.add(total.effectiveAmount, maximum.effectiveAmount).amount,
      ),
      rawAmount: Amounts.stringify(
        Amounts.add(total.rawAmount, maximum.rawAmount).amount,
      ),
      fees: {
        coin: Amounts.stringify(
          Amounts.add(total.fees.coin, maximum.fees.coin).amount,
        ),
        wire: Amounts.stringify(
          Amounts.add(total.fees.wire, maximum.fees.wire).amount,
        ),
        refresh: Amounts.stringify(
          Amounts.add(total.fees.refresh, maximum.fees.refresh).amount,
        ),
      },
    };
  }

  return { total, byExchange };
}

interface DepositExchangeEligibility {
  masterPub: string;
  reasons: DepositEligibilityReason[];
}

async function getDepositExchangeEligibilityInTx(
  tx: WalletDbTransaction,
  req: GetMaxDepositAmountRequest,
  wireMethod: string | undefined,
): Promise<Record<string, DepositExchangeEligibility>> {
  const result: Record<string, DepositExchangeEligibility> = {};
  for (const exchange of await tx.getExchanges()) {
    const details = await getExchangeDetailsInTx(tx, exchange.baseUrl);
    if (!details || details.currency !== req.currency) {
      continue;
    }

    const reasons: DepositEligibilityReason[] = [];
    if (exchange.directDepositDisabled) {
      reasons.push({
        type: DepositEligibilityReasonType.DirectDepositDisabled,
      });
    }
    if (
      req.restrictScope &&
      !(await checkExchangeInScopeTx(tx, exchange.baseUrl, req.restrictScope))
    ) {
      reasons.push({
        type: DepositEligibilityReasonType.ScopeRestricted,
        scopeInfo: req.restrictScope,
      });
    }
    if (wireMethod) {
      const wireMatch = findMatchingWire(
        wireMethod,
        req.depositPaytoUri,
        details,
      );
      switch (wireMatch.status) {
        case "match":
          break;
        case "account-restricted":
          reasons.push({
            type: DepositEligibilityReasonType.DepositAccountRestricted,
            wireMethod,
            accountRestrictions: wireMatch.accountRestrictions,
          });
          break;
        case "wire-method-unsupported":
          reasons.push({
            type: DepositEligibilityReasonType.WireMethodUnsupported,
            wireMethod,
          });
          break;
        case "wire-fee-unavailable":
          reasons.push({
            type: DepositEligibilityReasonType.WireFeeUnavailable,
            wireMethod,
          });
          break;
        default:
          assertUnreachable(wireMatch);
      }
    }

    result[exchange.baseUrl] = {
      masterPub: details.masterPublicKey,
      reasons,
    };
  }
  return result;
}

export async function getExchangesForDepositInTx(
  wex: WalletExecutionContext,
  tx: WalletDbTransaction,
  req: { restrictScope?: ScopeInfo; currency: string },
): Promise<Exchange[]> {
  logger.trace(`getting exchanges for deposit ${j2s(req)}`);
  const exchangeInfos: Exchange[] = [];
  const allExchanges = await tx.getExchanges();
  for (const e of allExchanges) {
    const details = await getExchangeDetailsInTx(tx, e.baseUrl);
    if (!details) {
      logger.trace(`skipping ${e.baseUrl}, no details`);
      continue;
    }
    if (req.currency !== details.currency) {
      logger.trace(`skipping ${e.baseUrl}, currency mismatch`);
      continue;
    }
    if (e.directDepositDisabled) {
      logger.trace(`skipping ${e.baseUrl}, wallet deposits disabled`);
      continue;
    }
    if (req.restrictScope) {
      const inScope = await checkExchangeInScopeTx(
        tx,
        e.baseUrl,
        req.restrictScope,
      );
      if (!inScope) {
        continue;
      }
    }
    exchangeInfos.push({
      master_pub: details.masterPublicKey,
      priority: 1,
      url: e.baseUrl,
    });
  }
  return exchangeInfos;
}

export async function getExchangesForDeposit(
  wex: WalletExecutionContext,
  req: { restrictScope?: ScopeInfo; currency: string },
): Promise<Exchange[]> {
  return await wex.runWalletDbTx(async (tx) => {
    return await getExchangesForDepositInTx(wex, tx, req);
  });
}

