export async function getMaxDepositAmount(
  wex: WalletExecutionContext,
  req: GetMaxDepositAmountRequest,
): Promise<GetMaxDepositAmountResponse> {
  logger.trace(`getting max deposit amount for: ${j2s(req)}`);
  return await wex.runWalletDbTx(
    async (tx): Promise<GetMaxDepositAmountResponse> => {
      let restrictWireMethod: string | undefined = undefined;
      if (req.depositPaytoUri) {
        const p = Paytos.parseOrThrow(req.depositPaytoUri);
        restrictWireMethod = p.targetType;
      }

      const eligibility = await getDepositExchangeEligibilityInTx(
        tx,
        req,
        restrictWireMethod,
      );
      const eligibleExchanges = Object.entries(eligibility)
        .filter(([, x]) => x.reasons.length === 0)
        .map(([exchangeBaseUrl, x]) => ({
          exchangeBaseUrl,
          exchangePub: x.masterPub,
        }));
      const candidateRequest = {
        currency: req.currency,
        restrictExchanges: {
          auditors: [],
          exchanges: eligibleExchanges,
        },
        restrictWireMethod,
        restrictScope: req.restrictScope,
        depositPaytoUri: req.depositPaytoUri,
        requiredMinimumAge: undefined,
      };
      const materialCandidates = await selectPayCandidates(wex, tx, {
        ...candidateRequest,
        includePendingCoins: false,
      });
      const availableCandidates = await selectPayCandidates(wex, tx, {
        ...candidateRequest,
        includePendingCoins: true,
      });
      const material = getMaxDepositAmountForAvailableCoins(
        req,
        materialCandidates,
      );
      const available = getMaxDepositAmountForAvailableCoins(
        req,
        availableCandidates,
      );
      const exchangeDiagnostics: Record<string, DepositExchangeDiagnostics> =
        {};
      for (const [exchangeBaseUrl, exchangeEligibility] of Object.entries(
        eligibility,
      )) {
        exchangeDiagnostics[exchangeBaseUrl] = {
          material:
            material.byExchange[exchangeBaseUrl] ??
            zeroDepositMaximum(req.currency),
          available:
            available.byExchange[exchangeBaseUrl] ??
            zeroDepositMaximum(req.currency),
          reasons: exchangeEligibility.reasons,
        };
      }
      return {
        material: material.total,
        available: available.total,
        exchangeDiagnostics,
      };
    },
  );
}

function getMaxPeerPushDebitAmountForAvailableCoins(
  req: GetMaxDepositAmountRequest,
  exchangeBaseUrl: string,
  candidateRes: PayCoinCandidates,
): GetMaxPeerPushDebitAmountResponse {
  let amountEffective = Amounts.zeroOfCurrency(req.currency);
  let fees = Amounts.zeroOfCurrency(req.currency);

  for (const cc of candidateRes.coinAvailability) {
    // Same rule as selectGreedy, which the peer coin selection also goes
    // through: a coin that costs more to deposit than it is worth is never
    // selected, so counting it would promise an amount that can't be reached.
    if (Amounts.cmp(cc.feeDeposit, cc.value) > 0) {
      continue;
    }

    amountEffective = Amounts.add(
      amountEffective,
      Amounts.mult(cc.value, cc.numAvailable).amount,
    ).amount;

    fees = Amounts.add(
      fees,
      Amounts.mult(cc.feeDeposit, cc.numAvailable).amount,
    ).amount;
  }

  return {
    exchangeBaseUrl,
    effectiveAmount: Amounts.stringify(amountEffective),
    rawAmount: Amounts.stringify(Amounts.sub(amountEffective, fees).amount),
  };
}

export async function getMaxPeerPushDebitAmount(
  wex: WalletExecutionContext,
  req: GetMaxPeerPushDebitAmountRequest,
): Promise<GetMaxPeerPushDebitAmountResponse> {
  logger.trace(`getting max deposit amount for: ${j2s(req)}`);

  return await wex.runWalletDbTx(
    async (tx): Promise<GetMaxPeerPushDebitAmountResponse> => {
      let result: GetMaxPeerPushDebitAmountResponse | undefined = undefined;
      const currency = req.currency;
      const exchanges = await tx.getExchanges();
      for (const exch of exchanges) {
        if (exch.detailsPointer?.currency !== currency) {
          continue;
        }
        const exchWire = await getExchangeDetailsInTx(tx, exch.baseUrl);
        if (!exchWire) {
          continue;
        }
        const isInScope = req.restrictScope
          ? await checkExchangeInScopeTx(tx, exch.baseUrl, req.restrictScope)
          : true;
        if (!isInScope) {
          continue;
        }
        if (
          req.restrictScope &&
          req.restrictScope.type === ScopeType.Exchange &&
          req.restrictScope.url !== exch.baseUrl
        ) {
          continue;
        }
        const globalFees = getGlobalFees(exchWire);
        if (!globalFees) {
          continue;
        }

        const candidatesRes = await selectPayCandidates(wex, tx, {
          currency,
          restrictExchanges: {
            auditors: [],
            exchanges: [
              {
                exchangeBaseUrl: exchWire.exchangeBaseUrl,
                exchangePub: exchWire.masterPublicKey,
              },
            ],
          },
          restrictWireMethod: undefined,
          includePendingCoins: true,
        });

        const myExchangeRes = getMaxPeerPushDebitAmountForAvailableCoins(
          req,
          exchWire.exchangeBaseUrl,
          candidatesRes,
        );

        if (!result) {
          result = myExchangeRes;
        } else if (Amounts.cmp(result.rawAmount, myExchangeRes.rawAmount) < 0) {
          result = myExchangeRes;
        }
      }
      if (!result) {
        return {
          effectiveAmount: Amounts.stringify(Amounts.zeroOfCurrency(currency)),
          rawAmount: Amounts.stringify(Amounts.zeroOfCurrency(currency)),
        };
      }
      return result;
    },
  );
}
