/**
 * @file
 * Compact, useful rendering of known bank accounts.
 */

import { WalletBankAccountInfo } from "@gnu-taler/taler-util";

/** Render one known bank account for a person reading the CLI output. */
export function formatPrettyBankAccount(
  account: WalletBankAccountInfo,
  verbose = false,
  oneline = false,
): string[] {
  const label = account.label ?? "(unlabelled)";
  const currencies = account.currencies?.join(", ") ?? "unknown currencies";
  const lines = [`${label}  ${account.paytoUri}  [${currencies}]`];

  if (oneline || !verbose) return lines;

  lines.push(`  ID: ${account.bankAccountId}`);
  lines.push(`  KYC completed: ${account.kycCompleted ? "yes" : "no"}`);
  return lines;
}
