export interface WellKnownPaytoParams {
  amount?: AmountString;
  message?: string;
  ["ch-qrr"]?: string;
  ["receiver-name"]?: string;
  ["receiver-town"]?: string;
  ["receiver-postal-code"]?: string;
}

/**
 * Add query parameters to a payto URI.
 *
 * Existing parameters are preserved.
 */
export function addPaytoQueryParams(
  s: string,
  params: WellKnownPaytoParams,
): string {
  if (!s.startsWith(PAYTO_PREFIX)) {
    throw Error("not a payto URI");
  }
  const [acct, search] = s.slice(PAYTO_PREFIX.length).split("?");
  const searchParams = new URLSearchParams(search || "");
  for (const [paramKey, paramValue] of Object.entries(params)) {
    searchParams.set(paramKey, paramValue);
  }
  const paramList = [...searchParams.entries()];
  if (paramList.length === 0) {
    return PAYTO_PREFIX + acct;
  }
  return PAYTO_PREFIX + acct + "?" + createSearchParams(paramList);
}

/**
 * https://developer.mozilla.org/en-US/docs/Web/JavaScript/Reference/Global_Objects/encodeURIComponent#encoding_for_rfc3986
 */
function encodeRFC3986URIComponent(str: string): string {
  return encodeURIComponent(str).replace(
    /[!'()*]/g,
    (c) => `%${c.charCodeAt(0).toString(16).toUpperCase()}`,
  );
}
const rfc3986 = encodeRFC3986URIComponent;

/**
 *
 * https://www.rfc-editor.org/rfc/rfc3986
 */
function createSearchParams(paramList: [string, string][]): string {
  return paramList
    .map(([key, value]) => `${rfc3986(key)}=${rfc3986(value)}`)
    .join("&");
}

export function paytoFromTransferSubject(
  basePayto: string,
  opt: TransferSubject,
): string | undefined {
  switch (opt.type) {
    case "SIMPLE": {
      return addPaytoQueryParams(basePayto, {
        message: opt.subject,
        amount: opt.credit_amount,
      });
    }
    case "URI": {
      return undefined;
    }
    case "CH_QR_BILL": {
      return addPaytoQueryParams(basePayto, {
        "ch-qrr": opt.qr_reference_number,
        amount: opt.credit_amount,
      });
    }
    default:
      logger.warn(`Unsupported transfer subject: ${j2s(opt)}`);
      return undefined;
  }
}
