export type Sqlite3Database = {
  internalDbHandle: any;
  exec(sqlStr: string): Promise<void>;
  prepare(stmtStr: string): Promise<Sqlite3Statement>;
  close(): Promise<void>;
};
export type Sqlite3Statement = {
  internalStatement: any;

  run(params?: BindParams): Promise<RunResult>;
  getAll(params?: BindParams): Promise<ResultRow[]>;
  getFirst(params?: BindParams): Promise<ResultRow | undefined>;
};

export interface RunResult {
  lastInsertRowid: number | bigint;
}

export type Sqlite3Value = string | Uint8Array | number | null | bigint;

export type BindParams = Record<string, Sqlite3Value | undefined>;
export type ResultRow = Record<string, Sqlite3Value>;

/**
 * SQLite error shape shared by the qtart and taler-helper-sqlite3 adapters.
 *
 * `code` and `errno` contain SQLite's extended symbolic and numeric result
 * codes, respectively.
 */
export class Sqlite3Error extends Error {
  override readonly name = "Sqlite3Error";

  constructor(
    message: string,
    public readonly code: string,
    public readonly errno: number,
  ) {
    super(message);
  }
}

/** Recognize SQLite errors across adapter/runtime boundaries. */
export function isSqlite3Error(error: unknown): error is Sqlite3Error {
  if (!(error instanceof Error)) {
    return false;
  }
  const candidate = error as Partial<Sqlite3Error>;
  return (
    candidate.name === "Sqlite3Error" &&
    typeof candidate.code === "string" &&
    Number.isInteger(candidate.errno)
  );
}

/**
 * Common interface that multiple sqlite3 bindings
 * (such as better-sqlite3 or qtart's sqlite3 bindings)
 * can adapt to.
 *
 * This does not expose full sqlite3 functionality, but just enough
 * to be used by our IndexedDB sqlite3 backend.
 */
export interface Sqlite3Interface {
  open(filename: string): Promise<Sqlite3Database>;
}
