import {
  CancellationToken,
  EmptyObject,
  FailCasesByMethod,
  HttpStatusCode,
  LibtoolVersion,
  OperationAlternative,
  OperationFail,
  OperationOk,
  PaymentResponse,
  RelativeTime,
  ResultByMethod,
  TaldirAlreadyPaidResponse,
  TaldirMailboxDetailResponse,
  TaldirRateLimitedResponse,
  TalerDirectoryApi,
  TalerErrorDetail,
  carefullyParseConfig,
  codecForAny,
  codecForTaldirAlreadyPaidResponse,
  codecForTaldirMailboxDetailResponse,
  codecForTalerDirectoryConfigResponse,
  opFixedSuccess,
  opKnownHttpFailure,
  opSuccessFromHttp,
  opUnknownHttpFailure,
} from "@gnu-taler/taler-util";
import {
  HttpRequestLibrary,
  createPlatformHttpLib,
} from "@gnu-taler/taler-util/http";
import { pathSegment } from "./utils.js";

export type TalerDirectoryInstanceResultByMethod<
  prop extends keyof TalerDirectoryInstanceHttpClient,
> = ResultByMethod<TalerDirectoryInstanceHttpClient, prop>;
export type TalerDirectoryInstanceErrorsByMethod<
  prop extends keyof TalerDirectoryInstanceHttpClient,
> = FailCasesByMethod<TalerDirectoryInstanceHttpClient, prop>;

/**
 * Protocol version spoken with the service.
 *
 * Endpoint must be ordered in the same way that in the docs
 * Response code (http and taler) must have the same order that in the docs
 * That way is easier to see changes
 *
 * Uses libtool's current:revision:age versioning.
 */
export class TalerDirectoryInstanceHttpClient {
  public static readonly PROTOCOL_VERSION = "1:0:0";

  readonly httpLib: HttpRequestLibrary;
  readonly cancellationToken: CancellationToken | undefined;

  constructor(
    readonly baseUrl: string,
    httpClient?: HttpRequestLibrary,
    cancellationToken?: CancellationToken,
  ) {
    this.httpLib = httpClient ?? createPlatformHttpLib();
    this.cancellationToken = cancellationToken;
  }

  static isCompatible(version: string): boolean {
    const compare = LibtoolVersion.compare(
      TalerDirectoryInstanceHttpClient.PROTOCOL_VERSION,
      version,
    );
    return compare?.compatible ?? false;
  }

  /**
   * https://docs.taler.net/core/api-taldir.html#get--config
   */
  async getConfig(): Promise<
    | OperationOk<TalerDirectoryApi.TalerDirectoryConfigResponse>
    | OperationFail<HttpStatusCode.NotFound>
  > {
    const url = new URL(`config`, this.baseUrl);
    const resp = await this.httpLib.fetch(url.href, {
      method: "GET",
    });
    switch (resp.status) {
      case HttpStatusCode.Ok:
        return carefullyParseConfig(
          "taler-directory",
          TalerDirectoryInstanceHttpClient.PROTOCOL_VERSION,
          resp,
          codecForTalerDirectoryConfigResponse(),
        );
      case HttpStatusCode.NotFound:
        return opKnownHttpFailure(resp.status, resp);
      default:
        return opUnknownHttpFailure(resp);
    }
  }

  /**
   * https://docs.taler.net/core/api-taldir.html#get--$H_ALIAS
   */
  async lookupAlias(args: {
    hAlias: string;
  }): Promise<
    | OperationOk<TaldirMailboxDetailResponse>
    | OperationFail<HttpStatusCode.NotFound>
  > {
    const { hAlias: hAlias } = args;
    const url = new URL(`${pathSegment(hAlias.toUpperCase())}`, this.baseUrl);

    const resp = await this.httpLib.fetch(url.href, {
      method: "GET",
      cancellationToken: this.cancellationToken,
    });

    switch (resp.status) {
      case HttpStatusCode.Ok: {
        return opSuccessFromHttp(resp, codecForAny());
      }
      case HttpStatusCode.NotFound: {
        return opKnownHttpFailure(
          resp.status,
          resp,
        );
      }
      default:
        return opUnknownHttpFailure(resp);
    }
  }

  /**
   * https://docs.taler.net/core/api-taldir.html#post--$H_ALIAS
   */
  async postRegistration(args: {
    hAlias: string;
    solution: string;
  }): Promise<
    | OperationOk<HttpStatusCode.NoContent>
    | OperationFail<HttpStatusCode.Forbidden>
    | OperationFail<HttpStatusCode.NotFound>
    | OperationFail<HttpStatusCode.TooManyRequests>
  > {
    const { hAlias: hAlias, solution: solution } = args;
    const url = new URL(`${pathSegment(hAlias.toUpperCase())}`, this.baseUrl);

    const resp = await this.httpLib.fetch(url.href, {
      method: "POST",
      body: {
        solution: solution,
      },
      cancellationToken: this.cancellationToken,
    });

    switch (resp.status) {
      case HttpStatusCode.NoContent: {
        return opFixedSuccess(resp, resp.status);
      }
      case HttpStatusCode.NotFound: {
        return opKnownHttpFailure(
          resp.status,
          resp,
        );
      }
      case HttpStatusCode.Forbidden: {
        return opKnownHttpFailure(
          resp.status,
          resp,
        );
      }
      case HttpStatusCode.TooManyRequests: {
        return opKnownHttpFailure(
          resp.status,
          resp,
        );
      }
       default:
        return opUnknownHttpFailure(resp);
    }
  }

  /**
   * https://docs.taler.net/core/api-taldir.html#post--register-$ALIASTYPE
   */
  async postRegistrationRequest(args: {
    alias: string;
    aliasType: string;
    targetUri: string;
    duration: RelativeTime;
  }): Promise<
    | OperationOk<TaldirAlreadyPaidResponse>
    | OperationOk<EmptyObject>
    | OperationFail<HttpStatusCode.PaymentRequired>
    | OperationFail<HttpStatusCode.TooManyRequests>
    | OperationFail<HttpStatusCode.NotFound>
  > {
    const {
      alias: alias,
      aliasType: aliasType,
      targetUri: targetUri,
      duration: duration,
    } = args;
    const url = new URL(`register/${pathSegment(aliasType)}`, this.baseUrl);

    const resp = await this.httpLib.fetch(url.href, {
      method: "POST",
      body: {
        alias: alias,
        target_uri: targetUri,
        duration: duration.d_us,
      },
      cancellationToken: this.cancellationToken,
    });

    switch (resp.status) {
      case HttpStatusCode.Accepted: {
        return opFixedSuccess(resp, {});
      }
      case HttpStatusCode.Ok: {
        return opSuccessFromHttp(resp, codecForTaldirAlreadyPaidResponse());
      }
      case HttpStatusCode.PaymentRequired: {
        return opKnownHttpFailure(resp.status, resp);
      }
      case HttpStatusCode.NotFound: {
        return opKnownHttpFailure(
          resp.status,
          resp,
        );
      }
      case HttpStatusCode.TooManyRequests: {
        return opKnownHttpFailure(
          resp.status,
          resp,
        );
      }
      default:
       return opUnknownHttpFailure(resp);
    }
  }


}
