/**
 * @file
 * Compact, useful rendering of the wallet's transaction history.
 */

import {
  AbsoluteTime,
  summarizeTalerErrorDetail,
  Transaction,
  TransactionAction,
  TransactionType,
} from "@gnu-taler/taler-util";
import { Continuation } from "./continuation.js";
import { formatTxState } from "./waitspec.js";

function descriptionOf(tx: Transaction): string | undefined {
  switch (tx.type) {
    case TransactionType.Payment:
      return tx.info == null
        ? undefined
        : `${tx.info.summary} — ${tx.info.merchant.name}`;
    case TransactionType.Refund:
      return tx.paymentInfo?.summary;
    case TransactionType.PeerPullCredit:
    case TransactionType.PeerPullDebit:
    case TransactionType.PeerPushCredit:
    case TransactionType.PeerPushDebit:
      return tx.info.summary;
    case TransactionType.DenomLoss:
      return tx.lossEventType;
    case TransactionType.Refresh:
      return `refresh of ${tx.refreshInputAmount}`;
    case TransactionType.Deposit:
      return "deposit to bank account";
    case TransactionType.Withdrawal:
      return tx.exchangeBaseUrl == null
        ? "withdrawal"
        : `withdrawal from ${tx.exchangeBaseUrl}`;
    case TransactionType.InternalWithdrawal:
      return `withdrawal from ${tx.exchangeBaseUrl}`;
    case TransactionType.Recoup:
      return "funds recouped from an exchange";
  }
}

function exchangeOf(tx: Transaction): string | undefined {
  switch (tx.type) {
    case TransactionType.Withdrawal:
    case TransactionType.InternalWithdrawal:
    case TransactionType.PeerPullCredit:
    case TransactionType.PeerPullDebit:
    case TransactionType.PeerPushCredit:
    case TransactionType.PeerPushDebit:
    case TransactionType.DenomLoss:
      return tx.exchangeBaseUrl;
    default:
      return undefined;
  }
}

function printDetail(key: string, value: unknown): string {
  return `${key}: ${typeof value === "string" ? value : JSON.stringify(value)}`;
}

function actionCommand(
  tx: Transaction,
  continuation: Continuation,
): string | undefined {
  if (continuation.actionable && continuation.automatic) {
    return `taler-wallet transactions continue ${
      tx.localTransactionId ?? tx.transactionId
    }`;
  }
  if (tx.txActions.includes(TransactionAction.Retry)) {
    return `taler-wallet transactions retry ${
      tx.localTransactionId ?? tx.transactionId
    }`;
  }
  return undefined;
}

/**
 * Render one transaction.  Actionable transactions deliberately include both
 * the explanation and a command that can be copied without relying on the
 * current ordering or filters of the list.
 */
export function formatPrettyTransaction(
  tx: Transaction,
  continuation: Continuation,
  verbose = false,
  oneline = false,
): string[] {
  const headline = `${tx.localTransactionId != null ? `${tx.localTransactionId}  ` : ""}${
    tx.type
  }  ${tx.amountEffective}  [${formatTxState(tx.txState)}]`;
  const description = descriptionOf(tx);
  if (oneline) {
    const parts = [headline];
    if (description != null) {
      parts.push(description);
    }
    if (continuation.actionable) {
      // Links and transfer details are deliberately kept out of this compact
      // form; the normal pretty view presents them on separate actionable
      // lines.
      parts.push(`Next: ${continuation.summary.split(": ")[0]}`);
    }
    if (tx.error != null) {
      parts.push(`Error: ${summarizeTalerErrorDetail(tx.error)}`);
    }
    return [parts.join(" — ")];
  }

  const lines = [headline];
  if (description != null) {
    lines.push(`  ${description}`);
  }

  if (continuation.actionable) {
    const bankConfirmationUrl = continuation.details?.bankConfirmationUrl;
    const summaryWithoutBankConfirmationUrl =
      typeof bankConfirmationUrl === "string" &&
      continuation.summary.endsWith(`: ${bankConfirmationUrl}`)
        ? continuation.summary.slice(0, -`: ${bankConfirmationUrl}`.length)
        : undefined;
    lines.push(
      `  Next: ${summaryWithoutBankConfirmationUrl ?? continuation.summary}`,
    );
    if (summaryWithoutBankConfirmationUrl != null) {
      lines.push(`    ${bankConfirmationUrl}`);
    }
    if (continuation.requiresTos) {
      lines.push(
        `  Before continuing: accept the terms of service of ${continuation.tosExchangeBaseUrl}.`,
      );
    }
    for (const [key, value] of Object.entries(continuation.details ?? {})) {
      if (value != null && key !== "bankConfirmationUrl") {
        lines.push(`  ${printDetail(key, value)}`);
      }
    }
  }

  const command = actionCommand(tx, continuation);
  if (command != null) {
    lines.push(`  Run: ${command}`);
  }

  if (tx.error != null) {
    lines.push(`  Error: ${summarizeTalerErrorDetail(tx.error)}`);
  }
  if (tx.abortReason != null) {
    lines.push(`  Aborted: ${summarizeTalerErrorDetail(tx.abortReason)}`);
  }
  if (tx.failReason != null) {
    lines.push(`  Failed: ${summarizeTalerErrorDetail(tx.failReason)}`);
  }

  if (!verbose) {
    return lines;
  }

  lines.push(`  ID: ${tx.transactionId}`);
  lines.push(
    `  Time: ${AbsoluteTime.toIsoString(
      AbsoluteTime.fromPreciseTimestamp(tx.timestamp),
    )}`,
  );
  lines.push(`  Amount before fees: ${tx.amountRaw}`);
  if (tx.amountRaw !== tx.amountEffective) {
    lines.push(`  Balance change: ${tx.amountEffective}`);
  }
  const exchange = exchangeOf(tx);
  if (exchange != null) {
    lines.push(`  Exchange: ${exchange}`);
  }
  if (tx.txActions.length > 0) {
    lines.push(`  Available actions: ${tx.txActions.join(", ")}`);
  }
  lines.push(`  Internal state ID: ${tx.stId}`);
  return lines;
}
