import type { WalletExchangeAuditor } from "./db/records.js";

export interface AuditorTrustRequirement {
  auditorBaseUrl?: string;
  auditorPub?: string;
  denomPubHash?: string;
}

/**
 * Test whether a persisted auditor entry provides verified trust for the
 * requested denomination.  Entries written by older wallets deliberately do
 * not satisfy this check: their signatures were never verified.
 */
export function auditorProvidesVerifiedTrust(
  auditor: WalletExchangeAuditor,
  requirement: AuditorTrustRequirement,
): boolean {
  if (auditor.walletAuditorSignaturesVerified !== true) {
    return false;
  }
  if (
    requirement.auditorBaseUrl != null &&
    auditor.auditor_url !== requirement.auditorBaseUrl
  ) {
    return false;
  }
  if (
    requirement.auditorPub != null &&
    auditor.auditor_pub !== requirement.auditorPub
  ) {
    return false;
  }
  if (requirement.denomPubHash == null) {
    return auditor.denomination_keys.length > 0;
  }
  return auditor.denomination_keys.some(
    (x) => x.denom_pub_h === requirement.denomPubHash,
  );
}

export function hasVerifiedAuditorTrust(
  auditors: WalletExchangeAuditor[],
  requirement: AuditorTrustRequirement,
): boolean {
  return auditors.some((auditor) =>
    auditorProvidesVerifiedTrust(auditor, requirement),
  );
}
