/**
 * Amount this payer still needs to contribute to the purse.
 *
 * A missing result means that the authenticated purse balance already meets
 * (or exceeds) the contract target.  The caller must then distinguish a
 * locally proven replay from a purse completed by another wallet.
 */
export function getPeerPullDebitRemainder(
  target: AmountLike,
  balance: AmountLike,
): AmountJson | undefined {
  const targetAmount = Amounts.parseOrThrow(target);
  const balanceAmount = Amounts.parseOrThrow(balance);
  if (Amounts.cmp(balanceAmount, targetAmount) >= 0) {
    return undefined;
  }
  return Amounts.sub(targetAmount, balanceAmount).amount;
}

export function getPeerPullDebitDepositedCoinCount(
  selection: PeerPullPaymentCoinSelection,
): number {
  const count = selection.depositedCoinCount ?? 0;
  if (
    !Number.isSafeInteger(count) ||
    count < 0 ||
    count > selection.coinPubs.length ||
    selection.coinPubs.length !== selection.contributions.length
  ) {
    throw Error("invalid persisted peer pull-debit deposit progress");
  }
  return count;
}

export function markPeerPullDebitCoinsDeposited(
  selection: PeerPullPaymentCoinSelection,
  batchStart: number,
  batchSize: number,
  confirmedPurseBalance: AmountLike,
): void {
  const oldCount = getPeerPullDebitDepositedCoinCount(selection);
  if (
    batchStart !== oldCount ||
    !Number.isSafeInteger(batchSize) ||
    batchSize <= 0 ||
    batchStart + batchSize > selection.coinPubs.length
  ) {
    throw Error("invalid peer pull-debit deposit confirmation sequence");
  }
  selection.depositedCoinCount = batchStart + batchSize;
  selection.confirmedPurseBalance = Amounts.stringify(confirmedPurseBalance);
}

export function getPeerPullDebitUnconfirmedCoins(
  selection: PeerPullPaymentCoinSelection,
  unrecoverableCoinPubs: ReadonlySet<string> = new Set(),
): CoinRefreshRequest[] {
  const acceptedCount = getPeerPullDebitDepositedCoinCount(selection);
  const coins: CoinRefreshRequest[] = [];
  for (let i = acceptedCount; i < selection.coinPubs.length; i++) {
    if (unrecoverableCoinPubs.has(selection.coinPubs[i])) {
      continue;
    }
    coins.push({
      amount: selection.contributions[i],
      coinPub: selection.coinPubs[i],
    });
  }
  return coins;
}

export function partitionPeerPullDebitRepair(
  selection: PeerPullPaymentCoinSelection,
  depositFees: AmountLike[],
  brokenCoinPub: string,
  remainder: AmountLike,
): {
  repair: PreviousPayCoins;
  recover: CoinRefreshRequest[];
} {
  if (depositFees.length !== selection.coinPubs.length) {
    throw Error("missing deposit fee for peer pull-debit repair");
  }
  let remaining = Amounts.parseOrThrow(remainder);
  const repair: PreviousPayCoins = [];
  const recover: CoinRefreshRequest[] = [];
  const acceptedCount = getPeerPullDebitDepositedCoinCount(selection);
  for (let i = acceptedCount; i < selection.coinPubs.length; i++) {
    const coinPub = selection.coinPubs[i];
    if (coinPub === brokenCoinPub) {
      continue;
    }
    const contribution = Amounts.parseOrThrow(selection.contributions[i]);
    const netContribution = Amounts.sub(contribution, depositFees[i]);
    if (
      !netContribution.saturated &&
      Amounts.isNonZero(netContribution.amount) &&
      Amounts.cmp(netContribution.amount, remaining) <= 0
    ) {
      repair.push({ coinPub, contribution });
      remaining = Amounts.sub(remaining, netContribution.amount).amount;
    } else {
      recover.push({
        coinPub,
        amount: Amounts.stringify(contribution),
      });
    }
  }
  return { repair, recover };
}

async function getStoredPeerPullDebitSelectionCostInTx(
  wex: WalletExecutionContext,
  tx: WalletDbTransaction,
  selection: PeerPullPaymentCoinSelection,
  end: number,
  currency: string,
): Promise<AmountJson> {
  if (end === 0) {
    return Amounts.zeroOfCurrency(currency);
  }
  const pubs = selection.coinPubs.slice(0, end);
  const coins = await tx.getCoinsByPubs(pubs);
  const coinsByPub = new Map(coins.map((coin) => [coin.coinPub, coin]));
  const prospective = pubs.map((coinPub, i) => {
    const coin = coinsByPub.get(coinPub);
    checkDbInvariant(!!coin, `coin ${coinPub} missing from peer pull debit`);
    return {
      coinPub,
      contribution: selection.contributions[i],
      denomPubHash: coin.denomPubHash,
      exchangeBaseUrl: coin.exchangeBaseUrl,
      exchangeMasterPub: coin.exchangeMasterPub,
    };
  });
  return getTotalPeerPaymentCostInTx(wex, tx, prospective);
}

async function retainPeerPullDebitAcceptedSelectionInTx(
  wex: WalletExecutionContext,
  tx: WalletDbTransaction,
  rec: WalletPeerPullDebit,
): Promise<number> {
  if (!rec.coinSel) {
    return 0;
  }
  const acceptedCount = getPeerPullDebitDepositedCoinCount(rec.coinSel);
  if (acceptedCount === 0) {
    return 0;
  }
  rec.coinSel.totalCost = Amounts.stringify(
    await getStoredPeerPullDebitSelectionCostInTx(
      wex,
      tx,
      rec.coinSel,
      acceptedCount,
      Amounts.currencyOf(rec.amount),
    ),
  );
  rec.coinSel.coinPubs = rec.coinSel.coinPubs.slice(0, acceptedCount);
  rec.coinSel.contributions = rec.coinSel.contributions.slice(0, acceptedCount);
  return acceptedCount;
}

function makePeerPullDebitPartialDepositError(): TalerErrorDetail {
  return makeErrorDetail(
    TalerErrorCode.WALLET_PEER_PULL_DEBIT_PURSE_GONE,
    { purseExpired: false },
    "only part of this wallet's payment was accepted by the purse",
  );
}

/**
 * Common context for a peer-pull-debit transaction.
 */
export class PeerPullDebitTransactionContext implements TransactionContext {
  readonly transactionId: TransactionIdStr;
  readonly taskId: TaskIdStr;

  constructor(
    public wex: WalletExecutionContext,
    public peerPullDebitId: string,
  ) {
    this.transactionId = constructTransactionIdentifier({
      tag: TransactionType.PeerPullDebit,
      peerPullDebitId,
    });
    this.taskId = constructTaskIdentifier({
      tag: PendingTaskType.PeerPullDebit,
      peerPullDebitId,
    });
  }

  async updateTransactionMeta(tx: WalletDbTransaction): Promise<void> {
    const rec = await tx.getPeerPullDebit(this.peerPullDebitId);
    if (rec == null) {
      await tx.deleteTransactionMeta(this.transactionId);
    } else {
      await tx.upsertTransactionMeta({
        currency: Amounts.currencyOf(rec.amount),
        exchanges: [rec.exchangeBaseUrl],
        status: rec.status,
        timestamp: rec.timestampCreated,
        transactionId: this.transactionId,
      });
    }
  }

  /**
   * Get the full transaction details for the transaction.
   *
   * Returns undefined if the transaction is in a state where we do not have a
   * transaction item (e.g. if it was deleted).
   */
  async lookupFullTransaction(
    tx: WalletDbTransaction,
  ): Promise<Transaction | undefined> {
    const pi = await tx.getPeerPullDebit(this.peerPullDebitId);
    if (!pi) {
      return undefined;
    }
    const ort = await tx.getOperationRetry(this.taskId);
    const txState = computePeerPullDebitTransactionState(pi);
    const ctRec = await tx.getContractTerms(pi.contractTermsHash);
    checkDbInvariant(!!ctRec, `no contract terms for ${this.transactionId}`);
    const contractTerms = ctRec.contractTermsRaw;
    return {
      type: TransactionType.PeerPullDebit,
      txState,
      stId: pi.status,
      scopes: await getScopeForAllExchanges(tx, [pi.exchangeBaseUrl]),
      txActions: computePeerPullDebitTransactionActions(pi),
      amountEffective: isUnsuccessfulTransaction(txState)
        ? Amounts.stringify(Amounts.zeroOfAmount(pi.amount))
        : pi.coinSel?.totalCost
          ? pi.coinSel?.totalCost
          : Amounts.stringify(pi.amount),
      amountRaw: Amounts.stringify(pi.amount),
      exchangeBaseUrl: pi.exchangeBaseUrl,
      info: {
        expiration: contractTerms.purse_expiration,
        summary: contractTerms.summary,
        iconId: contractTerms.icon_id,
      },
      abortReason: pi.abortReason,
      failReason: pi.failReason,
      timestamp: timestampPreciseFromDb(pi.timestampCreated),
      transactionId: this.transactionId,
      ...(ort?.lastError ? { error: ort.lastError } : {}),
    };
  }

  async getRecordHandle(
    tx: WalletDbTransaction,
  ): Promise<
    [WalletPeerPullDebit | undefined, RecordHandle<WalletPeerPullDebit>]
  > {
    return getGenericRecordHandle<WalletPeerPullDebit>(
      this,
      tx,
      async () => tx.getPeerPullDebit(this.peerPullDebitId),
      async (r) => {
        await tx.upsertPeerPullDebit(r);
      },
      async () => tx.deletePeerPullDebit(this.peerPullDebitId),
      (r) => computePeerPullDebitTransactionState(r),
      (r) => r.status,
      () => this.updateTransactionMeta(tx),
    );
  }

  async failTransaction(
    fromSt: PeerPullDebitRecordStatus,
    reason?: TalerErrorDetail,
    unrecoverableCoinPubs: ReadonlySet<string> = new Set(),
  ): Promise<void> {
    const { wex } = this;
    await wex.runWalletDbTx(async (tx) => {
      const [rec, h] = await this.getRecordHandle(tx);
      if (rec?.status != fromSt) {
        return;
      }
      if (rec.coinSel) {
        const recover = getPeerPullDebitUnconfirmedCoins(
          rec.coinSel,
          unrecoverableCoinPubs,
        );
        if (recover.length > 0) {
          await createRefreshGroup(
            wex,
            tx,
            Amounts.currencyOf(rec.amount),
            recover,
            RefreshReason.AbortPeerPullDebit,
            this.transactionId,
          );
        }
        await retainPeerPullDebitAcceptedSelectionInTx(wex, tx, rec);
      }
      rec.status = PeerPullDebitRecordStatus.Failed;
      rec.failReason = reason;
      await h.update(rec, "fail");
    });
  }

  /**
   * Terminate the transaction because the exchange does not have the purse of
   * the invoice anymore, which happens when the invoice lapsed, when the
   * payee withdrew it and when another wallet paid it first.
   */
  async purseGoneTransaction(
    fromSt: PeerPullDebitRecordStatus,
    unrecoverableCoinPubs: ReadonlySet<string> = new Set(),
  ): Promise<void> {
    const { wex } = this;
    await wex.runWalletDbTx(async (tx) => {
      const [rec, h] = await this.getRecordHandle(tx);
      if (rec?.status != fromSt) {
        return;
      }
      if (rec.coinSel) {
        const acceptedCount = getPeerPullDebitDepositedCoinCount(rec.coinSel);
        // Only the suffix without a signed deposit confirmation can be
        // recovered.  Confirmed prefix coins did reach the purse.
        const coinPubs = getPeerPullDebitUnconfirmedCoins(
          rec.coinSel,
          unrecoverableCoinPubs,
        );
        if (coinPubs.length > 0) {
          const refresh = await createRefreshGroup(
            wex,
            tx,
            Amounts.currencyOf(rec.totalCostEstimated),
            coinPubs,
            RefreshReason.AbortPeerPullDebit,
            this.transactionId,
          );
          rec.abortRefreshGroupId = refresh.refreshGroupId;
        }
        if (acceptedCount > 0) {
          await retainPeerPullDebitAcceptedSelectionInTx(wex, tx, rec);
          rec.status = PeerPullDebitRecordStatus.Failed;
          rec.failReason = makePeerPullDebitPartialDepositError();
          await h.update(rec, "purse-gone-after-partial-deposit");
          return;
        }
      }
      const ct = await tx.getContractTerms(rec.contractTermsHash);
      checkDbInvariant(!!ct, "contract terms for P2P payment not found");
      if (isPurseGoneByExpiration(ct.contractTermsRaw.purse_expiration)) {
        rec.status = PeerPullDebitRecordStatus.Expired;
        await h.update(rec, "expire");
      } else {
        rec.status = PeerPullDebitRecordStatus.Aborted;
        rec.abortReason = makeErrorDetail(
          TalerErrorCode.WALLET_PEER_PULL_DEBIT_PURSE_GONE,
          { purseExpired: false },
          "this invoice was already paid or withdrawn by the payee",
        );
        await h.update(rec, "purse-gone");
      }
    });
  }

  async userDeleteTransaction(): Promise<void> {
    await this.wex.runWalletDbTx(async (tx) => {
      await this.deleteTransactionInTx(tx);
    });
  }

  async deleteTransactionInTx(tx: WalletDbTransaction): Promise<void> {
    const [rec, h] = await this.getRecordHandle(tx);
    if (!rec) {
      return;
    }
    await h.update(undefined, "delete");
  }

  async userSuspendTransaction(): Promise<void> {
    await this.wex.runWalletDbTx(async (tx) => {
      const [rec, h] = await this.getRecordHandle(tx);
      if (!rec) {
        return;
      }
      switch (rec.status) {
        case PeerPullDebitRecordStatus.DialogProposed:
        case PeerPullDebitRecordStatus.Done:
        case PeerPullDebitRecordStatus.SuspendedDeposit:
        case PeerPullDebitRecordStatus.Aborted:
        case PeerPullDebitRecordStatus.Failed:
        case PeerPullDebitRecordStatus.Expired:
        case PeerPullDebitRecordStatus.SuspendedAbortingRefresh:
          return;
        case PeerPullDebitRecordStatus.PendingDeposit:
          rec.status = PeerPullDebitRecordStatus.SuspendedDeposit;
          break;
        case PeerPullDebitRecordStatus.AbortingRefresh:
          rec.status = PeerPullDebitRecordStatus.SuspendedAbortingRefresh;
          break;
        default:
          assertUnreachable(rec.status);
      }
      await h.update(rec, "suspend");
    });
    this.wex.taskScheduler.stopShepherdTask(this.taskId);
  }

  async userResumeTransaction(): Promise<void> {
    await this.wex.runWalletDbTx(async (tx) => {
      const [rec, h] = await this.getRecordHandle(tx);
      if (!rec) {
        return;
      }
      switch (rec.status) {
        case PeerPullDebitRecordStatus.SuspendedDeposit:
          rec.status = PeerPullDebitRecordStatus.PendingDeposit;
          break;
        case PeerPullDebitRecordStatus.SuspendedAbortingRefresh:
          rec.status = PeerPullDebitRecordStatus.AbortingRefresh;
          break;
        case PeerPullDebitRecordStatus.Aborted:
        case PeerPullDebitRecordStatus.AbortingRefresh:
        case PeerPullDebitRecordStatus.Failed:
        case PeerPullDebitRecordStatus.DialogProposed:
        case PeerPullDebitRecordStatus.Done:
        case PeerPullDebitRecordStatus.Expired:
        case PeerPullDebitRecordStatus.PendingDeposit:
          // Do nothing
          return;
        default:
          assertUnreachable(rec.status);
      }
      await h.update(rec, "resume");
    });
    await this.wex.taskScheduler.resetTask(this.taskId);
  }

  async userFailTransaction(reason?: TalerErrorDetail): Promise<void> {
    await this.wex.runWalletDbTx(async (tx) => {
      const [rec, h] = await this.getRecordHandle(tx);
      if (!rec) {
        return;
      }
      switch (rec.status) {
        case PeerPullDebitRecordStatus.SuspendedDeposit:
        case PeerPullDebitRecordStatus.PendingDeposit:
          // These states advertise Abort, which recovers every unconfirmed
          // coin, but deliberately do not advertise Fail.
          return;
        case PeerPullDebitRecordStatus.AbortingRefresh:
        case PeerPullDebitRecordStatus.SuspendedAbortingRefresh:
          // FIXME: Should we also abort the corresponding refresh session?!
          rec.status = PeerPullDebitRecordStatus.Failed;
          rec.failReason = reason;
          break;
        default:
          return;
      }
      await h.update(rec, "user-fail");
    });
    this.wex.taskScheduler.stopShepherdTask(this.taskId);
  }

  async userAbortTransaction(reason?: TalerErrorDetail): Promise<void> {
    await this.wex.runWalletDbTx(async (tx) => {
      const [pi, h] = await this.getRecordHandle(tx);
      if (!pi) {
        return;
      }
      switch (pi.status) {
        case PeerPullDebitRecordStatus.SuspendedDeposit:
        case PeerPullDebitRecordStatus.PendingDeposit:
          break;
        default:
          return;
      }
      const currency = Amounts.currencyOf(pi.totalCostEstimated);
      const coinPubs: CoinRefreshRequest[] = [];

      if (!pi.coinSel) {
        // We didn't even select coins yet, abort immediately.
        // Can happen for DBs that still have a prospective
        // coin selection.
        pi.status = PeerPullDebitRecordStatus.Aborted;
        pi.abortReason = reason;
      } else {
        const acceptedCount = getPeerPullDebitDepositedCoinCount(pi.coinSel);
        coinPubs.push(...getPeerPullDebitUnconfirmedCoins(pi.coinSel));
        if (coinPubs.length === 0) {
          if (acceptedCount > 0) {
            await retainPeerPullDebitAcceptedSelectionInTx(this.wex, tx, pi);
            pi.status = PeerPullDebitRecordStatus.Failed;
            pi.failReason = makePeerPullDebitPartialDepositError();
            pi.abortReason = reason;
          } else {
            pi.status = PeerPullDebitRecordStatus.Aborted;
            pi.abortReason = reason;
          }
          await h.update(pi, "abort-without-refresh");
          return;
        }
        const refresh = await createRefreshGroup(
          this.wex,
          tx,
          currency,
          coinPubs,
          RefreshReason.AbortPeerPullDebit,
          this.transactionId,
        );

        pi.status = PeerPullDebitRecordStatus.AbortingRefresh;
        pi.abortRefreshGroupId = refresh.refreshGroupId;
        pi.abortReason = reason;
      }
      await h.update(pi, "abort");
    });
    await this.wex.taskScheduler.resetTask(this.taskId);
  }
}

async function handlePurseCreationConflict(
  ctx: PeerPullDebitTransactionContext,
  peerPullInc: WalletPeerPullDebit,
  conflict: PurseConflict,
): Promise<TaskRunResult> {
  if (conflict.code !== TalerErrorCode.EXCHANGE_GENERIC_INSUFFICIENT_FUNDS) {
    await ctx.failTransaction(peerPullInc.status, { ...conflict });
    return TaskRunResult.finished();
  }

  const brokenCoinPub = conflict.coin_pub;
  logger.trace(`excluded broken coin pub=${brokenCoinPub}`);
  const exchangeBaseUrl = peerPullInc.exchangeBaseUrl;
  const currency = Amounts.currencyOf(peerPullInc.amount);

  const sel = peerPullInc.coinSel;
  checkDbInvariant(
    !!sel,
    `no coin selected for peer pull deposit ${peerPullInc.pursePub}`,
  );

  const statusResp = await walletExchangeClient(
    exchangeBaseUrl,
    ctx.wex,
  ).getPurseStatusAtMerge(peerPullInc.pursePub);
  switch (statusResp.case) {
    case "ok":
      break;
    case HttpStatusCode.Gone:
      await ctx.purseGoneTransaction(
        peerPullInc.status,
        new Set([brokenCoinPub]),
      );
      return TaskRunResult.finished();
    case HttpStatusCode.NotFound:
      await ctx.failTransaction(
        peerPullInc.status,
        statusResp.detail,
        new Set([brokenCoinPub]),
      );
      return TaskRunResult.finished();
    default:
      assertUnreachable(statusResp);
  }
  await requireValidExchangePurseStatus(
    ctx.wex,
    exchangeBaseUrl,
    statusResp.body,
  );

  const instructedAmount = getPeerPullDebitRemainder(
    peerPullInc.amount,
    statusResp.body.balance,
  );
  if (isPurseDeposited(statusResp.body) || !instructedAmount) {
    await ctx.purseGoneTransaction(
      peerPullInc.status,
      new Set([brokenCoinPub]),
    );
    return TaskRunResult.finished();
  }

  const coinDetails = await queryCoinInfosForSelection(ctx.wex, sel);
  const { repair, recover } = partitionPeerPullDebitRepair(
    sel,
    coinDetails.map((x) => x.feeDeposit),
    brokenCoinPub,
    instructedAmount,
  );

  const coinSelRes = await selectPeerCoins(ctx.wex, {
    instructedAmount,
    repair,
    restrictScope: {
      type: ScopeType.Exchange,
      currency,
      url: exchangeBaseUrl,
    },
  });

  switch (coinSelRes.type) {
    case "failure": {
      // Recover every unsubmitted, non-broken allocation.  Once those
      // refreshes produce fresh coins, the normal pending path re-selects
      // against a newly authenticated remainder.
      const recoverAfterFailure = [
        ...recover,
        ...repair.map((x) => ({
          coinPub: x.coinPub,
          amount: Amounts.stringify(x.contribution),
        })),
      ];
      await ctx.wex.runWalletDbTx(async (tx) => {
        const [rec, h] = await ctx.getRecordHandle(tx);
        if (
          rec?.status !== PeerPullDebitRecordStatus.PendingDeposit ||
          !rec.coinSel
        ) {
          return;
        }
        const acceptedCount = getPeerPullDebitDepositedCoinCount(rec.coinSel);
        if (recoverAfterFailure.length > 0) {
          await createRefreshGroup(
            ctx.wex,
            tx,
            currency,
            recoverAfterFailure,
            RefreshReason.AbortPeerPullDebit,
            ctx.transactionId,
          );
        }
        if (acceptedCount === 0) {
          rec.coinSel = undefined;
        } else {
          rec.coinSel.totalCost = Amounts.stringify(
            await getStoredPeerPullDebitSelectionCostInTx(
              ctx.wex,
              tx,
              rec.coinSel,
              acceptedCount,
              currency,
            ),
          );
          rec.coinSel.coinPubs = rec.coinSel.coinPubs.slice(0, acceptedCount);
          rec.coinSel.contributions = rec.coinSel.contributions.slice(
            0,
            acceptedCount,
          );
          rec.coinSel.confirmedPurseBalance = statusResp.body.balance;
        }
        await h.update(rec, "purse-conflict-await-refresh");
      });
      return TaskRunResult.backoff();
    }
    case "success":
      break;
    default:
      assertUnreachable(coinSelRes);
  }

  const replacementCost = await getTotalPeerPaymentCost(
    ctx.wex,
    coinSelRes.result.coins,
  );

  await ctx.wex.runWalletDbTx(async (tx) => {
    const [rec, h] = await ctx.getRecordHandle(tx);
    if (!rec) {
      return;
    }
    switch (rec.status) {
      case PeerPullDebitRecordStatus.PendingDeposit:
      case PeerPullDebitRecordStatus.SuspendedDeposit: {
        if (!rec.coinSel) {
          return;
        }
        const acceptedCount = getPeerPullDebitDepositedCoinCount(rec.coinSel);
        const oldSelection = rec.coinSel;
        const acceptedCost = await getStoredPeerPullDebitSelectionCostInTx(
          ctx.wex,
          tx,
          oldSelection,
          acceptedCount,
          currency,
        );
        if (recover.length > 0) {
          await createRefreshGroup(
            ctx.wex,
            tx,
            currency,
            recover,
            RefreshReason.AbortPeerPullDebit,
            ctx.transactionId,
          );
        }
        const replacement = coinSelRes.result;
        rec.coinSel = {
          coinPubs: [
            ...oldSelection.coinPubs.slice(0, acceptedCount),
            ...replacement.coins.map((x) => x.coinPub),
          ],
          contributions: [
            ...oldSelection.contributions.slice(0, acceptedCount),
            ...replacement.coins.map((x) => x.contribution),
          ],
          totalCost: Amounts.stringify(
            Amounts.add(acceptedCost, replacementCost).amount,
          ),
          depositedCoinCount: acceptedCount,
          confirmedPurseBalance: statusResp.body.balance,
        };
        // The carried-over coins were spent when they were first selected,
        // the ones that replace the double-spent coin still have to be.
        const added = coinsAddedByRepair(repair, replacement.coins);
        await spendCoins(ctx.wex, tx, {
          transactionId: ctx.transactionId,
          coinPubs: added.map((x) => x.coinPub),
          contributions: added.map((x) => Amounts.parseOrThrow(x.contribution)),
          refreshReason: RefreshReason.PayPeerPull,
        });
        await h.update(rec, "purse-conflict-repair");
        break;
      }
      default:
        break;
    }
  });
  return TaskRunResult.progress();
}

async function processPeerPullDebitDialogProposed(
  wex: WalletExecutionContext,
  pullIni: WalletPeerPullDebit,
): Promise<TaskRunResult> {
  const ctx = new PeerPullDebitTransactionContext(wex, pullIni.peerPullDebitId);
  const exchangeClient = walletExchangeClient(pullIni.exchangeBaseUrl, wex);
  const resp = await exchangeClient.getPurseStatusAtDeposit(
    pullIni.pursePub,
    true,
  );

  switch (resp.case) {
    case "ok":
      break;
    case HttpStatusCode.Gone:
      // The purse is gone: the invoice lapsed, the payee withdrew it, or
      // another wallet paid it.
      await ctx.purseGoneTransaction(PeerPullDebitRecordStatus.DialogProposed);
      return TaskRunResult.finished();
    case HttpStatusCode.NotFound:
      await ctx.failTransaction(pullIni.status, resp.detail);
      return TaskRunResult.finished();
    default:
      assertUnreachable(resp);
  }

  await requireValidExchangePurseStatus(
    wex,
    pullIni.exchangeBaseUrl,
    resp.body,
  );

  if (
    isPurseDeposited(resp.body) ||
    !getPeerPullDebitRemainder(pullIni.amount, resp.body.balance)
  ) {
    logger.info("purse completed by another wallet");
    await ctx.wex.runWalletDbTx(async (tx) => {
      const [rec, h] = await ctx.getRecordHandle(tx);
      switch (rec?.status) {
        case PeerPullDebitRecordStatus.DialogProposed:
          rec.status = PeerPullDebitRecordStatus.Aborted;
          break;
        default:
          return;
      }
      await h.update(rec, "dialog-aborted");
    });
    return TaskRunResult.finished();
  }

  return TaskRunResult.longpollReturnedPending();
}

async function processPeerPullDebitPendingDeposit(
  wex: WalletExecutionContext,
  peerPullInc: WalletPeerPullDebit,
): Promise<TaskRunResult> {
  const ctx = new PeerPullDebitTransactionContext(
    wex,
    peerPullInc.peerPullDebitId,
  );
  const { pursePub, coinSel } = peerPullInc;

  const exchangeBaseUrl = peerPullInc.exchangeBaseUrl;

  if (coinSel) {
    const depositedCount = getPeerPullDebitDepositedCoinCount(coinSel);
    if (
      depositedCount > 0 &&
      depositedCount === coinSel.coinPubs.length &&
      coinSel.confirmedPurseBalance &&
      !getPeerPullDebitRemainder(
        peerPullInc.amount,
        coinSel.confirmedPurseBalance,
      )
    ) {
      await wex.runWalletDbTx(async (tx) => {
        const [rec, h] = await ctx.getRecordHandle(tx);
        if (rec?.status !== PeerPullDebitRecordStatus.PendingDeposit) {
          return;
        }
        rec.status = PeerPullDebitRecordStatus.Done;
        await h.update(rec, "deposit-replay-confirmed");
      });
      return TaskRunResult.finished();
    }
  }

  const contractTerms = await wex.runWalletDbTx(async (tx) =>
    tx.getContractTerms(peerPullInc.contractTermsHash),
  );
  checkDbInvariant(
    !!contractTerms,
    `no contract terms for peer pull debit ${peerPullInc.peerPullDebitId}`,
  );

  if (
    isPurseGoneByExpiration(contractTerms.contractTermsRaw.purse_expiration)
  ) {
    const exchangeClient = walletExchangeClient(exchangeBaseUrl, wex);
    const statusResp = await exchangeClient.getPurseStatusAtMerge(
      pursePub,
      true,
    );
    switch (statusResp.case) {
      case "ok":
        await requireValidExchangePurseStatus(
          wex,
          exchangeBaseUrl,
          statusResp.body,
        );
        if (isPurseMerged(statusResp.body)) {
          await ctx.purseGoneTransaction(peerPullInc.status);
          return TaskRunResult.finished();
        }
        // The local clock reached the deadline first.  Reconcile again after
        // the exchange has either expired or merged the purse, but do not
        // select or submit any more coins.
        return TaskRunResult.longpollReturnedPending();
      case HttpStatusCode.Gone:
        await ctx.purseGoneTransaction(peerPullInc.status);
        return TaskRunResult.finished();
      case HttpStatusCode.NotFound:
        await ctx.failTransaction(peerPullInc.status, statusResp.detail);
        return TaskRunResult.finished();
      default:
        assertUnreachable(statusResp);
    }
  }

  // This can happen when there was a prospective coin selection, or after a
  // conflict where the already-confirmed prefix was retained and every
  // unsubmitted coin was sent to recovery.
  if (
    coinSel == null ||
    getPeerPullDebitDepositedCoinCount(coinSel) === coinSel.coinPubs.length
  ) {
    const exchangeClient = walletExchangeClient(exchangeBaseUrl, wex);
    const statusResp = await exchangeClient.getPurseStatusAtMerge(pursePub);
    switch (statusResp.case) {
      case "ok":
        break;
      case HttpStatusCode.Gone:
        await ctx.purseGoneTransaction(peerPullInc.status);
        return TaskRunResult.finished();
      case HttpStatusCode.NotFound:
        await ctx.failTransaction(peerPullInc.status, statusResp.detail);
        return TaskRunResult.finished();
      default:
        assertUnreachable(statusResp);
    }
    await requireValidExchangePurseStatus(
      wex,
      exchangeBaseUrl,
      statusResp.body,
    );
    const instructedAmount = getPeerPullDebitRemainder(
      peerPullInc.amount,
      statusResp.body.balance,
    );
    if (isPurseDeposited(statusResp.body) || !instructedAmount) {
      await ctx.purseGoneTransaction(peerPullInc.status);
      return TaskRunResult.finished();
    }
    const currency = instructedAmount.currency;

    const coinSelRes = await selectPeerCoins(wex, {
      instructedAmount,
      restrictScope: {
        type: ScopeType.Exchange,
        currency,
        url: exchangeBaseUrl,
      },
    });
    if (logger.shouldLogTrace()) {
      logger.trace(`selected p2p coins (pull): ${j2s(coinSelRes)}`);
    }

    let coins: SelectedProspectiveCoin[] | undefined = undefined;

    switch (coinSelRes.type) {
      case "failure":
        throw TalerError.fromDetail(
          TalerErrorCode.WALLET_PEER_PULL_PAYMENT_INSUFFICIENT_BALANCE,
          {
            insufficientBalanceDetails: coinSelRes.insufficientBalanceDetails,
          },
        );
      case "success":
        coins = coinSelRes.result.coins;
        break;
      default:
        assertUnreachable(coinSelRes);
    }

    const totalAmount = await getTotalPeerPaymentCost(wex, coins);
    return await wex.runWalletDbTx(async (tx) => {
      const [rec, h] = await ctx.getRecordHandle(tx);
      if (!rec) {
        return TaskRunResult.finished();
      }
      if (rec.status !== PeerPullDebitRecordStatus.PendingDeposit) {
        return TaskRunResult.backoff();
      }
      if (
        isPurseGoneByExpiration(contractTerms.contractTermsRaw.purse_expiration)
      ) {
        return TaskRunResult.progress();
      }
      const acceptedCount = rec.coinSel
        ? getPeerPullDebitDepositedCoinCount(rec.coinSel)
        : 0;
      if (
        (coinSel == null && rec.coinSel != null) ||
        (coinSel != null &&
          (!rec.coinSel ||
            acceptedCount !== rec.coinSel.coinPubs.length ||
            acceptedCount !== coinSel.coinPubs.length))
      ) {
        return TaskRunResult.backoff();
      }
      await spendCoins(wex, tx, {
        transactionId: ctx.transactionId,
        coinPubs: coinSelRes.result.coins.map((x) => x.coinPub),
        contributions: coinSelRes.result.coins.map((x) =>
          Amounts.parseOrThrow(x.contribution),
        ),
        refreshReason: RefreshReason.PayPeerPull,
      });
      const acceptedCoinPubs = rec.coinSel?.coinPubs ?? [];
      const acceptedContributions = rec.coinSel?.contributions ?? [];
      const acceptedCost = rec.coinSel?.totalCost
        ? Amounts.parseOrThrow(rec.coinSel.totalCost)
        : Amounts.zeroOfCurrency(currency);
      rec.coinSel = {
        coinPubs: [
          ...acceptedCoinPubs,
          ...coinSelRes.result.coins.map((x) => x.coinPub),
        ],
        contributions: [
          ...acceptedContributions,
          ...coinSelRes.result.coins.map((x) => x.contribution),
        ],
        totalCost: Amounts.stringify(
          Amounts.add(acceptedCost, totalAmount).amount,
        ),
        depositedCoinCount: acceptedCount,
        confirmedPurseBalance: statusResp.body.balance,
      };
      await h.update(rec, "select-coins");
      return TaskRunResult.progress();
    });
  }
  const exchangeClient = walletExchangeClient(peerPullInc.exchangeBaseUrl, wex);

  // FIXME: We could skip batches that we've already submitted.

  const coins = await queryCoinInfosForSelection(wex, coinSel);

  const maxBatchSize = 64;
  const depositedCoinCount = getPeerPullDebitDepositedCoinCount(coinSel);

  for (let i = depositedCoinCount; i < coins.length; i += maxBatchSize) {
    if (
      isPurseGoneByExpiration(contractTerms.contractTermsRaw.purse_expiration)
    ) {
      return TaskRunResult.progress();
    }
    const batchSize = Math.min(maxBatchSize, coins.length - i);

    wex.oc.observe({
      type: ObservabilityEventType.Message,
      contents: `Depositing batch at ${i}/${coins.length} of size ${batchSize}`,
    });

    const batchCoins = coins.slice(i, i + batchSize);
    const depositSigsResp = await wex.cryptoApi.signPurseDeposits({
      exchangeBaseUrl: peerPullInc.exchangeBaseUrl,
      pursePub: peerPullInc.pursePub,
      coins: batchCoins,
    });

    const depositPayload: ExchangePurseDeposits = {
      deposits: depositSigsResp.deposits,
    };

    if (logger.shouldLogTrace()) {
      logger.trace(`purse deposit payload: ${j2s(depositPayload)}`);
    }
    await requireExchangeCoinUseConfirmedOrThrow(wex, exchangeBaseUrl);
    const resp = await exchangeClient.depositIntoPurse(
      pursePub,
      depositPayload,
    );
    switch (resp.case) {
      case "ok": {
        await requireValidExchangePurseDepositConfirmation(wex, {
          exchangeBaseUrl,
          pursePub,
          contractTermsHash: peerPullInc.contractTermsHash,
          purseValueAfterFees: peerPullInc.amount,
          purseExpiration: contractTerms.contractTermsRaw.purse_expiration,
          response: resp.body,
        });
        const purseComplete =
          getPeerPullDebitRemainder(
            peerPullInc.amount,
            resp.body.total_deposited,
          ) === undefined;
        const confirmationStored = await wex.runWalletDbTx(async (tx) => {
          const [rec, h] = await ctx.getRecordHandle(tx);
          if (
            rec?.status !== PeerPullDebitRecordStatus.PendingDeposit ||
            !rec.coinSel
          ) {
            return false;
          }
          const currentCount = getPeerPullDebitDepositedCoinCount(rec.coinSel);
          if (currentCount !== i) {
            return false;
          }
          markPeerPullDebitCoinsDeposited(
            rec.coinSel,
            i,
            batchSize,
            resp.body.total_deposited,
          );
          if (purseComplete) {
            const acceptedCount = i + batchSize;
            const unsubmitted: CoinRefreshRequest[] = [];
            for (
              let coinIndex = acceptedCount;
              coinIndex < rec.coinSel.coinPubs.length;
              coinIndex++
            ) {
              unsubmitted.push({
                coinPub: rec.coinSel.coinPubs[coinIndex],
                amount: rec.coinSel.contributions[coinIndex],
              });
            }
            if (unsubmitted.length > 0) {
              await createRefreshGroup(
                wex,
                tx,
                Amounts.currencyOf(peerPullInc.amount),
                unsubmitted,
                RefreshReason.AbortPeerPullDebit,
                ctx.transactionId,
              );
            }
            rec.coinSel.totalCost = Amounts.stringify(
              await getStoredPeerPullDebitSelectionCostInTx(
                wex,
                tx,
                rec.coinSel,
                acceptedCount,
                Amounts.currencyOf(peerPullInc.amount),
              ),
            );
            rec.coinSel.coinPubs = rec.coinSel.coinPubs.slice(0, acceptedCount);
            rec.coinSel.contributions = rec.coinSel.contributions.slice(
              0,
              acceptedCount,
            );
            rec.status = PeerPullDebitRecordStatus.Done;
          }
          await h.update(rec, "deposit-confirmed");
          return true;
        });
        if (!confirmationStored) {
          return TaskRunResult.progress();
        }
        if (purseComplete) {
          return TaskRunResult.finished();
        }
        continue;
      }
      case HttpStatusCode.Gone: {
        await ctx.purseGoneTransaction(peerPullInc.status);
        return TaskRunResult.finished();
      }
      case HttpStatusCode.Conflict:
        return handlePurseCreationConflict(ctx, peerPullInc, resp.body);
      case HttpStatusCode.Forbidden:
      case HttpStatusCode.NotFound:
        await ctx.failTransaction(peerPullInc.status, resp.detail);
        return TaskRunResult.finished();
      default:
        assertUnreachable(resp);
    }
  }
  await ctx.failTransaction(peerPullInc.status, {
    code: TalerErrorCode.WALLET_TRANSACTION_PROTOCOL_VIOLATION,
    hint: "exchange accepted every selected coin but reported an incomplete purse",
  });
  return TaskRunResult.finished();
}

async function processPeerPullDebitAbortingRefresh(
  wex: WalletExecutionContext,
  peerPullInc: WalletPeerPullDebit,
): Promise<TaskRunResult> {
  const peerPullDebitId = peerPullInc.peerPullDebitId;
  const abortRefreshGroupId = peerPullInc.abortRefreshGroupId;
  checkLogicInvariant(!!abortRefreshGroupId);
  const ctx = new PeerPullDebitTransactionContext(wex, peerPullDebitId);
  let terminal = false;
  await wex.runWalletDbTx(async (tx) => {
    const refreshGroup = await tx.getRefreshGroup(abortRefreshGroupId);
    const [rec, h] = await ctx.getRecordHandle(tx);
    if (!rec) {
      return;
    }
    if (refreshGroup == null) {
      // Maybe it got manually deleted? Means that we should
      // just go into failed.
      logger.warn("no aborting refresh group found for deposit group");
      rec.status = PeerPullDebitRecordStatus.Failed;
      terminal = true;
    } else {
      switch (refreshGroup.operationStatus) {
        case RefreshOperationStatus.Finished: {
          const acceptedCount = await retainPeerPullDebitAcceptedSelectionInTx(
            wex,
            tx,
            rec,
          );
          if (acceptedCount > 0) {
            rec.status = PeerPullDebitRecordStatus.Failed;
            rec.failReason = makePeerPullDebitPartialDepositError();
          } else {
            rec.status = PeerPullDebitRecordStatus.Aborted;
          }
          terminal = true;
          break;
        }
        case RefreshOperationStatus.Failed: {
          rec.status = PeerPullDebitRecordStatus.Failed;
          terminal = true;
          break;
        }
        default:
          return;
      }
    }
    await h.update(rec, "aborting-refresh-failed");
  });
  return terminal ? TaskRunResult.finished() : TaskRunResult.backoff();
}

export async function processPeerPullDebit(
  wex: WalletExecutionContext,
  peerPullDebitId: string,
): Promise<TaskRunResult> {
  const processInfo = await wex.runWalletDbTx(async (tx) => {
    const peerPullInc = await tx.getPeerPullDebit(peerPullDebitId);
    if (!peerPullInc) {
      return undefined;
    }
    const contractTerms = await tx.getContractTerms(
      peerPullInc.contractTermsHash,
    );
    return { peerPullInc, contractTerms };
  });
  const peerPullInc = processInfo?.peerPullInc;
  if (!peerPullInc) {
    throw makeTransactionNotFoundError(
      constructTransactionIdentifier({
        tag: TransactionType.PeerPullDebit,
        peerPullDebitId,
      }),
    );
  }
  checkDbInvariant(
    !!processInfo.contractTerms,
    `no contract terms for peer pull debit ${peerPullDebitId}`,
  );
  const purseExpiration =
    processInfo.contractTerms.contractTermsRaw.purse_expiration;

  switch (peerPullInc.status) {
    case PeerPullDebitRecordStatus.Done:
    case PeerPullDebitRecordStatus.Aborted:
    case PeerPullDebitRecordStatus.Failed:
    case PeerPullDebitRecordStatus.Expired:
    case PeerPullDebitRecordStatus.SuspendedAbortingRefresh:
    case PeerPullDebitRecordStatus.SuspendedDeposit:
      return TaskRunResult.finished();
    default:
      break;
  }

  if (
    peerPullInc.status === PeerPullDebitRecordStatus.DialogProposed &&
    isPurseGoneByExpiration(purseExpiration)
  ) {
    const ctx = new PeerPullDebitTransactionContext(wex, peerPullDebitId);
    await ctx.purseGoneTransaction(peerPullInc.status);
    return TaskRunResult.finished();
  }

  if (!wex.ws.networkAvailable) {
    switch (peerPullInc.status) {
      case PeerPullDebitRecordStatus.DialogProposed:
      case PeerPullDebitRecordStatus.PendingDeposit:
        if (!isPurseGoneByExpiration(purseExpiration)) {
          return TaskRunResult.runAgainAt(
            AbsoluteTime.fromProtocolTimestamp(purseExpiration),
          );
        }
        break;
      default:
        break;
    }
    return TaskRunResult.networkRequired();
  }

  switch (peerPullInc.status) {
    case PeerPullDebitRecordStatus.DialogProposed:
      return processPeerPullDebitDialogProposed(wex, peerPullInc);
    case PeerPullDebitRecordStatus.PendingDeposit:
      return processPeerPullDebitPendingDeposit(wex, peerPullInc);
    case PeerPullDebitRecordStatus.AbortingRefresh:
      return processPeerPullDebitAbortingRefresh(wex, peerPullInc);
    default:
      assertUnreachable(peerPullInc.status);
  }
}

export async function confirmPeerPullDebit(
  wex: WalletExecutionContext,
  req: ConfirmPeerPullDebitRequest,
): Promise<AcceptPeerPullPaymentResponse> {
  const parsed = parseTransactionIdentifier(req.transactionId);
  if (!parsed || parsed.tag !== TransactionType.PeerPullDebit) {
    throw makeInvalidTransactionIdError(
      req.transactionId,
      TransactionType.PeerPullDebit,
    );
  }

  const peerPullInc = await wex.runWalletDbTx(async (tx) =>
    tx.getPeerPullDebit(parsed.peerPullDebitId),
  );

  if (peerPullInc == null) {
    throw makeTransactionNotFoundError(req.transactionId);
  }

  const ctx = new PeerPullDebitTransactionContext(wex, parsed.peerPullDebitId);

  // Confirmation is the transition out of the proposal dialog.  Once that
  // transition happened, processing is owned by the transaction task and a
  // repeated confirmation must not re-evaluate the purse.  In particular, a
  // fully deposited purse is expected for a transaction that is already done
  // and must not turn that transaction into a purse-gone failure.
  if (peerPullInc.status !== PeerPullDebitRecordStatus.DialogProposed) {
    return { transactionId: ctx.transactionId };
  }

  const contractTerms = await wex.runWalletDbTx(async (tx) =>
    tx.getContractTerms(peerPullInc.contractTermsHash),
  );
  checkDbInvariant(
    !!contractTerms,
    `no contract terms for peer pull debit ${peerPullInc.peerPullDebitId}`,
  );
  const purseExpiration = contractTerms.contractTermsRaw.purse_expiration;
  if (isPurseGoneByExpiration(purseExpiration)) {
    await ctx.purseGoneTransaction(peerPullInc.status);
    return { transactionId: ctx.transactionId };
  }

  const exchangeBaseUrl = peerPullInc.exchangeBaseUrl;

  const statusResp = await walletExchangeClient(
    exchangeBaseUrl,
    wex,
  ).getPurseStatusAtMerge(peerPullInc.pursePub);
  switch (statusResp.case) {
    case "ok":
      break;
    case HttpStatusCode.Gone:
      await ctx.purseGoneTransaction(peerPullInc.status);
      return { transactionId: ctx.transactionId };
    case HttpStatusCode.NotFound:
      await ctx.failTransaction(peerPullInc.status, statusResp.detail);
      return { transactionId: ctx.transactionId };
    default:
      assertUnreachable(statusResp);
  }
  await requireValidExchangePurseStatus(wex, exchangeBaseUrl, statusResp.body);

  const instructedAmount = getPeerPullDebitRemainder(
    peerPullInc.amount,
    statusResp.body.balance,
  );
  if (isPurseDeposited(statusResp.body) || !instructedAmount) {
    await ctx.purseGoneTransaction(peerPullInc.status);
    return { transactionId: ctx.transactionId };
  }
  const currency = instructedAmount.currency;

  const coinSelRes = await selectPeerCoins(wex, {
    instructedAmount,
    restrictScope: {
      type: ScopeType.Exchange,
      currency,
      url: exchangeBaseUrl,
    },
  });
  if (logger.shouldLogTrace()) {
    logger.trace(`selected p2p coins (pull): ${j2s(coinSelRes)}`);
  }

  let coins: SelectedProspectiveCoin[] | undefined = undefined;

  switch (coinSelRes.type) {
    case "failure":
      throw TalerError.fromDetail(
        TalerErrorCode.WALLET_PEER_PULL_PAYMENT_INSUFFICIENT_BALANCE,
        {
          insufficientBalanceDetails: coinSelRes.insufficientBalanceDetails,
        },
      );
    case "success":
      coins = coinSelRes.result.coins;
      break;
    default:
      assertUnreachable(coinSelRes);
  }

  const totalAmount = await getTotalPeerPaymentCost(wex, coins);

  await wex.runWalletDbTx(async (tx) => {
    const [rec, h] = await ctx.getRecordHandle(tx);
    if (!rec) {
      return;
    }
    if (rec.status !== PeerPullDebitRecordStatus.DialogProposed) {
      return;
    }
    if (isPurseGoneByExpiration(purseExpiration)) {
      rec.status = PeerPullDebitRecordStatus.Expired;
      await h.update(rec, "confirm-expired");
      return;
    }
    if (coinSelRes.type == "success") {
      await spendCoins(wex, tx, {
        transactionId: ctx.transactionId,
        coinPubs: coinSelRes.result.coins.map((x) => x.coinPub),
        contributions: coinSelRes.result.coins.map((x) =>
          Amounts.parseOrThrow(x.contribution),
        ),
        refreshReason: RefreshReason.PayPeerPull,
      });
      rec.coinSel = {
        coinPubs: coinSelRes.result.coins.map((x) => x.coinPub),
        contributions: coinSelRes.result.coins.map((x) => x.contribution),
        totalCost: Amounts.stringify(totalAmount),
        depositedCoinCount: 0,
        confirmedPurseBalance: statusResp.body.balance,
      };
    }
    rec.status = PeerPullDebitRecordStatus.PendingDeposit;
    await h.update(rec, "confirm");
  });

  await wex.taskScheduler.resetTask(ctx.taskId);

  return {
    transactionId: ctx.transactionId,
  };
}

/**
 * Look up information about an incoming peer pull payment.
 * Store the results in the wallet DB.
 */
export async function preparePeerPullDebit(
  wex: WalletExecutionContext,
  req: PreparePeerPullDebitRequest,
): Promise<PreparePeerPullDebitResponse> {
  return runWithMaybeProgressContext(
    wex,
    "preparePeerPullDebit",
    req.progressToken,
    () => internalPreparePeerPullDebit(wex, req),
  );
}

async function internalPreparePeerPullDebit(
  wex: WalletExecutionContext,
  req: PreparePeerPullDebitRequest,
): Promise<PreparePeerPullDebitResponse> {
  if (!req.talerUri && !req.transactionId) {
    throw TalerError.fromDetail(
      TalerErrorCode.WALLET_CORE_API_BAD_REQUEST,
      { parameter: "talerUri" },
      "either talerUri or transactionId must be specified",
    );
  }

  let uri: TalerPayPullUri | undefined;
  if (req.talerUri) {
    uri = Result.orUndefined(
      TalerUris.parseRestricted(req.talerUri, TalerUriAction.PayPull),
    );
    if (!uri) {
      throw TalerError.fromDetail(
        TalerErrorCode.WALLET_TALER_URI_MALFORMED,
        { talerUri: req.talerUri, expectedAction: TalerUriAction.PayPull },
        "expected a taler://pay-pull URI",
      );
    }
  }

  let parsedTxId: string | undefined;
  if (req.transactionId) {
    const parsedRes = parseTransactionIdentifier(req.transactionId);
    if (!parsedRes || parsedRes.tag !== TransactionType.PeerPullDebit) {
      throw makeInvalidTransactionIdError(
        req.transactionId,
        TransactionType.PeerPullDebit,
      );
    }
    parsedTxId = parsedRes.peerPullDebitId;
  }

  const existing = await wex.runWalletDbTx(async (tx) => {
    let peerPullDebitRecord: WalletPeerPullDebit | undefined;
    if (uri) {
      peerPullDebitRecord = await tx.getPeerPullDebitByExchangeAndContractPriv(
        uri.exchangeBaseUrl,
        uri.contractPriv,
      );
    } else if (parsedTxId) {
      peerPullDebitRecord = await tx.getPeerPullDebit(parsedTxId);
    }
    if (!peerPullDebitRecord) {
      return;
    }
    const contractTerms = await tx.getContractTerms(
      peerPullDebitRecord.contractTermsHash,
    );
    if (!contractTerms) {
      return;
    }
    const currency = Amounts.currencyOf(peerPullDebitRecord.amount);
    const scopeInfo = await getExchangeScopeInfo(
      tx,
      peerPullDebitRecord.exchangeBaseUrl,
      currency,
    );
    return {
      peerPullDebitRecord,
      contractTerms,
      scopeInfo,
      exchangeBaseUrl: peerPullDebitRecord.exchangeBaseUrl,
      rec: peerPullDebitRecord,
    };
  });

  if (existing) {
    return {
      amount: existing.peerPullDebitRecord.amount,
      amountRaw: existing.peerPullDebitRecord.amount,
      amountEffective: existing.peerPullDebitRecord.totalCostEstimated,
      contractTerms: existing.contractTerms.contractTermsRaw,
      scopeInfo: existing.scopeInfo,
      exchangeBaseUrl: existing.exchangeBaseUrl,
      txState: computePeerPullDebitTransactionState(existing.rec),
      transactionId: constructTransactionIdentifier({
        tag: TransactionType.PeerPullDebit,
        peerPullDebitId: existing.peerPullDebitRecord.peerPullDebitId,
      }),
    };
  }

  if (!uri) {
    throw makeTransactionNotFoundError(req.transactionId!);
  }

  const exchangeBaseUrl = uri.exchangeBaseUrl;
  const contractPriv = uri.contractPriv;
  const contractPub = encodeCrock(eddsaGetPublic(decodeCrock(contractPriv)));
  const exchangeClient = walletExchangeClient(exchangeBaseUrl, wex);

  // Retried under a progress context: a terminal outcome (NotFound) comes back
  // as a result case rather than an exception, so only transient failures are
  // retried — the caller still handles NotFound below.
  const contractResp = await runWithProgressRetries(wex, () =>
    exchangeClient.getContract(contractPub),
  );
  switch (contractResp.case) {
    case "ok":
      break;
    case HttpStatusCode.NotFound:
      throw TalerError.fromDetail(
        TalerErrorCode.WALLET_PEER_CONTRACT_NOT_FOUND,
        {},
        "the exchange does not know this peer-to-peer contract",
      );
    default:
      assertUnreachable(contractResp);
  }
  const pursePub = contractResp.body.purse_pub;

  const dec = await wex.cryptoApi.decryptContractForDeposit({
    ciphertext: contractResp.body.econtract,
    contractPriv: contractPriv,
    pursePub: pursePub,
  });

  let contractTerms: PeerContractTerms;

  // Decoded before asking for the purse status, because the purse expiration
  // in here is what tells a lapsed purse from a deleted one.
  if (dec.contractTerms) {
    contractTerms = codecForPeerContractTerms().decode(dec.contractTerms);
    // FIXME: Check that the purseStatus balance matches contract terms amount
  } else {
    // FIXME: In this case, where do we get the purse expiration from?!
    // https://bugs.gnunet.org/view.php?id=7706
    throw TalerError.fromDetail(
      TalerErrorCode.WALLET_CONTRACT_TERMS_UNSUPPORTED,
      {},
      "invoices without contract terms are not supported yet",
    );
  }

  if (isPurseGoneByExpiration(contractTerms.purse_expiration)) {
    throw TalerError.fromDetail(
      TalerErrorCode.WALLET_PEER_PULL_DEBIT_PURSE_GONE,
      { purseExpired: true },
      "this invoice expired",
    );
  }

  const resp = await runWithProgressRetries(wex, () =>
    exchangeClient.getPurseStatusAtMerge(pursePub),
  );
  switch (resp.case) {
    case "ok":
      break;
    case HttpStatusCode.Gone: {
      const purseExpired = isPurseGoneByExpiration(
        contractTerms.purse_expiration,
      );
      throw TalerError.fromDetail(
        TalerErrorCode.WALLET_PEER_PULL_DEBIT_PURSE_GONE,
        { purseExpired },
        purseExpired
          ? "this invoice expired"
          : "this invoice was already paid or withdrawn by the payee",
      );
    }
    case HttpStatusCode.NotFound:
      throw TalerError.fromDetail(
        TalerErrorCode.WALLET_PEER_CONTRACT_NOT_FOUND,
        {},
        "the exchange does not know the purse of this invoice",
      );
    default:
      assertUnreachable(resp);
  }

  await requireValidExchangePurseStatus(wex, exchangeBaseUrl, resp.body);

  const instructedAmount = getPeerPullDebitRemainder(
    contractTerms.amount,
    resp.body.balance,
  );
  if (isPurseDeposited(resp.body) || !instructedAmount) {
    logger.info("purse completed by another wallet");
    throw TalerError.fromDetail(
      TalerErrorCode.WALLET_PEER_PULL_DEBIT_ALREADY_PAID,
      {},
      "this invoice has already been paid",
    );
  }

  const peerPullDebitId = encodeCrock(getRandomBytes(32));

  const contractTermsHash = ContractTermsUtil.hashContractTerms(contractTerms);

  // FIXME: Why don't we compute the totalCost here?!

  const currency = Amounts.currencyOf(instructedAmount);

  const coinSelRes = await selectPeerCoins(wex, {
    instructedAmount,
    restrictScope: {
      type: ScopeType.Exchange,
      currency,
      url: exchangeBaseUrl,
    },
  });
  if (logger.shouldLogTrace()) {
    logger.trace(`selected p2p coins (pull): ${j2s(coinSelRes)}`);
  }

  let coins: SelectedProspectiveCoin[] | undefined = undefined;

  switch (coinSelRes.type) {
    case "failure":
      throw TalerError.fromDetail(
        TalerErrorCode.WALLET_PEER_PULL_PAYMENT_INSUFFICIENT_BALANCE,
        {
          insufficientBalanceDetails: coinSelRes.insufficientBalanceDetails,
        },
      );
    case "success":
      coins = coinSelRes.result.coins;
      break;
    default:
      assertUnreachable(coinSelRes);
  }

  const totalAmount = await getTotalPeerPaymentCost(wex, coins);

  const ctx = new PeerPullDebitTransactionContext(wex, peerPullDebitId);

  const ret = await wex.runWalletDbTx(async (tx) => {
    await tx.upsertContractTerms({
      h: contractTermsHash,
      contractTermsRaw: contractTerms,
    });
    const [rec, h] = await ctx.getRecordHandle(tx);
    if (rec) {
      throw Error("peer-pull-debit record already exists");
    }
    const newRec: WalletPeerPullDebit = {
      peerPullDebitId,
      contractPriv: contractPriv,
      exchangeBaseUrl: exchangeBaseUrl,
      pursePub: pursePub,
      timestampCreated: timestampPreciseToDb(TalerPreciseTimestamp.now()),
      contractTermsHash,
      amount: contractTerms.amount,
      status: PeerPullDebitRecordStatus.DialogProposed,
      totalCostEstimated: Amounts.stringify(totalAmount),
    };
    // Only the request is presented to the user, nothing is spent until
    // the payment is confirmed.
    await h.update(newRec, "prepare", BalanceEffect.None);
    return {
      newRec,
      scopeInfo: await getExchangeScopeInfo(tx, exchangeBaseUrl, currency),
    };
  });

  wex.taskScheduler.startShepherdTask(ctx.taskId);

  return {
    amount: contractTerms.amount,
    amountEffective: Amounts.stringify(totalAmount),
    amountRaw: contractTerms.amount,
    contractTerms: contractTerms,
    scopeInfo: ret.scopeInfo,
    txState: computePeerPullDebitTransactionState(ret.newRec),
    exchangeBaseUrl,
    transactionId: ctx.transactionId,
  };
}

export function computePeerPullDebitTransactionState(
  pullDebitRecord: WalletPeerPullDebit,
): TransactionState {
  switch (pullDebitRecord.status) {
    case PeerPullDebitRecordStatus.DialogProposed:
      return {
        major: TransactionMajorState.Dialog,
        minor: TransactionMinorState.Proposed,
      };
    case PeerPullDebitRecordStatus.PendingDeposit:
      return {
        major: TransactionMajorState.Pending,
        minor: TransactionMinorState.Deposit,
        working: true,
      };
    case PeerPullDebitRecordStatus.Done:
      return {
        major: TransactionMajorState.Done,
      };
    case PeerPullDebitRecordStatus.SuspendedDeposit:
      return {
        major: TransactionMajorState.Suspended,
        minor: TransactionMinorState.Deposit,
      };
    case PeerPullDebitRecordStatus.Aborted:
      return {
        major: TransactionMajorState.Aborted,
      };
    case PeerPullDebitRecordStatus.AbortingRefresh:
      return {
        major: TransactionMajorState.Aborting,
        minor: TransactionMinorState.Refresh,
        working: true,
      };
    case PeerPullDebitRecordStatus.Failed:
      return {
        major: TransactionMajorState.Failed,
      };
    case PeerPullDebitRecordStatus.Expired:
      return {
        major: TransactionMajorState.Expired,
      };
    case PeerPullDebitRecordStatus.SuspendedAbortingRefresh:
      return {
        major: TransactionMajorState.SuspendedAborting,
        minor: TransactionMinorState.Refresh,
      };
  }
}

export function computePeerPullDebitTransactionActions(
  pullDebitRecord: WalletPeerPullDebit,
): TransactionAction[] {
  switch (pullDebitRecord.status) {
    case PeerPullDebitRecordStatus.DialogProposed:
      return [TransactionAction.Retry, TransactionAction.Delete];
    case PeerPullDebitRecordStatus.PendingDeposit:
      return [TransactionAction.Abort, TransactionAction.Suspend];
    case PeerPullDebitRecordStatus.Done:
      return [TransactionAction.Delete];
    case PeerPullDebitRecordStatus.SuspendedDeposit:
      return [TransactionAction.Resume, TransactionAction.Abort];
    case PeerPullDebitRecordStatus.Aborted:
      return [TransactionAction.Delete];
    case PeerPullDebitRecordStatus.AbortingRefresh:
      return [TransactionAction.Fail, TransactionAction.Suspend];
    case PeerPullDebitRecordStatus.Expired:
      return [TransactionAction.Delete];
    case PeerPullDebitRecordStatus.Failed:
      return [TransactionAction.Delete];
    case PeerPullDebitRecordStatus.SuspendedAbortingRefresh:
      return [TransactionAction.Resume, TransactionAction.Fail];
  }
}
