/**
 * Upgrade an IndexedDB in an upgrade transaction.
 *
 * The upgrade is made based on a store map, i.e. the metadata
 * structure that describes all the object stores and indexes.
 */
function upgradeFromStoreMap(
  storeMap: any, // FIXME: nail down type
  db: IDBDatabase,
  oldVersion: number,
  newVersion: number,
  upgradeTransaction: IDBTransaction,
): void {
  if (oldVersion === 0) {
    for (const n in storeMap) {
      const swi: StoreWithIndexes<
        any,
        StoreDescriptor<unknown>,
        any
      > = storeMap[n];
      const storeDesc: StoreDescriptor<unknown> = swi.store;
      const s = db.createObjectStore(swi.storeName, {
        autoIncrement: storeDesc.autoIncrement,
        keyPath: storeDesc.keyPath,
      });
      for (const indexName in swi.indexMap as any) {
        const indexDesc: IndexDescriptor = swi.indexMap[indexName];
        s.createIndex(indexDesc.name, indexDesc.keyPath, {
          multiEntry: indexDesc.multiEntry,
          unique: indexDesc.unique,
        });
      }
    }
    return;
  }
  if (oldVersion === newVersion) {
    return;
  }
  logger.info(`upgrading database from ${oldVersion} to ${newVersion}`);
  for (const n in storeMap) {
    const swi: StoreWithIndexes<any, StoreDescriptor<unknown>, any> = storeMap[
      n
    ];
    const storeDesc: StoreDescriptor<unknown> = swi.store;
    const storeAddedVersion = storeDesc.versionAdded ?? 0;
    let s: IDBObjectStore;
    if (storeAddedVersion > oldVersion) {
      // Be tolerant if object store already exists.
      // Probably means somebody deployed without
      // adding the "addedInVersion" attribute.
      if (!upgradeTransaction.objectStoreNames.contains(swi.storeName)) {
        try {
          s = db.createObjectStore(swi.storeName, {
            autoIncrement: storeDesc.autoIncrement,
            keyPath: storeDesc.keyPath,
          });
        } catch (e) {
          const moreInfo = e instanceof Error ? ` Reason: ${e.message}` : "";
          throw new Error(
            `Migration failed. Could not create store ${swi.storeName}.${moreInfo}`,
            { cause: e },
          );
        }
      }
    }

    s = upgradeTransaction.objectStore(swi.storeName);

    for (const indexName in swi.indexMap as any) {
      const indexDesc: IndexDescriptor = swi.indexMap[indexName];
      const indexAddedVersion = indexDesc.versionAdded ?? 0;
      if (indexAddedVersion <= oldVersion) {
        continue;
      }
      // Be tolerant if index already exists.
      // Probably means somebody deployed without
      // adding the "addedInVersion" attribute.
      if (!s.indexNames.contains(indexDesc.name)) {
        try {
          s.createIndex(indexDesc.name, indexDesc.keyPath, {
            multiEntry: indexDesc.multiEntry,
            unique: indexDesc.unique,
          });
        } catch (e) {
          const moreInfo = e instanceof Error ? ` Reason: ${e.message}` : "";
          throw Error(
            `Migration failed. Could not create index ${indexDesc.name}/${indexDesc.keyPath}. ${moreInfo}`,
            { cause: e },
          );
        }
      }
    }
  }
}

export function promiseFromTransaction(
  transaction: IDBTransaction,
): Promise<void> {
  return new Promise<void>((resolve, reject) => {
    transaction.oncomplete = () => {
      resolve();
    };
    transaction.onerror = () => {
      reject();
    };
  });
}

export function promiseFromRequest(request: IDBRequest): Promise<any> {
  return new Promise((resolve, reject) => {
    request.onsuccess = () => {
      resolve(request.result);
    };
    request.onerror = () => {
      reject(request.error);
    };
  });
}

/**
 * Purge all data in the given database.
 */
export function clearDatabase(db: IDBDatabase): Promise<void> {
  // db.objectStoreNames is a DOMStringList, so we need to convert
  let stores: string[] = [];
  for (let i = 0; i < db.objectStoreNames.length; i++) {
    stores.push(db.objectStoreNames[i]);
  }
  logger.info(`clearing object stores: ${j2s(stores)}`);
  const tx = db.transaction(stores, "readwrite");
  for (const store of stores) {
    tx.objectStore(store).clear();
  }
  return promiseFromTransaction(tx);
}

function onTalerDbUpgradeNeeded(
  db: IDBDatabase,
  oldVersion: number,
  newVersion: number,
  upgradeTransaction: IDBTransaction,
) {
  upgradeFromStoreMap(
    WalletIndexedDbStoresV1,
    db,
    oldVersion,
    newVersion,
    upgradeTransaction,
  );
  if (oldVersion < 32) {
    const store = upgradeTransaction.objectStore("coinAvailabilityV2");
    const req = store.openCursor();
    req.onsuccess = () => {
      const cursor = req.result;
      if (!cursor) {
        return;
      }
      const value = cursor.value as WalletCoinAvailability;
      cursor.update({
        ...value,
        hasFreshCoins: value.freshCoinCount > 0 ? 1 : 0,
      });
      cursor.continue();
    };
  }
}

function onMetaDbUpgradeNeeded(
  db: IDBDatabase,
  oldVersion: number,
  newVersion: number,
  upgradeTransaction: IDBTransaction,
) {
  upgradeFromStoreMap(
    walletMetadataStore,
    db,
    oldVersion,
    newVersion,
    upgradeTransaction,
  );
}

/**
 * Return a promise that resolves
 * to the taler wallet db.
 *
 * @param onVersionChange Called when another client concurrenctly connects to the database
 * with a higher version.
 */
export async function openTalerDatabase(
  idbFactory: IDBFactory,
  onVersionChange: () => void,
  onUpgradeStart?: (oldVersion: number, newVersion: number) => void,
): Promise<IDBDatabase> {
  const state = await readMainDbState(idbFactory, true);
  await cleanInterruptedDatabaseReplacement(idbFactory, state);
  return await openTalerDatabaseGeneration(
    idbFactory,
    state.current,
    onVersionChange,
    onUpgradeStart,
  );
}

interface MainDbState {
  current: string;
  pending?: string;
  retired?: string;
}

function isCurrentGenerationName(name: string): boolean {
  return (
    name === TALER_WALLET_MAIN_DB_NAME ||
    name.startsWith(TALER_WALLET_DB_GENERATION_PREFIX)
  );
}

async function openMetaDatabase(idbFactory: IDBFactory): Promise<{
  handle: IDBDatabase;
  access: DbAccess<typeof walletMetadataStore>;
}> {
  const handle = await openDatabase(
    idbFactory,
    TALER_WALLET_META_DB_NAME,
    1,
    () => {},
    onMetaDbUpgradeNeeded,
  );
  return {
    handle,
    access: new DbAccessImpl(
      handle,
      walletMetadataStore,
      CancellationToken.CONTINUE,
    ),
  };
}

async function readMainDbState(
  idbFactory: IDBFactory,
  initialize: boolean,
): Promise<MainDbState> {
  const meta = await openMetaDatabase(idbFactory);
  try {
    let state!: MainDbState;
    await meta.access.runAllStoresReadWriteTx({}, async (tx) => {
      const currentRecord = await tx.metaConfig.get(CURRENT_DB_CONFIG_KEY);
      let current = currentRecord?.value as string | undefined;
      if (!current) {
        current = TALER_WALLET_MAIN_DB_NAME;
        if (initialize) {
          await tx.metaConfig.put({
            key: CURRENT_DB_CONFIG_KEY,
            value: current,
          });
        }
      } else if (!isCurrentGenerationName(current)) {
        switch (current) {
          case "taler-wallet-main-v2":
          case "taler-wallet-main-v3":
          case "taler-wallet-main-v4":
          case "taler-wallet-main-v5":
          case "taler-wallet-main-v6":
          case "taler-wallet-main-v7":
          case "taler-wallet-main-v8":
          case "taler-wallet-main-v9":
            // These were pre-release databases and have no supported major
            // migration.  Preserve the historical behaviour of starting the
            // current major afresh.
            current = TALER_WALLET_MAIN_DB_NAME;
            if (initialize) {
              await tx.metaConfig.put({
                key: CURRENT_DB_CONFIG_KEY,
                value: current,
              });
            }
            break;
          default:
            throw Error(
              `major migration from database major=${current} not supported`,
            );
        }
      }
      state = {
        current,
        pending: (await tx.metaConfig.get(PENDING_DB_CONFIG_KEY))?.value,
        retired: (await tx.metaConfig.get(RETIRED_DB_CONFIG_KEY))?.value,
      };
    });
    return state;
  } finally {
    meta.handle.close();
  }
}

export async function readCurrentMainDbName(
  idbFactory: IDBFactory,
): Promise<string> {
  return (await readMainDbState(idbFactory, true)).current;
}

async function openTalerDatabaseGeneration(
  idbFactory: IDBFactory,
  name: string,
  onVersionChange: () => void,
  onUpgradeStart?: (oldVersion: number, newVersion: number) => void,
): Promise<IDBDatabase> {
  if (!isCurrentGenerationName(name)) {
    throw Error(`invalid wallet database generation name ${name}`);
  }
  return await openDatabase(
    idbFactory,
    name,
    WALLET_DB_MINOR_VERSION,
    onVersionChange,
    (db, oldVersion, newVersion, transaction) => {
      onUpgradeStart?.(oldVersion, newVersion);
      onTalerDbUpgradeNeeded(db, oldVersion, newVersion, transaction);
    },
  );
}

/** Resolve true on deletion, false when another client still blocks it. */
async function tryDeleteDatabase(
  idbFactory: IDBFactory,
  name: string,
): Promise<boolean> {
  return await new Promise<boolean>((resolve, reject) => {
    const req = idbFactory.deleteDatabase(name);
    let settled = false;
    const finish = (result: boolean): void => {
      if (settled) return;
      settled = true;
      resolve(result);
    };
    req.onerror = () => {
      if (settled) return;
      settled = true;
      reject(req.error);
    };
    req.onblocked = () => finish(false);
    req.onsuccess = () => finish(true);
  });
}

async function clearMetaMarker(
  idbFactory: IDBFactory,
  key: string,
  expectedValue: string,
): Promise<void> {
  const meta = await openMetaDatabase(idbFactory);
  try {
    await meta.access.runAllStoresReadWriteTx({}, async (tx) => {
      const record = await tx.metaConfig.get(key);
      if (record?.value === expectedValue) {
        await tx.metaConfig.delete(key);
      }
    });
  } finally {
    meta.handle.close();
  }
}

async function cleanupGeneration(
  idbFactory: IDBFactory,
  name: string | undefined,
  marker: string,
  current: string,
): Promise<void> {
  if (!name || name === current) return;
  try {
    if (await tryDeleteDatabase(idbFactory, name)) {
      await clearMetaMarker(idbFactory, marker, name);
    }
  } catch (e) {
    // Cleanup is not authoritative-state recovery.  Retaining an unreachable
    // generation costs storage, but refusing to open the current wallet would
    // turn that harmless residue into an outage.
    logger.warn(`could not clean wallet database generation ${name}: ${e}`);
  }
}

async function cleanInterruptedDatabaseReplacement(
  idbFactory: IDBFactory,
  state: MainDbState,
): Promise<void> {
  // A pending generation was never published, so current is authoritative.
  // Clear its claim but do not issue deleteDatabase here: another wallet
  // context could still be preparing it, and a blocked deletion request would
  // remain armed and could delete the generation after that context publishes
  // and eventually closes it.  Clearing the claim instead makes that
  // publisher fail its compare-and-swap safely.  Hard-crash residue is an
  // unreachable storage leak, never an authoritative-state ambiguity.
  if (state.pending && state.pending !== state.current) {
    await clearMetaMarker(idbFactory, PENDING_DB_CONFIG_KEY, state.pending);
  }
  // A retired generation has already been superseded and can never become
  // authoritative again, so deletion is safe even when another context still
  // has it open (in which case cleanup remains recorded for the next start).
  await cleanupGeneration(
    idbFactory,
    state.retired,
    RETIRED_DB_CONFIG_KEY,
    state.current,
  );
}

export interface StagedTalerDatabase {
  name: string;
  handle: IDBDatabase;
}

/** Create and durably record an unpublished current-schema generation. */
export async function beginTalerDatabaseReplacement(
  idbFactory: IDBFactory,
  currentName: string,
  onVersionChange: () => void,
): Promise<StagedTalerDatabase> {
  const name = `${TALER_WALLET_DB_GENERATION_PREFIX}${encodeCrock(
    getRandomBytes(16),
  )}`;
  const meta = await openMetaDatabase(idbFactory);
  try {
    await meta.access.runAllStoresReadWriteTx({}, async (tx) => {
      const current = await tx.metaConfig.get(CURRENT_DB_CONFIG_KEY);
      if (current?.value !== currentName) {
        throw Error("wallet database generation changed during import");
      }
      const pending = await tx.metaConfig.get(PENDING_DB_CONFIG_KEY);
      if (pending) {
        throw Error(
          `another wallet database import is already pending (${pending.value})`,
        );
      }
      await tx.metaConfig.put({ key: PENDING_DB_CONFIG_KEY, value: name });
    });
  } finally {
    meta.handle.close();
  }
  try {
    return {
      name,
      handle: await openTalerDatabaseGeneration(
        idbFactory,
        name,
        onVersionChange,
      ),
    };
  } catch (e) {
    await abortTalerDatabaseReplacement(idbFactory, name);
    throw e;
  }
}

/** Atomically make a fully prepared generation authoritative. */
export async function publishTalerDatabaseReplacement(
  idbFactory: IDBFactory,
  oldName: string,
  newName: string,
): Promise<void> {
  const meta = await openMetaDatabase(idbFactory);
  try {
    await meta.access.runAllStoresReadWriteTx({}, async (tx) => {
      const current = await tx.metaConfig.get(CURRENT_DB_CONFIG_KEY);
      const pending = await tx.metaConfig.get(PENDING_DB_CONFIG_KEY);
      if (current?.value !== oldName || pending?.value !== newName) {
        throw Error("wallet database generation changed during import");
      }
      await tx.metaConfig.put({ key: CURRENT_DB_CONFIG_KEY, value: newName });
      await tx.metaConfig.delete(PENDING_DB_CONFIG_KEY);
      await tx.metaConfig.put({ key: RETIRED_DB_CONFIG_KEY, value: oldName });
    });
  } finally {
    meta.handle.close();
  }
}

/** Delete an unpublished generation after a failed import. */
export async function abortTalerDatabaseReplacement(
  idbFactory: IDBFactory,
  name: string,
): Promise<void> {
  await cleanupGeneration(idbFactory, name, PENDING_DB_CONFIG_KEY, "");
}

/** Best-effort deletion of the old generation after a successful publish. */
export async function retireTalerDatabaseGeneration(
  idbFactory: IDBFactory,
  name: string,
  currentName: string,
): Promise<void> {
  await cleanupGeneration(idbFactory, name, RETIRED_DB_CONFIG_KEY, currentName);
}

export async function deleteTalerDatabase(
  idbFactory: IDBFactory,
): Promise<void> {
  const state = await readMainDbState(idbFactory, false);
  const names = new Set([
    TALER_WALLET_MAIN_DB_NAME,
    state.current,
    state.pending,
    state.retired,
  ]);
  for (const name of names) {
    if (name && !(await tryDeleteDatabase(idbFactory, name))) {
      throw Error(`deletion of wallet database ${name} is blocked`);
    }
  }
  if (!(await tryDeleteDatabase(idbFactory, TALER_WALLET_META_DB_NAME))) {
    throw Error("deletion of wallet metadata database is blocked");
  }
}
