const logger = new Logger("db/indexeddb/fixups.ts");

export interface FixupDescription {
  name: string;
  fn(tx: WalletIndexedDbTransaction): Promise<void>;
}

/**
 * Manual migrations between minor versions of the DB schema.
 *
 * Fixups *must* be idempotent.
 */
export const walletDbFixups: FixupDescription[] = [
  // Exchange purging used to delete coins without deleting their histories,
  // leaving rows that the sqlite foreign key cannot represent.
  {
    fn: fixup20260822OrphanCoinHistories,
    name: "fixup20260822OrphanCoinHistories",
  },
  // Exchange purging used to delete the details row before querying an
  // array-valued index with a scalar key, so the related signing keys were
  // not found and survived without their parent.
  {
    fn: fixup20260822OrphanExchangeSignKeys,
    name: "fixup20260822OrphanExchangeSignKeys",
  },
  // A later repair for duplicate merge-reserve rows whose key material is
  // identical but where only one row carries KYC metadata.  This needs its
  // own fixup marker: affected databases have already recorded the older,
  // byte-identical-only repair below as complete.
  {
    fn: fixup20260820DuplicateReserveMetadata,
    name: "fixup20260820DuplicateReserveMetadata",
  },
  // Clause-Schnorr support made this field explicit.  Older RSA records imply
  // the RSA defaults and remain valid after the field was introduced.
  {
    fn: fixup20260812ExchangeWithdrawValues,
    name: "fixup20260812ExchangeWithdrawValues",
  },
  // Deduplicate reserve rows left behind by a version that inserted its
  // merge reserve repeatedly.  Needed for as long as pre-2024 databases can
  // still be imported.
  {
    fn: fixup20260720DuplicateReserves,
    name: "fixup20260720DuplicateReserves",
  },
  // Exchange details rows from before tinyAmount existed.
  {
    fn: fixup20260720ExchangeDetailsTinyAmount,
    name: "fixup20260720ExchangeDetailsTinyAmount",
  },
  // Refresh groups from before refundRequests existed.
  {
    fn: fixup20260720RefreshGroupRefundRequests,
    name: "fixup20260720RefreshGroupRefundRequests",
  },
  // Removing this would cause old transactions
  // to show up under multiple exchanges
  {
    fn: fixup20260718TransactionsScope,
    name: "fixup20260718TransactionsScope",
  },
  // Removing this would cause merchant acceptable
  // amount to be calculaed based on exchangeBaseUrl
  // instead of masterPublicKey for old coins.
  {
    fn: fixupCoinAvailabilityExchangePub,
    name: "fixupCoinAvailabilityExchangePub",
  },
  // Can be removed once all affected refresh groups have
  // been fixed. Conservative estimate: Jan 2028.
  {
    fn: fixup20260116BadRefreshCoinSelection,
    name: "fixup20260116BadRefreshCoinSelection",
  },
  // Denom families were introduced.
  // This migration creates denom families
  // for existing denomination records.
  {
    fn: fixup20260203DenomFamilyMigration,
    name: "fixup20260203DenomFamilyMigration",
  },
  // Fix a problem where refreshes went into a failed state
  // instead of retrying.
  {
    fn: fixup20260213RefreshBlunder,
    name: "fixup20260213RefreshBlunder",
  },
  // Several status enum members were persisted with a dropped hex
  // digit, putting them outside their status range.  Rewrite the raw records
  // to the corrected values (transactionsMeta is rebuilt separately via the
  // MATERIALIZED_TRANSACTIONS_VERSION bump).
  {
    fn: fixup20260718StatusEnumDigits,
    name: "fixup20260718StatusEnumDigits",
  },
  // Denominations move to a store keyed by the master public key that signed
  // them.  Runs after the family migration, which assigns the family serial
  // the copied rows carry.
  {
    fn: fixup20260807DenominationsByMasterPub,
    name: "fixup20260807DenominationsByMasterPub",
  },
  // Coin availability moves to the same key as the denominations it counts.
  {
    fn: fixup20260807CoinAvailabilityByMasterPub,
    name: "fixup20260807CoinAvailabilityByMasterPub",
  },
  // Coins record the key that signed their denomination, so that they are
  // tied to the keys that can settle them rather than to the URL the
  // exchange happens to answer on.
  {
    fn: fixup20260807CoinExchangeMasterPub,
    name: "fixup20260807CoinExchangeMasterPub",
  },
];

/** Schema opening, every record fixup, and transaction rematerialization. */
export const WALLET_DB_MAINTENANCE_TOTAL_STEPS = walletDbFixups.length + 2;
export const WALLET_DB_SCHEMA_UPGRADE_STEP = "indexeddb-schema-upgrade";
export const WALLET_DB_REMATERIALIZE_STEP = "rematerialize-transactions";

/**
 * Delete coin histories whose coins were removed by the old IndexedDB
 * exchange-purge implementation.
 *
 * Coin history is looked up through its coin and carries no independent
 * wallet state.  Removing an orphan therefore matches the ON DELETE CASCADE
 * constraint used by the sqlite backend.
 */
async function fixup20260822OrphanCoinHistories(
  tx: WalletIndexedDbTransaction,
): Promise<void> {
  await tx.coinHistory.iter().forEachAsync(async (history) => {
    if (await tx.coins.get(history.coinPub)) {
      return;
    }
    await tx.coinHistory.delete(history.coinPub);
  });
}

/**
 * Delete signing keys whose exchange details were removed by the old
 * IndexedDB exchange-purge implementation.
 *
 * A signing key describes exactly one details row and carries no independent
 * wallet state.  Removing it therefore matches the ON DELETE CASCADE
 * constraint used by the sqlite backend.
 */
async function fixup20260822OrphanExchangeSignKeys(
  tx: WalletIndexedDbTransaction,
): Promise<void> {
  await tx.exchangeSignKeys.iter().forEachAsync(async (signKey) => {
    if (await tx.exchangeDetails.get(signKey.exchangeDetailsRowId)) {
      return;
    }
    await tx.exchangeSignKeys.delete([
      signKey.exchangeDetailsRowId,
      signKey.signkeyPub,
    ]);
  });
}

/**
 * Copy coin availability into the store keyed by master public key.
 *
 * The key comes from the row itself where it was recorded, and otherwise from
 * the denomination it counts.  A row that resolves to neither is left behind
 * rather than filed under a guess: it would misreport what is spendable.
 */
async function fixup20260807CoinAvailabilityByMasterPub(
  tx: WalletIndexedDbTransaction,
): Promise<void> {
  const batchSize = 500;
  let range: IDBKeyRange | undefined = undefined;
  while (1) {
    const batch = await tx.coinAvailability.getAll(range, batchSize);
    if (batch.length === 0) {
      break;
    }
    const last = batch[batch.length - 1];
    range = GlobalIDB.KeyRange.lowerBound(
      [last.exchangeBaseUrl, last.denomPubHash, last.maxAge],
      true,
    );
    for (const av of batch) {
      let masterPub: string | undefined = av.exchangeMasterPub;
      if (!masterPub) {
        const denom = await tx.denominations.get([
          av.exchangeBaseUrl,
          av.denomPubHash,
        ]);
        masterPub = denom?.exchangeMasterPub;
      }
      if (!masterPub) {
        logger.warn(
          `coin availability for ${av.denomPubHash} has no master public key, not copying`,
        );
        continue;
      }
      const existing = await tx.coinAvailabilityV2.get([
        masterPub,
        av.denomPubHash,
        av.maxAge,
      ]);
      if (existing) {
        continue;
      }
      await tx.coinAvailabilityV2.put({
        ...av,
        exchangeMasterPub: masterPub,
        hasFreshCoins: av.freshCoinCount > 0 ? 1 : 0,
      });
    }
  }
}

/**
 * Copy denominations into the store keyed by master public key.
 *
 * The old store is left populated: it is the only source for this copy, so
 * clearing it would make the fixup unrepeatable, and a fixup can abort and be
 * retried on the next open.  Two base URLs that served the same key set
 * collapse onto one row here, which is the point -- they were never two
 * denominations.
 */
async function fixup20260807DenominationsByMasterPub(
  tx: WalletIndexedDbTransaction,
): Promise<void> {
  const batchSize = 500;
  let range: IDBKeyRange | undefined = undefined;
  while (1) {
    const batch = await tx.denominations.getAll(range, batchSize);
    if (batch.length === 0) {
      break;
    }
    const last = batch[batch.length - 1];
    range = GlobalIDB.KeyRange.lowerBound(
      [last.exchangeBaseUrl, last.denomPubHash],
      true,
    );
    for (const denom of batch) {
      if (!denom.exchangeMasterPub) {
        logger.warn(
          `denomination ${denom.denomPubHash} has no master public key, not copying`,
        );
        continue;
      }
      const existing = await tx.denominationsV2.get([
        denom.exchangeMasterPub,
        denom.denomPubHash,
      ]);
      if (existing) {
        continue;
      }
      await tx.denominationsV2.put(denom);
    }
  }
}

/**
 * Backfill {@link WalletCoin.exchangeMasterPub} from the coin's denomination.
 *
 * The denomination has carried the master public key all along, so nothing
 * has to be guessed.  A coin whose denomination is gone is left alone rather
 * than deleted: a fixup must never destroy coins, and an empty key reads as
 * "not known" everywhere it is used.
 */
async function fixup20260807CoinExchangeMasterPub(
  tx: WalletIndexedDbTransaction,
): Promise<void> {
  const batchSize = 500;
  let range: IDBKeyRange | undefined = undefined;
  while (1) {
    const batch = await tx.coins.getAll(range, batchSize);
    if (batch.length === 0) {
      break;
    }
    const last = batch[batch.length - 1];
    range = GlobalIDB.KeyRange.lowerBound(last.coinPub, true);
    for (const coin of batch) {
      if (coin.exchangeMasterPub) {
        continue;
      }
      const denom = await tx.denominations.get([
        coin.exchangeBaseUrl,
        coin.denomPubHash,
      ]);
      if (!denom) {
        logger.warn(
          `coin ${coin.coinPub} has no denomination, leaving its master public key unset`,
        );
        continue;
      }
      coin.exchangeMasterPub = denom.exchangeMasterPub;
      await tx.coins.put(coin);
    }
  }
}

async function fixup20260718StatusEnumDigits(
  tx: WalletIndexedDbTransaction,
): Promise<void> {
  // These OLD (mis-typed, 7-hex-digit) values are what was actually persisted
  // before, so we match on the raw numbers on purpose: the
  // enum members now resolve to the CORRECTED values and would not match old
  // records.
  const WG_FIX = new Map<number, number>([
    [0x0110005, 0x0110_0005], // WithdrawalGroupStatus.SuspendedKyc
    [0x0110006, 0x0110_0006], // WithdrawalGroupStatus.SuspendedBalanceKyc
    [0x0110007, 0x0110_0007], // WithdrawalGroupStatus.SuspendedBalanceKycInit
  ]);
  await tx.withdrawalGroups.iter().forEachAsync(async (rec) => {
    const nv = WG_FIX.get(rec.status);
    if (nv !== undefined) {
      rec.status = nv as WithdrawalGroupStatus;
      await tx.withdrawalGroups.put(rec);
    }
  });

  // PlanchetStatus.WithdrawalDone
  await tx.planchets.iter().forEachAsync(async (rec) => {
    if ((rec.planchetStatus as number) === 0x0500000) {
      rec.planchetStatus = 0x0500_0000 as PlanchetStatus;
      await tx.planchets.put(rec);
    }
  });

  // RefreshOperationStatus.{Finished,Failed} and RefreshCoinStatus.Failed
  const RO_FIX = new Map<number, number>([
    [0x0500000, 0x0500_0000], // Finished
    [0x0501000, 0x0501_0000], // Failed
  ]);
  await tx.refreshGroups.iter().forEachAsync(async (rec) => {
    let changed = false;
    const nv = RO_FIX.get(rec.operationStatus);
    if (nv !== undefined) {
      rec.operationStatus = nv as RefreshOperationStatus;
      changed = true;
    }
    for (let i = 0; i < rec.statusPerCoin.length; i++) {
      if ((rec.statusPerCoin[i] as number) === 0x0501000) {
        rec.statusPerCoin[i] = 0x0501_0000 as RefreshCoinStatus;
        changed = true;
      }
    }
    if (changed) {
      await tx.refreshGroups.put(rec);
    }
  });

  // RecoupOperationStatus.{Finished,Failed}
  const RC_FIX = new Map<number, number>([
    [0x0500000, 0x0500_0000], // Finished
    [0x0501000, 0x0501_0000], // Failed
  ]);
  await tx.recoupGroups.iter().forEachAsync(async (rec) => {
    const nv = RC_FIX.get(rec.operationStatus);
    if (nv !== undefined) {
      rec.operationStatus = nv as RecoupOperationStatus;
      await tx.recoupGroups.put(rec);
    }
  });
}

async function fixup20260213RefreshBlunder(
  tx: WalletIndexedDbTransaction,
): Promise<void> {
  await tx.refreshGroups.indexes.byStatus
    .iter(RefreshOperationStatus.Failed)
    .forEachAsync(async (refreshGroup) => {
      for (
        let coinIndex = 0;
        coinIndex < refreshGroup.statusPerCoin.length;
        coinIndex++
      ) {
        let changed = false;
        if (
          refreshGroup.statusPerCoin[coinIndex] === RefreshCoinStatus.Failed
        ) {
          const rs = await tx.refreshSessions.get([
            refreshGroup.refreshGroupId,
            coinIndex,
          ]);
          if (
            rs?.lastError?.code ===
            TalerErrorCode.EXCHANGE_GENERIC_DENOMINATION_EXPIRED
          ) {
            refreshGroup.statusPerCoin[coinIndex] =
              RefreshCoinStatus.PendingRedenominate;
            refreshGroup.operationStatus =
              RefreshOperationStatus.PendingRedenominate;
            delete refreshGroup.timestampFinished;
            changed = true;
          }
        }
        if (changed) {
          await tx.refreshGroups.put(refreshGroup);
        }
      }
    });
}

async function fixup20260203DenomFamilyMigration(
  tx: WalletIndexedDbTransaction,
): Promise<void> {
  const batchSize = 500;

  let range: IDBKeyRange | undefined = undefined;

  while (1) {
    const batch = await tx.denominations.getAll(range, batchSize);

    if (batch.length === 0) {
      break;
    }

    logger.info(`fixing up batch of ${batch.length} denominations`);

    const last = batch[batch.length - 1];
    range = GlobalIDB.KeyRange.lowerBound(
      [last.exchangeBaseUrl, last.denomPubHash],
      true,
    );

    for (const r of batch) {
      const fp: WalletDenomFamilyParams = {
        exchangeBaseUrl: r.exchangeBaseUrl,
        exchangeMasterPub: r.exchangeMasterPub,
        feeDeposit: r.fees.feeDeposit,
        feeRefresh: r.fees.feeRefresh,
        feeRefund: r.fees.feeRefund,
        feeWithdraw: r.fees.feeWithdraw,
        value: r.value,
      };
      if (r.denominationFamilySerial != null) {
        // Fast path: Check if family exists and is correct.
        const oldFpRec = await tx.denominationFamilies.get(
          r.denominationFamilySerial,
        );
        if (
          oldFpRec &&
          canonicalJson(fp) == canonicalJson(oldFpRec.familyParams)
        ) {
          continue;
        }
      }
      const familyParamsIndexKey = [
        fp.exchangeBaseUrl,
        fp.exchangeMasterPub,
        fp.value,
        fp.feeWithdraw,
        fp.feeDeposit,
        fp.feeRefresh,
        fp.feeRefund,
      ];
      const dfRec =
        await tx.denominationFamilies.indexes.byFamilyParms.get(
          familyParamsIndexKey,
        );
      let denominationFamilySerial;
      if (dfRec) {
        denominationFamilySerial = dfRec.denominationFamilySerial;
      } else {
        const insRes = await tx.denominationFamilies.put({
          familyParams: fp,
        });
        denominationFamilySerial = insRes.key;
      }
      checkDbInvariant(
        typeof denominationFamilySerial == "number",
        "denominationFamilySerial",
      );
      r.denominationFamilySerial = denominationFamilySerial;
      await tx.denominations.put(r);
    }
  }
}

async function fixup20260116BadRefreshCoinSelection(
  tx: WalletIndexedDbTransaction,
): Promise<void> {
  await tx.refreshGroups.iter().forEachAsync(async (rec) => {
    // Only repair groups that are still in flight.  "Input non-zero, output
    // zero" also describes a refresh that legitimately finished with its
    // whole input eaten by fees -- a dust refresh of TESTKUDOS:0.01 into
    // nothing looks identical to the bad coin selection this repairs.
    // Re-activating one of those undoes a completed operation, which showed
    // up as a finished refresh transaction reverting to pending after an
    // import.
    if (
      rec.operationStatus < OPERATION_STATUS_NONFINAL_FIRST ||
      rec.operationStatus > OPERATION_STATUS_NONFINAL_LAST
    ) {
      return;
    }
    const inputAmount = Amounts.sumOrZero(
      rec.currency,
      rec.inputPerCoin,
    ).amount;
    const outputAmount = Amounts.sumOrZero(
      rec.currency,
      rec.expectedOutputPerCoin,
    ).amount;
    if (Amounts.isNonZero(inputAmount) && Amounts.isZero(outputAmount)) {
      logger.info(
        `fixing up refresh group ${rec.refreshGroupId}, setting status to PendingRedenominate`,
      );
      rec.operationStatus = RefreshOperationStatus.PendingRedenominate;
      delete rec.timestampFinished;
      await tx.refreshGroups.put(rec);
    }
  });
}

/**
 * Some old payment transactions didn't correctly
 * set the involved exchanges.
 *
 * This fixup sets the exchanges of a payment transaction
 * based on the coin selection.
 */
async function fixup20260718TransactionsScope(
  tx: WalletIndexedDbTransaction,
): Promise<void> {
  await tx.purchases.iter().forEachAsync(async (rec) => {
    if (
      (rec.exchanges?.length ?? 0) == 0 &&
      rec.payInfo?.payCoinSelection != null
    ) {
      const pcs = rec.payInfo.payCoinSelection.coinPubs;
      const exchSet: Set<string> = new Set();
      for (const pc of pcs) {
        const coin = await tx.coins.get(pc);
        if (!coin) {
          continue;
        }
        exchSet.add(coin.exchangeBaseUrl);
      }
      rec.exchanges = [...exchSet];
      rec.exchanges.sort();
      if (rec.exchanges.length == 0) {
        // For old SPURLOS transactions, set exchange manually
        // when we can't infer it.
        if (
          rec.timestamp <= 1736942400000_000 &&
          rec.download?.currency === "SPURLOS"
        ) {
          rec.exchanges = ["https://exchange.taler.datenspuren.de/"];
        }
        logger.warn(
          `unable to fix up pay transaction ${rec.proposalId}, could not reconstruct exchanges`,
        );
      }
      await tx.purchases.put(rec);
    }
  });
}

async function fixupCoinAvailabilityExchangePub(
  tx: WalletIndexedDbTransaction,
): Promise<void> {
  await tx.coinAvailability.iter().forEachAsync(async (car) => {
    if (car.exchangeMasterPub === undefined) {
      const exchange = await tx.exchangeDetails.indexes.byExchangeBaseUrl.get(
        car.exchangeBaseUrl,
      );
      if (exchange !== undefined) {
        car.exchangeMasterPub = exchange.masterPublicKey;
        await tx.coinAvailability.put(car);
      }
    }
  });
}

/**
 * Backfill tinyAmount on exchange details rows from before the field existed.
 *
 * Uses the same default the keys update applies when an exchange reports no
 * tiny_amount, so a backfilled row equals what the next update would have
 * written anyway.  Without this, deposits read undefined where the type
 * promises an AmountString.
 */
async function fixup20260720ExchangeDetailsTinyAmount(
  tx: WalletIndexedDbTransaction,
): Promise<void> {
  await tx.exchangeDetails.iter().forEachAsync(async (det) => {
    if ((det as any).tinyAmount === undefined) {
      det.tinyAmount = `${det.currency}:0.01` as AmountString;
      await tx.exchangeDetails.put(det);
    }
  });
}

/**
 * Backfill refundRequests on refresh groups from before the field existed.
 *
 * The refresh task reads refundRequests[coinIndex] unguarded, so a group
 * written before the field existed throws when the task touches it.  An
 * empty map is the correct backfill: those groups have no pending refund
 * requests, or they would have been recorded.
 */
async function fixup20260720RefreshGroupRefundRequests(
  tx: WalletIndexedDbTransaction,
): Promise<void> {
  await tx.refreshGroups.iter().forEachAsync(async (rg) => {
    let changed = false;
    if ((rg as any).refundRequests === undefined) {
      rg.refundRequests = {};
      changed = true;
    }
    // originatingTransactionId used to be nested in a reasonDetails object;
    // the modern record carries it top-level and reads it there.
    const legacyDetails = (rg as any).reasonDetails;
    if (
      rg.originatingTransactionId === undefined &&
      legacyDetails?.originatingTransactionId !== undefined
    ) {
      rg.originatingTransactionId = legacyDetails.originatingTransactionId;
      changed = true;
    }
    if (legacyDetails !== undefined) {
      delete (rg as any).reasonDetails;
      changed = true;
    }
    if (changed) {
      await tx.refreshGroups.put(rg);
    }
  });
}

function canonicalFixupValue(value: any): any {
  if (Array.isArray(value)) return value.map(canonicalFixupValue);
  if (value !== null && typeof value === "object") {
    return Object.fromEntries(
      Object.keys(value)
        .sort()
        .map((key) => [key, canonicalFixupValue(value[key])]),
    );
  }
  return value;
}

async function remapAndDeleteReserve(
  tx: WalletIndexedDbTransaction,
  droppedRowId: number,
  retainedRowId: number,
): Promise<void> {
  await tx.exchanges.iter().forEachAsync(async (e) => {
    if (e.currentMergeReserveRowId === droppedRowId) {
      e.currentMergeReserveRowId = retainedRowId;
      await tx.exchanges.put(e);
    }
  });
  await tx.peerPullCredit.iter().forEachAsync(async (p) => {
    if (p.mergeReserveRowId === droppedRowId) {
      p.mergeReserveRowId = retainedRowId;
      await tx.peerPullCredit.put(p);
    }
  });
  await tx.reserves.delete(droppedRowId);
}

/**
 * Remove byte-identical duplicate reserve rows.
 *
 * An older wallet version inserted its merge reserve again on each update
 * instead of upserting, leaving several rows with identical key material
 * under different row ids.  Databases like that exist in the wild.  The
 * lowest row id is kept and the two references to reserve rows (the
 * exchange's current merge reserve and peer-pull-credit merge reserves) are
 * remapped onto it.
 *
 * Rows are removed only when every field except rowId matches the kept row.
 * Any disagreement is corruption or ambiguity, which deleting would paper
 * over, so those rows are left for conversion to reject.
 */
async function fixup20260720DuplicateReserves(
  tx: WalletIndexedDbTransaction,
): Promise<void> {
  let kept: WalletReserve | undefined;
  const withoutRowId = (r: WalletReserve): string => {
    const { rowId: _rowId, ...rest } = r;
    return JSON.stringify(canonicalFixupValue(rest));
  };
  // The index groups equal public keys, so only the retained row for the
  // current key is kept in memory.  References are remapped immediately,
  // avoiding a map proportional to the reserve store.
  await tx.reserves.indexes.byReservePub.iter().forEachAsync(async (r) => {
    if (r.rowId == null) return;
    if (!kept || kept.reservePub !== r.reservePub) {
      kept = r;
      return;
    }
    if (kept.rowId == null || withoutRowId(kept) !== withoutRowId(r)) {
      return;
    }
    const droppedRowId = r.rowId;
    const keptRowId = kept.rowId;
    await remapAndDeleteReserve(tx, droppedRowId, keptRowId);
  });
}

/**
 * Collapse the metadata-free reserve duplicate created by peer-credit
 * withdrawals before 528a32fff.
 *
 * Equal public and private keys identify the same reserve.  It is safe to
 * discard one row when all of its defined metadata is also present and equal
 * in the other row: the surviving row then loses no information.  Different
 * defined values remain untouched, so the converter still refuses an
 * ambiguous database for which there is no revision information to select a
 * winner.
 */
async function fixup20260820DuplicateReserveMetadata(
  tx: WalletIndexedDbTransaction,
): Promise<void> {
  const metadataIsSubset = (
    subset: WalletReserve,
    superset: WalletReserve,
  ): boolean => {
    for (const [key, value] of Object.entries(subset)) {
      if (
        key === "rowId" ||
        key === "reservePub" ||
        key === "reservePriv" ||
        value === undefined
      ) {
        continue;
      }
      if (
        JSON.stringify(canonicalFixupValue(value)) !==
        JSON.stringify(
          canonicalFixupValue(
            (superset as unknown as Record<string, unknown>)[key],
          ),
        )
      ) {
        return false;
      }
    }
    return true;
  };

  let retained: WalletReserve | undefined;
  await tx.reserves.indexes.byReservePub.iter().forEachAsync(async (row) => {
    if (row.rowId == null) return;
    if (!retained || retained.reservePub !== row.reservePub) {
      retained = row;
      return;
    }
    if (retained.rowId == null || retained.reservePriv !== row.reservePriv) {
      return;
    }
    const retainedIsSubset = metadataIsSubset(retained, row);
    const rowIsSubset = metadataIsSubset(row, retained);
    if (!retainedIsSubset && !rowIsSubset) {
      return;
    }
    if (retainedIsSubset && !rowIsSubset) {
      await remapAndDeleteReserve(tx, retained.rowId, row.rowId);
      retained = row;
    } else {
      await remapAndDeleteReserve(tx, row.rowId, retained.rowId);
    }
  });
}

async function fixup20260812ExchangeWithdrawValues(
  tx: WalletIndexedDbTransaction,
): Promise<void> {
  await tx.coins.iter().forEachAsync(async (coin) => {
    if (coin.exchangeWithdrawValues === undefined) {
      coin.exchangeWithdrawValues = { cipher: "RSA" } as any;
      await tx.coins.put(coin);
    }
  });
  await tx.planchets.iter().forEachAsync(async (planchet) => {
    if (planchet.exchangeWithdrawValues === undefined) {
      planchet.exchangeWithdrawValues = { cipher: "RSA" } as any;
      await tx.planchets.put(planchet);
    }
  });
}

export async function applyFixups(
  db: DbAccess<typeof WalletIndexedDbStoresV1>,
  onProgress: (notification: WalletNotification) => void = () => {},
  options: { deferCompletion?: boolean } = {},
): Promise<number> {
  logger.trace("applying fixups");
  let count = 0;
  // Most opens have no work to do.  Read the marker store once rather than
  // opening an all-store read-write transaction for every known fixup.  Load
  // it lazily in the first fixup transaction, so an old database with work to
  // do does not pay for an additional transaction just for the inventory.
  let completedFixups: Set<string> | undefined;
  for (let index = 0; index < walletDbFixups.length; index++) {
    const fixupInstruction = walletDbFixups[index];
    if (completedFixups?.has(fixupInstruction.name)) {
      continue;
    }
    let applied = false;
    try {
      await db.runAllStoresReadWriteTx({}, async (tx) => {
        logger.trace(`checking fixup ${fixupInstruction.name}`);
        if (!completedFixups) {
          completedFixups = new Set(
            (await tx.fixups.getAll()).map((x) => x.fixupName),
          );
        } else if (await tx.fixups.get(fixupInstruction.name)) {
          // Preserve atomicity if another context raced the marker snapshot.
          completedFixups.add(fixupInstruction.name);
        }
        if (completedFixups.has(fixupInstruction.name)) {
          return;
        }
        applied = true;
        logger.trace(`applying DB fixup ${fixupInstruction.name}`);
        onProgress({
          type: NotificationType.DatabaseMaintenanceProgress,
          operation: "indexeddb-fixup",
          phase: "fixup",
          step: fixupInstruction.name,
          completedSteps: index + 1,
          totalSteps: WALLET_DB_MAINTENANCE_TOTAL_STEPS,
        });
        await fixupInstruction.fn(tx);
        // A fixup may change any operation record from which transactionsMeta
        // is derived.  Invalidate the durable view version in the same commit
        // as the repair, so a crash or failed rematerialization is retried on
        // the next initialization instead of leaving a stale "current" flag.
        await tx.config.delete(ConfigRecordKey.MaterializedTransactionsVersion);
        await tx.fixups.put({
          fixupName: fixupInstruction.name,
        });
      });
      completedFixups!.add(fixupInstruction.name);
    } catch (e) {
      if (applied) {
        onProgress({
          type: NotificationType.DatabaseMaintenanceProgress,
          operation: "indexeddb-fixup",
          phase: "failed",
          step: fixupInstruction.name,
          completedSteps: index + 1,
          totalSteps: WALLET_DB_MAINTENANCE_TOTAL_STEPS,
          error: getErrorDetailFromException(e),
        });
      }
      throw e;
    }
    if (applied) {
      // Announce completion only after the transaction has committed.  A
      // commit error above produces "failed", never a misleading completed
      // step followed by a rollback.
      onProgress({
        type: NotificationType.DatabaseMaintenanceProgress,
        operation: "indexeddb-fixup",
        phase: "fixup",
        step: fixupInstruction.name,
        completedSteps: index + 2,
        totalSteps: WALLET_DB_MAINTENANCE_TOTAL_STEPS,
      });
      count++;
    }
  }
  if (count > 0 && !options.deferCompletion) {
    onProgress({
      type: NotificationType.DatabaseMaintenanceProgress,
      operation: "indexeddb-fixup",
      phase: "complete",
      completedSteps: WALLET_DB_MAINTENANCE_TOTAL_STEPS,
      totalSteps: WALLET_DB_MAINTENANCE_TOTAL_STEPS,
    });
  }
  return count;
}
