/**
 * Types used by the wallet crypto worker.
 *
 * These types are defined in a separate file make tree shaking easier, since
 * some components use these types (via RPC) but do not depend on the wallet
 * code directly.
 *
 * @author Florian Dold <dold@taler.net>
 */

/**
 * Imports.
 */
import {
  AgeCommitmentProof,
  AmountJson,
  AmountString,
  DenominationPubKey,
  EddsaPrivateKeyString,
  EddsaPublicKeyString,
  EddsaSignatureString,
  ExchangeProtocolVersion,
  ExchangeWithdrawValue,
  HashCodeString,
  RefreshPlanchetInfo,
  TalerProtocolTimestamp,
  UnblindedDenominationSignature,
  WalletAccountMergeFlags,
} from "@gnu-taler/taler-util";

export interface RefreshNewDenomInfo {
  count: number;
  value: AmountString;
  feeWithdraw: AmountString;
  denomPub: DenominationPubKey;
  denomPubHash: string;
}

/**
 * Request to derive a refresh session from the refresh session
 * secret seed.
 */
export interface DeriveRefreshSessionRequest {
  exchangeProtocolVersion: ExchangeProtocolVersion;
  sessionSecretSeed: string;
  kappa: number;
  meltCoinPub: string;
  meltCoinPriv: string;
  meltCoinDenomPubHash: string;
  meltCoinMaxAge: number;
  meltCoinAgeCommitmentProof?: AgeCommitmentProof;
  newCoinDenoms: RefreshNewDenomInfo[];
  feeRefresh: AmountJson;
}

/**
 * Request to derive a refresh session from the refresh session
 * public seed.
 *
 * This version is for the improved, PQC-compatible refresh protocol
 * of exchange protocol v27.
 */
export interface DeriveRefreshSessionRequestV2 {
  sessionPublicSeed: string;
  kappa: number;
  meltCoinPub: string;
  meltCoinPriv: string;
  meltCoinDenomPubHash: string;
  meltCoinMaxAge: number;
  meltCoinAgeCommitmentProof?: AgeCommitmentProof;
  newCoinDenoms: RefreshNewDenomInfo[];
  feeRefresh: AmountJson;
  blindingSeed?: string;
  exchangeWithdrawValues?: (ExchangeWithdrawValue | undefined)[];
}

/**
 * Request to derive a refresh session from the refresh session
 * public seed, for the refresh protocol of exchange protocol v32.
 *
 * Same inputs as {@link DeriveRefreshSessionRequestV2}; only the derivation
 * of the fresh coins from the seed differs.
 */
export interface DeriveRefreshSessionRequestV3 {
  sessionPublicSeed: string;
  kappa: number;
  meltCoinPub: string;
  meltCoinPriv: string;
  meltCoinDenomPubHash: string;
  meltCoinMaxAge: number;
  meltCoinAgeCommitmentProof?: AgeCommitmentProof;
  newCoinDenoms: RefreshNewDenomInfo[];
  feeRefresh: AmountJson;
  blindingSeed?: string;
  exchangeWithdrawValues?: (ExchangeWithdrawValue | undefined)[];
}

export interface DerivedRefreshSession {
  /**
   * Public key that's being melted in this session.
   */
  meltCoinPub: string;

  /**
   * Signature to confirm the melting.
   */
  confirmSig: string;

  /**
   * Planchets for each cut-and-choose instance.
   */
  planchets: RefreshPlanchetInfo[][];

  /**
   * The transfer keys, kappa of them.
   */
  transferPubs: string[];

  /**
   * Private keys for the transfer public keys.
   */
  transferPrivs: string[];

  /**
   * Hash of the session.
   */
  hash: string;

  /**
   * Exact value that is being melted.
   */
  meltValueWithFee: AmountJson;
}

export interface DerivedRefreshSessionV2 {
  /**
   * Public key that's being melted in this session.
   */
  meltCoinPub: string;

  /**
   * Signature to confirm the melting.
   */
  confirmSig: string;

  /**
   * Planchets for each cut-and-choose instance.
   */
  planchets: RefreshPlanchetInfo[][];

  /**
   * kappa signatures by the old coin private key.
   */
  signatures: EddsaSignatureString[];

  /**
   * Hash of the session.
   */
  hash: string;

  /**
   * Exact value that is being melted.
   */
  meltValueWithFee: AmountJson;
}

export interface DerivedRefreshSessionV3 {
  /**
   * Public key that's being melted in this session.
   */
  meltCoinPub: string;

  /**
   * Signature to confirm the melting.
   */
  confirmSig: string;

  /**
   * Planchets for each cut-and-choose instance.
   */
  planchets: RefreshPlanchetInfo[][];

  /**
   * kappa batch seeds, one per cut-and-choose instance.  The kappa-1 seeds
   * that are not the noreveal index are disclosed in the reveal step.
   */
  batchSeeds: HashCodeString[];

  /**
   * Transfer public keys, one per fresh coin for each of the kappa
   * cut-and-choose instances.  Sent in the melt step so that the owner of the
   * old coin can recover the fresh coins from the exchange's link data.
   */
  transferPubs: EddsaPublicKeyString[][];

  /**
   * Hash of the session.
   */
  hash: string;

  /**
   * Exact value that is being melted.
   */
  meltValueWithFee: AmountJson;
}

