/**
 * Imports.
 */
import { Amounts } from "./amounts.js";
import { Paytos, PaytoType } from "./payto.js";
import { Result } from "./result.js";

type EncodeResult = { type: "ok"; qrContent: string } | { type: "skip" };

/**
 * Both record formats are newline delimited, so a value carrying a line break
 * would shift every field after it -- including the beneficiary account.  No
 * field of either format may contain a control character anyway.
 */
function qrField(value: string | undefined): string {
  if (value == null) {
    return "";
  }
  // eslint-disable-next-line no-control-regex
  return value.replace(/[\u0000-\u001f\u007f]/g, " ");
}

/**
 * See "Schweizer Implementation Guidelines QR-Rechnung".
 */
function encodePaytoAsSwissQrBill(paytoUri: string): EncodeResult {
  const parsedPayto = Result.orUndefined(Paytos.fromString(paytoUri));
  if (!parsedPayto) {
    throw Error("invalid payto URI");
  }
  if (parsedPayto.targetType !== PaytoType.IBAN) {
    return { type: "skip" };
  }
  let referenceType = "NON";
  let referenceValue = "";
  if (parsedPayto.params["ch-qrr"] != null) {
    referenceType = "QRR";
    referenceValue = parsedPayto.params["ch-qrr"];
  }
  const amountStr = parsedPayto.params["amount"];
  const targetPathParts = parsedPayto.fullPath.split("/");
  const beneficiaryIban = targetPathParts[targetPathParts.length - 1];
  const countryCode = beneficiaryIban.slice(0, 2).toUpperCase();
  if (countryCode !== "CH") {
    // We only show the Swiss payment QR code for Swiss IBANs
    return { type: "skip" };
  }
  const lines = [
    "SPC", // QRType
    "0200", // Version
    "1", // Character set (1: UTF-8)
    beneficiaryIban, // Beneficiary IBAN
    // Group: Beneficiary
    "S", // Address type (S: structured)
    qrField(parsedPayto.params["receiver-name"]), // Beneficiary name
    "", // street
    "", // apt. nr.
    qrField(parsedPayto.params["receiver-postal-code"]), // town, // postal code
    qrField(parsedPayto.params["receiver-town"]), // town
    countryCode, // Country
    // Group: Ultimate Debtor (not used in version 0200)
    "", // Ultimate Debtor Address type (S: structured)
    "", // Ultimate Debtor name
    "", // Ultimate Debtor street
    "", // Ultimate Debtor apt. nr
    "", // Ultimate Debtor postal code
    "", // Ultimate Debtor town
    "", // Ultimate Debtor country
    // Group: Amount
    amountStr === undefined ? "" : Amounts.stringifyValue(amountStr, 2), // Amount
    amountStr === undefined ? "" : Amounts.currencyOf(amountStr), // Currency
    // Group: Debtor
    "", // Address type (S: structured)
    "", // Debtor name
    "", // Debtor street
    "", // Debtor apt. nr
    "", // Debtor postal code
    "", // Debtor town
    "", // Debtor country
    // Group: Reference
    referenceType, // reference type
    qrField(referenceValue), // Reference
    // Group: Additional Information
    qrField(parsedPayto.params["message"]), // Unstructured data
    "EPD", // End of payment data
  ];

  return {
    type: "ok",
    qrContent: lines.join("\n"),
  };
}

/**
 * See "Quick Response Code - Guidelines to
 * Enable the Data Capture for the
 * Initiation of a SEPA Credit Transfer".
 */
function encodePaytoAsEpcQr(paytoUri: string): EncodeResult {
  const parsedPayto = Result.orUndefined(Paytos.fromString(paytoUri));
  if (!parsedPayto) {
    throw Error("invalid payto URI");
  }
  if (parsedPayto.targetType !== PaytoType.IBAN) {
    return { type: "skip" };
  }
  const amountStr = parsedPayto.params["amount"];
  const targetPathParts = parsedPayto.fullPath.split("/");
  const beneficiaryIban = targetPathParts[targetPathParts.length - 1];
  const countryCode = beneficiaryIban.slice(0, 2).toUpperCase();
  switch (countryCode) {
    case "CH":
      // Switzerland has its own QR code, do not generate EPC.
      return { type: "skip" };
  }
  const amt =
    amountStr !== undefined
      ? `${Amounts.currencyOf(amountStr)}${Amounts.stringifyValue(
          amountStr,
          2,
        )}`
      : "";
  const lines = [
    "BCD", // service tag
    "002", // version
    "1", // character set (1: UTF-8)
    "SCT", // Identification
    "", // optional BIC
    qrField(parsedPayto.params["receiver-name"]), // Beneficiary name
    beneficiaryIban, // Beneficiary IBAN
    amt, // Amount (optional)
    "", // AT-44 Purpose
    qrField(parsedPayto.params["message"]), // AT-05 Unstructured remittance information
  ];
  return {
    type: "ok",
    qrContent: lines.join("\n"),
  };
}

// declare const __qr_id: unique symbol;
export type SupportedBankQr = "epc-qr" | "spc"; // & { [__qr_id]: true };
/**
 * Specification of a QR code that includes payment information.
 */
export interface QrCodeSpec {
  /**
   * Type of the QR code.
   *
   * Depending on the type, different visual styles
   * might be applied.
   */
  type: SupportedBankQr;

  /**
   * Content of the QR code that should be rendered.
   */
  qrContent: string;
}

/**
 * Get applicable QR code specifications for the given payto URI.
 */
export function getQrCodesForPayto(paytoUri: string): QrCodeSpec[] {
  const res: QrCodeSpec[] = [];
  {
    const qr = encodePaytoAsEpcQr(paytoUri);
    if (qr.type == "ok") {
      res.push({
        type: "epc-qr",
        qrContent: qr.qrContent,
      });
    }
  }
  {
    const qr = encodePaytoAsSwissQrBill(paytoUri);
    if (qr.type == "ok") {
      res.push({
        type: "spc",
        qrContent: qr.qrContent,
      });
    }
  }
  return res;
}
