import {
  AbsoluteTime,
  AmountString,
  Amounts,
  BatchDepositSuccess,
  Duration,
  EddsaPublicKeyString,
  ExchangePurseStatus,
  ExchangeRefundSuccessResponse,
  HashCodeString,
  PurseCreateSuccessResponse,
  PurseDepositSuccessResponse,
  TalerError,
  TalerErrorCode,
  TalerProtocolTimestamp,
  TrackTransactionWired,
} from "@gnu-taler/taler-util";
import {
  timestampProtocolFromDb,
  WalletExchangeSignkeys,
} from "./db/records.js";
import { WalletExecutionContext } from "./wallet.js";

const signingTimeTolerance = Duration.fromSpec({ hours: 1 });

export function exchangeSigningKeyIsUsable(
  signKeys: WalletExchangeSignkeys[],
  exchangePub: EddsaPublicKeyString,
  signedAt: AbsoluteTime,
): boolean {
  const latestStart = AbsoluteTime.addDuration(signedAt, signingTimeTolerance);
  const earliestExpiry = AbsoluteTime.subtractDuraction(
    signedAt,
    signingTimeTolerance,
  );
  return signKeys.some(
    (key) =>
      key.signkeyPub === exchangePub &&
      AbsoluteTime.cmp(
        AbsoluteTime.fromProtocolTimestamp(
          timestampProtocolFromDb(key.stampStart),
        ),
        latestStart,
      ) <= 0 &&
      AbsoluteTime.cmp(
        AbsoluteTime.fromProtocolTimestamp(
          timestampProtocolFromDb(key.stampExpire),
        ),
        earliestExpiry,
      ) > 0,
  );
}

async function isKnownExchangeSigningKey(
  wex: WalletExecutionContext,
  exchangeBaseUrl: string,
  exchangePub: EddsaPublicKeyString,
  signedAt: AbsoluteTime,
): Promise<boolean> {
  return await wex.runWalletDbTx(async (tx) => {
    const details = await tx.getExchangeDetails(exchangeBaseUrl);
    if (details?.rowId === undefined) {
      return false;
    }
    const signKeys = await tx.getExchangeSignKeysByDetailsRowId(details.rowId);
    return exchangeSigningKeyIsUsable(signKeys, exchangePub, signedAt);
  });
}

function invalidExchangeSignature(message: string): TalerError {
  return TalerError.fromDetail(
    TalerErrorCode.WALLET_TRANSACTION_PROTOCOL_VIOLATION,
    {},
    message,
  );
}

export async function requireValidExchangePurseStatus(
  wex: WalletExecutionContext,
  exchangeBaseUrl: string,
  status: ExchangePurseStatus,
): Promise<void> {
  const [knownKey, signatureResult] = await Promise.all([
    isKnownExchangeSigningKey(
      wex,
      exchangeBaseUrl,
      status.exchange_pub,
      AbsoluteTime.now(),
    ),
    wex.cryptoApi.isValidPurseStatus({
      balance: status.balance,
      depositTimestamp: status.deposit_timestamp,
      mergeTimestamp: status.merge_timestamp,
      exchangePub: status.exchange_pub,
      exchangeSig: status.exchange_sig,
    }),
  ]);
  if (!knownKey || !signatureResult.valid) {
    throw invalidExchangeSignature(
      "exchange returned an invalid purse status signature",
    );
  }
}

async function requireValidExchangePurseConfirmation(
  wex: WalletExecutionContext,
  args: {
    exchangeBaseUrl: string;
    pursePub: string;
    contractTermsHash: HashCodeString;
    purseValueAfterFees: AmountString;
    purseExpiration: TalerProtocolTimestamp;
    response: PurseCreateSuccessResponse;
  },
): Promise<void> {
  const [knownKey, signatureResult] = await Promise.all([
    isKnownExchangeSigningKey(
      wex,
      args.exchangeBaseUrl,
      args.response.exchange_pub,
      AbsoluteTime.fromProtocolTimestamp(args.response.exchange_timestamp),
    ),
    wex.cryptoApi.isValidPurseDepositConfirmation({
      exchangeTimestamp: args.response.exchange_timestamp,
      purseExpiration: args.purseExpiration,
      purseValueAfterFees: args.purseValueAfterFees,
      totalDeposited: args.response.total_deposited,
      pursePub: args.pursePub,
      contractTermsHash: args.contractTermsHash,
      exchangePub: args.response.exchange_pub,
      exchangeSig: args.response.exchange_sig,
    }),
  ]);
  if (!knownKey || !signatureResult.valid) {
    throw invalidExchangeSignature(
      "exchange returned an invalid purse-deposit confirmation signature",
    );
  }
}

/** Verify the confirmation returned by a purse-creation endpoint. */
export async function requireValidExchangePurseCreateConfirmation(
  wex: WalletExecutionContext,
  args: {
    exchangeBaseUrl: string;
    pursePub: string;
    contractTermsHash: HashCodeString;
    purseValueAfterFees: AmountString;
    purseExpiration: TalerProtocolTimestamp;
    response: PurseCreateSuccessResponse;
  },
): Promise<void> {
  await requireValidExchangePurseConfirmation(wex, args);
}

/** Verify the richer confirmation returned when adding to a purse. */
export async function requireValidExchangePurseDepositConfirmation(
  wex: WalletExecutionContext,
  args: {
    exchangeBaseUrl: string;
    pursePub: string;
    contractTermsHash: HashCodeString;
    purseValueAfterFees: AmountString;
    purseExpiration: TalerProtocolTimestamp;
    response: PurseDepositSuccessResponse;
  },
): Promise<void> {
  if (
    args.response.h_contract_terms !== args.contractTermsHash ||
    Amounts.cmp(
      args.response.purse_value_after_fees,
      args.purseValueAfterFees,
    ) !== 0 ||
    args.response.purse_expiration.t_s !== args.purseExpiration.t_s
  ) {
    throw invalidExchangeSignature(
      "exchange purse-deposit confirmation does not match the purse contract",
    );
  }
  await requireValidExchangePurseConfirmation(wex, args);
}

