import { WalletExecutionContext } from "./wallet.js";

const logger = new Logger("mailbox.ts");
export const MAX_MAILBOX_REFRESH_BATCHES = 100;

export function mailboxBatchMayHaveMoreMessages(
  numMessages: number,
  responseLimit: number,
): boolean {
  return numMessages >= responseLimit;
}

export function mailboxMetadataMatchesAddress(
  mailboxAddress: string,
  metadata: MailboxMetadata,
): boolean {
  return (
    encodeCrock(sha512(decodeCrock(metadata.signing_key))) === mailboxAddress
  );
}

/**
 * Add message to the database.
 */
export async function addMailboxMessage(
  wex: WalletExecutionContext,
  req: AddMailboxMessageRequest,
): Promise<EmptyObject> {
  await wex.runWalletDbTx(async (tx) => {
    await tx.upsertMailboxMessage(req.message);
    tx.notify({
      type: NotificationType.MailboxMessageAdded,
      message: req.message,
    });
  });
  return {};
}

/**
 * Delete message from the database.
 */
export async function deleteMailboxMessage(
  wex: WalletExecutionContext,
  req: DeleteMailboxMessageRequest,
): Promise<EmptyObject> {
  await wex.runWalletDbTx(async (tx) => {
    await tx.deleteMailboxMessage(
      req.message.originMailboxBaseUrl,
      req.message.talerUri,
    );
    tx.notify({
      type: NotificationType.MailboxMessageDeleted,
      message: req.message,
    });
  });
  return {};
}

/**
 * Get messages from the database.
 */
export async function listMailboxMessages(
  wex: WalletExecutionContext,
  req: EmptyObject,
): Promise<MailboxMessagesResponse> {
  const messages = await wex.runWalletDbTx(async (tx) => {
    return await tx.listMailboxMessages();
  });
  return { messages: messages };
}

/**
 * Register or update mailbox
 */
export async function registerMailbox(
  wex: WalletExecutionContext,
  mailboxConf: MailboxConfiguration,
): Promise<MailboxRegisterResult> {
  const privateSigningKey = decodeCrock(mailboxConf.privateKey);
  const signingKey = eddsaGetPublic(privateSigningKey);
  const encryptionKey = hpkeSecretKeyGetPublic(
    decodeCrock(mailboxConf.privateEncryptionKey),
  );
  // Message header: 8 byte + 64 byte SHA512 digest to sign
  // We hash encKtype|encKey|expiration
  const messageHeader = new ArrayBuffer(8);
  const expNboBuffer = new ArrayBuffer(8);
  const vMsg = new DataView(messageHeader);
  const vExpNbo = new DataView(expNboBuffer);
  if (mailboxConf.expiration.t_s == "never") {
    throw TalerError.fromDetail(
      TalerErrorCode.WALLET_MAILBOX_UNAVAILABLE,
      { mailboxBaseUrl: mailboxConf.mailboxBaseUrl },
      "a mailbox registration must have an expiration",
    );
  }
  vExpNbo.setBigUint64(0, BigInt(mailboxConf.expiration.t_s));
  const digestBuffer = new Uint8Array([
    ...stringToBytes("X25519"),
    ...encryptionKey,
    ...new Uint8Array(expNboBuffer),
  ]);
  const digest = sha512(digestBuffer);
  vMsg.setUint32(0, messageHeader.byteLength + digest.length);
  vMsg.setUint32(4, TalerSignaturePurpose.MAILBOX_REGISTER);
  const msgToSign = new Uint8Array([
    ...new Uint8Array(messageHeader),
    ...digest,
  ]);
  const signature = eddsaSign(msgToSign, privateSigningKey);
  const info: MailboxMetadata = {
    signing_key: encodeCrock(signingKey),
    signing_key_type: "EdDSA", // FIXME only supported key type ATM,
    encryption_key: encodeCrock(encryptionKey),
    encryption_key_type: "X25519", // FIXME only supported encryption key type ATM
    expiration: mailboxConf.expiration,
  };
  const req: MailboxRegisterRequest = {
    mailbox_metadata: info,
    signature: encodeCrock(signature),
  };
  const mailboxClient = new TalerMailboxInstanceHttpClient(
    mailboxConf.mailboxBaseUrl,
    wex.http,
  );

  const resp = await mailboxClient.registerMailbox(req);
  switch (resp.case) {
    case "ok":
      return resp.body;
    case HttpStatusCode.Forbidden:
      throw TalerError.fromDetail(
        TalerErrorCode.GENERIC_FORBIDDEN,
        {},
        "the mailbox service refused the registration",
      );
    case HttpStatusCode.PaymentRequired:
      return resp.body;
  }
}

/**
 * Get mailbox from the database.
 */
export async function getMailbox(
  wex: WalletExecutionContext,
  mailboxBaseUrl: MailboxBaseUrl,
): Promise<GetMailboxResponse> {
  return await wex.runWalletDbTx(async (tx) => {
    return {
      mailboxConfiguration: await tx.getMailboxConfiguration(
        mailboxBaseUrl.mailboxBaseUrl,
      ),
    };
  });
}

/**
 * Create new mailbox configuration locally and
 * try to register it.
 */
export async function createNewMailbox(
  wex: WalletExecutionContext,
  mailboxBaseUrl: MailboxBaseUrl,
): Promise<MailboxConfiguration> {
  const keys = createEddsaKeyPair();
  const hpkeKey = encodeCrock(hpkeCreateSecretKey());
  const privKey = encodeCrock(keys.eddsaPriv);
  const hAddress = encodeCrock(sha512(keys.eddsaPub));
  const nowInAYear = AbsoluteTime.addDuration(
    AbsoluteTime.now(),
    Duration.fromSpec({
      years: 1,
    }),
  );
  const mailboxConf: MailboxConfiguration = {
    mailboxBaseUrl: mailboxBaseUrl.mailboxBaseUrl,
    privateKey: privKey,
    privateEncryptionKey: hpkeKey,
    hAddress: hAddress,
    expiration: AbsoluteTime.toProtocolTimestamp(nowInAYear),
  };

  const resp = await registerMailbox(wex, mailboxConf);
  if (resp.status == "payment-required") {
    if (!resp.talerUri) {
      throw TalerError.fromDetail(
        TalerErrorCode.WALLET_RECEIVED_MALFORMED_RESPONSE,
        {
          requestUrl: mailboxConf.mailboxBaseUrl,
          requestMethod: "POST",
          httpStatusCode: HttpStatusCode.PaymentRequired,
        },
        "the mailbox service asked for payment but did not say how to pay",
      );
    }
    mailboxConf.payUri = Result.orElse(
      TalerUris.parse(resp.talerUri),
      undefined,
    );
  }
  await wex.runWalletDbTx(async (tx) => {
    return await tx.upsertMailboxConfiguration(mailboxConf);
  });
  return mailboxConf;
}

function decryptTalerUriMessage(
  sk: Uint8Array,
  msg: Uint8Array,
): string | undefined {
  const header = new Uint8Array(msg.slice(0, 4));
  const ct = new Uint8Array(msg.slice(4));
  const uri = hpkeOpenOneshot(
    sk,
    stringToBytes("mailbox-message"),
    header, // AAD
    ct,
  );
  if (!uri) {
    return undefined;
  }
  // Find start of padding
  const padIdx = uri.indexOf(0x00);
  if (-1 === padIdx) {
    return new TextDecoder().decode(uri);
  }
  return new TextDecoder().decode(uri.slice(0, padIdx));
}

/**
 * Refresh mailbox through HTTP
 */
export async function refreshMailbox(
  wex: WalletExecutionContext,
  mailboxConf: MailboxConfiguration,
): Promise<MailboxMessageRecordsResponse> {
  const mailboxClient = new TalerMailboxInstanceHttpClient(
    mailboxConf.mailboxBaseUrl,
    wex.http,
  );
  // Refresh message size
  var message_size;
  var message_response_limit;
  const resConf = await mailboxClient.getConfig();
  switch (resConf.case) {
    case "ok":
      message_size = resConf.body.message_body_bytes;
      message_response_limit = resConf.body.message_response_limit;
      break;
    default:
      throw TalerError.fromDetail(
        TalerErrorCode.WALLET_MAILBOX_UNAVAILABLE,
        { mailboxBaseUrl: mailboxConf.mailboxBaseUrl },
        "could not read the configuration of the mailbox service",
      );
  }
  if (
    !Number.isSafeInteger(message_response_limit) ||
    message_response_limit <= 0
  ) {
    throw TalerError.fromDetail(
      TalerErrorCode.WALLET_RECEIVED_MALFORMED_RESPONSE,
      {
        requestUrl: mailboxConf.mailboxBaseUrl,
        requestMethod: "GET",
        httpStatusCode: HttpStatusCode.Ok,
      },
      "mailbox service advertised an invalid message response limit",
    );
  }

  const hpkeSk: Uint8Array = decodeCrock(mailboxConf.privateEncryptionKey);
  const privateSigningKey: Uint8Array = decodeCrock(mailboxConf.privateKey);
  const records: MailboxMessageRecord[] = [];
  for (
    let batchIndex = 0;
    batchIndex < MAX_MAILBOX_REFRESH_BATCHES;
    batchIndex++
  ) {
    const res = await mailboxClient.getMessages({
      hMailbox: mailboxConf.hAddress,
    });
    if (res.case !== "ok") {
      throw TalerError.fromDetail(
        TalerErrorCode.WALLET_MAILBOX_UNAVAILABLE,
        { mailboxBaseUrl: mailboxConf.mailboxBaseUrl },
        "the mailbox service did not return the messages",
      );
    }

    const messages = res.body.messages;
    const now = TalerProtocolTimestamp.now();
    if (messages.byteLength % message_size !== 0) {
      throw TalerError.fromDetail(
        TalerErrorCode.WALLET_RECEIVED_MALFORMED_RESPONSE,
        {
          requestUrl: mailboxConf.mailboxBaseUrl,
          requestMethod: "GET",
          httpStatusCode: HttpStatusCode.Ok,
        },
        `mailbox messages response is not a multiple of the message size (${messages.byteLength} % ${message_size} != 0)`,
      );
    }
    const numMessages = messages.byteLength / message_size;
    if (numMessages === 0) {
      return { messages: records };
    }

    for (let i = 0; i < numMessages; i++) {
      const offset = i * message_size;
      const msg: Uint8Array = messages.slice(offset, offset + message_size);
      const uri = decryptTalerUriMessage(hpkeSk, msg);
      if (!uri) {
        logger.warn(`unable to decrypt message number ${i}`);
        continue;
      }
      const newMessage = {
        originMailboxBaseUrl: mailboxConf.mailboxBaseUrl,
        talerUri: uri,
        downloadedAt: now,
      };
      records.push(newMessage);
      await addMailboxMessage(wex, { message: newMessage });
    }

    const messageBuffer = new ArrayBuffer(16);
    const vMsg = new DataView(messageBuffer);
    vMsg.setUint32(0, 4 * 4);
    vMsg.setUint32(4, TalerSignaturePurpose.MAILBOX_MESSAGES_DELETE);
    vMsg.setUint32(8, parseInt(res.body.etag));
    vMsg.setUint32(12, numMessages);
    const signature = eddsaSign(
      new Uint8Array(messageBuffer),
      privateSigningKey,
    );
    succeedOrThrow(
      await mailboxClient.deleteMessages({
        mailboxConf,
        matchIf: res.body.etag,
        count: numMessages,
        signature: encodeCrock(signature),
      }),
    );

    if (!mailboxBatchMayHaveMoreMessages(numMessages, message_response_limit)) {
      return { messages: records };
    }
  }
  logger.warn(
    `mailbox refresh stopped after ${MAX_MAILBOX_REFRESH_BATCHES} full batches`,
  );
  return { messages: records };
}

function encryptTalerUriMessage(
  encryptionKey: Uint8Array,
  talerUri: string,
  paddedMessageSize: number,
): Uint8Array {
  // Padding must not include HPKE tag and encapsulation overhead
  // FIXME CRYPTO-AGILITY size of tag and encapsulation depends on used algos
  // DHKEM X25519: Encapsuation 32 bytes, Poly1305 tag 16 bytes
  const talerUriBytes = stringToBytes(talerUri);
  const paddingLength = paddedMessageSize - 4 - talerUriBytes.length - 16 - 32;
  if (paddingLength < 0) {
    throw TalerError.fromDetail(
      TalerErrorCode.WALLET_MAILBOX_UNAVAILABLE,
      {},
      "the taler:// URI does not fit into a message of this mailbox service",
    );
  }
  const header = new Uint8Array(4);
  const v = new DataView(header.buffer);
  v.setUint32(0, 0); // FIXME message type, derive number from crypto!
  const msg = new Uint8Array(talerUriBytes.length + paddingLength);
  msg.set(talerUriBytes, 0);
  const encryptedMessage = hpkeSealOneshot(
    encryptionKey,
    stringToBytes("mailbox-message"),
    header,
    msg,
  );
  const result = new Uint8Array(header.length + encryptedMessage.length);
  result.set(header, 0);
  result.set(encryptedMessage, header.length);
  return result;
}

export async function sendTalerUriMessage(
  wex: WalletExecutionContext,
  req: SendTalerUriMailboxMessageRequest,
): Promise<EmptyObject> {
  const mailboxClient = new TalerMailboxInstanceHttpClient(
    req.contact.mailboxBaseUri,
    wex.http,
  );
  // Get message size
  var paddedMessageSize;
  const resConf = await mailboxClient.getConfig();
  switch (resConf.case) {
    case "ok":
      paddedMessageSize = resConf.body.message_body_bytes;
      break;
    default:
      throw TalerError.fromDetail(
        TalerErrorCode.WALLET_MAILBOX_UNAVAILABLE,
        { mailboxBaseUrl: req.contact.mailboxBaseUri },
        "could not read the configuration of the mailbox service",
      );
  }
  const resKeys = await mailboxClient.getMailboxInfo(
    req.contact.mailboxAddress,
  );
  var keys;
  switch (resKeys.case) {
    case "ok":
      keys = resKeys.body;
      break;
    default:
      throw TalerError.fromDetail(
        TalerErrorCode.WALLET_MAILBOX_UNAVAILABLE,
        { mailboxBaseUrl: req.contact.mailboxBaseUri },
        "could not read the keys of the recipient's mailbox",
      );
  }
  if (!mailboxMetadataMatchesAddress(req.contact.mailboxAddress, keys)) {
    throw TalerError.fromDetail(
      TalerErrorCode.WALLET_MAILBOX_UNAVAILABLE,
      { mailboxBaseUrl: req.contact.mailboxBaseUri },
      "the mailbox service returned keys for a different mailbox address",
    );
  }
  const encryptedMessage = encryptTalerUriMessage(
    decodeCrock(keys.encryption_key),
    req.talerUri,
    paddedMessageSize,
  );
  const resSend = await mailboxClient.sendMessage({
    h_address: req.contact.mailboxAddress,
    body: encryptedMessage,
  });
  switch (resSend.case) {
    case "ok":
      return {};
    default:
      throw TalerError.fromDetail(
        TalerErrorCode.WALLET_MAILBOX_UNAVAILABLE,
        { mailboxBaseUrl: req.contact.mailboxBaseUri },
        "the mailbox service did not accept the message",
      );
  }
}
