export class ConfigError extends Error {
  constructor(message: string) {
    super();
    Object.setPrototypeOf(this, ConfigError.prototype);
    this.name = "ConfigError";
    this.message = message;
  }
}

enum EntryOrigin {
  /**
   * From a default file.
   */
  DefaultFile = 1,
  /**
   * From a system/installation specific default value.
   */
  DefaultSystem = 2,
  /**
   * Loaded from file or string
   */
  Loaded = 3,
  /**
   * Changed after loading
   */
  Changed = 4,
}

interface Entry {
  /**
   * Option name as it was first written.  Lookups are case insensitive, but
   * write-back overwrites the user's own file and must not respell it.
   */
  name: string;
  value: string;
  sourceLine: number;
  sourceFile: string;
  origin: EntryOrigin;
}

interface Section {
  /**
   * Section name as it was first written; see Entry.name.
   */
  name: string;
  secretFilename?: string;
  inaccessible: boolean;
  entries: { [optionName: string]: Entry };
}

type SectionMap = { [sectionName: string]: Section };

