/**
 * Imports.
 */
import { codecForAmountString } from "./amounts.js";
import {
  Codec,
  buildCodecForObject,
  codecForString,
  codecOptional,
} from "./codec.js";
import { TalerProtocolTimestamp } from "./time.js";
import { AmountString, EddsaSignatureString } from "./types-taler-common.js";

/**
 * Status of a reserve.
 *
 * Schema type for the exchange's response to "/reserve/status".
 */
export interface ReserveStatus {
  /**
   * Balance left in the reserve.
   */
  balance: AmountString;

  /**
   * Full payto URI of the bank account that
   * (most recently) funded this reserve.
   * Useful as a hint for deposit operations for wallets.
   * Missing if this reserve was only filled via P2P merges.
   * @since protocol **v23**.
   */
  last_origin?: string;
}

export const codecForReserveStatus = (): Codec<ReserveStatus> =>
  buildCodecForObject<ReserveStatus>()
    .property("balance", codecForAmountString())
    .property("last_origin", codecOptional(codecForString()))
    .build("ReserveStatus");

export interface ReserveCloseRequest {
  reserve_sig: EddsaSignatureString;
  request_timestamp: TalerProtocolTimestamp;
  payto_uri?: string;
}

export interface ReserveCloseResponse {
  wire_amount: AmountString;
}

export const codecForReserveCloseResponse = (): Codec<ReserveCloseResponse> =>
  buildCodecForObject<ReserveCloseResponse>()
    .property("wire_amount", codecForAmountString())
    .build("ReserveCloseResponse");
