import {
  createCipheriv,
  createDecipheriv,
  createHash,
  createHmac,
  createPrivateKey,
  createPublicKey,
  diffieHellman,
  sign,
  verify,
} from "node:crypto";
import { Buffer } from "node:buffer";

// RFC 8410 PKCS#8 / SPKI prefixes for raw Ed25519 and X25519 keys.
const ed25519Pkcs8Prefix = Uint8Array.from([
  0x30, 0x2e, 0x02, 0x01, 0x00, 0x30, 0x05, 0x06, 0x03, 0x2b, 0x65, 0x70, 0x04,
  0x22, 0x04, 0x20,
]);
const ed25519SpkiPrefix = Uint8Array.from([
  0x30, 0x2a, 0x30, 0x05, 0x06, 0x03, 0x2b, 0x65, 0x70, 0x03, 0x21, 0x00,
]);
const x25519Pkcs8Prefix = Uint8Array.from([
  0x30, 0x2e, 0x02, 0x01, 0x00, 0x30, 0x05, 0x06, 0x03, 0x2b, 0x65, 0x6e, 0x04,
  0x22, 0x04, 0x20,
]);
const x25519SpkiPrefix = Uint8Array.from([
  0x30, 0x2a, 0x30, 0x05, 0x06, 0x03, 0x2b, 0x65, 0x6e, 0x03, 0x21, 0x00,
]);

function checkLength(value: Uint8Array, length: number, name: string): void {
  if (value.byteLength !== length) {
    throw new Error(`bad ${name} size: ${value.byteLength}`);
  }
}

function privateKey(prefix: Uint8Array, rawKey: Uint8Array) {
  checkLength(rawKey, 32, "private key");
  return createPrivateKey({
    key: Buffer.concat([prefix, rawKey]),
    format: "der",
    type: "pkcs8",
  });
}

function publicKey(prefix: Uint8Array, rawKey: Uint8Array) {
  checkLength(rawKey, 32, "public key");
  return createPublicKey({
    key: Buffer.concat([prefix, rawKey]),
    format: "der",
    type: "spki",
  });
}

function rawPublicKey(der: Uint8Array): Uint8Array {
  return new Uint8Array(der.subarray(der.byteLength - 32));
}

export function hashSha256(data: Uint8Array): Uint8Array {
  return new Uint8Array(createHash("sha256").update(data).digest());
}

export function hashSha512(data: Uint8Array): Uint8Array {
  return new Uint8Array(createHash("sha512").update(data).digest());
}

export function hmacSha256(key: Uint8Array, message: Uint8Array): Uint8Array {
  return new Uint8Array(createHmac("sha256", key).update(message).digest());
}

export function hmacSha512(key: Uint8Array, message: Uint8Array): Uint8Array {
  return new Uint8Array(createHmac("sha512", key).update(message).digest());
}

export function eddsaGetPublic(seed: Uint8Array): Uint8Array {
  const privateKeyObject = privateKey(ed25519Pkcs8Prefix, seed);
  const der = createPublicKey(privateKeyObject).export({
    format: "der",
    type: "spki",
  });
  return rawPublicKey(der);
}

export function eddsaSign(message: Uint8Array, seed: Uint8Array): Uint8Array {
  return new Uint8Array(
    sign(null, message, privateKey(ed25519Pkcs8Prefix, seed)),
  );
}

export function eddsaVerify(
  message: Uint8Array,
  signature: Uint8Array,
  rawPublicKey: Uint8Array,
): boolean {
  checkLength(signature, 64, "signature");
  return verify(
    null,
    message,
    publicKey(ed25519SpkiPrefix, rawPublicKey),
    signature,
  );
}

export function x25519GetPublic(rawPrivateKey: Uint8Array): Uint8Array {
  const privateKeyObject = privateKey(x25519Pkcs8Prefix, rawPrivateKey);
  const der = createPublicKey(privateKeyObject).export({
    format: "der",
    type: "spki",
  });
  return rawPublicKey(der);
}

export function x25519(
  rawPrivateKey: Uint8Array,
  rawPublicKey: Uint8Array,
): Uint8Array {
  return new Uint8Array(
    diffieHellman({
      privateKey: privateKey(x25519Pkcs8Prefix, rawPrivateKey),
      publicKey: publicKey(x25519SpkiPrefix, rawPublicKey),
    }),
  );
}

export function chacha20Poly1305Encrypt(
  message: Uint8Array,
  additionalData: Uint8Array,
  nonce: Uint8Array,
  key: Uint8Array,
): Uint8Array {
  checkLength(key, 32, "key");
  checkLength(nonce, 12, "nonce");
  const cipher = createCipheriv("chacha20-poly1305", key, nonce, {
    authTagLength: 16,
  });
  cipher.setAAD(additionalData, { plaintextLength: message.byteLength });
  return new Uint8Array(
    Buffer.concat([
      cipher.update(message),
      cipher.final(),
      cipher.getAuthTag(),
    ]),
  );
}

export function chacha20Poly1305Decrypt(
  ciphertext: Uint8Array,
  additionalData: Uint8Array,
  nonce: Uint8Array,
  key: Uint8Array,
): Uint8Array | undefined {
  checkLength(key, 32, "key");
  checkLength(nonce, 12, "nonce");
  if (ciphertext.byteLength < 16) {
    return undefined;
  }
  const tagOffset = ciphertext.byteLength - 16;
  const encrypted = ciphertext.subarray(0, tagOffset);
  const tag = ciphertext.subarray(tagOffset);
  try {
    const decipher = createDecipheriv("chacha20-poly1305", key, nonce, {
      authTagLength: 16,
    });
    decipher.setAAD(additionalData, { plaintextLength: encrypted.byteLength });
    decipher.setAuthTag(tag);
    return new Uint8Array(
      Buffer.concat([decipher.update(encrypted), decipher.final()]),
    );
  } catch {
    return undefined;
  }
}

export interface Sha512Context {
  update(data: Uint8Array): void;
  finish(): Uint8Array;
}

export function createSha512Context(): Sha512Context {
  const hash = createHash("sha512");
  let digest: Uint8Array | undefined;
  return {
    update(data: Uint8Array): void {
      if (digest) {
        throw new Error("SHA-512 context is already finalized");
      }
      hash.update(data);
    },
    finish(): Uint8Array {
      digest ??= new Uint8Array(hash.digest());
      return new Uint8Array(digest);
    },
  };
}
