import { getRandomBytes } from "./taler-crypto.js";

const encTable = "ABCDEFGHIJKLMNOPQRSTUVWXYZ234567";

/**
 * base32 RFC 3548
 */
export function encodeRfc3548Base32(data: ArrayBuffer | ArrayBufferView) {
  let dataBytes: Uint8Array;
  if (ArrayBuffer.isView(data)) {
    dataBytes = new Uint8Array(data.buffer, data.byteOffset, data.byteLength);
  } else {
    dataBytes = new Uint8Array(data);
  }
  let sb = "";
  const size = data.byteLength;
  let bitBuf = 0;
  let numBits = 0;
  let pos = 0;
  while (pos < size || numBits > 0) {
    if (pos < size && numBits < 5) {
      const d = dataBytes[pos++];
      bitBuf = (bitBuf << 8) | d;
      numBits += 8;
    }
    if (numBits < 5) {
      // zero-padding
      bitBuf = bitBuf << (5 - numBits);
      numBits = 5;
    }
    const v = (bitBuf >>> (numBits - 5)) & 31;
    sb += encTable[v];
    numBits -= 5;
  }
  return sb;
}

export function isRfc3548Base32Charset(s: string): boolean {
  for (let idx = 0; idx < s.length; idx++) {
    const c = s.charAt(idx);
    if (encTable.indexOf(c) === -1) return false;
  }
  return true;
}

/**
 * Normalize a manually entered 160-bit OTP key.
 *
 * Whitespace is ignored so that a key copied in groups remains usable.  Other
 * punctuation is rejected instead of being silently discarded.
 */
export function normalizeRfc3548Base32Key(s: string): string | undefined {
  const normalized = s.toUpperCase().replace(/\s/g, "");
  if (normalized.length !== 32 || !isRfc3548Base32Charset(normalized)) {
    return undefined;
  }
  return normalized;
}

export function randomRfc3548Base32Key(): string {
  const buf = getRandomBytes(20);
  return encodeRfc3548Base32(buf);
}
