import { Logger, WalletNotification } from "@gnu-taler/taler-util";
import {
  WalletDbAccessStats,
  WalletDbHandle,
  WalletDbImportFinalizer,
} from "../handle.js";
import { WalletDbTransaction } from "../transaction.js";
import {
  clearNativeSqliteWalletDb,
  exportNativeSqliteDb,
  importNativeSqliteDb,
  NativeSqliteWalletDb,
  runNativeSqliteWalletTx,
} from "./database.js";

const logger = new Logger("db/sqlite/handle.ts");

function notifySafely(
  sink: (notification: WalletNotification) => void,
  notification: WalletNotification,
): void {
  try {
    sink(notification);
  } catch (e) {
    logger.warn(
      `ignoring exception from wallet notification sink: ${
        e instanceof Error ? e.message : String(e)
      }`,
    );
  }
}

/** WalletDbHandle over the native sqlite database. */
export class SqliteWalletDbHandle implements WalletDbHandle {
  readonly name = "sqlite";

  private notify: (n: WalletNotification) => void = () => {};

  setNotificationSink(sink: (n: WalletNotification) => void): void {
    this.notify = sink;
  }

  emitNotification(notification: WalletNotification): void {
    notifySafely(this.notify, notification);
  }

  constructor(private ndb: NativeSqliteWalletDb) {}

  async exportToFile(
    directory: string,
    stem: string,
    forceFormat?: string,
  ): Promise<{ path: string }> {
    if (forceFormat != null && forceFormat !== "sqlite3") {
      throw Error(
        `the native backend can only export sqlite3, not ${forceFormat}`,
      );
    }
    const path = `${directory}/${stem}.sqlite3`;
    await this.ndb.lock.run(async () => {
      await (
        await this.ndb.db.prepare("VACUUM INTO $filename")
      ).run({
        filename: path,
      });
    });
    return { path };
  }

  getDiagnosticStats(): unknown {
    return { rowsRead: this.ndb.stats.rowsRead };
  }

  async runReadWriteTx<T>(
    f: (tx: WalletDbTransaction) => Promise<T>,
  ): Promise<T> {
    return await runNativeSqliteWalletTx(
      this.ndb,
      (n) => this.emitNotification(n),
      async (tx) => await f(tx),
    );
  }

  async exportDatabase(): Promise<any> {
    return await exportNativeSqliteDb(this.ndb);
  }

  async importDatabase(
    dump: any,
    finalize: WalletDbImportFinalizer,
  ): Promise<void> {
    if (dump != null && typeof dump === "object" && "databases" in dump) {
      throw Error(
        "this dump is from the IndexedDB backend and cannot be imported" +
          " into the native sqlite backend; convert the database instead",
      );
    }
    await importNativeSqliteDb(this.ndb, dump, finalize, (n) =>
      this.emitNotification(n),
    );
  }

  async clearDatabase(): Promise<void> {
    await clearNativeSqliteWalletDb(this.ndb);
  }

  getAccessStats(): WalletDbAccessStats | undefined {
    return { recordsRead: this.ndb.stats.rowsRead };
  }

  async close(): Promise<void> {
    await this.ndb.db.close();
  }
}
