const EXIT_API_ERROR = 5;
const EXIT_INPUT_REQUIRED = 6;
const EXIT_TIMEOUT = 7;
const EXIT_TX_UNSUCCESSFUL = 8;

/**
 * Run the body of a command, turning what it throws into a message and
 * an exit code.
 *
 * Without this, an error from wallet-core ends up as a raw exception dump
 * from the argument parser.
 */
async function runCliAction(f: () => Promise<number | void>): Promise<void> {
  let code: number;
  try {
    code = (await f()) ?? 0;
  } catch (e) {
    if (e instanceof CliUsageError) {
      console.error(`error: ${e.message}`);
      if (e.hint) {
        console.error(`  ${e.hint}`);
      }
      code = EXIT_USAGE;
    } else {
      const ed = getErrorDetailFromException(e);
      console.error(`error: ${summarizeTalerErrorDetail(ed)}`);
      if (ed.hint) {
        console.error(`  ${ed.hint}`);
      }
      if (logger.shouldLogTrace()) {
        console.error(JSON.stringify(ed, undefined, 2));
      }
      code =
        ed.code === TalerErrorCode.WALLET_UNEXPECTED_EXCEPTION
          ? EXIT_EXCEPTION
          : EXIT_API_ERROR;
    }
  }
  // Only exit once the wallet has been shut down cleanly.
  if (code !== 0) {
    processExit(code);
  }
}

setUnhandledRejectionHandler((error: any) => {
  logger.error("unhandledRejection", error.message);
  logger.error("stack", error.stack);
  processExit(1);
});

