let machineSafeStdout = false;

function diagnosticLog(...args: unknown[]): void {
  if (machineSafeStdout) {
    console.error(...args);
  } else {
    console.log(...args);
  }
}

async function doHandlePayTransaction(
  ctx: WalletContext,
  transactionId: TransactionIdStr,
  options: PayOptions,
): Promise<void> {
  const wallet = ctx.client;
  await wallet.call(WalletApiOperation.TestingWaitTransactionState, {
    transactionId,
    txState: "nonpending",
  });
  const paySt = await wallet.call(WalletApiOperation.GetTransactionById, {
    transactionId,
  });
  if (paySt.type !== TransactionType.Payment) {
    throw Error("unexpected transaction type");
  }
  if (paySt.txState.major === TransactionMajorState.Done) {
    diagnosticLog(`Payment succeeded (already done).`);
    return;
  }
  if (paySt.txState.major === TransactionMajorState.Expired) {
    diagnosticLog(`Payment expired.`);
    return;
  }
  if (paySt.txState.major === TransactionMajorState.Aborted) {
    diagnosticLog(`Payment aborted.`);
    return;
  }
  if (paySt.txState.major === TransactionMajorState.Finalizing) {
    diagnosticLog(`Payment finalizing (${paySt.txState.minor})`);
    return;
  }
  if (
    paySt.txState.major === TransactionMajorState.Failed &&
    paySt.txState.minor === TransactionMinorState.Repurchase
  ) {
    diagnosticLog(`Repurchase detected (${[paySt.repurchaseTransactionId]})`);
    if (paySt.repurchaseTransactionId != null) {
      diagnosticLog(`Waiting for old transaction to be final.`);
      await wallet.call(WalletApiOperation.TestingWaitTransactionState, {
        transactionId: paySt.repurchaseTransactionId,
        txState: {
          major: TransactionMajorState.Done,
          minor: "*",
        },
      });
      diagnosticLog(`Transaction done.`);
    }
    return;
  }
  if (paySt.txState.major === TransactionMajorState.Failed) {
    diagnosticLog(`Payment failed.`);
    return;
  }
  if (paySt.txState.major === TransactionMajorState.Dialog) {
    // Same step as "continue-tx" on this transaction, so that the two
    // entry points cannot drift apart.
    const res = await performConfirmPayment(ctx, transactionId, {
      yes: options.alwaysYes ?? false,
      acceptTos: false,
      choiceIndex: options.choiceIndex,
    });
    if (res.exitCode !== 0) {
      processExit(res.exitCode);
    }
    if (options.noWait) {
      return;
    }
    diagnosticLog(`Waiting for transaction '${transactionId}' to finish`);
    await wallet.call(WalletApiOperation.TestingWaitTransactionState, {
      transactionId,
      txState: "nonpending",
    });
    const tx = await wallet.call(WalletApiOperation.GetTransactionById, {
      transactionId,
    });
    diagnosticLog(`Finished with status '${tx.txState.major}'.`);
  }
}

async function doPayTemplate(
  ctx: WalletContext,
  payUrl: string,
  options: PayOptions = {},
): Promise<void> {
  const r = await ctx.client.call(WalletApiOperation.PreparePayForTemplateV2, {
    talerPayTemplateUri: payUrl,
  });
  await doHandlePayTransaction(ctx, r.transactionId, options);
}

async function doPay(
  ctx: WalletContext,
  payUrl: string,
  options: PayOptions = {},
): Promise<void> {
  const r = await ctx.client.call(WalletApiOperation.PreparePayForUriV2, {
    talerPayUri: payUrl,
  });
  await doHandlePayTransaction(ctx, r.transactionId, options);
}

async function doPaivana(
  ctx: WalletContext,
  url: string,
  modeString: string,
  options: PayOptions,
): Promise<void> {
  let mode;
  try {
    mode = parsePaivanaOutputMode(modeString);
  } catch (e) {
    throw new CliUsageError(e instanceof Error ? e.message : String(e));
  }

  machineSafeStdout = true;
  try {
    const prepared = await ctx.client.call(
      WalletApiOperation.PreparePayForPaivana,
      { url },
    );
    await doHandlePayTransaction(ctx, prepared.transactionId, options);
    const { cookie } = await ctx.client.call(
      WalletApiOperation.GetPaivanaCookie,
      {
        transactionId: prepared.transactionId,
        paivana: prepared.paivana,
      },
    );

    switch (mode.type) {
      case "curl":
        console.log(makePaivanaCurlCommand(cookie, prepared.paivana.url));
        return;
      case "cookie":
        console.log(cookie);
        return;
      case "body": {
        const http = createPlatformHttpLib({ enableThrottling: false });
        const response = await http.fetch(prepared.paivana.url, {
          headers: { Cookie: cookie },
          redirect: "follow",
        });
        if (response.status < 200 || response.status >= 300) {
          throw TalerError.fromDetail(
            TalerErrorCode.WALLET_UNEXPECTED_REQUEST_ERROR,
            {
              requestUrl: response.requestUrl,
              requestMethod: response.requestMethod,
              httpStatusCode: response.status,
            },
            `protected resource returned HTTP status ${response.status}`,
          );
        }
        const bytes = await response.bytes();
        if (mode.path === "-") {
          await new Promise<void>((resolve, reject) => {
            process.stdout.write(bytes, (err) =>
              err ? reject(err) : resolve(),
            );
          });
          return;
        }
        const path =
          mode.path ??
          selectAvailableFilename(
            paivanaBodyFilename(prepared.paivana.url),
            fs.existsSync,
          );
        fs.writeFileSync(path, bytes);
        diagnosticLog(`Saved protected resource to '${path}'.`);
        return;
      }
    }
  } finally {
    machineSafeStdout = false;
  }
}

let globalNonInteractive = false;
let globalInteractive = false;

/**
 * Reject interactivity flags that can't be honored.
 *
 * Called from both flag handlers, since either one may come first.
 */
function validateInteractivity(): void {
  if (globalInteractive && globalNonInteractive) {
    console.error(
      "error: --interactive and --non-interactive are mutually exclusive",
    );
    processExit(EXIT_USAGE);
  }
  if (globalInteractive && !process.stdin.isTTY) {
    console.error("error: --interactive requires stdin to be a terminal");
    processExit(EXIT_USAGE);
  }
}

function isNonInteractive(): boolean {
  // An explicit --interactive outranks the environment, which is
  // otherwise easy to inherit by accident.
  if (globalInteractive) {
    return false;
  }
  return (
    globalNonInteractive ||
    checkEnvFlag("TALER_WALLET_NONINTERACTIVE") ||
    !process.stdin.isTTY
  );
}

/**
 * Ask the user something, unless nobody is there to answer.
 *
 * Without this, a command run from a script blocks forever
 * instead of reporting that it needs input.
 */
async function promptOrFail(question: string): Promise<string> {
  if (isNonInteractive()) {
    console.error(
      `error: input required, but running non-interactively: ${question}`,
    );
    processExit(EXIT_INPUT_REQUIRED);
  }
  if (!machineSafeStdout) {
    return await readlinePrompt(question);
  }
  const prompt = readline.createInterface({
    input: process.stdin,
    output: process.stderr,
  });
  return await new Promise<string>((resolve) => {
    prompt.question(question, (answer) => {
      prompt.close();
      resolve(answer);
    });
  });
}

async function askChoice(n: number): Promise<number> {
  while (true) {
    const choice = Number.parseInt(
      await promptOrFail(`Select choice (0-${n - 1}):`),
    );
    if (choice >= 0 && choice < n) {
      return choice;
    } else {
      diagnosticLog("Please enter a valid choice.");
    }
  }
}

async function askYesNo(question: string = "Pay?"): Promise<boolean> {
  while (true) {
    const yesNoResp = (await promptOrFail(`${question} [Y/n]`)).toLowerCase();
    if (yesNoResp === "" || yesNoResp === "y" || yesNoResp === "yes") {
      return true;
    } else if (yesNoResp === "n" || yesNoResp === "no") {
      return false;
    } else {
      diagnosticLog("please answer y/n");
    }
  }
}

