function addApiCommand(
  parent: any,
  argKey: string,
  name: string,
  mark?: clk.CommandMark,
): void {
  parent
    .subcommand(argKey, name, {
      help: "Call the wallet-core API directly.",
      mark,
    })
    .requiredArgument("operation", clk.STRING)
    .requiredArgument("request", clk.STRING)
    .flag("expectSuccess", ["--expect-success"], {
      help: "Exit with non-zero status code when request fails instead of returning error JSON.",
    })
    .action(async (args: any) => {
      const a = args[argKey];
      // Exit only after withWallet returned, so that the wallet
      // is shut down cleanly.
      await runCliAction(() =>
        withWallet(args, {}, async (wallet) => {
          let requestJson;
          logger.info(`handling 'api' request (${a.operation})`);
          const jsonContent = a.request.startsWith("@")
            ? readFile(a.request.substring(1))
            : a.request;
          try {
            requestJson = JSON.parse(jsonContent);
          } catch (e) {
            throw new CliUsageError("invalid JSON in request");
          }
          try {
            const resp = await wallet.makeCoreApiRequest(
              a.operation,
              requestJson,
            );
            console.log(JSON.stringify(resp, undefined, 2));
            if (resp.type === "error") {
              if (a.expectSuccess) {
                return EXIT_API_ERROR;
              }
              logger.warn("api request resulted in error response");
            }
          } catch (e) {
            logger.error(`Got exception while handling API request ${e}`);
            return EXIT_EXCEPTION;
          }
          logger.info("finished handling API request");
          return 0;
        }),
      );
    });
}

