/**
 * States that a transaction does not leave on its own and that
 * mean that it did not succeed.
 */
const UNSUCCESSFUL_STATE_PATTERNS: TransactionStatePattern[] = [
  { major: TransactionMajorState.Failed, minor: "*", working: "*" },
  { major: TransactionMajorState.Aborted, minor: "*", working: "*" },
  { major: TransactionMajorState.Expired, minor: "*", working: "*" },
];

interface WaitTxRequest {
  transactionId: TransactionIdStr;
  txState: TestingWaitTxStateSpec;
  /**
   * Timeout in milliseconds, or undefined to wait forever.
   */
  timeoutMs?: number;
  bailStates?: TransactionStatePattern[];
  bailOnError?: boolean;
  requireError?: boolean;
  logId?: string;
}

type WaitTxOutcome =
  | { result: "match" | "bail"; txState: TransactionState; stId: number }
  | { result: "timeout" };

/**
 * Wait until a transaction reaches one of the states we're interested in.
 *
 * The timeout is passed to wallet-core (which cancels the waiter, so that
 * nothing is left behind in a wallet that keeps running) and additionally
 * raced here, in case the wallet does not answer at all.
 */
async function waitForTxState(
  ctx: WalletContext,
  req: WaitTxRequest,
): Promise<WaitTxOutcome> {
  const timeoutMs = req.timeoutMs;
  const deadline =
    timeoutMs == null
      ? undefined
      : AbsoluteTime.addDuration(
          AbsoluteTime.now(),
          Duration.fromMilliseconds(timeoutMs),
        );
  // Give wallet-core's own timeout a head start, so that it is normally
  // the one that ends the wait.
  const graceMs =
    timeoutMs == null ? 0 : Math.min(5000, Math.max(1000, timeoutMs / 10));
  let timer: ReturnType<typeof setTimeout> | undefined;
  const clientTimeout = new Promise<"timeout">((resolve) => {
    if (timeoutMs != null) {
      timer = setTimeout(() => resolve("timeout"), timeoutMs + graceMs);
    }
  });
  try {
    const res = await Promise.race([
      ctx.client.call(WalletApiOperation.TestingWaitTransactionState, {
        transactionId: req.transactionId,
        txState: req.txState,
        bailStates: req.bailStates,
        bailOnError: req.bailOnError,
        requireError: req.requireError,
        logId: req.logId,
        timeout:
          timeoutMs == null
            ? undefined
            : { seconds: Math.ceil(timeoutMs / 1000) },
      }),
      clientTimeout,
    ]);
    if (res === "timeout") {
      return { result: "timeout" };
    }
    return {
      result: res.matched === "bail" ? "bail" : "match",
      txState: res.txState,
      stId: res.stId,
    };
  } catch (e) {
    const ed = getErrorDetailFromException(e);
    // Older wallets report the timeout as a plain exception, hence the
    // fallback to our own deadline.
    if (
      ed.code === TalerErrorCode.GENERIC_TIMEOUT ||
      (deadline != null && AbsoluteTime.isExpired(deadline))
    ) {
      return { result: "timeout" };
    }
    throw e;
  } finally {
    if (timer != null) {
      clearTimeout(timer);
    }
  }
}

async function lookupTxOrNull(
  ctx: WalletContext,
  transactionId: TransactionIdStr,
): Promise<Transaction | undefined> {
  try {
    return await ctx.client.call(WalletApiOperation.GetTransactionById, {
      transactionId,
    });
  } catch (e) {
    // The transaction might have been deleted while we were waiting.
    logger.warn(`could not look up transaction: ${e}`);
    return undefined;
  }
}

/**
 * Which of the requested patterns did the transaction match?
 *
 * Undefined for the shorthands and for a state ID, which don't
 * name a single pattern.
 */
function findMatchingPattern(
  spec: TestingWaitTxStateSpec,
  st: TransactionState,
): TransactionStatePattern | undefined {
  if (typeof spec === "string" || typeof spec === "number") {
    return undefined;
  }
  const pats = Array.isArray(spec) ? spec : [spec];
  return pats.find((pat) => matchTransactionState(st, pat));
}

function txDetailsForJson(tx: Transaction | undefined): unknown {
  if (tx == null) {
    return null;
  }
  return {
    type: tx.type,
    txState: tx.txState,
    stId: tx.stId,
    txActions: tx.txActions,
    amountRaw: tx.amountRaw,
    amountEffective: tx.amountEffective,
    timestamp: tx.timestamp,
    error: tx.error ?? null,
    abortReason: tx.abortReason ?? null,
    failReason: tx.failReason ?? null,
    kycUrl: tx.kycUrl ?? null,
    kycAccessToken: tx.kycAccessToken ?? null,
  };
}

interface WaitTxArgs {
  transactionId: string;
  state?: string;
  stid?: number;
  timeout?: string;
  failOn?: string;
  logId?: string;
  requireError: boolean;
  json: boolean;
  follow: boolean;
  quiet: boolean;
}

async function runWaitTx(
  cliArgs: WalletCliArgsType,
  a: WaitTxArgs,
): Promise<number> {
  if (a.stid != null && a.state != null) {
    throw new CliUsageError("--state and --stid are mutually exclusive");
  }
  const txState: TestingWaitTxStateSpec =
    a.stid != null ? a.stid : parseTxStateSpec(a.state ?? "final");
  const timeout = a.timeout != null ? parseTimeoutSpec(a.timeout) : "forever";
  const timeoutMs = timeout === "forever" ? undefined : timeout;
  let bailStates: TransactionStatePattern[] | undefined;
  let bailOnError: boolean | undefined;
  switch (a.failOn ?? "unsuccessful") {
    case "unsuccessful":
      bailStates = UNSUCCESSFUL_STATE_PATTERNS;
      break;
    case "error":
      bailOnError = true;
      break;
    case "both":
      bailStates = UNSUCCESSFUL_STATE_PATTERNS;
      bailOnError = true;
      break;
    case "none":
      break;
    default:
      throw new CliUsageError(
        `invalid value '${a.failOn}' for --fail-on`,
        "expected 'unsuccessful', 'error', 'both' or 'none'",
      );
  }
  return await withWallet(cliArgs, { lazyTaskLoop: false }, async (ctx) => {
    const transactionId = await resolveTxRef(ctx, a.transactionId);
    let cancelFollow: (() => void) | undefined;
    if (a.follow) {
      cancelFollow = ctx.addNotificationListener((n) => {
        if (
          n.type === NotificationType.TransactionStateTransition &&
          n.transactionId === transactionId
        ) {
          console.error(JSON.stringify(n));
        }
      });
    }
    const start = AbsoluteTime.now();
    let outcome: WaitTxOutcome;
    try {
      outcome = await waitForTxState(ctx, {
        transactionId,
        txState,
        timeoutMs,
        bailStates,
        bailOnError,
        requireError: a.requireError ? true : undefined,
        logId: a.logId,
      });
    } finally {
      if (cancelFollow != null) {
        cancelFollow();
      }
    }
    const waitedMs = Duration.toMilliseconds(
      AbsoluteTime.difference(start, AbsoluteTime.now()),
    );
    const tx = await lookupTxOrNull(ctx, transactionId);
    const state = outcome.result === "timeout" ? tx?.txState : outcome.txState;
    const matchedPattern =
      outcome.result === "match" && state != null
        ? findMatchingPattern(txState, state)
        : undefined;

    if (a.json) {
      console.log(
        JSON.stringify(
          {
            result: outcome.result,
            transactionId,
            waitedMs,
            requestedState: txState,
            matchedPattern: matchedPattern ?? null,
            transaction: txDetailsForJson(tx),
          },
          undefined,
          2,
        ),
      );
    }

    if (!a.quiet && !a.json) {
      const stateStr = state != null ? formatTxState(state) : "unknown";
      switch (outcome.result) {
        case "match":
          console.log(
            `matched ${stateStr} after ${(waitedMs / 1000).toFixed(1)}s`,
          );
          break;
        case "bail":
          console.error(
            `gave up: transaction is in ${stateStr} after ${(
              waitedMs / 1000
            ).toFixed(1)}s`,
          );
          break;
        case "timeout":
          console.error(
            `timeout: waited ${(waitedMs / 1000).toFixed(
              1,
            )}s for ${formatTxStateSpec(txState)}`,
          );
          console.error(`last observed state: ${stateStr}`);
          break;
      }
      if (tx != null) {
        if (outcome.result !== "match") {
          console.error(`possible actions: ${tx.txActions.join(", ")}`);
        }
        for (const [label, ed] of [
          ["error", tx.error],
          ["abort reason", tx.abortReason],
          ["fail reason", tx.failReason],
        ] as const) {
          if (ed != null) {
            console.error(`${label}: ${summarizeTalerErrorDetail(ed)}`);
            if (ed.hint) {
              console.error(`  hint: ${ed.hint}`);
            }
          }
        }
        if (tx.kycUrl != null) {
          console.log(`kyc required: ${tx.kycUrl}`);
        }
      }
    }

    switch (outcome.result) {
      case "match":
        return 0;
      case "bail":
        return EXIT_TX_UNSUCCESSFUL;
      case "timeout":
        return EXIT_TIMEOUT;
    }
  });
}

/**
 * Options that commands creating a transaction share, so that
 * they can be used non-interactively without a second command.
 */
interface CreateWaitArgs {
  wait: boolean;
  timeout?: string;
}

/**
 * Wait for a transaction that the command just created, if --wait
 * was given.  Returns the exit code for the command.
 */
async function waitForCreatedTx(
  ctx: WalletContext,
  transactionId: TransactionIdStr,
  a: CreateWaitArgs,
): Promise<number> {
  if (!a.wait) {
    return 0;
  }
  const timeout = a.timeout != null ? parseTimeoutSpec(a.timeout) : "forever";
  const outcome = await waitForTxState(ctx, {
    transactionId,
    txState: "final",
    timeoutMs: timeout === "forever" ? undefined : timeout,
  });
  if (outcome.result === "timeout") {
    console.error(`timeout: transaction ${transactionId} is not finished`);
    return EXIT_TIMEOUT;
  }
  console.log(
    `transaction ${transactionId} finished in state ${formatTxState(
      outcome.txState,
    )}`,
  );
  const unsuccessful = UNSUCCESSFUL_STATE_PATTERNS.some((pat) =>
    matchTransactionState(outcome.txState, pat),
  );
  return unsuccessful ? EXIT_TX_UNSUCCESSFUL : 0;
}

/**
 * States at which a deposit no longer needs the CLI to keep running.  A
 * deposit can take a long time to become final while its wire transfer is
 * being tracked, so finalizing is sufficient here.  KYC and suspended states
 * need action outside the wallet task loop and therefore also end the wait.
 */
const DEPOSIT_FINAL_STATE_PATTERNS: TransactionStatePattern[] = [
  { major: TransactionMajorState.Done, minor: "*", working: "*" },
  { major: TransactionMajorState.Failed, minor: "*", working: "*" },
  { major: TransactionMajorState.Aborted, minor: "*", working: "*" },
  { major: TransactionMajorState.Expired, minor: "*", working: "*" },
  { major: TransactionMajorState.Deleted, minor: "*", working: "*" },
];

const DEPOSIT_USER_ACTION_STATE_PATTERNS: TransactionStatePattern[] = [
  {
    major: TransactionMajorState.SuspendedFinalizing,
    minor: "*",
    working: "*",
  },
  { major: TransactionMajorState.Suspended, minor: "*", working: "*" },
  {
    major: TransactionMajorState.SuspendedAborting,
    minor: "*",
    working: "*",
  },
  { major: TransactionMajorState.Dialog, minor: "*", working: "*" },
  { major: "*", minor: TransactionMinorState.KycRequired, working: "*" },
  {
    major: "*",
    minor: TransactionMinorState.KycAuthRequired,
    working: "*",
  },
];

const DEPOSIT_WAIT_STATE_PATTERNS: TransactionStatePattern[] = [
  ...DEPOSIT_FINAL_STATE_PATTERNS,
  { major: TransactionMajorState.Finalizing, minor: "*", working: "*" },
  ...DEPOSIT_USER_ACTION_STATE_PATTERNS,
];

interface DepositWaitArgs {
  noWait: boolean;
  timeout?: string;
}

/**
 * Wait for a newly created deposit until it is final, finalizing, or needs
 * action from the user.  Returns the exit code for the command.
 */
async function waitForCreatedDepositTx(
  ctx: WalletContext,
  transactionId: TransactionIdStr,
  a: DepositWaitArgs,
): Promise<number> {
  if (a.noWait) {
    return 0;
  }
  const timeout = a.timeout != null ? parseTimeoutSpec(a.timeout) : "forever";
  const outcome = await waitForTxState(ctx, {
    transactionId,
    txState: DEPOSIT_WAIT_STATE_PATTERNS,
    timeoutMs: timeout === "forever" ? undefined : timeout,
  });
  if (outcome.result === "timeout") {
    console.error(`timeout: transaction ${transactionId} did not finish`);
    return EXIT_TIMEOUT;
  }
  console.log(
    `transaction ${transactionId} reached state ${formatTxState(
      outcome.txState,
    )}`,
  );
  const unsuccessful = UNSUCCESSFUL_STATE_PATTERNS.some((pat) =>
    matchTransactionState(outcome.txState, pat),
  );
  if (unsuccessful) {
    return EXIT_TX_UNSUCCESSFUL;
  }
  const requiresUserAction = DEPOSIT_USER_ACTION_STATE_PATTERNS.some((pat) =>
    matchTransactionState(outcome.txState, pat),
  );
  if (requiresUserAction) {
    const tx = await lookupTxOrNull(ctx, transactionId);
    if (tx?.kycUrl != null) {
      console.log(`kyc required: ${tx.kycUrl}`);
    }
    return EXIT_INPUT_REQUIRED;
  }
  return 0;
}

/**
 * Answers that a continuation may need, supplied on the command line
 * so that it also works without a terminal.
 */
interface ContinuationOptions {
  yes: boolean;
  acceptTos: boolean;
  choiceIndex?: number;
  exchange?: string;
  amount?: string;
  restrictAge?: number;
}

interface PerformResult {
  performed: boolean;
  exitCode: number;
}

const NOT_PERFORMED: PerformResult = { performed: false, exitCode: 0 };
const PERFORMED: PerformResult = { performed: true, exitCode: 0 };
const NEEDS_INPUT: PerformResult = {
  performed: false,
  exitCode: EXIT_INPUT_REQUIRED,
};

type Confirmation = "yes" | "no" | "input-required";

/**
 * Ask for a go-ahead, saying which flag would have given it when
 * there is nobody to ask.
 */
async function confirmContinuation(
  question: string,
  opts: ContinuationOptions,
): Promise<Confirmation> {
  if (opts.yes) {
    return "yes";
  }
  if (isNonInteractive()) {
    console.error(`error: confirmation required: ${question}`);
    console.error("  pass --yes to confirm without being asked");
    return "input-required";
  }
  return (await askYesNo(question)) ? "yes" : "no";
}

/**
 * Accept the exchange's terms of service, if they are still pending.
 *
 * Returns false if the user did not accept them, in which case the
 * continuation cannot go ahead.
 */
async function settleTos(
  ctx: WalletContext,
  exchangeBaseUrl: string | undefined,
  opts: ContinuationOptions,
): Promise<boolean> {
  if (exchangeBaseUrl == null) {
    return true;
  }
  const ok = await cliHandleTos(ctx, exchangeBaseUrl, {
    autoAccept: opts.acceptTos,
  });
  if (!ok) {
    console.error(
      `error: the terms of service of ${exchangeBaseUrl} have to be accepted first`,
    );
  }
  return ok;
}

/**
 * Pick a contract choice and pay, asking whoever is there to ask.
 */
async function performConfirmPayment(
  ctx: WalletContext,
  transactionId: TransactionIdStr,
  opts: ContinuationOptions,
): Promise<PerformResult> {
  const choices = await ctx.client.call(
    WalletApiOperation.GetChoicesForPayment,
    { transactionId },
  );
  let choiceIndex: number;
  if (opts.choiceIndex != null) {
    choiceIndex = opts.choiceIndex;
  } else if (choices.choices.length > 1) {
    if (isNonInteractive()) {
      console.error(
        `error: the offer has ${choices.choices.length} choices; pass --choice-index`,
      );
      console.error(j2s(choices));
      return { performed: false, exitCode: EXIT_INPUT_REQUIRED };
    }
    diagnosticLog(`${j2s(choices)}`);
    choiceIndex = await askChoice(choices.choices.length);
  } else {
    choiceIndex = 0;
    diagnosticLog("contract:", choices.contractTerms);
  }
  const myChoice = choices.choices[choiceIndex];
  if (myChoice == null) {
    throw new CliUsageError(
      `no choice with index ${choiceIndex}`,
      `the offer has ${choices.choices.length} choice(s)`,
    );
  }
  if (myChoice.status !== ChoiceSelectionDetailType.PaymentPossible) {
    console.error("error: insufficient balance for the selected choice");
    return { performed: false, exitCode: EXIT_API_ERROR };
  }
  switch (await confirmContinuation("Pay?", opts)) {
    case "input-required":
      return NEEDS_INPUT;
    case "no":
      diagnosticLog("not paying");
      return NOT_PERFORMED;
  }
  await ctx.client.call(WalletApiOperation.ConfirmPay, {
    transactionId,
    choiceIndex,
    useDonau: true,
  });
  return PERFORMED;
}

/**
 * Supply the exchange and amount that a withdrawal is waiting for.
 */
async function performConfirmWithdrawal(
  ctx: WalletContext,
  transactionId: TransactionIdStr,
  opts: ContinuationOptions,
): Promise<PerformResult> {
  let exchangeBaseUrl = opts.exchange;
  if (exchangeBaseUrl == null) {
    if (isNonInteractive()) {
      console.error(
        "error: the withdrawal has no exchange yet; pass --exchange",
      );
      return { performed: false, exitCode: EXIT_INPUT_REQUIRED };
    }
    const known = await ctx.client.call(WalletApiOperation.ListExchanges, {});
    for (const exch of known.exchanges) {
      console.log(`  ${exch.exchangeBaseUrl} (${exch.currency ?? "?"})`);
    }
    exchangeBaseUrl = (await promptOrFail("Exchange base URL: ")).trim();
  }
  if (exchangeBaseUrl === "") {
    console.error("error: no exchange given");
    return { performed: false, exitCode: EXIT_INPUT_REQUIRED };
  }
  if (!(await settleTos(ctx, exchangeBaseUrl, opts))) {
    return NOT_PERFORMED;
  }
  switch (
    await confirmContinuation(`Withdraw from ${exchangeBaseUrl}?`, opts)
  ) {
    case "input-required":
      return NEEDS_INPUT;
    case "no":
      console.log("not withdrawing");
      return NOT_PERFORMED;
  }
  let amount: AmountString | undefined;
  if (opts.amount != null) {
    // clk.AMOUNT does not validate, so a typo would only surface as a
    // wallet-core error about a malformed request.
    try {
      amount = Amounts.stringify(Amounts.parseOrThrow(opts.amount));
    } catch {
      throw new CliUsageError(`invalid amount '${opts.amount}'`);
    }
  }
  await ctx.client.call(WalletApiOperation.ConfirmWithdrawal, {
    transactionId,
    exchangeBaseUrl,
    amount,
    restrictAge: opts.restrictAge,
  });
  return PERFORMED;
}

/**
 * Do whatever the transaction is waiting for, if it is something that
 * wallet-core can be asked to do.
 */
async function performContinuation(
  ctx: WalletContext,
  tx: Transaction,
  cont: Continuation,
  opts: ContinuationOptions,
): Promise<PerformResult> {
  const transactionId = tx.transactionId;
  switch (cont.kind) {
    case ContinuationKind.Resume:
      await ctx.client.call(WalletApiOperation.ResumeTransaction, {
        transactionId,
      });
      return PERFORMED;
    case ContinuationKind.ConfirmPayment:
      return await performConfirmPayment(ctx, transactionId, opts);
    case ContinuationKind.ConfirmWithdrawal:
      return await performConfirmWithdrawal(ctx, transactionId, opts);
    case ContinuationKind.ConfirmPeerPushCredit: {
      if (!(await settleTos(ctx, cont.tosExchangeBaseUrl, opts))) {
        return NOT_PERFORMED;
      }
      switch (
        await confirmContinuation(
          `Accept payment of ${tx.amountEffective}?`,
          opts,
        )
      ) {
        case "input-required":
          return NEEDS_INPUT;
        case "no":
          console.log("not accepting");
          return NOT_PERFORMED;
      }
      await ctx.client.call(WalletApiOperation.ConfirmPeerPushCredit, {
        transactionId,
      });
      return PERFORMED;
    }
    case ContinuationKind.ConfirmPeerPullDebit: {
      switch (
        await confirmContinuation(`Pay invoice of ${tx.amountEffective}?`, opts)
      ) {
        case "input-required":
          return NEEDS_INPUT;
        case "no":
          console.log("not paying");
          return NOT_PERFORMED;
      }
      await ctx.client.call(WalletApiOperation.ConfirmPeerPullDebit, {
        transactionId,
      });
      return PERFORMED;
    }
    default:
      // Everything else is either nothing to do or somebody else's job.
      return NOT_PERFORMED;
  }
}

/**
 * Look up the terms of service status, so that the continuation can say
 * whether they are in the way.
 */
async function lookupTosStatus(
  ctx: WalletContext,
  exchangeBaseUrl: string,
): Promise<ExchangeTosStatus | undefined> {
  try {
    const exch = await ctx.client.call(
      WalletApiOperation.GetExchangeEntryByUrl,
      { exchangeBaseUrl },
    );
    return exch.tosStatus;
  } catch (e) {
    // Only used to describe the continuation, so a missing entry is
    // not worth failing the command over.
    logger.warn(`could not look up exchange ${exchangeBaseUrl}: ${e}`);
    return undefined;
  }
}

/**
 * Work out what a transaction needs, consulting the exchange when the
 * answer depends on its terms of service.
 */
async function continuationForTx(
  ctx: WalletContext,
  tx: Transaction,
): Promise<Continuation> {
  const first = computeContinuation(tx);
  if (!first.automatic || first.tosExchangeBaseUrl == null) {
    return first;
  }
  const tosStatus = await lookupTosStatus(ctx, first.tosExchangeBaseUrl);
  return computeContinuation(tx, { tosStatus });
}

interface ContinueTxArgs extends CreateWaitArgs {
  transactionId: string;
  yes: boolean;
  acceptTos: boolean;
  dryRun: boolean;
  choiceIndex?: number;
  exchange?: string;
  amount?: string;
  restrictAge?: number;
  json: boolean;
  quiet: boolean;
}

function reportContinuation(cont: Continuation, tx: Transaction): void {
  console.log(`transaction is in state ${formatTxState(tx.txState)}`);
  console.log(cont.summary);
  if (cont.requiresTos) {
    console.log(
      `the terms of service of ${cont.tosExchangeBaseUrl} have to be accepted first`,
    );
  }
  for (const [key, value] of Object.entries(cont.details ?? {})) {
    if (value != null) {
      console.log(
        `  ${key}: ${typeof value === "string" ? value : j2s(value)}`,
      );
    }
  }
}

async function runContinueTx(
  cliArgs: WalletCliArgsType,
  a: ContinueTxArgs,
): Promise<number> {
  const opts: ContinuationOptions = {
    yes: a.yes,
    acceptTos: a.acceptTos,
    choiceIndex: a.choiceIndex,
    exchange: a.exchange,
    amount: a.amount,
    restrictAge: a.restrictAge,
  };
  return await withWallet(cliArgs, { lazyTaskLoop: false }, async (ctx) => {
    const transactionId = await resolveTxRef(ctx, a.transactionId);
    const tx = await ctx.client.call(WalletApiOperation.GetTransactionById, {
      transactionId,
    });
    const cont = await continuationForTx(ctx, tx);

    let result: PerformResult = NOT_PERFORMED;
    if (cont.actionable && cont.automatic && !a.dryRun) {
      result = await performContinuation(ctx, tx, cont, opts);
    }

    if (a.json) {
      console.log(
        JSON.stringify(
          {
            transactionId,
            continuation: cont.kind,
            actionable: cont.actionable,
            automatic: cont.automatic,
            performed: result.performed,
            summary: cont.summary,
            requiresTos: cont.requiresTos ?? false,
            tosExchangeBaseUrl: cont.tosExchangeBaseUrl ?? null,
            details: cont.details ?? null,
            transaction: txDetailsForJson(tx),
          },
          undefined,
          2,
        ),
      );
    } else if (!a.quiet) {
      if (a.dryRun || !cont.automatic || !cont.actionable) {
        reportContinuation(cont, tx);
      } else if (result.performed) {
        console.log("transaction continued");
      }
    }

    if (result.exitCode !== 0) {
      return result.exitCode;
    }
    // Nothing the wallet can do about it, so say so with the exit code
    // instead of pretending that the transaction was continued.
    if (cont.actionable && !cont.automatic) {
      return EXIT_INPUT_REQUIRED;
    }
    if (!result.performed) {
      return 0;
    }
    return await waitForCreatedTx(ctx, transactionId, a);
  });
}

