async function resolveKnownBankAccountId(
  wallet: WalletContext,
  account: string,
): Promise<string> {
  const { accounts } = await wallet.client.call(
    WalletApiOperation.ListBankAccounts,
    {},
  );
  const matches = accounts.filter(
    (knownAccount) =>
      knownAccount.bankAccountId === account || knownAccount.label === account,
  );
  if (matches.length === 0) {
    throw new CliUsageError(
      `unknown bank account '${account}'`,
      "pass an account ID or the label of an account shown by 'bank-accounts list'",
    );
  }
  if (matches.length > 1) {
    throw new CliUsageError(
      `bank account '${account}' is ambiguous`,
      "use the account ID shown by 'bank-accounts list' instead",
    );
  }
  return matches[0].bankAccountId;
}

