async function resolveDepositPaytoUri(
  wallet: WalletContext,
  amount: AmountString,
  target: string,
): Promise<string> {
  if (target.toLowerCase().startsWith("payto:")) {
    return target;
  }

  const { accounts } = await wallet.client.call(
    WalletApiOperation.ListBankAccounts,
    { currency: Amounts.currencyOf(amount) },
  );
  const matches = accounts.filter((account) => account.label === target);
  if (matches.length === 0) {
    throw new CliUsageError(
      `unknown bank account label '${target}'`,
      "pass a payto URI or the label of an account shown by 'bank-accounts list'",
    );
  }
  if (matches.length > 1) {
    throw new CliUsageError(
      `bank account label '${target}' is ambiguous`,
      "use the account's payto URI instead",
    );
  }
  return matches[0].paytoUri;
}

