/**
 * In-place migration of a wallet database from the IndexedDB emulation to the
 * native schema.
 *
 * Both schemas are sqlite tables and their names do not overlap, so the
 * migration happens inside the one file the wallet already has: nothing is
 * written next to it and nothing is swapped afterwards.  That matters because
 * the platforms this migration exists for -- the mobile wallets -- hand
 * wallet-core a database and no filesystem to put a second one in.
 *
 * The order of operations is what makes an interrupted migration safe.  The
 * emulation's tables are read-only throughout and are renamed out of the way
 * only after the copy has been verified, in the same transaction that records
 * the migration as complete.  So at every instant exactly one of the two
 * schemas is the authoritative copy, and which one it is can be read back
 * from the file:
 *
 * - no idb_migration row: the emulation's tables are the wallet.
 * - status 'running': an attempt was interrupted.  The emulation's tables are
 *   still the wallet; the native tables hold a partial copy and are discarded
 *   when the migration is retried.
 * - status 'complete': the native tables are the wallet.  The emulation's
 *   tables are still in the file under their idb_backup_ names.
 *
 * The backup is kept for {@link MIGRATION_BACKUP_RETENTION} rather than
 * dropped at the end: a migration that copies every record and verifies it can
 * still turn out to have produced a wallet that misbehaves for a reason nobody
 * anticipated, and until that window closes the original is one statement
 * away.  {@link restoreMigrationBackup} is that statement.
 */

import {
  DatabaseMaintenanceProgressNotification,
  Duration,
  getErrorDetailFromException,
  Logger,
  NotificationType,
} from "@gnu-taler/taler-util";
import type { Sqlite3Database } from "@gnu-taler/idb-bridge";

import {
  convertWalletDb,
  DB_CONVERSION_STEP_COUNT,
  DbConversionOptions,
  DbConversionReport,
} from "./converter.js";
import {
  IDB_BACKUP_PREFIX,
  IDB_EMULATION_TABLES,
  NATIVE_DATA_TABLES,
} from "../sqlite/schema.js";
import { SqliteWalletDbHandle } from "../sqlite/handle.js";
import { WalletDbHandle } from "../handle.js";
import {
  clearNativeSqliteWalletDb,
  clearNativeSqliteWalletDbInTransaction,
  openNativeSqliteWalletDb,
  SqliteTxControl,
} from "../sqlite/database.js";

const logger = new Logger("db/migration/native.ts");

/**
 * How long the renamed emulation tables are kept after a successful
 * migration.
 *
 * Long enough that a wallet used every few days gets several chances to
 * expose a problem before the original goes away, short enough that a
 * wallet's storage does not carry two copies of itself indefinitely.
 */
export const MIGRATION_BACKUP_RETENTION = Duration.fromSpec({ months: 1 });

/** The retention as the microseconds the schema's timestamps are in. */
function retentionMicros(): number {
  const ms = MIGRATION_BACKUP_RETENTION.d_ms;
  // fromSpec never yields "forever", but narrowing rather than casting means
  // a retention that later becomes configurable cannot silently overflow into
  // a negative expiry.  MAX_SAFE_INTEGER is this schema's "never".
  return ms === "forever" ? Number.MAX_SAFE_INTEGER : ms * 1000;
}

/** Which schema the records in a wallet database file are stored in. */
export type WalletDbFileKind = "empty" | "indexeddb" | "native" | "ambiguous";

/**
 * Open storage known to have been empty before the IndexedDB bridge was
 * constructed as a native wallet database.
 *
 * Constructing the bridge eagerly creates its six bookkeeping tables even
 * when no wallet has opened it.  Remove that empty scaffolding so selecting
 * native storage for a new wallet is direct initialization, not a zero-record
 * migration with retained backup tables and an authority marker.
 */
export async function openNativeWalletDbForEmptyStorage(
  db: Sqlite3Database,
): Promise<SqliteWalletDbHandle> {
  for (const table of IDB_EMULATION_TABLES) {
    await db.exec(`DROP TABLE IF EXISTS "${table}"`);
  }
  return new SqliteWalletDbHandle(await openNativeSqliteWalletDb(db));
}

/**
 * 'rolled-back' is terminal: the emulation tables were put back by
 * {@link restoreMigrationBackup}, and the wallet does not migrate again on its
 * own, because whoever rolled back did so to stop using the native schema.
 */
export type MigrationStatus = "running" | "complete" | "rolled-back";

export type MigrationBackupStatus = "retained" | "dropped" | "restored";

export interface NativeMigrationInfo {
  status: MigrationStatus;
  /** Microseconds since the epoch, as everywhere in the native schema. */
  startedAt: number;
  finishedAt?: number;
  recordsCopied?: number;
  backupStatus?: MigrationBackupStatus;
  backupExpiresAt?: number;
  /**
   * Whether native rows are known to be only a disposable partial copy.
   * Undefined identifies the released legacy schema from before this column
   * was added; its running marker carried the same cleanup guarantee.
   */
  cleanupSafe?: boolean;
}

export interface WalletDbFileInspection {
  kind: WalletDbFileKind;
  indexedDbRecords: number;
  nativeRecords: number;
  ambiguityReason?: string;
}

/** Current time in the microseconds the native schema's timestamps use. */
function nowMicros(): number {
  return Date.now() * 1000;
}

function backupTableName(table: string): string {
  return `${IDB_BACKUP_PREFIX}${table}`;
}

async function tableExists(
  db: Sqlite3Database,
  name: string,
): Promise<boolean> {
  const row = await (
    await db.prepare(
      "SELECT name FROM sqlite_master WHERE type = 'table' AND name = $name",
    )
  ).getFirst({ name });
  return row != null;
}

/**
 * Read the migration bookkeeping, if this file has any.
 *
 * Tolerates a file that has never seen the native schema: the table itself is
 * absent there, which is not an error but the most common case.
 */
export async function readNativeMigrationInfo(
  db: Sqlite3Database,
): Promise<NativeMigrationInfo | undefined> {
  if (!(await tableExists(db, "idb_migration"))) {
    return undefined;
  }
  const row = await (
    await db.prepare("SELECT * FROM idb_migration WHERE id = 1")
  ).getFirst({});
  if (!row) {
    return undefined;
  }
  const optNum = (v: unknown): number | undefined =>
    v == null ? undefined : Number(v);
  return {
    status: String(row.status) as MigrationStatus,
    startedAt: Number(row.started_at),
    finishedAt: optNum(row.finished_at),
    recordsCopied: optNum(row.records_copied),
    backupStatus: (row.backup_status ?? undefined) as
      | MigrationBackupStatus
      | undefined,
    backupExpiresAt: optNum(row.backup_expires_at),
    cleanupSafe:
      row.cleanup_safe == null ? undefined : Number(row.cleanup_safe) === 1,
  };
}

async function countRows(db: Sqlite3Database, table: string): Promise<number> {
  const row = await (
    await db.prepare(`SELECT COUNT(*) AS n FROM "${table}"`)
  ).getFirst({});
  return Number(row?.n ?? 0);
}

async function countNativeRecords(db: Sqlite3Database): Promise<number> {
  let total = 0;
  for (const table of NATIVE_DATA_TABLES) {
    if (await tableExists(db, table)) total += await countRows(db, table);
  }
  return total;
}

async function countMainIndexedDbRecords(db: Sqlite3Database): Promise<number> {
  if (
    !(await tableExists(db, "object_data")) ||
    !(await tableExists(db, "object_stores"))
  ) {
    return 0;
  }
  const row = await (
    await db.prepare(
      "SELECT COUNT(*) AS n FROM object_data od" +
        " JOIN object_stores os ON os.id = od.object_store_id" +
        " WHERE os.database_name = 'taler-wallet-main-v10'" +
        " OR os.database_name LIKE 'taler-wallet-main-v10-generation-%'",
    )
  ).getFirst({});
  return Number(row?.n ?? 0);
}

export async function inspectWalletDbFileDetails(
  db: Sqlite3Database,
): Promise<WalletDbFileInspection> {
  const info = await readNativeMigrationInfo(db);
  const indexedDbRecords = await countMainIndexedDbRecords(db);
  const nativeRecords = await countNativeRecords(db);
  const result = (kind: WalletDbFileKind, ambiguityReason?: string) => ({
    kind,
    indexedDbRecords,
    nativeRecords,
    ...(ambiguityReason ? { ambiguityReason } : undefined),
  });

  if (info?.status === "complete") return result("native");
  if (info?.status === "running" && info.cleanupSafe !== false)
    return result("indexeddb");
  if (info?.status === "running" && nativeRecords > 0) {
    return result(
      "ambiguous",
      "an untrusted running migration marker coexists with native wallet records",
    );
  }
  if (info?.status === "rolled-back" && nativeRecords > 0) {
    return result(
      "ambiguous",
      "a rolled-back migration still has native wallet records",
    );
  }
  if (indexedDbRecords > 0 && nativeRecords > 0) {
    return result(
      "ambiguous",
      "both IndexedDB and native schemas contain wallet records without a trustworthy authority marker",
    );
  }
  if (await tableExists(db, "object_data")) return result("indexeddb");
  if (await tableExists(db, "schema_migrations")) return result("native");
  return result("empty");
}

/**
 * Decide which schema holds the wallet's records in an open database file.
 *
 * The host has to ask before it opens either backend over the file, because
 * both create their tables with IF NOT EXISTS: opening the wrong one does not
 * fail, it produces an empty wallet.
 */
export async function inspectWalletDbFile(
  db: Sqlite3Database,
): Promise<WalletDbFileKind> {
  return (await inspectWalletDbFileDetails(db)).kind;
}

/**
 * Run f inside one native sqlite transaction on db.
 *
 * The migration owns the connection while it runs, so it does not go through
 * the wallet's transaction queue; it does need the same explicit
 * BEGIN/COMMIT, since exec() would commit implicitly between statements.
 */
async function inTransaction(
  txc: SqliteTxControl,
  f: () => Promise<void>,
): Promise<void> {
  await txc.begin();
  try {
    await f();
    await txc.commit();
  } catch (e) {
    try {
      await txc.rollback();
    } catch (rollbackErr) {
      logger.warn(`rollback failed: ${rollbackErr}`);
    }
    throw e;
  }
}

export interface NativeMigrationResult {
  handle: SqliteWalletDbHandle;
  report: DbConversionReport;
  info: NativeMigrationInfo;
}

/**
 * Migrate the wallet records in db from the emulation to the native schema.
 *
 * `src` must be the open IndexedDB-emulation handle over the same connection:
 * opening it is what replays the fixup log, so the records this copies are
 * already repaired -- the native schema has no fixup log of its own.
 *
 * Returns the handle the wallet is to use from here on.  The caller keeps
 * using `src` if this throws: nothing destructive has happened, and the file
 * still opens as an emulation database.
 */
export async function migrateWalletDbToNative(
  db: Sqlite3Database,
  src: WalletDbHandle,
  conversionOptions: DbConversionOptions = {},
): Promise<NativeMigrationResult> {
  conversionOptions.cancellationToken?.throwIfCancelled();
  // Read this before native initialization upgrades the schema.  A running
  // marker written by versions before cleanup_safe existed is trustworthy:
  // those versions also cleared the native tables before recording it.  Once
  // migration 7 adds the column its DEFAULT 0 deliberately cannot make that
  // distinction for us anymore.
  const previous = await readNativeMigrationInfo(db);
  const previousPartialIsCleanupSafe =
    previous?.status === "running" && previous.cleanupSafe !== false;

  const ndb = await openNativeSqliteWalletDb(db);
  conversionOptions.cancellationToken?.throwIfCancelled();
  const dst = new SqliteWalletDbHandle(ndb);
  const txc = ndb.txc;

  if (previous?.status === "complete") {
    throw Error(
      "this wallet database has already been migrated to the native schema",
    );
  }
  if (previous?.status === "rolled-back") {
    throw Error(
      "this wallet database was rolled back to the IndexedDB schema and is" +
        " not migrated again automatically",
    );
  }
  if (previous?.status === "running") {
    if (previousPartialIsCleanupSafe) {
      logger.warn(
        previous.cleanupSafe === undefined
          ? "discarding the partial copy left by an interrupted legacy migration attempt"
          : "discarding the cleanup-safe partial copy left by an interrupted migration attempt",
      );
      await clearNativeSqliteWalletDb(ndb);
    } else if ((await countNativeRecords(db)) !== 0) {
      throw Error(
        "migration refused: an untrusted running marker has native wallet records; use db-migration-resolve after making a backup",
      );
    }
  } else if ((await countNativeRecords(db)) !== 0) {
    throw Error(
      "migration refused: the native schema already contains wallet records; use db-migration-resolve after making a backup",
    );
  }

  const startedAt = nowMicros();
  conversionOptions.cancellationToken?.throwIfCancelled();
  await ndb.lock.run(() =>
    inTransaction(txc, async () => {
      if ((await countNativeRecords(db)) !== 0) {
        throw Error(
          "migration refused: native wallet records appeared before cleanup ownership could be recorded",
        );
      }
      await (
        await db.prepare(
          "INSERT INTO idb_migration (id, status, started_at, cleanup_safe)" +
            " VALUES (1, 'running', $started_at, 1)" +
            " ON CONFLICT (id) DO UPDATE SET status = 'running'," +
            " started_at = $started_at, finished_at = NULL," +
            " records_copied = NULL, backup_status = NULL," +
            " backup_expires_at = NULL, cleanup_safe = 1",
        )
      ).run({ started_at: startedAt });
    }),
  );

  let lastProgress: DatabaseMaintenanceProgressNotification | undefined;
  try {
    logger.info("migrating the wallet database to the native schema");
    // Verifies its own copy record by record and throws on any difference, so
    // reaching the next statement means the native tables hold the wallet.
    const report = await convertWalletDb(src, dst, {
      ...conversionOptions,
      onProgress(notification) {
        lastProgress = notification;
        conversionOptions.onProgress?.(notification);
      },
    });

    conversionOptions.cancellationToken?.throwIfCancelled();

    await ndb.lock.run(async () => {
      const violations = await (
        await db.prepare("PRAGMA foreign_key_check")
      ).getAll({});
      if (violations.length !== 0) {
        throw Error(
          `migration refused: native foreign-key validation found ${violations.length} violation(s)`,
        );
      }
    });

    conversionOptions.cancellationToken?.throwIfCancelled();

    const finishedAt = nowMicros();
    const backupExpiresAt = finishedAt + retentionMicros();

    // One transaction: the renames and the record of them being done cannot come
    // apart.  A crash between them would leave a file whose emulation tables are
    // gone and whose bookkeeping still says the emulation is authoritative, and
    // the retry would then wipe the only remaining copy.
    await ndb.lock.run(() =>
      inTransaction(txc, async () => {
        for (const table of IDB_EMULATION_TABLES) {
          await (
            await db.prepare(
              `ALTER TABLE "${table}" RENAME TO "${backupTableName(table)}"`,
            )
          ).run({});
        }
        await (
          await db.prepare(
            "UPDATE idb_migration SET status = 'complete'," +
              " finished_at = $finished_at, records_copied = $records_copied," +
              " backup_status = 'retained'," +
              " backup_expires_at = $backup_expires_at WHERE id = 1",
          )
        ).run({
          finished_at: finishedAt,
          records_copied: report.totalRecords,
          backup_expires_at: backupExpiresAt,
        });
      }),
    );

    logger.info(
      `migrated ${report.totalRecords} records to the native schema;` +
        ` the previous database is kept in this file until` +
        ` ${new Date(backupExpiresAt / 1000).toISOString()}`,
    );

    // The bookkeeping is reported from what was just written rather than read
    // back: past the transaction above the emulation's tables are gone, so a
    // caller that treats a throw as "nothing happened, keep using the old
    // handle" would be wrong from here on.  Nothing after this can throw.
    src.emitNotification({
      type: NotificationType.DatabaseMaintenanceProgress,
      operation: "indexeddb-to-native-migration",
      phase: "complete",
      ...(conversionOptions.progressToken
        ? { progressToken: conversionOptions.progressToken }
        : {}),
      completedSteps: DB_CONVERSION_STEP_COUNT,
      totalSteps: DB_CONVERSION_STEP_COUNT,
      processedRecords: report.totalRecords,
      totalRecords: report.totalRecords,
      completionPercent: 100,
    });
    return {
      handle: dst,
      report,
      info: {
        status: "complete",
        startedAt,
        finishedAt,
        recordsCopied: report.totalRecords,
        backupStatus: "retained",
        backupExpiresAt,
        cleanupSafe: true,
      },
    };
  } catch (e) {
    src.emitNotification({
      type: NotificationType.DatabaseMaintenanceProgress,
      operation: "indexeddb-to-native-migration",
      phase: "failed",
      ...(conversionOptions.progressToken
        ? { progressToken: conversionOptions.progressToken }
        : {}),
      completedSteps: lastProgress?.completedSteps ?? 0,
      totalSteps: DB_CONVERSION_STEP_COUNT,
      ...(lastProgress?.processedRecords !== undefined
        ? { processedRecords: lastProgress.processedRecords }
        : {}),
      ...(lastProgress?.totalRecords !== undefined
        ? { totalRecords: lastProgress.totalRecords }
        : {}),
      completionPercent: lastProgress?.completionPercent ?? 0,
      error: getErrorDetailFromException(e),
    });
    throw e;
  }
}

/**
 * Drop the retained emulation tables once their retention has passed.
 *
 * Called when a migrated database is opened, which is the only moment at
 * which nothing is using it and a schema change is free.  Returns whether it
 * dropped anything.
 */
export async function dropExpiredMigrationBackup(
  db: Sqlite3Database,
  now: number = nowMicros(),
): Promise<boolean> {
  const info = await readNativeMigrationInfo(db);
  if (info?.status !== "complete" || info.backupStatus !== "retained") {
    return false;
  }
  if (info.backupExpiresAt == null || now < info.backupExpiresAt) {
    return false;
  }
  // Bring the native schema fully up to date and validate it before deleting
  // the last pre-migration copy.
  const ndb = await openNativeSqliteWalletDb(db);
  logger.info("dropping the retained pre-migration database tables");
  await ndb.lock.run(async () => {
    const violations = await (
      await db.prepare("PRAGMA foreign_key_check")
    ).getAll({});
    if (violations.length !== 0) {
      throw Error(
        "native database failed foreign-key validation; retained backup was not dropped",
      );
    }
    await inTransaction(ndb.txc, async () => {
      for (const table of IDB_EMULATION_TABLES) {
        if (!(await tableExists(db, backupTableName(table)))) {
          throw Error(
            `retained backup table ${backupTableName(table)} is missing`,
          );
        }
      }
      for (const table of IDB_EMULATION_TABLES) {
        await (
          await db.prepare(`DROP TABLE "${backupTableName(table)}"`)
        ).run({});
      }
      await (
        await db.prepare(
          "UPDATE idb_migration SET backup_status = 'dropped' WHERE id = 1",
        )
      ).run({});
    });
  });
  return true;
}

/**
 * Undo a migration, putting the retained emulation tables back in place.
 *
 * The wallet database must not be open: this renames the tables both backends
 * read.  Afterwards the file is an emulation database again and the native
 * tables are empty, so it opens the way it did before the migration.
 *
 * Deliberately not automatic.  A wallet that migrated and then misbehaved has
 * no way to tell whether the migration caused it, and rolling back on its own
 * would discard whatever the wallet did since -- the emulation tables stopped
 * being written the moment the migration completed.
 */
export async function restoreMigrationBackup(
  db: Sqlite3Database,
): Promise<void> {
  const info = await readNativeMigrationInfo(db);
  if (info?.status !== "complete") {
    throw Error("this database was not migrated to the native schema");
  }
  if (info.backupStatus !== "retained") {
    throw Error(
      `the pre-migration tables are not available (backup is` +
        ` ${info.backupStatus ?? "absent"})`,
    );
  }
  const ndb = await openNativeSqliteWalletDb(db);
  await ndb.lock.run(async () => {
    await inTransaction(ndb.txc, async () => {
      // Preflight is inside the same transaction as deletion and renaming, so
      // every failure leaves the complete native wallet authoritative.
      for (const table of IDB_EMULATION_TABLES) {
        if (await tableExists(db, table)) {
          throw Error(`cannot restore: table ${table} already exists`);
        }
        if (!(await tableExists(db, backupTableName(table)))) {
          throw Error(
            `cannot restore: backup table ${backupTableName(table)} is missing`,
          );
        }
      }
      await clearNativeSqliteWalletDbInTransaction(ndb);
      for (const table of IDB_EMULATION_TABLES) {
        await (
          await db.prepare(
            `ALTER TABLE "${backupTableName(table)}" RENAME TO "${table}"`,
          )
        ).run({});
      }
      await (
        await db.prepare(
          "UPDATE idb_migration SET backup_status = 'restored'," +
            " status = 'rolled-back' WHERE id = 1 AND status = 'complete'",
        )
      ).run({});
      const updated = await (
        await db.prepare("SELECT status FROM idb_migration WHERE id = 1")
      ).getFirst({});
      if (updated?.status !== "rolled-back") {
        throw Error(
          "migration status changed while rollback was being prepared",
        );
      }
    });
  });
  logger.info("restored the pre-migration wallet database");
}

export type MigrationAuthority = "indexeddb" | "native";

async function requireResolutionTables(db: Sqlite3Database): Promise<void> {
  for (const table of IDB_EMULATION_TABLES) {
    if (!(await tableExists(db, table))) {
      throw Error(
        `cannot resolve migration: expected IndexedDB table ${table} is missing`,
      );
    }
    if (await tableExists(db, backupTableName(table))) {
      throw Error(
        `cannot resolve migration: backup table ${backupTableName(table)} already exists`,
      );
    }
  }
  for (const table of NATIVE_DATA_TABLES) {
    if (!(await tableExists(db, table))) {
      throw Error(
        `cannot resolve migration: expected native table ${table} is missing`,
      );
    }
  }
}

/** Select authority in an ambiguous file.  The caller must create a backup first. */
export async function resolveAmbiguousWalletDb(
  db: Sqlite3Database,
  keep: MigrationAuthority,
): Promise<void> {
  const inspection = await inspectWalletDbFileDetails(db);
  if (inspection.kind !== "ambiguous") {
    throw Error(
      `migration resolution requires an ambiguous database, got ${inspection.kind}`,
    );
  }
  await requireResolutionTables(db);
  const ndb = await openNativeSqliteWalletDb(db);
  await ndb.lock.run(async () => {
    if (keep === "native") {
      const violations = await (
        await db.prepare("PRAGMA foreign_key_check")
      ).getAll({});
      if (violations.length !== 0) {
        throw Error(
          `cannot keep native: foreign-key validation found ${violations.length} violation(s)`,
        );
      }
    }
    await inTransaction(ndb.txc, async () => {
      // Repeat preflight under the mutation transaction.
      await requireResolutionTables(db);
      const at = nowMicros();
      if (keep === "indexeddb") {
        await clearNativeSqliteWalletDbInTransaction(ndb);
        await (
          await db.prepare(
            "INSERT INTO idb_migration" +
              " (id, status, started_at, finished_at, backup_status, cleanup_safe)" +
              " VALUES (1, 'rolled-back', $at, $at, 'restored', 1)" +
              " ON CONFLICT(id) DO UPDATE SET status='rolled-back'," +
              " finished_at=$at, backup_status='restored', cleanup_safe=1",
          )
        ).run({ at });
      } else {
        for (const table of IDB_EMULATION_TABLES) {
          await (
            await db.prepare(
              `ALTER TABLE "${table}" RENAME TO "${backupTableName(table)}"`,
            )
          ).run({});
        }
        await (
          await db.prepare(
            "INSERT INTO idb_migration" +
              " (id, status, started_at, finished_at, records_copied," +
              " backup_status, backup_expires_at, cleanup_safe)" +
              " VALUES (1, 'complete', $at, $at, $records, 'retained', $expires, 0)" +
              " ON CONFLICT(id) DO UPDATE SET status='complete'," +
              " started_at=$at, finished_at=$at, records_copied=$records," +
              " backup_status='retained', backup_expires_at=$expires, cleanup_safe=0",
          )
        ).run({
          at,
          records: inspection.nativeRecords,
          expires: at + retentionMicros(),
        });
      }
    });
  });
}
