/**
 * @file
 * Compact, useful rendering of wallet balances.
 */

import { ScopeInfo, ScopeType, WalletBalance } from "@gnu-taler/taler-util";

function scopeHost(scopeInfo: ScopeInfo): string {
  if (scopeInfo.type === ScopeType.Global) {
    return "";
  }
  try {
    return new URL(scopeInfo.url).hostname;
  } catch {
    return scopeInfo.url;
  }
}

function abbreviatedScope(scopeInfo: ScopeInfo): string | undefined {
  switch (scopeInfo.type) {
    case ScopeType.Global:
      return undefined;
    case ScopeType.Exchange:
      return `@e:${scopeHost(scopeInfo)}`;
    case ScopeType.Auditor:
      return `@a:${scopeHost(scopeInfo)}`;
    case ScopeType.ExchangeLegacyKeys:
      return `@e-legacy:${scopeHost(scopeInfo)}`;
  }
}

function scopeDetails(scopeInfo: ScopeInfo): string | undefined {
  switch (scopeInfo.type) {
    case ScopeType.Global:
      return undefined;
    case ScopeType.Exchange:
      return `Scope: exchange ${scopeInfo.url}`;
    case ScopeType.Auditor:
      return `Scope: auditor ${scopeInfo.url}`;
    case ScopeType.ExchangeLegacyKeys:
      return `Scope: exchange (old keys) ${scopeInfo.url}`;
  }
}

/** Render one balance for a person reading the CLI output. */
export function formatPrettyBalance(
  balance: WalletBalance,
  verbose = false,
  oneline = false,
): string[] {
  const scope = abbreviatedScope(balance.scopeInfo);
  const headline = [
    balance.available,
    `in=${balance.pendingIncoming}`,
    `out=${balance.pendingOutgoing}`,
    scope,
  ]
    .filter((x): x is string => x != null)
    .join(" ");
  const lines = [headline];

  if (oneline) {
    return lines;
  }

  if (!verbose) return lines;

  const detail = scopeDetails(balance.scopeInfo);
  if (detail != null) lines.push(`  ${detail}`);
  if (balance.scopeInfo.type === ScopeType.ExchangeLegacyKeys) {
    lines.push(`  Exchange master public key: ${balance.scopeInfo.masterPub}`);
  }
  if (balance.flags.length > 0) {
    lines.push(`  Restrictions: ${balance.flags.join(", ")}`);
  }
  if (balance.shoppingUrls != null && balance.shoppingUrls.length > 0) {
    lines.push(`  Shopping URLs: ${balance.shoppingUrls.join(", ")}`);
  }
  if (balance.disablePeerPayments) lines.push("  Peer payments: disabled");
  if (balance.disableDirectDeposits) lines.push("  Direct deposits: disabled");
  return lines;
}
