/**
 * Transaction context.
 * Uniform interface to all transactions.
 */
export interface TransactionContext {
  get taskId(): TaskIdStr | undefined;
  get transactionId(): TransactionIdStr;
  /**
   * Handle a user request to abort a transaction.
   * Only has an effect if the the transaction is
   * in a state that allows the user to abort.
   */
  userAbortTransaction(): Promise<void>;
  /**
   * Handle a user request to abort a transaction.
   * Only has an effect if the the transaction is
   * in a state that allows the user to suspend.
   */
  userSuspendTransaction(): Promise<void>;
  /**
   * Handle a user request to abort a transaction.
   * Only has an effect if the the transaction is
   * in a state that allows the user to resume.
   */
  userResumeTransaction(): Promise<void>;
  /**
   * Handle a user request to abort a transaction.
   * Only has an effect if the the transaction is
   * in a state that allows the user to fail.
   */
  userFailTransaction(): Promise<void>;
  /**
   * Handle a user request to abort a transaction.
   * Only has an effect if the the transaction is
   * in a state that allows the user to delete.
   */
  userDeleteTransaction(): Promise<void>;
  lookupFullTransaction(
    tx: WalletDbTransaction,
    args?: LookupFullTransactionOpts,
  ): Promise<Transaction | undefined>;
}

export interface LookupFullTransactionOpts {
  includeContractTerms?: boolean;
}

declare const __taskIdStr: unique symbol;
export type TaskIdStr = string & { [__taskIdStr]: true };

/**
 * Wait until the wallet is in a particular state.
 *
 * Two functions must be provided:
 * 1. checkState, which checks if the wallet is in the
 *    desired state.
 * 2. filterNotification, which checks whether a notification
 *    might have lead to a state change.
 */
export async function genericWaitForState(
  wex: WalletExecutionContext,
  args: {
    checkState: () => Promise<boolean>;
    filterNotification: (notif: WalletNotification) => boolean;
  },
): Promise<void> {
  await wex.taskScheduler.ensureRunning();

  // FIXME: Clean up using the new JS "using" / Symbol.dispose syntax.
  const flag = new AsyncFlag();
  // Raise purchaseNotifFlag whenever we get a notification
  // about our refresh.
  const cancelNotif = wex.ws.addNotificationListener((notif) => {
    if (args.filterNotification(notif)) {
      flag.raise();
    }
  });
  const unregisterOnCancelled = wex.cancellationToken.onCancelled((reason) => {
    cancelNotif();
    flag.raise();
  });

  try {
    while (true) {
      if (wex.cancellationToken.isCancelled) {
        throw TalerError.fromDetail(
          TalerErrorCode.WALLET_CORE_REQUEST_CANCELLED,
          {},
        );
      }
      if (await args.checkState()) {
        return;
      }
      // Wait for the next transition
      await flag.wait();
      flag.reset();
    }
  } finally {
    unregisterOnCancelled();
    cancelNotif();
  }
}

/**
 * Wait until the wallet is in a particular state.
 *
 * Two functions must be provided:
 * 1. checkState, which checks if the wallet is in the
 *    desired state.
 * 2. filterNotification, which checks whether a notification
 *    might have lead to a state change.
 */
export async function genericWaitForStateVal<T>(
  wex: WalletExecutionContext,
  args: {
    checkState: () => Promise<T | undefined>;
    filterNotification: (notif: WalletNotification) => boolean;
  },
): Promise<T> {
  await wex.taskScheduler.ensureRunning();

  // FIXME: Clean up using the new JS "using" / Symbol.dispose syntax.
  const flag = new AsyncFlag();
  // Raise purchaseNotifFlag whenever we get a notification
  // about our refresh.
  const cancelNotif = wex.ws.addNotificationListener((notif) => {
    if (args.filterNotification(notif)) {
      flag.raise();
    }
  });
  const unregisterOnCancelled = wex.cancellationToken.onCancelled((reason) => {
    cancelNotif();
    flag.raise();
  });

  try {
    while (true) {
      if (wex.cancellationToken.isCancelled) {
        throw TalerError.fromDetail(
          TalerErrorCode.WALLET_CORE_REQUEST_CANCELLED,
          {},
        );
      }
      const val = await args.checkState();
      if (val != null) {
        return val;
      }
      // Wait for the next transition
      await flag.wait();
      flag.reset();
    }
  } finally {
    unregisterOnCancelled();
    cancelNotif();
  }
}

export function requireExchangeTosAcceptedOrThrow(
  wex: WalletExecutionContext,
  exchange: ReadyExchangeSummary,
): void {
  if (wex.ws.refcntIgnoreTos > 0) {
    logger.warn(
      `ignoring ToS acceptance state, refcntIgnoreTos=${wex.ws.refcntIgnoreTos}`,
    );
    return;
  }
  switch (exchange.tosStatus) {
    case ExchangeTosStatus.Accepted:
    case ExchangeTosStatus.MissingTos:
      break;
    default:
      throw TalerError.fromDetail(
        TalerErrorCode.WALLET_EXCHANGE_TOS_NOT_ACCEPTED,
        {
          exchangeBaseUrl: exchange.exchangeBaseUrl,
          currentEtag: exchange.tosCurrentEtag,
          tosStatus: exchange.tosStatus,
        },
      );
  }
}

/**
 * Refuse an operation that sends money to an exchange whose key set changed
 * and has not been confirmed.
 *
 * This summary-level gate is used by operations that send new money to the
 * exchange.  Authorizations over coins already held are gated separately,
 * immediately before disclosure, by
 * requireExchangeCoinUseConfirmedOrThrow().
 */
export function requireExchangeKeysConfirmedOrThrow(
  wex: WalletExecutionContext,
  exchange: ReadyExchangeSummary,
): void {
  const change = exchange.unconfirmedKeyChange;
  if (!change) {
    return;
  }
  throw TalerError.fromDetail(
    TalerErrorCode.WALLET_EXCHANGE_KEYS_NOT_ACCEPTED,
    {
      exchangeBaseUrl: exchange.exchangeBaseUrl,
      currentMasterPub: change.currentMasterPub,
      supersededMasterPub: change.supersededMasterPub,
    },
    "the exchange changed its master public key and the change has not been confirmed",
  );
}

/**
 * Fetch with cancellation token
 */
export async function cancelableFetch(
  wex: WalletExecutionContext,
  url: URL,
  opt?: HttpRequestOptions,
): Promise<HttpResponse> {
  return wex.http.fetch(url.href, {
    ...opt,
    cancellationToken: wex.cancellationToken,
  });
}

export interface RecordHandle<T> {
  rec: T | undefined;
  /**
   * Store the new state of the record and notify about the transition.
   *
   * The cause hint is a short description of what caused the transition,
   * for debugging only.
   */
  update(
    newRec: T | undefined,
    causeHint: string,
    eff?: BalanceEffect,
    errorInfo?: ErrorInfoSummary,
  ): Promise<void>;
}

/**
 * Generic helper for transitioning transactions.
 */
export async function getGenericRecordHandle<T>(
  ctx: TransactionContext,
  tx: WalletDbTransaction,
  getRec: () => Promise<T | undefined>,
  storeRec: (r: T) => Promise<void>,
  deleteRec: () => Promise<void>,
  toSt: (r: T) => TransactionState,
  toStId: (r: T) => number,
  updateMeta: () => Promise<void>,
): Promise<[T | undefined, RecordHandle<T>]> {
  const rec = await getRec();
  let oldTxState: TransactionState;
  let oldStId: number;
  if (rec) {
    oldTxState = toSt(rec);
    oldStId = toStId(rec);
  } else {
    oldTxState = { major: TransactionMajorState.None };
    oldStId = 0;
  }
  const update = async (
    newRec: T | undefined,
    causeHint: string,
    eff?: BalanceEffect,
    errorInfo?: ErrorInfoSummary,
  ) => {
    let newTxState: TransactionState;
    let newStId: number;
    if (newRec != null) {
      newTxState = toSt(newRec);
      newStId = toStId(newRec);
      await storeRec(newRec);
    } else if (rec != null) {
      newTxState = { major: TransactionMajorState.Deleted };
      newStId = -1;
      await deleteRec();
    } else {
      // Neither old or new record. Nothing to do.
      return;
    }
    await updateMeta();
    if (rec == null) {
      // The transaction is new, so the exchanges it involves are now used by
      // the wallet and their entries must not be garbage-collected as
      // ephemeral ones anymore.
      const meta = await tx.getTransactionMeta(ctx.transactionId);
      for (const exchangeBaseUrl of meta?.exchanges ?? []) {
        await markExchangeUsed(tx, exchangeBaseUrl);
      }
    }
    applyNotifyTransition(tx.notify, ctx.transactionId, {
      oldTxState,
      newTxState,
      balanceEffect: eff ?? BalanceEffect.Any,
      causeHint,
      errorInfo,
      oldStId,
      newStId,
    });
  };
  return [rec, { rec, update }];
}

export interface TransferOptionsRawResult {
  transferOptions: TransferOptionRaw[];
  transferExpiry: TalerProtocolTimestamp;
}

/**
 * Get transfer options for withdrawals or
 * KYC auth transfers.
 *
 * If necessary, register the target key with
 * the prepared transfer service.
 */
export async function prepareTransferOptionsRaw(
  wex: WalletExecutionContext,
  req: {
    acct: ExchangeWireAccount;
    reservePub: string;
    reservePriv: string;
    transferAmount: AmountString;
    isKyc: boolean;
  },
): Promise<TransferOptionsRawResult> {
  const { acct, reservePub, reservePriv, transferAmount } = req;
  if (!acct.prepared_transfer_url) {
    let paytoUri = acct.payto_uri;
    paytoUri = addPaytoQueryParams(paytoUri, {
      amount: Amounts.stringify(transferAmount),
    });
    if (reservePub != null) {
      paytoUri = addPaytoQueryParams(paytoUri, {
        message: `Taler ${reservePub}`,
      });
    }
    return {
      transferOptions: [
        {
          type: "payto",
          paytoUri,
        },
      ],
      transferExpiry: TalerProtocolTimestamp.never(),
    };
  }
  const options: TransferOption[] = [];
  const prepClient = new TalerPreparedTransferHttpClient(
    acct.prepared_transfer_url,
    { httpClient: wex.http },
  );
  const mySig = await wex.cryptoApi.signPreparedTransferRegister({
    account_pub: reservePub,
    alg: "EdDSA",
    authorization_priv: reservePriv,
    credit_account: acct.payto_uri,
    credit_amount: transferAmount,
    recurrent: false,
    type: req.isKyc ? "kyc" : "reserve",
  });
  const resp = succeedOrThrow(
    await prepClient.register({
      credit_account: acct.payto_uri,
      account_pub: reservePub,
      alg: "EdDSA",
      authorization_pub: reservePub,
      authorization_sig: mySig.sig,
      credit_amount: transferAmount,
      recurrent: false,
      type: req.isKyc ? "kyc" : "reserve",
    }),
  );
  for (const opt of resp.subjects) {
    switch (opt.type) {
      case "SIMPLE": {
        const myPayto = paytoFromTransferSubject(acct.payto_uri, opt);
        checkLogicInvariant(!!myPayto);
        options.push({
          type: "payto",
          paytoUri: myPayto,
          qrCodes: getQrCodesForPayto(myPayto),
        });
        break;
      }
      case "URI": {
        options.push({
          type: "uri",
          uri: opt.uri,
        });
        break;
      }
      case "CH_QR_BILL": {
        const myPayto = paytoFromTransferSubject(acct.payto_uri, opt);
        checkLogicInvariant(!!myPayto);
        options.push({
          type: "ch-qr-bill",
          paytoUri: myPayto,
          qrReferenceNumber: opt.qr_reference_number,
          qrCodes: getQrCodesForPayto(myPayto),
        });
        break;
      }
      default:
        logger.warn(`Unsupported transfer subject: ${j2s(opt)}`);
        break;
    }
  }
  return {
    transferOptions: options,
    transferExpiry: resp.expiration,
  };
}

export function augmentTransferOptions(
  options: TransferOptionRaw[],
): TransferOption[] {
  const res: TransferOption[] = [];
  for (const opt of options) {
    switch (opt.type) {
      case "ch-qr-bill":
        res.push({
          type: "ch-qr-bill",
          paytoUri: opt.paytoUri,
          qrReferenceNumber: opt.qrReferenceNumber,
          qrCodes: getQrCodesForPayto(opt.paytoUri),
        });
        break;
      case "payto":
        res.push({
          type: "payto",
          paytoUri: opt.paytoUri,
          qrCodes: getQrCodesForPayto(opt.paytoUri),
        });
        break;
      case "uri":
        res.push({ type: "uri", uri: opt.uri });
        break;
      default:
        continue;
    }
  }
  return res;
}

/**
 * Build the canonical taler-reserve(-http) full payto-URI for a reserve at an
 * exchange, replacing the deprecated talerPaytoFromExchangeReserve.
 */
export function reservePaytoFromExchange(
  exchangeBaseUrl: string,
  reservePub: string,
): Paytos.FullPaytoString {
  const pub = decodeCrock(reservePub);
  const uri = exchangeBaseUrl.startsWith("http://")
    ? Paytos.createTalerReserveHttp(exchangeBaseUrl as HostPortPath, pub)
    : Paytos.createTalerReserve(exchangeBaseUrl as HostPortPath, pub);
  return Paytos.toFullString(uri);
}
