import { codecForAmountString } from "./amounts.js";
import {
  Codec,
  buildCodecForObject,
  codecForList,
  codecForNumber,
} from "./codec.js";
import { codecForConstString, codecForString } from "./codec.js";
import { codecForDuration } from "./time.js";
import {
  AmountString,
  RelativeTime,
} from "./types-taler-common.js";

export const codecForTaldirAliasType =
  (): Codec<TaldirAliasType> =>
    buildCodecForObject<TaldirAliasType>()
      .property("name", codecForString())
      .property("challenge_fee", codecForAmountString())
      .build("TalerDirectoryApi.TaldirAliasType");

export const codecForTalerDirectoryConfigResponse =
  (): Codec<TalerDirectoryConfigResponse> =>
    buildCodecForObject<TalerDirectoryConfigResponse>()
      .property("version", codecForString())
      .property("name", codecForConstString("taler-directory"))
      .property("monthly_fee", codecForAmountString())
      .property("alias_types", codecForList(codecForTaldirAliasType()))
      .build("TalerDirectoryApi.VersionResponse");

interface TaldirAliasType {
  // Name of the alias type, e.g. "email" or "sms".
  name: string;

  // per challenge fee
  challenge_fee: AmountString;

}

export interface TalerDirectoryConfigResponse {
  // libtool-style representation of the Merchant protocol version, see
  // https://www.gnu.org/software/libtool/manual/html_node/Versioning.html#Versioning
  // The format is "current:revision:age".
  version: string;

  // Name of the protocol.
  name: "taler-directory";

  // Supported alias types
  alias_types: TaldirAliasType[];

  // fee for one month of registration
  monthly_fee: AmountString;
}

export interface TaldirMailboxDetailResponse {

  // Target URI to associate with this alias.
  target_uri: string;

}

export const codecForTaldirMailboxDetailResponse = (): Codec<TaldirMailboxDetailResponse> =>
  buildCodecForObject<TaldirMailboxDetailResponse>()
    .property("target_uri", codecForString())
    .build("TalerDirectoryApi.TaldirMailboxDetailResponse");

export const codecForTalerDirectoryRateLimitedResponse =
  (): Codec<TaldirRateLimitedResponse> =>
    buildCodecForObject<TaldirRateLimitedResponse>()
      .property("code", codecForNumber())
      .property("retry_delay", codecForDuration)
      .property("hint", codecForString())
      .build("TalerDirectoryApi.TaldirRateLimitedResponse");

export interface TaldirAlreadyPaidResponse {
  // The remaining duration for which this registration is still paid for
  valid_for: RelativeTime;
}

export const codecForTaldirAlreadyPaidResponse =
  (): Codec<TaldirAlreadyPaidResponse> =>
    buildCodecForObject<TaldirAlreadyPaidResponse>()
      .property("valid_for", codecForDuration)
      .build("TalerDirectoryApi.TaldirAlreadyPaidResponse");

export interface TaldirRateLimitedResponse {
  // Taler error code, TALER_EC_TALDIR_DELIVERY_RATE_LIMITED.
  code: number;

  // When the client should retry.
  retry_delay: RelativeTime;

  // The human readable error message.
  hint: string;
}
