const logger = new Logger("shepherd.ts");

/**
 * Info about one task being shepherded.
 */
interface ShepherdInfo {
  cts: CancellationToken.Source;
  /**
   * Promise that resolves when the current
   * shepherd loop for the task has terminated.
   */
  latch?: Promise<void>;

  /**
   * Cut the current wait short.  Only installed while the loop is actually
   * waiting; a no-op otherwise, so it is always safe to call.
   */
  interruptWait: () => void;

  /**
   * Set when this shepherd has been asked to stop.  It then no longer accepts
   * wakeups and is replaced rather than reused.
   */
  stopRequested: boolean;

  /**
   * Set by a wakeup (startShepherdTask) for a shepherd that already exists.
   *
   * This is what makes a wakeup survive until the loop can act on it, whatever
   * the loop happens to be doing at the time: the loop clears it before each
   * handler run, skips waiting while it is set, and re-runs instead of
   * terminating when the handler reports that it is finished.
   */
  rerunRequested: boolean;

  /**
   * Unique numeric identifier for the shepherd.
   */
  shepId: number;
}

/**
 * Check if a task is alive, i.e. whether it prevents
 * the main task loop from exiting.
 */
function taskGivesLiveness(taskId: string): boolean {
  const parsedTaskId = parseTaskIdentifier(taskId);
  switch (parsedTaskId.tag) {
    case PendingTaskType.ExchangeUpdate:
    case PendingTaskType.ExchangeAutoRefresh:
    case PendingTaskType.ExchangeWalletKyc:
    case PendingTaskType.ValidateDenoms:
    case PendingTaskType.CleanupExpiredTransactions:
      return false;
    case PendingTaskType.Deposit:
    case PendingTaskType.PeerPullCredit:
    case PendingTaskType.PeerPullDebit:
    case PendingTaskType.PeerPushCredit:
    case PendingTaskType.Refresh:
    case PendingTaskType.Recoup:
    case PendingTaskType.Withdraw:
    case PendingTaskType.PeerPushDebit:
    case PendingTaskType.Purchase:
      return true;
    default:
      assertUnreachable(parsedTaskId);
  }
}

export interface TaskScheduler {
  /**
   * Ensure that the task scheduler is running.
   *
   * If it is not running, start it, with previous
   * tasks loaded from the database.
   *
   * Returns after the scheduler is running.
   */
  ensureRunning(): Promise<void>;
  startShepherdTask(taskId: TaskIdStr): void;
  stopShepherdTask(taskId: TaskIdStr): void;
  /**
   * Restart a task and reset retry counter.
   */
  resetTask(taskId: TaskIdStr): Promise<void>;
  reload(): Promise<void>;
  getActiveTasks(): TaskIdStr[];
  isIdle(): boolean;
  shutdown(): Promise<void>;
}

export class TaskSchedulerImpl implements TaskScheduler {
  private sheps: Map<TaskIdStr, ShepherdInfo> = new Map();

  private iterCond = new AsyncCondition();

  private throttler = new TaskThrottler();

  isRunning: boolean = false;

  private shepCounter = 1;

  constructor(private ws: InternalWalletState) {}

  private async loadTasksFromDb(): Promise<void> {
    const activeTasks = await getActiveTaskIds(this.ws);

    logger.trace(`active tasks from DB: ${j2s(activeTasks)}`);

    for (const tid of activeTasks.taskIds) {
      this.startShepherdTask(tid);
    }
  }

  getActiveTasks(): TaskIdStr[] {
    return [...this.sheps.keys()];
  }

  async shutdown(): Promise<void> {
    const tasksIds = [...this.sheps.keys()];
    logger.info(`Stopping task shepherd.`);
    for (const taskId of tasksIds) {
      this.stopShepherdTask(taskId);
    }
  }

  /**
   * @see TaskScheduler.ensureRunning
   */
  async ensureRunning(): Promise<void> {
    if (this.isRunning) {
      return;
    }
    this.isRunning = true;
    try {
      logger.trace(`loading shepherd tasks from database`);
      await this.loadTasksFromDb();
      logger.trace(`done loading shepherd tasks from database`);
    } catch (e) {
      this.isRunning = false;
      throw e;
    }
    this.run()
      .catch((e) => {
        logger.error("error running task loop");
        logger.error(`err: ${e}`);
      })
      .then(() => {
        logger.trace("done running task loop");
        this.isRunning = false;
      });
  }

  isIdle(): boolean {
    let alive = false;
    const taskIds = [...this.sheps.keys()];
    for (const taskId of taskIds) {
      if (taskGivesLiveness(taskId)) {
        alive = true;
        break;
      }
    }
    // We're idle if no task is alive anymore.
    return !alive;
  }

  private async run(): Promise<void> {
    logger.trace("Running task loop.");
    logger.trace(`sheps: ${this.sheps.size}`);
    while (true) {
      if (this.ws.stopped) {
        logger.trace("Breaking out of task loop (wallet stopped).");
        break;
      }

      if (this.isIdle()) {
        this.ws.notify({
          type: NotificationType.Idle,
        });
      }

      await this.iterCond.wait();
    }
    logger.trace("Done with task loop.");
  }

  startShepherdTask(taskId: TaskIdStr): void {
    this.ensureRunning().catch((e) => {
      logger.error(`error running scheduler: ${safeStringifyException(e)}`);
    });
    // Run in the background, no await!
    this.internalStartShepherdTask(taskId).catch((e) => {
      logger.error(`error running shepherd loop: ${safeStringifyException(e)}`);
    });
  }

  /**
   * Stop and re-load all existing tasks.
   *
   * Mostly useful to interrupt all waits when time-travelling.
   */
  async reload(): Promise<void> {
    logger.info("reloading all shepherd tasks");
    await this.ensureRunning();
    const tasksIds = [...this.sheps.keys()];
    logger.info(`reloading shepherd with ${tasksIds.length} existing tasks`);
    for (const taskId of tasksIds) {
      this.stopShepherdTask(taskId);
    }
    await this.loadTasksFromDb();
  }

  private async internalStartShepherdTask(taskId: TaskIdStr): Promise<void> {
    logger.trace(`Starting to shepherd task ${taskId}`);
    const oldShep = this.sheps.get(taskId);
    if (oldShep) {
      if (!oldShep.stopRequested) {
        // Both of these, always.  Recording the wakeup is what makes it
        // survive; interrupting the wait only shortens a sleep that happens
        // to be in progress and is a no-op otherwise.  Deciding between them
        // would mean knowing where the loop currently is, and getting that
        // wrong drops the wakeup.
        oldShep.rerunRequested = true;
        oldShep.interruptWait();
        logger.trace(`Already have a shepherd for ${taskId}`);
        return;
      }
      logger.trace(
        `Waiting for old task to complete the loop in cancel mode ${taskId}`,
      );
      oldShep.cts.cancel();
    }
    const newShep: ShepherdInfo = {
      cts: CancellationToken.create(),
      stopRequested: false,
      interruptWait: () => undefined,
      rerunRequested: false,
      shepId: this.shepCounter++,
    };
    logger.trace(
      `Creating new shepherd for ${taskId} with shepId=${newShep.shepId}`,
    );
    this.sheps.set(taskId, newShep);
    if (oldShep) {
      await oldShep.latch;
      logger.trace(`Old task ${taskId} completed in cancel mode`);
    }
    try {
      newShep.latch = this.internalShepherdTask(taskId, newShep);
      await newShep.latch;
    } finally {
      logger.trace(`Done shepherding ${taskId}`);
      newShep.cts.cancel();
      let deleted = false;
      if (this.sheps.get(taskId)?.shepId === newShep.shepId) {
        this.sheps.delete(taskId);
        deleted = true;
      }
      this.iterCond.trigger();
      // Close the residual race: a wakeup may have arrived after the loop
      // decided to terminate but before we removed the shepherd. Only restart
      // when this shepherd terminated on its own (not via stop/cancel), so we
      // don't resurrect a task that was deliberately stopped.
      if (
        deleted &&
        newShep.rerunRequested &&
        !newShep.stopRequested &&
        !this.ws.stopped
      ) {
        logger.trace(
          `rerun requested for ${taskId} after shepherd finished, restarting`,
        );
        this.startShepherdTask(taskId);
      }
    }
  }

  stopShepherdTask(taskId: TaskIdStr): void {
    logger.trace(`Stopping shepherding of ${taskId}`);
    const oldShep = this.sheps.get(taskId);
    if (oldShep) {
      logger.trace(`Cancelling old shepherd for ${taskId}`);
      if (!oldShep.stopRequested) {
        oldShep.cts.cancel(`stopping task ${taskId}`);
        oldShep.stopRequested = true;
      }
      this.iterCond.trigger();
    }
  }

  async resetTask(taskId: TaskIdStr): Promise<void> {
    await this.ws.runStandaloneWalletDbTx(async (tx) => {
      logger.trace(`storing task [reset] for ${taskId}`);
      await tx.deleteOperationRetry(taskId);
      const notif = await taskToRetryNotification(
        this.ws,
        tx,
        taskId,
        undefined,
      );
      if (notif) {
        tx.notify(notif);
      }
    });
    this.stopShepherdTask(taskId);
    this.startShepherdTask(taskId);
  }

  private async wait(
    taskId: TaskIdStr,
    info: ShepherdInfo,
    delay: Duration,
  ): Promise<void> {
    if (info.rerunRequested) {
      // A wakeup arrived while the handler was running.  Waiting it out would
      // mean answering it only after the delay that the wakeup was meant to
      // cut short.
      logger.trace(`Not waiting on ${taskId}, a rerun is already requested`);
      return;
    }
    await this.sleep(taskId, info, delay);
  }

  /**
   * Sleep for at most the given delay, returning early when the task is
   * stopped or when a wakeup interrupts the sleep.
   */
  private async sleep(
    taskId: TaskIdStr,
    info: ShepherdInfo,
    delay: Duration,
  ): Promise<void> {
    // Limit how long we wait.
    // The NodeJS runtime doesn't like very long timeouts.
    delay = Duration.min(delay, Duration.fromSpec({ hours: 1 }));
    logger.trace(`Waiting on ${taskId} (scheduled later)`);
    try {
      const op = openPromise<void>();
      info.interruptWait = () => op.resolve();
      await info.cts.token.racePromise(
        Promise.race([this.ws.timerGroup.resolveAfter(delay), op.promise]),
      );
    } catch (e) {
      if (e instanceof CancellationToken.CancellationError) {
        logger.trace(
          `waiting for ${taskId} interrupted: ${e.message} ${j2s(e.reason)}`,
        );
      } else {
        logger.trace(`waiting for ${taskId} interrupted: ${e}`);
      }
    } finally {
      info.interruptWait = () => undefined;
    }
  }

  /**
   * How much is left of the backoff that the task's last failure earned.
   *
   * Only a failing task has one.  A task that scheduled its own next run, or
   * that is parked until the network comes back, has no error stored and must
   * run as soon as it is woken up.
   */
  private async remainingErrorBackoff(
    taskId: TaskIdStr,
  ): Promise<Duration | undefined> {
    const retryRecord = await this.ws.runStandaloneWalletDbTx(async (tx) => {
      return tx.getOperationRetry(taskId);
    });
    if (!retryRecord?.lastError) {
      return undefined;
    }
    const remaining = AbsoluteTime.remaining(
      timestampAbsoluteFromDb(retryRecord.retryInfo.nextRetry),
    );
    if (remaining.d_ms !== "forever" && remaining.d_ms <= 0) {
      return undefined;
    }
    // The deadline is wall-clock time read back from the database, while the
    // policy that wrote it never asks for more than MAX_RETRY_DURATION.  A
    // longer wait therefore means the clock moved backwards since, and honouring
    // it would park the task for as long as the clock was off.  Running now
    // repairs the record: the next failure stores a deadline under this clock.
    if (Duration.cmp(remaining, MAX_RETRY_DURATION) > 0) {
      logger.warn(
        `backoff of ${taskId} exceeds the maximum, ignoring it (clock change?)`,
      );
      return undefined;
    }
    return remaining;
  }

  private async internalShepherdTask(
    taskId: TaskIdStr,
    info: ShepherdInfo,
  ): Promise<void> {
    while (true) {
      if (this.ws.stopped) {
        logger.trace(`Shepherd for ${taskId} stopping as wallet is stopped`);
        return;
      } else if (info.cts.token.isCancelled) {
        logger.trace(`Shepherd for ${taskId} got cancelled`);
        return;
      }
      // The backoff of a failing task is stored in the database and has to
      // outlive this loop.  Without that, every wakeup and every restart of
      // the wallet repeats the request immediately, so a client that resumes
      // the application once a second makes us retry once a second.  An
      // explicit retry still takes effect at once: it clears the error first.
      const backoff = await this.remainingErrorBackoff(taskId);
      if (backoff) {
        logger.trace(`Deferring ${taskId}, still backing off from an error`);
        await this.sleep(taskId, info, backoff);
        continue;
      }
      const isThrottled = this.throttler.applyThrottle(taskId);
      if (isThrottled) {
        logger.warn(
          `task ${taskId} throttled, this is very likely a bug in wallet-core, please report`,
        );
        logger.warn("waiting for 60 seconds");
        await this.ws.timerGroup.resolveAfter(
          Duration.fromSpec({ seconds: 60 }),
        );
      }
      const wex = getWalletExecutionContextForTask(
        this.ws,
        taskId,
        info.cts.token,
      );
      const startTime = AbsoluteTime.now();
      // Reset before running the handler so that any wakeup arriving while the
      // handler (and its result storage) runs is captured and honored below.
      info.rerunRequested = false;
      logger.trace(`Shepherd for ${taskId} will call handler`);
      let res: TaskRunResult;
      try {
        res = await callOperationHandlerForTaskId(wex, taskId);
      } catch (e) {
        res = {
          type: TaskRunResultType.Error,
          errorDetail: getErrorDetailFromException(e),
        };
      }
      if (this.ws.stopped) {
        logger.trace("wallet stopped, not processing result");
        return;
      } else if (info.cts.token.isCancelled) {
        logger.trace(`task ${taskId} cancelled, not processing result`);
        return;
      }
      logger.trace(`Shepherd for ${taskId} got result ${res.type}`);
      const endTime = AbsoluteTime.now();
      const taskDuration = AbsoluteTime.difference(endTime, startTime);
      if (taskDuration.d_ms === "forever") {
        throw Error("assertion failed");
      }
      wex.oc.observe({
        type: ObservabilityEventType.ShepherdTaskResult,
        taskId,
        resultType: res.type,
        durationMs: taskDuration.d_ms,
      });
      switch (res.type) {
        case TaskRunResultType.Error: {
          const retryRecord = await storePendingTaskError(
            this.ws,
            taskId,
            res.errorDetail,
          );
          const t = timestampAbsoluteFromDb(retryRecord.retryInfo.nextRetry);
          const delay = AbsoluteTime.remaining(t);
          logger.trace(`Stored error for ${taskId},`);
          await this.wait(taskId, info, delay);
          break;
        }
        case TaskRunResultType.Backoff: {
          const retryRecord = await storePendingTaskPending(this.ws, taskId);
          const t = timestampAbsoluteFromDb(retryRecord.retryInfo.nextRetry);
          const delay = AbsoluteTime.remaining(t);
          logger.trace(`Waiting on ${taskId} (backoff)`);
          await this.wait(taskId, info, delay);
          break;
        }
        case TaskRunResultType.Progress: {
          await storeTaskProgress(this.ws, taskId);
          break;
        }
        case TaskRunResultType.ScheduleLater: {
          const retryRecord = await storePendingTaskPending(
            this.ws,
            taskId,
            res.runAt,
          );
          const t = timestampAbsoluteFromDb(retryRecord.retryInfo.nextRetry);
          const delay = AbsoluteTime.remaining(t);
          logger.trace(`Waiting on ${taskId} (scheduled later)`);
          await this.wait(taskId, info, delay);
          break;
        }
        case TaskRunResultType.Finished:
          await storePendingTaskFinished(this.ws, taskId);
          if (info.rerunRequested) {
            // A wakeup arrived while we were finishing.
            // Re-run instead of terminating, otherwise the
            // task would be stuck until the next unrelated wakeup.
            logger.trace(
              `task ${taskId} finished but a rerun was requested, running again`,
            );
            break;
          }
          return;
        case TaskRunResultType.LongpollReturnedPending: {
          await storeTaskProgress(this.ws, taskId);
          // Make sure that we are waiting a bit if long-polling returned too early.
          if (
            Duration.cmp(taskDuration, Duration.fromSpec({ seconds: 20 })) < 0
          ) {
            logger.info(
              `long-poller for ${taskId} returned unexpectedly early (${taskDuration.d_ms} ms), waiting 10 seconds`,
            );
            await this.wait(taskId, info, Duration.fromSpec({ seconds: 10 }));
          } else {
            logger.info(`task ${taskId} will long-poll again`);
          }
          break;
        }
        case TaskRunResultType.NetworkRequired: {
          await storePendingTaskPending(this.ws, taskId);
          const delay = Duration.getForever();
          logger.trace(`Not retrying task until network is restored.`);
          await this.wait(taskId, info, delay);
          break;
        }
        case TaskRunResultType.Cancelled:
          logger.trace(`task ${taskId} cancelled`);
          break;
        default:
          assertUnreachable(res);
      }
    }
  }
}

async function storePendingTaskError(
  ws: InternalWalletState,
  pendingTaskId: string,
  e: TalerErrorDetail,
): Promise<WalletOperationRetry> {
  logger.trace(`storing task [pending] with ERROR for ${pendingTaskId}`);
  const res = await ws.runStandaloneWalletDbTx(async (tx) => {
    let retryRecord = await tx.getOperationRetry(pendingTaskId);
    if (!retryRecord) {
      retryRecord = {
        id: pendingTaskId,
        lastError: e,
        retryInfo: DbRetryInfo.reset(),
      };
    } else {
      retryRecord.lastError = e;
      retryRecord.retryInfo = DbRetryInfo.increment(retryRecord.retryInfo);
    }
    await tx.upsertOperationRetry(retryRecord);
    return {
      notification: await taskToRetryNotification(ws, tx, pendingTaskId, e),
      retryRecord,
    };
  });
  if (res?.notification) {
    ws.notify(res.notification);
  }
  return res.retryRecord;
}

/**
 * Task made progress, clear error.
 */
async function storeTaskProgress(
  ws: InternalWalletState,
  pendingTaskId: string,
): Promise<void> {
  logger.trace(`storing task [progress] for ${pendingTaskId}`);
  await ws.runStandaloneWalletDbTx(async (tx) => {
    await tx.deleteOperationRetry(pendingTaskId);
  });
}

async function storePendingTaskPending(
  ws: InternalWalletState,
  pendingTaskId: string,
  schedTime?: AbsoluteTime,
): Promise<WalletOperationRetry> {
  logger.trace(`storing task [pending] for ${pendingTaskId}`);
  const res = await ws.runStandaloneWalletDbTx(async (tx) => {
    let retryRecord = await tx.getOperationRetry(pendingTaskId);
    let hadError = false;
    if (!retryRecord) {
      retryRecord = {
        id: pendingTaskId,
        retryInfo: DbRetryInfo.reset(),
      };
    } else {
      if (retryRecord.lastError) {
        hadError = true;
      }
      delete retryRecord.lastError;
      // A task that names its own next run time is not backing off, so the
      // counter must not grow over the lifetime of a recurring task.
      retryRecord.retryInfo = schedTime
        ? DbRetryInfo.reset()
        : DbRetryInfo.increment(retryRecord.retryInfo);
    }
    if (schedTime) {
      retryRecord.retryInfo.nextRetry = timestampPreciseToDb(
        AbsoluteTime.toPreciseTimestamp(schedTime),
      );
    }
    await tx.upsertOperationRetry(retryRecord);
    if (hadError) {
      const notif = await taskToRetryNotification(
        ws,
        tx,
        pendingTaskId,
        undefined,
      );
      if (notif) {
        tx.notify(notif);
      }
    }
    return {
      retryRecord,
    };
  });
  return res.retryRecord;
}

async function storePendingTaskFinished(
  ws: InternalWalletState,
  pendingTaskId: string,
): Promise<void> {
  logger.trace(`storing task [finished] for ${pendingTaskId}`);
  await ws.runStandaloneWalletDbTx(async (tx) => {
    await tx.deleteOperationRetry(pendingTaskId);
  });
}

function getWalletExecutionContextForTask(
  ws: InternalWalletState,
  taskId: TaskIdStr,
  cancellationToken: CancellationToken,
): WalletExecutionContext {
  let oc: ObservabilityContext;
  let wex: WalletExecutionContext;

  if (ws.config.testing.emitObservabilityEvents) {
    oc = {
      observe(evt) {
        if (ws.config.testing.emitObservabilityEvents) {
          PerformanceTable.insertEvent(ws.performanceStats, evt);
          ws.notify({
            type: NotificationType.TaskObservabilityEvent,
            taskId,
            event: evt,
          });
        }
      },
    };

    wex = getObservedWalletExecutionContext(
      ws,
      cancellationToken,
      undefined,
      oc,
    );
  } else {
    oc = {
      observe(evt) {},
    };
    wex = getNormalWalletExecutionContext(ws, cancellationToken, undefined, oc);
  }
  return wex;
}

async function callOperationHandlerForTaskId(
  wex: WalletExecutionContext,
  taskId: TaskIdStr,
): Promise<TaskRunResult> {
  const pending = parseTaskIdentifier(taskId);

  const txId = convertTaskToTransactionId(taskId);
  if (txId) {
    wex.oc.observe({
      type: ObservabilityEventType.DeclareConcernsTransaction,
      transactionId: txId,
    });
  }

  switch (pending.tag) {
    case PendingTaskType.ExchangeUpdate:
      return await updateExchangeFromUrlHandler(wex, pending.exchangeBaseUrl);
    case PendingTaskType.ExchangeAutoRefresh:
      return await processTaskExchangeAutoRefresh(wex, pending.exchangeBaseUrl);
    case PendingTaskType.Refresh:
      return await processRefreshGroup(wex, pending.refreshGroupId);
    case PendingTaskType.Withdraw:
      return await processWithdrawalGroup(wex, pending.withdrawalGroupId);
    case PendingTaskType.Purchase:
      return await processPurchase(wex, pending.proposalId);
    case PendingTaskType.Recoup:
      return await processRecoupGroup(wex, pending.recoupGroupId);
    case PendingTaskType.Deposit:
      return await processDepositGroup(wex, pending.depositGroupId);
    case PendingTaskType.PeerPushDebit:
      return await processPeerPushDebit(wex, pending.pursePub);
    case PendingTaskType.PeerPullCredit:
      return await processPeerPullCredit(wex, pending.pursePub);
    case PendingTaskType.PeerPullDebit:
      return await processPeerPullDebit(wex, pending.peerPullDebitId);
    case PendingTaskType.PeerPushCredit:
      return await processPeerPushCredit(wex, pending.peerPushCreditId);
    case PendingTaskType.ExchangeWalletKyc:
      return await processExchangeKyc(wex, pending.exchangeBaseUrl);
    case PendingTaskType.ValidateDenoms:
      return await processValidateDenoms(wex);
    case PendingTaskType.CleanupExpiredTransactions:
      return await processCleanupExpiredTransactions(wex);
    default:
      return assertUnreachable(pending);
  }
  throw Error(`not reached ${pending.tag}`);
}

/**
 * Generate an appropriate error transition notification
 * for applicable tasks.
 *
 * Namely, transition notifications are generated for:
 * - exchange update errors
 * - transactions
 */
async function taskToRetryNotification(
  ws: InternalWalletState,
  tx: WalletDbTransaction,
  pendingTaskId: string,
  e: TalerErrorDetail | undefined,
): Promise<WalletNotification | undefined> {
  const parsedTaskId = parseTaskIdentifier(pendingTaskId);

  switch (parsedTaskId.tag) {
    case PendingTaskType.ExchangeUpdate:
      return makeExchangeRetryNotification(ws, tx, pendingTaskId, e);
    case PendingTaskType.PeerPullCredit:
    case PendingTaskType.PeerPullDebit:
    case PendingTaskType.Withdraw:
    case PendingTaskType.PeerPushCredit:
    case PendingTaskType.Deposit:
    case PendingTaskType.Refresh:
    case PendingTaskType.PeerPushDebit:
    case PendingTaskType.Purchase:
      return makeTransactionRetryNotification(ws, tx, pendingTaskId, e);
    case PendingTaskType.Recoup:
    case PendingTaskType.ValidateDenoms:
    case PendingTaskType.CleanupExpiredTransactions:
    case PendingTaskType.ExchangeWalletKyc:
    case PendingTaskType.ExchangeAutoRefresh:
      return undefined;
    default:
      assertUnreachable(parsedTaskId);
  }
}

async function getTransactionState(
  ws: InternalWalletState,
  tx: WalletDbTransaction,
  transactionId: string,
): Promise<{ txState: TransactionState; stId: number } | undefined> {
  const parsedTxId = parseTransactionIdentifier(transactionId);
  if (!parsedTxId) {
    throw Error("invalid tx identifier");
  }
  switch (parsedTxId.tag) {
    case TransactionType.Deposit: {
      const rec = await tx.getDepositGroup(parsedTxId.depositGroupId);
      if (!rec) {
        return undefined;
      }
      return {
        txState: computeDepositTransactionStatus(rec),
        stId: rec.operationStatus,
      };
    }
    case TransactionType.InternalWithdrawal:
    case TransactionType.Withdrawal: {
      const rec = await tx.getWithdrawalGroup(parsedTxId.withdrawalGroupId);
      if (!rec) {
        return undefined;
      }
      return {
        txState: computeWithdrawalTransactionStatus(rec),
        stId: rec.status,
      };
    }
    case TransactionType.Payment: {
      const rec = await tx.getPurchase(parsedTxId.proposalId);
      if (!rec) {
        return;
      }
      return {
        txState: computePayMerchantTransactionState(rec),
        stId: rec.purchaseStatus,
      };
    }
    case TransactionType.Refund: {
      const rec = await tx.getRefundGroup(parsedTxId.refundGroupId);
      if (!rec) {
        return undefined;
      }
      return {
        txState: computeRefundTransactionState(rec),
        stId: rec.status,
      };
    }
    case TransactionType.PeerPullCredit: {
      const rec = await tx.getPeerPullCredit(parsedTxId.pursePub);
      if (!rec) {
        return undefined;
      }
      return {
        txState: computePeerPullCreditTransactionState(rec),
        stId: rec.status,
      };
    }
    case TransactionType.PeerPullDebit: {
      const rec = await tx.getPeerPullDebit(parsedTxId.peerPullDebitId);
      if (!rec) {
        return undefined;
      }
      return {
        txState: computePeerPullDebitTransactionState(rec),
        stId: rec.status,
      };
    }
    case TransactionType.PeerPushCredit: {
      const rec = await tx.getPeerPushCredit(parsedTxId.peerPushCreditId);
      if (!rec) {
        return undefined;
      }
      return {
        txState: computePeerPushCreditTransactionState(rec),
        stId: rec.status,
      };
    }
    case TransactionType.PeerPushDebit: {
      const rec = await tx.getPeerPushDebit(parsedTxId.pursePub);
      if (!rec) {
        return undefined;
      }
      return {
        txState: computePeerPushDebitTransactionState(rec),
        stId: rec.status,
      };
    }
    case TransactionType.Refresh: {
      const rec = await tx.getRefreshGroup(parsedTxId.refreshGroupId);
      if (!rec) {
        return undefined;
      }
      return {
        txState: computeRefreshTransactionState(rec),
        stId: rec.operationStatus,
      };
    }
    case TransactionType.Recoup:
      throw Error("not yet supported");
    case TransactionType.DenomLoss: {
      const rec = await tx.getDenomLossEvent(parsedTxId.denomLossEventId);
      if (!rec) {
        return undefined;
      }
      return {
        txState: computeDenomLossTransactionStatus(rec),
        stId: rec.status,
      };
    }
    default:
      assertUnreachable(parsedTxId);
  }
}

async function makeTransactionRetryNotification(
  ws: InternalWalletState,
  tx: WalletDbTransaction,
  pendingTaskId: string,
  e: TalerErrorDetail | undefined,
): Promise<WalletNotification | undefined> {
  const txId = convertTaskToTransactionId(pendingTaskId);
  if (!txId) {
    return undefined;
  }
  const txState = await getTransactionState(ws, tx, txId);
  if (!txState) {
    return undefined;
  }
  const notif: WalletNotification = {
    type: NotificationType.TransactionStateTransition,
    causeHint: "shepherd-retry",
    transactionId: txId,
    oldTxState: txState.txState,
    newTxState: txState.txState,
    newStId: txState.stId,
  };
  if (e) {
    notif.errorInfo = {
      code: e.code as number,
      hint: e.hint,
    };
  }
  return notif;
}

async function makeExchangeRetryNotification(
  ws: InternalWalletState,
  tx: WalletDbTransaction,
  pendingTaskId: string,
  e: TalerErrorDetail | undefined,
): Promise<WalletNotification | undefined> {
  const parsedTaskId = parseTaskIdentifier(pendingTaskId);
  switch (parsedTaskId.tag) {
    case PendingTaskType.ExchangeUpdate:
    case PendingTaskType.ExchangeWalletKyc:
    case PendingTaskType.ExchangeAutoRefresh:
      break;
    default:
      throw Error("invalid task identifier");
  }
  const rec = await tx.getExchange(parsedTaskId.exchangeBaseUrl);

  if (!rec) {
    logger.info(`exchange ${parsedTaskId.exchangeBaseUrl} not found`);
    return undefined;
  }

  const notif: WalletNotification = {
    type: NotificationType.ExchangeStateTransition,
    exchangeBaseUrl: parsedTaskId.exchangeBaseUrl,
    causeHint: "shepherd-retry",
    oldExchangeState: getExchangeState(rec),
    newExchangeState: getExchangeState(rec),
  };
  if (e) {
    notif.errorInfo = {
      code: e.code as number,
      hint: e.hint,
    };
  }
  return notif;
}

/**
 * Convert the task ID for a task that processes a transaction int
 * the ID for the transaction.
 */
export function convertTaskToTransactionId(
  taskId: string,
): TransactionIdStr | undefined {
  const parsedTaskId = parseTaskIdentifier(taskId);
  switch (parsedTaskId.tag) {
    case PendingTaskType.PeerPullCredit:
      return constructTransactionIdentifier({
        tag: TransactionType.PeerPullCredit,
        pursePub: parsedTaskId.pursePub,
      });
    case PendingTaskType.PeerPullDebit:
      return constructTransactionIdentifier({
        tag: TransactionType.PeerPullDebit,
        peerPullDebitId: parsedTaskId.peerPullDebitId,
      });
    // FIXME: This doesn't distinguish internal-withdrawal.
    // Maybe we should have a different task type for that as well?
    // Or maybe transaction IDs should be valid task identifiers?
    case PendingTaskType.Withdraw:
      return constructTransactionIdentifier({
        tag: TransactionType.Withdrawal,
        withdrawalGroupId: parsedTaskId.withdrawalGroupId,
      });
    case PendingTaskType.PeerPushCredit:
      return constructTransactionIdentifier({
        tag: TransactionType.PeerPushCredit,
        peerPushCreditId: parsedTaskId.peerPushCreditId,
      });
    case PendingTaskType.Deposit:
      return constructTransactionIdentifier({
        tag: TransactionType.Deposit,
        depositGroupId: parsedTaskId.depositGroupId,
      });
    case PendingTaskType.Refresh:
      return constructTransactionIdentifier({
        tag: TransactionType.Refresh,
        refreshGroupId: parsedTaskId.refreshGroupId,
      });
    case PendingTaskType.PeerPushDebit:
      return constructTransactionIdentifier({
        tag: TransactionType.PeerPushDebit,
        pursePub: parsedTaskId.pursePub,
      });
    case PendingTaskType.Purchase:
      return constructTransactionIdentifier({
        tag: TransactionType.Payment,
        proposalId: parsedTaskId.proposalId,
      });
    default:
      return undefined;
  }
}

export interface ActiveTaskIdsResult {
  taskIds: TaskIdStr[];
}

export async function getActiveTaskIds(
  ws: InternalWalletState,
): Promise<ActiveTaskIdsResult> {
  const res: ActiveTaskIdsResult = {
    taskIds: [],
  };
  await ws.runStandaloneWalletDbTx(async (tx) => {
    // Withdrawals

    {
      const activeRecs = await tx.getActiveWithdrawalGroups();
      for (const rec of activeRecs) {
        const taskId = constructTaskIdentifier({
          tag: PendingTaskType.Withdraw,
          withdrawalGroupId: rec.withdrawalGroupId,
        });
        res.taskIds.push(taskId);
      }
    }

    // Deposits

    {
      const activeRecs = await tx.getActiveDepositGroups();
      for (const rec of activeRecs) {
        const taskId = constructTaskIdentifier({
          tag: PendingTaskType.Deposit,
          depositGroupId: rec.depositGroupId,
        });
        res.taskIds.push(taskId);
      }
    }

    // Refreshes

    {
      const activeRecs = await tx.getActiveRefreshGroups();
      for (const rec of activeRecs) {
        const taskId = constructTaskIdentifier({
          tag: PendingTaskType.Refresh,
          refreshGroupId: rec.refreshGroupId,
        });
        res.taskIds.push(taskId);
      }
    }

    // Purchases

    {
      const activeRecs = await tx.getActivePurchases();
      for (const rec of activeRecs) {
        const taskId = constructTaskIdentifier({
          tag: PendingTaskType.Purchase,
          proposalId: rec.proposalId,
        });
        res.taskIds.push(taskId);
      }
    }

    // peer-push-debit

    {
      const activeRecs = await tx.getActivePeerPushDebits();
      for (const rec of activeRecs) {
        const taskId = constructTaskIdentifier({
          tag: PendingTaskType.PeerPushDebit,
          pursePub: rec.pursePub,
        });
        res.taskIds.push(taskId);
      }
    }

    // peer-push-credit

    {
      const activeRecs = await tx.getActivePeerPushCredits();
      for (const rec of activeRecs) {
        const taskId = constructTaskIdentifier({
          tag: PendingTaskType.PeerPushCredit,
          peerPushCreditId: rec.peerPushCreditId,
        });
        res.taskIds.push(taskId);
      }
    }

    // peer-pull-debit

    {
      const activeRecs = await tx.getActivePeerPullDebits();
      for (const rec of activeRecs) {
        const taskId = constructTaskIdentifier({
          tag: PendingTaskType.PeerPullDebit,
          peerPullDebitId: rec.peerPullDebitId,
        });
        res.taskIds.push(taskId);
      }
    }

    // peer-pull-credit

    {
      const activeRecs = await tx.getActivePeerPullCredits();
      for (const rec of activeRecs) {
        const taskId = constructTaskIdentifier({
          tag: PendingTaskType.PeerPullCredit,
          pursePub: rec.pursePub,
        });
        res.taskIds.push(taskId);
      }
    }

    // recoup

    {
      const activeRecs = await tx.getActiveRecoupGroups();
      for (const rec of activeRecs) {
        const taskId = constructTaskIdentifier({
          tag: PendingTaskType.Recoup,
          recoupGroupId: rec.recoupGroupId,
        });
        res.taskIds.push(taskId);
      }
    }

    // exchange update and KYC

    {
      const exchanges = await tx.getExchanges();
      for (const rec of exchanges) {
        const taskIdUpdate = constructTaskIdentifier({
          tag: PendingTaskType.ExchangeUpdate,
          exchangeBaseUrl: rec.baseUrl,
        });
        res.taskIds.push(taskIdUpdate);

        const taskIdAutoRefresh = constructTaskIdentifier({
          tag: PendingTaskType.ExchangeAutoRefresh,
          exchangeBaseUrl: rec.baseUrl,
        });
        res.taskIds.push(taskIdAutoRefresh);

        const reserveId = rec.currentMergeReserveRowId;
        if (reserveId == null) {
          continue;
        }
        const reserveRec = await tx.getReserve(reserveId);
        if (
          reserveRec?.status != null &&
          reserveRec.status != ReserveRecordStatus.Done
        ) {
          const taskIdKyc = constructTaskIdentifier({
            tag: PendingTaskType.ExchangeWalletKyc,
            exchangeBaseUrl: rec.baseUrl,
          });
          res.taskIds.push(taskIdKyc);
        }
      }
    }

    // Always try to validate unvalidated denoms.

    res.taskIds.push(
      constructTaskIdentifier({ tag: PendingTaskType.ValidateDenoms }),
    );

    // FIXME: Recoup!
  });

  return res;
}

export async function processCleanupExpiredTransactions(
  wex: WalletExecutionContext,
): Promise<TaskRunResult> {
  await wex.runWalletDbTx(async (tx) => {
    const expired = await tx.getPurchasesByStatus(PurchaseStatus.Expired);
    for (const exp of expired) {
      if (!exp.timestampExpired) {
        continue;
      }
      if (
        AbsoluteTime.isExpired(
          AbsoluteTime.addDuration(
            timestampAbsoluteFromDb(exp.timestampExpired),
            Duration.fromSpec({ hours: 24 }),
          ),
        )
      ) {
        const ctx = new PayMerchantTransactionContext(wex, exp.proposalId);
        await ctx.userDeleteTransaction();
      }
    }
  });
  return TaskRunResult.runAgainAfter({ hours: 24 });
}
