/**
 * @file
 * Parsing of the command line syntax for transaction states,
 * used by the "wait-tx" command.
 */

/**
 * Imports.
 */
import {
  Duration,
  TestingWaitTxStateSpec,
  TransactionMajorState,
  TransactionMinorState,
  TransactionState,
  TransactionStatePattern,
} from "@gnu-taler/taler-util";

/**
 * Error caused by bad command line arguments.
 *
 * Reported without a stack trace, and with an exit code that
 * distinguishes it from a failed operation.
 */
export class CliUsageError extends Error {
  constructor(
    message: string,
    public hint?: string,
  ) {
    super(message);
    Object.setPrototypeOf(this, CliUsageError.prototype);
  }
}

const MAJOR_VALUES: string[] = Object.values(TransactionMajorState);
const MINOR_VALUES: string[] = Object.values(TransactionMinorState);

/**
 * Syntax of a state spec, as shown in the command line help.
 */
export const TX_STATE_SPEC_SYNTAX = [
  "MAJOR[:MINOR][/working|/idle], multiple alternatives separated by ','.",
  "MAJOR and MINOR may be '*' (or 'any'); MINOR defaults to 'any' and may be",
  "'-' to require a state without a minor state.",
  "The shorthands 'nonpending' and 'final' stand for whole categories.",
].join(" ");

/**
 * Suggest valid values for a token that wasn't recognized.
 */
function suggest(bad: string, candidates: string[]): string {
  const near = candidates.filter(
    (c) =>
      (bad.length >= 3 && c.startsWith(bad.substring(0, 3))) ||
      c.includes(bad) ||
      bad.includes(c),
  );
  if (near.length > 0) {
    return `did you mean: ${near.slice(0, 5).join(", ")}?`;
  }
  return `valid values: ${candidates.join(", ")}`;
}

function parseWorking(w: string): boolean | "*" {
  switch (w) {
    case "working":
      return true;
    case "idle":
      return false;
    case "*":
    case "any":
      return "*";
    default:
      throw new CliUsageError(
        `invalid working qualifier '${w}'`,
        "expected 'working', 'idle' or 'any'",
      );
  }
}

function parseAlternative(alt: string): TransactionStatePattern {
  let head = alt;
  let working: boolean | "*" = "*";
  const slash = alt.indexOf("/");
  if (slash >= 0) {
    head = alt.substring(0, slash);
    working = parseWorking(alt.substring(slash + 1));
  }

  // No enum value contains a colon, so the first one separates
  // the major from the minor state.
  const colon = head.indexOf(":");
  const majorStr = colon < 0 ? head : head.substring(0, colon);
  const minorStr = colon < 0 ? undefined : head.substring(colon + 1);

  let major: TransactionMajorState | "*";
  if (majorStr === "*" || majorStr === "any") {
    major = "*";
  } else if (MAJOR_VALUES.includes(majorStr)) {
    major = majorStr as TransactionMajorState;
  } else {
    throw new CliUsageError(
      `unknown transaction major state '${majorStr}'`,
      suggest(majorStr, MAJOR_VALUES),
    );
  }

  // An omitted minor state means "any" here, whereas wallet-core
  // takes it to mean "no minor state at all".  Spell out the wildcard,
  // and let '-' request what wallet-core does with an omitted value.
  let minor: TransactionMinorState | "*" | undefined;
  if (minorStr === undefined || minorStr === "*" || minorStr === "any") {
    minor = "*";
  } else if (minorStr === "-") {
    minor = undefined;
  } else if (MINOR_VALUES.includes(minorStr)) {
    minor = minorStr as TransactionMinorState;
  } else {
    throw new CliUsageError(
      `unknown transaction minor state '${minorStr}'`,
      suggest(minorStr, MINOR_VALUES),
    );
  }

  return { major, minor, working };
}

/**
 * Parse the state spec of the "wait-tx" command into what
 * wallet-core accepts for the state to wait for.
 */
export function parseTxStateSpec(spec: string): TestingWaitTxStateSpec {
  const s = spec.trim();
  if (s === "") {
    throw new CliUsageError("empty state specification");
  }
  if (s === "nonpending" || s === "final") {
    return s;
  }
  return s.split(",").map((alt) => {
    const trimmed = alt.trim();
    if (trimmed === "") {
      throw new CliUsageError(
        `empty alternative in state specification '${spec}'`,
      );
    }
    return parseAlternative(trimmed);
  });
}

/**
 * Parse a timeout as accepted on the command line.
 *
 * Returns the timeout in milliseconds, or "forever".
 */
export function parseTimeoutSpec(spec: string): number | "forever" {
  const s = spec.trim();
  if (s === "forever") {
    return "forever";
  }
  let d: Duration;
  try {
    d = Duration.fromPrettyString(s);
  } catch (e) {
    throw new CliUsageError(
      `invalid timeout '${spec}'`,
      "expected a duration such as '30s', '5m' or '2h', or 'forever'",
    );
  }
  if (d.d_ms === "forever") {
    return "forever";
  }
  if (d.d_ms <= 0) {
    throw new CliUsageError(`timeout '${spec}' must be positive`);
  }
  return d.d_ms;
}

/**
 * Render a transaction state the way it is written on the command line.
 */
export function formatTxState(st: TransactionState): string {
  const base = st.minor != null ? `${st.major}:${st.minor}` : `${st.major}`;
  return st.working ? `${base}/working` : base;
}

/**
 * Render a state spec for messages, in the command line syntax.
 */
export function formatTxStateSpec(spec: TestingWaitTxStateSpec): string {
  if (typeof spec === "string") {
    return spec;
  }
  if (typeof spec === "number") {
    return `state ID ${spec}`;
  }
  const pats = Array.isArray(spec) ? spec : [spec];
  return pats
    .map((pat) => {
      const minor = pat.minor === undefined ? "-" : pat.minor;
      const base = `${pat.major}:${minor}`;
      if (pat.working === true) {
        return `${base}/working`;
      }
      if (pat.working === false) {
        return `${base}/idle`;
      }
      return base;
    })
    .join(",");
}
