/**
 * Imports.
 */
import { AmountJson, Amounts } from "./amounts.js";
import { BtAddrString } from "./payto.js";
import { Result } from "./result.js";
import { BitcoinSewgit } from "./segwit_addr.js";

export enum GenerateSegwitAddrError {
  /**
   * The reserve pub used to generate the segwith is invalid
   */
  WRONG_RESERVE_PUB = "wrong-reserve-pub",
  /**
   * The net prefix of the addr is unsupported
   */
  WRONG_PREFIX = "wrong-prefix",
  /**
   * The process of generating a segwit failed
   */
  INVALID_SEGWIT = "invalid-segwit",
}

export function generateFakeSegwitAddress(
  pub: Uint8Array,
  addr: string,
): Result<[BtAddrString, BtAddrString], GenerateSegwitAddrError> {
  const first_rnd = new Uint8Array(4);
  first_rnd.set(pub.subarray(0, 4));
  const second_rnd = new Uint8Array(4);
  second_rnd.set(pub.subarray(0, 4));

  first_rnd[0] = first_rnd[0] & 0b0111_1111;
  second_rnd[0] = second_rnd[0] | 0b1000_0000;

  const first_part = new Uint8Array(first_rnd.length + pub.length / 2);
  first_part.set(first_rnd, 0);
  first_part.set(pub.subarray(0, 16), 4);

  const second_part = new Uint8Array(first_rnd.length + pub.length / 2);
  second_part.set(second_rnd, 0);
  second_part.set(pub.subarray(16, 32), 4);

  const prefix =
    addr[0] === "t" && addr[1] == "b"
      ? "tb"
      : addr[0] === "b" && addr[1] == "c" && addr[2] === "r" && addr[3] == "t"
        ? "bcrt"
        : addr[0] === "b" && addr[1] == "c"
          ? "bc"
          : undefined;
  if (prefix === undefined) {
    return Result.error(GenerateSegwitAddrError.WRONG_PREFIX);
  }

  const addr1 = BitcoinSewgit.encode(prefix, 0, Array.from(first_part));
  if (Result.isError(addr1)) {
    return Result.error(GenerateSegwitAddrError.INVALID_SEGWIT);
  }
  const addr2 = BitcoinSewgit.encode(prefix, 0, Array.from(second_part));
  if (Result.isError(addr2)) {
    return Result.error(GenerateSegwitAddrError.INVALID_SEGWIT);
  }
  const result: [BtAddrString, BtAddrString] = [addr1.value, addr2.value];
  return Result.of(result);
}

// https://github.com/bitcoin/bitcoin/blob/master/src/policy/policy.cpp
export function segwitMinAmount(currency: string): AmountJson {
  return Amounts.parseOrThrow(`${currency}:0.00000294`);
}
