function shouldSkipCurrency(
  transactionsRequest:
    | TransactionsRequest
    | GetTransactionsV2Request
    | undefined,
  currency: string,
  exchangesInTransaction: string[],
): boolean {
  if (transactionsRequest?.scopeInfo) {
    const sameCurrency = Amounts.isSameCurrency(
      currency,
      transactionsRequest.scopeInfo.currency,
    );
    switch (transactionsRequest.scopeInfo.type) {
      case ScopeType.Global: {
        return !sameCurrency;
      }
      case ScopeType.Exchange: {
        return (
          !sameCurrency ||
          (exchangesInTransaction.length > 0 &&
            !exchangesInTransaction.includes(transactionsRequest.scopeInfo.url))
        );
      }
      case ScopeType.Auditor: {
        // same currency and same auditor
        throw TalerError.fromDetail(
          TalerErrorCode.WALLET_CORE_API_BAD_REQUEST,
          { parameter: "scopeInfo" },
          "filtering transactions by auditor scope is not implemented",
        );
      }
      case ScopeType.ExchangeLegacyKeys: {
        // A transaction records the exchanges it involved by URL, which does
        // not say which key set signed the coins, so this filter cannot be
        // answered accurately.  Refusing beats quietly returning the
        // transactions of the exchange's current key set as if they were the
        // superseded ones.
        throw TalerError.fromDetail(
          TalerErrorCode.WALLET_CORE_API_BAD_REQUEST,
          { parameter: "scopeInfo" },
          "filtering transactions by a superseded exchange key set is not implemented",
        );
      }
      default:
        assertUnreachable(transactionsRequest.scopeInfo);
    }
  }
  if (transactionsRequest?.currency) {
    return (
      transactionsRequest.currency.toLowerCase() !== currency.toLowerCase()
    );
  }
  return false;
}

/**
 * Fallback order of transactions that have the same timestamp.
 */
const txOrder: { [t in TransactionType]: number } = {
  [TransactionType.Withdrawal]: 1,
  [TransactionType.Payment]: 3,
  [TransactionType.PeerPullCredit]: 4,
  [TransactionType.PeerPullDebit]: 5,
  [TransactionType.PeerPushCredit]: 6,
  [TransactionType.PeerPushDebit]: 7,
  [TransactionType.Refund]: 8,
  [TransactionType.Deposit]: 9,
  [TransactionType.Refresh]: 10,
  [TransactionType.Recoup]: 11,
  [TransactionType.InternalWithdrawal]: 12,
  [TransactionType.DenomLoss]: 13,
};

/**
 * Error for a transaction identifier that the client made up: either it does
 * not parse at all, or it denotes a different transaction type than the
 * operation accepts.
 */
export function makeInvalidTransactionIdError(
  transactionId: string,
  expectedType?: TransactionType,
): TalerError {
  const hint =
    expectedType == null
      ? `invalid transaction identifier "${transactionId}"`
      : `expected a ${expectedType} transaction identifier, got "${transactionId}"`;
  return TalerError.fromDetail(
    TalerErrorCode.WALLET_CORE_API_BAD_REQUEST,
    { parameter: "transactionId" },
    hint,
  );
}

/**
 * Error for a well-formed transaction identifier that the wallet has no
 * record for.  Distinct from {@link makeInvalidTransactionIdError}: the client
 * asked for something reasonable, it just isn't (or is no longer) there.
 */
export function makeTransactionNotFoundError(
  transactionId: string,
): TalerError {
  return TalerError.fromDetail(
    TalerErrorCode.WALLET_TRANSACTION_NOT_FOUND,
    { transactionId },
    `transaction ${transactionId} not found`,
  );
}

/**
 * Error for an action (abort/suspend/resume/fail) that this kind of
 * transaction does not offer at all.  Not to be confused with
 * WALLET_REQUEST_TRANSACTION_STATE_UNSUPPORTED, which means the action exists
 * but the transaction is currently in a state that does not allow it.
 */
export function makeTransactionActionUnsupportedError(
  transactionId: string,
  action: "abort" | "suspend" | "resume" | "fail" | "lookup",
  hint?: string,
): TalerError {
  return TalerError.fromDetail(
    TalerErrorCode.WALLET_TRANSACTION_ACTION_UNSUPPORTED,
    { transactionId, action },
    hint ?? `transaction ${transactionId} cannot be ${action}ed`,
  );
}

export async function getTransactionById(
  wex: WalletExecutionContext,
  req: TransactionByIdRequest,
): Promise<Transaction> {
  const parsedTx = parseTransactionIdentifier(req.transactionId);

  if (!parsedTx) {
    throw makeInvalidTransactionIdError(req.transactionId);
  }

  switch (parsedTx.tag) {
    case TransactionType.InternalWithdrawal:
    case TransactionType.Withdrawal:
    case TransactionType.DenomLoss:
    case TransactionType.Recoup:
    case TransactionType.PeerPushDebit:
    case TransactionType.PeerPushCredit:
    case TransactionType.Refresh:
    case TransactionType.PeerPullCredit:
    case TransactionType.Payment:
    case TransactionType.Deposit:
    case TransactionType.PeerPullDebit:
    case TransactionType.Refund: {
      const ctx = await getContextForTransaction(wex, req.transactionId);
      const result = await wex.runWalletDbTx(async (tx) => ({
        txDetails: await ctx.lookupFullTransaction(tx, {
          includeContractTerms: req.includeContractTerms,
        }),
        localIdent: (
          await tx.getLocalTransactionIdentifiers([req.transactionId])
        ).get(req.transactionId),
      }));
      if (!result.txDetails) {
        throw TalerError.fromDetail(
          TalerErrorCode.WALLET_TRANSACTION_NOT_FOUND,
          { transactionId: req.transactionId },
          `transaction ${req.transactionId} not found`,
        );
      }
      return withLocalTransactionIdentifier(
        result.txDetails,
        result.localIdent,
      );
    }
  }
}

function withLocalTransactionIdentifier(
  tx: Transaction,
  localIdent: string | undefined,
): Transaction {
  if (localIdent == null) {
    return tx;
  }
  return {
    ...tx,
    localTransactionId: `#${tx.type}:${localIdent}`,
  } as Transaction;
}

/**
 * Resolve either the stable transaction ID or the backend's optional local
 * identifier.  A local ID is deliberately scoped by its type and never
 * survives a wallet import or merge.
 */
export async function resolveTransactionReference(
  wex: WalletExecutionContext,
  req: ResolveTransactionReferenceRequest,
): Promise<ResolveTransactionReferenceResponse> {
  const ref = req.transactionReference;
  if (parseTransactionIdentifier(ref) != null) {
    return { transactionId: ref as TransactionIdStr };
  }
  const match = /^#([^:]+):([^:]+)$/.exec(ref);
  if (match != null) {
    if (!Object.values(TransactionType).includes(match[1] as TransactionType)) {
      throw makeInvalidTransactionIdError(ref);
    }
    const [, transactionType, localIdent] = match;
    const transactionId = await wex.runWalletDbTx((tx) =>
      tx.getTransactionIdByLocalIdentifier(transactionType, localIdent),
    );
    if (transactionId == null) {
      throw makeTransactionNotFoundError(ref);
    }
    const parsed = parseTransactionIdentifier(transactionId);
    if (parsed?.tag !== transactionType) {
      throw Error("local transaction identifier has inconsistent type");
    }
    return { transactionId: transactionId as TransactionIdStr };
  }

  // LSD 0006 withdrawal-transfer-result references are bank-generated opaque
  // strings that contain the reserve public key.  The status carried next to
  // the reference is deliberately not applied here: it is only a UI hint and
  // wallet-core's transaction state remains authoritative.
  const withdrawalMatches = await wex.runWalletDbTx(async (tx) =>
    (await tx.listAllWithdrawalGroups()).filter((wg) =>
      ref.includes(wg.reservePub),
    ),
  );
  if (withdrawalMatches.length !== 1) {
    throw makeTransactionNotFoundError(ref);
  }
  return {
    transactionId: constructTransactionIdentifier({
      tag: TransactionType.Withdrawal,
      withdrawalGroupId: withdrawalMatches[0].withdrawalGroupId,
    }),
  };
}

export function isUnsuccessfulTransaction(state: TransactionState): boolean {
  return (
    state.major === TransactionMajorState.Aborted ||
    state.major === TransactionMajorState.Expired ||
    state.major === TransactionMajorState.Aborting ||
    state.major === TransactionMajorState.Deleted ||
    state.major === TransactionMajorState.Failed
  );
}

function checkFilterIncludes(
  req: GetTransactionsV2Request | undefined,
  mtx: WalletTransactionMeta,
): boolean {
  if (shouldSkipCurrency(req, mtx.currency, mtx.exchanges)) {
    return false;
  }

  const parsedTx = parseTransactionIdentifier(mtx.transactionId);
  if (
    parsedTx?.tag === TransactionType.Refresh &&
    !(req?.includeRefreshes || req?.includeAll)
  ) {
    return false;
  }

  if (!req?.includeAll) {
    if (
      parsedTx?.tag === TransactionType.Payment &&
      mtx.status === PurchaseStatus.DoneRepurchaseDetected
    ) {
      return false;
    }
  }

  let included: boolean;

  const filter = req?.filterByState;
  switch (filter) {
    case "done":
      included =
        mtx.status >= OPERATION_STATUS_DONE_FIRST &&
        mtx.status <= OPERATION_STATUS_DONE_LAST;
      break;
    case "final":
      included = !(
        mtx.status >= OPERATION_STATUS_NONFINAL_FIRST &&
        mtx.status <= OPERATION_STATUS_NONFINAL_LAST
      );
      break;
    case "nonfinal-approved":
    case "nonfinal-dialog":
    case "nonfinal":
      included =
        mtx.status >= OPERATION_STATUS_NONFINAL_FIRST &&
        mtx.status <= OPERATION_STATUS_NONFINAL_LAST;
      if (filter === "nonfinal-approved") {
        included =
          included &&
          !(
            mtx.status >= OPERATION_STATUS_DIALOG_FIRST &&
            mtx.status <= OPERATION_STATUS_DIALOG_LAST
          );
      } else if (filter === "nonfinal-dialog") {
        included =
          included &&
          mtx.status >= OPERATION_STATUS_DIALOG_FIRST &&
          mtx.status <= OPERATION_STATUS_DIALOG_LAST;
      }
      break;
    case undefined:
      included = true;
      break;
    default:
      assertUnreachable(filter);
  }
  return included;
}

async function addFiltered(
  wex: WalletExecutionContext,
  tx: WalletDbTransaction,
  req: GetTransactionsV2Request | undefined,
  target: Transaction[],
  source: WalletTransactionMeta[],
): Promise<number> {
  let numAdded: number = 0;
  const localIdentifiers = await tx.getLocalTransactionIdentifiers(
    source.map((x) => x.transactionId),
  );
  for (const mtx of source) {
    if (req?.limit != null && target.length >= Math.abs(req.limit)) {
      break;
    }
    if (checkFilterIncludes(req, mtx)) {
      const ctx = await getContextForTransaction(wex, mtx.transactionId);
      const txDetails = await ctx.lookupFullTransaction(tx);
      // FIXME: This means that in some cases we can return fewer transactions
      // than requested.
      if (!txDetails) {
        logger.warn(
          `full transaction details missing for transaction ${mtx.transactionId}`,
        );
        continue;
      }
      numAdded += 1;
      target.push(
        withLocalTransactionIdentifier(
          txDetails,
          localIdentifiers.get(mtx.transactionId),
        ),
      );
    }
  }
  return numAdded;
}

/**
 * Sort transactions in-place according to the request.
 */
function sortTransactions(
  req: GetTransactionsV2Request | undefined,
  transactions: Transaction[],
): void {
  let sortSign: number;
  if (req?.limit != null && req.limit < 0) {
    sortSign = -1;
  } else {
    sortSign = 1;
  }
  const txCmp = (h1: Transaction, h2: Transaction) => {
    // Order transactions by timestamp.  Newest transactions come first.
    const tsCmp = AbsoluteTime.cmp(
      AbsoluteTime.fromPreciseTimestamp(h1.timestamp),
      AbsoluteTime.fromPreciseTimestamp(h2.timestamp),
    );
    // Match the unique database cursor order for equal timestamps.
    if (tsCmp === 0) {
      const idCmp =
        h1.transactionId < h2.transactionId
          ? -1
          : h1.transactionId > h2.transactionId
            ? 1
            : 0;
      return sortSign * idCmp;
    }
    return sortSign * tsCmp;
  };
  transactions.sort(txCmp);
}

async function findOffsetCursor(
  tx: WalletDbTransaction,
  req?: GetTransactionsV2Request,
): Promise<WalletTransactionMetaCursor | undefined> {
  const forwards = req?.limit == null || req.limit >= 0;
  if (req?.offsetTransactionId) {
    const res = await tx.getTransactionMeta(req.offsetTransactionId);
    if (res) {
      return { timestamp: res.timestamp, transactionId: res.transactionId };
    }
    if (!req.offsetTimestamp) {
      throw TalerError.fromDetail(
        TalerErrorCode.WALLET_TRANSACTION_NOT_FOUND,
        { transactionId: req.offsetTransactionId },
        `offset transaction ${req.offsetTransactionId} not found and no offset timestamp specified`,
      );
    }
  }
  if (!req?.offsetTimestamp) {
    return undefined;
  }
  const timestamp = timestampPreciseToDb(req.offsetTimestamp);
  if (!req.offsetTransactionId) {
    const atTimestamp = await tx.getTransactionMetaAtTimestamp(timestamp);
    if (atTimestamp) {
      return {
        timestamp: atTimestamp.timestamp,
        transactionId: atTimestamp.transactionId,
      };
    }
  }
  // No live transaction is available to anchor the cursor.  Conservatively
  // replay the whole run at this timestamp: use its low edge when paging
  // forward and its high edge when paging backward.  This guarantees that no
  // surviving transaction is skipped, at the cost of possibly returning one
  // from the preceding page again.
  return {
    timestamp,
    transactionId: forwards ? "" : "\uffff",
  };
}

export async function getTransactionsV2(
  wex: WalletExecutionContext,
  transactionsRequest?: GetTransactionsV2Request,
): Promise<TransactionsResponse> {
  // The implementation of this function is optimized for
  // the common fast path of requesting transactions
  // in an ascending order.
  // Other requests are more difficult to implement
  // in a performant way due to IndexedDB limitations.

  const resultTransactions: Transaction[] = [];

  await wex.runWalletDbTx(async (tx) => {
    let forwards =
      transactionsRequest?.limit == null || transactionsRequest.limit >= 0;
    let limit =
      transactionsRequest?.limit != null
        ? Math.abs(transactionsRequest.limit)
        : undefined;
    let cursor = await findOffsetCursor(tx, transactionsRequest);

    if (limit == null && cursor == null) {
      // Fast path for returning *everything* that matches the filter.
      // FIXME: We could use the DB for filtering here
      const res = await tx.listTransactionMetaByStatus({
        onlyActive: false,
      });
      await addFiltered(wex, tx, transactionsRequest, resultTransactions, res);
    } else {
      if (limit === 0) {
        return;
      }
      while (limit == null || resultTransactions.length < limit) {
        const remaining =
          limit == null ? 128 : Math.max(1, limit - resultTransactions.length);
        const pageSize = Math.min(256, Math.max(32, remaining * 2));
        const page = await tx.listTransactionMetaPage({
          cursor,
          direction: forwards ? "forward" : "backward",
          limit: pageSize,
        });
        if (page.length === 0) {
          break;
        }
        await addFiltered(
          wex,
          tx,
          transactionsRequest,
          resultTransactions,
          page,
        );
        const last = page[page.length - 1];
        cursor = {
          timestamp: last.timestamp,
          transactionId: last.transactionId,
        };
        if (page.length < pageSize) {
          break;
        }
      }
    }
  });

  sortTransactions(transactionsRequest, resultTransactions);

  return {
    transactions: resultTransactions,
  };
}

/**
 * Retrieve the full event history for this wallet.
 */
export async function getTransactions(
  wex: WalletExecutionContext,
  transactionsRequest?: TransactionsRequest,
): Promise<TransactionsResponse> {
  const transactions: Transaction[] = [];

  const onlyActive = transactionsRequest?.filterByState === "nonfinal";

  await wex.runWalletDbTx(async (tx) => {
    const allMetaTransactions = await tx.listTransactionMetaByStatus({
      onlyActive,
    });
    const localIdentifiers = await tx.getLocalTransactionIdentifiers(
      allMetaTransactions.map((x) => x.transactionId),
    );
    for (const metaTx of allMetaTransactions) {
      if (
        shouldSkipCurrency(
          transactionsRequest,
          metaTx.currency,
          metaTx.exchanges,
        )
      ) {
        continue;
      }

      const parsedTx = parseTransactionIdentifier(metaTx.transactionId);
      if (
        parsedTx?.tag === TransactionType.Refresh &&
        !transactionsRequest?.includeRefreshes
      ) {
        continue;
      }

      const ctx = await getContextForTransaction(wex, metaTx.transactionId);
      const txDetails = await ctx.lookupFullTransaction(tx);
      if (!txDetails) {
        continue;
      }
      transactions.push(
        withLocalTransactionIdentifier(
          txDetails,
          localIdentifiers.get(metaTx.transactionId),
        ),
      );
    }
  });

  // One-off checks, because of a bug where the wallet previously
  // did not migrate the DB correctly and caused these amounts
  // to be missing sometimes.
  for (let tx of transactions) {
    if (!tx.amountEffective) {
      logger.warn(`missing amountEffective in ${j2s(tx)}`);
    }
    if (!tx.amountRaw) {
      logger.warn(`missing amountRaw in ${j2s(tx)}`);
    }
    if (!tx.timestamp) {
      logger.warn(`missing timestamp in ${j2s(tx)}`);
    }
  }

  const isPending = (x: Transaction) =>
    x.txState.major === TransactionMajorState.Pending ||
    x.txState.major === TransactionMajorState.Aborting ||
    x.txState.major === TransactionMajorState.Dialog;

  let sortSign: number;
  if (transactionsRequest?.sort == "descending") {
    sortSign = -1;
  } else {
    sortSign = 1;
  }

  const txCmp = (h1: Transaction, h2: Transaction) => {
    // Order transactions by timestamp.  Newest transactions come first.
    const tsCmp = AbsoluteTime.cmp(
      AbsoluteTime.fromPreciseTimestamp(h1.timestamp),
      AbsoluteTime.fromPreciseTimestamp(h2.timestamp),
    );
    // If the timestamp is exactly the same, order by transaction type.
    if (tsCmp === 0) {
      return Math.sign(txOrder[h1.type] - txOrder[h2.type]);
    }
    return sortSign * tsCmp;
  };

  if (transactionsRequest?.sort === "stable-ascending") {
    transactions.sort(txCmp);
    return { transactions };
  }

  const txPending = transactions.filter((x) => isPending(x));
  const txNotPending = transactions.filter((x) => !isPending(x));

  txPending.sort(txCmp);
  txNotPending.sort(txCmp);

  return { transactions: [...txPending, ...txNotPending] };
}

/**
 * Re-create materialized transactions from scratch.
 *
 * Used for migrations.
 */
export async function rematerializeTransactions(
  wex: WalletExecutionContext,
  tx: WalletDbTransaction,
): Promise<void> {
  logger.trace("re-materializing transactions");

  await tx.deleteAllTransactionMeta();

  for (const x of await tx.listAllPeerPushDebits()) {
    const ctx = new PeerPushDebitTransactionContext(wex, x.pursePub);
    await ctx.updateTransactionMeta(tx);
  }

  for (const x of await tx.listAllPeerPushCredits()) {
    const ctx = new PeerPushCreditTransactionContext(wex, x.peerPushCreditId);
    await ctx.updateTransactionMeta(tx);
  }

  for (const x of await tx.listAllPeerPullCredits()) {
    const ctx = new PeerPullCreditTransactionContext(wex, x.pursePub);
    await ctx.updateTransactionMeta(tx);
  }

  for (const x of await tx.listAllPeerPullDebits()) {
    const ctx = new PeerPullDebitTransactionContext(wex, x.peerPullDebitId);
    await ctx.updateTransactionMeta(tx);
  }

  for (const x of await tx.listAllRefundGroups()) {
    const ctx = new RefundTransactionContext(wex, x.refundGroupId);
    await ctx.updateTransactionMeta(tx);
  }

  for (const x of await tx.listAllRefreshGroups()) {
    const ctx = new RefreshTransactionContext(wex, x.refreshGroupId);
    await ctx.updateTransactionMeta(tx);
  }

  for (const x of await tx.listAllWithdrawalGroups()) {
    const ctx = new WithdrawTransactionContext(wex, x.withdrawalGroupId);
    await ctx.updateTransactionMeta(tx);
  }

  for (const x of await tx.listAllDenomLossEvents()) {
    const ctx = new DenomLossTransactionContext(wex, x.denomLossEventId);
    await ctx.updateTransactionMeta(tx);
  }

  for (const x of await tx.listAllDepositGroups()) {
    const ctx = new DepositTransactionContext(wex, x.depositGroupId);
    await ctx.updateTransactionMeta(tx);
  }

  for (const x of await tx.listAllPurchases()) {
    const ctx = new PayMerchantTransactionContext(wex, x.proposalId);
    await ctx.updateTransactionMeta(tx);
  }
}

export type ParsedTransactionIdentifier =
  | { tag: TransactionType.Deposit; depositGroupId: string }
  | { tag: TransactionType.Payment; proposalId: string }
  | { tag: TransactionType.PeerPullDebit; peerPullDebitId: string }
  | { tag: TransactionType.PeerPullCredit; pursePub: string }
  | { tag: TransactionType.PeerPushCredit; peerPushCreditId: string }
  | { tag: TransactionType.PeerPushDebit; pursePub: string }
  | { tag: TransactionType.Refresh; refreshGroupId: string }
  | { tag: TransactionType.Refund; refundGroupId: string }
  | { tag: TransactionType.Withdrawal; withdrawalGroupId: string }
  | { tag: TransactionType.InternalWithdrawal; withdrawalGroupId: string }
  | { tag: TransactionType.Recoup; recoupGroupId: string }
  | { tag: TransactionType.DenomLoss; denomLossEventId: string };

export function constructTransactionIdentifier(
  pTxId: ParsedTransactionIdentifier,
): TransactionIdStr {
  switch (pTxId.tag) {
    case TransactionType.Deposit:
      return `txn:${pTxId.tag}:${pTxId.depositGroupId}` as TransactionIdStr;
    case TransactionType.Payment:
      return `txn:${pTxId.tag}:${pTxId.proposalId}` as TransactionIdStr;
    case TransactionType.PeerPullCredit:
      return `txn:${pTxId.tag}:${pTxId.pursePub}` as TransactionIdStr;
    case TransactionType.PeerPullDebit:
      return `txn:${pTxId.tag}:${pTxId.peerPullDebitId}` as TransactionIdStr;
    case TransactionType.PeerPushCredit:
      return `txn:${pTxId.tag}:${pTxId.peerPushCreditId}` as TransactionIdStr;
    case TransactionType.PeerPushDebit:
      return `txn:${pTxId.tag}:${pTxId.pursePub}` as TransactionIdStr;
    case TransactionType.Refresh:
      return `txn:${pTxId.tag}:${pTxId.refreshGroupId}` as TransactionIdStr;
    case TransactionType.Refund:
      return `txn:${pTxId.tag}:${pTxId.refundGroupId}` as TransactionIdStr;
    case TransactionType.Withdrawal:
      return `txn:${pTxId.tag}:${pTxId.withdrawalGroupId}` as TransactionIdStr;
    case TransactionType.InternalWithdrawal:
      return `txn:${pTxId.tag}:${pTxId.withdrawalGroupId}` as TransactionIdStr;
    case TransactionType.Recoup:
      return `txn:${pTxId.tag}:${pTxId.recoupGroupId}` as TransactionIdStr;
    case TransactionType.DenomLoss:
      return `txn:${pTxId.tag}:${pTxId.denomLossEventId}` as TransactionIdStr;
    default:
      assertUnreachable(pTxId);
  }
}

/**
 * Parse a transaction identifier string into a typed, structured representation.
 *
 * Returns undefined for every kind of malformed identifier, so that callers can
 * report one coded error instead of the shape of the failure deciding whether
 * they see an exception or a missing value.
 */
export function parseTransactionIdentifier(
  transactionId: string,
): ParsedTransactionIdentifier | undefined {
  const txnParts = transactionId.split(":");

  if (txnParts.length !== 3) {
    return undefined;
  }

  const [prefix, type, ...rest] = txnParts;

  if (prefix != "txn") {
    return undefined;
  }
  if (!rest[0]) {
    return undefined;
  }

  switch (type) {
    case TransactionType.Deposit:
      return { tag: TransactionType.Deposit, depositGroupId: rest[0] };
    case TransactionType.Payment:
      return { tag: TransactionType.Payment, proposalId: rest[0] };
    case TransactionType.PeerPullCredit:
      return { tag: TransactionType.PeerPullCredit, pursePub: rest[0] };
    case TransactionType.PeerPullDebit:
      return {
        tag: TransactionType.PeerPullDebit,
        peerPullDebitId: rest[0],
      };
    case TransactionType.PeerPushCredit:
      return {
        tag: TransactionType.PeerPushCredit,
        peerPushCreditId: rest[0],
      };
    case TransactionType.PeerPushDebit:
      return { tag: TransactionType.PeerPushDebit, pursePub: rest[0] };
    case TransactionType.Refresh:
      return { tag: TransactionType.Refresh, refreshGroupId: rest[0] };
    case TransactionType.Refund:
      return {
        tag: TransactionType.Refund,
        refundGroupId: rest[0],
      };
    case TransactionType.Withdrawal:
      return {
        tag: TransactionType.Withdrawal,
        withdrawalGroupId: rest[0],
      };
    case TransactionType.InternalWithdrawal:
      return {
        tag: TransactionType.InternalWithdrawal,
        withdrawalGroupId: rest[0],
      };
    case TransactionType.Recoup:
      return {
        tag: TransactionType.Recoup,
        recoupGroupId: rest[0],
      };
    case TransactionType.DenomLoss:
      return {
        tag: TransactionType.DenomLoss,
        denomLossEventId: rest[0],
      };
    default:
      return undefined;
  }
}

function maybeTaskFromTransaction(
  transactionId: string,
): TaskIdStr | undefined {
  const parsedTx = parseTransactionIdentifier(transactionId);

  if (!parsedTx) {
    throw makeInvalidTransactionIdError(transactionId);
  }

  // FIXME: We currently don't cancel active long-polling tasks here.

  switch (parsedTx.tag) {
    case TransactionType.PeerPullCredit:
      return constructTaskIdentifier({
        tag: PendingTaskType.PeerPullCredit,
        pursePub: parsedTx.pursePub,
      });
    case TransactionType.Deposit:
      return constructTaskIdentifier({
        tag: PendingTaskType.Deposit,
        depositGroupId: parsedTx.depositGroupId,
      });
    case TransactionType.InternalWithdrawal:
    case TransactionType.Withdrawal:
      return constructTaskIdentifier({
        tag: PendingTaskType.Withdraw,
        withdrawalGroupId: parsedTx.withdrawalGroupId,
      });
    case TransactionType.Payment:
      return constructTaskIdentifier({
        tag: PendingTaskType.Purchase,
        proposalId: parsedTx.proposalId,
      });
    case TransactionType.Refresh:
      return constructTaskIdentifier({
        tag: PendingTaskType.Refresh,
        refreshGroupId: parsedTx.refreshGroupId,
      });
    case TransactionType.PeerPullDebit:
      return constructTaskIdentifier({
        tag: PendingTaskType.PeerPullDebit,
        peerPullDebitId: parsedTx.peerPullDebitId,
      });
    case TransactionType.PeerPushCredit:
      return constructTaskIdentifier({
        tag: PendingTaskType.PeerPushCredit,
        peerPushCreditId: parsedTx.peerPushCreditId,
      });
    case TransactionType.PeerPushDebit:
      return constructTaskIdentifier({
        tag: PendingTaskType.PeerPushDebit,
        pursePub: parsedTx.pursePub,
      });
    case TransactionType.Refund:
      // Nothing to do for a refund transaction.
      return undefined;
    case TransactionType.Recoup:
      return constructTaskIdentifier({
        tag: PendingTaskType.Recoup,
        recoupGroupId: parsedTx.recoupGroupId,
      });
    case TransactionType.DenomLoss:
      // Nothing to do for denom loss
      return undefined;
    default:
      assertUnreachable(parsedTx);
  }
}

/**
 * Immediately retry the underlying operation
 * of a transaction.
 */
export async function retryTransaction(
  wex: WalletExecutionContext,
  transactionId: string,
): Promise<void> {
  await requireTransactionAction(wex, transactionId, TransactionAction.Retry);
  logger.info(`resetting retry timeout for ${transactionId}`);
  const taskId = maybeTaskFromTransaction(transactionId);
  if (taskId) {
    await wex.taskScheduler.resetTask(taskId);
  }
}

/**
 * Reset the task retry counter for all tasks.
 */
export async function retryAll(wex: WalletExecutionContext): Promise<void> {
  await wex.taskScheduler.ensureRunning();
  const tasks = wex.taskScheduler.getActiveTasks();
  for (const task of tasks) {
    await wex.taskScheduler.resetTask(task);
  }
}

/**
 * Restart all the running tasks.
 */
export async function restartAll(wex: WalletExecutionContext): Promise<void> {
  await wex.taskScheduler.reload();
}

async function getContextForTransaction(
  wex: WalletExecutionContext,
  transactionId: string,
): Promise<TransactionContext> {
  const tx = parseTransactionIdentifier(transactionId);
  if (!tx) {
    throw makeInvalidTransactionIdError(transactionId);
  }
  switch (tx.tag) {
    case TransactionType.Deposit:
      return new DepositTransactionContext(wex, tx.depositGroupId);
    case TransactionType.Refresh:
      return new RefreshTransactionContext(wex, tx.refreshGroupId);
    case TransactionType.InternalWithdrawal:
    case TransactionType.Withdrawal:
      return new WithdrawTransactionContext(wex, tx.withdrawalGroupId);
    case TransactionType.Payment:
      return new PayMerchantTransactionContext(wex, tx.proposalId);
    case TransactionType.PeerPullCredit:
      return new PeerPullCreditTransactionContext(wex, tx.pursePub);
    case TransactionType.PeerPushDebit:
      return new PeerPushDebitTransactionContext(wex, tx.pursePub);
    case TransactionType.PeerPullDebit:
      return new PeerPullDebitTransactionContext(wex, tx.peerPullDebitId);
    case TransactionType.PeerPushCredit:
      return new PeerPushCreditTransactionContext(wex, tx.peerPushCreditId);
    case TransactionType.Refund:
      return new RefundTransactionContext(wex, tx.refundGroupId);
    case TransactionType.Recoup:
      //return new RecoupTransactionContext(ws, tx.recoupGroupId);
      throw TalerError.fromDetail(
        TalerErrorCode.WALLET_TRANSACTION_ACTION_UNSUPPORTED,
        { transactionId, action: "lookup" },
        "recoup transactions cannot be inspected yet",
      );
    case TransactionType.DenomLoss:
      return new DenomLossTransactionContext(wex, tx.denomLossEventId);
    default:
      assertUnreachable(tx);
  }
}

/**
 * Resolve a transaction and verify that its current public state advertises
 * the requested user action.
 *
 * Transaction contexts still validate their own state transitions.  This
 * check is the common API boundary that keeps every action dispatcher aligned
 * with the actions returned to clients.
 */
async function requireTransactionAction(
  wex: WalletExecutionContext,
  transactionId: string,
  action: TransactionAction,
): Promise<TransactionContext> {
  const ctx = await getContextForTransaction(wex, transactionId);
  const transaction = await wex.runWalletDbTx(async (tx) =>
    ctx.lookupFullTransaction(tx),
  );
  if (!transaction) {
    throw makeTransactionNotFoundError(transactionId);
  }
  if (!transaction.txActions.includes(action)) {
    throw TalerError.fromDetail(
      TalerErrorCode.WALLET_REQUEST_TRANSACTION_STATE_UNSUPPORTED,
      {
        txState: transaction.txState,
        debugStateNum: transaction.stId,
      },
      `transaction ${transactionId} does not allow ${action} in its current state`,
    );
  }
  return ctx;
}

/**
 * Suspends a pending transaction, stopping any associated network activities,
 * but with a chance of trying again at a later time. This could be useful if
 * a user needs to save battery power or bandwidth and an operation is expected
 * to take longer (such as a backup, recovery or very large withdrawal operation).
 */
export async function suspendTransaction(
  wex: WalletExecutionContext,
  transactionId: string,
): Promise<void> {
  const ctx = await requireTransactionAction(
    wex,
    transactionId,
    TransactionAction.Suspend,
  );
  await ctx.userSuspendTransaction();
}

export async function failTransaction(
  wex: WalletExecutionContext,
  transactionId: string,
): Promise<void> {
  const ctx = await requireTransactionAction(
    wex,
    transactionId,
    TransactionAction.Fail,
  );
  await ctx.userFailTransaction();
}

/**
 * Resume a suspended transaction.
 */
export async function resumeTransaction(
  wex: WalletExecutionContext,
  transactionId: string,
): Promise<void> {
  const ctx = await requireTransactionAction(
    wex,
    transactionId,
    TransactionAction.Resume,
  );
  await ctx.userResumeTransaction();
}

/**
 * Permanently delete a transaction based on the transaction ID.
 */
export async function deleteTransaction(
  wex: WalletExecutionContext,
  transactionId: string,
): Promise<void> {
  const ctx = await requireTransactionAction(
    wex,
    transactionId,
    TransactionAction.Delete,
  );
  await ctx.userDeleteTransaction();
  if (ctx.taskId) {
    wex.taskScheduler.stopShepherdTask(ctx.taskId);
  }
}

export async function abortTransaction(
  wex: WalletExecutionContext,
  transactionId: string,
): Promise<void> {
  const ctx = await requireTransactionAction(
    wex,
    transactionId,
    TransactionAction.Abort,
  );
  await ctx.userAbortTransaction();
}

export interface TransitionInfo {
  // FIXME: Get rid in favor of oldStId
  oldTxState: TransactionState;
  // FIXME: Get rid in favor of newStId
  newTxState: TransactionState;

  balanceEffect: BalanceEffect;

  /**
   * A hint as to why the transition happened.
   *
   * Should not be relied upon by clients.
   */
  causeHint: string | undefined;

  /**
   * Reason for a transition into an error state, reported to clients.
   */
  errorInfo?: ErrorInfoSummary;

  newStId: number;
  oldStId: number;
}

export enum BalanceEffect {
  /**
   * There is no effect on the balance.
   */
  None = 0,
  /**
   * Balance change is internal and should not
   * change the user-visible balance.
   */
  PreserveUserVisible = 1,
  /**
   * The balance preserves the user-visible balance,
   * but might affect user-visible flags.
   */
  Flags = 2,
  /**
   * Balance change can have any effect.
   */
  Any = 3,
}

/**
 * Call the given notification function with a
 * balance effect notification, if necessary.
 */
export function applyNotifyBalanceEffect(
  notify: (n: WalletNotification) => void,
  transactionId: string,
  balanceEffect: BalanceEffect,
): void {
  if (balanceEffect > BalanceEffect.None) {
    notify({
      type: NotificationType.BalanceChange,
      hintTransactionId: transactionId,
      isInternal: balanceEffect <= BalanceEffect.PreserveUserVisible,
    });
  }
}

/**
 * Notify of a state transition and balance change if necessary.
 */
export function applyNotifyTransition(
  notify: (n: WalletNotification) => void,
  transactionId: string,
  transitionInfo: TransitionInfo | undefined,
): void {
  if (
    transitionInfo &&
    !(
      transitionInfo.oldStId === transitionInfo.newStId &&
      transitionInfo.oldTxState.major === transitionInfo.newTxState.major &&
      transitionInfo.oldTxState.minor === transitionInfo.newTxState.minor &&
      !!transitionInfo.oldTxState.working ===
        !!transitionInfo.newTxState.working
    )
  ) {
    notify({
      type: NotificationType.TransactionStateTransition,
      oldTxState: transitionInfo.oldTxState,
      newTxState: transitionInfo.newTxState,
      transactionId,
      causeHint: transitionInfo.causeHint,
      newStId: transitionInfo.newStId,
      ...(transitionInfo.errorInfo
        ? { errorInfo: transitionInfo.errorInfo }
        : {}),
    });

    applyNotifyBalanceEffect(
      notify,
      transactionId,
      transitionInfo.balanceEffect,
    );
  }
}
