export type PaivanaOutputMode =
  | { type: "curl" }
  | { type: "cookie" }
  | { type: "body"; path?: string };

export function parsePaivanaOutputMode(mode: string): PaivanaOutputMode {
  if (mode === "curl") return { type: "curl" };
  if (mode === "cookie") return { type: "cookie" };
  if (mode === "body") return { type: "body" };
  if (mode === "body:-") return { type: "body", path: "-" };
  if (mode.startsWith("body:") && mode.length > "body:".length) {
    return { type: "body", path: mode.substring("body:".length) };
  }
  throw Error(
    `invalid Paivana output mode '${mode}' (expected curl, cookie, body, body:-, or body:PATH)`,
  );
}

/** Quote one argument for a POSIX shell without permitting interpolation. */
export function posixShellQuote(value: string): string {
  return `'${value.replace(/'/g, `'"'"'`)}'`;
}

export function makePaivanaCurlCommand(cookie: string, url: string): string {
  return `curl --location --cookie ${posixShellQuote(cookie)} ${posixShellQuote(url)}`;
}

/** Wget-style Unix filename based only on the originally requested URL. */
export function paivanaBodyFilename(url: string): string {
  const parsed = new URL(url);
  const slash = parsed.pathname.lastIndexOf("/");
  const component = parsed.pathname.substring(slash + 1) || "index.html";
  return component + parsed.search;
}

export function selectAvailableFilename(
  wanted: string,
  exists: (path: string) => boolean,
): string {
  if (!exists(wanted)) return wanted;
  for (let suffix = 1; ; suffix++) {
    const candidate = `${wanted}.${suffix}`;
    if (!exists(candidate)) return candidate;
  }
}
