const logger = new Logger("pay-template.ts");

/**
 * Apply template overrides from the taler://pay-template URI.
 *
 * @param parsedUri parsed Taler pay-template URI
 * @param templateContract template contract details that will be
 *  modified by this function to match the overrides from the URI.
 * @param editableDefaults editable defaults passed on to the client,
 *  will be modified by this function to match the ovverrides from the URI
 */
export function applyTemplateUriOverrides(
  parsedUri: TalerPayTemplateUri,
  templateContract: TemplateContractDetails,
  editableDefaults: TemplateContractDetailsDefaults,
): void {
  switch (templateContract.template_type) {
    case TemplateType.FIXED_ORDER: {
      if (parsedUri.amount) {
        if (parsedUri.editableAmount) {
          editableDefaults.amount = parsedUri.amount;
        } else {
          delete editableDefaults.amount;
          templateContract.amount = parsedUri.amount;
        }
      }
      if (parsedUri.summary) {
        if (parsedUri.editableSummary) {
          editableDefaults.summary = parsedUri.summary;
        } else {
          delete editableDefaults.summary;
          templateContract.summary = parsedUri.summary;
        }
      }
      break;
    }
    case TemplateType.PAIVANA:
      if (parsedUri.amount) {
        if (parsedUri.editableAmount) {
          // FIXME: Not clear if paivana templates should support
          // defaults for editable amounts.
          editableDefaults.amount = parsedUri.amount;
        } else {
          delete editableDefaults.amount;
          for (const c of templateContract.choices) {
            // Use the amount from the URI to override simple choices
            // without fancy inputs.
            if (
              Amounts.isSameCurrency(
                Amounts.currencyOf(c.amount),
                Amounts.currencyOf(parsedUri.amount),
              ) &&
              (c.inputs == null || c.inputs.length == 0)
            ) {
              c.amount = parsedUri.amount;
            }
          }
        }
      }
      if (parsedUri.summary) {
        if (parsedUri.editableSummary) {
          editableDefaults.summary = parsedUri.summary;
        } else {
          delete editableDefaults.summary;
          templateContract.summary = parsedUri.summary;
        }
      }
      break;
    case TemplateType.INVENTORY_CART:
      // We don't support overrides for this template type.
      break;
    default:
      throw TalerError.fromDetail(
        TalerErrorCode.WALLET_CONTRACT_TERMS_UNSUPPORTED,
        {},
        "this wallet does not support this order template type",
      );
  }
}

export function applyTemplateUserOverrides(
  instDetails: UsingTemplateDetailsRequest,
  parsedUri: TalerPayTemplateUri,
  templateContract: TemplateContractDetails,
  editableDefaults: TemplateContractDetailsDefaults,
  params: TemplateParams,
): void {
  switch (templateContract.template_type) {
    case TemplateType.PAIVANA:
    case TemplateType.FIXED_ORDER: {
      if (parsedUri.amount) {
        if (parsedUri.editableAmount) {
          instDetails.amount = params.amount ?? parsedUri.amount;
        } else {
          instDetails.amount = parsedUri.amount;
        }
      } else if (
        templateContract.template_type !== TemplateType.PAIVANA &&
        !templateContract.amount
      ) {
        instDetails.amount =
          params.amount ?? (editableDefaults.amount as AmountString);
      }
      if (parsedUri.summary) {
        if (parsedUri.editableSummary) {
          instDetails.summary = params.summary ?? parsedUri.summary;
        } else {
          instDetails.summary = parsedUri.summary;
        }
      } else if (!templateContract.summary) {
        instDetails.summary = params.summary ?? editableDefaults.summary;
      }
      break;
    }
    case TemplateType.INVENTORY_CART:
      // We don't support overrides for this template type.
      break;
    default:
      throw TalerError.fromDetail(
        TalerErrorCode.WALLET_CONTRACT_TERMS_UNSUPPORTED,
        {},
        "this wallet does not support this order template type",
      );
  }
}

export async function checkPayForTemplate(
  wex: WalletExecutionContext,
  req: CheckPayTemplateRequest,
): Promise<CheckPayTemplateReponse> {
  return runWithMaybeProgressContext(
    wex,
    "checkPayForTemplate",
    req.progressToken,
    () => internalCheckPayForTemplate(wex, req),
  );
}

async function internalCheckPayForTemplate(
  wex: WalletExecutionContext,
  req: CheckPayTemplateRequest,
): Promise<CheckPayTemplateReponse> {
  const parsedUri = Result.orUndefined(
    TalerUris.parseRestricted(
      req.talerPayTemplateUri,
      TalerUriAction.PayTemplate,
    ),
  );
  if (!parsedUri) {
    throw TalerError.fromDetail(
      TalerErrorCode.WALLET_TALER_URI_MALFORMED,
      {
        talerUri: req.talerPayTemplateUri,
        expectedAction: TalerUriAction.PayTemplate,
      },
      "expected a taler://pay-template URI",
    );
  }

  const merchantApi = new TalerMerchantInstanceHttpClient(
    parsedUri.merchantBaseUrl,
    wex.http,
    undefined,
    wex.cancellationToken,
  );

  // Retried under a progress context, like the other merchant queries here.
  const templateDetails = await runWithProgressRetries(wex, async () =>
    succeedOrThrow(await merchantApi.useTemplateGetInfo(parsedUri.templateId)),
  );

  const cfg = await runWithProgressRetries(wex, async () =>
    succeedOrThrow(await merchantApi.getConfig()),
  );

  const currSet = new Set(Object.keys(cfg.currencies));
  currSet.add(cfg.currency);

  let editableDefaults = templateDetails.editable_defaults;
  if (!editableDefaults) {
    templateDetails.editable_defaults = editableDefaults = {};
  }

  applyTemplateUriOverrides(
    parsedUri,
    templateDetails.template_contract,
    editableDefaults,
  );

  return {
    templateDetails,
    supportedCurrencies: [...currSet].sort(),
  };
}

export async function instantiateTemplateRaw(
  wex: WalletExecutionContext,
  req: PreparePayTemplateRequest,
  prefetchedTemplateInfo?: WalletTemplateDetailsResponse,
): Promise<{
  merchantBaseUrl: string;
  orderId: string;
  sessionId: string;
  claimToken: string | undefined;
}> {
  const parsedUri = Result.orUndefined(
    TalerUris.parseRestricted(
      req.talerPayTemplateUri,
      TalerUriAction.PayTemplate,
    ),
  );

  if (!parsedUri) {
    throw TalerError.fromDetail(
      TalerErrorCode.WALLET_TALER_URI_MALFORMED,
      {
        talerUri: req.talerPayTemplateUri,
        expectedAction: TalerUriAction.PayTemplate,
      },
      "expected a taler://pay-template URI",
    );
  }

  const merchantApi = new TalerMerchantInstanceHttpClient(
    parsedUri.merchantBaseUrl,
    wex.http,
    undefined,
    wex.cancellationToken,
  );

  logger.trace(`parsed URI: ${j2s(parsedUri)}`);
  // Retried under a progress context.
  const templateInfo =
    prefetchedTemplateInfo ??
    (await runWithProgressRetries(wex, async () =>
      succeedOrThrow(
        await merchantApi.useTemplateGetInfo(parsedUri.templateId),
      ),
    ));

  let templateDetails: UsingTemplateDetailsRequest;
  switch (templateInfo.template_contract.template_type) {
    case TalerMerchantApi.TemplateType.FIXED_ORDER: {
      templateDetails = {
        template_type: TemplateType.FIXED_ORDER,
      };
      break;
    }

    case TalerMerchantApi.TemplateType.INVENTORY_CART: {
      templateDetails = {
        template_type: TemplateType.INVENTORY_CART,
      };
      break;
    }
    case TalerMerchantApi.TemplateType.PAIVANA: {
      templateDetails = {
        template_type: TemplateType.PAIVANA,
        paivana_id: parsedUri.sessionId!,
        website: parsedUri.fulfillmentUrl!,
      };
      break;
    }
    default:
      assertUnreachable(templateInfo.template_contract);
  }

  let editableDefaults = templateInfo.editable_defaults;
  if (!editableDefaults) {
    editableDefaults = templateInfo.editable_defaults = {};
  }

  applyTemplateUserOverrides(
    templateDetails,
    parsedUri,
    templateInfo.template_contract,
    editableDefaults,
    req.templateParams ?? {},
  );

  // Instantiating a template is not idempotent.  In particular, a transport
  // failure can happen after the merchant committed the new order.  Retrying
  // here would create an additional order with no way to identify the first
  // one, so this POST is attempted exactly once.
  const resp = succeedOrThrow(
    await merchantApi.useTemplateCreateOrder(
      parsedUri.templateId,
      templateDetails,
    ),
  );

  return {
    merchantBaseUrl: parsedUri.merchantBaseUrl,
    orderId: resp.order_id,
    sessionId: parsedUri.sessionId ?? "",
    claimToken: resp.token,
  };
}
