import {
  CancellationToken,
  CancelProgressTokenRequest,
  Duration,
  EmptyObject,
  Logger,
  NotificationType,
  safeStringifyException,
  TalerError,
  TalerErrorCode,
} from "@gnu-taler/taler-util";
import { getRetryDuration } from "./common.js";
import { WalletExecutionContext } from "./wallet.js";

const logger = new Logger("progress.ts");

export interface ProgressContext {
  /**
   * User-defined progress token.
   */
  progressToken: string;
  /**
   * Operation that this progress token is for.
   */
  operation: string;
  /**
   * Did the underlying request finish?
   */
  finished: boolean;
  cts: CancellationToken.Source | undefined;
  onRetryNow?: () => Promise<void>;
  /**
   * Unique counter for this progress context.
   */
  progressContextId: number;
}

function getProgressKey(args: {
  operation: string;
  progressToken: string;
}): string {
  return `${args.operation}:${encodeURIComponent(args.progressToken)}`;
}

let progressContextCounter = 1;

export async function runWithMaybeProgressContext<T>(
  wex: WalletExecutionContext,
  op: string,
  tok: string | undefined,
  f: (pc?: ProgressContext) => Promise<T>,
): Promise<T> {
  if (tok != null) {
    const pc: ProgressContext = {
      operation: op,
      progressToken: tok,
      finished: false,
      onRetryNow: undefined,
      cts: wex.cts,
      progressContextId: progressContextCounter++,
    };
    const key = getProgressKey(pc);
    const oldPc = wex.ws.progressMap.get(key);
    if (oldPc) {
      oldPc.cts?.cancel();
      oldPc.finished = true;
      wex.ws.progressMap.delete(key);
    }
    // Restored below, so that a nested context does not clobber the outer one.
    const prevPc = wex.progressContext;
    try {
      if (!wex.cts) {
        logger.warn(`no cancellation source for ${op}:${tok}`);
      }
      wex.ws.progressMap.set(key, pc);
      // Published on the execution context, as that is how code far away from
      // the handler (fetchFreshExchange, runWithProgressRetries) finds out
      // that the request is retryable and cancellable.
      wex.progressContext = pc;
      emitProgressPhaseNotifications(wex, pc).catch((e) => {
        logger.warn(safeStringifyException(e));
      });
      return await f(pc);
    } finally {
      // Marked finished whether the request succeeded or threw, otherwise the
      // phase notification loop keeps sending "delayed"/"stalled" after the
      // "done" below.
      pc.finished = true;
      wex.progressContext = prevPc;
      // Clean up progress token registration,
      // but only if it is *our* context
      wex.ws.notify({
        type: NotificationType.RequestProgressPhase,
        operation: pc.operation,
        progressToken: pc.progressToken,
        phase: "done",
      });
      const currentPc = wex.ws.progressMap.get(key);
      if (currentPc && currentPc.progressContextId == pc.progressContextId) {
        wex.ws.progressMap.delete(key);
      }
    }
  } else {
    return await f(undefined);
  }
}

/**
 * Emit progress notifications until the request is finished/cancelled.
 */
async function emitProgressPhaseNotifications(
  wex: WalletExecutionContext,
  pc: ProgressContext,
): Promise<void> {
  await wex.ws.timerGroup.resolveAfter(
    Duration.fromSpec({
      seconds: 5,
    }),
  );
  if (wex.cancellationToken.isCancelled || pc.finished) {
    return;
  }
  wex.ws.notify({
    type: NotificationType.RequestProgressPhase,
    operation: pc.operation,
    progressToken: pc.progressToken,
    phase: "delayed",
  });
  await wex.ws.timerGroup.resolveAfter(
    Duration.fromSpec({
      seconds: 5,
    }),
  );
  if (wex.cancellationToken.isCancelled || pc.finished) {
    return;
  }
  wex.ws.notify({
    type: NotificationType.RequestProgressPhase,
    operation: pc.operation,
    progressToken: pc.progressToken,
    phase: "stalled",
  });
}

export async function handleCancelProgressToken(
  wex: WalletExecutionContext,
  req: CancelProgressTokenRequest,
): Promise<EmptyObject> {
  const key = getProgressKey({
    operation: req.operation,
    progressToken: req.progressToken,
  });
  const pc = wex.ws.progressMap.get(key);
  if (!pc) {
    logger.warn("unable to cancel progress token, not found");
    return {};
  }
  pc.cts?.cancel();
  return {};
}

export async function handleRetryProgressTokenNow(
  wex: WalletExecutionContext,
  req: CancelProgressTokenRequest,
): Promise<EmptyObject> {
  const key = getProgressKey({
    operation: req.operation,
    progressToken: req.progressToken,
  });
  const pc = wex.ws.progressMap.get(key);
  if (!pc) {
    logger.warn("unable to retry progress token, not found");
    return {};
  }
  if (!pc.onRetryNow) {
    logger.warn("unable to retry progress token, no retry logic defined");
    return {};
  }
  await pc.onRetryNow();
  emitProgressPhaseNotifications(wex, pc).catch((e) => {
    logger.warn(safeStringifyException(e));
  });
  return {};
}

/**
 * Throw if the request this progress context belongs to should not run
 * anymore, either because the client cancelled it or because a newer request
 * with the same progress token superseded it.
 */
function checkRequestNotCancelled(
  wex: WalletExecutionContext,
  pc: ProgressContext,
): void {
  if (wex.cancellationToken.isCancelled || pc.finished) {
    throw TalerError.fromDetail(
      TalerErrorCode.WALLET_CORE_REQUEST_CANCELLED,
      {},
    );
  }
}

/**
 * Run with retries if there is a progress context.
 * Otherwise, just try once.
 */
export async function runWithProgressRetries<T>(
  wex: WalletExecutionContext,
  f: () => Promise<T>,
): Promise<T> {
  const pc = wex.progressContext;
  if (!pc) {
    return await f();
  }
  let retryCount = 0;
  try {
    while (true) {
      checkRequestNotCancelled(wex, pc);
      const cts = CancellationToken.create();
      pc.onRetryNow = async () => {
        cts.cancel();
        retryCount = 0;
      };
      try {
        return await f();
      } catch (e) {
        // A cancelled request must not be reported as an attempt that is
        // about to be retried, as no further attempt will follow.
        checkRequestNotCancelled(wex, pc);
        const delay = getRetryDuration(retryCount);
        wex.ws.notify({
          type: NotificationType.RequestProgressError,
          operation: pc.operation,
          progressToken: pc.progressToken,
          error: TalerError.fromException(e).errorDetail,
          nextRetryDelay: Duration.toTalerProtocolDuration(delay),
          retryCounter: retryCount,
        });
        retryCount++;
        // Raced against the request's own token, so that cancelling does not
        // have to wait out the backoff, which grows to minutes.
        const didWait = await wex.ws.timerGroup.resolveAfter(
          delay,
          CancellationToken.race(cts.token, wex.cancellationToken),
        );
        if (!didWait) {
          logger.info(`timeout cancelled, retrying immediately`);
        }
      }
    }
  } finally {
    pc.onRetryNow = undefined;
  }
}
