  /**
   * Request: POST /withdraw
   *
   * https://docs.taler.net/core/api-exchange.html#withdrawal
   */
  /**
   * Metadata about the exchange's terms of service: the current
   * `taler-terms-version` etag. (A GET is used since not every HTTP backend
   * supports HEAD.)
   *
   * https://docs.taler.net/core/api-exchange.html#terms-of-service
   */
  async getTermsMeta(): Promise<
    | OperationOk<{ etag: string | undefined }>
    | OperationFail<HttpStatusCode.NotFound>
    | OperationFail<HttpStatusCode.NotImplemented>
  > {
    const resp = await this.fetch("terms");
    switch (resp.status) {
      case HttpStatusCode.Ok: {
        const etag = resp.headers.get("taler-terms-version") || undefined;
        return opFixedSuccess(resp, { etag });
      }
      // The body of these responses is not necessarily a Taler error JSON
      // (e.g. the exchange returns 501 "not configured" as plain text), so we
      // must not try to parse it.
      case HttpStatusCode.NotFound:
        return opKnownFailure(resp, HttpStatusCode.NotFound);
      case HttpStatusCode.NotImplemented:
        return opKnownFailure(resp, HttpStatusCode.NotImplemented);
      default:
        return opUnknownHttpFailure(resp);
    }
  }

