  /**
   * https://docs.taler.net/core/api-exchange.html#get--deposits-$H_WIRE-$MERCHANT_PUB-$H_CONTRACT_TERMS-$COIN_PUB
   *
   * Long-polls until the deposit is wired (200) or the exchange reports a
   * pending (202) state.
   */
  async trackDeposit(args: {
    wireHash: string;
    merchantPub: string;
    contractTermsHash: string;
    coinPub: string;
    merchantSig: string;
    /**
     * Wait for the deposit status to change instead of returning the current
     * status immediately.  Defaults to true for backwards compatibility.
     */
    longpoll?: boolean;
  }): Promise<
    | OperationOk<TrackTransactionWired>
    | OperationAlternative<HttpStatusCode.Accepted, TrackTransactionAccepted>
  > {
    const url = new URL(
      `deposits/${args.wireHash}/${args.merchantPub}/${args.contractTermsHash}/${args.coinPub}`,
      this.baseUrl,
    );
    url.searchParams.set("merchant_sig", args.merchantSig);
    const longpoll = args.longpoll ?? true;
    if (longpoll) {
      url.searchParams.set("lpt", "1");
    }
    const resp = await this.fetch(url, {}, longpoll);
    switch (resp.status) {
      case HttpStatusCode.Ok:
        return opSuccessFromHttp(resp, codecForTackTransactionWired());
      case HttpStatusCode.Accepted:
        return opKnownAlternativeHttpFailure(
          resp,
          resp.status,
          codecForTackTransactionAccepted(),
        );
      default:
        return opUnknownHttpFailure(resp);
    }
  }

