/**
 * Execution context for code that is run in the wallet.
 *
 * Typically the execution context is either for a wallet-core
 * request handler or for a shepherded task.
 */
export interface WalletExecutionContext {
  /**
   * Start a database transaction.
   * Uses the database abstraction layer.
   */
  runWalletDbTx<T>(f: (tx: WalletDbTransaction) => Promise<T>): Promise<T>;
  readonly ws: InternalWalletState;
  readonly cryptoApi: TalerCryptoInterface;
  readonly cancellationToken: CancellationToken;
  readonly http: HttpRequestLibrary;
  readonly oc: ObservabilityContext;
  readonly cts: CancellationToken.Source | undefined;
  readonly taskScheduler: TaskScheduler;
  readonly dbRetryState: DbRetryState;
  progressContext?: ProgressContext;
}

export interface DbRetryState {
  retriedExchangeUpdate?: Set<string>;
}

/** Writer-preferring admission gate for operations that may replace a DB handle. */
export class DbOperationGate {
  private shared = 0;
  private exclusive = false;
  private waitingExclusive = 0;
  private waiters: Array<() => void> = [];

  private async changed(): Promise<void> {
    await new Promise<void>((resolve) => this.waiters.push(resolve));
  }

  private wake(): void {
    const waiters = this.waiters;
    this.waiters = [];
    for (const resolve of waiters) resolve();
  }

  async runShared<T>(f: () => Promise<T>): Promise<T> {
    while (this.exclusive || this.waitingExclusive !== 0) await this.changed();
    this.shared++;
    try {
      return await f();
    } finally {
      this.shared--;
      this.wake();
    }
  }

  async acquireExclusive(
    cancellationToken: CancellationToken = CancellationToken.CONTINUE,
  ): Promise<() => void> {
    this.waitingExclusive++;
    try {
      while (this.exclusive || this.shared !== 0) {
        cancellationToken.throwIfCancelled();
        await cancellationToken.racePromise(this.changed());
      }
      cancellationToken.throwIfCancelled();
      this.exclusive = true;
    } finally {
      this.waitingExclusive--;
      this.wake();
    }
    let released = false;
    return () => {
      if (released) return;
      released = true;
      this.exclusive = false;
      this.wake();
    };
  }

  async runExclusive<T>(
    f: () => Promise<T>,
    cancellationToken: CancellationToken = CancellationToken.CONTINUE,
  ): Promise<T> {
    const release = await this.acquireExclusive(cancellationToken);
    try {
      return await f();
    } finally {
      release();
    }
  }
}

/** Stable facade that resolves the current handle only after shared admission. */
export class AdmittedWalletDbHandle implements WalletDbHandle {
  get name(): string {
    return this.current().name;
  }
  exportToFile?: WalletDbHandle["exportToFile"];
  readBackupJson?: WalletDbHandle["readBackupJson"];
  getDiagnosticStats?: WalletDbHandle["getDiagnosticStats"];

  constructor(
    private current: () => WalletDbHandle,
    private gate: DbOperationGate,
  ) {
    if (current().exportToFile) {
      this.exportToFile = (...args) =>
        gate.runShared(async () => {
          const fn = current().exportToFile;
          if (!fn)
            throw Error("current database backend cannot export to a file");
          return await fn.apply(current(), args);
        });
    }
    if (current().readBackupJson) {
      this.readBackupJson = (...args) =>
        gate.runShared(async () => {
          const fn = current().readBackupJson;
          if (!fn)
            throw Error("current database backend cannot read this backup");
          return await fn.apply(current(), args);
        });
    }
    if (current().getDiagnosticStats) {
      this.getDiagnosticStats = () => current().getDiagnosticStats?.();
    }
  }

  runReadWriteTx<T>(f: (tx: WalletDbTransaction) => Promise<T>): Promise<T> {
    return this.gate.runShared(() => this.current().runReadWriteTx(f));
  }
  exportDatabase(): Promise<any> {
    return this.gate.runShared(() => this.current().exportDatabase());
  }
  importDatabase(
    dump: any,
    finalize: Parameters<WalletDbHandle["importDatabase"]>[1],
  ): Promise<void> {
    return this.gate.runExclusive(() =>
      this.current().importDatabase(dump, finalize),
    );
  }
  clearDatabase(): Promise<void> {
    return this.gate.runExclusive(() => this.current().clearDatabase());
  }
  getAccessStats() {
    return this.current().getAccessStats();
  }
  setNotificationSink(sink: (n: WalletNotification) => void): void {
    this.current().setNotificationSink(sink);
  }
  emitNotification(notification: WalletNotification): void {
    this.current().emitNotification(notification);
  }
  close(): Promise<void> {
    return this.gate.runExclusive(() => this.current().close());
  }
}

