/**
 * Incremented each time we want to re-materialize transactions.
 *
 * Bumped to 4 for BUG-084: after the status-enum digit fixup
 * (fixup20260718StatusEnumDigits) rewrites the raw records, transactionsMeta
 * and its byStatus index must be rebuilt from the corrected values.
 */
const MATERIALIZED_TRANSACTIONS_VERSION = 4;

/** Rebuild the transaction view and durably mark this exact view version. */
export async function rematerializeTransactionsAtCurrentVersion(
  wex: WalletExecutionContext,
  tx: WalletDbTransaction,
): Promise<void> {
  await rematerializeTransactions(wex, tx);
  await tx.upsertConfig({
    key: ConfigRecordKey.MaterializedTransactionsVersion,
    value: MATERIALIZED_TRANSACTIONS_VERSION,
  });
}

export async function migrateMaterializedTransactions(
  wex: WalletExecutionContext,
): Promise<void> {
  await wex.runWalletDbTx(async (tx) => {
    const ver = await tx.getConfig(
      ConfigRecordKey.MaterializedTransactionsVersion,
    );
    if (ver) {
      if (ver.value == MATERIALIZED_TRANSACTIONS_VERSION) {
        return;
      }
      if (ver.value > MATERIALIZED_TRANSACTIONS_VERSION) {
        logger.error(
          "database is newer than code (materializedTransactionsVersion)",
        );
        return;
      }
    }

    await rematerializeTransactionsAtCurrentVersion(wex, tx);
  });
}

export async function getDenomInfo(
  wex: WalletExecutionContext,
  tx: WalletDbTransaction,
  ref: WalletDenomRef,
): Promise<DenominationInfo | undefined> {
  const key = denomRefKey(ref);
  return wex.ws.denomInfoCache.getOrPut(key, async () => {
    const d = await tx.getDenomination(ref);
    if (d != null) {
      return WalletDenomination.toDenomInfo(d);
    } else {
      return undefined;
    }
  });
}

/** Stable in-memory key for denomination references. */
export function denomRefKey(ref: WalletDenomRef): string {
  return `${ref.exchangeMasterPub}:${ref.denomPubHash}`;
}

/** Stable in-memory key for coin-availability references. */
export function coinAvailabilityRefKey(ref: WalletCoinAvailabilityRef): string {
  return `${denomRefKey(ref)}:${ref.maxAge}`;
}

/**
 * Load denomination information for many references with one backend batch.
 *
 * Cached entries are reused, missing records are omitted, and each unique
 * reference appears at most once in the returned map.
 */
export async function getDenomInfos(
  wex: WalletExecutionContext,
  tx: WalletDbTransaction,
  refs: WalletDenomRef[],
): Promise<Map<string, DenominationInfo>> {
  const result = new Map<string, DenominationInfo>();
  const missing = new Map<string, WalletDenomRef>();
  for (const ref of refs) {
    const key = denomRefKey(ref);
    const cached = wex.ws.denomInfoCache.get(key);
    if (cached) {
      result.set(key, cached);
    } else if (!missing.has(key)) {
      missing.set(key, ref);
    }
  }
  if (missing.size === 0) {
    return result;
  }
  const records = await tx.getDenominationsByRefs([...missing.values()]);
  for (const record of records) {
    const key = denomRefKey(record);
    const info = WalletDenomination.toDenomInfo(record);
    wex.ws.denomInfoCache.put(key, info);
    result.set(key, info);
  }
  return result;
}

/**
 * Get an API client from an internal wallet state object.
 */
let id = 0;
async function getClientFromWalletState(
  ws: InternalWalletState,
): Promise<WalletCoreApiClient> {
  const client: WalletCoreApiClient = {
    async call(op, payload): Promise<any> {
      id = (id + 1) % (Number.MAX_SAFE_INTEGER - 100);
      const res = await dispatchWalletCoreApiRequest(
        ws,
        op,
        String(id),
        payload,
      );
      switch (res.type) {
        case "error":
          throw TalerError.fromUncheckedDetail(res.error);
        case "response":
          return res.result;
      }
    },
    callForResult: async function <Op extends keyof WalletOperations>(
      op: Op,
      payload: WalletCoreRequestType<Op>,
    ): Promise<Result<WalletCoreResponseType<Op>, WalletCoreErrorType<Op>>> {
      id = (id + 1) % (Number.MAX_SAFE_INTEGER - 100);
      const res = await dispatchWalletCoreApiRequest(
        ws,
        op,
        String(id),
        payload,
      );
      switch (res.type) {
        case "error": {
          if (op in walletApiExpectedErrors) {
            const errs = (
              walletApiExpectedErrors as {
                [x: string]: readonly TalerErrorCode[];
              }
            )[op];
            if (errs.includes(res.error.code)) {
              return Result.errorWithDetail(
                res.error.code as WalletCoreErrorType<Op>,
                res.error,
              );
            }
          }
          throw TalerError.fromUncheckedDetail(res.error);
        }
        case "response":
          return Result.of(res.result as WalletCoreResponseType<Op>);
        default:
          assertUnreachable(res);
      }
    },
  };
  return client;
}

export function getObservedWalletExecutionContext(
  ws: InternalWalletState,
  cancellationToken: CancellationToken,
  cts: CancellationToken.Source | undefined,
  oc: ObservabilityContext,
): WalletExecutionContext {
  const wex: WalletExecutionContext = {
    async runWalletDbTx(f) {
      return await runWalletDbTx(wex, f);
    },
    ws,
    cancellationToken,
    cts,
    cryptoApi: observeTalerCrypto(ws.cryptoApi, oc),
    dbRetryState: {
      retriedExchangeUpdate: new Set(),
    },
    http: new ObservableHttpClientLibrary(ws.http, oc),
    taskScheduler: new ObservableTaskScheduler(ws.taskScheduler, oc),
    oc,
  };
  return wex;
}

function maybeExtractTransactionError(
  e: unknown,
): UnverifiedDenomError | OutdatedExchangeError | undefined {
  if (e instanceof UnverifiedDenomError || e instanceof OutdatedExchangeError) {
    return e;
  }
  if (
    e instanceof TransactionAbortedError &&
    (e.exn instanceof UnverifiedDenomError ||
      e.exn instanceof OutdatedExchangeError)
  ) {
    return e.exn;
  }
  return undefined;
}

const maxDbTxRetries = 20;

async function handleTxRetries<T>(
  wex: WalletExecutionContext,
  f: () => Promise<T>,
): Promise<T> {
  let n = 0;
  while (1) {
    if (n > 0) {
      logger.trace(`db transaction attempt ${n}`);
    }
    if (n > maxDbTxRetries) {
      throw Error("max DB retries reached, giving up");
    }
    n++;
    wex.cancellationToken.throwIfCancelled();
    try {
      return await f();
    } catch (e) {
      let exn = maybeExtractTransactionError(e);
      if (exn == null) {
        throw e;
      }
      let url: string | undefined = undefined;
      if (exn instanceof UnverifiedDenomError) {
        url = exn.denomInfo.exchangeBaseUrl;
        logger.info(`got unverified denominations, updating ${url}`);
      } else if (exn instanceof OutdatedExchangeError) {
        url = exn.exchangeBaseUrl;
        logger.info(`got outdated exchange entry, updating ${url}`);
      }
      if (url) {
        if (!wex.dbRetryState.retriedExchangeUpdate) {
          wex.dbRetryState.retriedExchangeUpdate = new Set();
        }
        if (wex.dbRetryState.retriedExchangeUpdate.has(url)) {
          logger.error(
            `updating exchange already failed in execution context, not retrying`,
          );
          // UnverifiedDenomError and OutdatedExchangeError are internal
          // signals for "update the exchange and try again".  Once that has
          // been tried, they escape to the client, and there they have to
          // carry a code instead of surfacing as an unexpected exception.
          throw TalerError.fromDetail(
            TalerErrorCode.WALLET_EXCHANGE_ENTRY_OUTDATED,
            { exchangeBaseUrl: url },
            `the wallet's information about ${url} is outdated and could not be refreshed`,
            exn,
          );
        }
        // Prevent both recursion and multiple updates
        // per wallet execution context.
        wex.dbRetryState.retriedExchangeUpdate.add(url);
        await fetchFreshExchange(wex, url);
        await updateWithdrawalDenomsForExchange(wex, url);
        logger.info(`updated exchange, continuing with transaction retry`);
      }
    }
  }
  throw Error("not reached");
}

async function runWalletDbTx<T>(
  wex: WalletExecutionContext,
  f: (tx: WalletDbTransaction) => Promise<T>,
): Promise<T> {
  // Set by the wrapper below when the transaction calls a method that makes
  // the wallet's caches stale.  Acted on only after a successful commit: a
  // transaction that rolls back changed nothing, and an attempt that is about
  // to be retried resets the flag so a discarded write cannot carry over.
  const dirty = { dirty: false, terminalPaymentIds: new Set<string>() };
  // Retries wrap the transaction for both backends: the failure modes they
  // guard against (transaction aborted, retryable conflict) are not specific
  // to the storage layer.
  return await handleTxRetries(wex, async () => {
    dirty.dirty = false;
    dirty.terminalPaymentIds.clear();
    const location = getCallerInfo();
    wex.oc.observe({
      type: ObservabilityEventType.DbQueryStart,
      name: "<unknown>",
      location,
    });
    const start = performanceNow();
    try {
      const ret = await wex.ws.db.runReadWriteTx(
        async (tx) => await f(watchForCacheInvalidation(tx, dirty)),
      );
      wex.oc.observe({
        type: ObservabilityEventType.DbQueryFinishSuccess,
        name: "<unknown>",
        location,
        durationMs: performanceDelta(start, performanceNow()),
      });
      if (dirty.dirty) {
        wex.ws.clearAllCaches();
      }
      for (const proposalId of dirty.terminalPaymentIds) {
        wex.ws.clearDepositPermissionCache(proposalId);
      }
      return ret;
    } catch (e) {
      wex.oc.observe({
        type: ObservabilityEventType.DbQueryFinishError,
        name: "<unknown>",
        location,
        error: getErrorDetailFromException(e),
        durationMs: performanceDelta(start, performanceNow()),
      });
      throw e;
    }
  });
}

export function getNormalWalletExecutionContext(
  ws: InternalWalletState,
  cancellationToken: CancellationToken,
  cts: CancellationToken.Source | undefined,
  oc: ObservabilityContext,
): WalletExecutionContext {
  const wex: WalletExecutionContext = {
    async runWalletDbTx(f) {
      return await runWalletDbTx(wex, f);
    },
    ws,
    cancellationToken,
    cts,
    cryptoApi: ws.cryptoApi,
    dbRetryState: {
      retriedExchangeUpdate: new Set(),
    },
    get http() {
      if (ws.initCalled) {
        return ws.http;
      }
      throw Error("wallet not initialized");
    },
    taskScheduler: ws.taskScheduler,
    oc,
  };
  return wex;
}

/**
 * Handle a request to the wallet-core API.
 */
async function dispatchWalletCoreApiRequest(
  ws: InternalWalletState,
  operation: string,
  id: string,
  payload: unknown,
): Promise<CoreApiResponse> {
  const isInitOperation = isWalletInitOperation(operation);
  if (!isInitOperation) {
    if (!ws.initCalled) {
      throw Error("init must be called first");
    }
  }

  if (isInitOperation) {
    const req: InitRequest = codecForInitRequest().decode(payload);
    const config = applyRunConfigDefaults(req.config);
    ws.initWithConfig(config);
    if (!ws.initCalled && config.features.useNativeDb) {
      await ws.openNativeDatabaseIfEmpty();
    }
  }

  await ws.ensureWalletDbOpen();

  let wex: WalletExecutionContext;
  let oc: ObservabilityContext;

  const cts = CancellationToken.create();

  if (ws.initCalled && ws.config.testing.emitObservabilityEvents) {
    oc = {
      observe(evt) {
        PerformanceTable.insertEvent(ws.performanceStats, evt);
        ws.notify({
          type: NotificationType.RequestObservabilityEvent,
          operation,
          requestId: id,
          event: evt,
        });
      },
    };

    wex = getObservedWalletExecutionContext(ws, cts.token, cts, oc);
  } else {
    oc = {
      observe(evt) {},
    };
    wex = getNormalWalletExecutionContext(ws, cts.token, cts, oc);
  }

  const start = performanceNow();
  try {
    oc.observe({
      type: ObservabilityEventType.RequestStart,
      name: operation,
    });
    const injectedResponse = takeDevExperimentApiResponse(
      ws.devExperimentState,
      operation,
    );
    if (injectedResponse !== undefined) {
      const end = performanceNow();
      oc.observe({
        type: ObservabilityEventType.RequestFinishSuccess,
        operation,
        requestId: id,
        durationMs: performanceDelta(start, end),
      });
      return {
        type: "response",
        operation,
        id,
        result: injectedResponse,
      };
    }
    const injectedError = takeDevExperimentApiError(
      ws.devExperimentState,
      operation,
    );
    if (injectedError) throw TalerError.fromUncheckedDetail(injectedError);
    const result = await dispatchRequestInternal(
      wex,
      operation as any,
      payload,
    );
    const end = performanceNow();
    oc.observe({
      type: ObservabilityEventType.RequestFinishSuccess,
      operation: operation,
      requestId: id,
      durationMs: performanceDelta(start, end),
    });
    return {
      type: "response",
      operation,
      id,
      result,
    };
  } catch (e: any) {
    const err = getErrorDetailFromException(e);
    logger.info(
      `finished wallet core request ${operation} with error: ${j2s(err)}`,
    );
    const end = performanceNow();
    oc.observe({
      type: ObservabilityEventType.RequestFinishError,
      operation: operation,
      requestId: id,
      durationMs: performanceDelta(start, end),
    });
    return {
      type: "error",
      operation,
      id,
      error: err,
    };
  }
}

/**
 * Environment variable that selects the coin selection algorithm.
 */
const coinSelectionEnvVar = "TALER_WALLET_COINSEL";

/**
 * Read the coin selection algorithm from the environment.
 *
 * Returns undefined on platforms without an environment and when the variable
 * is unset, so that the caller falls back to its own default.  An unknown
 * value is an error: silently spending with a different algorithm than the
 * one that was asked for would be very hard to notice.
 */
function coinSelectionAlgorithmFromEnv(): CoinSelectionAlgorithm | undefined {
  const val = getenv(coinSelectionEnvVar);
  if (val == null || val === "") {
    return undefined;
  }
  switch (val) {
    case "default":
    case "legacy-2024":
      return val;
    default:
      throw Error(
        `invalid value for ${coinSelectionEnvVar}: "${val}" ` +
          `(expected "default" or "legacy-2024")`,
      );
  }
}

/**
 * Environment variable that turns on the migration to the native database.
 *
 * Configures wallet-core rather than a particular frontend, so it is named
 * for wallet-core.  A client with a settings UI passes the flag in the init
 * request instead.
 */
const migrateNativeDbEnvVar = "TALER_WALLET_MIGRATE_NATIVE_DB";

/**
 * Read the native-database migration flag from the environment.
 *
 * Returns undefined where there is no environment or the variable is unset,
 * so the caller falls back to its own default.
 */
function migrateNativeDbFromEnv(): boolean | undefined {
  const val = getenv(migrateNativeDbEnvVar);
  if (val == null || val === "") {
    return undefined;
  }
  return val !== "0";
}

export function applyRunConfigDefaults(
  wcp?: PartialWalletRunConfig,
): WalletRunConfig {
  if (wcp?.features?.allowHttp != null) {
    logger.warn(`allowHttp flag not supported anymore`);
  }
  const coinSelectionAlgorithm =
    wcp?.testing?.coinSelectionAlgorithm ??
    coinSelectionAlgorithmFromEnv() ??
    "default";
  if (coinSelectionAlgorithm !== "default") {
    logger.warn(`using non-default coin selection: ${coinSelectionAlgorithm}`);
  }
  return {
    features: {
      allowHttp: true,
      migrateNativeDb:
        wcp?.features?.migrateNativeDb ?? migrateNativeDbFromEnv() ?? false,
      useNativeDb: wcp?.features?.useNativeDb ?? false,
    },
    testing: {
      devModeActive: wcp?.testing?.devModeActive ?? false,
      insecureTrustExchange: wcp?.testing?.insecureTrustExchange ?? false,
      preventThrottling: wcp?.testing?.preventThrottling ?? false,
      skipDefaults: wcp?.testing?.skipDefaults ?? false,
      emitObservabilityEvents: wcp?.testing?.emitObservabilityEvents ?? false,
      coinSelectionAlgorithm,
    },
    lazyTaskLoop: wcp?.lazyTaskLoop ?? false,
    logLevel: wcp?.logLevel ?? "INFO",
  };
}

export type HttpFactory = (config: WalletRunConfig) => HttpRequestLibrary;

/**
 * How a host hands its database to the wallet.
 *
 * Was an interface of its own describing an IndexedDB factory plus an
 * optional native handle; the host now opens exactly one backend and passes
 * the handle for it, so there is nothing left to describe separately.
 */
export type WalletDatabaseImplementation = WalletDbHandle;

/**
 * Public handle to a running wallet.
 */
export class Wallet {
  private ws: InternalWalletState;
  private _client: WalletCoreApiClient | undefined;

  private constructor(
    dbHandle: WalletDbHandle,
    httpFactory: HttpFactory,
    timer: TimerAPI,
    cryptoWorkerFactory: CryptoWorkerFactory,
  ) {
    this.ws = new InternalWalletState(
      dbHandle,
      httpFactory,
      timer,
      cryptoWorkerFactory,
    );
  }

  get client(): WalletCoreApiClient {
    if (!this._client) {
      throw Error();
    }
    return this._client;
  }

  static async create(
    dbHandle: WalletDbHandle,
    httpFactory: HttpFactory,
    timer: TimerAPI,
    cryptoWorkerFactory: CryptoWorkerFactory,
  ): Promise<Wallet> {
    const w = new Wallet(dbHandle, httpFactory, timer, cryptoWorkerFactory);
    w._client = await getClientFromWalletState(w.ws);
    return w;
  }

  addNotificationListener(f: (n: WalletNotification) => void): CancelFn {
    return this.ws.addNotificationListener(f);
  }

  async handleCoreApiRequest(
    operation: string,
    id: string,
    payload: unknown,
  ): Promise<CoreApiResponse> {
    return dispatchWalletCoreApiRequest(this.ws, operation, id, payload);
  }
}

/**
 * Internal state of the wallet.
 *
 * This ties together all the operation implementations.
 */
export class InternalWalletState {
  cryptoApi: TalerCryptoInterface;
  private cryptoDispatcher: CryptoDispatcher;

  readonly timerGroup: TimerGroup;
  stopped = false;

  private listeners: NotificationListener[] = [];

  initCalled = false;

  /**
   * Proposal IDs of payments that were still claiming when this wallet
   * was started, i.e. left over from a previous run.
   *
   * Each of them gets one more attempt to claim, after which the
   * transaction is discarded instead of being retried forever.
   */
  readonly leftoverClaims = new Set<string>();

  refreshCostCache: Cache<AmountJson> = new Cache(
    1000,
    Duration.fromSpec({ minutes: 1 }),
  );

  denomInfoCache: Cache<DenominationInfo> = new Cache(
    1000,
    Duration.fromSpec({ minutes: 1 }),
  );

  exchangeCache: Cache<ReadyExchangeSummary> = new Cache(
    1000,
    Duration.fromSpec({ minutes: 1 }),
  );

  /**
   * Base URL to talk to for a given exchange master public key.
   *
   * Coins name the key that signed their denomination, not a URL, so every
   * request made on their behalf resolves through here.
   */
  exchangeBaseUrlCache: Cache<string> = new Cache(
    1000,
    Duration.fromSpec({ minutes: 1 }),
  );

  depositPermissionCache = new Cache<Promise<CoinDepositPermission[]>>(
    100,
    Duration.fromSpec({ minutes: 5 }),
  );

  private depositPermissionKeysByScope = new Map<string, Set<string>>();

  cacheDepositPermissions(
    scope: string,
    key: string,
    value: Promise<CoinDepositPermission[]>,
  ): void {
    let trackedKeys = 0;
    for (const keys of this.depositPermissionKeysByScope.values()) {
      trackedKeys += keys.size;
    }
    if (trackedKeys >= 100) {
      this.depositPermissionCache.clear();
      this.depositPermissionKeysByScope.clear();
    }
    this.depositPermissionCache.put(key, value);
    const keys = this.depositPermissionKeysByScope.get(scope) ?? new Set();
    keys.add(key);
    this.depositPermissionKeysByScope.set(scope, keys);
  }

  forgetDepositPermission(scope: string, key: string): void {
    this.depositPermissionCache.delete(key);
    const keys = this.depositPermissionKeysByScope.get(scope);
    keys?.delete(key);
    if (keys?.size === 0) {
      this.depositPermissionKeysByScope.delete(scope);
    }
  }

  clearDepositPermissionCache(scope: string): void {
    const keys = this.depositPermissionKeysByScope.get(scope);
    if (!keys) {
      return;
    }
    for (const key of keys) {
      this.depositPermissionCache.delete(key);
    }
    this.depositPermissionKeysByScope.delete(scope);
  }

  /**
   * Promises that are waiting for a particular resource.
   */
  private resourceWaiters: Record<string, OpenedPromise<void>[]> = {};

  /**
   * Resources that are currently locked.
   */
  private resourceLocks: Set<string> = new Set();

  taskScheduler: TaskScheduler = new TaskSchedulerImpl(this);

  private _config: Readonly<WalletRunConfig> | undefined;

  private _http: HttpRequestLibrary | undefined = undefined;

  devExperimentState: DevExperimentState = {};

  clientCancellationMap: Map<string, CancellationToken.Source> = new Map();

  progressMap: Map<string, ProgressContext> = new Map();

  longpollQueue = new LongpollQueue();

  private loadingDb: boolean = false;

  private loadingDbCond: AsyncCondition = new AsyncCondition();

  private dbOperationGate = new DbOperationGate();

  private admittedDb: WalletDbHandle;

  private suspendedDbRelease: (() => void) | undefined;

  private maintenanceNotifications: MaintenanceNotificationThrottler;

  performanceStats: PerformanceTable = {};

  /**
   * The wallet database, whichever backend is behind it.
   *
   * The single place the storage backend is chosen.  Everything above this
   * line works through WalletDbHandle and cannot tell the two apart.
   */
  public get db(): WalletDbHandle {
    return this.admittedDb;
  }

  /**
   * The IndexedDB-specific handle for the fixup log.  Undefined when the
   * native backend is in use, so a caller has to say what it does when the
   * capability is absent.
   */
  public get idbOnly(): IdbWalletDbHandle | undefined {
    const h = this.dbHandle;
    return h instanceof IdbWalletDbHandle ? h : undefined;
  }

  /**
   * Planned exchange migrations.
   * Maps the old exchange base URL to a new one.
   */
  exchangeMigrationPlan: Map<
    string,
    {
      newExchangeBaseUrl: string;
    }
  > = new Map();

  /**
   * Run a database transaction outside of a wallet execution context.
   */
  /**
   * Run f in a transaction outside any WalletExecutionContext.
   *
   * Dispatches to the native backend when one is configured, which
   * the older legacy helper could not do: that one handed out the raw
   * IndexedDB handle.  Background work (the task shepherd) must go through
   * here, or it reads a different database than the one the wallet writes.
   */
  async runStandaloneWalletDbTx<T>(
    f: (tx: WalletDbTransaction) => Promise<T>,
  ): Promise<T> {
    const dirty = { dirty: false };
    const ret = await this.db.runReadWriteTx(
      async (tx) => await f(watchForCacheInvalidation(tx, dirty)),
    );
    if (dirty.dirty) {
      this.clearAllCaches();
    }
    return ret;
  }

  /** Admit an IndexedDB-specific operation that cannot use the DAL. */
  async runWithDatabaseShared<T>(f: () => Promise<T>): Promise<T> {
    return await this.dbOperationGate.runShared(f);
  }

  /**
   * When set to false, all tasks that require network will be stopped and
   * retried until connection is restored.
   *
   * Set to true by default for compatibility with clients that don't hint
   * network availability via hintNetworkAvailability.
   */
  private _networkAvailable = true;

  get networkAvailable(): boolean {
    return this._networkAvailable;
  }

  set networkAvailable(status: boolean) {
    this._networkAvailable = status;
  }

  /**
   * Reference counter for active integration tests
   * that ignore ToS acceptance rules.
   */
  refcntIgnoreTos: number = 0;

  clearAllCaches(): void {
    this.exchangeCache.clear();
    this.denomInfoCache.clear();
    this.refreshCostCache.clear();
    this.exchangeBaseUrlCache.clear();
    this.depositPermissionCache.clear();
    this.depositPermissionKeysByScope.clear();
  }

  initWithConfig(newConfig: WalletRunConfig): void {
    this._config = newConfig;

    this._http = this.httpFactory(newConfig);

    if (this.config.testing.devModeActive) {
      logger.warn("using dev experiment http lib");
      this._http = new DevExperimentHttpLib(this.http, this.devExperimentState);
    }
  }

  flightRecords: FlightRecordEntry[] = [];

  addFdr(arg: { target: string; event: FlightRecordEvent }) {
    this.flightRecords.push({
      timestamp: TalerPreciseTimestamp.now(),
      event: arg.event,
      target: arg.target,
    });
    if (this.flightRecords.length > 100) {
      this.flightRecords.shift();
    }
  }

  get config(): WalletRunConfig {
    if (!this._config) {
      throw Error("config not initialized");
    }
    return this._config;
  }

  get http(): HttpRequestLibrary {
    if (!this._http) {
      throw Error("wallet not initialized");
    }
    return this._http;
  }

  constructor(
    public dbHandle: WalletDbHandle,
    private httpFactory: HttpFactory,
    timer: TimerAPI,
    cryptoWorkerFactory: CryptoWorkerFactory,
  ) {
    this.admittedDb = new AdmittedWalletDbHandle(
      () => this.dbHandle,
      this.dbOperationGate,
    );
    this.cryptoDispatcher = new CryptoDispatcher(cryptoWorkerFactory);
    this.cryptoApi = this.cryptoDispatcher.cryptoApi;
    this.timerGroup = new TimerGroup(timer);
    this.maintenanceNotifications = new MaintenanceNotificationThrottler(
      timer,
      (n) => this.deliverNotificationSynchronously(n),
    );
    // The host opened the database before this wallet existed, so its
    // notifications had nowhere to go until now.
    dbHandle.setNotificationSink((n) => this.notify(n));
    // Migration record used for testing with sandcastle or local deployment.
    this.exchangeMigrationPlan.set("http://exchange.taler.localhost:4321/", {
      newExchangeBaseUrl: "http://exchange.taler2.localhost:4321/",
    });
    // Prod migration (BFH)
    this.exchangeMigrationPlan.set("https://exchange.chf.taler.net/", {
      newExchangeBaseUrl: "https://exchange.taler.ti.bfh.ch/",
    });
    // Prod migration (GLS)
    this.exchangeMigrationPlan.set("https://exchange.glstest.taler.net/", {
      newExchangeBaseUrl: "https://test.exchange.gls.de/",
    });
  }

  async ensureWalletDbOpen(): Promise<void> {
    if (this.loadingDb) {
      while (this.loadingDb) {
        await this.loadingDbCond.wait();
      }
      return;
    }
    this.loadingDb = true;
    try {
      // Opening and repairing is the backend's business.  It reports how many
      // fixups it applied, because rebuilding the transaction view afterwards
      // is a wallet-level concern that no storage layer should know about.
      await this.dbOperationGate.runExclusive(async () => {
        const idb = this.idbOnly;
        if (idb) {
          await this.finalizeIndexedDbOpen(idb, await idb.ensureOpen());
        }
      });
    } catch (e) {
      logger.error(
        "error writing to database during initialization (during migration)",
      );
      const err = getErrorDetailFromException(e);
      logger.error(`details: ${j2s(err)}`);
      throw TalerError.fromDetail(TalerErrorCode.WALLET_DB_UNAVAILABLE, {
        innerError: err,
      });
    } finally {
      this.loadingDb = false;
      this.loadingDbCond.trigger();
    }
  }

  private async finalizeIndexedDbOpen(
    idb: IdbWalletDbHandle,
    result: { fixupsApplied: number; schemaUpgraded: boolean },
  ): Promise<void> {
    if (result.fixupsApplied === 0 && !result.schemaUpgraded) return;
    const wex = getNormalWalletExecutionContext(
      this,
      CancellationToken.CONTINUE,
      undefined,
      { observe(evt: any) {} },
    );
    try {
      if (result.fixupsApplied > 0) {
        idb.emitNotification({
          type: NotificationType.DatabaseMaintenanceProgress,
          operation: "indexeddb-fixup",
          phase: "fixup",
          step: WALLET_DB_REMATERIALIZE_STEP,
          completedSteps: WALLET_DB_MAINTENANCE_TOTAL_STEPS - 1,
          totalSteps: WALLET_DB_MAINTENANCE_TOTAL_STEPS,
        });
        // Use the raw handle while holding exclusive admission; routing
        // through admittedDb would try to acquire shared admission and
        // deadlock behind ourselves.
        await idb.runReadWriteTx(async (tx) => {
          await rematerializeTransactionsAtCurrentVersion(wex, tx);
        });
      }
      idb.emitNotification({
        type: NotificationType.DatabaseMaintenanceProgress,
        operation: "indexeddb-fixup",
        phase: "complete",
        completedSteps: WALLET_DB_MAINTENANCE_TOTAL_STEPS,
        totalSteps: WALLET_DB_MAINTENANCE_TOTAL_STEPS,
      });
    } catch (e) {
      idb.emitNotification({
        type: NotificationType.DatabaseMaintenanceProgress,
        operation: "indexeddb-fixup",
        phase: "failed",
        step: WALLET_DB_REMATERIALIZE_STEP,
        completedSteps: WALLET_DB_MAINTENANCE_TOTAL_STEPS - 1,
        totalSteps: WALLET_DB_MAINTENANCE_TOTAL_STEPS,
        error: getErrorDetailFromException(e),
      });
      throw e;
    }
  }

  /** Select native sqlite before an empty database is opened as IndexedDB. */
  async openNativeDatabaseIfEmpty(): Promise<boolean> {
    if (this.loadingDb) {
      while (this.loadingDb) {
        await this.loadingDbCond.wait();
      }
    }
    const oldHandle = this.dbHandle;
    if (!oldHandle.openNativeIfEmpty) {
      logger.trace("this host offers no native backend for empty storage");
      return false;
    }
    this.loadingDb = true;
    try {
      return await this.dbOperationGate.runExclusive(async () => {
        if (this.dbHandle !== oldHandle || !oldHandle.openNativeIfEmpty) {
          return false;
        }
        const newHandle = await oldHandle.openNativeIfEmpty();
        this.dbHandle = newHandle;
        newHandle.setNotificationSink((n) => this.notify(n));
        await oldHandle.close();
        this.clearAllCaches();
        logger.info("initialized an empty database with the native schema");
        return true;
      });
    } finally {
      this.loadingDb = false;
      this.loadingDbCond.trigger();
    }
  }

  /**
   * Migrate the database to the native schema, if it is not already there and
   * the host can do it.
   *
   * Returns whether this call changed the active backend.  Automatic startup
   * migration logs a failure and keeps running on the untouched old database;
   * the explicit API asks this method to propagate failures instead.
   *
   * Runs under the same guard as opening and importing, so no transaction can
   * be in flight while the handle underneath the wallet is replaced.  Every
   * transaction resolves the handle through this class when it starts, so
   * work that was queued before the swap runs against the new database.
   */
  async migrateDbToNativeSchema(
    options: {
      cancellationToken?: CancellationToken;
      progressToken?: string;
      failIfUnsupported?: boolean;
      propagateFailure?: boolean;
    } = {},
  ): Promise<boolean> {
    const cancellationToken =
      options.cancellationToken ?? CancellationToken.CONTINUE;
    if (this.loadingDb) {
      while (this.loadingDb) {
        cancellationToken.throwIfCancelled();
        await cancellationToken.racePromise(this.loadingDbCond.wait());
      }
    }
    // Resolve only after earlier initialization/migration work has completed:
    // a repeated init queued during a successful migration must observe the
    // new native handle, not retain the old IndexedDB handle it first saw.
    const oldHandle = this.dbHandle;
    if (!oldHandle.migrateToNative) {
      // Either the database is already native or the host cannot migrate it;
      // both are "nothing to do", and neither is worth an alarming message on
      // every initialization.
      if (oldHandle.name !== "sqlite" && options.failIfUnsupported) {
        throw TalerError.fromDetail(
          TalerErrorCode.WALLET_DB_BACKEND_UNSUPPORTED,
          { backend: oldHandle.name },
          "this database backend cannot be migrated in place",
        );
      }
      logger.trace("this wallet database offers no in-place migration");
      return false;
    }
    this.loadingDb = true;
    try {
      return await this.dbOperationGate.runExclusive(async () => {
        try {
          cancellationToken.throwIfCancelled();
          const newHandle = await oldHandle.migrateToNative!({
            cancellationToken,
            progressToken: options.progressToken,
          });
          this.dbHandle = newHandle;
          newHandle.setNotificationSink((n) => this.notify(n));
          try {
            await oldHandle.close();
          } catch (e) {
            logger.warn(
              `closing the migrated IndexedDB handle failed: ${safeStringifyException(e)}`,
            );
          }
          this.clearAllCaches();
          return true;
        } catch (e) {
          logger.error(
            `migration to the native database failed, continuing with the` +
              ` existing one: ${safeStringifyException(e)}`,
          );
          if (options.propagateFailure) {
            if (
              e instanceof CancellationToken.CancellationError ||
              (e instanceof TalerError &&
                e.errorDetail.code ===
                  TalerErrorCode.WALLET_CORE_REQUEST_CANCELLED)
            ) {
              throw e;
            }
            throw TalerError.fromDetail(TalerErrorCode.WALLET_DB_UNAVAILABLE, {
              innerError: getErrorDetailFromException(e),
            });
          }
          return false;
        }
      }, cancellationToken);
    } finally {
      this.loadingDb = false;
      this.loadingDbCond.trigger();
    }
  }

  /**
   * Prepare database for import by closing it.
   */
  async suspendDatabase(): Promise<void> {
    if (this.loadingDb) {
      while (this.loadingDb) {
        await this.loadingDbCond.wait();
      }
    }
    this.loadingDb = true;
    this.suspendedDbRelease = await this.dbOperationGate.acquireExclusive();
    try {
      await this.dbHandle.close();
    } catch (e) {
      this.suspendedDbRelease();
      this.suspendedDbRelease = undefined;
      this.loadingDb = false;
      this.loadingDbCond.trigger();
      throw e;
    }
  }

  /**
   * Resume database by re-opening it.
   */
  async resumeDatabase(): Promise<void> {
    const release = this.suspendedDbRelease;
    this.suspendedDbRelease = undefined;
    try {
      const idb = this.idbOnly;
      if (idb) {
        await this.finalizeIndexedDbOpen(idb, await idb.ensureOpen());
      }
    } finally {
      this.loadingDb = false;
      this.loadingDbCond.trigger();
      release?.();
    }
  }

  notify(n: WalletNotification): void {
    logger.trace(`Notification: ${j2s(n)}`);
    if (n.type === NotificationType.DatabaseMaintenanceProgress) {
      this.maintenanceNotifications.offer(n);
      return;
    }
    for (const l of this.listeners) {
      const nc = JSON.parse(JSON.stringify(n));
      setTimeout(() => {
        l(nc);
      }, 0);
    }
  }

  private deliverNotificationSynchronously(n: WalletNotification): void {
    for (const l of [...this.listeners]) {
      const nc = JSON.parse(JSON.stringify(n));
      try {
        l(nc);
      } catch (e) {
        logger.warn(
          `ignoring exception from wallet notification listener: ${safeStringifyException(e)}`,
        );
      }
    }
  }

  addNotificationListener(f: (n: WalletNotification) => void): CancelFn {
    this.listeners.push(f);
    return () => {
      const idx = this.listeners.indexOf(f);
      if (idx >= 0) {
        this.listeners.splice(idx, 1);
      }
    };
  }

  /**
   * Stop ongoing processing.
   */
  stop(): void {
    logger.trace("stopping (at internal wallet state)");
    this.stopped = true;
    this.maintenanceNotifications.stop();
    this.timerGroup.stopCurrentAndFutureTimers();
    this.cryptoDispatcher.stop();
    this.taskScheduler.shutdown().catch((e) => {
      logger.warn(`shutdown failed: ${safeStringifyException(e)}`);
    });
  }

  /** Stop processing and release the database before shutdown completes. */
  async shutdown(): Promise<void> {
    this.stop();
    await this.dbOperationGate.runExclusive(async () => {
      await this.dbHandle.close();
    });
  }

  /**
   * Run an async function after acquiring a list of locks, identified
   * by string tokens.
   */
  async runSequentialized<T>(
    tokens: string[],
    f: () => Promise<T>,
  ): Promise<T> {
    // Make sure locks are always acquired in the same order
    tokens = [...tokens].sort();

    for (const token of tokens) {
      if (this.resourceLocks.has(token)) {
        const p = openPromise<void>();
        let waitList = this.resourceWaiters[token];
        if (!waitList) {
          waitList = this.resourceWaiters[token] = [];
        }
        waitList.push(p);
        await p.promise;
      }
      this.resourceLocks.add(token);
    }

    try {
      logger.trace(`begin exclusive execution on ${JSON.stringify(tokens)}`);
      const result = await f();
      logger.trace(`end exclusive execution on ${JSON.stringify(tokens)}`);
      return result;
    } finally {
      for (const token of tokens) {
        this.resourceLocks.delete(token);
        const waiter = (this.resourceWaiters[token] ?? []).shift();
        if (waiter) {
          waiter.resolve();
        }
      }
    }
  }
}
