const logger = new Logger("operations/balance.ts");

interface WalletBalance {
  scopeInfo: ScopeInfo;
  available: AmountJson;
  pendingIncoming: AmountJson;
  pendingOutgoing: AmountJson;
  flagIncomingKyc: boolean;
  flagIncomingConfirmation: boolean;
  flagOutgoingKyc: boolean;
  disablePeerPayments: boolean;
  disableDirectDeposits: boolean;
  shoppingUrls: Set<string>;
}

async function computeRefreshGroupAvailableAmountForExchanges(
  tx: WalletDbTransaction,
  r: WalletRefreshGroup,
  restrictSenderScope: ScopeInfo | undefined,
  snapshot?: PaymentBalanceSnapshot,
): Promise<AmountJson> {
  // Don't count finished refreshes, since the refresh already resulted
  // in coins being added to the wallet.
  let available = Amounts.zeroOfCurrency(r.currency);
  if (r.timestampFinished) {
    return available;
  }
  if (r.reason === RefreshReason.AbortPay) {
    return available;
  }
  if (!r.infoPerExchange) {
    return available;
  }
  for (const exch of Object.keys(r.infoPerExchange)) {
    const pe = r.infoPerExchange[exch];
    if (
      restrictSenderScope &&
      !(snapshot
        ? await snapshot.checkExchangeInScope(tx, exch, restrictSenderScope)
        : await tx.checkExchangeInScope(exch, restrictSenderScope))
    ) {
      continue;
    }
    available = Amounts.add(available, pe.outputEffective).amount;
  }
  return available;
}

function getBalanceKey(scopeInfo: ScopeInfo): string {
  switch (scopeInfo.type) {
    case ScopeType.Auditor:
      return `${scopeInfo.type};${scopeInfo.currency};${scopeInfo.url}`;
    case ScopeType.Exchange:
      return `${scopeInfo.type};${scopeInfo.currency};${scopeInfo.url}`;
    case ScopeType.Global:
      return `${scopeInfo.type};${scopeInfo.currency}`;
    case ScopeType.ExchangeLegacyKeys:
      // The key is part of the bucket identity: one exchange can have funds
      // under more than one superseded key.
      return `${scopeInfo.type};${scopeInfo.currency};${scopeInfo.url};${scopeInfo.masterPub}`;
  }
}

function getScopeSortingOrder(scopeInfo: ScopeInfo): number {
  switch (scopeInfo.type) {
    case ScopeType.Global:
      return 0;
    case ScopeType.Auditor:
      return 1;
    case ScopeType.Exchange:
      return 2;
    // Sorted last: these funds are a leftover, not something to spend from
    // by default.
    case ScopeType.ExchangeLegacyKeys:
      return 3;
    default:
      assertUnreachable(scopeInfo);
  }
}

class BalancesStore {
  private exchangeScopeCache: Record<string, ScopeInfo> = {};
  private balanceStore: Record<string, WalletBalance> = {};
  private donauSummaryItems: DonauSummaryItem[] | undefined = undefined;

  constructor(
    private wex: WalletExecutionContext,
    private tx: WalletDbTransaction,
  ) {}

  /**
   * Add amount to a balance field, both for
   * the slicing by exchange and currency.
   */
  /**
   * @param exchangeMasterPub the key that signed the funds, when they are
   *   coins.  Amounts that are not yet coins -- a pending withdrawal, a
   *   refresh output -- always belong to the key set in force now and pass
   *   nothing.
   */
  private async initBalance(
    currency: string,
    exchangeBaseUrl: string,
    exchangeMasterPub?: string,
    denomPubHash?: string,
  ): Promise<WalletBalance> {
    // The currency and the key are part of the cache key, not just the URL:
    // one exchange can hold funds under a key or a currency it has since
    // replaced, and those are different buckets.  Keyed on the URL alone,
    // the first scope resolved would be reused for all of them and amounts
    // in different currencies would be added together.
    const cacheKey = `${exchangeBaseUrl}\u0000${currency}\u0000${
      exchangeMasterPub ?? ""
    }\u0000${denomPubHash ?? ""}`;
    let scopeInfo: ScopeInfo | undefined = this.exchangeScopeCache[cacheKey];
    if (!scopeInfo) {
      scopeInfo = await this.resolveScope(
        exchangeBaseUrl,
        currency,
        exchangeMasterPub,
        denomPubHash,
      );
      this.exchangeScopeCache[cacheKey] = scopeInfo;
    }
    const balanceKey = getBalanceKey(scopeInfo);
    let b = this.balanceStore[balanceKey];
    if (!b) {
      const zero = Amounts.zeroOfCurrency(currency);
      b = this.balanceStore[balanceKey] = {
        scopeInfo,
        available: zero,
        pendingIncoming: zero,
        pendingOutgoing: zero,
        flagIncomingConfirmation: false,
        flagIncomingKyc: false,
        flagOutgoingKyc: false,
        disablePeerPayments: false,
        disableDirectDeposits: false,
        shoppingUrls: new Set(),
      };
    }
    return this.balanceStore[balanceKey];
  }

  /**
   * Scope for funds at an exchange, telling superseded key sets apart.
   *
   * Coins issued under a master key the exchange has replaced, or in a
   * currency it no longer uses, are not interchangeable with what it issues
   * now, so they get a scope of their own rather than being pooled.
   */
  private async resolveScope(
    exchangeBaseUrl: string,
    currency: string,
    exchangeMasterPub?: string,
    denomPubHash?: string,
  ): Promise<ScopeInfo> {
    const det = await this.tx.getExchangeDetails(exchangeBaseUrl);
    if (
      det &&
      (det.currency !== currency ||
        (exchangeMasterPub != null &&
          det.masterPublicKey !== exchangeMasterPub))
    ) {
      return {
        type: ScopeType.ExchangeLegacyKeys,
        currency,
        url: exchangeBaseUrl,
        masterPub: exchangeMasterPub ?? det.masterPublicKey,
      };
    }
    return await this.tx.getExchangeScopeInfo(
      exchangeBaseUrl,
      currency,
      denomPubHash,
    );
  }

  async addZero(
    currency: string,
    exchangeBaseUrl: string,
    exchangeMasterPub?: string,
    denomPubHash?: string,
  ): Promise<void> {
    await this.initBalance(
      currency,
      exchangeBaseUrl,
      exchangeMasterPub,
      denomPubHash,
    );
  }

  async setPeerPaymentsDisabled(
    currency: string,
    exchangeBaseUrl: string,
  ): Promise<void> {
    const b = await this.initBalance(currency, exchangeBaseUrl);
    b.disablePeerPayments = true;
  }

  async setDirectDepositsDisabled(
    currency: string,
    exchangeBaseUrl: string,
  ): Promise<void> {
    const b = await this.initBalance(currency, exchangeBaseUrl);
    b.disableDirectDeposits = true;
  }

  async addShoppingUrl(
    currency: string,
    exchangeBaseUrl: string,
    shoppingUrl: string,
  ): Promise<void> {
    const b = await this.initBalance(currency, exchangeBaseUrl);
    b.shoppingUrls.add(shoppingUrl);
  }

  async addAvailable(
    currency: string,
    exchangeBaseUrl: string,
    amount: AmountLike,
    exchangeMasterPub?: string,
    denomPubHash?: string,
  ): Promise<void> {
    const b = await this.initBalance(
      currency,
      exchangeBaseUrl,
      exchangeMasterPub,
      denomPubHash,
    );
    b.available = Amounts.add(b.available, amount).amount;
  }

  async addPendingIncoming(
    currency: string,
    exchangeBaseUrl: string,
    amount: AmountLike,
  ): Promise<void> {
    const b = await this.initBalance(currency, exchangeBaseUrl);
    b.pendingIncoming = Amounts.add(b.pendingIncoming, amount).amount;
  }

  async addPendingOutgoing(
    currency: string,
    exchangeBaseUrl: string,
    amount: AmountLike,
  ): Promise<void> {
    const b = await this.initBalance(currency, exchangeBaseUrl);
    b.pendingOutgoing = Amounts.add(b.pendingOutgoing, amount).amount;
  }

  async setFlagIncomingKyc(
    currency: string,
    exchangeBaseUrl: string,
  ): Promise<void> {
    const b = await this.initBalance(currency, exchangeBaseUrl);
    b.flagIncomingKyc = true;
  }

  async setFlagIncomingConfirmation(
    currency: string,
    exchangeBaseUrl: string,
  ): Promise<void> {
    const b = await this.initBalance(currency, exchangeBaseUrl);
    b.flagIncomingConfirmation = true;
  }

  async setFlagOutgoingKyc(
    currency: string,
    exchangeBaseUrl: string,
  ): Promise<void> {
    const b = await this.initBalance(currency, exchangeBaseUrl);
    b.flagOutgoingKyc = true;
  }

  addDonauItem(rec: WalletDonationSummary): void {
    if (!this.donauSummaryItems) {
      this.donauSummaryItems = [];
    }

    this.donauSummaryItems.push({
      amountReceiptsAvailable: rec.amountReceiptsAvailable,
      amountReceiptsSubmitted: rec.amountReceiptsSubmitted,
      donauBaseUrl: rec.donauBaseUrl,
      year: rec.year,
      legalDomain: rec.legalDomain,
      // Not yet implemented
      amountStatement: undefined,
    });
  }

  toBalancesResponse(haveProdBalance: boolean): BalancesResponse {
    const balancesResponse: BalancesResponse = {
      balances: [],
      haveProdBalance,
    };

    if (this.donauSummaryItems) {
      balancesResponse.donauSummary = this.donauSummaryItems;
    }

    const balanceStore = this.balanceStore;

    Object.keys(balanceStore)
      .sort((a, b) => {
        const balanceA = balanceStore[a];
        const balanceB = balanceStore[b];
        const scopeA = getScopeSortingOrder(balanceA.scopeInfo);
        const scopeB = getScopeSortingOrder(balanceB.scopeInfo);
        if (scopeA !== scopeB) return scopeA - scopeB;
        return a.localeCompare(b);
      })
      .forEach((c, i) => {
        const v = balanceStore[c];
        const flags: BalanceFlag[] = [];
        if (v.flagIncomingKyc) {
          flags.push(BalanceFlag.IncomingKyc);
        }
        if (v.flagIncomingConfirmation) {
          flags.push(BalanceFlag.IncomingConfirmation);
        }
        if (v.flagOutgoingKyc) {
          flags.push(BalanceFlag.OutgoingKyc);
        }
        let shoppingUrls: string[];
        if (this.wex.ws.devExperimentState.fakeShoppingUrl != null) {
          shoppingUrls = [this.wex.ws.devExperimentState.fakeShoppingUrl];
        } else {
          shoppingUrls = [...v.shoppingUrls];
        }
        let disableDirectDeposits: boolean;
        if (this.wex.ws.devExperimentState.flagDisableDirectDeposits) {
          disableDirectDeposits = true;
        } else {
          disableDirectDeposits = v.disableDirectDeposits;
        }
        let disablePeerPayments: boolean;
        if (i === 0 && this.wex.ws.devExperimentState.flagDisablePeerPayments) {
          disablePeerPayments = true; // only disable for first balance
        } else {
          disablePeerPayments = v.disablePeerPayments;
        }
        balancesResponse.balances.push({
          scopeInfo: v.scopeInfo,
          available: Amounts.stringify(v.available),
          pendingIncoming: Amounts.stringify(v.pendingIncoming),
          pendingOutgoing: Amounts.stringify(v.pendingOutgoing),
          flags,
          shoppingUrls,
          disablePeerPayments,
          disableDirectDeposits,
        });
      });
    return balancesResponse;
  }
}

/**
 * Get balance information.
 */
export async function getBalancesInsideTransaction(
  wex: WalletExecutionContext,
  tx: WalletDbTransaction,
): Promise<BalancesResponse> {
  const balanceStore: BalancesStore = new BalancesStore(wex, tx);
  let haveProdBalance = false;

  const donationSummaries = await tx.getDonationSummaries();
  for (const rec of donationSummaries) {
    balanceStore.addDonauItem(rec);
  }

  const exchanges = await tx.getExchanges();
  for (const ex of exchanges) {
    if (
      ex.entryStatus === ExchangeEntryDbRecordStatus.Used ||
      ex.tosAcceptedTimestamp != null
    ) {
      const det = await tx.getExchangeDetails(ex.baseUrl);
      if (det) {
        const exchangeType = getEffectiveExchangeType(
          ex.baseUrl,
          ex.presetType,
        );
        if (exchangeType !== "demo" && exchangeType !== "test") {
          haveProdBalance = true;
        }
        await balanceStore.addZero(det.currency, ex.baseUrl);
        if (ex.peerPaymentsDisabled) {
          await balanceStore.setPeerPaymentsDisabled(det.currency, ex.baseUrl);
        }
        if (ex.directDepositDisabled) {
          await balanceStore.setDirectDepositsDisabled(
            det.currency,
            ex.baseUrl,
          );
        }
        if (det.shoppingUrl) {
          await balanceStore.addShoppingUrl(
            det.currency,
            ex.baseUrl,
            det.shoppingUrl,
          );
        }
      }
    }
  }

  const coinAvailability = await tx.getCoinAvailabilities();
  const denominations = await tx.getDenominationsByRefs(coinAvailability);
  const masterPubByDenom = new Map(
    denominations.map((denom) => [denomRefKey(denom), denom.exchangeMasterPub]),
  );
  for (const ca of coinAvailability) {
    const count = ca.visibleCoinCount ?? 0;
    // The denomination is authoritative for which key set the coins belong
    // to: an exchange update re-attributes the denominations it still
    // offers, while the availability row keeps the key recorded when the
    // coin was made available.
    const denomKey = denomRefKey(ca);
    const masterPub = masterPubByDenom.get(denomKey) ?? ca.exchangeMasterPub;
    await balanceStore.addZero(
      ca.currency,
      ca.exchangeBaseUrl,
      masterPub,
      ca.denomPubHash,
    );
    if (count > 0) {
      await balanceStore.addAvailable(
        ca.currency,
        ca.exchangeBaseUrl,
        Amounts.mult(ca.value, count).amount,
        masterPub,
        ca.denomPubHash,
      );
    }
  }

  const refreshGroups = await tx.getActiveRefreshGroups();
  for (const r of refreshGroups) {
    if (r.reason === RefreshReason.AbortPay) {
      continue;
    }
    switch (r.operationStatus) {
      case RefreshOperationStatus.Pending:
      case RefreshOperationStatus.Suspended:
        break;
      default:
        continue;
    }
    const perExchange = r.infoPerExchange;
    if (!perExchange) {
      continue;
    }
    for (const [e, x] of Object.entries(perExchange)) {
      await balanceStore.addAvailable(r.currency, e, x.outputEffective);
    }
  }

  const withdrawalGroups = await tx.getActiveWithdrawalGroups();
  for (const wg of withdrawalGroups) {
    switch (wg.status) {
      case WithdrawalGroupStatus.AbortedBank:
      case WithdrawalGroupStatus.AbortedExchange:
      case WithdrawalGroupStatus.FailedAbortingBank:
      case WithdrawalGroupStatus.FailedBankAborted:
      case WithdrawalGroupStatus.AbortedOtherWallet:
      case WithdrawalGroupStatus.AbortedUserRefused:
      case WithdrawalGroupStatus.DialogProposed:
      case WithdrawalGroupStatus.Done:
      case WithdrawalGroupStatus.FinalizingKycHardLimit:
      case WithdrawalGroupStatus.FailedKycHardLimit:
      case WithdrawalGroupStatus.FailedKycHardLimitRecovery:
        // Does not count as pendingIncoming
        continue;
      case WithdrawalGroupStatus.PendingReady:
      case WithdrawalGroupStatus.PendingRedenominate:
      case WithdrawalGroupStatus.SuspendedRedenominate:
      case WithdrawalGroupStatus.AbortingBank:
      case WithdrawalGroupStatus.PendingQueryingStatus:
      case WithdrawalGroupStatus.SuspendedWaitConfirmBank:
      case WithdrawalGroupStatus.SuspendedReady:
      case WithdrawalGroupStatus.SuspendedRegisteringBank:
      case WithdrawalGroupStatus.SuspendedAbortingBank:
      case WithdrawalGroupStatus.SuspendedQueryingStatus:
        // Pending, but no special flag.
        break;
      case WithdrawalGroupStatus.PendingBalanceKyc:
      case WithdrawalGroupStatus.SuspendedBalanceKyc:
      case WithdrawalGroupStatus.SuspendedKyc:
      case WithdrawalGroupStatus.PendingBalanceKycInit:
      case WithdrawalGroupStatus.SuspendedBalanceKycInit:
      case WithdrawalGroupStatus.PendingKyc: {
        checkDbInvariant(
          wg.denomsSel !== undefined,
          "wg in kyc state should have been initialized",
        );
        checkDbInvariant(
          wg.exchangeBaseUrl !== undefined,
          "wg in kyc state should have been initialized",
        );
        const currency = Amounts.currencyOf(wg.denomsSel.totalCoinValue);
        await balanceStore.setFlagIncomingKyc(currency, wg.exchangeBaseUrl);
        break;
      }
      case WithdrawalGroupStatus.PendingRegisteringBank: {
        if (wg.denomsSel && wg.exchangeBaseUrl) {
          const currency = Amounts.currencyOf(wg.denomsSel.totalCoinValue);
          await balanceStore.setFlagIncomingConfirmation(
            currency,
            wg.exchangeBaseUrl,
          );
        }
        break;
      }
      case WithdrawalGroupStatus.PendingWaitConfirmBank: {
        checkDbInvariant(
          wg.exchangeBaseUrl !== undefined,
          "withdrawal group in PendingWaitConfirmBank state should have been initialized",
        );

        // FIXME: Consider just having the currency as a fixed field in the DB
        // instead of having it in many locations.
        let currency: string;

        if (wg.denomsSel) {
          currency = Amounts.currencyOf(wg.denomsSel.totalCoinValue);
        } else if (
          wg.wgInfo.withdrawalType === WithdrawalRecordType.BankIntegrated &&
          wg.wgInfo.bankInfo.currency
        ) {
          currency = wg.wgInfo.bankInfo.currency;
        } else {
          logger.warn(
            "could not determine currency for confirmed withdrawal group",
          );
          break;
        }
        await balanceStore.setFlagIncomingConfirmation(
          currency,
          wg.exchangeBaseUrl,
        );
        break;
      }
      default:
        assertUnreachable(wg.status);
    }
    if (wg.denomsSel && wg.exchangeBaseUrl) {
      // only inform pending incoming if amount and exchange has been selected
      const currency = Amounts.currencyOf(wg.denomsSel.totalCoinValue);
      await balanceStore.addPendingIncoming(
        currency,
        wg.exchangeBaseUrl,
        wg.denomsSel.totalCoinValue,
      );
    }
  }

  const peerPushDebits = await tx.getActivePeerPushDebits();
  for (const ppdRecord of peerPushDebits) {
    switch (ppdRecord.status) {
      case PeerPushDebitStatus.AbortingDeletePurse:
      case PeerPushDebitStatus.SuspendedAbortingDeletePurse:
      case PeerPushDebitStatus.ExpiredDeletePurse:
      case PeerPushDebitStatus.SuspendedExpiredDeletePurse:
      case PeerPushDebitStatus.PendingReady:
      case PeerPushDebitStatus.SuspendedReady:
      case PeerPushDebitStatus.PendingCreatePurse:
      case PeerPushDebitStatus.SuspendedCreatePurse: {
        const currency = Amounts.currencyOf(ppdRecord.amount);
        await balanceStore.addPendingOutgoing(
          currency,
          ppdRecord.exchangeBaseUrl,
          ppdRecord.totalCost,
        );
        break;
      }
      case PeerPushDebitStatus.Failed:
      case PeerPushDebitStatus.Aborted:
      case PeerPushDebitStatus.Done:
      case PeerPushDebitStatus.Expired:
        break;
      default:
        assertUnreachable(ppdRecord.status);
    }
  }

  const peerPushCredits = await tx.getActivePeerPushCredits();
  for (const rec of peerPushCredits) {
    switch (rec.status) {
      case PeerPushCreditStatus.PendingMerge:
      case PeerPushCreditStatus.PendingBalanceKycInit:
      case PeerPushCreditStatus.PendingBalanceKycRequired:
      case PeerPushCreditStatus.SuspendedBalanceKycInit:
      case PeerPushCreditStatus.PendingMergeKycRequired:
      case PeerPushCreditStatus.SuspendedMerge:
      case PeerPushCreditStatus.SuspendedBalanceKycRequired:
      case PeerPushCreditStatus.SuspendedMergeKycRequired: {
        const currency = Amounts.currencyOf(rec.estimatedAmountEffective);
        const amount = rec.estimatedAmountEffective;
        await balanceStore.addPendingIncoming(
          currency,
          rec.exchangeBaseUrl,
          amount,
        );
        break;
      }
      case PeerPushCreditStatus.PendingWithdrawing:
      case PeerPushCreditStatus.SuspendedWithdrawing: {
        // Here, incoming balance should be covered by internal withdrawal tx
        break;
      }
    }
  }

  const peerPullCredits = await tx.getActivePeerPullCredits();
  for (const rec of peerPullCredits) {
    switch (rec.status) {
      case PeerPullPaymentCreditStatus.SuspendedBalanceKycInit:
      case PeerPullPaymentCreditStatus.PendingBalanceKycInit:
      case PeerPullPaymentCreditStatus.PendingBalanceKycRequired:
      case PeerPullPaymentCreditStatus.SuspendedBalanceKycRequired:
      case PeerPullPaymentCreditStatus.SuspendedMergeKycRequired:
      case PeerPullPaymentCreditStatus.PendingMergeKycRequired:
      case PeerPullPaymentCreditStatus.PendingReady:
      case PeerPullPaymentCreditStatus.PendingCreatePurse:
      case PeerPullPaymentCreditStatus.SuspendedReady:
      case PeerPullPaymentCreditStatus.SuspendedCreatePurse: {
        const currency = Amounts.currencyOf(rec.amount);
        const amount = rec.estimatedAmountEffective;
        await balanceStore.addPendingIncoming(
          currency,
          rec.exchangeBaseUrl,
          amount,
        );
        break;
      }
    }
  }

  const peerPullDebits = await tx.getActivePeerPullDebits();
  for (const rec of peerPullDebits) {
    switch (rec.status) {
      case PeerPullDebitRecordStatus.PendingDeposit:
      case PeerPullDebitRecordStatus.AbortingRefresh:
      case PeerPullDebitRecordStatus.SuspendedAbortingRefresh:
      case PeerPullDebitRecordStatus.SuspendedDeposit: {
        const currency = Amounts.currencyOf(rec.amount);
        const amount = rec.coinSel?.totalCost ?? rec.amount;
        await balanceStore.addPendingOutgoing(
          currency,
          rec.exchangeBaseUrl,
          amount,
        );
        break;
      }
    }
  }

  const purchases = await tx.getActivePurchases();
  for (const rec of purchases) {
    switch (rec.purchaseStatus) {
      case PurchaseStatus.SuspendedPaying:
      case PurchaseStatus.PendingPaying: {
        if (!rec.payInfo || !rec.payInfo.payCoinSelection?.coinPubs) {
          break;
        }
        const currency = Amounts.currencyOf(rec.payInfo.totalPayCost);
        const sel = rec.payInfo.payCoinSelection;
        const coins = await tx.getCoinsByPubs(sel.coinPubs);
        const coinsByPub = new Map(coins.map((c) => [c.coinPub, c]));
        for (let i = 0; i < sel.coinPubs.length; i++) {
          const coinPub = sel.coinPubs[i];
          const coinRec = coinsByPub.get(coinPub);
          if (!coinRec) {
            continue;
          }
          await balanceStore.addPendingOutgoing(
            currency,
            coinRec.exchangeBaseUrl,
            sel.coinContributions[i],
          );
        }
      }
    }
  }

  const activeDepositGroups = await tx.getActiveDepositGroups();
  for (const dgRecord of activeDepositGroups) {
    const perExchange = dgRecord.infoPerExchange;
    if (!perExchange) {
      continue;
    }
    for (const [e, x] of Object.entries(perExchange)) {
      const currency = Amounts.currencyOf(dgRecord.amount);
      switch (dgRecord.operationStatus) {
        case DepositOperationStatus.SuspendedAggregateKyc:
        case DepositOperationStatus.PendingAggregateKyc:
        case DepositOperationStatus.PendingDepositKyc:
        case DepositOperationStatus.PendingDepositKycAuth:
        case DepositOperationStatus.SuspendedDepositKyc:
        case DepositOperationStatus.SuspendedDepositKycAuth:
          await balanceStore.setFlagOutgoingKyc(currency, e);
      }
      switch (dgRecord.operationStatus) {
        case DepositOperationStatus.SuspendedAggregateKyc:
        case DepositOperationStatus.PendingAggregateKyc:
        case DepositOperationStatus.LegacyPendingTrack:
        case DepositOperationStatus.SuspendedAborting:
        case DepositOperationStatus.SuspendedDeposit:
        case DepositOperationStatus.LegacySuspendedTrack:
        case DepositOperationStatus.PendingDepositKyc:
        case DepositOperationStatus.PendingDepositKycAuth:
        case DepositOperationStatus.SuspendedDepositKyc:
        case DepositOperationStatus.SuspendedDepositKycAuth:
        case DepositOperationStatus.PendingDeposit: {
          await balanceStore.addPendingOutgoing(currency, e, x.amountEffective);
        }
      }
    }
  }

  return balanceStore.toBalancesResponse(haveProdBalance);
}

/**
 * Get detailed balance information, sliced by exchange and by currency.
 */
export async function getBalances(
  wex: WalletExecutionContext,
): Promise<BalancesResponse> {
  logger.trace("starting to compute balance");

  const wbal = await wex.runWalletDbTx(async (tx) => {
    return getBalancesInsideTransaction(wex, tx);
  });

  logger.trace("finished computing wallet balance");

  return wbal;
}

export interface PaymentRestrictionsForBalance {
  currency: string;

  minAge: number;

  /**
   * Restriction by the *sender* on the exchange.
   */
  restrictSenderScope: ScopeInfo | undefined;

  /**
   * Restrictions of the *receiver* on the exchanges.
   */
  restrictReceiverExchanges: ExchangeRestrictionSpec | undefined;

  /**
   * Restriction of the receiver on the supported wire methods.
   */
  restrictWireMethods: string[] | undefined;

  depositPaytoUri: string | undefined;
}

export interface AcceptableExchanges {
  /**
   * Exchanges accepted by the merchant, but wire method might not match.
   */
  acceptableExchanges: string[];

  /**
   * Exchanges accepted by the merchant, including a matching
   * wire method, i.e. the merchant can deposit coins there.
   */
  depositableExchanges: string[];
}

export interface PaymentBalanceDetails {
  /**
   * Balance of type "available" (see balance.ts for definition).
   */
  balanceAvailable: AmountJson;

  /**
   * Balance of type "material" (see balance.ts for definition).
   */
  balanceMaterial: AmountJson;

  /**
   * Balance of type "age-acceptable" (see balance.ts for definition).
   */
  balanceAgeAcceptable: AmountJson;

  /**
   * Balance of type "receiver-acceptable" (see balance.ts for definition).
   *
   * @deprecated (2025-12-05) use balanceReceiver[...]Acceptable instead.
   */
  balanceReceiverAcceptable: AmountJson;

  /**
   * Balance of type "receiver-exchange-url-acceptable" (see balance.ts for definition).
   */
  balanceReceiverExchangeUrlAcceptable: AmountJson;

  /**
   * Balance of type "receiver-exchange-pub-acceptable" (see balance.ts for definition).
   */
  balanceReceiverExchangePubAcceptable: AmountJson;

  /**
   * Balance of type "receiver-auditor-url-acceptable" (see balance.ts for definition).
   */
  balanceReceiverAuditorUrlAcceptable: AmountJson;

  /**
   * Balance of type "receiver-depositable" (see balance.ts for definition).
   */
  balanceReceiverDepositable: AmountJson;

  /**
   * Balance that's depositable with the exchange.
   * This balance is reduced by the exchange's debit restrictions
   * and wire fee configuration.
   */
  balanceExchangeDepositable: AmountJson;

  /**
   * Estimated maximum amount that the wallet could pay for, under the assumption
   * that the merchant pays absolutely no fees.
   */
  maxMerchantEffectiveDepositAmount: AmountJson;
}

/** Reusable database inputs for global and per-exchange payment diagnostics. */
export class PaymentBalanceSnapshot {
  readonly exchangeDetails = new Map<
    string,
    WalletExchangeDetails | undefined
  >();
  readonly scopes = new Map<string, boolean>();

  private constructor(
    readonly availabilities: WalletCoinAvailability[],
    readonly refreshGroups: WalletRefreshGroup[],
    readonly denoms: Map<string, DenominationInfo>,
  ) {}

  static async load(
    wex: WalletExecutionContext,
    tx: WalletDbTransaction,
  ): Promise<PaymentBalanceSnapshot> {
    const [availabilities, refreshGroups] = await Promise.all([
      tx.getCoinAvailabilities(),
      tx.getActiveRefreshGroups(),
    ]);
    const denoms = await getDenomInfos(wex, tx, availabilities);
    return new PaymentBalanceSnapshot(availabilities, refreshGroups, denoms);
  }

  getDenom(availability: WalletCoinAvailability): DenominationInfo | undefined {
    return this.denoms.get(denomRefKey(availability));
  }

  async getExchangeDetails(
    tx: WalletDbTransaction,
    exchangeBaseUrl: string,
  ): Promise<WalletExchangeDetails | undefined> {
    if (!this.exchangeDetails.has(exchangeBaseUrl)) {
      this.exchangeDetails.set(
        exchangeBaseUrl,
        await tx.getExchangeDetails(exchangeBaseUrl),
      );
    }
    return this.exchangeDetails.get(exchangeBaseUrl);
  }

  async checkExchangeInScope(
    tx: WalletDbTransaction,
    exchangeBaseUrl: string,
    scope: ScopeInfo,
    denomPubHash?: string,
  ): Promise<boolean> {
    const key = `${exchangeBaseUrl}\0${j2s(scope)}\0${denomPubHash ?? ""}`;
    if (!this.scopes.has(key)) {
      this.scopes.set(
        key,
        await tx.checkExchangeInScope(exchangeBaseUrl, scope, denomPubHash),
      );
    }
    return this.scopes.get(key)!;
  }
}

export async function getPaymentBalanceDetails(
  wex: WalletExecutionContext,
  req: PaymentRestrictionsForBalance,
): Promise<PaymentBalanceDetails> {
  return await wex.runWalletDbTx(async (tx) => {
    return getPaymentBalanceDetailsInTx(wex, tx, req);
  });
}

export async function getPaymentBalanceDetailsInTx(
  wex: WalletExecutionContext,
  tx: WalletDbTransaction,
  req: PaymentRestrictionsForBalance,
  existingSnapshot?: PaymentBalanceSnapshot,
): Promise<PaymentBalanceDetails> {
  const snapshot =
    existingSnapshot ?? (await PaymentBalanceSnapshot.load(wex, tx));
  const d: PaymentBalanceDetails = {
    balanceAvailable: Amounts.zeroOfCurrency(req.currency),
    balanceMaterial: Amounts.zeroOfCurrency(req.currency),
    balanceAgeAcceptable: Amounts.zeroOfCurrency(req.currency),
    balanceReceiverAcceptable: Amounts.zeroOfCurrency(req.currency),
    balanceReceiverExchangeUrlAcceptable: Amounts.zeroOfCurrency(req.currency),
    balanceReceiverExchangePubAcceptable: Amounts.zeroOfCurrency(req.currency),
    balanceReceiverAuditorUrlAcceptable: Amounts.zeroOfCurrency(req.currency),
    balanceReceiverDepositable: Amounts.zeroOfCurrency(req.currency),
    maxMerchantEffectiveDepositAmount: Amounts.zeroOfCurrency(req.currency),
    balanceExchangeDepositable: Amounts.zeroOfCurrency(req.currency),
  };

  logger.trace(`computing balance details for ${j2s(req)}`);

  const availableCoins = snapshot.availabilities;

  for (const ca of availableCoins) {
    if (ca.currency != req.currency) {
      continue;
    }

    const denom = snapshot.getDenom(ca);
    if (!denom) {
      continue;
    }

    // Skip exchanges if excluded by the receiver.
    if (
      req.restrictSenderScope &&
      !(await snapshot.checkExchangeInScope(
        tx,
        ca.exchangeBaseUrl,
        req.restrictSenderScope,
        ca.denomPubHash,
      ))
    ) {
      continue;
    }

    const wireDetails = await snapshot.getExchangeDetails(
      tx,
      ca.exchangeBaseUrl,
    );
    if (!wireDetails) {
      continue;
    }

    // Signed by a master key the exchange has replaced and did not
    // re-advertise: coin selection will not pick these, so counting them as
    // spendable here would make the balance disagree with what a payment can
    // actually do.  They keep their value and stay in getBalances.
    if (denom.exchangeMasterPub !== wireDetails.masterPublicKey) {
      continue;
    }

    const singleCoinAmount: AmountJson = Amounts.parseOrThrow(ca.value);
    const coinAmount: AmountJson = Amounts.mult(
      singleCoinAmount,
      ca.freshCoinCount,
    ).amount;

    let wireOkay = false;
    if (req.restrictWireMethods == null) {
      wireOkay = true;
    } else {
      for (const wm of req.restrictWireMethods) {
        const wmf = findMatchingWire(wm, req.depositPaytoUri, wireDetails);
        if (wmf.status === "match") {
          wireOkay = true;
          break;
        }
      }
    }

    if (wireOkay) {
      d.balanceExchangeDepositable = Amounts.add(
        d.balanceExchangeDepositable,
        coinAmount,
      ).amount;
    }

    let ageOkay = ca.maxAge >= req.minAge;

    let merchantExchangePubAcceptable = false;
    let merchantExchangeUrlAcceptable = false;
    let merchantExchangeAuditorAcceptable = false;

    if (!req.restrictReceiverExchanges) {
      merchantExchangePubAcceptable = true;
      merchantExchangeUrlAcceptable = true;
      merchantExchangeAuditorAcceptable = true;
    } else {
      for (const ex of req.restrictReceiverExchanges.exchanges) {
        if (ex.exchangePub === ca.exchangeMasterPub) {
          merchantExchangePubAcceptable = true;
          break;
        }
      }

      for (const ex of req.restrictReceiverExchanges.exchanges) {
        if (ex.exchangeBaseUrl === ca.exchangeBaseUrl) {
          merchantExchangeUrlAcceptable = true;
          break;
        }
      }

      for (const acceptedAuditor of req.restrictReceiverExchanges.auditors) {
        if (
          hasVerifiedAuditorTrust(wireDetails.auditors, {
            auditorBaseUrl: acceptedAuditor.auditorBaseUrl,
            auditorPub: acceptedAuditor.auditorPub,
            denomPubHash: ca.denomPubHash,
          })
        ) {
          merchantExchangeAuditorAcceptable = true;
          break;
        }
      }
    }

    const merchantExchangeAcceptable = checkExchangeAccepted(
      wireDetails,
      req.restrictReceiverExchanges,
      ca.denomPubHash,
    ).accepted;
    const merchantExchangeDepositable = merchantExchangeAcceptable && wireOkay;

    d.balanceAvailable = Amounts.add(d.balanceAvailable, coinAmount).amount;
    d.balanceMaterial = Amounts.add(d.balanceMaterial, coinAmount).amount;
    if (ageOkay) {
      d.balanceAgeAcceptable = Amounts.add(
        d.balanceAgeAcceptable,
        coinAmount,
      ).amount;
      // Each receiver-*-acceptable balance is defined by its own criterion, so
      // the public key one must not depend on the URL or the auditor matching
      // as well.  The other two are only reached when their own criterion
      // holds, which already implies merchantExchangeAcceptable.
      if (merchantExchangePubAcceptable) {
        d.balanceReceiverExchangePubAcceptable = Amounts.add(
          d.balanceReceiverExchangePubAcceptable,
          coinAmount,
        ).amount;
      }
      if (merchantExchangeAcceptable) {
        d.balanceReceiverAcceptable = Amounts.add(
          d.balanceReceiverAcceptable,
          coinAmount,
        ).amount;
        if (merchantExchangeDepositable) {
          d.balanceReceiverDepositable = Amounts.add(
            d.balanceReceiverDepositable,
            coinAmount,
          ).amount;
        }
        if (merchantExchangeUrlAcceptable) {
          d.balanceReceiverExchangeUrlAcceptable = Amounts.add(
            d.balanceReceiverExchangeUrlAcceptable,
            coinAmount,
          ).amount;
        }
        if (merchantExchangeAuditorAcceptable) {
          d.balanceReceiverAuditorUrlAcceptable = Amounts.add(
            d.balanceReceiverAuditorUrlAcceptable,
            coinAmount,
          ).amount;
        }
      }
    }

    if (
      ageOkay &&
      wireOkay &&
      merchantExchangeAcceptable &&
      merchantExchangeDepositable
    ) {
      // Coin selection rejects denominations whose deposit fee exceeds their
      // value.  Keep the diagnostic maximum aligned with that rule while the
      // broader balance tallies above continue to show that the coins exist.
      if (Amounts.cmp(denom.feeDeposit, ca.value) > 0) {
        continue;
      }
      d.maxMerchantEffectiveDepositAmount = Amounts.add(
        d.maxMerchantEffectiveDepositAmount,
        Amounts.mult(ca.value, ca.freshCoinCount).amount,
      ).amount;

      d.maxMerchantEffectiveDepositAmount = Amounts.sub(
        d.maxMerchantEffectiveDepositAmount,
        Amounts.mult(denom.feeDeposit, ca.freshCoinCount).amount,
      ).amount;
    }
  }

  const refreshGroups = snapshot.refreshGroups;
  for (const r of refreshGroups) {
    if (r.currency != req.currency) {
      continue;
    }
    const balRefresh = await computeRefreshGroupAvailableAmountForExchanges(
      tx,
      r,
      req.restrictSenderScope,
      snapshot,
    );
    d.balanceAvailable = Amounts.add(d.balanceAvailable, balRefresh).amount;
  }

  return d;
}

export async function getBalanceDetail(
  wex: WalletExecutionContext,
  req: GetBalanceDetailRequest,
): Promise<PaymentBalanceDetails> {
  const exchanges: { exchangeBaseUrl: string; exchangePub: string }[] = [];
  const wires = new Array<string>();
  await wex.runWalletDbTx(async (tx) => {
    const allExchanges = await tx.getExchanges();
    for (const e of allExchanges) {
      const details = await tx.getExchangeDetails(e.baseUrl);
      if (!details || req.currency !== details.currency) {
        continue;
      }
      details.wireInfo.accounts.forEach((a) => {
        const payto = Result.orUndefined(Paytos.fromString(a.payto_uri));
        if (payto && !wires.includes(payto.targetType!)) {
          wires.push(payto.targetType!);
        }
      });
      exchanges.push({
        exchangePub: details.masterPublicKey,
        exchangeBaseUrl: e.baseUrl,
      });
    }
  });

  return await getPaymentBalanceDetails(wex, {
    currency: req.currency,
    restrictSenderScope: undefined,
    restrictReceiverExchanges: {
      auditors: [],
      exchanges,
    },
    restrictWireMethods: wires,
    minAge: 0,
    depositPaytoUri: undefined,
  });
}
